(1327, 321, 1, 'علم الاجتماع — السنة الأولى', 'يدرس كتاب «المجتمع: بنية وحركة» موضوع علم الاجتماع وبنية المجتمع وتراتبه وتطوّره، والجماعات، والتواصل في المجتمع.', 1, '2026-09-30 17:14:32', '2026-09-30 17:14:32', NULL),
(1328, 321, 2, 'Sociology — First Secondary', 'The book \"Society: Structure and Movement\" covers the scope of sociology, social structure and stratification, social change, groups, and communication in society.', 1, '2026-09-30 17:14:32', '2026-09-30 17:14:32', NULL),
(1329, 322, 1, 'اللغة العربيّة — السنة الثانية (إنسانيّات)', 'يغطّي كتاب الأدب لفرع الإنسانيّات بمحاوره الأربعة والأعلام والفنّ القصصيّ والثقافة الأدبيّة العالميّة، إلى جانب القواعد والبلاغة والعروض.', 1, '2026-09-30 17:15:24', '2026-09-30 17:15:24', NULL),
