(1332, 323, 2, 'Arabic Language — Second Secondary (Sciences)', 'Covers the Sciences literature and grammar book: four themes and Cervantes\' Don Quixote, then the grammar lessons.', 1, '2026-09-30 17:15:45', '2026-09-30 17:15:45', NULL),
(1333, 324, 1, 'علم الاقتصاد — السنة الثانية', 'يعرض كتاب «الأنشطة والأوّليات الاقتصاديّة» الدارة الاقتصاديّة والمحاسبة الوطنيّة والنقود والمصارف وإواليّات السوق والمبادلات الخارجيّة والماليّة العامّة والمحاسبة العامّة.', 1, '2026-09-30 17:15:46', '2026-09-30 17:15:46', NULL),
(1334, 324, 2, 'Economics — Second Secondary', 'The book «Economic Activities and Fundamentals» covers the economic circuit, national accounting, money and banking, market mechanisms, external trade, public finance and general accounting.', 1, '2026-09-30 17:15:46', '2026-09-30 17:15:46', NULL),
