(1336, 325, 2, 'Economics — First Secondary', 'The book \"Economic Life\" covers the scope of economics, labour and the workforce, capital, the firm, income, and household income use.', 1, '2026-09-30 17:15:52', '2026-09-30 17:15:52', NULL),
(1337, 326, 1, 'الجغرافيا — السنة الأولى', 'يدرس كتاب «المجال الجغرافيّ» تمثيل المجال والسكّان والريف والمدينة والأرض في الكون والمناخ وأقاليمه والمياه وبنية الأرض والتجوية والحتّ.', 1, '2026-09-30 17:15:54', '2026-09-30 17:15:54', NULL),
(1338, 326, 2, 'Geography — First Secondary', 'The book \"The Geographic Space\" covers mapping, population, rural and urban areas, Earth in the universe, climate and climate regions, water, Earth\'s structure, and weathering and erosion.', 1, '2026-09-30 17:15:54', '2026-09-30 17:15:54', NULL),
(1339, 327, 1, 'الفلسفة — السنة الثانية (إنسانيّات)', 'يعرّف كتاب «الفلسفة والحضارات» بالحضارة وبناها، ويعرض حضارات الشرق القديم واليونان وروما، وإسهامات المسيحيّة والحضارة العربيّة، وينتهي بفلسفة الحضارات عند هيجل وتوينبي.', 1, '2026-09-30 17:15:55', '2026-09-30 17:15:55', NULL),
(1340, 327, 2, 'Philosophy — Second Secondary (Humanities)', '\"Philosophy and Civilisations\" defines civilisation and its structures, surveys the ancient Near East, Greece and Rome, the contributions of Christianity and Arab civilisation, and ends with the philosophy of civilisation in Hegel and Toynbee.', 1, '2026-09-30 17:15:55', '2026-09-30 17:15:55', NULL),
(1341, 328, 1, 'الفلسفة — السنة الثانية (علوم)', 'يعرّف كتاب «فلسفة وحضارات» بالحضارة وأهمّيّة العلم، ويعرض إنجازات الحضارة العربيّة العلميّة وعلم العمران عند ابن خلدون، ثمّ العلوم الحديثة في الغرب ومشكلات العلم.', 1, '2026-09-30 17:15:56', '2026-09-30 17:15:56', NULL),
(1342, 328, 2, 'Philosophy — Second Secondary (Sciences)', '\"Philosophy and Civilisations\" (Sciences) defines civilisation and the role of science, covers Arab scientific achievements and Ibn Khaldun\'s science of civilisation, then modern Western science and the problems of science.', 1, '2026-09-30 17:15:56', '2026-09-30 17:15:56', NULL),
(1343, 329, 1, 'علم الاجتماع — السنة الثانية', 'يشرح كتاب «القيم والمشكلات الاجتماعيّة» التنشئة الاجتماعيّة ووسائطها، والمراهق والشابّ في المجتمع، وأبرز المشكلات الاجتماعيّة كالفقر والبطالة والانحراف.', 1, '2026-09-30 17:15:57', '2026-09-30 17:15:57', NULL),
(1344, 329, 2, 'Sociology — Second Secondary', 'The book «Values and Social Problems» covers socialization and its agents, adolescents and young people in society, and major social problems such as poverty, unemployment and deviance.', 1, '2026-09-30 17:15:57', '2026-09-30 17:15:57', NULL),
(1345, 330, 1, 'التربية الوطنيّة — السنة الثانية', 'يتناول كتاب «التربية الوطنيّة والتنشئة المدنيّة» القيم الإنسانيّة والديمقراطيّة، والعدالة والقضاء، وخلقيّة العمل، والتعاون العربيّ، والعلاقات الدوليّة، والتنظيم المدنيّ.', 1, '2026-09-30 17:16:23', '2026-09-30 17:16:23', NULL),
(1346, 330, 2, 'Civics — Second Secondary', 'The civics book covers human and democratic values, justice and the judiciary, work ethics, Arab cooperation, international relations and the UN, and urban planning.', 1, '2026-09-30 17:16:23', '2026-09-30 17:16:23', NULL),
(1347, 331, 1, 'التربية الوطنيّة — السنة الأولى', 'يدرس كتاب «التربية الوطنيّة والتنشئة المدنيّة» حقوق المواطن وواجباته وحماية حقوق الإنسان وتنظيم الأسرة والنزاعات والمرافق العامّة ومشكلات العالم الأساسيّة.', 1, '2026-09-30 17:16:25', '2026-09-30 17:16:25', NULL),
(1348, 331, 2, 'Civics — First Secondary', 'The book \"National and Civic Education\" covers citizens\' rights and duties, human rights protection, family planning, conflict, public property and services, and major world problems.', 1, '2026-09-30 17:16:25', '2026-09-30 17:16:25', NULL),
(1407, 332, 1, 'اللغة العربيّة — السنة الأولى', 'يغطّي كتاب الأدب للسنة الأولى الثانويّة بنصوصه من الجاهليّة إلى العصر الحديث والأدب العالميّ، إلى جانب القواعد والبلاغة والعروض.', 1, '2026-10-01 13:11:44', '2026-10-01 13:11:44', NULL),
(1408, 332, 2, 'Arabic Language — First Secondary', 'Covers the First Secondary literature book, from pre-Islamic to modern and world literature, plus grammar, rhetoric and prosody.', 1, '2026-10-01 13:11:44', '2026-10-01 13:11:44', NULL),
(1411, 334, 1, 'التاريخ — السنة الأولى', 'الحضارات القديمة (بلاد ما بين النهرين، مصر، فينيقيا، روما) والحضارة العربيّة، من عروض وزارة التربية.', 1, '2026-10-01 18:06:20', '2026-10-01 18:06:20', NULL);
