(23993, 11005, 1, 'بأيّ مؤسّسة تكرّست القوانين التي شرّعها الإسلام في البيع والشراء والإجارة والزواج والإرث؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(23994, 11005, 2, 'بأيّ مؤسّسة تكرّست القوانين التي شرّعها الإسلام في البيع والشراء والإجارة والزواج والإرث؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(23995, 11006, 1, 'حين تفرّعت العلوم الإسلاميّة بحسب موضوعاتها قبل نهاية المئة الثانية للهجرة، أيّ علم اختصّ بالأخلاق؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(23996, 11006, 2, 'حين تفرّعت العلوم الإسلاميّة بحسب موضوعاتها قبل نهاية المئة الثانية للهجرة، أيّ علم اختصّ بالأخلاق؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(23997, 11007, 1, 'بحسب يوحنّا الدمشقي، الإنسان مركّب من جسد منظور ونفس عاقلة هي صورة الله، ونفسه الروحيّة تُدرك بالحواسّ.', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(23998, 11007, 2, 'بحسب يوحنّا الدمشقي، الإنسان مركّب من جسد منظور ونفس عاقلة هي صورة الله، ونفسه الروحيّة تُدرك بالحواسّ.', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(23999, 11008, 1, 'بحسب الترتيب الذي اتّفق عليه معظم العلماء للأدلّة الشرعيّة، ما الدليل الذي يأتي في المرتبة الثالثة؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
