(24001, 11009, 1, 'في أيّ دور صار علم الكلام علماً له موضوع ومنهج، ومن أرسى دعائمه؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(24002, 11009, 2, 'في أيّ دور صار علم الكلام علماً له موضوع ومنهج، ومن أرسى دعائمه؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(24003, 11010, 1, 'يؤدّي الحجّاج مناسكهم بثياب متماثلة. أيّ بعد تؤكّده هذه العبادة بحسب الدرس؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(24004, 11010, 2, 'يؤدّي الحجّاج مناسكهم بثياب متماثلة. أيّ بعد تؤكّده هذه العبادة بحسب الدرس؟', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(24005, 11011, 1, 'يرى يوحنّا الدمشقي أنّ كثرة الآلهة تعني النقص، والنقص يناقض الكمال، ومن لم يكن كاملاً لا يكون إلهاً.', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(24006, 11011, 2, 'يرى يوحنّا الدمشقي أنّ كثرة الآلهة تعني النقص، والنقص يناقض الكمال، ومن لم يكن كاملاً لا يكون إلهاً.', 1, '2026-09-30 22:11:20', '2026-09-30 22:11:20'),
(24007, 11012, 1, 'ما صدر عن شخصٍ بحضور النبيّ فأقرّه، بموافقة صريحة أو باستحسان أو بالسكوت، يُسمّى:', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24008, 11012, 2, 'ما صدر عن شخصٍ بحضور النبيّ فأقرّه، بموافقة صريحة أو باستحسان أو بالسكوت، يُسمّى:', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24009, 11013, 1, 'من الذي ردّ على القائلين بالتخيير بأنّ الإنسان مجبور؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24010, 11013, 2, 'من الذي ردّ على القائلين بالتخيير بأنّ الإنسان مجبور؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24011, 11014, 1, 'ما النور الإلهيّ عند أوغسطينوس؟ وما الطريقان اللذان يكتشف بهما الإنسان وجود الله؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24012, 11014, 2, 'ما النور الإلهيّ عند أوغسطينوس؟ وما الطريقان اللذان يكتشف بهما الإنسان وجود الله؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24013, 11015, 1, 'كان لكلّ قبيلة في الجزيرة العربيّة قبل الإسلام صنم يعبده أهلها، وكانت أهمّ الأصنام العزّى واللات ومناة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24014, 11015, 2, 'كان لكلّ قبيلة في الجزيرة العربيّة قبل الإسلام صنم يعبده أهلها، وكانت أهمّ الأصنام العزّى واللات ومناة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24015, 11016, 1, 'إذا كان الله يعرف مسبقاً ما سيفعله كلّ إنسان، فهل يبقى الإنسان حرّاً ومسؤولاً عند يوحنّا الدمشقي؟ ولماذا يسمح الله بالشرّ؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24016, 11016, 2, 'إذا كان الله يعرف مسبقاً ما سيفعله كلّ إنسان، فهل يبقى الإنسان حرّاً ومسؤولاً عند يوحنّا الدمشقي؟ ولماذا يسمح الله بالشرّ؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24017, 11017, 1, 'اختلف الناس في حقّ المرور لأرض وقف، فأُلحق الوقف بالإجارة لا بالبيع، لأنّ المقصود من الوقف الانتفاع. هذا مثال على:', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24018, 11017, 2, 'اختلف الناس في حقّ المرور لأرض وقف، فأُلحق الوقف بالإجارة لا بالبيع، لأنّ المقصود من الوقف الانتفاع. هذا مثال على:', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24019, 11018, 1, 'حصر الإسلام التعلّم في إطار عقائديّ محدّد.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
