(24023, 11020, 1, 'قارن بين المدينة الأرضيّة والمدينة السماويّة عند أوغسطينوس، وبيّن موقع الدولة منهما.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24024, 11020, 2, 'قارن بين المدينة الأرضيّة والمدينة السماويّة عند أوغسطينوس، وبيّن موقع الدولة منهما.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24025, 11021, 1, 'أوجد الإسلام مفهوم الأمّة إطاراً للجماعة بدل القبيلة، وهي كيان إنسانيّ يجمع التنوّعات العرقيّة والطبقيّة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24026, 11021, 2, 'أوجد الإسلام مفهوم الأمّة إطاراً للجماعة بدل القبيلة، وهي كيان إنسانيّ يجمع التنوّعات العرقيّة والطبقيّة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24027, 11022, 1, 'طالب لم يدرس فرسب، ثمّ قال: «هذا مكتوب عليّ». أيّ فرقة ترى أنّ هذا الطالب خالق لفعله ومسؤول عنه؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24028, 11022, 2, 'طالب لم يدرس فرسب، ثمّ قال: «هذا مكتوب عليّ». أيّ فرقة ترى أنّ هذا الطالب خالق لفعله ومسؤول عنه؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24029, 11023, 1, '«الدائن يظلّ دائناً حتّى تثبت براءة ذمّة المدين». إلى أيّ دليل مختلف عليه يعود هذا الحكم؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24030, 11023, 2, '«الدائن يظلّ دائناً حتّى تثبت براءة ذمّة المدين». إلى أيّ دليل مختلف عليه يعود هذا الحكم؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21');
