(24031, 11024, 1, 'يرى الكتاب أنّ غنى الحوار الذي أنشأه الإسلام مع المذاهب والأفكار الأخرى هو السبب الوحيد لوصوله إلى الصين شرقاً والأندلس غرباً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24032, 11024, 2, 'يرى الكتاب أنّ غنى الحوار الذي أنشأه الإسلام مع المذاهب والأفكار الأخرى هو السبب الوحيد لوصوله إلى الصين شرقاً والأندلس غرباً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24033, 11025, 1, 'يرى ابن خلدون أنّ الأساليب البيانيّة للقرآن، بين آيات تنزّه الله وآيات قليلة توهم التشبيه، أحد أسباب نشأة علم الكلام.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24034, 11025, 2, 'يرى ابن خلدون أنّ الأساليب البيانيّة للقرآن، بين آيات تنزّه الله وآيات قليلة توهم التشبيه، أحد أسباب نشأة علم الكلام.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24035, 11026, 1, 'لماذا أنكر فريقٌ من العلماء، سُمّوا نفاة القياس، الاستدلالَ بالقياس؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24036, 11026, 2, 'لماذا أنكر فريقٌ من العلماء، سُمّوا نفاة القياس، الاستدلالَ بالقياس؟', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24037, 11027, 1, 'صِف حال الجزيرة العربيّة قبل الإسلام (دينيّاً واجتماعيّاً وسياسيّاً)، واذكر مثالين على المنكرات التي كانت منتشرة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24038, 11027, 2, 'صِف حال الجزيرة العربيّة قبل الإسلام (دينيّاً واجتماعيّاً وسياسيّاً)، واذكر مثالين على المنكرات التي كانت منتشرة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24039, 11028, 1, 'الإجماع هو اتّفاق جميع المجتهدين على حكم حادثة وقت وقوعها، وقد انعقد مرّات عدّة في تاريخ المسلمين.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24040, 11028, 2, 'الإجماع هو اتّفاق جميع المجتهدين على حكم حادثة وقت وقوعها، وقد انعقد مرّات عدّة في تاريخ المسلمين.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24041, 11029, 1, 'قسّم المعتزلة الأفعال إلى إراديّة واعية يُسأل عنها الإنسان، واضطراريّة كالمرض والموت يُسأل عنها الإنسان أيضاً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24042, 11029, 2, 'قسّم المعتزلة الأفعال إلى إراديّة واعية يُسأل عنها الإنسان، واضطراريّة كالمرض والموت يُسأل عنها الإنسان أيضاً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24043, 11030, 1, 'كيف ربط الإسلام بين الأخلاق والدين؟ اذكر علامتين من علامات النفاق كما وردتا في الدرس.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24044, 11030, 2, 'كيف ربط الإسلام بين الأخلاق والدين؟ اذكر علامتين من علامات النفاق كما وردتا في الدرس.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24045, 11031, 1, 'في الدور الثالث من أدوار علم الكلام جاء التقليد والجمود، فصارت المعتقدات تُحفظ تلقيناً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24046, 11031, 2, 'في الدور الثالث من أدوار علم الكلام جاء التقليد والجمود، فصارت المعتقدات تُحفظ تلقيناً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24047, 11032, 1, 'في القرآن ثلاثة أنواع من الأحكام: اعتقاديّة وخلقيّة وعمليّة، والأحكام العمليّة هي موضوع علم أصول الفقه.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24048, 11032, 2, 'في القرآن ثلاثة أنواع من الأحكام: اعتقاديّة وخلقيّة وعمليّة، والأحكام العمليّة هي موضوع علم أصول الفقه.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24049, 11033, 1, 'قارن بين إطار الجماعة وبنية المجتمع قبل الإسلام وبعده، ثمّ بيّن دور التسامح في انتشار الإسلام.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24050, 11033, 2, 'قارن بين إطار الجماعة وبنية المجتمع قبل الإسلام وبعده، ثمّ بيّن دور التسامح في انتشار الإسلام.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24051, 11034, 1, 'العدل عند الأشعري أهمّ صفة للفعل الإلهيّ، والحسن والقبح عنده عقليّان.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24052, 11034, 2, 'العدل عند الأشعري أهمّ صفة للفعل الإلهيّ، والحسن والقبح عنده عقليّان.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24053, 11035, 1, 'القول: «وضع الشرائع إنّما هو لمصلحة العباد في العاجل والآجل معاً» ورد في كتاب «الموافقات» للإمام الغزالي.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(24054, 11035, 2, 'القول: «وضع الشرائع إنّما هو لمصلحة العباد في العاجل والآجل معاً» ورد في كتاب «الموافقات» للإمام الغزالي.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
