(29210, 13613, 2, 'احتكار القلّة يؤدّي غالباً إلى قيام الكارتيلات وانخفاض الأسعار.', 1, '2026-09-30 22:54:06', '2026-09-30 22:54:06'),
(29211, 13615, 1, 'أين يودَع رسم المحروقات ورسم المرفأ اللذان تستوفيهما الدولة لحساب جميع البلديّات، ومَن يوزّعهما على البلديّات؟', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29212, 13614, 1, 'بالتفسير الأوسع، يتراوح مفهوم الاتحاد الجمركي بين تخفيض جزئي للرسوم وتحرير تامّ للتجارة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29213, 13615, 2, 'أين يودَع رسم المحروقات ورسم المرفأ اللذان تستوفيهما الدولة لحساب جميع البلديّات، ومَن يوزّعهما على البلديّات؟', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29214, 13614, 2, 'بالتفسير الأوسع، يتراوح مفهوم الاتحاد الجمركي بين تخفيض جزئي للرسوم وتحرير تامّ للتجارة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29215, 13616, 1, 'في القرن التاسع عشر برزت الرأسماليّة، وافترض علماء الاقتصاد آنذاك أنّ السوق التي يجري فيها العرض والطلب هي سوق منافسة حرّة تامّة وكاملة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29216, 13616, 2, 'في القرن التاسع عشر برزت الرأسماليّة، وافترض علماء الاقتصاد آنذاك أنّ السوق التي يجري فيها العرض والطلب هي سوق منافسة حرّة تامّة وكاملة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29217, 13617, 1, 'إذا كان ميزان العمليّات الرأسماليّة في عجز، أي كان رصيده سلبيّاً، دلّ ذلك على أنّ الاقتصاد يسعى إلى إيجاد موارد ماليّة من الخارج.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29218, 13617, 2, 'إذا كان ميزان العمليّات الرأسماليّة في عجز، أي كان رصيده سلبيّاً، دلّ ذلك على أنّ الاقتصاد يسعى إلى إيجاد موارد ماليّة من الخارج.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29219, 13618, 1, 'في أيّ مرحلة من مراحل تنفيذ النفقة البلديّة يُثبَت ترتّب الدين على البلديّة ويُحدَّد مقداره؟', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29220, 13618, 2, 'في أيّ مرحلة من مراحل تنفيذ النفقة البلديّة يُثبَت ترتّب الدين على البلديّة ويُحدَّد مقداره؟', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29221, 13619, 1, 'اقرأ المستند الآتي، ثمّ أجب عن الأسئلة.\n«يعتبر كولن كلارك أنّ نسبة الدخل المخصّصة لاستهلاك السلع والخدمات الكماليّة تتزايد عندما يصل الدخل إلى مستوى معيّن.\nأمّا ملتون فريدمان فيعتبر أنّ ما كان عليه دخل المستهلك ماضياً، وما يجنيه من دخل حاضراً، وما يتوقّعه من دخل مستقبلاً، هي المعطيات التي تحدّد مستوى طلبه الاستهلاكيّ.»\nأ- ما نوع العلاقة بين مستوى الدخل وحجم الطلب؟ علّل جوابك.\nب- بيّن ما يضيفه رأي فريدمان إلى رأي كولن كلارك.\nج- ارتفع دخل أسرة. كيف تتغيّر نسبة الدخل التي تخصّصها لشراء المواد الغذائيّة، ونسبة ما تخصّصه للكساء وأثاث المنزل؟ حدّد مرونة الطلب بالنسبة إلى الدخل في كلّ من الحالتين.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(29222, 13619, 2, 'اقرأ المستند الآتي، ثمّ أجب عن الأسئلة.\n«يعتبر كولن كلارك أنّ نسبة الدخل المخصّصة لاستهلاك السلع والخدمات الكماليّة تتزايد عندما يصل الدخل إلى مستوى معيّن.\nأمّا ملتون فريدمان فيعتبر أنّ ما كان عليه دخل المستهلك ماضياً، وما يجنيه من دخل حاضراً، وما يتوقّعه من دخل مستقبلاً، هي المعطيات التي تحدّد مستوى طلبه الاستهلاكيّ.»\nأ- ما نوع العلاقة بين مستوى الدخل وحجم الطلب؟ علّل جوابك.\nب- بيّن ما يضيفه رأي فريدمان إلى رأي كولن كلارك.\nج- ارتفع دخل أسرة. كيف تتغيّر نسبة الدخل التي تخصّصها لشراء المواد الغذائيّة، ونسبة ما تخصّصه للكساء وأثاث المنزل؟ حدّد مرونة الطلب بالنسبة إلى الدخل في كلّ من الحالتين.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29223, 13620, 1, 'اقرأ المستند الآتي ثمّ أجب:\n«رصيد ميزان الحساب الجاري يعطي فكرة واضحة عن قدرات الاقتصاد أو عن حاجاته إلى التمويل. […] أمّا إذا حقّق [ميزان العمليّات الرأسماليّة] فائضاً، أي كان رصيده إيجابيّاً، فهذا دليل على أنّ الاقتصاد يسعى إلى إيجاد موارد ماليّة من الخارج لحاجته إليها في الداخل، وذلك بهدف سدّ عجز ميزان الحساب الجاري. وهذا ما يحصل في لبنان.»\nأ- عدّد الموازين الثلاثة التي يضمّها ميزان الحساب الجاري.\nب- علّل وجود عجز في ميزان الحساب الجاري في لبنان انطلاقاً من حال الميزان التجاريّ فيه.\nج- بيّن، استناداً إلى المستند، كيف يسدّ الاقتصاد اللبنانيّ هذا العجز.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29224, 13620, 2, 'اقرأ المستند الآتي ثمّ أجب:\n«رصيد ميزان الحساب الجاري يعطي فكرة واضحة عن قدرات الاقتصاد أو عن حاجاته إلى التمويل. […] أمّا إذا حقّق [ميزان العمليّات الرأسماليّة] فائضاً، أي كان رصيده إيجابيّاً، فهذا دليل على أنّ الاقتصاد يسعى إلى إيجاد موارد ماليّة من الخارج لحاجته إليها في الداخل، وذلك بهدف سدّ عجز ميزان الحساب الجاري. وهذا ما يحصل في لبنان.»\nأ- عدّد الموازين الثلاثة التي يضمّها ميزان الحساب الجاري.\nب- علّل وجود عجز في ميزان الحساب الجاري في لبنان انطلاقاً من حال الميزان التجاريّ فيه.\nج- بيّن، استناداً إلى المستند، كيف يسدّ الاقتصاد اللبنانيّ هذا العجز.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29225, 13621, 1, 'في نفقات الموازنة العامّة يُقسَم الباب إلى فصول، ويُقسَم الفصل إلى بنود.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29226, 13621, 2, 'في نفقات الموازنة العامّة يُقسَم الباب إلى فصول، ويُقسَم الفصل إلى بنود.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29227, 13622, 1, 'عدّد أسباب نشوء الاحتكار الثلاثة، واشرح كلّ سبب منها باختصار، مع ذكر مثال الدرس حيث وُجد.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29228, 13622, 2, 'عدّد أسباب نشوء الاحتكار الثلاثة، واشرح كلّ سبب منها باختصار، مع ذكر مثال الدرس حيث وُجد.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29229, 13623, 1, '«ترتكز التجارة الخارجيّة على التخصّص.»\nأ- اشرح لماذا يجب على كلّ دولة أن تتخصّص، وبيّن ما المقصود بالميزات الفضلى.\nب- بيّن العلاقة بين مدى التخصّص واتّساع السوق.\nج- اشرح كيف تؤثّر حرّية التبادل في السوق وفي تخصّص الدول.\nد- رأى التقليديّون أنّ التبادل الدولي مفيد لجميع الدول فلا يجب أن توضع أمامه أيّة قيود أو عوائق. أيّ سياسة من سياستَي التجارة الخارجيّة تتوافق مع هذا الموقف؟ علّل.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29230, 13623, 2, '«ترتكز التجارة الخارجيّة على التخصّص.»\nأ- اشرح لماذا يجب على كلّ دولة أن تتخصّص، وبيّن ما المقصود بالميزات الفضلى.\nب- بيّن العلاقة بين مدى التخصّص واتّساع السوق.\nج- اشرح كيف تؤثّر حرّية التبادل في السوق وفي تخصّص الدول.\nد- رأى التقليديّون أنّ التبادل الدولي مفيد لجميع الدول فلا يجب أن توضع أمامه أيّة قيود أو عوائق. أيّ سياسة من سياستَي التجارة الخارجيّة تتوافق مع هذا الموقف؟ علّل.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29231, 13624, 1, 'تُدرَج القروض التي تعقدها الدولة في الجزء الأوّل من الواردات، أي الواردات العاديّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29232, 13624, 2, 'تُدرَج القروض التي تعقدها الدولة في الجزء الأوّل من الواردات، أي الواردات العاديّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29233, 13625, 1, '«يتكوّن السعر بفعل التقاء العرض بالطلب، وهذا ما يسمّى آليّة السوق.»\nانطلاقاً من هذه العبارة ومن درسَي «تعريف إواليّات السوق» و«شروط المنافسة الحرّة»:\nأ- اشرح كيف يتحدّد السعر عند نقطة الالتقاء، ومتى تكون السوق في حالة توازن.\nب- بيّن كيف يمنع شرط ذرّيّة السوق أيّ عارض أو طالب من فرض السعر.\nج- قارن ذلك بالاحتكار: من يحدّد السعر فيه، وكيف يكون السعر المفروض في أغلب الأحيان مقارنةً بسعر السوق الحرّة؟ ولماذا تكون سوق المحتكر مضمونة؟', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29234, 13625, 2, '«يتكوّن السعر بفعل التقاء العرض بالطلب، وهذا ما يسمّى آليّة السوق.»\nانطلاقاً من هذه العبارة ومن درسَي «تعريف إواليّات السوق» و«شروط المنافسة الحرّة»:\nأ- اشرح كيف يتحدّد السعر عند نقطة الالتقاء، ومتى تكون السوق في حالة توازن.\nب- بيّن كيف يمنع شرط ذرّيّة السوق أيّ عارض أو طالب من فرض السعر.\nج- قارن ذلك بالاحتكار: من يحدّد السعر فيه، وكيف يكون السعر المفروض في أغلب الأحيان مقارنةً بسعر السوق الحرّة؟ ولماذا تكون سوق المحتكر مضمونة؟', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29235, 13626, 1, 'استثنت دولة منطقة معيّنة من نطاقها الجمركي، وصارت تعاملها كأنّها خارج حدودها. استورد أحد المصانع في هذه المنطقة مواد أوليّة من الخارج، فصنّعها، ثمّ أعاد تصدير قسم من إنتاجه إلى الخارج، وأدخل القسم الآخر إلى أسواق الدولة.\nأ- ما اسم هذا التنظيم؟ واذكر هدفاً من أهداف إنشائه.\nب- بيّن هل تُدفع رسوم على المواد الأوليّة المستوردة وعلى القسم المُعاد تصديره، وهل تُدفع على القسم الذي دخل أسواق الدولة. علّل.\nج- اذكر مثالاً على هذا التنظيم في لبنان كما ورد في الدرس.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29236, 13626, 2, 'استثنت دولة منطقة معيّنة من نطاقها الجمركي، وصارت تعاملها كأنّها خارج حدودها. استورد أحد المصانع في هذه المنطقة مواد أوليّة من الخارج، فصنّعها، ثمّ أعاد تصدير قسم من إنتاجه إلى الخارج، وأدخل القسم الآخر إلى أسواق الدولة.\nأ- ما اسم هذا التنظيم؟ واذكر هدفاً من أهداف إنشائه.\nب- بيّن هل تُدفع رسوم على المواد الأوليّة المستوردة وعلى القسم المُعاد تصديره، وهل تُدفع على القسم الذي دخل أسواق الدولة. علّل.\nج- اذكر مثالاً على هذا التنظيم في لبنان كما ورد في الدرس.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29237, 13627, 1, 'تُطرح الرسوم البلديّة السنويّة، كالرسم على القيمة التأجيريّة للأبنية، بموجب أوامر قبض إفراديّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29238, 13627, 2, 'تُطرح الرسوم البلديّة السنويّة، كالرسم على القيمة التأجيريّة للأبنية، بموجب أوامر قبض إفراديّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29239, 13628, 1, 'يغذّي الاحتياطي في الموازنة البلديّة الأبواب عند نقص في التقدير، أو يفتح اعتماداً لنفقة طارئة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29240, 13628, 2, 'يغذّي الاحتياطي في الموازنة البلديّة الأبواب عند نقص في التقدير، أو يفتح اعتماداً لنفقة طارئة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29241, 13629, 1, 'اقرأ النصّ الآتي ثمّ أجب:\n«الدولة الحديثة لم تعد محايدة تجاه حياة مواطنيها. إنّها دولة تدخّليّة، تراقب النشاط الاقتصادي وتوجّهه، وتعمل على رفع المستوى المعيشي والاجتماعي. لذلك لم تعد الموازنة مستنداً حسابيّاً فقط، بل أصبحت أداة فعّالة لتنفيذ سياستها.»\nأ- اشرح ما المقصود بأنّ الدولة الحديثة «دولة تدخّليّة».\nب- علّل: تُعَدّ الموازنة العامّة عملاً سياسيّاً وليست مجرّد جداول محاسبيّة وأرقام.\nج- اذكر ثلاثة من القطاعات التي تموّلها النفقات لأنّ الدولة تعدّها ذات أولويّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(29242, 13629, 2, 'اقرأ النصّ الآتي ثمّ أجب:\n«الدولة الحديثة لم تعد محايدة تجاه حياة مواطنيها. إنّها دولة تدخّليّة، تراقب النشاط الاقتصادي وتوجّهه، وتعمل على رفع المستوى المعيشي والاجتماعي. لذلك لم تعد الموازنة مستنداً حسابيّاً فقط، بل أصبحت أداة فعّالة لتنفيذ سياستها.»\nأ- اشرح ما المقصود بأنّ الدولة الحديثة «دولة تدخّليّة».\nب- علّل: تُعَدّ الموازنة العامّة عملاً سياسيّاً وليست مجرّد جداول محاسبيّة وأرقام.\nج- اذكر ثلاثة من القطاعات التي تموّلها النفقات لأنّ الدولة تعدّها ذات أولويّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
