(30101, 14059, 1, 'تبلورت صيغة التعاونيّة منذ أواسط القرن التاسع عشر في المجتمعات الصناعيّة الأوروبيّة، لتخفيف كلفة الحاجات الاستهلاكيّة في الأوساط العمّاليّة والشعبيّة الفقيرة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30102, 14059, 2, 'تبلورت صيغة التعاونيّة منذ أواسط القرن التاسع عشر في المجتمعات الصناعيّة الأوروبيّة، لتخفيف كلفة الحاجات الاستهلاكيّة في الأوساط العمّاليّة والشعبيّة الفقيرة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30103, 14060, 1, 'ساعد تجمّع عدد كبير من العمّال في مصنع واحد على توحيد مواقفهم، فانتظموا في نقابات تدافع عن مصالحهم بدل التفاوض الفردي مع أرباب العمل.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30104, 14060, 2, 'ساعد تجمّع عدد كبير من العمّال في مصنع واحد على توحيد مواقفهم، فانتظموا في نقابات تدافع عن مصالحهم بدل التفاوض الفردي مع أرباب العمل.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30105, 14061, 1, 'يطرح الكتاب سؤالَين: «من يصنع كلّ هذه المعلومات؟ ومن يروّج لها؟». إلى أيّ مفهوم يقودنا هذان السؤالان؟', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30106, 14061, 2, 'يطرح الكتاب سؤالَين: «من يصنع كلّ هذه المعلومات؟ ومن يروّج لها؟». إلى أيّ مفهوم يقودنا هذان السؤالان؟', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30107, 14062, 1, 'تشكّل الأحزاب حلقات وسيطة بين السلطة الحاكمة والناس، والسلطة السياسيّة هي منظومة الأجهزة والأفراد التي يُعترف لها بشرعيّة القرار.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30108, 14062, 2, 'تشكّل الأحزاب حلقات وسيطة بين السلطة الحاكمة والناس، والسلطة السياسيّة هي منظومة الأجهزة والأفراد التي يُعترف لها بشرعيّة القرار.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30109, 14063, 1, 'على المستوى الاجتماعيّ في المجتمعات ما بعد الصناعيّة، ترتفع معدّلات المواليد إلى مستويات قياسيّة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30110, 14063, 2, 'على المستوى الاجتماعيّ في المجتمعات ما بعد الصناعيّة، ترتفع معدّلات المواليد إلى مستويات قياسيّة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30111, 14064, 1, 'في التواصل المباشر تصل الرسالة بواسطة طرف آخر أو عبر آلة، كالمكتوب والفاكس.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30112, 14064, 2, 'في التواصل المباشر تصل الرسالة بواسطة طرف آخر أو عبر آلة، كالمكتوب والفاكس.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30113, 14065, 1, 'حسب معيار النطاق الجغرافيّ، تُصنَّف المنظّمة غير الحكوميّة تمويليّة أو فنّيّة، تدريبيّة أو توثيقيّة، تنفيذيّة أو ميدانيّة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30114, 14065, 2, 'حسب معيار النطاق الجغرافيّ، تُصنَّف المنظّمة غير الحكوميّة تمويليّة أو فنّيّة، تدريبيّة أو توثيقيّة، تنفيذيّة أو ميدانيّة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30115, 14066, 1, 'ما زال مفهوم حقّ الاتصال موضوع خلاف حتى اليوم، ولم يدخل بعد نظم كثير من الدول.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30116, 14067, 1, 'اقرأ النصّ الآتي ثمّ أجب عن الأسئلة:\n«قضت الثورة الصناعية على الجزء الأكبر من الصناعات الحرفية الصغيرة، وانفصلت الصناعة عن الزراعة انفصالاً تامّاً. وتحوّلت وحدة الإنتاج من الورشة الصغيرة إلى المصنع الكبير، فاضطرّ معظم الحرفيين إلى إغلاق محترفاتهم والعمل في المصانع.»\nأ- استخرج من النصّ مظهرين من مظاهر التطوّر على مستوى الإنتاج.\nب- قارن بين علاقة الحرف بالزراعة في المجتمعات التقليديّة وما يصفه النصّ.\nج- بيّن كيف أسهم ما يصفه النصّ في انتقال أغلب السكان إلى المدن.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30117, 14066, 2, 'ما زال مفهوم حقّ الاتصال موضوع خلاف حتى اليوم، ولم يدخل بعد نظم كثير من الدول.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30118, 14067, 2, 'اقرأ النصّ الآتي ثمّ أجب عن الأسئلة:\n«قضت الثورة الصناعية على الجزء الأكبر من الصناعات الحرفية الصغيرة، وانفصلت الصناعة عن الزراعة انفصالاً تامّاً. وتحوّلت وحدة الإنتاج من الورشة الصغيرة إلى المصنع الكبير، فاضطرّ معظم الحرفيين إلى إغلاق محترفاتهم والعمل في المصانع.»\nأ- استخرج من النصّ مظهرين من مظاهر التطوّر على مستوى الإنتاج.\nب- قارن بين علاقة الحرف بالزراعة في المجتمعات التقليديّة وما يصفه النصّ.\nج- بيّن كيف أسهم ما يصفه النصّ في انتقال أغلب السكان إلى المدن.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30119, 14068, 1, 'بيّن كيف تسهم الجمعيّات في بناء المجتمع المدني الديمقراطي، مستعيناً بما تعلّمته في درس «الجماعات: أنواعها وأدوارها وأهدافها» ودرس «الجماعة الاجتماعيّة في المنظّمات التطوّعيّة»: عرّف المجتمع المدني، ثمّ اشرح دور الجمعيّة وسيطاً، واذكر وظيفتين مدنيّتين لها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30120, 14068, 2, 'بيّن كيف تسهم الجمعيّات في بناء المجتمع المدني الديمقراطي، مستعيناً بما تعلّمته في درس «الجماعات: أنواعها وأدوارها وأهدافها» ودرس «الجماعة الاجتماعيّة في المنظّمات التطوّعيّة»: عرّف المجتمع المدني، ثمّ اشرح دور الجمعيّة وسيطاً، واذكر وظيفتين مدنيّتين لها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30121, 14069, 1, 'بعد انتهاء الحرب الباردة، مال الاتجاه العالمي إلى توسيع الاستخدام الدعائي للإذاعة، والسماح للقطاع التجاري الخاص بممارسة البثّ الإذاعي.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30122, 14070, 1, 'ثورة العلوم والتكنولوجيا هي التحوّل الثالث من التحوّلات الكبرى في تاريخ البشرية.\nأ- حدّد زمنها، واذكر مجالين من مجالات التطوّر العلمي الذي أحدث فيها تغييرات حادّة وجذرية في حياة الناس.\nب- بيّن أثرها في العلاقة بين البلدان الصناعية وغير الصناعية.\nج- اشرح الدور الذي صار للمعرفة ولمراكز تحصيلها في المجتمعات ما بعد الصناعيّة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30123, 14069, 2, 'بعد انتهاء الحرب الباردة، مال الاتجاه العالمي إلى توسيع الاستخدام الدعائي للإذاعة، والسماح للقطاع التجاري الخاص بممارسة البثّ الإذاعي.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(30124, 14070, 2, 'ثورة العلوم والتكنولوجيا هي التحوّل الثالث من التحوّلات الكبرى في تاريخ البشرية.\nأ- حدّد زمنها، واذكر مجالين من مجالات التطوّر العلمي الذي أحدث فيها تغييرات حادّة وجذرية في حياة الناس.\nب- بيّن أثرها في العلاقة بين البلدان الصناعية وغير الصناعية.\nج- اشرح الدور الذي صار للمعرفة ولمراكز تحصيلها في المجتمعات ما بعد الصناعيّة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30125, 14071, 1, 'سهّل الكومبيوتر تصنيف المراجع والكتب، وطوّر علم المكتبات وتبادل المعلومات في ما بينها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30126, 14071, 2, 'سهّل الكومبيوتر تصنيف المراجع والكتب، وطوّر علم المكتبات وتبادل المعلومات في ما بينها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30127, 14072, 1, 'قارن بين المجتمعات التقليديّة القديمة والمجتمعات التقليديّة المعاصرة من حيث: أ- النشاط الاقتصادي. ب- علاقات القربى والعائلة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30128, 14072, 2, 'قارن بين المجتمعات التقليديّة القديمة والمجتمعات التقليديّة المعاصرة من حيث: أ- النشاط الاقتصادي. ب- علاقات القربى والعائلة.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30129, 14073, 1, 'اقرأ المقطع الآتي ثمّ أجب:\n«ينتمي أفرادها إلى جدّ مشترك، ويحملون اسمه. وتُعتبر في بعض جوانبها استمراراً للأطر القرابية القديمة، كالقبيلة والعشيرة والجبّ. يعيشون في بيت واحد، ويعملون في مهن تتكامل فيما بينها، وينفقون من دخل مشترك يوضع بتصرّف ربّ العائلة.»\nأ- سمِّ التكوين القرابي الذي يصفه المقطع.\nب- قارنه بالأسرة الزوجية النواتية من حيث التكوين.\nج- ماذا حلّ بهذا التكوين في المدن؟ وما الدور الذي بقي له؟', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30130, 14073, 2, 'اقرأ المقطع الآتي ثمّ أجب:\n«ينتمي أفرادها إلى جدّ مشترك، ويحملون اسمه. وتُعتبر في بعض جوانبها استمراراً للأطر القرابية القديمة، كالقبيلة والعشيرة والجبّ. يعيشون في بيت واحد، ويعملون في مهن تتكامل فيما بينها، وينفقون من دخل مشترك يوضع بتصرّف ربّ العائلة.»\nأ- سمِّ التكوين القرابي الذي يصفه المقطع.\nب- قارنه بالأسرة الزوجية النواتية من حيث التكوين.\nج- ماذا حلّ بهذا التكوين في المدن؟ وما الدور الذي بقي له؟', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30131, 14074, 1, 'يريد عدد من المنتجين في إحدى القرى إنشاء تنظيم دائم يؤمّن لهم حاجاتهم بأسعار أقلّ، ويبيع إنتاجهم بأعلى سعر ممكن.\nأ- ما الشكل المناسب لهذا التنظيم من أشكال الجماعة المهنيّة؟\nب- اشرح خطوات تأسيسه في لبنان.\nج- ميّز بينه وبين التجمّع المهنيّ.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30132, 14075, 1, 'اقرأ المستند الآتي عن قانون المطبوعات في لبنان، ثمّ أجب:\n«يقرّ القانون في مادّته الأولى أنّ المطبعة والصحافة والمكتبة ودار النشر والتوزيع حرّة. ويميّز بين المطبوعة السياسية وغير السياسية. فالأولى تخضع للرقابة وهي مسؤولة تجاه السلطات الرسمية. أمّا الثانية فمسؤولة فقط تجاه الرأي العام والأطراف المدنية.»\n١- ما المبدأ الذي يقرّه القانون في مادّته الأولى؟\n٢- قارن بين المطبوعة السياسية والمطبوعة غير السياسية من حيث الرقابة والمسؤولية.\n٣- بيّن الجهة التي يضع القانون الرقابة بيدها، واذكر أقسام العقوبات التي يحدّدها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30133, 14074, 2, 'يريد عدد من المنتجين في إحدى القرى إنشاء تنظيم دائم يؤمّن لهم حاجاتهم بأسعار أقلّ، ويبيع إنتاجهم بأعلى سعر ممكن.\nأ- ما الشكل المناسب لهذا التنظيم من أشكال الجماعة المهنيّة؟\nب- اشرح خطوات تأسيسه في لبنان.\nج- ميّز بينه وبين التجمّع المهنيّ.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30134, 14076, 1, 'في بلدة لبنانية ما زال الأهالي يتعاونون في المواسم الزراعية، وفي الوقت نفسه صار بعض أبنائها ينجزون أعمالهم عبر الكومبيوتر دون الحضور إلى مكاتب مؤسّساتهم.\nأ- إلامَ يدلّ تعاون الأهالي في المواسم؟ علّل بالعودة إلى سمات الزراعة في المجتمعات التقليديّة.\nب- اشرح التحوّل الذي يدلّ عليه عمل أبناء البلدة عبر الكومبيوتر.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30135, 14076, 2, 'في بلدة لبنانية ما زال الأهالي يتعاونون في المواسم الزراعية، وفي الوقت نفسه صار بعض أبنائها ينجزون أعمالهم عبر الكومبيوتر دون الحضور إلى مكاتب مؤسّساتهم.\nأ- إلامَ يدلّ تعاون الأهالي في المواسم؟ علّل بالعودة إلى سمات الزراعة في المجتمعات التقليديّة.\nب- اشرح التحوّل الذي يدلّ عليه عمل أبناء البلدة عبر الكومبيوتر.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30136, 14075, 2, 'اقرأ المستند الآتي عن قانون المطبوعات في لبنان، ثمّ أجب:\n«يقرّ القانون في مادّته الأولى أنّ المطبعة والصحافة والمكتبة ودار النشر والتوزيع حرّة. ويميّز بين المطبوعة السياسية وغير السياسية. فالأولى تخضع للرقابة وهي مسؤولة تجاه السلطات الرسمية. أمّا الثانية فمسؤولة فقط تجاه الرأي العام والأطراف المدنية.»\n١- ما المبدأ الذي يقرّه القانون في مادّته الأولى؟\n٢- قارن بين المطبوعة السياسية والمطبوعة غير السياسية من حيث الرقابة والمسؤولية.\n٣- بيّن الجهة التي يضع القانون الرقابة بيدها، واذكر أقسام العقوبات التي يحدّدها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30137, 14077, 1, 'تبثّ إذاعة رسمية خطاباً يلقيه رئيس الدولة ويخاطب فيه المواطنين. مستعيناً بدرسَي «التواصل وأشكال التعبير» و«التواصل ووسائل الإعلام»:\n١- حدّد عناصر الدائرة الاتصالية في هذه الحالة.\n٢- بيّن هل هذا التواصل شخصيّ أم جماهيريّ، وهل المتلقي محدّد أم عامّ، معلّلاً إجابتك.\n٣- صنّف هذه الإذاعة بحسب التصنيف الحديث للإذاعات، وبيّن من يملكها ويموّلها، وما الرسائل التي تحملها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30138, 14077, 2, 'تبثّ إذاعة رسمية خطاباً يلقيه رئيس الدولة ويخاطب فيه المواطنين. مستعيناً بدرسَي «التواصل وأشكال التعبير» و«التواصل ووسائل الإعلام»:\n١- حدّد عناصر الدائرة الاتصالية في هذه الحالة.\n٢- بيّن هل هذا التواصل شخصيّ أم جماهيريّ، وهل المتلقي محدّد أم عامّ، معلّلاً إجابتك.\n٣- صنّف هذه الإذاعة بحسب التصنيف الحديث للإذاعات، وبيّن من يملكها ويموّلها، وما الرسائل التي تحملها.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30139, 14078, 1, 'لماذا لا يكون المضمون الخاصّ موضوعاً للدراسة العلمية؟ ثمّ عدّد العناوين الرئيسية التي يرتبط بها المضمون العامّ.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30140, 14078, 2, 'لماذا لا يكون المضمون الخاصّ موضوعاً للدراسة العلمية؟ ثمّ عدّد العناوين الرئيسية التي يرتبط بها المضمون العامّ.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30141, 14079, 1, 'علّل: يرى الكتاب أنّ الانكفاء غير ممكن في عصر تكنولوجيا الانفتاح. ثمّ بيّن ما الذي يحدث إذا أحسنّا التعامل مع هذا الانفتاح.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30142, 14079, 2, 'علّل: يرى الكتاب أنّ الانكفاء غير ممكن في عصر تكنولوجيا الانفتاح. ثمّ بيّن ما الذي يحدث إذا أحسنّا التعامل مع هذا الانفتاح.', 1, '2026-09-30 22:54:23', '2026-09-30 22:54:23'),
(30143, 14081, 1, 'يستطيع شخص أن يحصل على ثروة إنسان يعيش في الطرف الآخر من العالم بضغطة زرّ تقضي على حياته، من دون أن يعرف أحد، ومن دون أن يسبّب له أيّ ألم. لماذا يترفّع الإنسان الذي استكمل مقوّمات إنسانيّته عن هذا العمل بحسب الدرس؟', 1, '2026-09-30 22:54:24', '2026-09-30 22:54:24'),
