(30349, 14183, 1, 'بعد أن احتلّت إسرائيل الجنوب اللبنانيّ والبقاع الغربيّ في آذار عام ١٩٧٨، صدر عن مجلس الأمن القرار ٤٢٥ الذي قضى بسحب القوّات الإسرائيليّة دون قيد أو شرط.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30350, 14183, 2, 'بعد أن احتلّت إسرائيل الجنوب اللبنانيّ والبقاع الغربيّ في آذار عام ١٩٧٨، صدر عن مجلس الأمن القرار ٤٢٥ الذي قضى بسحب القوّات الإسرائيليّة دون قيد أو شرط.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30351, 14184, 1, 'تعتبر الدول الموقّعة على المعاهدات والمواثيق الخاصّة هذه المواثيق مصدراً قانونياً ملزماً يضمن حقوقاً إضافيّة للإنسان.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30352, 14184, 2, 'تعتبر الدول الموقّعة على المعاهدات والمواثيق الخاصّة هذه المواثيق مصدراً قانونياً ملزماً يضمن حقوقاً إضافيّة للإنسان.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30353, 14185, 1, 'مَن هو العنصر المشترك بين تنظيم الأسرة وتنمية المجتمع بحسب درس «تنظيم الأسرة حاجة فرديّة ومجتمعيّة»؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30354, 14185, 2, 'مَن هو العنصر المشترك بين تنظيم الأسرة وتنمية المجتمع بحسب درس «تنظيم الأسرة حاجة فرديّة ومجتمعيّة»؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(30355, 14186, 1, 'شابّ لبنانيّ أكمل الحادية والعشرين من عمره، وتهرّب من خدمة العلم، ثمّ أراد أن يشارك في الانتخابات النيابيّة ناخباً.\n(أ) هل يحقّ له ذلك؟ علّل جوابك بالاستناد إلى درس واجبات المواطن.\n(ب) مستعيناً بدرس حقّ الترشيح والانتخاب، اشرح لماذا يُعدّ الانتخاب حقّاً وواجباً ومسؤوليّة معاً، ثمّ بيّن العلاقة بين هذا الحقّ وواجب خدمة العلم في الدولة الديمقراطيّة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30356, 14186, 2, 'شابّ لبنانيّ أكمل الحادية والعشرين من عمره، وتهرّب من خدمة العلم، ثمّ أراد أن يشارك في الانتخابات النيابيّة ناخباً.\n(أ) هل يحقّ له ذلك؟ علّل جوابك بالاستناد إلى درس واجبات المواطن.\n(ب) مستعيناً بدرس حقّ الترشيح والانتخاب، اشرح لماذا يُعدّ الانتخاب حقّاً وواجباً ومسؤوليّة معاً، ثمّ بيّن العلاقة بين هذا الحقّ وواجب خدمة العلم في الدولة الديمقراطيّة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30357, 14187, 1, 'اقرأ المستند الآتي ثمّ أجب:\n«وفي إنكلترا، صدرت الشرعة الكبرى سنة ألف ومئتين وخمس عشرة، وهي تُعدّ أوّل شرعة للحرّيّات، ونصّت على احترام الحرّيّة الشخصيّة. [...] أمّا في فرنسا، فقد غذّى فلاسفة ومفكّرون مثل فولتير وديدرو ومونتسكيو الجدل حول حقوق الإنسان، وطالبوا بالمساواة والحرّيّة والإخاء، فصدر إعلان حقوق الإنسان والمواطن سنة ألف وسبعمئة وتسع وثمانين.»\nأ- سمِّ الوثيقتين الواردتين في المستند، وحدّد البلد الذي صدرت فيه كلّ منهما.\nب- بيّن المحورين اللذين تقوم عليهما شرعة تنظيم العلاقات بين البشر كما يظهران في مطالب المستند.\nج- إلى أيّ إعلان مهّدت هذه المحطّات وغيرها، ومتى صدر؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30358, 14187, 2, 'اقرأ المستند الآتي ثمّ أجب:\n«وفي إنكلترا، صدرت الشرعة الكبرى سنة ألف ومئتين وخمس عشرة، وهي تُعدّ أوّل شرعة للحرّيّات، ونصّت على احترام الحرّيّة الشخصيّة. [...] أمّا في فرنسا، فقد غذّى فلاسفة ومفكّرون مثل فولتير وديدرو ومونتسكيو الجدل حول حقوق الإنسان، وطالبوا بالمساواة والحرّيّة والإخاء، فصدر إعلان حقوق الإنسان والمواطن سنة ألف وسبعمئة وتسع وثمانين.»\nأ- سمِّ الوثيقتين الواردتين في المستند، وحدّد البلد الذي صدرت فيه كلّ منهما.\nب- بيّن المحورين اللذين تقوم عليهما شرعة تنظيم العلاقات بين البشر كما يظهران في مطالب المستند.\nج- إلى أيّ إعلان مهّدت هذه المحطّات وغيرها، ومتى صدر؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30359, 14188, 1, 'تتكوّن الأسرة بالزواج، ويزداد عدد أفرادها بالإنجاب. فبماذا يزداد تماسكها؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30360, 14188, 2, 'تتكوّن الأسرة بالزواج، ويزداد عدد أفرادها بالإنجاب. فبماذا يزداد تماسكها؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30361, 14189, 1, 'أيّ ممّا يلي يندرج ضمن فئة «صحّة الطفل» من شروط الأمان الصحّي للأسرة؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30362, 14189, 2, 'أيّ ممّا يلي يندرج ضمن فئة «صحّة الطفل» من شروط الأمان الصحّي للأسرة؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30363, 14190, 1, 'ما الذي يبقى أساس معالجة النزاعات الأسرية في كلّ الميادين؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30364, 14190, 2, 'ما الذي يبقى أساس معالجة النزاعات الأسرية في كلّ الميادين؟', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30365, 14191, 1, 'علّل: وجب الفصل بين السلطات في دولة القانون. استعن في تعليلك بما تعرفه من درس حقّ مقاومة الظلم والاستبداد عن خصائص الحاكم المستبدّ.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30366, 14191, 2, 'علّل: وجب الفصل بين السلطات في دولة القانون. استعن في تعليلك بما تعرفه من درس حقّ مقاومة الظلم والاستبداد عن خصائص الحاكم المستبدّ.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30367, 14192, 1, 'عُرض مشروع قرار على مجلس الأمن، فأيّده أربعة عشر عضواً وعارضته فرنسا وحدها.\nأ- ماذا يحلّ بهذا القرار؟ علّل إجابتك.\nب- لو عُرض المشروع نفسه على الجمعيّة العامّة للأمم المتّحدة، فكم يكون وزن صوت فرنسا فيها مقارنة بسائر الدول؟\nج- سمِّ الجهاز الذي ينتخب الأعضاء العشرة غير الدائمين في مجلس الأمن.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30368, 14192, 2, 'عُرض مشروع قرار على مجلس الأمن، فأيّده أربعة عشر عضواً وعارضته فرنسا وحدها.\nأ- ماذا يحلّ بهذا القرار؟ علّل إجابتك.\nب- لو عُرض المشروع نفسه على الجمعيّة العامّة للأمم المتّحدة، فكم يكون وزن صوت فرنسا فيها مقارنة بسائر الدول؟\nج- سمِّ الجهاز الذي ينتخب الأعضاء العشرة غير الدائمين في مجلس الأمن.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30369, 14193, 1, 'في الدول التي تشهد نقصاناً في عدد سكانها، كفرنسا، يشكّل الإنجاب عامل تغيير لهذا الواقع، لذلك يقترن بالتشجيع والإغراء.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30370, 14193, 2, 'في الدول التي تشهد نقصاناً في عدد سكانها، كفرنسا، يشكّل الإنجاب عامل تغيير لهذا الواقع، لذلك يقترن بالتشجيع والإغراء.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30371, 14194, 1, 'اقرأ المستند الآتي من نصّ القرار ٤٢٥ كما ورد في الدرس، ثمّ أجب:\n«يدعو مجلس الأمن إلى احترام صارم لسلامة الأراضي اللبنانيّة وسيادة لبنان واستقلاله السياسيّ ضمن حدوده المعترف بها دوليّاً. ويدعو إسرائيل إلى أن توقف فوراً عملها العسكريّ ضدّ سلامة الأراضي اللبنانيّة، وأن تسحب على التوّ قوّاتها من كلّ الأراضي اللبنانيّة.»\n(أ) استخرج من المستند عنصرين من عناصر مفهوم الاستقلال.\n(ب) بيّن لماذا يُعدّ الاحتلال الذي يعالجه هذا القرار عدواناً صارخاً، وكيف يجب مواجهته.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30372, 14194, 2, 'اقرأ المستند الآتي من نصّ القرار ٤٢٥ كما ورد في الدرس، ثمّ أجب:\n«يدعو مجلس الأمن إلى احترام صارم لسلامة الأراضي اللبنانيّة وسيادة لبنان واستقلاله السياسيّ ضمن حدوده المعترف بها دوليّاً. ويدعو إسرائيل إلى أن توقف فوراً عملها العسكريّ ضدّ سلامة الأراضي اللبنانيّة، وأن تسحب على التوّ قوّاتها من كلّ الأراضي اللبنانيّة.»\n(أ) استخرج من المستند عنصرين من عناصر مفهوم الاستقلال.\n(ب) بيّن لماذا يُعدّ الاحتلال الذي يعالجه هذا القرار عدواناً صارخاً، وكيف يجب مواجهته.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30373, 14195, 1, 'تعلّمتَ في درس المنظّمات الدوليّة والإقليميّة أنّ الإعلان العالميّ لحقوق الإنسان ليس ملزِماً بطبيعته القانونيّة، وتعلّمتَ في درس الإجراءات التطبيقيّة أنّ إقرار الاتفاقيّتين الدوليّتين مثّل نقلة نوعيّة من مستوى التمنّيات إلى مستوى الإجراءات العمليّة.\nأ- بيّن مصدر قوّة الإعلان العالميّ على الرغم من أنّه غير ملزِم بطبيعته القانونيّة.\nب- اذكر ثلاثة من الجهود التي بذلتها المنظّمات والأمم المتّحدة بعد إقرار الاتفاقيّتين لحماية حقوق الإنسان عمليّاً.\nج- اشرح ماذا أتاح البروتوكول الاختياري للفرد، وعلّل لماذا لا تتعارض هذه الرقابة مع السيادة الداخليّة للدولة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30374, 14195, 2, 'تعلّمتَ في درس المنظّمات الدوليّة والإقليميّة أنّ الإعلان العالميّ لحقوق الإنسان ليس ملزِماً بطبيعته القانونيّة، وتعلّمتَ في درس الإجراءات التطبيقيّة أنّ إقرار الاتفاقيّتين الدوليّتين مثّل نقلة نوعيّة من مستوى التمنّيات إلى مستوى الإجراءات العمليّة.\nأ- بيّن مصدر قوّة الإعلان العالميّ على الرغم من أنّه غير ملزِم بطبيعته القانونيّة.\nب- اذكر ثلاثة من الجهود التي بذلتها المنظّمات والأمم المتّحدة بعد إقرار الاتفاقيّتين لحماية حقوق الإنسان عمليّاً.\nج- اشرح ماذا أتاح البروتوكول الاختياري للفرد، وعلّل لماذا لا تتعارض هذه الرقابة مع السيادة الداخليّة للدولة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30375, 14196, 1, 'تلد المرأة العربيّة ستّة أطفال في المتوسّط خلال حياتها الإنجابيّة، وهذا يعادل ضعفَي نظيره في الدول المتقدّمة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30376, 14196, 2, 'تلد المرأة العربيّة ستّة أطفال في المتوسّط خلال حياتها الإنجابيّة، وهذا يعادل ضعفَي نظيره في الدول المتقدّمة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30377, 14197, 1, 'تكفل المادّة الثالثة عشرة من الدستور اللبنانيّ «حرّيّة تأليف الجمعيّات» ضمن دائرة القانون. اتّفقت مجموعة من الشبّان على تأسيس جمعيّة لرعاية اليتامى في بلدتهم.\n(أ) هل يحتاجون إلى رخصة مسبقة؟ وما الذي يلزمهم به القانون بعد التأسيس؟\n(ب) بيّن كيف تظهر عبارة «ضمن دائرة القانون» في تنظيم الجمعيّات، مع ذكر نوعين من الجمعيّات الممنوعة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30378, 14197, 2, 'تكفل المادّة الثالثة عشرة من الدستور اللبنانيّ «حرّيّة تأليف الجمعيّات» ضمن دائرة القانون. اتّفقت مجموعة من الشبّان على تأسيس جمعيّة لرعاية اليتامى في بلدتهم.\n(أ) هل يحتاجون إلى رخصة مسبقة؟ وما الذي يلزمهم به القانون بعد التأسيس؟\n(ب) بيّن كيف تظهر عبارة «ضمن دائرة القانون» في تنظيم الجمعيّات، مع ذكر نوعين من الجمعيّات الممنوعة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30379, 14198, 1, 'بعد الزواج، تصبح الوقاية من الأمراض، وخاصّة الجنسيّة منها، مسؤوليّة الأب وحده.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30380, 14198, 2, 'بعد الزواج، تصبح الوقاية من الأمراض، وخاصّة الجنسيّة منها، مسؤوليّة الأب وحده.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30381, 14199, 1, 'من الأسباب العاطفية والنفسية للنزاعات الأسرية أجواء الشجار بين الأبناء أنفسهم، حين يسعى كلّ منهم إلى الاستئثار بالمكاسب الممكنة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30382, 14199, 2, 'من الأسباب العاطفية والنفسية للنزاعات الأسرية أجواء الشجار بين الأبناء أنفسهم، حين يسعى كلّ منهم إلى الاستئثار بالمكاسب الممكنة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30383, 14200, 1, 'اقرأ المقطع الآتي من درس «مفهوم تنظيم الأسرة»، ثمّ أجب:\n«عدد سكّان العالم يتزايد بسرعة، وتتركّز غالبيّة هذه الزيادة في الدول النامية. […] وكلّ عام تستقبل الأرض ملايين البشر الإضافيّين، وهذا يجعل خطط التنمية محدودة الفاعليّة.»\nأ- اشرح سببَي تسارع وتيرة النموّ السكّاني في العالم.\nب- مستعيناً بدرس «تنظيم الأسرة حاجة فرديّة ومجتمعيّة»، بيّن لماذا يجعل ازدياد السكان خطط التنمية محدودة الفاعليّة، ذاكراً ثلاثة من الأعباء التي يرتّبها على الدولة.\nج- بيّن كيف يسهم جعل الإنجاب جزءاً من سياسة سكانيّة تنمويّة في مواجهة هذه المشكلة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30384, 14200, 2, 'اقرأ المقطع الآتي من درس «مفهوم تنظيم الأسرة»، ثمّ أجب:\n«عدد سكّان العالم يتزايد بسرعة، وتتركّز غالبيّة هذه الزيادة في الدول النامية. […] وكلّ عام تستقبل الأرض ملايين البشر الإضافيّين، وهذا يجعل خطط التنمية محدودة الفاعليّة.»\nأ- اشرح سببَي تسارع وتيرة النموّ السكّاني في العالم.\nب- مستعيناً بدرس «تنظيم الأسرة حاجة فرديّة ومجتمعيّة»، بيّن لماذا يجعل ازدياد السكان خطط التنمية محدودة الفاعليّة، ذاكراً ثلاثة من الأعباء التي يرتّبها على الدولة.\nج- بيّن كيف يسهم جعل الإنجاب جزءاً من سياسة سكانيّة تنمويّة في مواجهة هذه المشكلة.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30385, 14201, 1, 'زوجان دخلهما محدود، رُزقا بطفلهما الأوّل منذ أشهر قليلة، ويفكّر الزوج في إنجاب طفل ثانٍ فوراً من دون أن يتشاور مع زوجته.\nأ- بيّن، استناداً إلى ما تعلّمته عن حجم الأسرة، لماذا يُنصح هذان الزوجان بالمباعدة بين مولود وآخر.\nب- اذكر ثلاث وسائل يتحقّق بها النموّ الاقتصادي للأسرة.\nج- بيّن كيف يجب أن يُتّخذ قرار الإنجاب في هذه الأسرة، وماذا على الأهل أن يفعلوا قبل الإقدام عليه.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30386, 14201, 2, 'زوجان دخلهما محدود، رُزقا بطفلهما الأوّل منذ أشهر قليلة، ويفكّر الزوج في إنجاب طفل ثانٍ فوراً من دون أن يتشاور مع زوجته.\nأ- بيّن، استناداً إلى ما تعلّمته عن حجم الأسرة، لماذا يُنصح هذان الزوجان بالمباعدة بين مولود وآخر.\nب- اذكر ثلاث وسائل يتحقّق بها النموّ الاقتصادي للأسرة.\nج- بيّن كيف يجب أن يُتّخذ قرار الإنجاب في هذه الأسرة، وماذا على الأهل أن يفعلوا قبل الإقدام عليه.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30387, 14202, 1, 'اقرأ المقطع الآتي من درس «الانسجام في الأسرة ومعالجة النزاعات بين أفرادها»:\n«يلجأ بعض الأهل إلى إخماد النزاع، دون معالجة جذوره وأسبابه. هذا هو القمع، وتبقى فيه الأسباب قائمة. أمّا المعالجة فتقوم على الحوار، وعلى الاعتراف العادل بالخلافات والتباينات، وصولاً إلى معالجتها.»\nأسرة تدنّى دخلها وضاق مسكنها، ويتشاجر أفرادها كلّما قارنوا أوضاعهم بأسر تفوقهم ثروة وغنى، فيكتفي الأب بإسكاتهم.\nأ- حدّد سبب النزاع في هذه الأسرة، وصنّف موقف الأب بالاستناد إلى المقطع.\nب- علّل لماذا لا يكفي موقف الأب لحلّ النزاع.\nج- اقترح سبيل المعالجة المناسب لهذا الميدان.\nد- مستعيناً بدرس «أمان الأسرة واتّخاذ القرارات فيها»، صِف كيف يمكن لهذه الأسرة أن تتّخذ قراراً مشتركاً في تخطيط مصروفها.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
(30388, 14202, 2, 'اقرأ المقطع الآتي من درس «الانسجام في الأسرة ومعالجة النزاعات بين أفرادها»:\n«يلجأ بعض الأهل إلى إخماد النزاع، دون معالجة جذوره وأسبابه. هذا هو القمع، وتبقى فيه الأسباب قائمة. أمّا المعالجة فتقوم على الحوار، وعلى الاعتراف العادل بالخلافات والتباينات، وصولاً إلى معالجتها.»\nأسرة تدنّى دخلها وضاق مسكنها، ويتشاجر أفرادها كلّما قارنوا أوضاعهم بأسر تفوقهم ثروة وغنى، فيكتفي الأب بإسكاتهم.\nأ- حدّد سبب النزاع في هذه الأسرة، وصنّف موقف الأب بالاستناد إلى المقطع.\nب- علّل لماذا لا يكفي موقف الأب لحلّ النزاع.\nج- اقترح سبيل المعالجة المناسب لهذا الميدان.\nد- مستعيناً بدرس «أمان الأسرة واتّخاذ القرارات فيها»، صِف كيف يمكن لهذه الأسرة أن تتّخذ قراراً مشتركاً في تخطيط مصروفها.', 1, '2026-09-30 22:54:28', '2026-09-30 22:54:28'),
