(30531, 14274, 1, 'بيّن كيف تحكّمت الشروط الطبيعيّة بتوزيع السكن في لبنان حين كان دوره الاقتصاديّ زراعيّاً (حتّى منتصف القرن التاسع عشر)، ثمّ أعطِ مثالين على مدن داخليّة نمت في تلك الفترة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30532, 14274, 2, 'بيّن كيف تحكّمت الشروط الطبيعيّة بتوزيع السكن في لبنان حين كان دوره الاقتصاديّ زراعيّاً (حتّى منتصف القرن التاسع عشر)، ثمّ أعطِ مثالين على مدن داخليّة نمت في تلك الفترة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30533, 14275, 1, 'اقرأ المستند الآتي ثمّ أجب:\n«تستقطب بيروت تجارة الجملة، وقد قام نموّها على نموّ المرفأ، حيث أقيمت في محيطه الوكالات التجاريّة. وبما أنّ تجارة المفرّق ترتبط بتجارة الجملة، فإنّ بيروت تمدّ المدن الأخرى بالموارد عبر شبكة التوزيع السلعيّ، وتدمجها باقتصادها، أي تنظّم استهلاك الريف وفق أنماطها. وتلعب المدن الأخرى في هذه العمليّة دور الوسيط التجاريّ.»\n(أ) سمِّ عامل الاستقطاب الذي يتناوله المستند، واذكر الوجه الآخر لهذا العامل.\n(ب) أعطِ معطى رقميّاً من الدرس يؤكّد هيمنة بيروت التجاريّة.\n(ج) بيّن، بمثال التاجر في مدينة بعيدة، كيف ترتبط المدن الأخرى بالعاصمة، وما العلاقة التي يكشفها ذلك.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30534, 14275, 2, 'اقرأ المستند الآتي ثمّ أجب:\n«تستقطب بيروت تجارة الجملة، وقد قام نموّها على نموّ المرفأ، حيث أقيمت في محيطه الوكالات التجاريّة. وبما أنّ تجارة المفرّق ترتبط بتجارة الجملة، فإنّ بيروت تمدّ المدن الأخرى بالموارد عبر شبكة التوزيع السلعيّ، وتدمجها باقتصادها، أي تنظّم استهلاك الريف وفق أنماطها. وتلعب المدن الأخرى في هذه العمليّة دور الوسيط التجاريّ.»\n(أ) سمِّ عامل الاستقطاب الذي يتناوله المستند، واذكر الوجه الآخر لهذا العامل.\n(ب) أعطِ معطى رقميّاً من الدرس يؤكّد هيمنة بيروت التجاريّة.\n(ج) بيّن، بمثال التاجر في مدينة بعيدة، كيف ترتبط المدن الأخرى بالعاصمة، وما العلاقة التي يكشفها ذلك.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30535, 14276, 1, 'ممرّ ظهر البيدر من ممرّات السلسلة الغربيّة التي تصل المنطقة الساحليّة بسهل البقاع.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30536, 14276, 2, 'ممرّ ظهر البيدر من ممرّات السلسلة الغربيّة التي تصل المنطقة الساحليّة بسهل البقاع.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30537, 14277, 1, 'يُعتبر لبنان «خزّان المياه في الشرق الأوسط». اشرح ذلك رابطاً بين ما درسته في درس «التاريخ الجيولوجيّ والتضاريس» عن البنية العامّة للأراضي اللبنانيّة وفئات صخورها، وما درسته في درس «المياه في لبنان» عن مصدر المياه وطبيعة الصخور الكلسيّة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30538, 14277, 2, 'يُعتبر لبنان «خزّان المياه في الشرق الأوسط». اشرح ذلك رابطاً بين ما درسته في درس «التاريخ الجيولوجيّ والتضاريس» عن البنية العامّة للأراضي اللبنانيّة وفئات صخورها، وما درسته في درس «المياه في لبنان» عن مصدر المياه وطبيعة الصخور الكلسيّة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30539, 14278, 1, '«فالساحل ليس مجرّد موقع، بل هو البوّابة التي تمرّ منها التجارة الخارجيّة اللبنانيّة». اشرح هذه العبارة مستنداً إلى درسَي «المواصلات في المنطقة الساحليّة» و«التجارة في المنطقة الساحليّة»، مبيّناً:\n(أ) منافذ التبادل التجاريّ الخارجيّ وترتيبها.\n(ب) مكانة مرفأ بيروت وأسبابها.\n(ج) دور المرافئ الساحليّة في تجارة الترانزيت وما يستفيده لبنان منها.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30540, 14279, 1, 'اقرأ المستند الآتي ثمّ أجب:\n«تنعكس فتوّة الأعمار في الحاجات الإسكانيّة والاقتصاديّة والاجتماعيّة، وفي إمكانيّة تلبيتها. ومن آثارها أنّ نسبة إعالة الصغار انخفضت في المجتمع اللبناني، وتراجع نسبة الفتوّة سيخفّف تدريجياً من معدّل الإعالة.»\nأ- حدّد من المستند المجالات التي تنعكس فيها فتوّة الأعمار، والأثر الذي يذكره المستند.\nب- اشرح أثرين آخرين لفتوّة الأعمار في المجتمع اللبناني لم يذكرهما المستند.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30541, 14278, 2, '«فالساحل ليس مجرّد موقع، بل هو البوّابة التي تمرّ منها التجارة الخارجيّة اللبنانيّة». اشرح هذه العبارة مستنداً إلى درسَي «المواصلات في المنطقة الساحليّة» و«التجارة في المنطقة الساحليّة»، مبيّناً:\n(أ) منافذ التبادل التجاريّ الخارجيّ وترتيبها.\n(ب) مكانة مرفأ بيروت وأسبابها.\n(ج) دور المرافئ الساحليّة في تجارة الترانزيت وما يستفيده لبنان منها.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30542, 14279, 2, 'اقرأ المستند الآتي ثمّ أجب:\n«تنعكس فتوّة الأعمار في الحاجات الإسكانيّة والاقتصاديّة والاجتماعيّة، وفي إمكانيّة تلبيتها. ومن آثارها أنّ نسبة إعالة الصغار انخفضت في المجتمع اللبناني، وتراجع نسبة الفتوّة سيخفّف تدريجياً من معدّل الإعالة.»\nأ- حدّد من المستند المجالات التي تنعكس فيها فتوّة الأعمار، والأثر الذي يذكره المستند.\nب- اشرح أثرين آخرين لفتوّة الأعمار في المجتمع اللبناني لم يذكرهما المستند.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30543, 14280, 1, 'اقرأ المستند الآتي عن نتائج تحرّر السكن الجبليّ من قيود الطبيعة، ثمّ أجب:\n«والنتائج ثلاث. الأولى تمركّز سكّانيّ جديد في المنطقة الجبليّة السفلى القريبة من المدن الساحليّة حيث تتوافر فرص العمل والعلم. والثانية تدنّي الكثافة السكّانيّة في القرى الجبليّة العالية وفي الأرياف البعيدة.»\nأ- اذكر دافعَين دفعا الناس إلى هذا التحوّل. ب- علّل، بالاستناد إلى المستند، التمركّز السكّانيّ الجديد في المنطقة الجبليّة السفلى. ج- اذكر النتيجة الثالثة التي لم يوردها المستند.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30544, 14280, 2, 'اقرأ المستند الآتي عن نتائج تحرّر السكن الجبليّ من قيود الطبيعة، ثمّ أجب:\n«والنتائج ثلاث. الأولى تمركّز سكّانيّ جديد في المنطقة الجبليّة السفلى القريبة من المدن الساحليّة حيث تتوافر فرص العمل والعلم. والثانية تدنّي الكثافة السكّانيّة في القرى الجبليّة العالية وفي الأرياف البعيدة.»\nأ- اذكر دافعَين دفعا الناس إلى هذا التحوّل. ب- علّل، بالاستناد إلى المستند، التمركّز السكّانيّ الجديد في المنطقة الجبليّة السفلى. ج- اذكر النتيجة الثالثة التي لم يوردها المستند.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30545, 14281, 1, 'بيّن ما تؤمّنه بورصة بيروت للشركات التي تطرح أسهمها فيها وللأفراد، ثمّ اذكر أمراً ما يزال يحدّ من دورها.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30546, 14281, 2, 'بيّن ما تؤمّنه بورصة بيروت للشركات التي تطرح أسهمها فيها وللأفراد، ثمّ اذكر أمراً ما يزال يحدّ من دورها.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30547, 14282, 1, 'انتقلت أسرة من مدينة تقع في المنطقة الساحليّة الرطبة إلى البقاع الأوسط. قارن بين المنطقتين المناخيّتين من حيث معدّل الأمطار والمدى الحراريّ، مع تعليل الفرق في المدى الحراريّ.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30548, 14282, 2, 'انتقلت أسرة من مدينة تقع في المنطقة الساحليّة الرطبة إلى البقاع الأوسط. قارن بين المنطقتين المناخيّتين من حيث معدّل الأمطار والمدى الحراريّ، مع تعليل الفرق في المدى الحراريّ.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30549, 14283, 1, 'ترد بلدات بحمدون وصوفر وعاليه في درس «السكّان والخدمات في المنطقة الجبليّة» وفي ملفّ «المواصلات والممرّات في المنطقة الجبليّة». أ- بيّن لماذا كانت هذه البلدات من أولى بلدات الاصطياف في الجبل. ب- اشرح كيف وفّر خطّ ممرّ ظهر البيدر فرص الازدهار للمدن الواقعة عليه، مستعيناً بوظيفتَيه في حركة الناس.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30550, 14283, 2, 'ترد بلدات بحمدون وصوفر وعاليه في درس «السكّان والخدمات في المنطقة الجبليّة» وفي ملفّ «المواصلات والممرّات في المنطقة الجبليّة». أ- بيّن لماذا كانت هذه البلدات من أولى بلدات الاصطياف في الجبل. ب- اشرح كيف وفّر خطّ ممرّ ظهر البيدر فرص الازدهار للمدن الواقعة عليه، مستعيناً بوظيفتَيه في حركة الناس.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30551, 14284, 1, 'علّل: تدلّ النسبة الكبيرة من رجال الأعمال بين نزلاء الفنادق في المنطقة الساحليّة على ضرورة تنشيط السياحة الجماهيريّة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30552, 14284, 2, 'علّل: تدلّ النسبة الكبيرة من رجال الأعمال بين نزلاء الفنادق في المنطقة الساحليّة على ضرورة تنشيط السياحة الجماهيريّة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30553, 14285, 1, 'للزراعة في المنطقة الجبليّة وجهان. أ- قارن بين الزراعات البعليّة والزراعات المرويّة من حيث: مصدر المياه، وأبرز المزروعات، والمردود أو النتاج. ب- علّل حلول الأصناف المدارية في البساتين المرويّة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30554, 14285, 2, 'للزراعة في المنطقة الجبليّة وجهان. أ- قارن بين الزراعات البعليّة والزراعات المرويّة من حيث: مصدر المياه، وأبرز المزروعات، والمردود أو النتاج. ب- علّل حلول الأصناف المدارية في البساتين المرويّة.', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30555, 14286, 1, 'في البقاع الجنوبيّ احتلّت القرى والمحلّات السكنيّة الروابي المشرفة على السهل. لماذا؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30556, 14286, 2, 'في البقاع الجنوبيّ احتلّت القرى والمحلّات السكنيّة الروابي المشرفة على السهل. لماذا؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30557, 14287, 1, 'في أيّ مرحلة من مراحل تطوّر الاقتصاد اللبنانيّ شهد لبنان حالة ازدهار اقتصاديّ، فتحوّل كثير من الأيدي العاملة ورؤوس الأموال نحو قطاع الخدمات وخصوصاً التجارة؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30558, 14287, 2, 'في أيّ مرحلة من مراحل تطوّر الاقتصاد اللبنانيّ شهد لبنان حالة ازدهار اقتصاديّ، فتحوّل كثير من الأيدي العاملة ورؤوس الأموال نحو قطاع الخدمات وخصوصاً التجارة؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30559, 14288, 1, 'ما نوع التربة التي تسود في منطقة بعلبك ورياق؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30560, 14288, 2, 'ما نوع التربة التي تسود في منطقة بعلبك ورياق؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
(30561, 14289, 1, 'تتفاوت وجهة العلاقات الاقتصاديّة بين دولةٍ عربيّةٍ وأخرى. مع أيّ مجموعةٍ من الدول العربيّة تحرص الولايات المتّحدة الأميركيّة على علاقاتٍ مميّزة؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(30562, 14289, 2, 'تتفاوت وجهة العلاقات الاقتصاديّة بين دولةٍ عربيّةٍ وأخرى. مع أيّ مجموعةٍ من الدول العربيّة تحرص الولايات المتّحدة الأميركيّة على علاقاتٍ مميّزة؟', 1, '2026-09-30 22:54:32', '2026-09-30 22:54:32'),
