(33665, 15789, 1, '٥- يجمع نصّ «بيت جدّي» بين الوصف الموضوعيّ والوصف الوجدانيّ. هاتِ من الفقرة الأولى مؤشّرين على الوصف الموضوعيّ، ومن الفقرة الثانية مؤشّرين على الوصف الوجدانيّ، مع مثال من النصّ لكلّ مؤشّر.', 1, '2026-10-01 01:31:39', '2026-10-01 01:31:39'),
(33666, 15789, 2, '٥- يجمع نصّ «بيت جدّي» بين الوصف الموضوعيّ والوصف الوجدانيّ. هاتِ من الفقرة الأولى مؤشّرين على الوصف الموضوعيّ، ومن الفقرة الثانية مؤشّرين على الوصف الوجدانيّ، مع مثال من النصّ لكلّ مؤشّر.', 1, '2026-10-01 01:31:39', '2026-10-01 01:31:39'),
(33667, 15790, 1, 'امرأة تمتهن الخياطة لجمع المال، وأخرى تمارسها لإصلاح ثياب العائلة. أيّ فكرة عند بيار جانيه توضّحها هذه الحالة؟', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33668, 15790, 2, 'امرأة تمتهن الخياطة لجمع المال، وأخرى تمارسها لإصلاح ثياب العائلة. أيّ فكرة عند بيار جانيه توضّحها هذه الحالة؟', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33669, 15791, 1, '٦- أ- حدّد الفكرة العامّة لنصّ «بيت جدّي» في جملة واحدة.\nب- بيّن كيف تدرّج الكاتب في عرض أفكاره، مستعينًا بمؤشّر زمنيّ أو أداة ربط من النصّ.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33670, 15791, 2, '٦- أ- حدّد الفكرة العامّة لنصّ «بيت جدّي» في جملة واحدة.\nب- بيّن كيف تدرّج الكاتب في عرض أفكاره، مستعينًا بمؤشّر زمنيّ أو أداة ربط من النصّ.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33671, 15792, 1, 'في النظرية الفيزيولوجية، يتكوّن جسم الإنسان من أربعة أخلاط توازي:', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33672, 15792, 2, 'في النظرية الفيزيولوجية، يتكوّن جسم الإنسان من أربعة أخلاط توازي:', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33673, 15793, 1, '٧- أعرب ما يأتي كما ورد في النصّ: الكلمات إعرابَ مفردات، وما بين قوسين إعرابَ جمل:\n- «وَيَجْلِسُ مَسَاءً تَحْتَ شَجَرَةِ التُّوتِ الْعَتِيقَةِ»: مَسَاءً – الْعَتِيقَةِ\n- «هُنَا قَضَيْتُ أَجْمَلَ أَيَّامِ طُفُولَتِي»: هُنَا\n- «وَفِي زَاوِيَتِهَا بِئْرٌ قَدِيمَةٌ (يُغَطِّيهَا لَوْحٌ مِنْ حَدِيدٍ)»', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33674, 15793, 2, '٧- أعرب ما يأتي كما ورد في النصّ: الكلمات إعرابَ مفردات، وما بين قوسين إعرابَ جمل:\n- «وَيَجْلِسُ مَسَاءً تَحْتَ شَجَرَةِ التُّوتِ الْعَتِيقَةِ»: مَسَاءً – الْعَتِيقَةِ\n- «هُنَا قَضَيْتُ أَجْمَلَ أَيَّامِ طُفُولَتِي»: هُنَا\n- «وَفِي زَاوِيَتِهَا بِئْرٌ قَدِيمَةٌ (يُغَطِّيهَا لَوْحٌ مِنْ حَدِيدٍ)»', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33675, 15794, 1, '٨- كان الجدّ يقول: «بِئْسَ الْعَيْشُ الْوَحْدَةُ!».\nأ- عيّن فعل الذمّ، وفاعله، والمخصوص بالذمّ.\nب- أعرب «الْوَحْدَةُ»، وبيّن محلّ جملة «بِئْسَ الْعَيْشُ» من الإعراب.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33676, 15794, 2, '٨- كان الجدّ يقول: «بِئْسَ الْعَيْشُ الْوَحْدَةُ!».\nأ- عيّن فعل الذمّ، وفاعله، والمخصوص بالذمّ.\nب- أعرب «الْوَحْدَةُ»، وبيّن محلّ جملة «بِئْسَ الْعَيْشُ» من الإعراب.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33677, 15795, 1, 'من أصحاب النظرية التجريبية الإنكليزيان دايفد هيوم وجون لوك، والفرنسي كوندياك.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33678, 15795, 2, 'من أصحاب النظرية التجريبية الإنكليزيان دايفد هيوم وجون لوك، والفرنسي كوندياك.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33679, 15796, 1, '٩- أعد كتابة الجملة الآتية ضابطًا أواخر كلماتها بالحركات المناسبة:\nجلس الجد مساء تحت شجرة التوت، وروى للأحفاد حكايات جميلة.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33680, 15796, 2, '٩- أعد كتابة الجملة الآتية ضابطًا أواخر كلماتها بالحركات المناسبة:\nجلس الجد مساء تحت شجرة التوت، وروى للأحفاد حكايات جميلة.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33681, 15797, 1, 'انتقد موريس برادين النظرية التجريبية مميّزاً بين الميل إلى الشيء والميل عن الشيء.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33682, 15797, 2, 'انتقد موريس برادين النظرية التجريبية مميّزاً بين الميل إلى الشيء والميل عن الشيء.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(33683, 15798, 1, '١٠- قطّع البيت الشعريّ الوارد في الإطار المرافق لنصّ «بيت جدّي»، واذكر تفعيلاته وبحره، وعيّن رويّه وقافيته:\nوَهَذِهِ الدَّارُ لَا تُبْقِي عَلَى أَحَدٍ ... وَلَا يَدُومُ عَلَى حَالٍ لَهَا شَانُ', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33684, 15798, 2, '١٠- قطّع البيت الشعريّ الوارد في الإطار المرافق لنصّ «بيت جدّي»، واذكر تفعيلاته وبحره، وعيّن رويّه وقافيته:\nوَهَذِهِ الدَّارُ لَا تُبْقِي عَلَى أَحَدٍ ... وَلَا يَدُومُ عَلَى حَالٍ لَهَا شَانُ', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33685, 15799, 1, 'بيّنت البيولوجيا الحديثة أنّ ميل الأمّ نحو أطفالها مرتبط بتزايد هرمون البرولاكتين في جسمها أثناء الحمل.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33686, 15799, 2, 'بيّنت البيولوجيا الحديثة أنّ ميل الأمّ نحو أطفالها مرتبط بتزايد هرمون البرولاكتين في جسمها أثناء الحمل.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33687, 15800, 1, '١١- تفرّق أبناء الجدّ في المدن البعيدة، فهُجر البيت. في رأيك، هل يستطيع من يعيش بعيدًا في المدينة أن يحافظ على بيت أجداده وذكرياته فيه؟ أبدِ رأيك في فقرة (٣ – ٤ أسطر)، مدعّمًا إيّاه بحجّة ومثال.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33688, 15800, 2, '١١- تفرّق أبناء الجدّ في المدن البعيدة، فهُجر البيت. في رأيك، هل يستطيع من يعيش بعيدًا في المدينة أن يحافظ على بيت أجداده وذكرياته فيه؟ أبدِ رأيك في فقرة (٣ – ٤ أسطر)، مدعّمًا إيّاه بحجّة ومثال.', 1, '2026-10-01 01:31:40', '2026-10-01 01:31:40'),
(33689, 15801, 1, 'بحسب ريبو، لا يمكن لمجموع الحركات المتكرّرة التي تشكّل عادة من العادات أن تنقلب إلى ميل.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33690, 15801, 2, 'بحسب ريبو، لا يمكن لمجموع الحركات المتكرّرة التي تشكّل عادة من العادات أن تنقلب إلى ميل.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33691, 15802, 1, '١٢- تخيّل أنّك الكاتب، وقد عدت إلى بيت جدّك بعد سنوات. اكتب فقرة (٣ – ٤ أسطر) تخاطب فيها البيت، معبّرًا عن شعورك. (لا تنسَ استخدام ضمير المخاطب، وجملة إنشائيّة، وصورة بيانيّة)', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33692, 15802, 2, '١٢- تخيّل أنّك الكاتب، وقد عدت إلى بيت جدّك بعد سنوات. اكتب فقرة (٣ – ٤ أسطر) تخاطب فيها البيت، معبّرًا عن شعورك. (لا تنسَ استخدام ضمير المخاطب، وجملة إنشائيّة، وصورة بيانيّة)', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33693, 15803, 1, 'ميّز بين الحاجات والرغبات، ووضّح الفرق بينهما بمثال الطعام.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33694, 15803, 2, 'ميّز بين الحاجات والرغبات، ووضّح الفرق بينهما بمثال الطعام.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33695, 15804, 1, 'اضطُرّت عائلتك إلى الانتقال من الحيّ الذي نشأتَ فيه... في اليوم الأخير وقفتَ على شرفة البيت تتأمّل المكان: البيوت المتلاصقة، الملعب الصغير، دكّان الحيّ... كلّ زاوية تحمل ذكرى... ودّعتَ الجيران والرفاق... واليوم، كلّما مررتَ بالحيّ...\nوسّع هذه الأفكار في نصّ وصفيّ متماسك، تصف فيه الحيّ وتعبّر عن مشاعرك نحوه، مازجًا بين الوصف الموضوعيّ والوصف الوجدانيّ.\n\nملاحظات:\n- لا تنسَ أن تضع عنوانًا لتعبيرك الكتابيّ.\n- وظّف الصور البيانيّة والمحسّنات البديعيّة.\n- اعتمد علامات الوقف الملائمة.\n- امزج بين الوصف الموضوعيّ والوصف الوجدانيّ.\n- نوّع بين الجمل الإنشائيّة والخبريّة.\n- رتّب الأفكار في فقرات، واكتب بخطّ واضح ومقروء.\n(٢٠٠ إلى ٣٥٠ كلمة تقريبًا)', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33696, 15804, 2, 'اضطُرّت عائلتك إلى الانتقال من الحيّ الذي نشأتَ فيه... في اليوم الأخير وقفتَ على شرفة البيت تتأمّل المكان: البيوت المتلاصقة، الملعب الصغير، دكّان الحيّ... كلّ زاوية تحمل ذكرى... ودّعتَ الجيران والرفاق... واليوم، كلّما مررتَ بالحيّ...\nوسّع هذه الأفكار في نصّ وصفيّ متماسك، تصف فيه الحيّ وتعبّر عن مشاعرك نحوه، مازجًا بين الوصف الموضوعيّ والوصف الوجدانيّ.\n\nملاحظات:\n- لا تنسَ أن تضع عنوانًا لتعبيرك الكتابيّ.\n- وظّف الصور البيانيّة والمحسّنات البديعيّة.\n- اعتمد علامات الوقف الملائمة.\n- امزج بين الوصف الموضوعيّ والوصف الوجدانيّ.\n- نوّع بين الجمل الإنشائيّة والخبريّة.\n- رتّب الأفكار في فقرات، واكتب بخطّ واضح ومقروء.\n(٢٠٠ إلى ٣٥٠ كلمة تقريبًا)', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33697, 15805, 1, 'اعتاد تلميذ طوال السنة الدراسية سلوك طريق المدرسة، لكنّه لا يشعر بأيّ ميل إلى سلوكه خلال عطلته الصيفية. اشرح النظرية التي تنقضها هذه الملاحظة، ثمّ بيّن النقد الذي تمثّله.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33698, 15805, 2, 'اعتاد تلميذ طوال السنة الدراسية سلوك طريق المدرسة، لكنّه لا يشعر بأيّ ميل إلى سلوكه خلال عطلته الصيفية. اشرح النظرية التي تنقضها هذه الملاحظة، ثمّ بيّن النقد الذي تمثّله.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33699, 15806, 1, 'في الموضوع الامتحاني «التجربة الحسية هي المبدأ الأول لكلّ ميولنا»، اشرح حكم كوندياك موضّحاً بمثال الوردة كيف يولد الميل عند التجريبيين، ثمّ اذكر نقدين وُجّها إلى هذه النظرية.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33700, 15806, 2, 'في الموضوع الامتحاني «التجربة الحسية هي المبدأ الأول لكلّ ميولنا»، اشرح حكم كوندياك موضّحاً بمثال الوردة كيف يولد الميل عند التجريبيين، ثمّ اذكر نقدين وُجّها إلى هذه النظرية.', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
(33701, 15807, 1, 'اقرأ النصّ الآتي، ثمّ أجب عن الأسئلة.\n\n«يَوْمٌ فِي قَلْعَةِ صَيْدَا»\n\n١- انْطَلَقْنَا مِنْ بَيْرُوتَ فِي الصَّبَاحِ الْبَاكِرِ وَالشَّمْسُ تَصْعَدُ خَلْفَ الْجِبَالِ. كَانَتِ الْحَافِلَةُ تَسِيرُ عَلَى الطَّرِيقِ السَّاحِلِيِّ نَحْوَ الْجَنُوبِ، وَالْبَحْرُ عَنْ يَمِينِنَا مِرْآةٌ زَرْقَاءُ. وَكَانَ الرِّفَاقُ يُغَنُّونَ، وَبَعْضُهُمْ يَلْتَقِطُ الصُّوَرَ مِنَ النَّوَافِذِ. سَأَلَنِي صَدِيقِي سَامِرٌ: «مَتَى نَصِلُ؟»، فَقَالَ الْمُعَلِّمُ: «سَنَصِلُ بَعْدَ سَاعَةٍ».\n\n٢- وَصَلْنَا إِلَى صَيْدَا قُبَيْلَ الظُّهْرِ، وَمَشَيْنَا فِي السُّوقِ الْقَدِيمَةِ بَيْنَ الدَّكَاكِينِ الضَّيِّقَةِ. كَانَ بَائِعٌ عَجُوزٌ يَبِيعُ الصَّابُونَ الْمَصْنُوعَ مِنْ زَيْتِ الزَّيْتُونِ، فَاشْتَرَى كُلٌّ مِنَّا قِطْعَةً صَغِيرَةً. وَكَانَتْ رَائِحَةُ الْكَعْكِ وَالْبَهَارَاتِ تَمْلَأُ الْأَزِقَّةَ الْمَسْقُوفَةَ. ثُمَّ خَرَجْنَا إِلَى الشَّاطِئِ، فَرَأَيْنَا الْقَلْعَةَ الْبَحْرِيَّةَ تَقُومُ عَلَى صَخْرَةٍ فِي الْمَاءِ، يَصِلُهَا بِالْبَرِّ جِسْرٌ حَجَرِيٌّ طَوِيلٌ.\n\n٣- عَبَرْنَا الْجِسْرَ وَالْأَمْوَاجُ تَضْرِبُ أَعْمِدَتَهُ بِهُدُوءٍ. كَانَتْ جُدْرَانُ الْقَلْعَةِ عَالِيَةً، حِجَارَتُهَا ضَخْمَةٌ رَمَادِيَّةٌ أَكَلَ الْمِلْحُ أَطْرَافَهَا، وَفِي دَاخِلِهَا قَاعَاتٌ وَاسِعَةٌ سُقُوفُهَا مُقَوَّسَةٌ، وَنَوَافِذُهَا ضَيِّقَةٌ تُطِلُّ عَلَى الْمَوْجِ. صَعِدْنَا الدَّرَجَ الضَّيِّقَ إِلَى السَّطْحِ، فَانْكَشَفَتْ أَمَامَنَا الْمَدِينَةُ وَالْمِينَاءُ وَقَوَارِبُ الصَّيَّادِينَ. سَأَلَتْ رِيمُ: «مَنْ بَنَى هَذِهِ الْقَلْعَةَ؟»، فَرَاحَ الْمُعَلِّمُ يَحْكِي لَنَا تَارِيخَهَا، وَنَحْنُ نُصْغِي(١) إِلَيْهِ كُلَّ الْإِصْغَاءِ.\n\n٤- قُبَيْلَ الْغُرُوبِ عُدْنَا إِلَى الْحَافِلَةِ مُتْعَبِينَ، فَسَأَلَنَا الْمُعَلِّمُ: «مَا رَأَيْتُمْ فِي الْقَلْعَةِ؟». قَالَ سَامِرٌ: «رَأَيْتُ حِجَارَةً»، وَقُلْتُ: «بَلْ رَأَيْتُ حِكَايَاتٍ»؛ فَفِي الْقَلْعَةِ عِبْرَةٌ لِمَنْ يَتَأَمَّلُ، وَحِكَايَةٌ لِمَنْ يَتَمَهَّلُ. وَفِي طَرِيقِ الْعَوْدَةِ قَرَّرْتُ أَنْ أَدْرُسَ التَّارِيخَ، لِأَقْرَأَ مَا تَكْتُبُهُ الْحِجَارَةُ. لَقَدْ عُدْتُ مِنْ صَيْدَا بِقِطْعَةِ صَابُونٍ فِي حَقِيبَتِي، وَبِحُلْمٍ كَبِيرٍ فِي قَلْبِي.\n\nنصّ مؤلَّف لهذا النموذج.\n\nفي إطار مرافق للنصّ البيت الآتي:\nإِذَا غَامَرْتَ فِي شَرَفٍ مَرُومِ(٢) ... فَلَا تَقْنَعْ بِمَا دُونَ النُّجُومِ\n(المتنبّي)\n\nشرح المفردات:\n(١) نُصْغِي: نستمع بانتباه.\n(٢) مَرُوم: مطلوب مرغوب فيه.\n\n١- أعد كتابة ما يأتي مختارًا الإجابة الصحيحة (نصف علامة لكلّ مطلب):\nأ- انطلقت الرحلة من:', 1, '2026-10-01 01:31:41', '2026-10-01 01:31:41'),
