(35076, 16494, 2, '【المجال الثاني: على مستوى تحليل المستندات (ستّ علامات)】\nمستند رقم (١):\n«يقدّم من يرغب في الترشّح لعضويّة المجلس البلديّ أو للمختاريّة تصريحًا باسمه لدى الكاتب العدل، ويؤدّي رسمًا مقطوعًا مقداره عشرة آلاف ليرة لبنانيّة، ثمّ يقدّم طلبه إلى القائمقاميّة أو المحافظة مع تأمين قدره خمسمئة ألف ليرة لبنانيّة يُعاد إليه إذا فاز أو نال خمسة وعشرين بالمئة من الأصوات، وذلك قبل موعد الانتخاب بخمسة أيّام على الأقلّ. ولا يُقبل الترشيح إذا لم يكن المرشّح ناخبًا مدوّنًا اسمه في القائمة الانتخابيّة. ولا يكون أهلًا لعضويّة المجلس البلديّ الذين لا يعرفون القراءة والكتابة، والمحكومون بجرائم الانتماء إلى جمعيّات سرّيّة، والمحجور عليهم قضائيًّا لعلّة العته أو الجنون...»\n(من الأحكام الناظمة للانتخابات البلديّة والاختياريّة في لبنان — بتصرّف)\n\nمستند رقم (٢):\n«قبل أسبوع من موعد الانتخابات البلديّة في إحدى البلدات، تقدّم سامي بطلب ترشيحه إلى القائمقاميّة، فرفضه القائمقام بقرار معلّل لأنّ اسمه غير مدوّن في القائمة الانتخابيّة. وفي البلدة نفسها ترشّح رئيس إحدى البلديّات المجاورة وهو في الوقت ذاته مختار في حيّه. وبعد إعلان النتائج تبيّن أنّ أخوين، هما فادي (٤٥ سنة) ووليد (٣٨ سنة)، فازا معًا بعضويّة المجلس البلديّ نفسه. وقد علّق أحد أبناء البلدة قائلًا: إنّ القانون وُضع ليبقى المجلس البلديّ ممثّلًا للناس جميعًا لا لعائلة واحدة.»\n(دراسة حالة مفترضة أُعدّت لهذا النموذج)\n\n٣- انطلاقًا من معارفك، بيّن مهامّ المجلس البلديّ، وكيف يُنتخب رئيسه ونائبه. (علامة واحدة)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35077, 16495, 1, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n١- استنتج المشكلة الرئيسة التي تطرحها الوضعيّة أعلاه. (علامة واحدة)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35078, 16495, 2, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n١- استنتج المشكلة الرئيسة التي تطرحها الوضعيّة أعلاه. (علامة واحدة)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(35079, 16496, 1, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n٢- بيّن ثلاث نتائج سلبيّة لهذه الممارسة الإعلاميّة. (علامة ونصف)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35080, 16496, 2, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n٢- بيّن ثلاث نتائج سلبيّة لهذه الممارسة الإعلاميّة. (علامة ونصف)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35081, 16497, 1, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n٣- قدّم ثلاثة اقتراحات لمواجهة هذه المشكلة. (علامة ونصف)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35082, 16497, 2, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n٣- قدّم ثلاثة اقتراحات لمواجهة هذه المشكلة. (علامة ونصف)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35083, 16498, 1, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n٤- يرى البعض أنّ حرّيّة الصحافيّ تبيح له أن ينشر كلّ ما يصل إليه، فيما يرى آخرون أنّ حرّيّة الصحافيّ لا تنفصل عن مسؤوليّاته المهنيّة.\nفي ضوء المسألة أعلاه وبالاستناد إلى معلوماتك الشخصيّة، أبدِ رأيك في هذا الموضوع معلّلًا. (علامتان)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35084, 16498, 2, '【المجال الثالث: دراسة وضعيّة مشكلة (ستّ علامات)】\nالوضعيّة: نشر موقع إخباريّ خبرًا عن الحياة الخاصّة لإحدى الشخصيّات العامّة، معتمدًا على شائعات لم يتحقّق من صحّتها ومن دون تحديد مصدرها، واستعمل عبارات مبتذلة وصورًا تخدش الحياء العامّ طمعًا في زيادة عدد القرّاء. ولمّا طلبت الشخصيّة المعنيّة نشر ردّها، رفض الموقع ذلك بحجّة أنّ «الصحافيّ حرّ في أن يقول كلّ شيء»...\n\n٤- يرى البعض أنّ حرّيّة الصحافيّ تبيح له أن ينشر كلّ ما يصل إليه، فيما يرى آخرون أنّ حرّيّة الصحافيّ لا تنفصل عن مسؤوليّاته المهنيّة.\nفي ضوء المسألة أعلاه وبالاستناد إلى معلوماتك الشخصيّة، أبدِ رأيك في هذا الموضوع معلّلًا. (علامتان)', 1, '2026-10-01 02:31:25', '2026-10-01 02:31:25'),
(35085, 16499, 1, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nأوّلًا: صحّح الخطأ في كلّ من العبارات الواردة أدناه. (علامتان)\nأ- النوّاب يراقبون الجميع، والرأي العامّ والإعلام يراقبان أعمال الحكومة فقط.\nب- يحقّ للمرشّح الذي رُفض ترشيحه لعضويّة المجلس البلديّ أن يراجع المجلس الدستوريّ.\nج- يمثّل النائب ناخبي دائرته الانتخابيّة وحدهم.\nد- يحقّق النظام الأكثريّ عدالة في التمثيل في الدوائر الانتخابيّة الكبيرة.', 1, '2026-10-01 02:31:26', '2026-10-01 02:31:26'),
(35086, 16499, 2, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nأوّلًا: صحّح الخطأ في كلّ من العبارات الواردة أدناه. (علامتان)\nأ- النوّاب يراقبون الجميع، والرأي العامّ والإعلام يراقبان أعمال الحكومة فقط.\nب- يحقّ للمرشّح الذي رُفض ترشيحه لعضويّة المجلس البلديّ أن يراجع المجلس الدستوريّ.\nج- يمثّل النائب ناخبي دائرته الانتخابيّة وحدهم.\nد- يحقّق النظام الأكثريّ عدالة في التمثيل في الدوائر الانتخابيّة الكبيرة.', 1, '2026-10-01 02:31:26', '2026-10-01 02:31:26'),
(35087, 16500, 1, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nثانيًا: عيّن الدخيل في كلّ من المجموعتين التاليتين، معلّلًا إجابتك. (علامتان)\nأ- رجال الجنديّة – القضاة – الموظّفون من الفئتين الأولى والثانية – المرشّحون المقيّدون في قائمة الناخبين (فئات يشترط القانون استقالتها قبل الترشّح للانتخابات النيابيّة)\nب- الإعلان العالميّ لحقوق الإنسان – الاتفاقيّة الأوروبيّة لحقوق الإنسان – الميثاق الإفريقيّ لحقوق الإنسان والشعوب – شرعة الأخلاق المهنيّة في لبنان (مواثيق دوليّة تحمي حرّيّة الرأي والتعبير)', 1, '2026-10-01 02:31:26', '2026-10-01 02:31:26'),
(35088, 16500, 2, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nثانيًا: عيّن الدخيل في كلّ من المجموعتين التاليتين، معلّلًا إجابتك. (علامتان)\nأ- رجال الجنديّة – القضاة – الموظّفون من الفئتين الأولى والثانية – المرشّحون المقيّدون في قائمة الناخبين (فئات يشترط القانون استقالتها قبل الترشّح للانتخابات النيابيّة)\nب- الإعلان العالميّ لحقوق الإنسان – الاتفاقيّة الأوروبيّة لحقوق الإنسان – الميثاق الإفريقيّ لحقوق الإنسان والشعوب – شرعة الأخلاق المهنيّة في لبنان (مواثيق دوليّة تحمي حرّيّة الرأي والتعبير)', 1, '2026-10-01 02:31:26', '2026-10-01 02:31:26'),
(35089, 16501, 1, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nثالثًا: اربط ما يرد في العمود الأوّل بما يناسبه في العمود الثاني. (علامتان)\nالعمود الأوّل — أنظمة الانتخاب:\nأ- النظام الأكثريّ\nب- النظام النسبيّ\nج- النظام المختلط أو المركّب\nالعمود الثاني:\n١- يفوز المرشّح الذي ينال أكثر الأصوات بين المرشّحين المتنافسين.\n٢- تُمثَّل القوى السياسيّة بعدد من المقاعد يوازي عدد الأصوات التي نالتها لوائحها.\n٣- يُعتمد الحاصل الانتخابيّ، وتوزَّع المقاعد المتبقّية وفق قاعدة الكسر الأكبر أو المعدّل الأكبر.\n٤- أكثريّ في الدوائر الصغرى أو المتوسّطة، ونسبيّ في الدولة بوصفها دائرة انتخابيّة واحدة.', 1, '2026-10-01 02:31:27', '2026-10-01 02:31:27'),
(35090, 16501, 2, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nثالثًا: اربط ما يرد في العمود الأوّل بما يناسبه في العمود الثاني. (علامتان)\nالعمود الأوّل — أنظمة الانتخاب:\nأ- النظام الأكثريّ\nب- النظام النسبيّ\nج- النظام المختلط أو المركّب\nالعمود الثاني:\n١- يفوز المرشّح الذي ينال أكثر الأصوات بين المرشّحين المتنافسين.\n٢- تُمثَّل القوى السياسيّة بعدد من المقاعد يوازي عدد الأصوات التي نالتها لوائحها.\n٣- يُعتمد الحاصل الانتخابيّ، وتوزَّع المقاعد المتبقّية وفق قاعدة الكسر الأكبر أو المعدّل الأكبر.\n٤- أكثريّ في الدوائر الصغرى أو المتوسّطة، ونسبيّ في الدولة بوصفها دائرة انتخابيّة واحدة.', 1, '2026-10-01 02:31:27', '2026-10-01 02:31:27'),
(35091, 16502, 1, '【المجال الأوّل: على مستوى المعارف (ثماني علامات)】\nرابعًا: اختر الإجابة الصحيحة في كلّ ممّا يلي. (علامتان)\n١- حدّد قانون تنظيم مهنة المحاماة مدّة ولاية مجلس النقابة بـ:', 1, '2026-10-01 02:31:29', '2026-10-01 02:31:29'),
