(35610, 16761, 2, '【المطلب ج — الرأي】\nأجب عن المطلب (ج) في الموضوع نفسه الذي اخترته في المطلب (أ):\nالموضوع الأوّل («إذا انتقلت فئةٌ من فئات المجتمع إلى عملٍ لا تألفه، اختلّ النظام وطرأ الوهن على السلطة.»): ج- هل تعتقد أنّ تغيير الإنسان مهنته أكثر من مرّة في حياته أصبح ضرورة في سوق العمل اليوم؟ علّل إجابتك.\nالموضوع الثاني («إنّ الله جعل في جِبِلّة النفوس معرفةَ هويّته طبعًا، من غير تعلّمٍ ولا اكتساب.»): ج- هل تعتقد أنّ التربية في الأسرة والمدرسة ضروريّة لتنمية القيم الروحيّة عند الأطفال؟ علّل إجابتك.\nالموضوع الثالث (نصّ الغزالي): ج- هل تعتقد أنّ الخوارزميّات التي توجّه اختياراتنا على الإنترنت تحدّ من حرّية الإنسان؟ علّل إجابتك.', 1, '2026-10-01 02:32:59', '2026-10-01 02:32:59'),
(35611, 16762, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- صراع بين القيم المحلّيّة والقيم الوافدة من الخارج، يولّد تبايناً في المواقف داخل المجتمع.\nب- انتقال الفرد من مستوى اجتماعيّ اقتصاديّ إلى مستوى مماثل له من دون تغيّر في مستوى عيشه.\nج- حالة رضا مرتفع يشعر معها العامل بأنّ مؤسّسة العمل جزء من «النحن».', 1, '2026-10-01 02:33:00', '2026-10-01 02:33:00'),
(35612, 16762, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- صراع بين القيم المحلّيّة والقيم الوافدة من الخارج، يولّد تبايناً في المواقف داخل المجتمع.\nب- انتقال الفرد من مستوى اجتماعيّ اقتصاديّ إلى مستوى مماثل له من دون تغيّر في مستوى عيشه.\nج- حالة رضا مرتفع يشعر معها العامل بأنّ مؤسّسة العمل جزء من «النحن».', 1, '2026-10-01 02:33:00', '2026-10-01 02:33:00'),
(35613, 16763, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- أ- حدّد المعيار المميّز للتفاوت في كلّ من النظامين الآتيين: النظام الإقطاعيّ – النظام الطبقيّ الحديث. (٠٫٥٠ علامة)\nب- اذكر إمكانيّة الحراك في كلّ من النظامين الآتيين: نظام الرتب – النظام الطبقيّ الحديث. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:00', '2026-10-01 02:33:00'),
(35614, 16763, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- أ- حدّد المعيار المميّز للتفاوت في كلّ من النظامين الآتيين: النظام الإقطاعيّ – النظام الطبقيّ الحديث. (٠٫٥٠ علامة)\nب- اذكر إمكانيّة الحراك في كلّ من النظامين الآتيين: نظام الرتب – النظام الطبقيّ الحديث. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:00', '2026-10-01 02:33:00'),
(35615, 16764, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- من أشكال التفاوت الاجتماعيّ: التمييز الجنسيّ – التفاوت المناطقيّ – التفاوت العرقيّ – التفاوت المهنيّ – البُعد المجاليّ والمكانيّ. (٠٫٧٥ علامة)\nب- من عوامل الحراك الاجتماعيّ: التغيّر الاجتماعيّ الواسع النطاق – وسائل الاتّصال – تقسيم العمل – العامل الديمغرافيّ – المقارنة بين مهنة الأب ومهنة الابن. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35616, 16764, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- من أشكال التفاوت الاجتماعيّ: التمييز الجنسيّ – التفاوت المناطقيّ – التفاوت العرقيّ – التفاوت المهنيّ – البُعد المجاليّ والمكانيّ. (٠٫٧٥ علامة)\nب- من عوامل الحراك الاجتماعيّ: التغيّر الاجتماعيّ الواسع النطاق – وسائل الاتّصال – تقسيم العمل – العامل الديمغرافيّ – المقارنة بين مهنة الأب ومهنة الابن. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35617, 16765, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- بيّن العلاقة بين:\nأ- المواطنيّة ودولة العناية. (٠٫٧٥ علامة)\nب- التغيّر الجذريّ والحراك الاجتماعيّ. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35618, 16765, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- بيّن العلاقة بين:\nأ- المواطنيّة ودولة العناية. (٠٫٧٥ علامة)\nب- التغيّر الجذريّ والحراك الاجتماعيّ. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(35619, 16766, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- تعاني بعض المدارس الرسميّة في المناطق الطرفيّة ارتفاعاً في ظاهرة التسرّب المدرسيّ. طُلب إليك المشاركة في دراسة هذه الظاهرة.\nأ- لرصد هذه الظاهرة قمت بحضور عدد من الحصص في إحدى هذه المدارس من دون التدخّل في سير الحصّة. سمِّ تقنية البحث المناسبة لهذه الخطوة، ثمّ اذكر نوع التحليل الملائم لها. (٠٫٧٥ علامة)\nب- أعدّ استمارة موجّهة إلى عيّنة من أهالي التلامذة المتسرّبين. صغ سؤالاً ذا ثلاثة خيارات للتعرّف إلى أسباب التسرّب، ثمّ اذكر نوع السؤال المطروح. (١٫٢٥ علامة)\nج- أعدّ مقابلة موجّهة إلى مدير المدرسة. صغ سؤالاً حول كيفيّة الحدّ من هذه الظاهرة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35620, 16766, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- تعاني بعض المدارس الرسميّة في المناطق الطرفيّة ارتفاعاً في ظاهرة التسرّب المدرسيّ. طُلب إليك المشاركة في دراسة هذه الظاهرة.\nأ- لرصد هذه الظاهرة قمت بحضور عدد من الحصص في إحدى هذه المدارس من دون التدخّل في سير الحصّة. سمِّ تقنية البحث المناسبة لهذه الخطوة، ثمّ اذكر نوع التحليل الملائم لها. (٠٫٧٥ علامة)\nب- أعدّ استمارة موجّهة إلى عيّنة من أهالي التلامذة المتسرّبين. صغ سؤالاً ذا ثلاثة خيارات للتعرّف إلى أسباب التسرّب، ثمّ اذكر نوع السؤال المطروح. (١٫٢٥ علامة)\nج- أعدّ مقابلة موجّهة إلى مدير المدرسة. صغ سؤالاً حول كيفيّة الحدّ من هذه الظاهرة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35621, 16767, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\nالمجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)\n\nالمستند رقم ١: مواقع لا تُنال بالكفاءة وحدها\nلا يزال حضور النساء في مواقع القرار في لبنان محدوداً؛ فنسبة النساء في مجلس النوّاب أقلّ بكثير من نسبة الرجال، وتُمنح الأولويّة للرجل على حساب المرأة في الدخل والموقع والدور وحيازة السلطة. ويتّصل بذلك اختلاف بين المهن اليدويّة والمهن الفكريّة في الدخل والاحترام. ولا يعود هذا الاختلاف إلى عوامل بيولوجيّة موروثة، بل إلى الموقع الذي يشغله الفرد في المؤسّسة وفي المجتمع. فبعضهم يبلغ موقعه بنفسه، كالمدير والأستاذ، وبعضهم يناله من خلال ظروف ليست له سيطرة عليها، كابن المدير أو زوجة القاضي، وكلّ موقع يقترن بدور يؤدّيه صاحبه وبهيبة يحظى بها.\nالمصدر: مقال صحفيّ لبنانيّ (بتصرّف)\n\nالمستند رقم ٢: خدمات على قدر الحاجات\nتختلف المناطق اللبنانيّة في حجم الخدمات الصحّيّة والتربويّة والاجتماعيّة بين الأطراف والمراكز وبين الأرياف والمدن؛ فنسبة الأمّيّة مرتفعة في شمال لبنان بينما هي أقلّ في بيروت. ويقوم تقييم الناس في الدول النامية على الانتماء العائليّ والطائفيّ، وهو أساس خاطئ. ويرى باحثون أنّ من الأفضل تقديم خدمات بحسب حاجات المناطق لا خدمات متساوية لكلّ المناطق، لأنّ مناطق يزداد حرمانها وترتفع فيها نسبة الفقر.\nالمصدر: تقرير حول توزيع الخدمات العامّة (بتصرّف)\n\nالمستند رقم ٣: من القرية إلى المدينة\nيترك عدد كبير من أبناء القرى قراهم في اتّجاه المدن، هرباً من تدنّي مستوى المعيشة في الريف وطلباً للعمل والعلم. ويحمل النازحون إلى المدينة نمط عيشهم وعلاقاتهم، فتقوم داخلها مناطق أقرب إلى الريف في نمط العيش والعلاقات. وفي المقابل تزداد المدن اكتظاظاً وتتبدّل بنية السكّان فيها، فيما يبقى قطاع الزراعة خارج دائرة الاهتمام لصالح التجارة والخدمات.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nأجب عن الأسئلة التالية من خلال المستندات الواردة أعلاه ومعلوماتك المكتسبة:\n١- بالعودة إلى المستند الأوّل:\nأ- استخرج شكلين من أشكال التفاوت الاجتماعيّ. (٠٫٥٠ علامة)\nب- حدّد العامل الذي يعود إليه هذا التفاوت. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35622, 16767, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\nالمجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)\n\nالمستند رقم ١: مواقع لا تُنال بالكفاءة وحدها\nلا يزال حضور النساء في مواقع القرار في لبنان محدوداً؛ فنسبة النساء في مجلس النوّاب أقلّ بكثير من نسبة الرجال، وتُمنح الأولويّة للرجل على حساب المرأة في الدخل والموقع والدور وحيازة السلطة. ويتّصل بذلك اختلاف بين المهن اليدويّة والمهن الفكريّة في الدخل والاحترام. ولا يعود هذا الاختلاف إلى عوامل بيولوجيّة موروثة، بل إلى الموقع الذي يشغله الفرد في المؤسّسة وفي المجتمع. فبعضهم يبلغ موقعه بنفسه، كالمدير والأستاذ، وبعضهم يناله من خلال ظروف ليست له سيطرة عليها، كابن المدير أو زوجة القاضي، وكلّ موقع يقترن بدور يؤدّيه صاحبه وبهيبة يحظى بها.\nالمصدر: مقال صحفيّ لبنانيّ (بتصرّف)\n\nالمستند رقم ٢: خدمات على قدر الحاجات\nتختلف المناطق اللبنانيّة في حجم الخدمات الصحّيّة والتربويّة والاجتماعيّة بين الأطراف والمراكز وبين الأرياف والمدن؛ فنسبة الأمّيّة مرتفعة في شمال لبنان بينما هي أقلّ في بيروت. ويقوم تقييم الناس في الدول النامية على الانتماء العائليّ والطائفيّ، وهو أساس خاطئ. ويرى باحثون أنّ من الأفضل تقديم خدمات بحسب حاجات المناطق لا خدمات متساوية لكلّ المناطق، لأنّ مناطق يزداد حرمانها وترتفع فيها نسبة الفقر.\nالمصدر: تقرير حول توزيع الخدمات العامّة (بتصرّف)\n\nالمستند رقم ٣: من القرية إلى المدينة\nيترك عدد كبير من أبناء القرى قراهم في اتّجاه المدن، هرباً من تدنّي مستوى المعيشة في الريف وطلباً للعمل والعلم. ويحمل النازحون إلى المدينة نمط عيشهم وعلاقاتهم، فتقوم داخلها مناطق أقرب إلى الريف في نمط العيش والعلاقات. وفي المقابل تزداد المدن اكتظاظاً وتتبدّل بنية السكّان فيها، فيما يبقى قطاع الزراعة خارج دائرة الاهتمام لصالح التجارة والخدمات.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nأجب عن الأسئلة التالية من خلال المستندات الواردة أعلاه ومعلوماتك المكتسبة:\n١- بالعودة إلى المستند الأوّل:\nأ- استخرج شكلين من أشكال التفاوت الاجتماعيّ. (٠٫٥٠ علامة)\nب- حدّد العامل الذي يعود إليه هذا التفاوت. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35623, 16768, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٢- أ- سمِّ البُعد من أبعاد التفاوت الاجتماعيّ الذي يتناوله المستند الأوّل، ثمّ برّر إجابتك بدلالة منه. (٠٫٥٠ علامة)\nب- استخرج من المستند الأوّل نوعَي المركز، مع مثال على كلّ منهما. (علامة واحدة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35624, 16768, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٢- أ- سمِّ البُعد من أبعاد التفاوت الاجتماعيّ الذي يتناوله المستند الأوّل، ثمّ برّر إجابتك بدلالة منه. (٠٫٥٠ علامة)\nب- استخرج من المستند الأوّل نوعَي المركز، مع مثال على كلّ منهما. (علامة واحدة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35625, 16769, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٣- بالعودة إلى المستند الثاني:\nأ- قدّم دلالتين على التفاوت المناطقيّ. (علامة واحدة)\nب- حدّد الأساس الذي يجب أن يقوم عليه تقييم الناس. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35626, 16769, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٣- بالعودة إلى المستند الثاني:\nأ- قدّم دلالتين على التفاوت المناطقيّ. (علامة واحدة)\nب- حدّد الأساس الذي يجب أن يقوم عليه تقييم الناس. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:01', '2026-10-01 02:33:01'),
(35627, 16770, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٤- استنتج من المستند الثاني نوع الخدمات التي يقترح الباحثون أن تقدّمها الدولة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35628, 16770, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٤- استنتج من المستند الثاني نوع الخدمات التي يقترح الباحثون أن تقدّمها الدولة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35629, 16771, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٥- بالعودة إلى المستند الثالث:\nأ- سمِّ شكل الحراك الجغرافيّ الذي يتناوله المستند، ثمّ استخرج سببين له. (٠٫٧٥ علامة)\nب- سمِّ الظاهرة التي تدلّ عليها عبارة «تقوم داخلها مناطق أقرب إلى الريف في نمط العيش والعلاقات»، ثمّ بيّن موقف علم الاجتماع منها. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35630, 16771, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٥- بالعودة إلى المستند الثالث:\nأ- سمِّ شكل الحراك الجغرافيّ الذي يتناوله المستند، ثمّ استخرج سببين له. (٠٫٧٥ علامة)\nب- سمِّ الظاهرة التي تدلّ عليها عبارة «تقوم داخلها مناطق أقرب إلى الريف في نمط العيش والعلاقات»، ثمّ بيّن موقف علم الاجتماع منها. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35631, 16772, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٦- بيّن، بالعودة إلى المستندين الثاني والثالث، كيف يسهم التفاوت المناطقيّ في تفاقم النزوح من الأرياف إلى المدن. (علامة واحدة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35632, 16772, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٦- بيّن، بالعودة إلى المستندين الثاني والثالث، كيف يسهم التفاوت المناطقيّ في تفاقم النزوح من الأرياف إلى المدن. (علامة واحدة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35633, 16773, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٧- بيّن العلاقة بين المشكلات الواردة في المستندات الثلاثة من جهة، والاندماج الاجتماعيّ في لبنان من جهة أخرى. (علامة واحدة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35634, 16773, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٧- بيّن العلاقة بين المشكلات الواردة في المستندات الثلاثة من جهة، والاندماج الاجتماعيّ في لبنان من جهة أخرى. (علامة واحدة)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35635, 16774, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٨- يواجه المجتمع اللبنانيّ أشكالاً متعدّدة من التفاوت الاجتماعيّ. مستعيناً بالمستندات وبمعلوماتك المكتسبة، اكتب نصّاً: تحدّد فيه شكلين من أشكال التفاوت الواردة في المستندات، مسمّياً عاملين من عوامله، ثمّ اقترح حلّين للحدّ منه، مبيّناً النتيجة المتوخّاة. (٤ علامات)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35636, 16774, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٨- يواجه المجتمع اللبنانيّ أشكالاً متعدّدة من التفاوت الاجتماعيّ. مستعيناً بالمستندات وبمعلوماتك المكتسبة، اكتب نصّاً: تحدّد فيه شكلين من أشكال التفاوت الواردة في المستندات، مسمّياً عاملين من عوامله، ثمّ اقترح حلّين للحدّ منه، مبيّناً النتيجة المتوخّاة. (٤ علامات)', 1, '2026-10-01 02:33:02', '2026-10-01 02:33:02'),
(35637, 16775, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- مجموعة الآليّات التي يقوم بها الفرد ليجعل من نفسه أهلاً لعضويّة المجتمع.\nب- تحوّل عميق وسريع يحصل في بنية المجتمع السياسيّة والاقتصاديّة والاجتماعيّة والثقافيّة والقيميّة، ويسمّى عادةً الثورة.\nج- مجموعة من الأسئلة المرقّمة المغلقة تستهدف جمع بيانات ومعلومات من خلال آراء أفراد العيّنة.', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35638, 16775, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- مجموعة الآليّات التي يقوم بها الفرد ليجعل من نفسه أهلاً لعضويّة المجتمع.\nب- تحوّل عميق وسريع يحصل في بنية المجتمع السياسيّة والاقتصاديّة والاجتماعيّة والثقافيّة والقيميّة، ويسمّى عادةً الثورة.\nج- مجموعة من الأسئلة المرقّمة المغلقة تستهدف جمع بيانات ومعلومات من خلال آراء أفراد العيّنة.', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35639, 16776, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- أ- حدّد وظيفة دولة العناية التي تتمّ من خلال تشريع قانون العمل وقانون الأجور. (٠٫٥٠ علامة)\nب- اذكر سببين من أسباب نشأة الضمان الاجتماعيّ في لبنان. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35640, 16776, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- أ- حدّد وظيفة دولة العناية التي تتمّ من خلال تشريع قانون العمل وقانون الأجور. (٠٫٥٠ علامة)\nب- اذكر سببين من أسباب نشأة الضمان الاجتماعيّ في لبنان. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35641, 16777, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- من قوى التغيّر النظاميّة (المنظّمة): الأحزاب – النقابات – الجمعيّات – الفنّانون والأدباء والشعراء – فئات التكنوقراط. (٠٫٧٥ علامة)\nب- من أجزاء ثقافة الفرد: الشخصيّة القاعديّة – البيئة الاجتماعيّة أو الحيّز الثقافيّ – شخصيّة الفرد المستقلّة – ما يتلقّاه من الثقافات الأخرى عبر وسائل الإعلام – المركّب الثقافيّ. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35642, 16777, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- من قوى التغيّر النظاميّة (المنظّمة): الأحزاب – النقابات – الجمعيّات – الفنّانون والأدباء والشعراء – فئات التكنوقراط. (٠٫٧٥ علامة)\nب- من أجزاء ثقافة الفرد: الشخصيّة القاعديّة – البيئة الاجتماعيّة أو الحيّز الثقافيّ – شخصيّة الفرد المستقلّة – ما يتلقّاه من الثقافات الأخرى عبر وسائل الإعلام – المركّب الثقافيّ. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35643, 16778, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- بيّن العلاقة بين:\nأ- الحراك الاجتماعيّ والاندماج الاجتماعيّ. (٠٫٧٥ علامة)\nب- مؤسّسات البناء التي نقلت نمط العمارة الغربيّة وتغيّر القيم. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35644, 16778, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- بيّن العلاقة بين:\nأ- الحراك الاجتماعيّ والاندماج الاجتماعيّ. (٠٫٧٥ علامة)\nب- مؤسّسات البناء التي نقلت نمط العمارة الغربيّة وتغيّر القيم. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35645, 16779, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- تتزايد هجرة الشباب اللبنانيّ الحاملين شهادات جامعيّة إلى الخارج. طُلب إليك دراسة هذه الظاهرة.\nأ- للتعرّف إلى دوافع الهجرة بعمق، أجريت لقاءً مطوّلاً مع شابّ واحد ينوي الهجرة، وتركت له حرّيّة الإجابة. سمِّ تقنية البحث المعتمدة، ثمّ اذكر نوع التحليل الملائم للمعلومات التي جمعتها. (٠٫٧٥ علامة)\nب- أعدّ استمارة موجّهة إلى عيّنة من طلّاب الجامعة. صغ سؤالاً ذا ثلاثة خيارات للتعرّف إلى أسباب رغبتهم في الهجرة، ثمّ اذكر نوع السؤال المطروح. (١٫٢٥ علامة)\nج- اذكر خطوتين من خطوات المرحلة التحليليّة النهائيّة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35646, 16779, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- تتزايد هجرة الشباب اللبنانيّ الحاملين شهادات جامعيّة إلى الخارج. طُلب إليك دراسة هذه الظاهرة.\nأ- للتعرّف إلى دوافع الهجرة بعمق، أجريت لقاءً مطوّلاً مع شابّ واحد ينوي الهجرة، وتركت له حرّيّة الإجابة. سمِّ تقنية البحث المعتمدة، ثمّ اذكر نوع التحليل الملائم للمعلومات التي جمعتها. (٠٫٧٥ علامة)\nب- أعدّ استمارة موجّهة إلى عيّنة من طلّاب الجامعة. صغ سؤالاً ذا ثلاثة خيارات للتعرّف إلى أسباب رغبتهم في الهجرة، ثمّ اذكر نوع السؤال المطروح. (١٫٢٥ علامة)\nج- اذكر خطوتين من خطوات المرحلة التحليليّة النهائيّة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35647, 16780, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\nالمجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)\n\nالمستند رقم ١: دولة العناية بين الوظائف والأزمة\nالسياسة الاجتماعيّة مجموعة النظم والقرارات والتشريعات التي تقوم بها الدولة، وهي تختلف عن الرعاية الاجتماعيّة، ولا تنجح إلّا إذا قامت على نوع من الدولة هو دولة العناية. وتتولّى هذه الدولة ضبط التوازن عبر تشريع قانون العمل وقانون الأجور، ورصد اعتمادات التمويل للإدارات العامّة ولأجهزة الدفاع العسكريّ، وتقديم الخدمات الاجتماعيّة من خلال وزارتَي التعليم والصحّة. غير أنّ متابعين يسجّلون ضعف فعاليّتها في مكافحة التفاوت والفقر، إذ أدّى عدم حلّ مشكلتي البطالة والضمان إلى مزيد من الفقر والتفاوت.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nالمستند رقم ٢: الضمان الاجتماعيّ في لبنان\nنشأ الضمان الاجتماعيّ في لبنان مع ازدياد الهوّة بين الطبقات والفئات الاجتماعيّة، وفي إطار السياسة الإصلاحيّة الشاملة التي بدأ تطبيقها الرئيس فؤاد شهاب، وتأكيداً لالتزام لبنان بالإعلان العالميّ لحقوق الإنسان. ويشمل الخضوع الإلزاميّ أجراء الصناعة والتجارة والخدمات والمدرّسين وموظّفي الدولة وغيرهم، ويتوزّع على أربعة فروع، في حين يشمل الخضوع الاختياريّ العاملين لحسابهم وأرباب العمل والعمّال المستقلّين، ويقتصر على ثلاثة فروع ما عدا فرع تعويض نهاية الخدمة. ويتيح صندوق الضمان الاختياريّ لمن هم في عمر الشيخوخة ولا ضمان صحّة لديهم الإفادة من الخدمات، غير أنّه لا يؤمّن الخدمة إلّا لمن يستطيع دفع الاشتراك.\nالمصدر: تقرير اجتماعيّ (بتصرّف)\n\nالمستند رقم ٣: حين تراجعت الدولة\nساهمت الحرب اللبنانيّة في تفكّك الدولة والمجتمع، وشجّعت العودة إلى العصبيّات والعائلة والطائفة، وتسبّبت في تدهور مستوى المعيشة بعدما تقلّصت الموارد والمداخيل ودُمّرت البنى التحتيّة. فتراجع دور القطاع الحكوميّ وازداد الاهتمام بالمنظّمات غير الحكوميّة، ممّا ساعد على نقل الولاءات من ولاءات وطنيّة إلى ولاءات طائفيّة وعشائريّة. وما تزال مشكلات الفقر والسكن والتعليم قائمة، ومن نتائجها ظهور أحزمة البؤس والأبنية العشوائيّة، والتسرّب المدرسيّ وعمالة الأطفال.\nالمصدر: دراسة حول السياسة الاجتماعيّة في لبنان (بتصرّف)\n\nأجب عن الأسئلة التالية من خلال المستندات الواردة أعلاه ومعلوماتك المكتسبة:\n١- بالعودة إلى المستند الأوّل:\nأ- استخرج تعريف السياسة الاجتماعيّة. (٠٫٥٠ علامة)\nب- سمِّ نوع الدولة التي تقوم عليها السياسة الاجتماعيّة الناجحة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35648, 16780, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\nالمجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)\n\nالمستند رقم ١: دولة العناية بين الوظائف والأزمة\nالسياسة الاجتماعيّة مجموعة النظم والقرارات والتشريعات التي تقوم بها الدولة، وهي تختلف عن الرعاية الاجتماعيّة، ولا تنجح إلّا إذا قامت على نوع من الدولة هو دولة العناية. وتتولّى هذه الدولة ضبط التوازن عبر تشريع قانون العمل وقانون الأجور، ورصد اعتمادات التمويل للإدارات العامّة ولأجهزة الدفاع العسكريّ، وتقديم الخدمات الاجتماعيّة من خلال وزارتَي التعليم والصحّة. غير أنّ متابعين يسجّلون ضعف فعاليّتها في مكافحة التفاوت والفقر، إذ أدّى عدم حلّ مشكلتي البطالة والضمان إلى مزيد من الفقر والتفاوت.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nالمستند رقم ٢: الضمان الاجتماعيّ في لبنان\nنشأ الضمان الاجتماعيّ في لبنان مع ازدياد الهوّة بين الطبقات والفئات الاجتماعيّة، وفي إطار السياسة الإصلاحيّة الشاملة التي بدأ تطبيقها الرئيس فؤاد شهاب، وتأكيداً لالتزام لبنان بالإعلان العالميّ لحقوق الإنسان. ويشمل الخضوع الإلزاميّ أجراء الصناعة والتجارة والخدمات والمدرّسين وموظّفي الدولة وغيرهم، ويتوزّع على أربعة فروع، في حين يشمل الخضوع الاختياريّ العاملين لحسابهم وأرباب العمل والعمّال المستقلّين، ويقتصر على ثلاثة فروع ما عدا فرع تعويض نهاية الخدمة. ويتيح صندوق الضمان الاختياريّ لمن هم في عمر الشيخوخة ولا ضمان صحّة لديهم الإفادة من الخدمات، غير أنّه لا يؤمّن الخدمة إلّا لمن يستطيع دفع الاشتراك.\nالمصدر: تقرير اجتماعيّ (بتصرّف)\n\nالمستند رقم ٣: حين تراجعت الدولة\nساهمت الحرب اللبنانيّة في تفكّك الدولة والمجتمع، وشجّعت العودة إلى العصبيّات والعائلة والطائفة، وتسبّبت في تدهور مستوى المعيشة بعدما تقلّصت الموارد والمداخيل ودُمّرت البنى التحتيّة. فتراجع دور القطاع الحكوميّ وازداد الاهتمام بالمنظّمات غير الحكوميّة، ممّا ساعد على نقل الولاءات من ولاءات وطنيّة إلى ولاءات طائفيّة وعشائريّة. وما تزال مشكلات الفقر والسكن والتعليم قائمة، ومن نتائجها ظهور أحزمة البؤس والأبنية العشوائيّة، والتسرّب المدرسيّ وعمالة الأطفال.\nالمصدر: دراسة حول السياسة الاجتماعيّة في لبنان (بتصرّف)\n\nأجب عن الأسئلة التالية من خلال المستندات الواردة أعلاه ومعلوماتك المكتسبة:\n١- بالعودة إلى المستند الأوّل:\nأ- استخرج تعريف السياسة الاجتماعيّة. (٠٫٥٠ علامة)\nب- سمِّ نوع الدولة التي تقوم عليها السياسة الاجتماعيّة الناجحة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35649, 16781, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٢- أ- استخرج من المستند الأوّل وظيفتين من وظائف دولة العناية، مبيّناً كيف تتمّ كلّ منهما. (علامة واحدة)\nب- حدّد من المستند نفسه المظهر الذي تتجلّى فيه أزمة دولة العناية وحدودها. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35650, 16781, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٢- أ- استخرج من المستند الأوّل وظيفتين من وظائف دولة العناية، مبيّناً كيف تتمّ كلّ منهما. (علامة واحدة)\nب- حدّد من المستند نفسه المظهر الذي تتجلّى فيه أزمة دولة العناية وحدودها. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35651, 16782, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٣- بالعودة إلى المستند الثاني:\nأ- استخرج ثلاثة أسباب لنشأة الضمان الاجتماعيّ في لبنان. (٠٫٧٥ علامة)\nب- ميّز بين الخضوع الإلزاميّ والخضوع الاختياريّ من حيث الفئات المشمولة وعدد الفروع. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35652, 16782, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٣- بالعودة إلى المستند الثاني:\nأ- استخرج ثلاثة أسباب لنشأة الضمان الاجتماعيّ في لبنان. (٠٫٧٥ علامة)\nب- ميّز بين الخضوع الإلزاميّ والخضوع الاختياريّ من حيث الفئات المشمولة وعدد الفروع. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35653, 16783, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٤- قدّم من المستند الثاني دلالة على أنّ صندوق الضمان الاختياريّ لا يحقّق مبدأ الحماية الاجتماعيّة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35654, 16783, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٤- قدّم من المستند الثاني دلالة على أنّ صندوق الضمان الاختياريّ لا يحقّق مبدأ الحماية الاجتماعيّة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35655, 16784, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٥- بالعودة إلى المستند الثالث:\nأ- استخرج ثلاثاً من انعكاسات الحرب اللبنانيّة على الدولة والمجتمع. (٠٫٧٥ علامة)\nب- يشير المستند إلى انتقال في الولاءات يعاكس أحد أهداف الضمان الاجتماعيّ. سمِّ هذا الهدف، ثمّ برّر إجابتك بدلالة من المستند. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35656, 16784, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٥- بالعودة إلى المستند الثالث:\nأ- استخرج ثلاثاً من انعكاسات الحرب اللبنانيّة على الدولة والمجتمع. (٠٫٧٥ علامة)\nب- يشير المستند إلى انتقال في الولاءات يعاكس أحد أهداف الضمان الاجتماعيّ. سمِّ هذا الهدف، ثمّ برّر إجابتك بدلالة من المستند. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:03', '2026-10-01 02:33:03'),
(35657, 16785, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٦- استخرج من المستند الثالث مشكلتين اجتماعيّتين، ثمّ قدّم من معلوماتك المكتسبة حلّاً لكلّ منهما. (علامة واحدة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35658, 16785, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٦- استخرج من المستند الثالث مشكلتين اجتماعيّتين، ثمّ قدّم من معلوماتك المكتسبة حلّاً لكلّ منهما. (علامة واحدة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35659, 16786, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٧- بيّن العلاقة بين دولة العناية من جهة، والتفاوت الاجتماعيّ من جهة أخرى. (علامة واحدة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35660, 16786, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٧- بيّن العلاقة بين دولة العناية من جهة، والتفاوت الاجتماعيّ من جهة أخرى. (علامة واحدة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35661, 16787, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٨- تعكس المستندات واقع السياسة الاجتماعيّة في لبنان. مستعيناً بالمستندات وبمعلوماتك المكتسبة، اكتب نصّاً: تحدّد فيه مشكلتين تعترضان السياسة الاجتماعيّة في لبنان، مسمّياً مرتكزَي الضمان الاجتماعيّ، ثمّ اقترح حلّين لتفعيل شبكة الأمان الاجتماعيّ، مبيّناً النتيجة المتوخّاة. (٤ علامات)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35662, 16787, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٨- تعكس المستندات واقع السياسة الاجتماعيّة في لبنان. مستعيناً بالمستندات وبمعلوماتك المكتسبة، اكتب نصّاً: تحدّد فيه مشكلتين تعترضان السياسة الاجتماعيّة في لبنان، مسمّياً مرتكزَي الضمان الاجتماعيّ، ثمّ اقترح حلّين لتفعيل شبكة الأمان الاجتماعيّ، مبيّناً النتيجة المتوخّاة. (٤ علامات)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35663, 16788, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- موقع الفرد في الجماعة التي ينتمي إليها.\nب- هجرة داخليّة ينتقل فيها السكّان من الأرياف إلى المدن.\nج- مشاركة الناس في صنع السياسات الاجتماعيّة، ولا ديمقراطيّة من دونها.', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35664, 16788, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- موقع الفرد في الجماعة التي ينتمي إليها.\nب- هجرة داخليّة ينتقل فيها السكّان من الأرياف إلى المدن.\nج- مشاركة الناس في صنع السياسات الاجتماعيّة، ولا ديمقراطيّة من دونها.', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35665, 16789, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- برّر بفكرة صحّة كلّ من الجملتين الآتيتين:\nأ- يُعدّ الدخول في الضمان الاجتماعيّ شرطاً من الشروط الاقتصاديّة والاجتماعيّة للاندماج. (٠٫٥٠ علامة)\nب- تُعدّ الشهادة المدرسيّة رأسمالاً قابلاً للتحوّل إلى رأسمال اقتصاديّ. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35666, 16789, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- برّر بفكرة صحّة كلّ من الجملتين الآتيتين:\nأ- يُعدّ الدخول في الضمان الاجتماعيّ شرطاً من الشروط الاقتصاديّة والاجتماعيّة للاندماج. (٠٫٥٠ علامة)\nب- تُعدّ الشهادة المدرسيّة رأسمالاً قابلاً للتحوّل إلى رأسمال اقتصاديّ. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35667, 16790, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- من مؤسّسات نقل القيم من الخارج: وسائل الاتّصال – المقاهي والمسارح ودور السينما – المدارس والجامعات الأجنبيّة – مؤسّسات وشركات البناء – العائلة. (٠٫٧٥ علامة)\nب- من خطوات المرحلة التحليليّة النهائيّة: جدولة النتائج إحصائيّاً – تصنيف المعلومات – تحليلها وتفسيرها – كتابة تقرير عن نتائج البحث – صياغة الفرضيّات. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35668, 16790, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- من مؤسّسات نقل القيم من الخارج: وسائل الاتّصال – المقاهي والمسارح ودور السينما – المدارس والجامعات الأجنبيّة – مؤسّسات وشركات البناء – العائلة. (٠٫٧٥ علامة)\nب- من خطوات المرحلة التحليليّة النهائيّة: جدولة النتائج إحصائيّاً – تصنيف المعلومات – تحليلها وتفسيرها – كتابة تقرير عن نتائج البحث – صياغة الفرضيّات. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35669, 16791, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- بيّن العلاقة بين:\nأ- الانفتاح على الثقافات الأخرى واختلاف مواقع الأفراد في المجتمع. (٠٫٧٥ علامة)\nب- الاصطفاء العاديّ والتماهي. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35670, 16791, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- بيّن العلاقة بين:\nأ- الانفتاح على الثقافات الأخرى واختلاف مواقع الأفراد في المجتمع. (٠٫٧٥ علامة)\nب- الاصطفاء العاديّ والتماهي. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35671, 16792, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- يشكو أهالي إحدى البلدات اللبنانيّة من ضعف خدمات السكن والتعليم والصحّة، أي من ضعف التنمية البشريّة. طُلب إليك دراسة هذه الظاهرة.\nأ- للتعرّف إلى الأنشطة المعتادة العامّة في حياة الأهالي، راقبتهم عن قرب من دون التدخّل في حياتهم. سمِّ تقنية البحث المعتمدة، ثمّ حدّد نوعها. (٠٫٧٥ علامة)\nب- أعدّ استمارة موجّهة إلى عيّنة من الأهالي. صغ سؤالاً ذا ثلاثة خيارات حول أولويّات التنمية في البلدة، ثمّ اذكر نوع السؤال المطروح. (١٫٢٥ علامة)\nج- أعدّ مقابلة موجّهة إلى رئيس البلديّة. صغ سؤالاً حول مشاريع البلديّة في هذا المجال. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35672, 16792, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- يشكو أهالي إحدى البلدات اللبنانيّة من ضعف خدمات السكن والتعليم والصحّة، أي من ضعف التنمية البشريّة. طُلب إليك دراسة هذه الظاهرة.\nأ- للتعرّف إلى الأنشطة المعتادة العامّة في حياة الأهالي، راقبتهم عن قرب من دون التدخّل في حياتهم. سمِّ تقنية البحث المعتمدة، ثمّ حدّد نوعها. (٠٫٧٥ علامة)\nب- أعدّ استمارة موجّهة إلى عيّنة من الأهالي. صغ سؤالاً ذا ثلاثة خيارات حول أولويّات التنمية في البلدة، ثمّ اذكر نوع السؤال المطروح. (١٫٢٥ علامة)\nج- أعدّ مقابلة موجّهة إلى رئيس البلديّة. صغ سؤالاً حول مشاريع البلديّة في هذا المجال. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35673, 16793, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\nالمجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)\n\nالمستند رقم ١: مهنة الأب ومهنة الابن\nاعتمد فريق من الباحثين، في دراسة شملت عدداً من الأسر اللبنانيّة، المقارنة بين مهنة الأب ومهنة الابن: فإذا لم تتغيّر مهنة الابن عن مهنة أبيه فلا حراك، وإذا تغيّرت فقد حصل حراك. ففي أسرة أولى بقي الابن فلّاحاً كأبيه. وفي أسرة ثانية انتقل ابن عامل الميكانيك إلى صاحب محلّ درّاجات فارتفع مستوى عيشه. وفي أسرة ثالثة اضطرّ ابن ربّ عمل إلى العمل عاملاً مأجوراً فتراجع مستوى عيشه. أمّا الأب في الأسرة الرابعة فانتقل في منتصف حياته المهنيّة من العمل في مصنع نسيج إلى العمل في مصنع أحذية من دون أن يتغيّر مستوى عيشه.\nالمصدر: دراسة ميدانيّة (بتصرّف)\n\nالمستند رقم ٢: ما الذي يفتح السلّم وما الذي يقفله؟\nيرى الباحثون أنّ انتشار وسائل الاتّصال بين الناس يشجّع على الحراك، فقد ساعد الهاتف والإنترنت على إيجاد فرص عمل جديدة، وأنّ التغيّر الاجتماعيّ الواسع النطاق، جذريّاً كان أم طبيعيّاً كالتقدّم العلميّ والتقنيّ، يسهّل الانتقال من مستوى إلى آخر. غير أنّ تقسيم العمل حين يبلغ تنوّع التخصّص فيه درجة معقّدة يجعل الانتقال من مهنة إلى أخرى صعباً.\nالمصدر: تقرير اجتماعيّ (بتصرّف)\n\nالمستند رقم ٣: سلّم في الداخل أم في الخارج؟\nيغادر كثير من الشباب اللبنانيّ البلاد بسبب عدم توفّر فرص العمل وشروط الاندماج الاجتماعيّ، فيخسر المجتمع الأدمغة وذوي الكفاءات واليد العاملة الماهرة، وتصل في المقابل عائدات ماليّة من المغتربين. ويلاحظ الباحثون أنّ الحراك يزداد في المجتمع الأكثر ديمقراطيّة ومرونة، وفي المجتمع الذي يقيّم الناس على أساس الكفاءة والمهارة بعيداً عن الانتماءات الأوّليّة، وحيث تُطبَّق العدالة والمساواة بين الأفراد.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nأجب عن الأسئلة التالية من خلال المستندات الواردة أعلاه ومعلوماتك المكتسبة:\n١- بالعودة إلى المستند الأوّل:\nأ- استخرج الوسيلة المعتمدة في قياس الحراك الاجتماعيّ. (٠٫٥٠ علامة)\nب- حدّد الحالة التي يُستنتج منها انعدام الحراك. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35674, 16793, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\nالمجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)\n\nالمستند رقم ١: مهنة الأب ومهنة الابن\nاعتمد فريق من الباحثين، في دراسة شملت عدداً من الأسر اللبنانيّة، المقارنة بين مهنة الأب ومهنة الابن: فإذا لم تتغيّر مهنة الابن عن مهنة أبيه فلا حراك، وإذا تغيّرت فقد حصل حراك. ففي أسرة أولى بقي الابن فلّاحاً كأبيه. وفي أسرة ثانية انتقل ابن عامل الميكانيك إلى صاحب محلّ درّاجات فارتفع مستوى عيشه. وفي أسرة ثالثة اضطرّ ابن ربّ عمل إلى العمل عاملاً مأجوراً فتراجع مستوى عيشه. أمّا الأب في الأسرة الرابعة فانتقل في منتصف حياته المهنيّة من العمل في مصنع نسيج إلى العمل في مصنع أحذية من دون أن يتغيّر مستوى عيشه.\nالمصدر: دراسة ميدانيّة (بتصرّف)\n\nالمستند رقم ٢: ما الذي يفتح السلّم وما الذي يقفله؟\nيرى الباحثون أنّ انتشار وسائل الاتّصال بين الناس يشجّع على الحراك، فقد ساعد الهاتف والإنترنت على إيجاد فرص عمل جديدة، وأنّ التغيّر الاجتماعيّ الواسع النطاق، جذريّاً كان أم طبيعيّاً كالتقدّم العلميّ والتقنيّ، يسهّل الانتقال من مستوى إلى آخر. غير أنّ تقسيم العمل حين يبلغ تنوّع التخصّص فيه درجة معقّدة يجعل الانتقال من مهنة إلى أخرى صعباً.\nالمصدر: تقرير اجتماعيّ (بتصرّف)\n\nالمستند رقم ٣: سلّم في الداخل أم في الخارج؟\nيغادر كثير من الشباب اللبنانيّ البلاد بسبب عدم توفّر فرص العمل وشروط الاندماج الاجتماعيّ، فيخسر المجتمع الأدمغة وذوي الكفاءات واليد العاملة الماهرة، وتصل في المقابل عائدات ماليّة من المغتربين. ويلاحظ الباحثون أنّ الحراك يزداد في المجتمع الأكثر ديمقراطيّة ومرونة، وفي المجتمع الذي يقيّم الناس على أساس الكفاءة والمهارة بعيداً عن الانتماءات الأوّليّة، وحيث تُطبَّق العدالة والمساواة بين الأفراد.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nأجب عن الأسئلة التالية من خلال المستندات الواردة أعلاه ومعلوماتك المكتسبة:\n١- بالعودة إلى المستند الأوّل:\nأ- استخرج الوسيلة المعتمدة في قياس الحراك الاجتماعيّ. (٠٫٥٠ علامة)\nب- حدّد الحالة التي يُستنتج منها انعدام الحراك. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35675, 16794, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٢- سمِّ شكل الحراك الذي تدلّ عليه كلّ من الحالات الآتية الواردة في المستند الأوّل: (١٫٥٠ علامة)\nأ- انتقال ابن عامل الميكانيك إلى صاحب محلّ درّاجات.\nب- عمل ابن ربّ العمل عاملاً مأجوراً.\nج- انتقال الأب من مصنع نسيج إلى مصنع أحذية في منتصف حياته المهنيّة.', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35676, 16794, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٢- سمِّ شكل الحراك الذي تدلّ عليه كلّ من الحالات الآتية الواردة في المستند الأوّل: (١٫٥٠ علامة)\nأ- انتقال ابن عامل الميكانيك إلى صاحب محلّ درّاجات.\nب- عمل ابن ربّ العمل عاملاً مأجوراً.\nج- انتقال الأب من مصنع نسيج إلى مصنع أحذية في منتصف حياته المهنيّة.', 1, '2026-10-01 02:33:04', '2026-10-01 02:33:04'),
(35677, 16795, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٣- بالعودة إلى المستند الثاني:\nأ- استخرج عاملين يسهّلان الحراك الاجتماعيّ. (٠٫٥٠ علامة)\nب- استخرج العامل الذي يعيق الحراك، مبرّراً إجابتك. (علامة واحدة)', 1, '2026-10-01 02:33:05', '2026-10-01 02:33:05'),
(35678, 16795, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٣- بالعودة إلى المستند الثاني:\nأ- استخرج عاملين يسهّلان الحراك الاجتماعيّ. (٠٫٥٠ علامة)\nب- استخرج العامل الذي يعيق الحراك، مبرّراً إجابتك. (علامة واحدة)', 1, '2026-10-01 02:33:05', '2026-10-01 02:33:05'),
