(35711, 16812, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٧- بيّن العلاقة بين ما تعرضه المستندات من جهة، واختبار القيم في المجتمع اللبنانيّ من جهة أخرى. (علامة واحدة)', 1, '2026-10-01 02:33:06', '2026-10-01 02:33:06'),
(35712, 16812, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٧- بيّن العلاقة بين ما تعرضه المستندات من جهة، واختبار القيم في المجتمع اللبنانيّ من جهة أخرى. (علامة واحدة)', 1, '2026-10-01 02:33:06', '2026-10-01 02:33:06'),
(35713, 16813, 1, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٨- تعكس المستندات تحدّيات تواجه الثقافة في المجتمع اللبنانيّ. مستعيناً بالمستندات وبمعلوماتك المكتسبة، اكتب نصّاً: تحدّد فيه تحدّيين من هذه التحدّيات، مسمّياً وظيفتين للشخصيّة القاعديّة، ثمّ اقترح حلّين ليبقى التفاعل الثقافيّ تبادلاً لا فرضاً، مبيّناً النتيجة المتوخّاة. (٤ علامات)', 1, '2026-10-01 02:33:06', '2026-10-01 02:33:06'),
(35714, 16813, 2, '【المجموعة الثانية: تحليل مستندات اجتماعيّة (١٢ علامة)】\n٨- تعكس المستندات تحدّيات تواجه الثقافة في المجتمع اللبنانيّ. مستعيناً بالمستندات وبمعلوماتك المكتسبة، اكتب نصّاً: تحدّد فيه تحدّيين من هذه التحدّيات، مسمّياً وظيفتين للشخصيّة القاعديّة، ثمّ اقترح حلّين ليبقى التفاعل الثقافيّ تبادلاً لا فرضاً، مبيّناً النتيجة المتوخّاة. (٤ علامات)', 1, '2026-10-01 02:33:06', '2026-10-01 02:33:06'),
(35715, 16814, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- خريطة العلاقات الاجتماعيّة داخل الجماعة، وهي أداة وصفيّة.\nب- الدولة الضامنة للعدالة الاجتماعيّة، ويدلّ وجودها على التقدّم والرقيّ.\nج- صراع بين ثقافة الأقوى وثقافة الأضعف، تكمن خطورته في سعي الثقافة الأقوى إلى إلغاء الأضعف أو وضعها في حالة التبعيّة.', 1, '2026-10-01 02:33:07', '2026-10-01 02:33:07'),
(35716, 16814, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- خريطة العلاقات الاجتماعيّة داخل الجماعة، وهي أداة وصفيّة.\nب- الدولة الضامنة للعدالة الاجتماعيّة، ويدلّ وجودها على التقدّم والرقيّ.\nج- صراع بين ثقافة الأقوى وثقافة الأضعف، تكمن خطورته في سعي الثقافة الأقوى إلى إلغاء الأضعف أو وضعها في حالة التبعيّة.', 1, '2026-10-01 02:33:07', '2026-10-01 02:33:07'),
(35717, 16815, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- ميّز بفارق واحد بين:\nأ- جماعة الانتماء وجماعة المرجع. (٠٫٥٠ علامة)\nب- التفسير الوظيفيّ والتفسير الماركسيّ للتفاوت الاجتماعيّ. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(35718, 16815, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- ميّز بفارق واحد بين:\nأ- جماعة الانتماء وجماعة المرجع. (٠٫٥٠ علامة)\nب- التفسير الوظيفيّ والتفسير الماركسيّ للتفاوت الاجتماعيّ. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35719, 16816, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- فرع المرض والأمومة – فرع التعويضات العائليّة – فرع تعويض نهاية الخدمة – فرع طوارئ العمل والأمراض المهنيّة – فرع القروض السكنيّة. (٠٫٧٥ علامة)\nب- الطبقة المسيطرة في ترسيم بورديو: الصناعيّون – كبار التجّار – أصحاب المهن الحرّة – المزارعون. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35720, 16816, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج العنصر غير المناسب في كلّ من المجموعتين الآتيتين، ثمّ برّر إجابتك:\nأ- فرع المرض والأمومة – فرع التعويضات العائليّة – فرع تعويض نهاية الخدمة – فرع طوارئ العمل والأمراض المهنيّة – فرع القروض السكنيّة. (٠٫٧٥ علامة)\nب- الطبقة المسيطرة في ترسيم بورديو: الصناعيّون – كبار التجّار – أصحاب المهن الحرّة – المزارعون. (٠٫٧٥ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35721, 16817, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- صنّف الحالات الآتية ضمن مجموعتين متجانستين، ثمّ برّر إجابتك: (١٫٥٠ علامة)\nعامل نسيج أصبح عاملاً في مصنع أحذية – فلّاح تحوّل إلى صاحب أرض – ربّ عمل أصبح عاملاً مأجوراً – موظّف انتقل إلى وظيفة مماثلة لوظيفته.', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35722, 16817, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- صنّف الحالات الآتية ضمن مجموعتين متجانستين، ثمّ برّر إجابتك: (١٫٥٠ علامة)\nعامل نسيج أصبح عاملاً في مصنع أحذية – فلّاح تحوّل إلى صاحب أرض – ربّ عمل أصبح عاملاً مأجوراً – موظّف انتقل إلى وظيفة مماثلة لوظيفته.', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35723, 16818, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- طُلب إليك إجراء دراسة حول ضعف استفادة العاملين لحسابهم من تقديمات الضمان الاجتماعيّ في إحدى المناطق اللبنانيّة.\nأ- اذكر تقنية البحث التي سوف تعتمدها لجمع المعلومات من عيّنة واسعة من هؤلاء العاملين، ثمّ برّر إجابتك. (٠٫٧٥ علامة)\nب- صغ سؤالاً ذا ثلاثة خيارات موجّهاً إلى أفراد العيّنة، ثمّ اذكر نوع التحليل الذي يناسب أجوبتهم بعد جدولتها. (١٫٢٥ علامة)\nج- اذكر خطوتين من خطوات المرحلة النظريّة (ما قبل الميدان) يقوم بهما الباحث قبل النزول إلى الميدان. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35724, 16818, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- طُلب إليك إجراء دراسة حول ضعف استفادة العاملين لحسابهم من تقديمات الضمان الاجتماعيّ في إحدى المناطق اللبنانيّة.\nأ- اذكر تقنية البحث التي سوف تعتمدها لجمع المعلومات من عيّنة واسعة من هؤلاء العاملين، ثمّ برّر إجابتك. (٠٫٧٥ علامة)\nب- صغ سؤالاً ذا ثلاثة خيارات موجّهاً إلى أفراد العيّنة، ثمّ اذكر نوع التحليل الذي يناسب أجوبتهم بعد جدولتها. (١٫٢٥ علامة)\nج- اذكر خطوتين من خطوات المرحلة النظريّة (ما قبل الميدان) يقوم بهما الباحث قبل النزول إلى الميدان. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35725, 16819, 1, '【المجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)】\nالمجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)\n\nمستند:\nيشكو شباب لبنانيّون من أنّ العمل الذي يجدونه لا يقوم على راتب محدّد ودوام محدّد، وأنّ بعضهم يُصرف من دون إنذار ولا يدخل الضمان الاجتماعيّ، ولا تمثّلهم نقابات تدافع عن مصالحهم. ويشكو آخرون من مدرسة رسميّة تنقصها التجهيزات والمختبرات والكادر التعليميّ، ومن مناهج جامعيّة لا تتوافق مع طلب المنشآت للعمل، ومن توظيف يقوم على الانتماء العائليّ والطائفيّ لا على الكفاءة والمهارة. وفي المقابل يصون القانون حرّيّة الإعلام والتعبير والنشر وحرّيّة الترشّح والانتخاب في مجلس النوّاب ومجلس البلديّة، غير أنّ إقبال الشباب على المشاركة يبقى ضعيفاً، فيتراجع شعورهم بأنّهم جزء من «النحن».\nالمصدر: دراسة اجتماعيّة حول الشباب والمشاركة (بتصرّف)\n\nيواجه الشباب في المجتمع اللبنانيّ صعوبات تعيق انتقالهم من حالة الصراع إلى حالة العيش معاً. مستعيناً بالمستند وبمعلوماتك المكتسبة، عالج هذا الموضوع مركّزاً على النقاط الآتية:\n• الاندماج الاجتماعيّ والتكيّف: تعريف كلّ منهما والعلاقة بينهما.\n• واقع الشروط الثلاثة للاندماج في المجتمع اللبنانيّ (الاقتصاديّة والاجتماعيّة، التربويّة والثقافيّة، السياسيّة).\n• تقييم دور الدولة اللبنانيّة في تأمين شروط الاندماج.\n• ثلاثة اقتراحات لتعزيز اندماج الشباب في المجتمع اللبنانيّ.', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35726, 16819, 2, '【المجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)】\nالمجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)\n\nمستند:\nيشكو شباب لبنانيّون من أنّ العمل الذي يجدونه لا يقوم على راتب محدّد ودوام محدّد، وأنّ بعضهم يُصرف من دون إنذار ولا يدخل الضمان الاجتماعيّ، ولا تمثّلهم نقابات تدافع عن مصالحهم. ويشكو آخرون من مدرسة رسميّة تنقصها التجهيزات والمختبرات والكادر التعليميّ، ومن مناهج جامعيّة لا تتوافق مع طلب المنشآت للعمل، ومن توظيف يقوم على الانتماء العائليّ والطائفيّ لا على الكفاءة والمهارة. وفي المقابل يصون القانون حرّيّة الإعلام والتعبير والنشر وحرّيّة الترشّح والانتخاب في مجلس النوّاب ومجلس البلديّة، غير أنّ إقبال الشباب على المشاركة يبقى ضعيفاً، فيتراجع شعورهم بأنّهم جزء من «النحن».\nالمصدر: دراسة اجتماعيّة حول الشباب والمشاركة (بتصرّف)\n\nيواجه الشباب في المجتمع اللبنانيّ صعوبات تعيق انتقالهم من حالة الصراع إلى حالة العيش معاً. مستعيناً بالمستند وبمعلوماتك المكتسبة، عالج هذا الموضوع مركّزاً على النقاط الآتية:\n• الاندماج الاجتماعيّ والتكيّف: تعريف كلّ منهما والعلاقة بينهما.\n• واقع الشروط الثلاثة للاندماج في المجتمع اللبنانيّ (الاقتصاديّة والاجتماعيّة، التربويّة والثقافيّة، السياسيّة).\n• تقييم دور الدولة اللبنانيّة في تأمين شروط الاندماج.\n• ثلاثة اقتراحات لتعزيز اندماج الشباب في المجتمع اللبنانيّ.', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35727, 16820, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- عمليّة يُرتَّب بها الأفراد والجماعات ضمن سلسلة متدرّجة من المراكز.\nب- الاختلاف بين المناطق في حجم الخدمات الصحّيّة والتربويّة والاجتماعيّة بين الأطراف والمراكز.\nج- مجموعة من الأشخاص النافذين داخل كلّ جماعة، يتألّفون من وجهاء العائلات والقرى وممثّلي الطوائف الروحيّين والسياسيّين.', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35728, 16820, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- عمليّة يُرتَّب بها الأفراد والجماعات ضمن سلسلة متدرّجة من المراكز.\nب- الاختلاف بين المناطق في حجم الخدمات الصحّيّة والتربويّة والاجتماعيّة بين الأطراف والمراكز.\nج- مجموعة من الأشخاص النافذين داخل كلّ جماعة، يتألّفون من وجهاء العائلات والقرى وممثّلي الطوائف الروحيّين والسياسيّين.', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35729, 16821, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- ميّز بفارق واحد بين:\nأ- التغيّر الطبيعيّ والتغيّر الجذريّ. (٠٫٥٠ علامة)\nب- الملاحظة المقنّنة والملاحظة بالمشاركة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35730, 16821, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- ميّز بفارق واحد بين:\nأ- التغيّر الطبيعيّ والتغيّر الجذريّ. (٠٫٥٠ علامة)\nب- الملاحظة المقنّنة والملاحظة بالمشاركة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35731, 16822, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج الإجابة الصحيحة في كلّ من المجموعات الآتية:\nأ- خاصّيّة القيم التي تعني أنّها تتغيّر من مجتمع إلى آخر ومن شخص إلى آخر: الاكتساب – النسبيّة – التنقّل – التغيّر. (٠٫٥٠ علامة)\nب- مرتكزا الضمان الاجتماعيّ: الأجر والتعويض – التأمين والتضامن – الضريبة والقرض – الدولة والسوق. (٠٫٥٠ علامة)\nج- معيار التقدّم والتخلّف الذي يتعلّق بالضرائب التصاعديّة والتقديمات الاجتماعيّة: مستوى المديونيّة – مستوى الدخل – مدى توزّع المداخيل – الأمل في الحياة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35732, 16822, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج الإجابة الصحيحة في كلّ من المجموعات الآتية:\nأ- خاصّيّة القيم التي تعني أنّها تتغيّر من مجتمع إلى آخر ومن شخص إلى آخر: الاكتساب – النسبيّة – التنقّل – التغيّر. (٠٫٥٠ علامة)\nب- مرتكزا الضمان الاجتماعيّ: الأجر والتعويض – التأمين والتضامن – الضريبة والقرض – الدولة والسوق. (٠٫٥٠ علامة)\nج- معيار التقدّم والتخلّف الذي يتعلّق بالضرائب التصاعديّة والتقديمات الاجتماعيّة: مستوى المديونيّة – مستوى الدخل – مدى توزّع المداخيل – الأمل في الحياة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:08', '2026-10-01 02:33:08'),
(35733, 16823, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- صنّف العناصر الآتية ضمن مجموعتين متجانستين وفق صنف شروط الاندماج الاجتماعيّ، ثمّ برّر إجابتك: (١٫٥٠ علامة)\nالعمل براتب محدّد ودوام محدّد – حرّيّة الترشّح والانتخاب – الدخول إلى نقابات تدافع عن مصالح العمّال – حرّيّة الإعلام والتعبير والنشر.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35734, 16823, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٤- صنّف العناصر الآتية ضمن مجموعتين متجانستين وفق صنف شروط الاندماج الاجتماعيّ، ثمّ برّر إجابتك: (١٫٥٠ علامة)\nالعمل براتب محدّد ودوام محدّد – حرّيّة الترشّح والانتخاب – الدخول إلى نقابات تدافع عن مصالح العمّال – حرّيّة الإعلام والتعبير والنشر.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35735, 16824, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- طُلب إليك إجراء دراسة حول تفاوت الخدمات الصحّيّة والتربويّة بين منطقة في شمال لبنان ومنطقة في بيروت.\nأ- اذكر تقنية البحث التي سوف تعتمدها لجمع آراء عدد كبير من الأهالي، وتلك التي سوف تعتمدها في لقاء رئيس البلديّة، ثمّ برّر إجابتك. (علامة واحدة)\nب- صغ سؤالاً ذا ثلاثة خيارات موجّهاً إلى أهالي المنطقتين. (علامة واحدة)\nج- سمِّ نوع العيّنة التي لا تراعي معايير معيّنة في اختيار أفرادها. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35736, 16824, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٥- طُلب إليك إجراء دراسة حول تفاوت الخدمات الصحّيّة والتربويّة بين منطقة في شمال لبنان ومنطقة في بيروت.\nأ- اذكر تقنية البحث التي سوف تعتمدها لجمع آراء عدد كبير من الأهالي، وتلك التي سوف تعتمدها في لقاء رئيس البلديّة، ثمّ برّر إجابتك. (علامة واحدة)\nب- صغ سؤالاً ذا ثلاثة خيارات موجّهاً إلى أهالي المنطقتين. (علامة واحدة)\nج- سمِّ نوع العيّنة التي لا تراعي معايير معيّنة في اختيار أفرادها. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35737, 16825, 1, '【المجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)】\nالمجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)\n\nمستند:\nتنقل العائلة والمدرسة والحيّ والدين إلى الفرد اللبنانيّ قيماً يكتسبها من بيئته، فتدرّبه العائلة على الطاعة والامتثال واحترام الرأي، وتكسبه المدرسة المعرفة وروح الانتماء إلى الجماعة واحترام القواعد. غير أنّ قيماً وافدة تصل إليه عبر وسائل الاتّصال، والمقاهي والمسارح ودور السينما، والشركات التي تنشر قيمة الربح، والمدارس والجامعات الأجنبيّة. فينقسم المجتمع بين مسنّين يرفضون القيم الوافدة ويتمسّكون بالتراث القديم وشباب يتلقّون ما هو جديد، ويكون التلقّي عند أهل المدينة أسرع منه عند أهل الريف.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nيعيش المجتمع اللبنانيّ صراعاً بين قيمه المحلّيّة وقيم وافدة إليه من الخارج. مستعيناً بالمستند وبمعلوماتك المكتسبة، عالج هذا الموضوع مركّزاً على النقاط الآتية:\n• القيم واختبار القيم: تعريف كلّ منهما والعلاقة بينهما.\n• مؤسّستان من مؤسّسات نقل القيم من الداخل ومؤسّستان من مؤسّسات نقلها من الخارج، مع دور كلّ منها.\n• واقع التباين في المواقف من القيم الوافدة في المجتمع اللبنانيّ.\n• ثلاثة اقتراحات لتعزيز دور مؤسّسات نقل القيم من الداخل.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35738, 16825, 2, '【المجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)】\nالمجموعة الثانية: معالجة موضوع اجتماعيّ (١٢ علامة)\n\nمستند:\nتنقل العائلة والمدرسة والحيّ والدين إلى الفرد اللبنانيّ قيماً يكتسبها من بيئته، فتدرّبه العائلة على الطاعة والامتثال واحترام الرأي، وتكسبه المدرسة المعرفة وروح الانتماء إلى الجماعة واحترام القواعد. غير أنّ قيماً وافدة تصل إليه عبر وسائل الاتّصال، والمقاهي والمسارح ودور السينما، والشركات التي تنشر قيمة الربح، والمدارس والجامعات الأجنبيّة. فينقسم المجتمع بين مسنّين يرفضون القيم الوافدة ويتمسّكون بالتراث القديم وشباب يتلقّون ما هو جديد، ويكون التلقّي عند أهل المدينة أسرع منه عند أهل الريف.\nالمصدر: دراسة اجتماعيّة (بتصرّف)\n\nيعيش المجتمع اللبنانيّ صراعاً بين قيمه المحلّيّة وقيم وافدة إليه من الخارج. مستعيناً بالمستند وبمعلوماتك المكتسبة، عالج هذا الموضوع مركّزاً على النقاط الآتية:\n• القيم واختبار القيم: تعريف كلّ منهما والعلاقة بينهما.\n• مؤسّستان من مؤسّسات نقل القيم من الداخل ومؤسّستان من مؤسّسات نقلها من الخارج، مع دور كلّ منها.\n• واقع التباين في المواقف من القيم الوافدة في المجتمع اللبنانيّ.\n• ثلاثة اقتراحات لتعزيز دور مؤسّسات نقل القيم من الداخل.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35739, 16826, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- دراسة الاختيارات الاجتماعيّة التي يقوم بها الأفراد وقياسها، والتعبير عنها تعبيراً كمّيّاً ورياضيّاً.\nب- تبادل المعارف والعادات بين ثقافتين، يوسّع دائرة التلقّي للمعلومات ويسمح بالتواصل مع المجتمعات المغايرة.\nج- مجموعة المؤسّسات الضامنة اجتماعيّاً التي تؤمّن الحماية الاجتماعيّة لأبناء الوطن وتحميهم من حالة الفقر.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35740, 16826, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\nتتكوّن هذه المسابقة من مجموعتين: المجموعة الأولى (٨ علامات) ومجموعة ثانية (١٢ علامة). أجب عن الأسئلة كلّها.\n\nالمجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)\n١- سمِّ المفهوم أو المصطلح الاجتماعيّ المناسب لكلّ من العبارات الآتية: (١٫٥٠ علامة)\nأ- دراسة الاختيارات الاجتماعيّة التي يقوم بها الأفراد وقياسها، والتعبير عنها تعبيراً كمّيّاً ورياضيّاً.\nب- تبادل المعارف والعادات بين ثقافتين، يوسّع دائرة التلقّي للمعلومات ويسمح بالتواصل مع المجتمعات المغايرة.\nج- مجموعة المؤسّسات الضامنة اجتماعيّاً التي تؤمّن الحماية الاجتماعيّة لأبناء الوطن وتحميهم من حالة الفقر.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35741, 16827, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- ميّز بفارق واحد بين:\nأ- المراكز المكتسبة والمراكز المفروضة. (٠٫٥٠ علامة)\nب- الهجرة والنزوح. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35742, 16827, 2, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٢- ميّز بفارق واحد بين:\nأ- المراكز المكتسبة والمراكز المفروضة. (٠٫٥٠ علامة)\nب- الهجرة والنزوح. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(35743, 16828, 1, '【المجموعة الأولى: استعمال مفاهيم وتقنيّات (٨ علامات)】\n٣- استخرج الإجابة الصحيحة في كلّ من المجموعات الآتية:\nأ- من العوامل الداخليّة لتغيّر القيم: سيطرة الدول الغربيّة على الدول الضعيفة – النموّ السكّانيّ – المدارس الأجنبيّة – دور السينما. (٠٫٥٠ علامة)\nب- أساس اختيار الأشخاص ومساعدتهم في الأنظمة الشموليّة الديكتاتوريّة المنغلقة: الكفاءة والمهارة – الحاجة والحماية – الانتماء إلى الحزب الحاكم – المساواة أمام قانون العمل. (٠٫٥٠ علامة)\nج- تُصنَّف الدول التي وضعت خطط التنمية لكنّها غرقت في الديون وفوائدها في خانة: الدول المتقدّمة – الدول المتخلّفة – الدول في طور النموّ – الدول الصناعيّة. (٠٫٥٠ علامة)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
