INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(35820, 16865, 2, 'رابعًا: القيم الاجتماعيّة والمدنيّة أساس لتنظيم الحياة المشتركة.\nب- بيّن من خلال فكرة واحدة كيف تشكّل القيم المدنيّة أساسًا لدولة القانون (نصف علامة).', 1, '2026-10-01 03:15:13', '2026-10-01 03:15:13'),
(35821, 16866, 1, 'المستند رقم (1):\n«- لبنان جمهوريّة ديمقراطيّة برلمانيّة، تقوم على احترام الحرّيّات العامّة، وفي طليعتها حرّيّة الرأي والمعتقد، وعلى العدالة الاجتماعيّة والمساواة في الحقوق والواجبات بين جميع المواطنين دون تمايز أو تفضيل. (مقدّمة الدستور، الفقرة ج)\n- كلّ اللبنانيّين سواء لدى القانون، وهم يتمتّعون بالسواء بالحقوق المدنيّة والسياسيّة، ويتحمّلون الفرائض والواجبات العامّة دونما فرق بينهم. (المادّة ٧)»\n[المصدر: الدستور اللبنانيّ]\n\nالمستند رقم (2):\n«اجتمع تلامذة الصفّ التاسع لاختيار مشروع يقدّمونه في المعرض المدرسيّ. وما إن بدأ سليم يعرض اقتراحه حتّى قاطعه بعض رفاقه، وقال أحدهم: \"لا داعي لسماعه، فهو جديد في المدرسة ومن منطقة بعيدة، ولن يأتي بفكرة جيّدة\". وتمسّك كلّ فريق برأيه رافضًا أيّ تعديل عليه، فعلت الأصوات وكاد الاجتماع ينتهي بخلاف حادّ. عندها تدخّلت المعلّمة، فطلبت من كلّ تلميذ أن يصغي إلى زميله حتّى ينهي كلامه، وأن يعتمد الجميع الحوار والتفاوض لحلّ الخلاف. فأصغى التلامذة إلى سليم، واتّفقوا على مشروع يجمع أفضل الاقتراحات، فتحسّن التواصل بينهم وانتهى الخلاف.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n١- قدّم كلًّا من المستندين (١ و٢): نوعه، مصدره، وحدّد الفكرة الرئيسة التي يتناولها (علامتان).', 1, '2026-10-01 03:15:13', '2026-10-01 03:15:13'),
(35822, 16866, 2, 'المستند رقم (1):\n«- لبنان جمهوريّة ديمقراطيّة برلمانيّة، تقوم على احترام الحرّيّات العامّة، وفي طليعتها حرّيّة الرأي والمعتقد، وعلى العدالة الاجتماعيّة والمساواة في الحقوق والواجبات بين جميع المواطنين دون تمايز أو تفضيل. (مقدّمة الدستور، الفقرة ج)\n- كلّ اللبنانيّين سواء لدى القانون، وهم يتمتّعون بالسواء بالحقوق المدنيّة والسياسيّة، ويتحمّلون الفرائض والواجبات العامّة دونما فرق بينهم. (المادّة ٧)»\n[المصدر: الدستور اللبنانيّ]\n\nالمستند رقم (2):\n«اجتمع تلامذة الصفّ التاسع لاختيار مشروع يقدّمونه في المعرض المدرسيّ. وما إن بدأ سليم يعرض اقتراحه حتّى قاطعه بعض رفاقه، وقال أحدهم: \"لا داعي لسماعه، فهو جديد في المدرسة ومن منطقة بعيدة، ولن يأتي بفكرة جيّدة\". وتمسّك كلّ فريق برأيه رافضًا أيّ تعديل عليه، فعلت الأصوات وكاد الاجتماع ينتهي بخلاف حادّ. عندها تدخّلت المعلّمة، فطلبت من كلّ تلميذ أن يصغي إلى زميله حتّى ينهي كلامه، وأن يعتمد الجميع الحوار والتفاوض لحلّ الخلاف. فأصغى التلامذة إلى سليم، واتّفقوا على مشروع يجمع أفضل الاقتراحات، فتحسّن التواصل بينهم وانتهى الخلاف.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n١- قدّم كلًّا من المستندين (١ و٢): نوعه، مصدره، وحدّد الفكرة الرئيسة التي يتناولها (علامتان).', 1, '2026-10-01 03:15:13', '2026-10-01 03:15:13'),
