(35906, 16908, 2, 'المستند رقم (2):\n«قرّرت مجموعة من الشباب في إحدى البلدات، بينهم ريم التي بلغت الحادية والعشرين من عمرها وشقيقها وسيم ابن الخامسة عشرة، تأسيس جمعيّة أهليّة لحماية البيئة، هدفها الحفاظ على بيئة نظيفة وسليمة. ووضعت المجموعة خطّة عمل تتضمّن تقديم أنشطة مفيدة ومتنوّعة كحملات التوعية البيئيّة، وتوعية الرأي العامّ، والضغط على المعنيّين للدفع بالواقع الاجتماعيّ والأداء العامّ نحو الأفضل. وفي أثناء التحضير، اقترح أحد الأعضاء أن تتحوّل المجموعة إلى حزب سياسيّ يشارك في الانتخابات ترشيحًا واقتراعًا بهدف الوصول إلى السلطة، فيما رأى آخر أن ينتسب الأعضاء إلى نقابة مهنيّة للدفاع عن مصالحهم وحقوقهم. فذكّرتهم ريم بأنّ لكلّ مجال من مجالات المشاركة في مؤسّسات المجتمع المدنيّ وسيلته وهدفه.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n٢- استخرج من المستند رقم (٢):\nج- هدفين من أهداف المشاركة الأهليّة (علامة واحدة).', 1, '2026-10-01 03:15:29', '2026-10-01 03:15:29'),
(35907, 16909, 1, 'المستند رقم (2):\n«قرّرت مجموعة من الشباب في إحدى البلدات، بينهم ريم التي بلغت الحادية والعشرين من عمرها وشقيقها وسيم ابن الخامسة عشرة، تأسيس جمعيّة أهليّة لحماية البيئة، هدفها الحفاظ على بيئة نظيفة وسليمة. ووضعت المجموعة خطّة عمل تتضمّن تقديم أنشطة مفيدة ومتنوّعة كحملات التوعية البيئيّة، وتوعية الرأي العامّ، والضغط على المعنيّين للدفع بالواقع الاجتماعيّ والأداء العامّ نحو الأفضل. وفي أثناء التحضير، اقترح أحد الأعضاء أن تتحوّل المجموعة إلى حزب سياسيّ يشارك في الانتخابات ترشيحًا واقتراعًا بهدف الوصول إلى السلطة، فيما رأى آخر أن ينتسب الأعضاء إلى نقابة مهنيّة للدفاع عن مصالحهم وحقوقهم. فذكّرتهم ريم بأنّ لكلّ مجال من مجالات المشاركة في مؤسّسات المجتمع المدنيّ وسيلته وهدفه.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n٢- استخرج من المستند رقم (٢):\nد- مجالين آخرين للمشاركة في مؤسّسات المجتمع المدنيّ غير المشاركة الأهليّة، مع هدف كلّ منهما (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35908, 16909, 2, 'المستند رقم (2):\n«قرّرت مجموعة من الشباب في إحدى البلدات، بينهم ريم التي بلغت الحادية والعشرين من عمرها وشقيقها وسيم ابن الخامسة عشرة، تأسيس جمعيّة أهليّة لحماية البيئة، هدفها الحفاظ على بيئة نظيفة وسليمة. ووضعت المجموعة خطّة عمل تتضمّن تقديم أنشطة مفيدة ومتنوّعة كحملات التوعية البيئيّة، وتوعية الرأي العامّ، والضغط على المعنيّين للدفع بالواقع الاجتماعيّ والأداء العامّ نحو الأفضل. وفي أثناء التحضير، اقترح أحد الأعضاء أن تتحوّل المجموعة إلى حزب سياسيّ يشارك في الانتخابات ترشيحًا واقتراعًا بهدف الوصول إلى السلطة، فيما رأى آخر أن ينتسب الأعضاء إلى نقابة مهنيّة للدفاع عن مصالحهم وحقوقهم. فذكّرتهم ريم بأنّ لكلّ مجال من مجالات المشاركة في مؤسّسات المجتمع المدنيّ وسيلته وهدفه.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n٢- استخرج من المستند رقم (٢):\nد- مجالين آخرين للمشاركة في مؤسّسات المجتمع المدنيّ غير المشاركة الأهليّة، مع هدف كلّ منهما (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35909, 16910, 1, 'المستند رقم (1):\n«- يُشترط في من يرغب في تأسيس جمعيّة أو الانتساب إليها أن يكون لبنانيًّا بلغ العشرين من عمره، غير محكوم بجناية، وغير محروم من حقوقه المدنيّة.\n- يتوجّب على الراغبين في تأسيس جمعيّة التقدّم بالعلم والخبر إلى وزارة الداخليّة.\n- على كلّ جمعيّة أن تمسك دفاتر معيّنة، وأن تُعلم وزارة الداخليّة بالتعديلات التي تطرأ على أنظمتها وعلى هيئتها الإداريّة.»\n[المصدر: القانون اللبنانيّ الذي ينظّم الجمعيّات (بتصرّف)]\n\nالمستند رقم (2):\n«قرّرت مجموعة من الشباب في إحدى البلدات، بينهم ريم التي بلغت الحادية والعشرين من عمرها وشقيقها وسيم ابن الخامسة عشرة، تأسيس جمعيّة أهليّة لحماية البيئة، هدفها الحفاظ على بيئة نظيفة وسليمة. ووضعت المجموعة خطّة عمل تتضمّن تقديم أنشطة مفيدة ومتنوّعة كحملات التوعية البيئيّة، وتوعية الرأي العامّ، والضغط على المعنيّين للدفع بالواقع الاجتماعيّ والأداء العامّ نحو الأفضل. وفي أثناء التحضير، اقترح أحد الأعضاء أن تتحوّل المجموعة إلى حزب سياسيّ يشارك في الانتخابات ترشيحًا واقتراعًا بهدف الوصول إلى السلطة، فيما رأى آخر أن ينتسب الأعضاء إلى نقابة مهنيّة للدفاع عن مصالحهم وحقوقهم. فذكّرتهم ريم بأنّ لكلّ مجال من مجالات المشاركة في مؤسّسات المجتمع المدنيّ وسيلته وهدفه.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n٣- استنادًا إلى المستند رقم (١)، بيّن هل يحقّ لوسيم أن يكون من مؤسّسي الجمعيّة الواردة في المستند رقم (٢)، معلّلًا إجابتك (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(35910, 16910, 2, 'المستند رقم (1):\n«- يُشترط في من يرغب في تأسيس جمعيّة أو الانتساب إليها أن يكون لبنانيًّا بلغ العشرين من عمره، غير محكوم بجناية، وغير محروم من حقوقه المدنيّة.\n- يتوجّب على الراغبين في تأسيس جمعيّة التقدّم بالعلم والخبر إلى وزارة الداخليّة.\n- على كلّ جمعيّة أن تمسك دفاتر معيّنة، وأن تُعلم وزارة الداخليّة بالتعديلات التي تطرأ على أنظمتها وعلى هيئتها الإداريّة.»\n[المصدر: القانون اللبنانيّ الذي ينظّم الجمعيّات (بتصرّف)]\n\nالمستند رقم (2):\n«قرّرت مجموعة من الشباب في إحدى البلدات، بينهم ريم التي بلغت الحادية والعشرين من عمرها وشقيقها وسيم ابن الخامسة عشرة، تأسيس جمعيّة أهليّة لحماية البيئة، هدفها الحفاظ على بيئة نظيفة وسليمة. ووضعت المجموعة خطّة عمل تتضمّن تقديم أنشطة مفيدة ومتنوّعة كحملات التوعية البيئيّة، وتوعية الرأي العامّ، والضغط على المعنيّين للدفع بالواقع الاجتماعيّ والأداء العامّ نحو الأفضل. وفي أثناء التحضير، اقترح أحد الأعضاء أن تتحوّل المجموعة إلى حزب سياسيّ يشارك في الانتخابات ترشيحًا واقتراعًا بهدف الوصول إلى السلطة، فيما رأى آخر أن ينتسب الأعضاء إلى نقابة مهنيّة للدفاع عن مصالحهم وحقوقهم. فذكّرتهم ريم بأنّ لكلّ مجال من مجالات المشاركة في مؤسّسات المجتمع المدنيّ وسيلته وهدفه.»\n[المصدر: دراسة حالة مُعَدّة لهذا الامتحان]\n\nانطلاقًا من المستندين، أجب عن السؤال الآتي:\n٣- استنادًا إلى المستند رقم (١)، بيّن هل يحقّ لوسيم أن يكون من مؤسّسي الجمعيّة الواردة في المستند رقم (٢)، معلّلًا إجابتك (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35911, 16911, 1, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n١- استنتج المشكلة المطروحة في الوضعيّة (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35912, 16911, 2, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n١- استنتج المشكلة المطروحة في الوضعيّة (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35913, 16912, 1, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٢- اذكر ثلاثًا من الصفات التي يتحلّى بها المواطن الذي يحافظ على الملك العامّ (علامة ونصف).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35914, 16912, 2, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٢- اذكر ثلاثًا من الصفات التي يتحلّى بها المواطن الذي يحافظ على الملك العامّ (علامة ونصف).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35915, 16913, 1, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٣- أوضح من خلال فكرتين واجب الشابّ في مجتمعه للإسهام في تنظيم الحياة المشتركة على أساس القيم (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35916, 16913, 2, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٣- أوضح من خلال فكرتين واجب الشابّ في مجتمعه للإسهام في تنظيم الحياة المشتركة على أساس القيم (علامة واحدة).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35917, 16914, 1, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٤- أبدِ رأيك في قول الشابّ: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟»، معلّلًا رأيك بفكرتين (علامة ونصف).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35918, 16914, 2, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٤- أبدِ رأيك في قول الشابّ: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟»، معلّلًا رأيك بفكرتين (علامة ونصف).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35919, 16915, 1, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٥- قدّم اقتراحين يسهمان في المحافظة على الحديقة العامّة في البلدة (علامتان).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35920, 16915, 2, 'الوضعيّة: في إحدى البلدات، أُهملت الحديقة العامّة حتّى تكسّرت ألعاب الأطفال فيها وتراكمت النفايات بين أشجارها، ويهدر بعض الزوّار مياه الريّ من دون حساب. وحين دعت البلديّة شباب البلدة إلى المشاركة في حملة تطوّعيّة لتنظيف الحديقة وإعادة تأهيلها، لم يلبِّ الدعوة سوى عدد قليل منهم، وقال أحدهم: «الحديقة ملك للدولة، فلماذا أتعب نفسي من أجلها؟».\n\n٥- قدّم اقتراحين يسهمان في المحافظة على الحديقة العامّة في البلدة (علامتان).', 1, '2026-10-01 03:15:30', '2026-10-01 03:15:30'),
(35921, 16916, 1, 'المستند رقم (١): خريطة لبنان الطبيعيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مصبّ نهر عند أقصى شمال الشاطئ اللبنانيّ، يبدأ عنده الشاطئ — الصفّ ١، العمود ٣.\n(٢) رأس عند أقصى جنوب الشاطئ اللبنانيّ، تنتهي عنده الحدود الجنوبيّة — الصفّ ٥، العمود ١.\n(٣) مدينة بيروت (العاصمة) — الصفّ ٣، العمود ٢.\n(أ) منطقة يتّسع فيها السهل الساحليّ في شمال البلاد — الصفّ ١، العمود ٣.\n(ب) مدينتان ساحليّتان في الجنوب يتّسع عندهما السهل الساحليّ — الصفّ ٤، العمود ١ والصفّ ٥، العمود ١.\n(ج) قمّة في الجزء الشماليّ المرتفع والعريض من السلسلة الجبليّة المشرفة على الساحل — الصفّ ٢، العمود ٣.\n(د) سهل واسع ممتدّ بين السلسلتين الجبليّتين من الصفّ ٢ إلى الصفّ ٤، في العمودين ٣ و٤.\n(هـ) مدينة بعلبك داخل السهل (د) — الصفّ ٣، العمود ٤.\n(و) جبل الشيخ (حرمون) — الصفّ ٥، العمود ٣.\n\nمن خلال المستند رقم (١):\n١- اذكر:\nأ- اسمَي المعلمين المشار إليهما بالرقمين (١، ٢) اللذين يمتدّ بينهما الشاطئ اللبنانيّ. (علامة واحدة)\nب- اسم المنطقة المشار إليها بالحرف (أ)، واسمَي المدينتين المشار إليهما بالحرف (ب). (علامة واحدة)\nج- اسم القمّة المشار إليها بالحرف (ج)، واسم الوحدة التضاريسيّة التي تقع فيها. (نصف علامة)\nد- اسم السهل المشار إليه بالحرف (د)، واسم الوحدة التضاريسيّة التي ينتمي إليها. (نصف علامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35922, 16916, 2, 'المستند رقم (١): خريطة لبنان الطبيعيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مصبّ نهر عند أقصى شمال الشاطئ اللبنانيّ، يبدأ عنده الشاطئ — الصفّ ١، العمود ٣.\n(٢) رأس عند أقصى جنوب الشاطئ اللبنانيّ، تنتهي عنده الحدود الجنوبيّة — الصفّ ٥، العمود ١.\n(٣) مدينة بيروت (العاصمة) — الصفّ ٣، العمود ٢.\n(أ) منطقة يتّسع فيها السهل الساحليّ في شمال البلاد — الصفّ ١، العمود ٣.\n(ب) مدينتان ساحليّتان في الجنوب يتّسع عندهما السهل الساحليّ — الصفّ ٤، العمود ١ والصفّ ٥، العمود ١.\n(ج) قمّة في الجزء الشماليّ المرتفع والعريض من السلسلة الجبليّة المشرفة على الساحل — الصفّ ٢، العمود ٣.\n(د) سهل واسع ممتدّ بين السلسلتين الجبليّتين من الصفّ ٢ إلى الصفّ ٤، في العمودين ٣ و٤.\n(هـ) مدينة بعلبك داخل السهل (د) — الصفّ ٣، العمود ٤.\n(و) جبل الشيخ (حرمون) — الصفّ ٥، العمود ٣.\n\nمن خلال المستند رقم (١):\n١- اذكر:\nأ- اسمَي المعلمين المشار إليهما بالرقمين (١، ٢) اللذين يمتدّ بينهما الشاطئ اللبنانيّ. (علامة واحدة)\nب- اسم المنطقة المشار إليها بالحرف (أ)، واسمَي المدينتين المشار إليهما بالحرف (ب). (علامة واحدة)\nج- اسم القمّة المشار إليها بالحرف (ج)، واسم الوحدة التضاريسيّة التي تقع فيها. (نصف علامة)\nد- اسم السهل المشار إليه بالحرف (د)، واسم الوحدة التضاريسيّة التي ينتمي إليها. (نصف علامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35923, 16917, 1, 'من خلال المستند رقم (١) (خريطة لبنان الطبيعيّة):\n٢- حدّد:\nأ- موقع جبل الشيخ (و) بالنسبة إلى مدينة بيروت (٣). (نصف علامة)\nب- الاتّجاه العامّ لانحدار السطح الشماليّ لسهل البقاع انطلاقًا من منطقة بعلبك (هـ). (نصف علامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35924, 16917, 2, 'من خلال المستند رقم (١) (خريطة لبنان الطبيعيّة):\n٢- حدّد:\nأ- موقع جبل الشيخ (و) بالنسبة إلى مدينة بيروت (٣). (نصف علامة)\nب- الاتّجاه العامّ لانحدار السطح الشماليّ لسهل البقاع انطلاقًا من منطقة بعلبك (هـ). (نصف علامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35925, 16918, 1, 'المستند رقم (٢):\n«تعود ظاهرة النزوح الريفيّ في لبنان إلى أواسط القرن العشرين، ولا تزال ناشطة حتّى يومنا هذا. فقد انتقل عدد كبير من سكّان الأرياف إلى المدن رغبةً منهم في تحسين أوضاعهم، ولتوفّر فرص العمل والخدمات فيها. ويقدّر الخبراء أنّ بيروت وضواحيها تستأثران بالحصّة الكبرى من إجمالي هذه الحركة، إذ تستأثر العاصمة بمعظم النشاطات الاقتصاديّة وغير الاقتصاديّة في البلاد.\nوقد أدّت هذه الظاهرة إلى تضخّم سكّانيّ أصاب بشكل كبير مدينة بيروت وضواحيها وطرابلس، وإلى ظهور مشكلات متعدّدة في المدن أهمّها الحاجة إلى مزيد من الخدمات الجديدة، في حين تقهقرت الأرياف اقتصاديًّا وسكّانيًّا، فتراجع النشاط الزراعيّ فيها وخسرت العناصر الشابّة. وإلى جانب هذا النزوح، ينطلق العاملون كلّ صباح من المحافظات باتّجاه بيروت ثمّ يعودون مساءً نحو المحافظات، فتشهد مداخل العاصمة زحمة سير خانقة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35926, 16918, 2, 'المستند رقم (٢):\n«تعود ظاهرة النزوح الريفيّ في لبنان إلى أواسط القرن العشرين، ولا تزال ناشطة حتّى يومنا هذا. فقد انتقل عدد كبير من سكّان الأرياف إلى المدن رغبةً منهم في تحسين أوضاعهم، ولتوفّر فرص العمل والخدمات فيها. ويقدّر الخبراء أنّ بيروت وضواحيها تستأثران بالحصّة الكبرى من إجمالي هذه الحركة، إذ تستأثر العاصمة بمعظم النشاطات الاقتصاديّة وغير الاقتصاديّة في البلاد.\nوقد أدّت هذه الظاهرة إلى تضخّم سكّانيّ أصاب بشكل كبير مدينة بيروت وضواحيها وطرابلس، وإلى ظهور مشكلات متعدّدة في المدن أهمّها الحاجة إلى مزيد من الخدمات الجديدة، في حين تقهقرت الأرياف اقتصاديًّا وسكّانيًّا، فتراجع النشاط الزراعيّ فيها وخسرت العناصر الشابّة. وإلى جانب هذا النزوح، ينطلق العاملون كلّ صباح من المحافظات باتّجاه بيروت ثمّ يعودون مساءً نحو المحافظات، فتشهد مداخل العاصمة زحمة سير خانقة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35927, 16919, 1, '٤- من خلال المستند رقم (٢) (نصّ حول النزوح الريفيّ في لبنان):\nأ- حدّد سببين للنزوح الريفيّ في لبنان. (نصف علامة)\nب- بيّن نتيجة واحدة للنزوح الريفيّ على الأرياف، ونتيجة واحدة على المدن. (علامة واحدة)\nج- استنتج مكانة مدينة بيروت في التحرّكات المكانيّة للسكّان في لبنان، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35928, 16919, 2, '٤- من خلال المستند رقم (٢) (نصّ حول النزوح الريفيّ في لبنان):\nأ- حدّد سببين للنزوح الريفيّ في لبنان. (نصف علامة)\nب- بيّن نتيجة واحدة للنزوح الريفيّ على الأرياف، ونتيجة واحدة على المدن. (علامة واحدة)\nج- استنتج مكانة مدينة بيروت في التحرّكات المكانيّة للسكّان في لبنان، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35929, 16920, 1, '٥- يشير المستند رقم (٢) إلى حركة العمل اليوميّة، وهي أحد أشكال التحرّكات الدوريّة في لبنان. أوضح شكلين آخرين من أشكال التحرّكات الدوريّة. (علامة واحدة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35930, 16920, 2, '٥- يشير المستند رقم (٢) إلى حركة العمل اليوميّة، وهي أحد أشكال التحرّكات الدوريّة في لبنان. أوضح شكلين آخرين من أشكال التحرّكات الدوريّة. (علامة واحدة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35931, 16921, 1, 'المستند رقم (٣): مقوّمات السياحة في لبنان.\n| المقوّم | مضمونه |\n| الموقع | عند ملتقى ثلاث قارّات، وفيه مواقع مقدّسة لدى الديانات |\n| المناخ | معتدل ومتنوّع: الاصطياف ممكن في الصيف، والتزلّج ممكن في الشتاء |\n| روائع الطبيعة | مغارة جعيتا؛ قرب الشواطئ من الجبال أحيانًا |\n| الآثار والمرافق | آثار الحضارات القديمة، ومنها الآثار المكتشفة حديثًا في بيروت؛ فنادق ومطاعم ومسابح ومنتزهات للهو والسهر تُقام في المناطق الساحليّة والجبليّة |\n| النقل | تطوّر وسائل النقل قصّر المسافات؛ السفر من الدول الأوروبيّة إلى لبنان لا يستغرق أكثر من ٤ أو ٥ ساعات |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35932, 16921, 2, 'المستند رقم (٣): مقوّمات السياحة في لبنان.\n| المقوّم | مضمونه |\n| الموقع | عند ملتقى ثلاث قارّات، وفيه مواقع مقدّسة لدى الديانات |\n| المناخ | معتدل ومتنوّع: الاصطياف ممكن في الصيف، والتزلّج ممكن في الشتاء |\n| روائع الطبيعة | مغارة جعيتا؛ قرب الشواطئ من الجبال أحيانًا |\n| الآثار والمرافق | آثار الحضارات القديمة، ومنها الآثار المكتشفة حديثًا في بيروت؛ فنادق ومطاعم ومسابح ومنتزهات للهو والسهر تُقام في المناطق الساحليّة والجبليّة |\n| النقل | تطوّر وسائل النقل قصّر المسافات؛ السفر من الدول الأوروبيّة إلى لبنان لا يستغرق أكثر من ٤ أو ٥ ساعات |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35933, 16922, 1, '٧- من خلال المستند رقم (٣) (جدول مقوّمات السياحة في لبنان):\nأ- حدّد وحدة القياس المستخدمة فيه. (نصف علامة)\nب- استنتج هل يستطيع السائح أن يمارس السباحة والتزلّج في اليوم نفسه في لبنان، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35934, 16922, 2, '٧- من خلال المستند رقم (٣) (جدول مقوّمات السياحة في لبنان):\nأ- حدّد وحدة القياس المستخدمة فيه. (نصف علامة)\nب- استنتج هل يستطيع السائح أن يمارس السباحة والتزلّج في اليوم نفسه في لبنان، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:31', '2026-10-01 03:15:31'),
(35935, 16923, 1, '٨- يشير المستند رقم (٣) إلى المرافق السياحيّة التي تُقام في المناطق الساحليّة والجبليّة.\nأوضح ثلاثة انعكاسات سلبيّة للنشاط السياحيّ على البيئة في لبنان. (علامة ونصف)', 1, '2026-10-01 03:15:32', '2026-10-01 03:15:32'),
(35936, 16923, 2, '٨- يشير المستند رقم (٣) إلى المرافق السياحيّة التي تُقام في المناطق الساحليّة والجبليّة.\nأوضح ثلاثة انعكاسات سلبيّة للنشاط السياحيّ على البيئة في لبنان. (علامة ونصف)', 1, '2026-10-01 03:15:32', '2026-10-01 03:15:32'),
(35937, 16924, 1, 'المستند رقم (٤): الزراعة في لبنان.\n«عانت الزراعة في لبنان من أزمة حادّة على صعيد الإنتاج وعلى صعيد تصريفه، وزاد التوسّع العمرانيّ من ضيق المجالات الزراعيّة، فتخلّى بعض المزارعين عن أرضهم، وارتفعت أصوات تطالب بتغيير الأنماط الزراعيّة المعتمدة. وبعد أن بقيت الزراعة فترة طويلة تعتمد تقنيات تقليديّة، بدأ التحديث يدخل إليها، فانتشرت الزراعة المحميّة المكيّفة بسرعة قرب المدن حتّى باتت تغطّي مساحة تجاوزت ثلاثة آلاف هكتار. ولم يتحقّق هذا التطوير بجهد فرديّ، بل اشترك القطاعان العامّ والخاصّ في إرساء عناصره، لأنّ الزراعة من الركائز الأساسيّة للاقتصاد اللبنانيّ، فهي توفّر الغذاء للسكّان وتؤمّن المادّة الأوّليّة لكثير من الصناعات.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) عن التحوّلات في المجال الزراعيّ اللبنانيّ، مبيّنًا فيه:\n- سببين دفعا إلى المطالبة بتغيير الأنماط الزراعيّة في لبنان. (علامة واحدة)\n- ثلاثة من مظاهر تحديث التقنيات الزراعيّة. (علامة ونصف)\n- ثلاثة مظاهر تدلّ على تمدين الريف اللبنانيّ. (علامة ونصف)\n- دورين للقطاع العامّ ودورين للقطاع الخاصّ في تطوير المجال الزراعيّ. (علامتان)', 1, '2026-10-01 03:15:32', '2026-10-01 03:15:32'),
(35938, 16924, 2, 'المستند رقم (٤): الزراعة في لبنان.\n«عانت الزراعة في لبنان من أزمة حادّة على صعيد الإنتاج وعلى صعيد تصريفه، وزاد التوسّع العمرانيّ من ضيق المجالات الزراعيّة، فتخلّى بعض المزارعين عن أرضهم، وارتفعت أصوات تطالب بتغيير الأنماط الزراعيّة المعتمدة. وبعد أن بقيت الزراعة فترة طويلة تعتمد تقنيات تقليديّة، بدأ التحديث يدخل إليها، فانتشرت الزراعة المحميّة المكيّفة بسرعة قرب المدن حتّى باتت تغطّي مساحة تجاوزت ثلاثة آلاف هكتار. ولم يتحقّق هذا التطوير بجهد فرديّ، بل اشترك القطاعان العامّ والخاصّ في إرساء عناصره، لأنّ الزراعة من الركائز الأساسيّة للاقتصاد اللبنانيّ، فهي توفّر الغذاء للسكّان وتؤمّن المادّة الأوّليّة لكثير من الصناعات.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) عن التحوّلات في المجال الزراعيّ اللبنانيّ، مبيّنًا فيه:\n- سببين دفعا إلى المطالبة بتغيير الأنماط الزراعيّة في لبنان. (علامة واحدة)\n- ثلاثة من مظاهر تحديث التقنيات الزراعيّة. (علامة ونصف)\n- ثلاثة مظاهر تدلّ على تمدين الريف اللبنانيّ. (علامة ونصف)\n- دورين للقطاع العامّ ودورين للقطاع الخاصّ في تطوير المجال الزراعيّ. (علامتان)', 1, '2026-10-01 03:15:32', '2026-10-01 03:15:32'),
(35939, 16925, 1, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول التحوّلات في المجال الزراعيّ اللبنانيّ): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:32', '2026-10-01 03:15:32'),
(35940, 16925, 2, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول التحوّلات في المجال الزراعيّ اللبنانيّ): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:32', '2026-10-01 03:15:32'),
(35941, 16926, 1, 'المستند رقم (١): خريطة حدود لبنان ووحداته الداخليّة الجنوبيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) منطقة تقع عندها الحدود الشماليّة للبنان — الصفّ ١، العمود ٤.\n(٢) قرية تبدأ منها الحدود الجنوبيّة عند طرفها الشرقيّ — الصفّ ٥، العمود ٢.\n(٣) رأس الناقورة — الصفّ ٥، العمود ١.\n(أ) سهل صغير المساحة يفصله جبل العربي عن سهل البقاع — الصفّ ٥، العمود ٢.\n(ب) هضاب كثيرة التعاريج وشديدة الانحدارات، تقع بين جبل الشيخ وجبلَي العربي وبير الضهر — الصفّ ٥، العمودان ٢ و٣.\n(ج) الموضع الذي ينتهي عنده السطح الجنوبيّ لسهل البقاع — الصفّ ٤، العمود ٢.\n(د) أعلى قمّة في القسم الجنوبيّ الأكثر ارتفاعًا من سلسلة جبال لبنان الشرقيّة — الصفّ ٥، العمود ٣.\n\nمن خلال المستند رقم (١):\n١- اذكر اسم كلٍّ من:\nأ- المعلمين المشار إليهما بالرقمين (١، ٢). (علامة واحدة)\nب- السهل المشار إليه بالحرف (أ)، ونوعين من المزروعات التي تُزرع فيه. (علامة واحدة)\nج- الهضاب المشار إليها بالحرف (ب)، والموضع المشار إليه بالحرف (ج). (نصف علامة)\nد- القمّة المشار إليها بالحرف (د)، والقسم الجبليّ الذي تقع فيه. (نصف علامة)', 1, '2026-10-01 03:15:34', '2026-10-01 03:15:34'),
(35942, 16926, 2, 'المستند رقم (١): خريطة حدود لبنان ووحداته الداخليّة الجنوبيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) منطقة تقع عندها الحدود الشماليّة للبنان — الصفّ ١، العمود ٤.\n(٢) قرية تبدأ منها الحدود الجنوبيّة عند طرفها الشرقيّ — الصفّ ٥، العمود ٢.\n(٣) رأس الناقورة — الصفّ ٥، العمود ١.\n(أ) سهل صغير المساحة يفصله جبل العربي عن سهل البقاع — الصفّ ٥، العمود ٢.\n(ب) هضاب كثيرة التعاريج وشديدة الانحدارات، تقع بين جبل الشيخ وجبلَي العربي وبير الضهر — الصفّ ٥، العمودان ٢ و٣.\n(ج) الموضع الذي ينتهي عنده السطح الجنوبيّ لسهل البقاع — الصفّ ٤، العمود ٢.\n(د) أعلى قمّة في القسم الجنوبيّ الأكثر ارتفاعًا من سلسلة جبال لبنان الشرقيّة — الصفّ ٥، العمود ٣.\n\nمن خلال المستند رقم (١):\n١- اذكر اسم كلٍّ من:\nأ- المعلمين المشار إليهما بالرقمين (١، ٢). (علامة واحدة)\nب- السهل المشار إليه بالحرف (أ)، ونوعين من المزروعات التي تُزرع فيه. (علامة واحدة)\nج- الهضاب المشار إليها بالحرف (ب)، والموضع المشار إليه بالحرف (ج). (نصف علامة)\nد- القمّة المشار إليها بالحرف (د)، والقسم الجبليّ الذي تقع فيه. (نصف علامة)', 1, '2026-10-01 03:15:34', '2026-10-01 03:15:34'),
(35943, 16927, 1, 'من خلال المستند رقم (١) (خريطة حدود لبنان ووحداته الداخليّة الجنوبيّة):\n٢- حدّد:\nأ- الاتّجاه العامّ لامتداد الحدود الجنوبيّة للبنان من القرية (٢) إلى رأس الناقورة (٣). (نصف علامة)\nب- موقع المنطقة (١) بالنسبة إلى رأس الناقورة (٣). (نصف علامة)', 1, '2026-10-01 03:15:34', '2026-10-01 03:15:34'),
(35944, 16927, 2, 'من خلال المستند رقم (١) (خريطة حدود لبنان ووحداته الداخليّة الجنوبيّة):\n٢- حدّد:\nأ- الاتّجاه العامّ لامتداد الحدود الجنوبيّة للبنان من القرية (٢) إلى رأس الناقورة (٣). (نصف علامة)\nب- موقع المنطقة (١) بالنسبة إلى رأس الناقورة (٣). (نصف علامة)', 1, '2026-10-01 03:15:34', '2026-10-01 03:15:34'),
(35945, 16928, 1, 'المستند رقم (٢):\n«السياحة من النشاطات الحديثة التي برزت خلال القرن العشرين، وقد مارسها الإنسان بدافع حبّ الاستطلاع والرغبة في الترفيه والاستجمام. ويتمتّع لبنان بموقع عند ملتقى ثلاث قارات، وباعتدال مناخه وتنوّعه، فالاصطياف ممكن في الصيف والتزلّج ممكن في الشتاء، كما يسمح قرب الشواطئ من الجبال أحيانًا بممارسة السباحة والتزلّج في اليوم نفسه، وتضاف إلى ذلك روائع الطبيعة ومنها مغارة جعيتا.\nويأتي السيّاح إلى لبنان من دول موزّعة في القارات الخمس، ومن أهمّ أسباب كثرة عدد السيّاح الأوروبيّين قرب دولهم من لبنان، فالسفر منها إليه لا يستغرق أكثر من أربع أو خمس ساعات، أمّا السيّاح العرب فمعظمهم من دول الخليج العربيّ الغنيّ بثرواته النفطيّة. غير أنّ قطاع السياحة شهد تراجعًا ملحوظًا خلال الأحداث، إذ فقد جزءًا كبيرًا من بنيته التحتيّة، وانخفض عدد الفنادق العاملة فيه. ثمّ عاد عدد السيّاح إلى الارتفاع بعد الأحداث، لكنّ هذا القطاع، على الرغم من الجهود الحثيثة لتنميته، لم يصل بعد إلى ما كان عليه قبلها.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35946, 16928, 2, 'المستند رقم (٢):\n«السياحة من النشاطات الحديثة التي برزت خلال القرن العشرين، وقد مارسها الإنسان بدافع حبّ الاستطلاع والرغبة في الترفيه والاستجمام. ويتمتّع لبنان بموقع عند ملتقى ثلاث قارات، وباعتدال مناخه وتنوّعه، فالاصطياف ممكن في الصيف والتزلّج ممكن في الشتاء، كما يسمح قرب الشواطئ من الجبال أحيانًا بممارسة السباحة والتزلّج في اليوم نفسه، وتضاف إلى ذلك روائع الطبيعة ومنها مغارة جعيتا.\nويأتي السيّاح إلى لبنان من دول موزّعة في القارات الخمس، ومن أهمّ أسباب كثرة عدد السيّاح الأوروبيّين قرب دولهم من لبنان، فالسفر منها إليه لا يستغرق أكثر من أربع أو خمس ساعات، أمّا السيّاح العرب فمعظمهم من دول الخليج العربيّ الغنيّ بثرواته النفطيّة. غير أنّ قطاع السياحة شهد تراجعًا ملحوظًا خلال الأحداث، إذ فقد جزءًا كبيرًا من بنيته التحتيّة، وانخفض عدد الفنادق العاملة فيه. ثمّ عاد عدد السيّاح إلى الارتفاع بعد الأحداث، لكنّ هذا القطاع، على الرغم من الجهود الحثيثة لتنميته، لم يصل بعد إلى ما كان عليه قبلها.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35947, 16929, 1, '٤- من خلال المستند رقم (٢) (نصّ حول السياحة في لبنان):\nأ- حدّد مقوّمين طبيعيّين للسياحة في لبنان. (نصف علامة)\nب- حدّد سبب كثرة عدد السيّاح الأوروبيّين في لبنان، والمنطقة التي يأتي منها معظم السيّاح العرب. (نصف علامة)\nج- استنتج واقع القطاع السياحيّ في لبنان بعد الأحداث، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35948, 16929, 2, '٤- من خلال المستند رقم (٢) (نصّ حول السياحة في لبنان):\nأ- حدّد مقوّمين طبيعيّين للسياحة في لبنان. (نصف علامة)\nب- حدّد سبب كثرة عدد السيّاح الأوروبيّين في لبنان، والمنطقة التي يأتي منها معظم السيّاح العرب. (نصف علامة)\nج- استنتج واقع القطاع السياحيّ في لبنان بعد الأحداث، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35949, 16930, 1, '٥- يشير المستند رقم (٢) إلى الجهود الحثيثة المبذولة لتنمية القطاع السياحيّ في لبنان. أوضح اثنين من الإجراءات التي اتّخذتها الدولة لتطوير هذا القطاع. (علامة واحدة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35950, 16930, 2, '٥- يشير المستند رقم (٢) إلى الجهود الحثيثة المبذولة لتنمية القطاع السياحيّ في لبنان. أوضح اثنين من الإجراءات التي اتّخذتها الدولة لتطوير هذا القطاع. (علامة واحدة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35951, 16931, 1, 'المستند رقم (٣): مصادر الطاقة المستعملة في لبنان.\n| المصدر | ما يعتمد عليه | دوره أو واقعه |\n| المعامل الحراريّة | الفيول أويل أو الغاز | يعتمد عليها لبنان بالدرجة الأولى لإنتاج حاجته من الطاقة |\n| المعامل المائيّة | المياه | تسهم بجزء من إنتاج الكهرباء |\n| مصفاتا طرابلس والزهراني | تكرير النفط | كانتا تؤمّنان حاجة البلاد من النفط ومشتقّاته، وتوقّف فيهما التكرير منذ مطلع الثمانينات |\n| النفط ومشتقّاته | غير متوفّر في الأراضي اللبنانيّة | يعتمد تأمينه على الاستيراد |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35952, 16931, 2, 'المستند رقم (٣): مصادر الطاقة المستعملة في لبنان.\n| المصدر | ما يعتمد عليه | دوره أو واقعه |\n| المعامل الحراريّة | الفيول أويل أو الغاز | يعتمد عليها لبنان بالدرجة الأولى لإنتاج حاجته من الطاقة |\n| المعامل المائيّة | المياه | تسهم بجزء من إنتاج الكهرباء |\n| مصفاتا طرابلس والزهراني | تكرير النفط | كانتا تؤمّنان حاجة البلاد من النفط ومشتقّاته، وتوقّف فيهما التكرير منذ مطلع الثمانينات |\n| النفط ومشتقّاته | غير متوفّر في الأراضي اللبنانيّة | يعتمد تأمينه على الاستيراد |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:35', '2026-10-01 03:15:35'),
(35953, 16932, 1, '٧- من خلال المستند رقم (٣) (جدول مصادر الطاقة المستعملة في لبنان):\nأ- حدّد مصدر الطاقة الذي يعتمد عليه لبنان بالدرجة الأولى، ونوعَي الوقود المستعمل فيه. (نصف علامة)\nب- استنتج مشكلة يعاني منها لبنان في تأمين الطاقة، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:38', '2026-10-01 03:15:38'),
(35954, 16932, 2, '٧- من خلال المستند رقم (٣) (جدول مصادر الطاقة المستعملة في لبنان):\nأ- حدّد مصدر الطاقة الذي يعتمد عليه لبنان بالدرجة الأولى، ونوعَي الوقود المستعمل فيه. (نصف علامة)\nب- استنتج مشكلة يعاني منها لبنان في تأمين الطاقة، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:38', '2026-10-01 03:15:38'),
(35955, 16933, 1, '٨- يشير المستند رقم (٣) إلى فقر لبنان بالنفط، ومع ذلك استطاعت المؤسّسات الصناعيّة اللبنانيّة أن تحقّق بعض التقدّم.\nأ- أوضح تدبيرين اتّخذتهما الدولة لتطوير المجال الصناعيّ. (علامة واحدة)\nب- اقترح خطوة عمليّة واحدة بإمكانك القيام بها لدعم القطاع الصناعيّ اللبنانيّ، معلّلًا اقتراحك. (علامة واحدة)', 1, '2026-10-01 03:15:39', '2026-10-01 03:15:39'),
(35956, 16933, 2, '٨- يشير المستند رقم (٣) إلى فقر لبنان بالنفط، ومع ذلك استطاعت المؤسّسات الصناعيّة اللبنانيّة أن تحقّق بعض التقدّم.\nأ- أوضح تدبيرين اتّخذتهما الدولة لتطوير المجال الصناعيّ. (علامة واحدة)\nب- اقترح خطوة عمليّة واحدة بإمكانك القيام بها لدعم القطاع الصناعيّ اللبنانيّ، معلّلًا اقتراحك. (علامة واحدة)', 1, '2026-10-01 03:15:39', '2026-10-01 03:15:39'),
(35957, 16934, 1, 'المستند رقم (٤): التجارة في الاقتصاد اللبنانيّ.\n«تؤمّن التجارة الترابط بين جميع المجالات الإنتاجيّة والخدماتيّة، وتشكّل إحدى الركائز المهمّة في البنية الاقتصاديّة اللبنانيّة، لكنّ هذا الارتكاز يجعل الاقتصاد اللبنانيّ غير مستقرّ وسريع التأثّر بالأوضاع السياسيّة المحلّيّة والإقليميّة والعالميّة. وتزدهر في لبنان أشكال متعدّدة من النشاط التجاريّ تنطلق معظمها من مدينة بيروت، منها الاستيراد والتصدير وتجارة المرور (الترانزيت) والتجارة المثلّثة وإعادة التصدير. غير أنّ لبنان يستورد من الخارج معظم حاجاته من المواد والسلع المختلفة، في حين تقتصر صادراته على بعض المحاصيل الزراعيّة وبعض المنتجات الصناعيّة الخفيفة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول التبادل مع الخارج والميزان التجاريّ في لبنان، مبيّنًا فيه:\n- مفهوم كلٍّ من تجارة المرور (الترانزيت) والتجارة المثلّثة. (علامة واحدة)\n- مفهوم الميزان التجاريّ، والصفة التي يتّصف بها في لبنان. (علامة واحدة)\n- أربعة أسباب للعجز في الميزان التجاريّ اللبنانيّ. (علامتان)\n- ثلاث نتائج لهذا العجز على ماليّة الدولة، مع توضيح العلاقة بين العجز والدين العامّ. (علامتان)', 1, '2026-10-01 03:15:39', '2026-10-01 03:15:39'),
(35958, 16934, 2, 'المستند رقم (٤): التجارة في الاقتصاد اللبنانيّ.\n«تؤمّن التجارة الترابط بين جميع المجالات الإنتاجيّة والخدماتيّة، وتشكّل إحدى الركائز المهمّة في البنية الاقتصاديّة اللبنانيّة، لكنّ هذا الارتكاز يجعل الاقتصاد اللبنانيّ غير مستقرّ وسريع التأثّر بالأوضاع السياسيّة المحلّيّة والإقليميّة والعالميّة. وتزدهر في لبنان أشكال متعدّدة من النشاط التجاريّ تنطلق معظمها من مدينة بيروت، منها الاستيراد والتصدير وتجارة المرور (الترانزيت) والتجارة المثلّثة وإعادة التصدير. غير أنّ لبنان يستورد من الخارج معظم حاجاته من المواد والسلع المختلفة، في حين تقتصر صادراته على بعض المحاصيل الزراعيّة وبعض المنتجات الصناعيّة الخفيفة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول التبادل مع الخارج والميزان التجاريّ في لبنان، مبيّنًا فيه:\n- مفهوم كلٍّ من تجارة المرور (الترانزيت) والتجارة المثلّثة. (علامة واحدة)\n- مفهوم الميزان التجاريّ، والصفة التي يتّصف بها في لبنان. (علامة واحدة)\n- أربعة أسباب للعجز في الميزان التجاريّ اللبنانيّ. (علامتان)\n- ثلاث نتائج لهذا العجز على ماليّة الدولة، مع توضيح العلاقة بين العجز والدين العامّ. (علامتان)', 1, '2026-10-01 03:15:39', '2026-10-01 03:15:39'),
(35959, 16935, 1, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول التبادل مع الخارج والميزان التجاريّ في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:39', '2026-10-01 03:15:39'),
(35960, 16935, 2, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول التبادل مع الخارج والميزان التجاريّ في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:39', '2026-10-01 03:15:39'),
(35961, 16936, 1, 'المستند رقم (١): خريطة لبنان السياحيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مغارة تُعدّ من روائع الطبيعة في لبنان — الصفّ ٣، العمود ٢.\n(٢) مصيفان شهيران متجاوران في الجزء الشماليّ من سلسلة جبال لبنان الغربيّة — الصفّ ٢، العمود ٣.\n(٣) مدينة ساحليّة جنوبيّة جرى فيها التعاون مع المنظّمات الدوليّة للتنقيب عن الآثار وحمايتها — الصفّ ٥، العمود ١.\n(٤) العاصمة، وقد اكتُشفت فيها آثار حديثًا — الصفّ ٣، العمود ٢.\n(أ) طريق جبليّ يزدحم مساء السبت وصباح الاثنين بحركة الترفيه الأسبوعيّة — الصفّ ٣، العمود ٢.\n(ب) ممرّ طبيعيّ يخترق سلسلة جبال لبنان الغربيّة ويصل المنطقة الساحليّة بالمنطقة الداخليّة — الصفّ ٢، العمود ٣.\n(ج) أعلى قمّة في القسم الشماليّ من سلسلة جبال لبنان الشرقيّة — الصفّ ٢، العمود ٤.\n\nمن خلال المستند رقم (١):\n١- اذكر اسم كلٍّ من:\nأ- المعالم المشار إليها بالأرقام (١، ٢، ٣). (ثلاثة أرباع العلامة)\nب- الطريق المشار إليه بالحرف (أ)، والممرّ المشار إليه بالحرف (ب). (نصف علامة)\nج- القمّة المشار إليها بالحرف (ج)، والقسم الجبليّ الذي تقع فيه. (نصف علامة)\nد- المدينة المشار إليها بالرقم (٤)، ونوع النشاط السياحيّ الذي يمارسه السائح حين يزور آثارها. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:40', '2026-10-01 03:15:40'),
(35962, 16936, 2, 'المستند رقم (١): خريطة لبنان السياحيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مغارة تُعدّ من روائع الطبيعة في لبنان — الصفّ ٣، العمود ٢.\n(٢) مصيفان شهيران متجاوران في الجزء الشماليّ من سلسلة جبال لبنان الغربيّة — الصفّ ٢، العمود ٣.\n(٣) مدينة ساحليّة جنوبيّة جرى فيها التعاون مع المنظّمات الدوليّة للتنقيب عن الآثار وحمايتها — الصفّ ٥، العمود ١.\n(٤) العاصمة، وقد اكتُشفت فيها آثار حديثًا — الصفّ ٣، العمود ٢.\n(أ) طريق جبليّ يزدحم مساء السبت وصباح الاثنين بحركة الترفيه الأسبوعيّة — الصفّ ٣، العمود ٢.\n(ب) ممرّ طبيعيّ يخترق سلسلة جبال لبنان الغربيّة ويصل المنطقة الساحليّة بالمنطقة الداخليّة — الصفّ ٢، العمود ٣.\n(ج) أعلى قمّة في القسم الشماليّ من سلسلة جبال لبنان الشرقيّة — الصفّ ٢، العمود ٤.\n\nمن خلال المستند رقم (١):\n١- اذكر اسم كلٍّ من:\nأ- المعالم المشار إليها بالأرقام (١، ٢، ٣). (ثلاثة أرباع العلامة)\nب- الطريق المشار إليه بالحرف (أ)، والممرّ المشار إليه بالحرف (ب). (نصف علامة)\nج- القمّة المشار إليها بالحرف (ج)، والقسم الجبليّ الذي تقع فيه. (نصف علامة)\nد- المدينة المشار إليها بالرقم (٤)، ونوع النشاط السياحيّ الذي يمارسه السائح حين يزور آثارها. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:40', '2026-10-01 03:15:40'),
(35963, 16937, 1, 'من خلال المستند رقم (١) (خريطة لبنان السياحيّة):\n٢- حدّد:\nأ- موقع مغارة جعيتا (١) بالنسبة إلى كلٍّ من المدينة (٣) والمصيفين (٢). (نصف علامة)\nب- الاتّجاه العامّ لامتداد سلسلة جبال لبنان الغربيّة. (نصف علامة)\nج- الاتّجاه العامّ لرحلة سياحيّة تنطلق من المدينة (٣) نحو العاصمة (٤). (نصف علامة)', 1, '2026-10-01 03:15:40', '2026-10-01 03:15:40'),
(35964, 16937, 2, 'من خلال المستند رقم (١) (خريطة لبنان السياحيّة):\n٢- حدّد:\nأ- موقع مغارة جعيتا (١) بالنسبة إلى كلٍّ من المدينة (٣) والمصيفين (٢). (نصف علامة)\nب- الاتّجاه العامّ لامتداد سلسلة جبال لبنان الغربيّة. (نصف علامة)\nج- الاتّجاه العامّ لرحلة سياحيّة تنطلق من المدينة (٣) نحو العاصمة (٤). (نصف علامة)', 1, '2026-10-01 03:15:40', '2026-10-01 03:15:40'),
(35965, 16938, 1, 'المستند رقم (٢):\n«المجال الصناعيّ في لبنان هو مجموع المؤسّسات الصناعيّة التي تنتج السلع، ويعمل فيها عدد كبير من اليد العاملة، وقد استطاعت هذه المؤسّسات أن تحقّق بعض التقدّم على الرغم من فقر البلاد بالنفط وبالمواد الأوّليّة عامّةً. وتستوعب المناطق الساحليّة القسم الأكبر من هذه المؤسّسات ومن اليد العاملة فيها، وتستأثر بيروت وضواحيها الممتدّة في محافظة جبل لبنان بالنصيب الأوفر منها، بينما تقلّ نسبة المؤسّسات كثيرًا في أقضية أخرى. وتقوم هذه المؤسّسات داخل مناطق صناعيّة محدّدة، أو في الأحياء السكنيّة داخل المدن، أو في المناطق الريفيّة، ومن أمثلتها مصنع الحديد الوحيد في عمشيت ومعمل غندور في طرابلس.\nأمّا الصناعات الحديثة والخفيفة، كالأدوية والإلكترونيّات والبرمجة المعلوماتيّة، فلا تزال ضعيفة في البلاد، مع أنّ السوق العربيّة بحاجة إلى منتجاتها، ومع أنّ تطويرها ممكن نظرًا لتوفّر الكفاءات العلميّة الضروريّة لذلك.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:40', '2026-10-01 03:15:40'),
(35966, 16938, 2, 'المستند رقم (٢):\n«المجال الصناعيّ في لبنان هو مجموع المؤسّسات الصناعيّة التي تنتج السلع، ويعمل فيها عدد كبير من اليد العاملة، وقد استطاعت هذه المؤسّسات أن تحقّق بعض التقدّم على الرغم من فقر البلاد بالنفط وبالمواد الأوّليّة عامّةً. وتستوعب المناطق الساحليّة القسم الأكبر من هذه المؤسّسات ومن اليد العاملة فيها، وتستأثر بيروت وضواحيها الممتدّة في محافظة جبل لبنان بالنصيب الأوفر منها، بينما تقلّ نسبة المؤسّسات كثيرًا في أقضية أخرى. وتقوم هذه المؤسّسات داخل مناطق صناعيّة محدّدة، أو في الأحياء السكنيّة داخل المدن، أو في المناطق الريفيّة، ومن أمثلتها مصنع الحديد الوحيد في عمشيت ومعمل غندور في طرابلس.\nأمّا الصناعات الحديثة والخفيفة، كالأدوية والإلكترونيّات والبرمجة المعلوماتيّة، فلا تزال ضعيفة في البلاد، مع أنّ السوق العربيّة بحاجة إلى منتجاتها، ومع أنّ تطويرها ممكن نظرًا لتوفّر الكفاءات العلميّة الضروريّة لذلك.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:40', '2026-10-01 03:15:40'),
(35967, 16939, 1, '٤- من خلال المستند رقم (٢) (نصّ حول المجال الصناعيّ في لبنان):\nأ- حدّد ثلاثة مواقع تقوم فيها المؤسّسات الصناعيّة اللبنانيّة. (ثلاثة أرباع العلامة)\nب- حدّد اثنتين من الصناعات الحديثة والخفيفة التي لا تزال ضعيفة في لبنان. (نصف علامة)\nج- استنتج ميزة يتّصف بها توزّع المؤسّسات الصناعيّة بين المناطق اللبنانيّة، مبرّرًا إجابتك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35968, 16939, 2, '٤- من خلال المستند رقم (٢) (نصّ حول المجال الصناعيّ في لبنان):\nأ- حدّد ثلاثة مواقع تقوم فيها المؤسّسات الصناعيّة اللبنانيّة. (ثلاثة أرباع العلامة)\nب- حدّد اثنتين من الصناعات الحديثة والخفيفة التي لا تزال ضعيفة في لبنان. (نصف علامة)\nج- استنتج ميزة يتّصف بها توزّع المؤسّسات الصناعيّة بين المناطق اللبنانيّة، مبرّرًا إجابتك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35969, 16940, 1, '٥- يشير المستند رقم (٢) إلى أنّ تطوير الصناعات الحديثة ممكن في لبنان. أوضح سببين يجعلان تنمية القطاع الصناعيّ أمرًا حيويًّا للبنان. (علامة واحدة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35970, 16940, 2, '٥- يشير المستند رقم (٢) إلى أنّ تطوير الصناعات الحديثة ممكن في لبنان. أوضح سببين يجعلان تنمية القطاع الصناعيّ أمرًا حيويًّا للبنان. (علامة واحدة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35971, 16941, 1, 'المستند رقم (٣-أ): توزّع المؤسّسات الصناعيّة اللبنانيّة حسب طبيعة الإنتاج.\n| طبيعة الإنتاج | النسبة من المؤسّسات (٪) | ملاحظة |\n| الصناعة التحويليّة | نحو ٧٨ | إنتاج متنوّع (صناعة غذائيّة، مواد بناء، صناعة كيماويّة...) |\n| أنواع أخرى | الباقي | — |\n\nالمستند رقم (٣-ب): المؤسّسات الصناعيّة اللبنانيّة حسب عدد العمّال.\n| عدد العمّال في المؤسّسة | حصّتها من مجموع المؤسّسات |\n| عدد قليل من العمّال | القسم الأكبر (الأكثريّة الساحقة) |\n| أكثر من ١٠ عمّال | قلّة من المؤسّسات |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة كلٍّ من المستندين (٣-أ) و(٣-ب)، وموضوع المستند (٣-ب). (علامة واحدة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35972, 16941, 2, 'المستند رقم (٣-أ): توزّع المؤسّسات الصناعيّة اللبنانيّة حسب طبيعة الإنتاج.\n| طبيعة الإنتاج | النسبة من المؤسّسات (٪) | ملاحظة |\n| الصناعة التحويليّة | نحو ٧٨ | إنتاج متنوّع (صناعة غذائيّة، مواد بناء، صناعة كيماويّة...) |\n| أنواع أخرى | الباقي | — |\n\nالمستند رقم (٣-ب): المؤسّسات الصناعيّة اللبنانيّة حسب عدد العمّال.\n| عدد العمّال في المؤسّسة | حصّتها من مجموع المؤسّسات |\n| عدد قليل من العمّال | القسم الأكبر (الأكثريّة الساحقة) |\n| أكثر من ١٠ عمّال | قلّة من المؤسّسات |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة كلٍّ من المستندين (٣-أ) و(٣-ب)، وموضوع المستند (٣-ب). (علامة واحدة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35973, 16942, 1, '٧- أ- حدّد وحدة القياس المستخدمة في المستند (٣-أ). (ربع علامة)\nب- استنتج من خلال المستند (٣-أ) ميزة تتّصف بها الصناعة اللبنانيّة من حيث طبيعة الإنتاج، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)\nج- استنتج من خلال المستند (٣-ب) ميزة تتّصف بها معظم المؤسّسات الصناعيّة اللبنانيّة من حيث الحجم، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35974, 16942, 2, '٧- أ- حدّد وحدة القياس المستخدمة في المستند (٣-أ). (ربع علامة)\nب- استنتج من خلال المستند (٣-أ) ميزة تتّصف بها الصناعة اللبنانيّة من حيث طبيعة الإنتاج، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)\nج- استنتج من خلال المستند (٣-ب) ميزة تتّصف بها معظم المؤسّسات الصناعيّة اللبنانيّة من حيث الحجم، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35975, 16943, 1, '٨- يشير المستندان (٣-أ) و(٣-ب) إلى القطاع الصناعيّ اللبنانيّ. أوضح:\nأ- دورين للقطاع الخاصّ في تطوير المجال الصناعيّ. (علامة واحدة)\nب- الإجراء الذي اتّجه إليه مجلس الوزراء لحماية مصنع الحديد الوطنيّ في عمشيت، وسبب ذلك. (نصف علامة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35976, 16943, 2, '٨- يشير المستندان (٣-أ) و(٣-ب) إلى القطاع الصناعيّ اللبنانيّ. أوضح:\nأ- دورين للقطاع الخاصّ في تطوير المجال الصناعيّ. (علامة واحدة)\nب- الإجراء الذي اتّجه إليه مجلس الوزراء لحماية مصنع الحديد الوطنيّ في عمشيت، وسبب ذلك. (نصف علامة)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35977, 16944, 1, 'المستند رقم (٤): اللبنانيّون بين الداخل والخارج.\n«بدأت الهجرة اللبنانيّة الحديثة منذ منتصف القرن التاسع عشر، عندما ضاقت سبل العيش أمام بعض اللبنانيّين، فاندفعوا نحو بقاع الأرض بحثًا عن وطن جديد وحياة أفضل. ومنذ ذلك الوقت تسارعت موجات الهجرة نحو الخارج متأثّرة بالأوضاع الاقتصاديّة والسياسيّة والأمنيّة السائدة في البلاد، ويُستدلّ من الأرقام المتوفّرة أنّ الذين غادروا لبنان خلال الأحداث الأخيرة بلغ عددهم أكثر من مليون لبنانيّ، بينهم علماء وأطبّاء ومهندسون. وقد عرف لبنان خلال الأحداث أيضًا حركة نزوح أخرى متشعّبة ومتشابكة هي حركة النزوح القسريّ. ومع ذلك، أبقى المغتربون على علاقاتهم الوطيدة بوطنهم وأهلهم.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول التحرّكات المكانيّة للسكّان في لبنان، مبيّنًا فيه:\n- مفهوم التحرّكات المكانيّة، وأنواعها الكبرى الثلاثة في لبنان. (علامة واحدة)\n- ثلاثة أسباب للهجرة اللبنانيّة نحو الخارج. (علامة ونصف)\n- مفهوم النزوح القسريّ، وأثرين له. (علامتان)\n- ثلاث فوائد يجنيها لبنان من مغتربيه. (علامة ونصف)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35978, 16944, 2, 'المستند رقم (٤): اللبنانيّون بين الداخل والخارج.\n«بدأت الهجرة اللبنانيّة الحديثة منذ منتصف القرن التاسع عشر، عندما ضاقت سبل العيش أمام بعض اللبنانيّين، فاندفعوا نحو بقاع الأرض بحثًا عن وطن جديد وحياة أفضل. ومنذ ذلك الوقت تسارعت موجات الهجرة نحو الخارج متأثّرة بالأوضاع الاقتصاديّة والسياسيّة والأمنيّة السائدة في البلاد، ويُستدلّ من الأرقام المتوفّرة أنّ الذين غادروا لبنان خلال الأحداث الأخيرة بلغ عددهم أكثر من مليون لبنانيّ، بينهم علماء وأطبّاء ومهندسون. وقد عرف لبنان خلال الأحداث أيضًا حركة نزوح أخرى متشعّبة ومتشابكة هي حركة النزوح القسريّ. ومع ذلك، أبقى المغتربون على علاقاتهم الوطيدة بوطنهم وأهلهم.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول التحرّكات المكانيّة للسكّان في لبنان، مبيّنًا فيه:\n- مفهوم التحرّكات المكانيّة، وأنواعها الكبرى الثلاثة في لبنان. (علامة واحدة)\n- ثلاثة أسباب للهجرة اللبنانيّة نحو الخارج. (علامة ونصف)\n- مفهوم النزوح القسريّ، وأثرين له. (علامتان)\n- ثلاث فوائد يجنيها لبنان من مغتربيه. (علامة ونصف)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35979, 16945, 1, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول التحرّكات المكانيّة للسكّان في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35980, 16945, 2, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول التحرّكات المكانيّة للسكّان في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:41', '2026-10-01 03:15:41'),
(35981, 16946, 1, 'المستند رقم (١): خريطة لبنان الزراعيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مدينة ساحليّة كبرى في الجنوب، شهدت القرى القريبة منها تحوّلًا شديدًا حتّى فقد بعضها مظاهره القرويّة وصار جزءًا منها — الصفّ ٤، العمود ١.\n(٢) سهل واسع في المنطقة الداخليّة، روى مشروع الريّ (٤) بعض أراضيه — من الصفّ ٢ إلى الصفّ ٤، في العمودين ٣ و٤.\n(٣) مشروع ريّ كبير نفّذته الدولة في الجنوب — الصفّ ٥، العمود ١.\n(٤) مشروع ريّ كبير نفّذته الدولة وروى بعض أراضي البقاع — الصفّ ٢، العمود ٣.\n(أ) موقع مركز الأبحاث العلميّة الزراعيّة التابع للدولة — الصفّ ٣، العمود ٢.\n(ب) منطقة تراجعت فيها الزراعات الممنوعة في مطلع التسعينات، وحلّت محلّها زراعة الشمندر السكّريّ ودوّار الشمس — الصفّ ٢، العمود ٤.\n(ج) بلدة في البقاع فيها معهد الهندسة الزراعيّة التابع لجامعة القدّيس يوسف — الصفّ ٣، العمود ٣.\n\nمن خلال المستند رقم (١):\n١- اكتب اسم كلٍّ من:\nأ- المدينة والسهل المشار إليهما بالرقمين (١، ٢). (نصف علامة)\nب- مشروعَي الريّ المشار إليهما بالرقمين (٣، ٤). (نصف علامة)\nج- الموقع المشار إليه بالحرف (أ)، والمنطقة المشار إليها بالحرف (ب). (نصف علامة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35982, 16946, 2, 'المستند رقم (١): خريطة لبنان الزراعيّة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مدينة ساحليّة كبرى في الجنوب، شهدت القرى القريبة منها تحوّلًا شديدًا حتّى فقد بعضها مظاهره القرويّة وصار جزءًا منها — الصفّ ٤، العمود ١.\n(٢) سهل واسع في المنطقة الداخليّة، روى مشروع الريّ (٤) بعض أراضيه — من الصفّ ٢ إلى الصفّ ٤، في العمودين ٣ و٤.\n(٣) مشروع ريّ كبير نفّذته الدولة في الجنوب — الصفّ ٥، العمود ١.\n(٤) مشروع ريّ كبير نفّذته الدولة وروى بعض أراضي البقاع — الصفّ ٢، العمود ٣.\n(أ) موقع مركز الأبحاث العلميّة الزراعيّة التابع للدولة — الصفّ ٣، العمود ٢.\n(ب) منطقة تراجعت فيها الزراعات الممنوعة في مطلع التسعينات، وحلّت محلّها زراعة الشمندر السكّريّ ودوّار الشمس — الصفّ ٢، العمود ٤.\n(ج) بلدة في البقاع فيها معهد الهندسة الزراعيّة التابع لجامعة القدّيس يوسف — الصفّ ٣، العمود ٣.\n\nمن خلال المستند رقم (١):\n١- اكتب اسم كلٍّ من:\nأ- المدينة والسهل المشار إليهما بالرقمين (١، ٢). (نصف علامة)\nب- مشروعَي الريّ المشار إليهما بالرقمين (٣، ٤). (نصف علامة)\nج- الموقع المشار إليه بالحرف (أ)، والمنطقة المشار إليها بالحرف (ب). (نصف علامة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35983, 16947, 1, 'من خلال المستند رقم (١) (خريطة لبنان الزراعيّة):\n٢- حدّد:\nأ- موقع المنطقة (ب) بالنسبة إلى كلٍّ من مشروع الريّ (٣) والموقع (أ). (علامة واحدة)\nب- الاتّجاه العامّ لانحدار السطح الجنوبيّ لسهل البقاع انطلاقًا من منطقة بعلبك. (نصف علامة)\nج- اتّجاه شاحنة تنقل بذورًا محسّنة من الموقع (أ) إلى البلدة (ج)، ثمّ اتّجاهها من البلدة (ج) إلى منطقة مشروع الريّ (٤). (علامة واحدة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35984, 16947, 2, 'من خلال المستند رقم (١) (خريطة لبنان الزراعيّة):\n٢- حدّد:\nأ- موقع المنطقة (ب) بالنسبة إلى كلٍّ من مشروع الريّ (٣) والموقع (أ). (علامة واحدة)\nب- الاتّجاه العامّ لانحدار السطح الجنوبيّ لسهل البقاع انطلاقًا من منطقة بعلبك. (نصف علامة)\nج- اتّجاه شاحنة تنقل بذورًا محسّنة من الموقع (أ) إلى البلدة (ج)، ثمّ اتّجاهها من البلدة (ج) إلى منطقة مشروع الريّ (٤). (علامة واحدة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35985, 16948, 1, 'المستند رقم (٢):\n«تلازمت حركة تبادل البضائع مع نشأة جميع المدن اللبنانيّة، ثمّ اتّسع نطاق هذا التبادل ليشمل العالم الخارجيّ. فلبنان يستورد سلعًا ومواد أوّليّة مختلفة، ويصدّر الفائض من منتجاته الزراعيّة. وتتمّ عبر مرفأَي بيروت وطرابلس حركة تجاريّة تعبر فيها البضائع الواردة من الدول المصدِّرة إلى الدول العربيّة، كما تتمّ الحركة باتّجاه معاكس، ويستوفي لبنان منها رسم المرفأ أو رسوم المرور. ويلعب التاجر اللبنانيّ أحيانًا دور الوسيط بتأمين الاتّصالات وعقد الصفقات، فتنتقل البضائع من البلدان المصدِّرة إلى البلدان المستهلكة من دون المرور بلبنان، بعد أن يأخذ نصيبه من الأرباح. وقد يستورد التاجر البضائع ثمّ يخزّنها لفترة زمنيّة معيّنة في المناطق الحرّة في لبنان لقاء رسوم زهيدة، ثمّ يعيد تصديرها إلى البلدان المستهلكة. ومعظم هذه الأنشطة ينطلق من مدينة بيروت، ويمتدّ عبر شبكات متشعّبة إلى كافّة المناطق اللبنانيّة وإلى البلدان العربيّة المجاورة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد موضوع المستند رقم (٢). (نصف علامة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35986, 16948, 2, 'المستند رقم (٢):\n«تلازمت حركة تبادل البضائع مع نشأة جميع المدن اللبنانيّة، ثمّ اتّسع نطاق هذا التبادل ليشمل العالم الخارجيّ. فلبنان يستورد سلعًا ومواد أوّليّة مختلفة، ويصدّر الفائض من منتجاته الزراعيّة. وتتمّ عبر مرفأَي بيروت وطرابلس حركة تجاريّة تعبر فيها البضائع الواردة من الدول المصدِّرة إلى الدول العربيّة، كما تتمّ الحركة باتّجاه معاكس، ويستوفي لبنان منها رسم المرفأ أو رسوم المرور. ويلعب التاجر اللبنانيّ أحيانًا دور الوسيط بتأمين الاتّصالات وعقد الصفقات، فتنتقل البضائع من البلدان المصدِّرة إلى البلدان المستهلكة من دون المرور بلبنان، بعد أن يأخذ نصيبه من الأرباح. وقد يستورد التاجر البضائع ثمّ يخزّنها لفترة زمنيّة معيّنة في المناطق الحرّة في لبنان لقاء رسوم زهيدة، ثمّ يعيد تصديرها إلى البلدان المستهلكة. ومعظم هذه الأنشطة ينطلق من مدينة بيروت، ويمتدّ عبر شبكات متشعّبة إلى كافّة المناطق اللبنانيّة وإلى البلدان العربيّة المجاورة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد موضوع المستند رقم (٢). (نصف علامة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42');
INSERT INTO `questions_translations` (`id`, `question_id`, `language_id`, `question_text`, `is_active`, `created_at`, `updated_at`) VALUES
(35987, 16949, 1, '٤- من خلال المستند رقم (٢) (نصّ حول التبادل التجاريّ مع الخارج):\nأ- حدّد ما يستورده لبنان وما يصدّره. (علامة واحدة)\nب- بيّن ثلاثة أشكال من النشاط التجاريّ مع الخارج يشير إليها المستند. (ثلاثة أرباع العلامة)\nج- استنتج أهمّيّة مرفأَي بيروت وطرابلس في التبادل التجاريّ مع الخارج، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35988, 16949, 2, '٤- من خلال المستند رقم (٢) (نصّ حول التبادل التجاريّ مع الخارج):\nأ- حدّد ما يستورده لبنان وما يصدّره. (علامة واحدة)\nب- بيّن ثلاثة أشكال من النشاط التجاريّ مع الخارج يشير إليها المستند. (ثلاثة أرباع العلامة)\nج- استنتج أهمّيّة مرفأَي بيروت وطرابلس في التبادل التجاريّ مع الخارج، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:42', '2026-10-01 03:15:42'),
(35989, 16950, 1, '٥- يشير المستند رقم (٢) إلى تلازم حركة تبادل البضائع مع نشأة المدن اللبنانيّة. أوضح:\nأ- الوظيفة التي أسهمت بشكل مباشر في نشأة معظم المدن اللبنانيّة. (نصف علامة)\nب- سبب الدور الاستقطابيّ البارز الذي تنفرد به مدينة بيروت. (نصف علامة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35990, 16950, 2, '٥- يشير المستند رقم (٢) إلى تلازم حركة تبادل البضائع مع نشأة المدن اللبنانيّة. أوضح:\nأ- الوظيفة التي أسهمت بشكل مباشر في نشأة معظم المدن اللبنانيّة. (نصف علامة)\nب- سبب الدور الاستقطابيّ البارز الذي تنفرد به مدينة بيروت. (نصف علامة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35991, 16951, 1, 'المستند رقم (٣): تحوّلات في توزّع المساحات المزروعة في لبنان.\n| المزروعات | التحوّل في المساحة المزروعة |\n| الحبوب | تراجعت إلى النصف تقريبًا |\n| الزيتون | ازدادت |\n| الزراعات الصناعيّة الأخرى | ازدادت |\n| الزراعات الممنوعة في البقاع الشماليّ | تراجعت في مطلع التسعينات، وحلّت محلّها زراعة الشمندر السكّريّ ودوّار الشمس |\n| الزراعة المحميّة المكيّفة | انتشرت بسرعة قرب المدن حتّى تجاوزت ٣٠٠٠ هكتار |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35992, 16951, 2, 'المستند رقم (٣): تحوّلات في توزّع المساحات المزروعة في لبنان.\n| المزروعات | التحوّل في المساحة المزروعة |\n| الحبوب | تراجعت إلى النصف تقريبًا |\n| الزيتون | ازدادت |\n| الزراعات الصناعيّة الأخرى | ازدادت |\n| الزراعات الممنوعة في البقاع الشماليّ | تراجعت في مطلع التسعينات، وحلّت محلّها زراعة الشمندر السكّريّ ودوّار الشمس |\n| الزراعة المحميّة المكيّفة | انتشرت بسرعة قرب المدن حتّى تجاوزت ٣٠٠٠ هكتار |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35993, 16952, 1, '٧- من خلال المستند رقم (٣) (جدول التحوّلات في توزّع المساحات المزروعة في لبنان):\nأ- حدّد وحدة القياس المستخدمة فيه. (نصف علامة)\nب- استنتج الاتّجاه العامّ لتطوّر المساحات المخصّصة للزراعات الصناعيّة في لبنان، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35994, 16952, 2, '٧- من خلال المستند رقم (٣) (جدول التحوّلات في توزّع المساحات المزروعة في لبنان):\nأ- حدّد وحدة القياس المستخدمة فيه. (نصف علامة)\nب- استنتج الاتّجاه العامّ لتطوّر المساحات المخصّصة للزراعات الصناعيّة في لبنان، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35995, 16953, 1, '٨- يشير المستند رقم (٣) إلى انتشار الزراعة المحميّة المكيّفة في لبنان. أوضح:\nأ- مفهوم الزراعة المحميّة المكيّفة، وسبب لجوء المزارع إليها. (علامة واحدة)\nب- دورًا واحدًا للقطاع الخاصّ ساعد في انتشار هذه الزراعة. (نصف علامة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35996, 16953, 2, '٨- يشير المستند رقم (٣) إلى انتشار الزراعة المحميّة المكيّفة في لبنان. أوضح:\nأ- مفهوم الزراعة المحميّة المكيّفة، وسبب لجوء المزارع إليها. (علامة واحدة)\nب- دورًا واحدًا للقطاع الخاصّ ساعد في انتشار هذه الزراعة. (نصف علامة)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35997, 16954, 1, 'المستند رقم (٤-أ): موقع لبنان.\n| الموقع الفلكيّ | بين خطَّي طول شرق خطّ غرينيتش، وبين دائرتَي عرض شمال خطّ الاستواء |\n| الموقع النسبيّ | على الساحل الشرقيّ للبحر المتوسّط (في الحوض الشرقيّ منه)، في ملتقى قارّات العالم القديم: آسيا وأفريقيا وأوروبا |\n| الانتماء | بلد من العالم العربيّ، يقع في منطقة الشرق الأوسط |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\nالمستند رقم (٤-ب):\n«في خطاب ألقاه رئيس الجمهوريّة اللبنانيّة العماد إميل لحود في اختتام القمّة الثامنة للدول الفرنكوفونيّة التي عُقدت في كندا، وصف لبنان بأنّه نقطة الشرق الأوسط على البحر المتوسّط، وبأنّه بطبيعته بلد انفتاح، وبأنّ اللبنانيّين أصحاب مسؤوليّة خاصّة.»\nالمصدر: مستند من كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستندين (٤-أ) و(٤-ب) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول موقع لبنان وأهمّيّته، مبيّنًا فيه:\n- موقع لبنان الفلكيّ وأثره في المناخ، وموقعه بالنسبة إلى القارّات والبحر المتوسّط. (علامة ونصف)\n- شكل لبنان وامتداد شاطئه. (علامة واحدة)\n- ثلاثة مظاهر للأهمّيّة الاستراتيجيّة لموقع لبنان. (علامة ونصف)\n- أربع نتائج اقتصاديّة لموقع لبنان. (علامتان)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35998, 16954, 2, 'المستند رقم (٤-أ): موقع لبنان.\n| الموقع الفلكيّ | بين خطَّي طول شرق خطّ غرينيتش، وبين دائرتَي عرض شمال خطّ الاستواء |\n| الموقع النسبيّ | على الساحل الشرقيّ للبحر المتوسّط (في الحوض الشرقيّ منه)، في ملتقى قارّات العالم القديم: آسيا وأفريقيا وأوروبا |\n| الانتماء | بلد من العالم العربيّ، يقع في منطقة الشرق الأوسط |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\nالمستند رقم (٤-ب):\n«في خطاب ألقاه رئيس الجمهوريّة اللبنانيّة العماد إميل لحود في اختتام القمّة الثامنة للدول الفرنكوفونيّة التي عُقدت في كندا، وصف لبنان بأنّه نقطة الشرق الأوسط على البحر المتوسّط، وبأنّه بطبيعته بلد انفتاح، وبأنّ اللبنانيّين أصحاب مسؤوليّة خاصّة.»\nالمصدر: مستند من كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستندين (٤-أ) و(٤-ب) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول موقع لبنان وأهمّيّته، مبيّنًا فيه:\n- موقع لبنان الفلكيّ وأثره في المناخ، وموقعه بالنسبة إلى القارّات والبحر المتوسّط. (علامة ونصف)\n- شكل لبنان وامتداد شاطئه. (علامة واحدة)\n- ثلاثة مظاهر للأهمّيّة الاستراتيجيّة لموقع لبنان. (علامة ونصف)\n- أربع نتائج اقتصاديّة لموقع لبنان. (علامتان)', 1, '2026-10-01 03:15:43', '2026-10-01 03:15:43'),
(35999, 16955, 1, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول موقع لبنان وأهمّيّته): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:44', '2026-10-01 03:15:44'),
(36000, 16955, 2, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول موقع لبنان وأهمّيّته): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:44', '2026-10-01 03:15:44'),
(36001, 16956, 1, 'المستند رقم (١): خريطة لبنان: مواقع صناعيّة وطاقة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مصفاة نفط في مدينة ساحليّة شماليّة، توقّف فيها التكرير منذ مطلع الثمانينات — الصفّ ١، العمود ٣.\n(٢) مصفاة نفط على الساحل الجنوبيّ، توقّف فيها التكرير منذ مطلع الثمانينات — الصفّ ٥، العمود ١.\n(٣) بلدة ساحليّة فيها مصنع الحديد الوحيد في لبنان — الصفّ ٢، العمود ٢.\n(٤) مدينة ساحليّة جنوبيّة يتّسع عندها السهل الساحليّ، وتقع إلى الشمال من المصفاة (٢) — الصفّ ٤، العمود ١.\n(٥) مدينة بيروت — الصفّ ٣، العمود ٢.\n(أ) سهل يقع خارج الحدود اللبنانيّة، يتّصل به السطح الشماليّ لسهل البقاع — إلى الشمال من الصفّ ١، العمود ٤.\nتقع المعالم (١) و(٢) و(٣) و(٤) و(٥) كلّها في الوحدة التضاريسيّة الممتدّة على طول البحر.\n\nمن خلال المستند رقم (١):\n١- اذكر:\nأ- اسمَي المصفاتين المشار إليهما بالرقمين (١، ٢). (علامة واحدة)\nب- اسمَي البلدة والمدينة المشار إليهما بالرقمين (٣، ٤). (علامة واحدة)\nج- اسم السهل المشار إليه بالحرف (أ)، واسم البلد الذي يقع فيه. (نصف علامة)\nد- اسم الوحدة التضاريسيّة التي تقع فيها المعالم (١، ٢، ٣، ٤، ٥). (نصف علامة)', 1, '2026-10-01 03:15:44', '2026-10-01 03:15:44'),
(36002, 16956, 2, 'المستند رقم (١): خريطة لبنان: مواقع صناعيّة وطاقة.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(١) مصفاة نفط في مدينة ساحليّة شماليّة، توقّف فيها التكرير منذ مطلع الثمانينات — الصفّ ١، العمود ٣.\n(٢) مصفاة نفط على الساحل الجنوبيّ، توقّف فيها التكرير منذ مطلع الثمانينات — الصفّ ٥، العمود ١.\n(٣) بلدة ساحليّة فيها مصنع الحديد الوحيد في لبنان — الصفّ ٢، العمود ٢.\n(٤) مدينة ساحليّة جنوبيّة يتّسع عندها السهل الساحليّ، وتقع إلى الشمال من المصفاة (٢) — الصفّ ٤، العمود ١.\n(٥) مدينة بيروت — الصفّ ٣، العمود ٢.\n(أ) سهل يقع خارج الحدود اللبنانيّة، يتّصل به السطح الشماليّ لسهل البقاع — إلى الشمال من الصفّ ١، العمود ٤.\nتقع المعالم (١) و(٢) و(٣) و(٤) و(٥) كلّها في الوحدة التضاريسيّة الممتدّة على طول البحر.\n\nمن خلال المستند رقم (١):\n١- اذكر:\nأ- اسمَي المصفاتين المشار إليهما بالرقمين (١، ٢). (علامة واحدة)\nب- اسمَي البلدة والمدينة المشار إليهما بالرقمين (٣، ٤). (علامة واحدة)\nج- اسم السهل المشار إليه بالحرف (أ)، واسم البلد الذي يقع فيه. (نصف علامة)\nد- اسم الوحدة التضاريسيّة التي تقع فيها المعالم (١، ٢، ٣، ٤، ٥). (نصف علامة)', 1, '2026-10-01 03:15:44', '2026-10-01 03:15:44'),
(36003, 16957, 1, 'من خلال المستند رقم (١) (خريطة لبنان: مواقع صناعيّة وطاقة):\n٢- حدّد:\nأ- موقع المصفاة (٢) بالنسبة إلى المصفاة (١). (نصف علامة)\nب- الاتّجاه العامّ لشاحنة تنقل الحديد من المصنع في البلدة (٣) إلى مدينة بيروت (٥). (نصف علامة)', 1, '2026-10-01 03:15:44', '2026-10-01 03:15:44'),
(36004, 16957, 2, 'من خلال المستند رقم (١) (خريطة لبنان: مواقع صناعيّة وطاقة):\n٢- حدّد:\nأ- موقع المصفاة (٢) بالنسبة إلى المصفاة (١). (نصف علامة)\nب- الاتّجاه العامّ لشاحنة تنقل الحديد من المصنع في البلدة (٣) إلى مدينة بيروت (٥). (نصف علامة)', 1, '2026-10-01 03:15:44', '2026-10-01 03:15:44'),
(36005, 16958, 1, 'المستند رقم (٢):\n«عانت الزراعة في لبنان من أزمة حادّة على صعيد الإنتاج وعلى صعيد تصريفه، وزاد التوسّع العمرانيّ من ضيق المجالات الزراعيّة. وبعد أن بقيت الزراعة لفترة طويلة تعتمد تقنيات تقليديّة، بدأ التحديث يدخل إليها: فاستُعملت الآلة في الحراثة والبذار والحصاد، واعتُمد الريّ بالرشّ والريّ بالتنقيط الذي يؤمّن المياه نقطة نقطة إلى النبتة بواسطة شبكة من الأنابيب، وأُجريت في المختبرات عمليّات لتأصيل البذور والشتول، واعتُمدت المعالجات البيولوجيّة بدل المعالجات الكيماويّة في وقاية النباتات. وصار بعض المزارعين يخزّنون محاصيلهم في برّادات خاصّة، ثمّ يطرحونها في السوق في الوقت المناسب.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36006, 16958, 2, 'المستند رقم (٢):\n«عانت الزراعة في لبنان من أزمة حادّة على صعيد الإنتاج وعلى صعيد تصريفه، وزاد التوسّع العمرانيّ من ضيق المجالات الزراعيّة. وبعد أن بقيت الزراعة لفترة طويلة تعتمد تقنيات تقليديّة، بدأ التحديث يدخل إليها: فاستُعملت الآلة في الحراثة والبذار والحصاد، واعتُمد الريّ بالرشّ والريّ بالتنقيط الذي يؤمّن المياه نقطة نقطة إلى النبتة بواسطة شبكة من الأنابيب، وأُجريت في المختبرات عمليّات لتأصيل البذور والشتول، واعتُمدت المعالجات البيولوجيّة بدل المعالجات الكيماويّة في وقاية النباتات. وصار بعض المزارعين يخزّنون محاصيلهم في برّادات خاصّة، ثمّ يطرحونها في السوق في الوقت المناسب.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36007, 16959, 1, '٤- من خلال المستند رقم (٢) (نصّ حول تحديث التقنيات الزراعيّة في لبنان):\nأ- حدّد نوعَي الريّ الحديث الواردين في المستند. (نصف علامة)\nب- بيّن المقصود بتأصيل البذور والشتول، والميزة التي يتّصف بها الريّ بالتنقيط. (علامة واحدة)\nج- استنتج أثر تخزين المحاصيل في برّادات خاصّة على تصريف الإنتاج الزراعيّ، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36008, 16959, 2, '٤- من خلال المستند رقم (٢) (نصّ حول تحديث التقنيات الزراعيّة في لبنان):\nأ- حدّد نوعَي الريّ الحديث الواردين في المستند. (نصف علامة)\nب- بيّن المقصود بتأصيل البذور والشتول، والميزة التي يتّصف بها الريّ بالتنقيط. (علامة واحدة)\nج- استنتج أثر تخزين المحاصيل في برّادات خاصّة على تصريف الإنتاج الزراعيّ، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36009, 16960, 1, '٥- يشير المستند رقم (٢) إلى انتقال الزراعة في لبنان من تقنيات تقليديّة إلى تقنيات حديثة.\nقارن بين التقنيات التقليديّة والتقنيات الحديثة من حيث وقاية النبات ومن حيث مكان الزراعة. (علامة واحدة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36010, 16960, 2, '٥- يشير المستند رقم (٢) إلى انتقال الزراعة في لبنان من تقنيات تقليديّة إلى تقنيات حديثة.\nقارن بين التقنيات التقليديّة والتقنيات الحديثة من حيث وقاية النبات ومن حيث مكان الزراعة. (علامة واحدة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36011, 16961, 1, 'المستند رقم (٣): أشكال التحرّكات الدوريّة للسكّان في لبنان.\n| الشكل | التكرار | من يمارسه | الوجهة | مثال |\n| حركة العمل | يوميّة | العاملون | صباحًا من المحافظات نحو بيروت ومراكز المحافظات، ومساءً في الاتّجاه المعاكس | زحمة سير خانقة على مداخل بيروت صباحًا ومساءً |\n| حركة الترفيه | أسبوعيّة (عطلة نهاية الأسبوع) | فئة معيّنة من سكّان بيروت والمدن الأخرى | القرى والمدن الأصليّة، أو أماكن الترفيه الساحليّة والجبليّة | ازدحام طريق ضهر البيدر مساء السبت وصباح الاثنين |\n| حركة الاستجمام | موسميّة (فصل الصيف والعطل الطويلة) | ذوو المداخيل المرتفعة | داخل البلاد أو خارجها | — |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36012, 16961, 2, 'المستند رقم (٣): أشكال التحرّكات الدوريّة للسكّان في لبنان.\n| الشكل | التكرار | من يمارسه | الوجهة | مثال |\n| حركة العمل | يوميّة | العاملون | صباحًا من المحافظات نحو بيروت ومراكز المحافظات، ومساءً في الاتّجاه المعاكس | زحمة سير خانقة على مداخل بيروت صباحًا ومساءً |\n| حركة الترفيه | أسبوعيّة (عطلة نهاية الأسبوع) | فئة معيّنة من سكّان بيروت والمدن الأخرى | القرى والمدن الأصليّة، أو أماكن الترفيه الساحليّة والجبليّة | ازدحام طريق ضهر البيدر مساء السبت وصباح الاثنين |\n| حركة الاستجمام | موسميّة (فصل الصيف والعطل الطويلة) | ذوو المداخيل المرتفعة | داخل البلاد أو خارجها | — |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة المستند رقم (٣)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36013, 16962, 1, '٧- من خلال المستند رقم (٣) (جدول أشكال التحرّكات الدوريّة للسكّان في لبنان):\nأ- حدّد الفئة التي تمارس حركة الاستجمام، والفترة التي تمارسها فيها. (نصف علامة)\nب- استنتج الصفة المشتركة بين أشكال التحرّكات الواردة في المستند، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36014, 16962, 2, '٧- من خلال المستند رقم (٣) (جدول أشكال التحرّكات الدوريّة للسكّان في لبنان):\nأ- حدّد الفئة التي تمارس حركة الاستجمام، والفترة التي تمارسها فيها. (نصف علامة)\nب- استنتج الصفة المشتركة بين أشكال التحرّكات الواردة في المستند، مبرّرًا استنتاجك بالدليل المناسب. (علامة واحدة)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36015, 16963, 1, '٨- يشير المستند رقم (٣) إلى زحمة السير الخانقة على مداخل بيروت صباحًا ومساءً.\nأوضح سبب اتّجاه حركة العمل اليوميّة نحو بيروت بالدرجة الأولى، ثمّ قارن بين حركة العمل اليوميّة والنزوح الريفيّ من حيث الدافع ومن حيث الأثر. (علامة ونصف)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36016, 16963, 2, '٨- يشير المستند رقم (٣) إلى زحمة السير الخانقة على مداخل بيروت صباحًا ومساءً.\nأوضح سبب اتّجاه حركة العمل اليوميّة نحو بيروت بالدرجة الأولى، ثمّ قارن بين حركة العمل اليوميّة والنزوح الريفيّ من حيث الدافع ومن حيث الأثر. (علامة ونصف)', 1, '2026-10-01 03:15:45', '2026-10-01 03:15:45'),
(36017, 16964, 1, 'المستند رقم (٤): السياحة في لبنان.\n«تتنوّع النشاطات التي يمارسها السيّاح في لبنان، ويسمح قرب الشواطئ من الجبال أحيانًا بممارسة هوايتين متميّزتين في اليوم نفسه، هما السباحة والتزلّج. ولا تقتصر مقوّمات السياحة في لبنان على الطبيعة، فقد تركت الحضارات القديمة فيه آثارًا كثيرة، ومنها الآثار المكتشفة حديثًا في مدينة بيروت، كما أنّ للإنسان اللبنانيّ دورًا أساسيًّا في تنشيط الحركة السياحيّة. غير أنّ للنشاط السياحيّ وجهين: فهو يُنعش الاقتصاد من جهة، ويتطلّب من جهة أخرى خلق مناطق اصطناعيّة ضمن مناطق طبيعيّة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول النشاط السياحيّ في لبنان، مبيّنًا فيه:\n- أنواع النشاط السياحيّ الأربعة في لبنان، مع مثال واحد لكلّ نوع. (علامتان)\n- مقوّمين بشريّين للسياحة في لبنان. (علامة واحدة)\n- انعكاسين إيجابيّين وانعكاسين سلبيّين للنشاط السياحيّ. (علامتان)\n- مقوّمين من المقوّمات التاريخيّة والعمرانيّة والاقتصاديّة للسياحة في لبنان. (علامة واحدة)', 1, '2026-10-01 03:15:46', '2026-10-01 03:15:46'),
(36018, 16964, 2, 'المستند رقم (٤): السياحة في لبنان.\n«تتنوّع النشاطات التي يمارسها السيّاح في لبنان، ويسمح قرب الشواطئ من الجبال أحيانًا بممارسة هوايتين متميّزتين في اليوم نفسه، هما السباحة والتزلّج. ولا تقتصر مقوّمات السياحة في لبنان على الطبيعة، فقد تركت الحضارات القديمة فيه آثارًا كثيرة، ومنها الآثار المكتشفة حديثًا في مدينة بيروت، كما أنّ للإنسان اللبنانيّ دورًا أساسيًّا في تنشيط الحركة السياحيّة. غير أنّ للنشاط السياحيّ وجهين: فهو يُنعش الاقتصاد من جهة، ويتطلّب من جهة أخرى خلق مناطق اصطناعيّة ضمن مناطق طبيعيّة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول النشاط السياحيّ في لبنان، مبيّنًا فيه:\n- أنواع النشاط السياحيّ الأربعة في لبنان، مع مثال واحد لكلّ نوع. (علامتان)\n- مقوّمين بشريّين للسياحة في لبنان. (علامة واحدة)\n- انعكاسين إيجابيّين وانعكاسين سلبيّين للنشاط السياحيّ. (علامتان)\n- مقوّمين من المقوّمات التاريخيّة والعمرانيّة والاقتصاديّة للسياحة في لبنان. (علامة واحدة)', 1, '2026-10-01 03:15:46', '2026-10-01 03:15:46'),
(36019, 16965, 1, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول النشاط السياحيّ في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:46', '2026-10-01 03:15:46'),
(36020, 16965, 2, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول النشاط السياحيّ في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:46', '2026-10-01 03:15:46'),
(36021, 16966, 1, 'المستند رقم (١): خريطة لبنان: مصايف ومدن وجبال.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(أ) الجزء الأوسط والجنوبيّ من سلسلة جبال لبنان الغربيّة، تنتشر فيه مصايف شهيرة — الصفوف ٣ و٤، العمود ٢.\n(١) مركزا تزلّج مهمّان في سلسلة جبال لبنان الغربيّة — الصفّ ٢، العمود ٣.\n(ب) جبل يفصل سهل البقاع عن سهل مرجعيون — الصفّ ٥، العمود ٢.\n(ج) جبل يحصر مع جبل الشيخ ومع الجبل (ب) هضاب وادي التيم — الصفّ ٥، العمود ٢.\n(٢) مدينة كبرى في المنطقة الداخليّة، شهدت القرى القريبة منها تحوّلًا شديدًا — الصفّ ٣، العمود ٣.\n(٣) مدينة كبرى ساحليّة في الشمال، شهدت القرى القريبة منها تحوّلًا شديدًا — الصفّ ١، العمود ٣.\n(٤) مدينة بيروت — الصفّ ٣، العمود ٢.\n\nمن خلال المستند رقم (١):\n١- اذكر:\nأ- ثلاثة من المصايف الشهيرة الواقعة في المنطقة المشار إليها بالحرف (أ). (ثلاثة أرباع العلامة)\nب- اسمَي مركزَي التزلّج المشار إليهما بالرقم (١). (نصف علامة)\nج- اسمَي الجبلين المشار إليهما بالحرفين (ب، ج). (نصف علامة)\nد- اسمَي المدينتين المشار إليهما بالرقمين (٢، ٣)، واسم التحوّل الذي أصاب القرى القريبة منهما. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36022, 16966, 2, 'المستند رقم (١): خريطة لبنان: مصايف ومدن وجبال.\n(وصف مكتوب للخريطة) قُسِّمت خريطة لبنان إلى شبكة مربّعات: الصفوف مرقّمة من الشمال إلى الجنوب (الصفّ ١ في أعلى الخريطة والصفّ ٥ في أسفلها)، والأعمدة مرقّمة من الغرب إلى الشرق (العمود ١ عند البحر المتوسّط والعمود ٤ عند أقصى الشرق). سهم الشمال يتّجه إلى أعلى الخريطة. يُحدَّد موقع كلّ معلم برقم الصفّ ورقم العمود.\nالمعالم المرسومة على الخريطة:\n(أ) الجزء الأوسط والجنوبيّ من سلسلة جبال لبنان الغربيّة، تنتشر فيه مصايف شهيرة — الصفوف ٣ و٤، العمود ٢.\n(١) مركزا تزلّج مهمّان في سلسلة جبال لبنان الغربيّة — الصفّ ٢، العمود ٣.\n(ب) جبل يفصل سهل البقاع عن سهل مرجعيون — الصفّ ٥، العمود ٢.\n(ج) جبل يحصر مع جبل الشيخ ومع الجبل (ب) هضاب وادي التيم — الصفّ ٥، العمود ٢.\n(٢) مدينة كبرى في المنطقة الداخليّة، شهدت القرى القريبة منها تحوّلًا شديدًا — الصفّ ٣، العمود ٣.\n(٣) مدينة كبرى ساحليّة في الشمال، شهدت القرى القريبة منها تحوّلًا شديدًا — الصفّ ١، العمود ٣.\n(٤) مدينة بيروت — الصفّ ٣، العمود ٢.\n\nمن خلال المستند رقم (١):\n١- اذكر:\nأ- ثلاثة من المصايف الشهيرة الواقعة في المنطقة المشار إليها بالحرف (أ). (ثلاثة أرباع العلامة)\nب- اسمَي مركزَي التزلّج المشار إليهما بالرقم (١). (نصف علامة)\nج- اسمَي الجبلين المشار إليهما بالحرفين (ب، ج). (نصف علامة)\nد- اسمَي المدينتين المشار إليهما بالرقمين (٢، ٣)، واسم التحوّل الذي أصاب القرى القريبة منهما. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36023, 16967, 1, 'من خلال المستند رقم (١) (خريطة لبنان: مصايف ومدن وجبال):\n٢- حدّد:\nأ- موقع المدينة (٢) بالنسبة إلى كلٍّ من المدينة (٣) ومدينة بيروت (٤). (نصف علامة)\nب- موقع سلسلة جبال لبنان الشرقيّة بالنسبة إلى المنطقة الداخليّة، واتّجاه امتدادها بالنسبة إلى السلسلة الغربيّة. (نصف علامة)\nج- الاتّجاه العامّ لرحلة تنطلق من مدينة بيروت (٤) نحو مركزَي التزلّج (١). (نصف علامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36024, 16967, 2, 'من خلال المستند رقم (١) (خريطة لبنان: مصايف ومدن وجبال):\n٢- حدّد:\nأ- موقع المدينة (٢) بالنسبة إلى كلٍّ من المدينة (٣) ومدينة بيروت (٤). (نصف علامة)\nب- موقع سلسلة جبال لبنان الشرقيّة بالنسبة إلى المنطقة الداخليّة، واتّجاه امتدادها بالنسبة إلى السلسلة الغربيّة. (نصف علامة)\nج- الاتّجاه العامّ لرحلة تنطلق من مدينة بيروت (٤) نحو مركزَي التزلّج (١). (نصف علامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36025, 16968, 1, 'المستند رقم (٢):\n«القطاع الثالثيّ هو قطاع التجارة والخدمات، وقد تطوّر في لبنان بشكل واسع على حساب قطاعَي الزراعة والصناعة، وصارت التجارة والسياحة تحتلّان فيه مرتبة متقدّمة. وتعود نشأة المدن اللبنانيّة إلى عوامل عديدة، معظمها ذات طابع تجاريّ وخدماتيّ، أبرزها وجود المرافئ التجاريّة على طول الشاطئ اللبنانيّ، وتوفّر المرافق والمعالم السياحيّة العمرانيّة منها والأثريّة، وقيام الصناعة، ووجود مؤسّسات الدولة الإداريّة الأساسيّة.\nوقد أدّت هذه العوامل نفسها إلى نموّ المدن وتطوّرها بشكل متسارع، وبخاصّة في المنطقة الساحليّة، فتركّزت معظم النشاطات التجاريّة والخدماتيّة في العاصمة وفي المنطقة الساحليّة، وهذا ما يطرح سؤال الإنماء المتوازن بين مختلف المناطق اللبنانيّة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36026, 16968, 2, 'المستند رقم (٢):\n«القطاع الثالثيّ هو قطاع التجارة والخدمات، وقد تطوّر في لبنان بشكل واسع على حساب قطاعَي الزراعة والصناعة، وصارت التجارة والسياحة تحتلّان فيه مرتبة متقدّمة. وتعود نشأة المدن اللبنانيّة إلى عوامل عديدة، معظمها ذات طابع تجاريّ وخدماتيّ، أبرزها وجود المرافئ التجاريّة على طول الشاطئ اللبنانيّ، وتوفّر المرافق والمعالم السياحيّة العمرانيّة منها والأثريّة، وقيام الصناعة، ووجود مؤسّسات الدولة الإداريّة الأساسيّة.\nوقد أدّت هذه العوامل نفسها إلى نموّ المدن وتطوّرها بشكل متسارع، وبخاصّة في المنطقة الساحليّة، فتركّزت معظم النشاطات التجاريّة والخدماتيّة في العاصمة وفي المنطقة الساحليّة، وهذا ما يطرح سؤال الإنماء المتوازن بين مختلف المناطق اللبنانيّة.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٣- حدّد طبيعة المستند رقم (٢)، وموضوعه. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36027, 16969, 1, '٤- من خلال المستند رقم (٢) (نصّ حول القطاع الثالثيّ والمدن اللبنانيّة):\nأ- حدّد ثلاثة من عوامل نشأة المدن اللبنانيّة. (ثلاثة أرباع العلامة)\nب- حدّد النشاطين اللذين يحتلّان مرتبة متقدّمة في القطاع الثالثيّ في لبنان. (نصف علامة)\nج- استنتج طبيعة الاقتصاد اللبنانيّ، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36028, 16969, 2, '٤- من خلال المستند رقم (٢) (نصّ حول القطاع الثالثيّ والمدن اللبنانيّة):\nأ- حدّد ثلاثة من عوامل نشأة المدن اللبنانيّة. (ثلاثة أرباع العلامة)\nب- حدّد النشاطين اللذين يحتلّان مرتبة متقدّمة في القطاع الثالثيّ في لبنان. (نصف علامة)\nج- استنتج طبيعة الاقتصاد اللبنانيّ، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36029, 16970, 1, '٥- يشير المستند رقم (٢) إلى المكانة المتقدّمة للتجارة في الاقتصاد اللبنانيّ. أوضح وجهَي ارتكاز الاقتصاد اللبنانيّ على التجارة: وجه القوّة ووجه الضعف. (علامة واحدة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36030, 16970, 2, '٥- يشير المستند رقم (٢) إلى المكانة المتقدّمة للتجارة في الاقتصاد اللبنانيّ. أوضح وجهَي ارتكاز الاقتصاد اللبنانيّ على التجارة: وجه القوّة ووجه الضعف. (علامة واحدة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36031, 16971, 1, 'المستند رقم (٣-أ): من مؤسّسات القطاع العامّ ومشاريعه في المجال الزراعيّ.\n| المؤسّسة أو المشروع | أمثلة | المهمّة |\n| مشاريع الريّ الكبرى | مشروع القاسميّة، مشروع اليمّونة | ريّ أراضٍ زراعيّة، ومنها بعض أراضي البقاع |\n| مراكز الأبحاث العلميّة الزراعيّة | مركز الفنار | تأصيل البذور، وتحسين النسل، وإجراء التجارب لمكافحة الأمراض |\n| المكاتب الزراعيّة | مكتب الحبوب والشمندر السكّريّ، مكتب الفاكهة | تقديم الإرشادات إلى الطرق الفضلى لزراعة هذه الأصناف وتصريف إنتاجها |\n| المشروع الأخضر | — | مساعدة الفلّاحين في استصلاح أراضيهم وشقّ الطرقات الزراعيّة |\n| مصرف التسليف الزراعيّ والصناعيّ والعقاريّ | — | قروض متوسّطة وطويلة الأجل يسدّدها المزارع على دفعات في فترة ١٠ سنوات أو أكثر |\n\nالمستند رقم (٣-ب): من أدوار القطاع الخاصّ في المجال الزراعيّ.\n| الجهة | الدور |\n| الجامعات والمعاهد الخاصّة | كلّيّات الهندسة الزراعيّة ومراكز الأبحاث ومحطّات التجارب الزراعيّة (الجامعة الأميركيّة، والجامعة اليسوعيّة في البقاع، ومعهد الهندسة الزراعيّة في تعنايل) |\n| الشركات الخاصّة | تأمين البذور والأدوية والأسمدة والمعدّات الزراعيّة |\n| مراكز التوضيب | توضيب الفواكه والخضار وحفظها قبل طرحها في الأسواق |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة كلٍّ من المستندين (٣-أ) و(٣-ب)، وموضوع المستند (٣-أ). (علامة واحدة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36032, 16971, 2, 'المستند رقم (٣-أ): من مؤسّسات القطاع العامّ ومشاريعه في المجال الزراعيّ.\n| المؤسّسة أو المشروع | أمثلة | المهمّة |\n| مشاريع الريّ الكبرى | مشروع القاسميّة، مشروع اليمّونة | ريّ أراضٍ زراعيّة، ومنها بعض أراضي البقاع |\n| مراكز الأبحاث العلميّة الزراعيّة | مركز الفنار | تأصيل البذور، وتحسين النسل، وإجراء التجارب لمكافحة الأمراض |\n| المكاتب الزراعيّة | مكتب الحبوب والشمندر السكّريّ، مكتب الفاكهة | تقديم الإرشادات إلى الطرق الفضلى لزراعة هذه الأصناف وتصريف إنتاجها |\n| المشروع الأخضر | — | مساعدة الفلّاحين في استصلاح أراضيهم وشقّ الطرقات الزراعيّة |\n| مصرف التسليف الزراعيّ والصناعيّ والعقاريّ | — | قروض متوسّطة وطويلة الأجل يسدّدها المزارع على دفعات في فترة ١٠ سنوات أو أكثر |\n\nالمستند رقم (٣-ب): من أدوار القطاع الخاصّ في المجال الزراعيّ.\n| الجهة | الدور |\n| الجامعات والمعاهد الخاصّة | كلّيّات الهندسة الزراعيّة ومراكز الأبحاث ومحطّات التجارب الزراعيّة (الجامعة الأميركيّة، والجامعة اليسوعيّة في البقاع، ومعهد الهندسة الزراعيّة في تعنايل) |\n| الشركات الخاصّة | تأمين البذور والأدوية والأسمدة والمعدّات الزراعيّة |\n| مراكز التوضيب | توضيب الفواكه والخضار وحفظها قبل طرحها في الأسواق |\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٦- حدّد طبيعة كلٍّ من المستندين (٣-أ) و(٣-ب)، وموضوع المستند (٣-أ). (علامة واحدة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36033, 16972, 1, '٧- أ- حدّد من خلال المستند (٣-أ) المدّة التي يسدّد فيها المزارع القرض الذي يحصل عليه من المصرف. (ربع علامة)\nب- استنتج من خلال المستند (٣-أ) أثر مشاريع الريّ الكبرى في المساحات الزراعيّة، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)\nج- استنتج من خلال المستند (٣-ب) أثر دور الشركات الخاصّة في الإنتاج الزراعيّ، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36034, 16972, 2, '٧- أ- حدّد من خلال المستند (٣-أ) المدّة التي يسدّد فيها المزارع القرض الذي يحصل عليه من المصرف. (ربع علامة)\nب- استنتج من خلال المستند (٣-أ) أثر مشاريع الريّ الكبرى في المساحات الزراعيّة، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)\nج- استنتج من خلال المستند (٣-ب) أثر دور الشركات الخاصّة في الإنتاج الزراعيّ، مبرّرًا استنتاجك بالدليل المناسب. (ثلاثة أرباع العلامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36035, 16973, 1, '٨- يشير المستندان (٣-أ) و(٣-ب) إلى اشتراك القطاعين العامّ والخاصّ في تطوير المجال الزراعيّ. أوضح:\nأ- إجراءين آخرين اتّخذتهما الدولة لتطوير المجال الزراعيّ، غير الواردَين في المستند (٣-أ). (علامة واحدة)\nب- الدورين اللذين تؤدّيهما الزراعة في الاقتصاد اللبنانيّ. (نصف علامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36036, 16973, 2, '٨- يشير المستندان (٣-أ) و(٣-ب) إلى اشتراك القطاعين العامّ والخاصّ في تطوير المجال الزراعيّ. أوضح:\nأ- إجراءين آخرين اتّخذتهما الدولة لتطوير المجال الزراعيّ، غير الواردَين في المستند (٣-أ). (علامة واحدة)\nب- الدورين اللذين تؤدّيهما الزراعة في الاقتصاد اللبنانيّ. (نصف علامة)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36037, 16974, 1, 'المستند رقم (٤): مظاهر السطح في لبنان.\n«تضاريس سطح لبنان متنوّعة إجمالًا، لكنّ المظهر الجبليّ هو الغالب عليها. فعلى طول البحر يمتدّ شاطئ قليل التعاريج عمومًا، تظهر قبالته بعض الجزر الصغيرة غير المأهولة، وتقوم عليه منتجعات سياحيّة ضخمة وعديدة. وفي الداخل تنحصر بين سلسلتين جبليّتين متوازيتين منطقةٌ أهمّ ما فيها سهل البقاع، الذي يتمتّع بأهمّيّة اقتصاديّة خاصّة على الصعيد الزراعيّ.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول الوحدات التضاريسيّة في لبنان، مبيّنًا فيه:\n- الوحدات التضاريسيّة الأربع مرتّبة من الغرب إلى الشرق. (علامة واحدة)\n- ثلاثًا من خصائص الشاطئ والسهل الساحليّ. (علامة ونصف)\n- مقارنة بين سلسلة جبال لبنان الغربيّة وسلسلة جبال لبنان الشرقيّة من حيث: الموقع، والسكن، والمسالك، والنشاط أو الغطاء النباتيّ. (علامتان)\n- ثلاثًا من خصائص سهل البقاع. (علامة ونصف)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36038, 16974, 2, 'المستند رقم (٤): مظاهر السطح في لبنان.\n«تضاريس سطح لبنان متنوّعة إجمالًا، لكنّ المظهر الجبليّ هو الغالب عليها. فعلى طول البحر يمتدّ شاطئ قليل التعاريج عمومًا، تظهر قبالته بعض الجزر الصغيرة غير المأهولة، وتقوم عليه منتجعات سياحيّة ضخمة وعديدة. وفي الداخل تنحصر بين سلسلتين جبليّتين متوازيتين منطقةٌ أهمّ ما فيها سهل البقاع، الذي يتمتّع بأهمّيّة اقتصاديّة خاصّة على الصعيد الزراعيّ.»\nالمصدر: كتاب الجغرافيا — الصفّ التاسع الأساسيّ (بتصرّف)\n\n٩- بالاعتماد على المستند رقم (٤) ومعلوماتك المكتسبة، اكتب نصًّا جغرافيًّا بحدود (١٢-١٥ سطرًا) حول الوحدات التضاريسيّة في لبنان، مبيّنًا فيه:\n- الوحدات التضاريسيّة الأربع مرتّبة من الغرب إلى الشرق. (علامة واحدة)\n- ثلاثًا من خصائص الشاطئ والسهل الساحليّ. (علامة ونصف)\n- مقارنة بين سلسلة جبال لبنان الغربيّة وسلسلة جبال لبنان الشرقيّة من حيث: الموقع، والسكن، والمسالك، والنشاط أو الغطاء النباتيّ. (علامتان)\n- ثلاثًا من خصائص سهل البقاع. (علامة ونصف)', 1, '2026-10-01 03:15:48', '2026-10-01 03:15:48'),
(36039, 16975, 1, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول الوحدات التضاريسيّة في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:49', '2026-10-01 03:15:49'),
(36040, 16975, 2, 'شكل المسابقة (يُقيَّم على مجمل المسابقة، ولا سيّما النصّ الجغرافيّ حول الوحدات التضاريسيّة في لبنان): تماسك النصّ، استعمال المصطلحات والمفاهيم، ترتيب المسابقة، إمكانيّة قراءتها. (علامتان)', 1, '2026-10-01 03:15:49', '2026-10-01 03:15:49'),
