(3166, 1083, 2, 'Comprehension and Analysis', 'Text, narrative, descriptive and travel structure, plus style and imagery in a literary text.', 1, '2026-09-25 08:31:58', '2026-09-25 08:31:58'),
(3167, 1084, 1, 'القواعد', 'التعجّب والاستفهام والمدح والذمّ، والمفاعيل، والحال والنعت، والجمل التي لها محلّ من الإعراب، وتصريف الفعل.', 1, '2026-09-25 08:31:58', '2026-09-25 08:31:58'),
(3168, 1084, 2, 'Grammar', 'Exclamation, interrogation, praise and blame, the objects, circumstantial and adjectival accusatives, clauses with a grammatical position, and verb conjugation.', 1, '2026-09-25 08:31:58', '2026-09-25 08:31:58'),
(3169, 1085, 1, 'البلاغة', 'الخبر والإنشاء، والتشبيه والكناية والحقيقة والمجاز والاستعارة، والطباق والمقابلة، والجناس والسجع.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
(3170, 1085, 2, 'Rhetoric', 'Declarative and performative sentences, simile, metonymy, literal and figurative meaning, metaphor, antithesis, paronomasia and rhymed prose.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
(3171, 1086, 1, 'العروض', 'الكتابة العروضيّة ورموزها، والتفاعيل والقافية والرويّ، وبحرا البسيط والوافر.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
(3172, 1086, 2, 'Prosody', 'Prosodic writing and its symbols, the feet, rhyme and rawi, and the Basit and Wafir metres.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
(3173, 1087, 1, 'التعبير الكتابيّ', 'كتابة الوصف الموضوعيّ والوجدانيّ، والنصّ السرديّ، والقصّة الواقعيّة، والرحلة، وإبداء الرأي، والإنشاء الحرّ.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
(3174, 1087, 2, 'Written Expression', 'Objective and emotional description, narrative text, realistic story, travel text, giving an opinion, and free composition.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
(3175, 1088, 1, 'مسابقات', 'خمسة نماذج على نمط الشهادة المتوسّطة الرسميّة، مع أسس التصحيح كاملةً.', 1, '2026-09-25 08:31:59', '2026-09-25 08:31:59'),
