(13730, 1365, 2, 'سَلَامُنْ مِنْ / صَبَا بَرَدَى / أَرَقْقُو. الرموز: //ه/ه/ه — //ه///ه — //ه/ه. التفاعيل: مَفَاعِيلُنْ مُفَاعَلَتُنْ فَعُولُنْ. الجواز: مفاعلتن صارت مفاعيلن في التفعيلة الأولى. العروض: فَعُولُنْ.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13731, 1366, 1, 'وَءَاخَرُو / نَ بِبَطْ / نِلْأَرْضِ أَحْ / يَاءُو. الرموز: //ه//ه — ///ه — /ه/ه//ه — /ه/ه. التفاعيل: مُفَاعِلُنْ فَعِلُنْ مُسْتَفْعِلُنْ فَعْلُنْ. الجوازات: مستفعلن صارت مفاعلن، وفاعلن صارت فعِلن. الضرب: فَعْلُنْ.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13732, 1366, 2, 'وَءَاخَرُو / نَ بِبَطْ / نِلْأَرْضِ أَحْ / يَاءُو. الرموز: //ه//ه — ///ه — /ه/ه//ه — /ه/ه. التفاعيل: مُفَاعِلُنْ فَعِلُنْ مُسْتَفْعِلُنْ فَعْلُنْ. الجوازات: مستفعلن صارت مفاعلن، وفاعلن صارت فعِلن. الضرب: فَعْلُنْ.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13733, 1367, 1, 'الوزن: مُسْتَفْعِلُنْ فَاعِلُنْ مُسْتَفْعِلُنْ فَاعِلُنْ في كلّ شطر. المفتاح: إنّ البسيط لديه يُبسط الأمل. جوازات الحشو: مستفعلن ← مفاعلن، وفاعلن ← فعِلن. العروض واحدة: فَعِلُنْ، والضرب: فَعِلُنْ أو فَعْلُنْ.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13734, 1367, 2, 'الوزن: مُسْتَفْعِلُنْ فَاعِلُنْ مُسْتَفْعِلُنْ فَاعِلُنْ في كلّ شطر. المفتاح: إنّ البسيط لديه يُبسط الأمل. جوازات الحشو: مستفعلن ← مفاعلن، وفاعلن ← فعِلن. العروض واحدة: فَعِلُنْ، والضرب: فَعِلُنْ أو فَعْلُنْ.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13735, 1368, 1, 'وَدَمْعُنْ لَا / يُكَفْكَفُ يَا / دِمَشْقُو. الرموز: //ه/ه/ه — //ه///ه — //ه/ه. التفاعيل: مَفَاعِيلُنْ مُفَاعَلَتُنْ فَعُولُنْ. الجواز: مفاعلتن صارت مفاعيلن في التفعيلة الأولى. الضرب: فَعُولُنْ.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13736, 1369, 1, 'الرويّ: آخر حرف صحيح في البيت، تُنسَب إليه القصيدة. القافية: من آخر ساكن في البيت إلى الساكن الذي قبله مع المتحرّك الذي قبله (أي من آخر البيت إلى المتحرّك قبل الساكنين الأخيرين).', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13737, 1370, 1, 'العروض ميزان الشعر، به نعرف سلامة الوزن من اختلاله، وواضعه الخليل بن أحمد الفراهيدي. يتألّف البيت من شطرين: الصدر والعجز، وتُبنى أبيات القصيدة على وزن واحد يُسمّى بحرًا.', 1, '2026-09-30 22:08:01', '2026-09-30 22:08:01'),
(13738, 1369, 2, 'الرويّ: آخر حرف صحيح في البيت، تُنسَب إليه القصيدة. القافية: من آخر ساكن في البيت إلى الساكن الذي قبله مع المتحرّك الذي قبله (أي من آخر البيت إلى المتحرّك قبل الساكنين الأخيرين).', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13739, 1370, 2, 'العروض ميزان الشعر، به نعرف سلامة الوزن من اختلاله، وواضعه الخليل بن أحمد الفراهيدي. يتألّف البيت من شطرين: الصدر والعجز، وتُبنى أبيات القصيدة على وزن واحد يُسمّى بحرًا.', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13740, 1368, 2, 'وَدَمْعُنْ لَا / يُكَفْكَفُ يَا / دِمَشْقُو. الرموز: //ه/ه/ه — //ه///ه — //ه/ه. التفاعيل: مَفَاعِيلُنْ مُفَاعَلَتُنْ فَعُولُنْ. الجواز: مفاعلتن صارت مفاعيلن في التفعيلة الأولى. الضرب: فَعُولُنْ.', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13741, 1371, 1, 'الوافر التامّ: مُفَاعَلَتُنْ مُفَاعَلَتُنْ فَعُولُنْ في كلّ شطر، وعروضه وضربه فعولن. المجزوء: مفاعلتن مفاعلتن في كلّ شطر. المفتاح: بحور الشعر وافرها جميل. الجواز الوحيد: مفاعلتن ← مفاعيلن أينما وقعت في الحشو.', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13742, 1371, 2, 'الوافر التامّ: مُفَاعَلَتُنْ مُفَاعَلَتُنْ فَعُولُنْ في كلّ شطر، وعروضه وضربه فعولن. المجزوء: مفاعلتن مفاعلتن في كلّ شطر. المفتاح: بحور الشعر وافرها جميل. الجواز الوحيد: مفاعلتن ← مفاعيلن أينما وقعت في الحشو.', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13743, 1372, 1, 'وَلْجَهْلُ يَهْ / دِمُ بَيْ / تَلْعِزْزِ وَشْ / شَرَفِي. الرموز: /ه/ه//ه — ///ه — /ه/ه//ه — ///ه. التفاعيل: مُسْتَفْعِلُنْ فَعِلُنْ مُسْتَفْعِلُنْ فَعِلُنْ. الضرب (آخر تفعيلة في العجز): فَعِلُنْ، والحشو: مُسْتَفْعِلُنْ فَعِلُنْ مُسْتَفْعِلُنْ، والرويّ: الفاء (آخر حرف صحيح في البيت).', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13744, 1372, 2, 'وَلْجَهْلُ يَهْ / دِمُ بَيْ / تَلْعِزْزِ وَشْ / شَرَفِي. الرموز: /ه/ه//ه — ///ه — /ه/ه//ه — ///ه. التفاعيل: مُسْتَفْعِلُنْ فَعِلُنْ مُسْتَفْعِلُنْ فَعِلُنْ. الضرب (آخر تفعيلة في العجز): فَعِلُنْ، والحشو: مُسْتَفْعِلُنْ فَعِلُنْ مُسْتَفْعِلُنْ، والرويّ: الفاء (آخر حرف صحيح في البيت).', 1, '2026-09-30 22:08:02', '2026-09-30 22:08:02'),
(13745, 1373, 1, 'الجملة الخبريّة جملة تحمل خبرًا يحتمل الصدق أو الكذب. غرضاها: فائدة الخبر، حين يكون السامع يجهل الخبر؛ ولازم الفائدة، حين يكون السامع يعرف الخبر.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13746, 1373, 2, 'الجملة الخبريّة جملة تحمل خبرًا يحتمل الصدق أو الكذب. غرضاها: فائدة الخبر، حين يكون السامع يجهل الخبر؛ ولازم الفائدة، حين يكون السامع يعرف الخبر.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13747, 1374, 1, 'اُدْرُسْ دَرْسَكَ: إنشاء طلبيّ، صيغته الأمر. هَلْ كَتَبْتَ فُرُوضَكَ؟: إنشاء طلبيّ، صيغته الاستفهام. مَا أَجْمَلَ الطَّقْسَ!: إنشاء غير طلبيّ، صيغته التعجّب. هي إنشائيّة لأنّها لا تحتمل الصدق أو الكذب لذاتها، فلا يمكن أن تقول لصاحبها: صدقتَ أو كذبتَ، إذ ليست إخبارًا عن شيء واقع.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13748, 1374, 2, 'اُدْرُسْ دَرْسَكَ: إنشاء طلبيّ، صيغته الأمر. هَلْ كَتَبْتَ فُرُوضَكَ؟: إنشاء طلبيّ، صيغته الاستفهام. مَا أَجْمَلَ الطَّقْسَ!: إنشاء غير طلبيّ، صيغته التعجّب. هي إنشائيّة لأنّها لا تحتمل الصدق أو الكذب لذاتها، فلا يمكن أن تقول لصاحبها: صدقتَ أو كذبتَ، إذ ليست إخبارًا عن شيء واقع.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13749, 1375, 1, '«الطِّفْلُ يَبْكِي»: حقيقة، لأنّ الفعل استُعمل فيما وُضع له أصلًا (الطفل يبكي فعلًا). «السَّمَاءُ تَبْكِي»: مجاز، لأنّ الفعل استُعمل في غير ما وُضع له، فالسماء لا تبكي حقيقةً، وإسناد البكاء إليها قرينة تمنع المعنى الحقيقيّ.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13750, 1375, 2, '«الطِّفْلُ يَبْكِي»: حقيقة، لأنّ الفعل استُعمل فيما وُضع له أصلًا (الطفل يبكي فعلًا). «السَّمَاءُ تَبْكِي»: مجاز، لأنّ الفعل استُعمل في غير ما وُضع له، فالسماء لا تبكي حقيقةً، وإسناد البكاء إليها قرينة تمنع المعنى الحقيقيّ.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13751, 1376, 1, 'الطلبيّ (أربع ممّا يلي): الأمر، النهي، الاستفهام، النداء، المصدر النائب عن فعل الأمر، اسم الفعل، التمنّي. غير الطلبيّ (ثلاث ممّا يلي): المدح، الذمّ، التعجّب، القسم، الرجاء.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13752, 1376, 2, 'الطلبيّ (أربع ممّا يلي): الأمر، النهي، الاستفهام، النداء، المصدر النائب عن فعل الأمر، اسم الفعل، التمنّي. غير الطلبيّ (ثلاث ممّا يلي): المدح، الذمّ، التعجّب، القسم، الرجاء.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13753, 1377, 1, 'قَدْ نَجَحَ: قَدْ قبل الماضي. سَيَنْجَحُ: السين. أَمَّا الْعِلْمُ فَنُورٌ: «أمّا» الشرطيّة. لَلْعِلْمُ نُورٌ: لام الابتداء.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13754, 1377, 2, 'قَدْ نَجَحَ: قَدْ قبل الماضي. سَيَنْجَحُ: السين. أَمَّا الْعِلْمُ فَنُورٌ: «أمّا» الشرطيّة. لَلْعِلْمُ نُورٌ: لام الابتداء.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13755, 1378, 1, 'الأركان: المشبَّه: خَدٌّ، المشبَّه به: الورد، الأداة: الكاف، وجه الشبه: أحمر (الحُمرة). النوع: مرسَل لأنّ الأداة ذُكرت، ومفصَّل لأنّ وجه الشبه ذُكر. القيمة: يوضّح المعنى، ويقرّب الصورة، ويقوّي الوصف.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13756, 1379, 1, 'الجملة الإنشائيّة جملة تتضمّن كلامًا لا يحتمل الصدق أو الكذب لذاته. الإنشاء الطلبيّ يستدعي مطلوبًا غير حاصل (كالأمر والنهي والاستفهام)، والإنشاء غير الطلبيّ لا يستدعي مطلوبًا (كالمدح والتعجّب والقسم).', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13757, 1378, 2, 'الأركان: المشبَّه: خَدٌّ، المشبَّه به: الورد، الأداة: الكاف، وجه الشبه: أحمر (الحُمرة). النوع: مرسَل لأنّ الأداة ذُكرت، ومفصَّل لأنّ وجه الشبه ذُكر. القيمة: يوضّح المعنى، ويقرّب الصورة، ويقوّي الوصف.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13758, 1379, 2, 'الجملة الإنشائيّة جملة تتضمّن كلامًا لا يحتمل الصدق أو الكذب لذاته. الإنشاء الطلبيّ يستدعي مطلوبًا غير حاصل (كالأمر والنهي والاستفهام)، والإنشاء غير الطلبيّ لا يستدعي مطلوبًا (كالمدح والتعجّب والقسم).', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13759, 1380, 1, 'نؤكّد الخبر إذا تردّد السامع أو أنكر. خالي الذهن يُلقى إليه الخبر بلا توكيد، والمتردّد يُؤكَّد له بأداة، والمنكِر بأداتين، مثل: «وَاللهِ إِنَّ الْعِلْمَ نُورٌ» (القسم وإنّ).', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13760, 1380, 2, 'نؤكّد الخبر إذا تردّد السامع أو أنكر. خالي الذهن يُلقى إليه الخبر بلا توكيد، والمتردّد يُؤكَّد له بأداة، والمنكِر بأداتين، مثل: «وَاللهِ إِنَّ الْعِلْمَ نُورٌ» (القسم وإنّ).', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13761, 1381, 1, 'شرطا المجاز: علاقة بين المعنيين (الحقيقيّ والمجازيّ)، وقرينة تمنع المعنى الحقيقيّ. القرينة في «السَّمَاءُ تَبْكِي» إسناد البكاء إلى السماء؛ فالسماء لا تبكي حقيقةً، فيمتنع أن يكون الفعل مستعملًا في معناه الأصليّ.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13762, 1381, 2, 'شرطا المجاز: علاقة بين المعنيين (الحقيقيّ والمجازيّ)، وقرينة تمنع المعنى الحقيقيّ. القرينة في «السَّمَاءُ تَبْكِي» إسناد البكاء إلى السماء؛ فالسماء لا تبكي حقيقةً، فيمتنع أن يكون الفعل مستعملًا في معناه الأصليّ.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13763, 1382, 1, 'مرسَل مجمَل: «خَدٌّ كَالْوَرْدِ»، حذفنا وجه الشبه (أحمر) وأبقينا الأداة. بليغ: «خَدٌّ وَرْدٌ»، حذفنا الأداة ووجه الشبه معًا.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13764, 1382, 2, 'مرسَل مجمَل: «خَدٌّ كَالْوَرْدِ»، حذفنا وجه الشبه (أحمر) وأبقينا الأداة. بليغ: «خَدٌّ وَرْدٌ»، حذفنا الأداة ووجه الشبه معًا.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13765, 1384, 1, 'الحقيقة: استعمال اللفظ فيما وُضع له أصلًا، أي في معناه الأصليّ الذي وُضع له في اللغة. المجاز: استعمال اللفظ في غير ما وُضع له، بشرطين: علاقة بين المعنيين، وقرينة تمنع المعنى الحقيقيّ.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13766, 1383, 1, 'التشبيه مشاركة طرفين في صفة لتوضيح المعنى. بحسب الأداة: المرسَل ما ذُكرت فيه الأداة، والمؤكَّد ما حُذفت منه. بحسب وجه الشبه: المفصَّل ما ذُكر فيه وجه الشبه، والمجمَل ما حُذف منه.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13767, 1383, 2, 'التشبيه مشاركة طرفين في صفة لتوضيح المعنى. بحسب الأداة: المرسَل ما ذُكرت فيه الأداة، والمؤكَّد ما حُذفت منه. بحسب وجه الشبه: المفصَّل ما ذُكر فيه وجه الشبه، والمجمَل ما حُذف منه.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13768, 1384, 2, 'الحقيقة: استعمال اللفظ فيما وُضع له أصلًا، أي في معناه الأصليّ الذي وُضع له في اللغة. المجاز: استعمال اللفظ في غير ما وُضع له، بشرطين: علاقة بين المعنيين، وقرينة تمنع المعنى الحقيقيّ.', 1, '2026-09-30 22:08:34', '2026-09-30 22:08:34'),
(13769, 1385, 1, '«يُرِيدُ / لَا يُرِيدُ»: طباق سلب، لأنّ الكلمة نفسها جاءت مثبتةً ومنفيّةً. «يُقْدِمُ / يُحْجِمُ»: طباق إيجاب، لأنّهما ضدّان مثبتان مختلفان في المعنى. القيمة: الضدّ يُظهر الضدّ فيتّضح المعنى، والطباق يركّز المعنى في الذهن ويعطيه حدّة (هنا يُبرز تردّد المراهق).', 1, '2026-09-30 22:08:35', '2026-09-30 22:08:35'),
(13770, 1385, 2, '«يُرِيدُ / لَا يُرِيدُ»: طباق سلب، لأنّ الكلمة نفسها جاءت مثبتةً ومنفيّةً. «يُقْدِمُ / يُحْجِمُ»: طباق إيجاب، لأنّهما ضدّان مثبتان مختلفان في المعنى. القيمة: الضدّ يُظهر الضدّ فيتّضح المعنى، والطباق يركّز المعنى في الذهن ويعطيه حدّة (هنا يُبرز تردّد المراهق).', 1, '2026-09-30 22:08:35', '2026-09-30 22:08:35'),
(13771, 1386, 1, 'المقابلة: أن يُؤتى بمعنيين أو أكثر، ثمّ بما يقابلها بالترتيب. الفرق: الطباق كلمتان متضادّتان، والمقابلة جملتان تتقابل كلماتهما واحدةً واحدة. القيمة: الطباق يركّز المعنى في الذهن ويعطيه حدّة (الضدّ يُظهر الضدّ)، والمقابلة تُبرز التناقض بين حالين أو موقفين كاملين.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13772, 1387, 1, 'شُبّهت الأرض (المستعار له/المشبَّه) بشيء يتألّق، وهو المشبَّه به (المستعار منه) المحذوف، وبقي من لوازمه الفعل «تَأَلَّقَتْ» وهو القرينة. فهي استعارة: تشبيه حُذف أحد طرفيه، والحقيقة فيه مستحيلة.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13773, 1386, 2, 'المقابلة: أن يُؤتى بمعنيين أو أكثر، ثمّ بما يقابلها بالترتيب. الفرق: الطباق كلمتان متضادّتان، والمقابلة جملتان تتقابل كلماتهما واحدةً واحدة. القيمة: الطباق يركّز المعنى في الذهن ويعطيه حدّة (الضدّ يُظهر الضدّ)، والمقابلة تُبرز التناقض بين حالين أو موقفين كاملين.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13774, 1387, 2, 'شُبّهت الأرض (المستعار له/المشبَّه) بشيء يتألّق، وهو المشبَّه به (المستعار منه) المحذوف، وبقي من لوازمه الفعل «تَأَلَّقَتْ» وهو القرينة. فهي استعارة: تشبيه حُذف أحد طرفيه، والحقيقة فيه مستحيلة.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13775, 1388, 1, 'المحسّن جناس تامّ بين «شَعَرْنَا» و«شَعَرْنَا»: لفظان متشابهان في النطق، مختلفان في المعنى، متّفقان في نوع الحروف وعددها وحركاتها وترتيبها. قيمته: يُحدث إيقاعًا موسيقيًّا، ويشدّ الانتباه بالمفاجأة: صوت واحد ومعنيان.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13776, 1388, 2, 'المحسّن جناس تامّ بين «شَعَرْنَا» و«شَعَرْنَا»: لفظان متشابهان في النطق، مختلفان في المعنى، متّفقان في نوع الحروف وعددها وحركاتها وترتيبها. قيمته: يُحدث إيقاعًا موسيقيًّا، ويشدّ الانتباه بالمفاجأة: صوت واحد ومعنيان.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13777, 1389, 1, 'الطباق: الجمع بين الشيء وضدّه، ويقع بين فعلين أو اسمين أو حرفين. نوعاه: طباق الإيجاب: ضدّان مثبتان مختلفان في المعنى؛ وطباق السلب: الكلمة نفسها مثبتةً ومنفيّةً.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13778, 1389, 2, 'الطباق: الجمع بين الشيء وضدّه، ويقع بين فعلين أو اسمين أو حرفين. نوعاه: طباق الإيجاب: ضدّان مثبتان مختلفان في المعنى؛ وطباق السلب: الكلمة نفسها مثبتةً ومنفيّةً.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13779, 1390, 1, 'التشبيه: الطرفان مذكوران. الاستعارة: حُذف أحد الطرفين، والحقيقة مستحيلة. الكناية: لا حذف، والحقيقة جائزة.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13780, 1390, 2, 'التشبيه: الطرفان مذكوران. الاستعارة: حُذف أحد الطرفين، والحقيقة مستحيلة. الكناية: لا حذف، والحقيقة جائزة.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13781, 1391, 1, 'الاستعارة مجاز علاقته المشابهة، أو تشبيه حُذف أحد طرفيه. تُولَد من التشبيه بأن نحذف أحد الطرفين ونُبقي شيئًا من لوازمه يدلّ عليه (القرينة).', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13782, 1391, 2, 'الاستعارة مجاز علاقته المشابهة، أو تشبيه حُذف أحد طرفيه. تُولَد من التشبيه بأن نحذف أحد الطرفين ونُبقي شيئًا من لوازمه يدلّ عليه (القرينة).', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13783, 1392, 1, 'يتّفق لفظا الجناس التامّ في: نوع الحروف، وعددها، وحركاتها، وترتيبها، مع اختلافهما في المعنى. ويكون الجناس غير تامّ إذا اختلف اللفظان في واحد من هذه الأمور الأربعة.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13784, 1393, 1, 'المقدّمة: الفقرة الأولى، فكرتها هدوء القرية قديمًا. العرض: الفقرة الثانية، فكرتها التغيّر بعد الطريق. الخاتمة: الفقرة الثالثة، فكرتها قلق الكاتب على روح القرية (تنتهي بسؤال). الفكرة العامّة: تحوّل القرية بعد مجيء الطريق وأثره في الناس.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13785, 1392, 2, 'يتّفق لفظا الجناس التامّ في: نوع الحروف، وعددها، وحركاتها، وترتيبها، مع اختلافهما في المعنى. ويكون الجناس غير تامّ إذا اختلف اللفظان في واحد من هذه الأمور الأربعة.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13786, 1393, 2, 'المقدّمة: الفقرة الأولى، فكرتها هدوء القرية قديمًا. العرض: الفقرة الثانية، فكرتها التغيّر بعد الطريق. الخاتمة: الفقرة الثالثة، فكرتها قلق الكاتب على روح القرية (تنتهي بسؤال). الفكرة العامّة: تحوّل القرية بعد مجيء الطريق وأثره في الناس.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13787, 1394, 1, 'السجع: توافق فاصلتين أو أكثر في الحرف الأخير، في النثر. قيمته: يمنح النثر نغمًا ويجعل الكلام سهل الحفظ. ويصير عيبًا إذا تُكُلِّف فأثقل المعنى، فالمعنى أوّلًا.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13788, 1394, 2, 'السجع: توافق فاصلتين أو أكثر في الحرف الأخير، في النثر. قيمته: يمنح النثر نغمًا ويجعل الكلام سهل الحفظ. ويصير عيبًا إذا تُكُلِّف فأثقل المعنى، فالمعنى أوّلًا.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13789, 1395, 1, 'انتقل الكاتب من الماضي إلى الحاضر، ومن المكان إلى الإنسان، ومن الوصف إلى السؤال. من الأدوات التي كشفت التدرّج (اثنتان): ثمّ، صار، اليوم/الأمس، لكنّ.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13790, 1395, 2, 'انتقل الكاتب من الماضي إلى الحاضر، ومن المكان إلى الإنسان، ومن الوصف إلى السؤال. من الأدوات التي كشفت التدرّج (اثنتان): ثمّ، صار، اليوم/الأمس، لكنّ.', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13791, 1396, 1, 'البُعد الاجتماعيّ، ودليله: «صار الجار يُغلق بابه» (تغيّر العلاقات بين الناس). البُعد الاقتصاديّ، ودليله: «صار الوقت يُقاس بالمال». (يُقبل كلّ بُعد مع دليل مناسب من العبارتين.)', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13792, 1396, 2, 'البُعد الاجتماعيّ، ودليله: «صار الجار يُغلق بابه» (تغيّر العلاقات بين الناس). البُعد الاقتصاديّ، ودليله: «صار الوقت يُقاس بالمال». (يُقبل كلّ بُعد مع دليل مناسب من العبارتين.)', 1, '2026-09-30 22:08:36', '2026-09-30 22:08:36'),
(13793, 1397, 1, 'الوضع الابتدائيّ: «كان نمرٌ قويّ يحكم الغابة، والحيوانات تخافه وتخدمه». العنصر المحرّك: «ذات يوم علق النمر في شبكة صيّاد… فهرب الجميع». الأحداث: مرور الفأر وتردّده، ثمّ اقترابه وقرضه الحبال. الحلّ: «بعد ساعة تمزّقت الشبكة، وخرج النمر حرًّا». الوضع النهائيّ: «منذ ذلك اليوم لم يعد النمر يسخر من الصغار، وصار الفأر أقرب أصدقائه».', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13794, 1398, 1, '١- الولادة سنة ١٩٥٠ في بلدة على الساحل. ٢- دخول المدرسة في السابعة (المعلّم الأوّل وأوّل كتاب). ٣- السفر إلى بيروت في الخامسة عشرة، والعمل نهارًا والدراسة ليلًا. ٤- نشر أوّل قصّة سنة ١٩٨٠.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13795, 1397, 2, 'الوضع الابتدائيّ: «كان نمرٌ قويّ يحكم الغابة، والحيوانات تخافه وتخدمه». العنصر المحرّك: «ذات يوم علق النمر في شبكة صيّاد… فهرب الجميع». الأحداث: مرور الفأر وتردّده، ثمّ اقترابه وقرضه الحبال. الحلّ: «بعد ساعة تمزّقت الشبكة، وخرج النمر حرًّا». الوضع النهائيّ: «منذ ذلك اليوم لم يعد النمر يسخر من الصغار، وصار الفأر أقرب أصدقائه».', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13796, 1398, 2, '١- الولادة سنة ١٩٥٠ في بلدة على الساحل. ٢- دخول المدرسة في السابعة (المعلّم الأوّل وأوّل كتاب). ٣- السفر إلى بيروت في الخامسة عشرة، والعمل نهارًا والدراسة ليلًا. ٤- نشر أوّل قصّة سنة ١٩٨٠.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13797, 1399, 1, 'الزمان: «ذات يوم»، «بعد ساعة»، «منذ ذلك اليوم». المكان: الغابة («كان نمرٌ قويّ يحكم الغابة»). الحدث: الوقوع في الشبكة والخلاص منها («علق النمر في شبكة صيّاد»، «تمزّقت الشبكة، وخرج النمر حرًّا»).', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13798, 1399, 2, 'الزمان: «ذات يوم»، «بعد ساعة»، «منذ ذلك اليوم». المكان: الغابة («كان نمرٌ قويّ يحكم الغابة»). الحدث: الوقوع في الشبكة والخلاص منها («علق النمر في شبكة صيّاد»، «تمزّقت الشبكة، وخرج النمر حرًّا»).', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13799, 1400, 1, 'الضمير: المتكلّم (وُلدتُ، دخلتُ، سافرتُ). الزمن: أفعال ماضية وتواريخ وأعمار: سنة ١٩٥٠، في السابعة، الخامسة عشرة، سنة ١٩٨٠. الأمكنة: بلدة الساحل، بيروت. المؤثّرون: الأب، الأمّ، المعلّم الأوّل. الأثر: «البحر الذي تركتُه ما زال يسكنني».', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13800, 1400, 2, 'الضمير: المتكلّم (وُلدتُ، دخلتُ، سافرتُ). الزمن: أفعال ماضية وتواريخ وأعمار: سنة ١٩٥٠، في السابعة، الخامسة عشرة، سنة ١٩٨٠. الأمكنة: بلدة الساحل، بيروت. المؤثّرون: الأب، الأمّ، المعلّم الأوّل. الأثر: «البحر الذي تركتُه ما زال يسكنني».', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13801, 1401, 1, 'المثل الخرافيّ قصّة قصيرة أبطالها حيوانات تتكلّم وتتصرّف كالبشر، وتنتهي بعبرة. قصّة النمر والفأر مثل خرافيّ لأنّ شخصيّاتها حيوانات تفكّر وتتصرّف كالبشر، ولها البنية السرديّة نفسها، وغايتها عبرة: لا تحتقر أحدًا لصغره، فقد تحتاج إليه يومًا.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13802, 1401, 2, 'المثل الخرافيّ قصّة قصيرة أبطالها حيوانات تتكلّم وتتصرّف كالبشر، وتنتهي بعبرة. قصّة النمر والفأر مثل خرافيّ لأنّ شخصيّاتها حيوانات تفكّر وتتصرّف كالبشر، ولها البنية السرديّة نفسها، وغايتها عبرة: لا تحتقر أحدًا لصغره، فقد تحتاج إليه يومًا.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13803, 1402, 1, 'الموصوف: البيت القديم (في آخر الحيّ). الأجزاء وصفاتها: الجدران: من حجر رمليّ أصفر. السقف: من القرميد الأحمر. الساحة: في وسطه، مبلّطة، تتوسّطها بركة صغيرة، وحولها شجرتا ليمون. الشرفة العليا: تطلّ على البحر، وقد صدئ حديدها من ملح الهواء.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13804, 1402, 2, 'الموصوف: البيت القديم (في آخر الحيّ). الأجزاء وصفاتها: الجدران: من حجر رمليّ أصفر. السقف: من القرميد الأحمر. الساحة: في وسطه، مبلّطة، تتوسّطها بركة صغيرة، وحولها شجرتا ليمون. الشرفة العليا: تطلّ على البحر، وقد صدئ حديدها من ملح الهواء.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13805, 1403, 1, 'السيرة سرد لحياة شخص حقيقيّ بترتيب الزمن؛ الذاتيّة يرويها صاحبها بضمير المتكلّم، والغيريّة تُروى بضمير الغائب. هذه السيرة ذاتيّة، لأنّها بضمير المتكلّم (وُلدتُ).', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13806, 1403, 2, 'السيرة سرد لحياة شخص حقيقيّ بترتيب الزمن؛ الذاتيّة يرويها صاحبها بضمير المتكلّم، والغيريّة تُروى بضمير الغائب. هذه السيرة ذاتيّة، لأنّها بضمير المتكلّم (وُلدتُ).', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13807, 1404, 1, '(أ) وصف موضوعيّ: ضمير الغائب (له، تُطلّ)، ومعجم مادّيّ ونعوت حسّيّة (حجريّ، من طبقتين، شرفة)، وجملة خبريّة. (ب) وصف وجدانيّ: ضمير المتكلّم (جدّي، يحضنني، بي)، ومعجم العاطفة وصورة بيانيّة (البيت يحضنني، ضاقت بي الدنيا).', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13808, 1404, 2, '(أ) وصف موضوعيّ: ضمير الغائب (له، تُطلّ)، ومعجم مادّيّ ونعوت حسّيّة (حجريّ، من طبقتين، شرفة)، وجملة خبريّة. (ب) وصف وجدانيّ: ضمير المتكلّم (جدّي، يحضنني، بي)، ومعجم العاطفة وصورة بيانيّة (البيت يحضنني، ضاقت بي الدنيا).', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13809, 1405, 1, 'الموضوعيّ: ضمير الغائب، معجم مادّيّ، نعوت حسّيّة، جمل خبريّة. الوجدانيّ: ضمير المتكلّم، معجم العاطفة، صور بيانيّة، إنشاء وتعجّب.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13810, 1405, 2, 'الموضوعيّ: ضمير الغائب، معجم مادّيّ، نعوت حسّيّة، جمل خبريّة. الوجدانيّ: ضمير المتكلّم، معجم العاطفة، صور بيانيّة، إنشاء وتعجّب.', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13811, 1406, 1, 'الانطلاق: «انطلقنا من طرابلس عند الفجر». المسار (الطريق): «سلكنا الطريق الجبليّ…» و«بعد ساعتين توقّفنا في قرية معلّقة على حافّة الوادي…». الوصول: «وعند الظهر وصلنا إلى الأرز». المشاهدات: «كانت الأشجار عملاقة، أغصانها تمتدّ كأذرع تحمل السماء». العودة والأثر: «قبل الغروب عدنا، وفي القلب شعورٌ بأنّ الجبل صار أكبر في داخلنا…».', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13812, 1406, 2, 'الانطلاق: «انطلقنا من طرابلس عند الفجر». المسار (الطريق): «سلكنا الطريق الجبليّ…» و«بعد ساعتين توقّفنا في قرية معلّقة على حافّة الوادي…». الوصول: «وعند الظهر وصلنا إلى الأرز». المشاهدات: «كانت الأشجار عملاقة، أغصانها تمتدّ كأذرع تحمل السماء». العودة والأثر: «قبل الغروب عدنا، وفي القلب شعورٌ بأنّ الجبل صار أكبر في داخلنا…».', 1, '2026-09-30 22:08:38', '2026-09-30 22:08:38'),
(13813, 1407, 1, 'الضمير: المتكلّم (نحن): انطلقنا، عدنا. الأمكنة الحقيقيّة: طرابلس، الوادي، الأرز. الزمن المتدرّج: الفجر، بعد ساعتين، الظهر، الغروب. أفعال الحركة: انطلق، سلك، وصل، عاد. الأثر في الرحّالة: شعورٌ بأنّ الجبل صار أكبر في داخلهم ممّا كان في الخريطة.', 1, '2026-09-30 22:08:39', '2026-09-30 22:08:39'),
(13814, 1407, 2, 'الضمير: المتكلّم (نحن): انطلقنا، عدنا. الأمكنة الحقيقيّة: طرابلس، الوادي، الأرز. الزمن المتدرّج: الفجر، بعد ساعتين، الظهر، الغروب. أفعال الحركة: انطلق، سلك، وصل، عاد. الأثر في الرحّالة: شعورٌ بأنّ الجبل صار أكبر في داخلهم ممّا كان في الخريطة.', 1, '2026-09-30 22:08:39', '2026-09-30 22:08:39'),
(13815, 1408, 1, 'السرد يحرّك الرحلة بأفعال الحركة، مثل: «انطلقنا من طرابلس عند الفجر» أو «وعند الظهر وصلنا إلى الأرز». الوصف يوقف الرحلة عند المشاهدات، مثل: «كانت الأشجار عملاقة، أغصانها تمتدّ كأذرع تحمل السماء».', 1, '2026-09-30 22:08:39', '2026-09-30 22:08:39'),
(13816, 1408, 2, 'السرد يحرّك الرحلة بأفعال الحركة، مثل: «انطلقنا من طرابلس عند الفجر» أو «وعند الظهر وصلنا إلى الأرز». الوصف يوقف الرحلة عند المشاهدات، مثل: «كانت الأشجار عملاقة، أغصانها تمتدّ كأذرع تحمل السماء».', 1, '2026-09-30 22:08:39', '2026-09-30 22:08:39'),
(13817, 1409, 1, 'يُقبل اثنان ممّا يلي: «يا وطني»: نداء؛ «ما أقسى غيابك!» أو «ما أحلى ذكراك!»: تعجّب؛ «فهل تعود الأيّام؟» أو «وهل يعود الأحبّة؟»: استفهام. الدور: الإنشاء يُشرك القارئ في الانفعال (الحنين والألم على غياب الوطن).', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13818, 1409, 2, 'يُقبل اثنان ممّا يلي: «يا وطني»: نداء؛ «ما أقسى غيابك!» أو «ما أحلى ذكراك!»: تعجّب؛ «فهل تعود الأيّام؟» أو «وهل يعود الأحبّة؟»: استفهام. الدور: الإنشاء يُشرك القارئ في الانفعال (الحنين والألم على غياب الوطن).', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13819, 1410, 1, 'الجوّ لطيف: مَا أَلْطَفَ الْجَوَّ! وأَلْطِفْ بِالْجَوِّ! (الفعل لَطُفَ ثلاثيّ يستوفي الشروط). البحر أزرق: مَا أَشَدَّ زُرْقَةَ الْبَحْرِ! لأنّ الزرقة لون، واللون لا يُبنى منه التعجّب مباشرةً، فنستعين بـ«أشدّ» ثمّ نأتي بالمصدر «زرقة».', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13820, 1410, 2, 'الجوّ لطيف: مَا أَلْطَفَ الْجَوَّ! وأَلْطِفْ بِالْجَوِّ! (الفعل لَطُفَ ثلاثيّ يستوفي الشروط). البحر أزرق: مَا أَشَدَّ زُرْقَةَ الْبَحْرِ! لأنّ الزرقة لون، واللون لا يُبنى منه التعجّب مباشرةً، فنستعين بـ«أشدّ» ثمّ نأتي بالمصدر «زرقة».', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13821, 1411, 1, 'يُقبل اثنان ممّا يلي: طباق: أقسى/أحلى أو ضحك/بكت، يُبرز التناقض بين الماضي والحاضر. مقابلة: «أمًّا تحضن الجائع / أبًا يردّ الخائف»، توازن يقوّي الصورة. سجع: الجائع/الخائف، إيقاع موسيقيّ يسهّل الحفظ.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13822, 1411, 2, 'يُقبل اثنان ممّا يلي: طباق: أقسى/أحلى أو ضحك/بكت، يُبرز التناقض بين الماضي والحاضر. مقابلة: «أمًّا تحضن الجائع / أبًا يردّ الخائف»، توازن يقوّي الصورة. سجع: الجائع/الخائف، إيقاع موسيقيّ يسهّل الحفظ.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13823, 1412, 1, 'أن يكون: ثلاثيًّا، مثبتًا (لا منفيًّا)، متصرّفًا، معلومًا (لا مبنيًّا للمجهول)، تامًّا (ليس مثل كان وأخواتها)، قابلًا للمفاضلة، وألّا يدلّ على لون أو عيب أو حلية.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13824, 1412, 2, 'أن يكون: ثلاثيًّا، مثبتًا (لا منفيًّا)، متصرّفًا، معلومًا (لا مبنيًّا للمجهول)، تامًّا (ليس مثل كان وأخواتها)، قابلًا للمفاضلة، وألّا يدلّ على لون أو عيب أو حلية.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13825, 1413, 1, 'العناصر الفنّيّة للأدب: العاطفة، والخيال (الصور)، والأسلوب (الأساليب والمحسّنات)، والفكرة. ويختصّ الأدب بأنّه يؤثّر بالشعور والجمال، لا بالبرهان وحده.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13826, 1413, 2, 'العناصر الفنّيّة للأدب: العاطفة، والخيال (الصور)، والأسلوب (الأساليب والمحسّنات)، والفكرة. ويختصّ الأدب بأنّه يؤثّر بالشعور والجمال، لا بالبرهان وحده.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13827, 1414, 1, 'نستعين بفعل تعجّب مساعد مثل: أَشَدّ أو أَحْسَن أو أَعْظَم أو أَجْمَل، ثمّ نأتي بمصدر الفعل. «احتاج» خماسيّ ليس ثلاثيًّا، فنقول: مَا أَشَدَّ حَاجَتَنَا إِلَى الْعِلْمِ! (أشدّ: فعل التعجّب المساعد، وحاجتنا: المصدر).', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13828, 1414, 2, 'نستعين بفعل تعجّب مساعد مثل: أَشَدّ أو أَحْسَن أو أَعْظَم أو أَجْمَل، ثمّ نأتي بمصدر الفعل. «احتاج» خماسيّ ليس ثلاثيًّا، فنقول: مَا أَشَدَّ حَاجَتَنَا إِلَى الْعِلْمِ! (أشدّ: فعل التعجّب المساعد، وحاجتنا: المصدر).', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13829, 1415, 1, 'ما: نكرة تامّة بمعنى «شيء» مبنيّة على السكون في محلّ رفع مبتدأ. أَرْوَعَ: فعل تعجّب ماضٍ جامد مبنيّ على الفتح، وفاعله ضمير مستتر وجوبًا تقديره «هو». الْبَحْرَ: مفعول به منصوب وعلامة نصبه الفتحة الظاهرة على آخره. وجملة «أَرْوَعَ الْبَحْرَ» الفعليّة في محلّ رفع خبر المبتدأ.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13830, 1415, 2, 'ما: نكرة تامّة بمعنى «شيء» مبنيّة على السكون في محلّ رفع مبتدأ. أَرْوَعَ: فعل تعجّب ماضٍ جامد مبنيّ على الفتح، وفاعله ضمير مستتر وجوبًا تقديره «هو». الْبَحْرَ: مفعول به منصوب وعلامة نصبه الفتحة الظاهرة على آخره. وجملة «أَرْوَعَ الْبَحْرَ» الفعليّة في محلّ رفع خبر المبتدأ.', 1, '2026-09-30 22:08:40', '2026-09-30 22:08:40'),
(13831, 1416, 1, 'ما: نكرة تامّة بمعنى «شيء» مبنيّة على السكون في محلّ رفع مبتدأ. كَانَ: فعل ماضٍ زائد، لا فاعل له ولا اسم ولا خبر. أَجْمَلَ: فعل تعجّب ماضٍ جامد مبنيّ على الفتح، وفاعله ضمير مستتر وجوبًا تقديره «هو». الرَّبِيعَ: مفعول به منصوب وعلامة نصبه الفتحة الظاهرة. وجملة «أَجْمَلَ الرَّبِيعَ» الفعليّة في محلّ رفع خبر المبتدأ. و«كان» تدلّ على أنّ التعجّب في الماضي.', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13832, 1416, 2, 'ما: نكرة تامّة بمعنى «شيء» مبنيّة على السكون في محلّ رفع مبتدأ. كَانَ: فعل ماضٍ زائد، لا فاعل له ولا اسم ولا خبر. أَجْمَلَ: فعل تعجّب ماضٍ جامد مبنيّ على الفتح، وفاعله ضمير مستتر وجوبًا تقديره «هو». الرَّبِيعَ: مفعول به منصوب وعلامة نصبه الفتحة الظاهرة. وجملة «أَجْمَلَ الرَّبِيعَ» الفعليّة في محلّ رفع خبر المبتدأ. و«كان» تدلّ على أنّ التعجّب في الماضي.', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13833, 1417, 1, '(أ) مَتَى وَصَلْتَ إِلَى الْمَدْرَسَةِ؟ (متى للزمان). (ب) أَيْنَ وَجَدْتَ قَلَمَكَ؟ (أين للمكان). (ج) مَنْ فَازَ بِالْجَائِزَةِ؟ (مَن للعاقل).', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13834, 1417, 2, '(أ) مَتَى وَصَلْتَ إِلَى الْمَدْرَسَةِ؟ (متى للزمان). (ب) أَيْنَ وَجَدْتَ قَلَمَكَ؟ (أين للمكان). (ج) مَنْ فَازَ بِالْجَائِزَةِ؟ (مَن للعاقل).', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13835, 1418, 1, 'لأنّ «ما» في التعجّب ليست حرفًا، بل اسم بمعنى «شيء» (كأنّك تقول: شيء عظيم جعل الربيع جميلًا)، فهي نكرة تامّة مبنيّة على السكون في محلّ رفع مبتدأ. وخبرها ليس كلمة واحدة، بل الجملة الفعليّة بعدها (مثل «أَجْمَلَ الرَّبِيعَ») في محلّ رفع خبر المبتدأ.', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13836, 1418, 2, 'لأنّ «ما» في التعجّب ليست حرفًا، بل اسم بمعنى «شيء» (كأنّك تقول: شيء عظيم جعل الربيع جميلًا)، فهي نكرة تامّة مبنيّة على السكون في محلّ رفع مبتدأ. وخبرها ليس كلمة واحدة، بل الجملة الفعليّة بعدها (مثل «أَجْمَلَ الرَّبِيعَ») في محلّ رفع خبر المبتدأ.', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13837, 1419, 1, 'مَنْ: للعاقل؛ ما وماذا: لغير العاقل (أو حقيقة الشيء)؛ أين: للمكان؛ متى: للزمان؛ كيف: للحال؛ كم: للعدد؛ أيّ: للتعيين (واحد من جماعة)؛ أنّى: بمعنى «من أين» أو «متى».', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13838, 1419, 2, 'مَنْ: للعاقل؛ ما وماذا: لغير العاقل (أو حقيقة الشيء)؛ أين: للمكان؛ متى: للزمان؛ كيف: للحال؛ كم: للعدد؛ أيّ: للتعيين (واحد من جماعة)؛ أنّى: بمعنى «من أين» أو «متى».', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13839, 1420, 1, 'الهمزة وهل حرفا استفهام يسألان عن صحّة الخبر، وجوابهما نعم أو لا، مثل: هَلْ نَجَحَ أَخُوكَ؟ — نعم، نجح؛ أَتُحِبُّ الْقِرَاءَةَ؟ — لا. وتزيد الهمزة بأنّها تسأل مع «أم» عن التعيين، مثل: أَقَهْوَةً تَشْرَبُ أَمْ شَايًا؟ والجواب: قهوة أو شايًا، لا نعم أو لا.', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41'),
(13840, 1420, 2, 'الهمزة وهل حرفا استفهام يسألان عن صحّة الخبر، وجوابهما نعم أو لا، مثل: هَلْ نَجَحَ أَخُوكَ؟ — نعم، نجح؛ أَتُحِبُّ الْقِرَاءَةَ؟ — لا. وتزيد الهمزة بأنّها تسأل مع «أم» عن التعيين، مثل: أَقَهْوَةً تَشْرَبُ أَمْ شَايًا؟ والجواب: قهوة أو شايًا، لا نعم أو لا.', 1, '2026-09-30 22:08:41', '2026-09-30 22:08:41');
