(15015, 2008, 1, 'يكفي ثلاثة ممّا يلي: 1) الأعمال العمرانية. 2) الأعمال العسكرية. 3) دراسة الجغرافيين للمجال الجغرافي. 4) أساس لخرائط توزيع الطبقات الجيولوجية أو التربة أو الغطاء النباتي أو شبكة المواصلات.', 1, '2026-09-30 22:10:37', '2026-09-30 22:10:37'),
(15016, 2008, 2, 'يكفي ثلاثة ممّا يلي: 1) الأعمال العمرانية. 2) الأعمال العسكرية. 3) دراسة الجغرافيين للمجال الجغرافي. 4) أساس لخرائط توزيع الطبقات الجيولوجية أو التربة أو الغطاء النباتي أو شبكة المواصلات.', 1, '2026-09-30 22:10:37', '2026-09-30 22:10:37'),
(15017, 2009, 1, 'الخريطة الموضوعاتيّة (أو المتخصّصة) هي الخريطة التي ترسم موضوعاً معيّناً من حيث انتشاره وحدوده ونمط توزّعه، في العالم أو داخل إقليم معيّن. تعدّدت أنواع الخرائط لأنّ السلطات الرسميّة أعدّتها في البداية لأغراض عسكريّة ومدنيّة، ثمّ برزت الحاجة إليها في ميادين مختلفة اقتصاديّة واجتماعيّة.', 1, '2026-09-30 22:10:38', '2026-09-30 22:10:38'),
(15018, 2009, 2, 'الخريطة الموضوعاتيّة (أو المتخصّصة) هي الخريطة التي ترسم موضوعاً معيّناً من حيث انتشاره وحدوده ونمط توزّعه، في العالم أو داخل إقليم معيّن. تعدّدت أنواع الخرائط لأنّ السلطات الرسميّة أعدّتها في البداية لأغراض عسكريّة ومدنيّة، ثمّ برزت الحاجة إليها في ميادين مختلفة اقتصاديّة واجتماعيّة.', 1, '2026-09-30 22:10:38', '2026-09-30 22:10:38'),
(15019, 2010, 1, 'الخرائط التحليليّة تتناول موضوعاً واحداً بصورة تحليليّة، لتبيّن الارتباط بين هذا الموضوع والمجال الجغرافيّ. أمّا الخرائط التركيبيّة فتركّب أكثر من خريطة موضوعاتيّة في خريطة واحدة، فترسم ظاهرات مترابطة أو متفاعلة وتبلور ترابط الظاهرات الطبيعيّة والبشريّة والاقتصاديّة، وهدفها التفسير والاستنتاج: استنتاج العلاقات وتحديد الأسباب وتوقّع التطوّرات الممكنة للمشاكل.', 1, '2026-09-30 22:10:38', '2026-09-30 22:10:38'),
(15020, 2010, 2, 'الخرائط التحليليّة تتناول موضوعاً واحداً بصورة تحليليّة، لتبيّن الارتباط بين هذا الموضوع والمجال الجغرافيّ. أمّا الخرائط التركيبيّة فتركّب أكثر من خريطة موضوعاتيّة في خريطة واحدة، فترسم ظاهرات مترابطة أو متفاعلة وتبلور ترابط الظاهرات الطبيعيّة والبشريّة والاقتصاديّة، وهدفها التفسير والاستنتاج: استنتاج العلاقات وتحديد الأسباب وتوقّع التطوّرات الممكنة للمشاكل.', 1, '2026-09-30 22:10:38', '2026-09-30 22:10:38'),
(15021, 2011, 1, 'هي خريطة تركيبيّة، لأنّها تجمع ظاهرتين مترابطتين في خريطة واحدة هما انسيابات الهجرة وحصّة الفرد من الناتج المحلّيّ الإجماليّ. وفائدتها تفسير دوافع الهجرة وأسبابها، واستنتاج الارتباط بين ثروات الشعوب وهجراتها.', 1, '2026-09-30 22:10:38', '2026-09-30 22:10:38'),
(15022, 2011, 2, 'هي خريطة تركيبيّة، لأنّها تجمع ظاهرتين مترابطتين في خريطة واحدة هما انسيابات الهجرة وحصّة الفرد من الناتج المحلّيّ الإجماليّ. وفائدتها تفسير دوافع الهجرة وأسبابها، واستنتاج الارتباط بين ثروات الشعوب وهجراتها.', 1, '2026-09-30 22:10:38', '2026-09-30 22:10:38'),
(15023, 2012, 1, 'الكثافة العامّة = عدد السكّان في سنة معيّنة ÷ المساحة بالكلم². الكثافة الزراعيّة = عدد العاملين في الزراعة ÷ مساحة الأرض المزروعة (المساحة الزراعيّة). لا تكفي الكثافة العامّة لأنّها تفترض أنّ السكّان يتوزّعون بالتساوي على الأرض، وهذا يناقض الواقع، فالناس تستقطبهم الموارد؛ لذلك نلجأ إلى الكثافات الأخرى لقياس الضغط الفعليّ على الموارد.', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15024, 2012, 2, 'الكثافة العامّة = عدد السكّان في سنة معيّنة ÷ المساحة بالكلم². الكثافة الزراعيّة = عدد العاملين في الزراعة ÷ مساحة الأرض المزروعة (المساحة الزراعيّة). لا تكفي الكثافة العامّة لأنّها تفترض أنّ السكّان يتوزّعون بالتساوي على الأرض، وهذا يناقض الواقع، فالناس تستقطبهم الموارد؛ لذلك نلجأ إلى الكثافات الأخرى لقياس الضغط الفعليّ على الموارد.', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15025, 2013, 1, 'العائق هو الجفاف أو البرودة الشديدة. لكنّ الحاجات الاقتصاديّة دفعت الإنسان إلى تخطّي عوائق الطبيعة، خاصّة بعد اكتشاف النفط، فضاعف إنتاجه من الطاقة وأنشأ المدن المكيّفة، وهي مدن في مناطق شديدة الحرارة أو شديدة البرودة يكون فيها التكييف ضرورة دائمة. مثالان: الصحراء العربيّة، سيبيريا (أو ألاسكا).', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15026, 2013, 2, 'العائق هو الجفاف أو البرودة الشديدة. لكنّ الحاجات الاقتصاديّة دفعت الإنسان إلى تخطّي عوائق الطبيعة، خاصّة بعد اكتشاف النفط، فضاعف إنتاجه من الطاقة وأنشأ المدن المكيّفة، وهي مدن في مناطق شديدة الحرارة أو شديدة البرودة يكون فيها التكييف ضرورة دائمة. مثالان: الصحراء العربيّة، سيبيريا (أو ألاسكا).', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15027, 2014, 1, 'من الأسباب (ثلاثة منها): التوازن الغذائيّ، جودة الخدمات الصحّيّة، ارتفاع مستوى المعيشة، تراجع حوادث العمل، الطبّ الوقائيّ، اكتشاف المضادّات الحيويّة واللقاحات.', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15028, 2015, 1, 'هرم الأعمار تمثيل بياني لتركيب السكّان. فئاته: فئة الفتيان في القاعدة (من الولادة حتّى الرابعة عشرة)، وفئة البالغين في الوسط (من الخامسة عشرة حتّى الرابعة والستّين)، وفئة المسنّين في القمّة (من الخامسة والستّين وما فوق).', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15029, 2016, 1, 'لا، ليس حتماً. فالاكتظاظ السكّانيّ نتيجة لانعدام التوازن بين حاجات الناس والموارد المتوافرة لهم، ويحدث إذا كانت الموارد أقلّ من الحاجة. مثال: اليابان تفوق الهند في كثافتها ولا تشكو من الاكتظاظ لتوافر فرص العمل وارتفاع مداخيل سكّانها، أمّا الهند فترتفع فيها البطالة وتنخفض الأجور وتقلّ الموارد، لذلك تسجّل اكتظاظاً سكّانيّاً.', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15030, 2014, 2, 'من الأسباب (ثلاثة منها): التوازن الغذائيّ، جودة الخدمات الصحّيّة، ارتفاع مستوى المعيشة، تراجع حوادث العمل، الطبّ الوقائيّ، اكتشاف المضادّات الحيويّة واللقاحات.', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15031, 2015, 2, 'هرم الأعمار تمثيل بياني لتركيب السكّان. فئاته: فئة الفتيان في القاعدة (من الولادة حتّى الرابعة عشرة)، وفئة البالغين في الوسط (من الخامسة عشرة حتّى الرابعة والستّين)، وفئة المسنّين في القمّة (من الخامسة والستّين وما فوق).', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15032, 2016, 2, 'لا، ليس حتماً. فالاكتظاظ السكّانيّ نتيجة لانعدام التوازن بين حاجات الناس والموارد المتوافرة لهم، ويحدث إذا كانت الموارد أقلّ من الحاجة. مثال: اليابان تفوق الهند في كثافتها ولا تشكو من الاكتظاظ لتوافر فرص العمل وارتفاع مداخيل سكّانها، أمّا الهند فترتفع فيها البطالة وتنخفض الأجور وتقلّ الموارد، لذلك تسجّل اكتظاظاً سكّانيّاً.', 1, '2026-09-30 22:10:39', '2026-09-30 22:10:39'),
(15033, 2017, 1, 'نسبة الإعالة = (عدد القوى غير العاملة × 100) ÷ عدد القوى العاملة. لكلّ عامل واحد شخصان غير عاملين: (2 × 100) ÷ 1 = 200. إذا ارتفعت نسبة الإعالة انخفضت توفيرات الأسر ونقصت الرساميل، فتكتفي الأسر بالحاجات الأساسية كالغذاء والطبابة والتعليم، وينخفض مستوى المعيشة (باستثناء بعض الدول النامية الغنية كالدول النفطية حيث المداخيل مرتفعة).', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15034, 2017, 2, 'نسبة الإعالة = (عدد القوى غير العاملة × 100) ÷ عدد القوى العاملة. لكلّ عامل واحد شخصان غير عاملين: (2 × 100) ÷ 1 = 200. إذا ارتفعت نسبة الإعالة انخفضت توفيرات الأسر ونقصت الرساميل، فتكتفي الأسر بالحاجات الأساسية كالغذاء والطبابة والتعليم، وينخفض مستوى المعيشة (باستثناء بعض الدول النامية الغنية كالدول النفطية حيث المداخيل مرتفعة).', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15035, 2018, 1, 'فرض التقدّم التقنيّ دراسة أطول فتضاعفت مصاريف الإعالة. ودخلت المرأة ميادين العمل فتأخّر زواجها واكتفت بولد أو اثنين، كما تيسّرت وسائل منع الحمل، ولم تنجح التقديمات الاجتماعيّة في وقف هذا التراجع.', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15036, 2018, 2, 'فرض التقدّم التقنيّ دراسة أطول فتضاعفت مصاريف الإعالة. ودخلت المرأة ميادين العمل فتأخّر زواجها واكتفت بولد أو اثنين، كما تيسّرت وسائل منع الحمل، ولم تنجح التقديمات الاجتماعيّة في وقف هذا التراجع.', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15037, 2019, 1, 'الانفجار السكّانيّ نموّ متسارع ناتج عن انخفاض الوفيات وثبات الولادات على معدّلات عالية. سلكت الدول النامية المسار نفسه الذي سلكته الدول الصناعيّة، لكن بسرعة أكبر وبتوقيت ومدّة متفاوتين.', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15038, 2019, 2, 'الانفجار السكّانيّ نموّ متسارع ناتج عن انخفاض الوفيات وثبات الولادات على معدّلات عالية. سلكت الدول النامية المسار نفسه الذي سلكته الدول الصناعيّة، لكن بسرعة أكبر وبتوقيت ومدّة متفاوتين.', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15039, 2020, 1, 'في الدول الصناعية يوفّر قطاع الخدمات الجزء الأكبر من فرص العمل، لأنّ الآلة حلّت في الأعمال الزراعية والصناعية، ولأنّ التقدّم التكنولوجي (التحكّم الآلي والحاسوب والمعلوماتية) جعل قطاع الخدمات أكثر إنتاجية وربحاً فجذب العمالة. أمّا في الدول النامية فالحصّة الكبرى للزراعة، ويتعايش فيها نمطان من الإنتاج: تقليدي يعتمد على الطاقة العضلية والأدوات البسيطة، وحديث يعتمد على الآلات والأجهزة.', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15040, 2020, 2, 'في الدول الصناعية يوفّر قطاع الخدمات الجزء الأكبر من فرص العمل، لأنّ الآلة حلّت في الأعمال الزراعية والصناعية، ولأنّ التقدّم التكنولوجي (التحكّم الآلي والحاسوب والمعلوماتية) جعل قطاع الخدمات أكثر إنتاجية وربحاً فجذب العمالة. أمّا في الدول النامية فالحصّة الكبرى للزراعة، ويتعايش فيها نمطان من الإنتاج: تقليدي يعتمد على الطاقة العضلية والأدوات البسيطة، وحديث يعتمد على الآلات والأجهزة.', 1, '2026-09-30 22:10:40', '2026-09-30 22:10:40'),
(15041, 2021, 1, 'العامل الدافع يدفع السكّان إلى ترك الريف، والعامل الجاذب يشدّهم إلى المدينة. من العوامل الدافعة: انخفاض المداخيل، ضعف الخدمات، البطالة، سوء توزيع الملكية الزراعية. ومن العوامل الجاذبة: تنوّع فرص العمل، والحراك الاجتماعيّ.', 1, '2026-09-30 22:10:41', '2026-09-30 22:10:41'),
(15042, 2021, 2, 'العامل الدافع يدفع السكّان إلى ترك الريف، والعامل الجاذب يشدّهم إلى المدينة. من العوامل الدافعة: انخفاض المداخيل، ضعف الخدمات، البطالة، سوء توزيع الملكية الزراعية. ومن العوامل الجاذبة: تنوّع فرص العمل، والحراك الاجتماعيّ.', 1, '2026-09-30 22:10:41', '2026-09-30 22:10:41'),
(15043, 2022, 1, 'هجرة الأدمغة هي هجرة الباحثين وأساتذة الجامعات وأصحاب الاختصاصات العالية. الخسارة الأولى فقدان الكفاءة البشرية نفسها، والخسارة الثانية ضياع ما أنفقه البلد على إعدادها خلال الدراسة.', 1, '2026-09-30 22:10:41', '2026-09-30 22:10:41'),
(15044, 2022, 2, 'هجرة الأدمغة هي هجرة الباحثين وأساتذة الجامعات وأصحاب الاختصاصات العالية. الخسارة الأولى فقدان الكفاءة البشرية نفسها، والخسارة الثانية ضياع ما أنفقه البلد على إعدادها خلال الدراسة.', 1, '2026-09-30 22:10:41', '2026-09-30 22:10:41'),
(15045, 2023, 1, 'تنعش التحويلات المالية اقتصاد الأسر وتدعم ميزان المدفوعات. وميزان المدفوعات هو المقارنة بين الأموال الخارجة من البلد والداخلة إليه.', 1, '2026-09-30 22:10:41', '2026-09-30 22:10:41'),
(15046, 2023, 2, 'تنعش التحويلات المالية اقتصاد الأسر وتدعم ميزان المدفوعات. وميزان المدفوعات هو المقارنة بين الأموال الخارجة من البلد والداخلة إليه.', 1, '2026-09-30 22:10:41', '2026-09-30 22:10:41'),
(15047, 2024, 1, 'الزراعة التجارية مخصّصة للتصدير إلى الأسواق العالمية، ومن أمثلتها الأناناس والكاكاو والبنّ. أمّا الزراعة الاكتفائية فتلبّي حاجات ذاتية، أسرية أو قروية، ومن أمثلتها الزراعات التقليدية وتربية الماشية.', 1, '2026-09-30 22:10:42', '2026-09-30 22:10:42'),
(15048, 2024, 2, 'الزراعة التجارية مخصّصة للتصدير إلى الأسواق العالمية، ومن أمثلتها الأناناس والكاكاو والبنّ. أمّا الزراعة الاكتفائية فتلبّي حاجات ذاتية، أسرية أو قروية، ومن أمثلتها الزراعات التقليدية وتربية الماشية.', 1, '2026-09-30 22:10:42', '2026-09-30 22:10:42'),
(15049, 2025, 1, 'ترتفع الإنتاجية بفضل المكننة، والأسمدة الكيماوية، والانتقاء العلمي للبذور، ومكافحة الأمراض. من المشاكل: كلفة الزراعة الحديثة الباهظة، أو تلوّث المياه وتدهور التربة بسبب الأسمدة والمبيدات. ومن إجراءات الحكومات: تحديد كميات الإنتاج، أو ترك بعض الأراضي بوراً، أو توسيع الغابات.', 1, '2026-09-30 22:10:42', '2026-09-30 22:10:42'),
(15050, 2025, 2, 'ترتفع الإنتاجية بفضل المكننة، والأسمدة الكيماوية، والانتقاء العلمي للبذور، ومكافحة الأمراض. من المشاكل: كلفة الزراعة الحديثة الباهظة، أو تلوّث المياه وتدهور التربة بسبب الأسمدة والمبيدات. ومن إجراءات الحكومات: تحديد كميات الإنتاج، أو ترك بعض الأراضي بوراً، أو توسيع الغابات.', 1, '2026-09-30 22:10:42', '2026-09-30 22:10:42'),
(15051, 2026, 1, 'المدينة تجمّع عمراني وبشري، أي مساحة محدّدة فيها مبانٍ وسكّان. وهي حلقة تنظيمية لأنّها مركز قيادي تتجمّع فيه المؤسّسات السياسية والإدارية والفكرية والخدمات. كما تنظّم محيطها، فهي توجّه الريف لتأمين الغذاء والمواد الأوّلية والأسواق.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15052, 2026, 2, 'المدينة تجمّع عمراني وبشري، أي مساحة محدّدة فيها مبانٍ وسكّان. وهي حلقة تنظيمية لأنّها مركز قيادي تتجمّع فيه المؤسّسات السياسية والإدارية والفكرية والخدمات. كما تنظّم محيطها، فهي توجّه الريف لتأمين الغذاء والمواد الأوّلية والأسواق.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15053, 2027, 1, 'شجّع الاستعمار الزراعات التجارية على حساب الزراعات الغذائية، كالبنّ في البرازيل والشاي في سريلانكا والكرمة في الجزائر. وشقّ طرق مواصلات تخدم مصالحه، تربط المدن المرافئ بمراكز الإنتاج.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15054, 2027, 2, 'شجّع الاستعمار الزراعات التجارية على حساب الزراعات الغذائية، كالبنّ في البرازيل والشاي في سريلانكا والكرمة في الجزائر. وشقّ طرق مواصلات تخدم مصالحه، تربط المدن المرافئ بمراكز الإنتاج.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15055, 2028, 1, 'الأحياء العشوائية هي أحياء أنشأها النازحون عشوائياً في ضواحي المدينة، دون أيّ تخطيط أو هندسة، ولا تتوافر فيها شروط الحياة المناسبة. نتج عن التزايد السكاني (بسبب ارتفاع نسبة المواليد والنزوح الواسع من الريف) نقص كبير في الأبنية، فاضطرّ كثير من السكان إلى العيش في أحياء عشوائية النموّ ومساكن مزرية.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15056, 2028, 2, 'الأحياء العشوائية هي أحياء أنشأها النازحون عشوائياً في ضواحي المدينة، دون أيّ تخطيط أو هندسة، ولا تتوافر فيها شروط الحياة المناسبة. نتج عن التزايد السكاني (بسبب ارتفاع نسبة المواليد والنزوح الواسع من الريف) نقص كبير في الأبنية، فاضطرّ كثير من السكان إلى العيش في أحياء عشوائية النموّ ومساكن مزرية.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15057, 2029, 1, 'في الدول المتطوّرة ارتبط نموّ المدن بحركة التصنيع في القرن التاسع عشر. وفي الدول النامية ارتبط في القرن العشرين بالنموّ السكّاني وحركة النزوح الريفي الواسعة. ونتيجة ذلك ظهرت في الدول النامية مشكلات اقتصادية واجتماعية وعمرانية كثيرة.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15058, 2029, 2, 'في الدول المتطوّرة ارتبط نموّ المدن بحركة التصنيع في القرن التاسع عشر. وفي الدول النامية ارتبط في القرن العشرين بالنموّ السكّاني وحركة النزوح الريفي الواسعة. ونتيجة ذلك ظهرت في الدول النامية مشكلات اقتصادية واجتماعية وعمرانية كثيرة.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15059, 2030, 1, 'المشكلات الاجتماعية: التسوّل، وتفكّك العائلة. المشكلات الخدماتية: مياه الشفة، والنفايات المنزلية.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15060, 2030, 2, 'المشكلات الاجتماعية: التسوّل، وتفكّك العائلة. المشكلات الخدماتية: مياه الشفة، والنفايات المنزلية.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15061, 2031, 1, 'من المدن الكبرى (اثنتان منها): طوكيو، نيويورك، باريس. وتؤثّر في الاقتصاد العالمي بشركاتها ومصارفها وبورصاتها وجامعاتها ومراكز أبحاثها ووسائل إعلامها (يكفي ذكر اثنتين).', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15062, 2031, 2, 'من المدن الكبرى (اثنتان منها): طوكيو، نيويورك، باريس. وتؤثّر في الاقتصاد العالمي بشركاتها ومصارفها وبورصاتها وجامعاتها ومراكز أبحاثها ووسائل إعلامها (يكفي ذكر اثنتين).', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15063, 2032, 1, 'واجهت الدول الصناعية هذه المشكلات مبكراً منذ القرن الثامن عشر، وأمّنت الرساميل اللازمة لحلّها، ووسّعت صلاحيات البلديات فصارت أقدر على الإدارة. ومن الوسائل (اثنتان منها): التوسّع المنظّم، إعادة تأهيل الأبنية القديمة، توسيع المساحات الخضراء، إنشاء مراكز جديدة خارج المدينة.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15064, 2032, 2, 'واجهت الدول الصناعية هذه المشكلات مبكراً منذ القرن الثامن عشر، وأمّنت الرساميل اللازمة لحلّها، ووسّعت صلاحيات البلديات فصارت أقدر على الإدارة. ومن الوسائل (اثنتان منها): التوسّع المنظّم، إعادة تأهيل الأبنية القديمة، توسيع المساحات الخضراء، إنشاء مراكز جديدة خارج المدينة.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15065, 2033, 1, 'مفهوم المدينة القائم على نقيض الريف تخطّاه الزمن، وحلّ مكانه مفهوم قائم على التعاون والتكامل. فالريف يحتاج إلى المدينة لتصريف إنتاجه الزراعي وللحصول على الخدمات، والمدينة تجد في الريف امتداداً لأسواقها المالية والسلعية والخدماتية.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15066, 2033, 2, 'مفهوم المدينة القائم على نقيض الريف تخطّاه الزمن، وحلّ مكانه مفهوم قائم على التعاون والتكامل. فالريف يحتاج إلى المدينة لتصريف إنتاجه الزراعي وللحصول على الخدمات، والمدينة تجد في الريف امتداداً لأسواقها المالية والسلعية والخدماتية.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15067, 2034, 1, 'النزوح اليومي وإنشاء مراكز العمل خارج المدينة يشجّعان السكان على البقاء في مساكنهم، فينهض الريف ويخفّ ضيقه الاقتصادي، ولا يبقى نشاطه محصوراً في زراعة الأرض وتربية الماشية. ودورا المدينة: دور إداري لإنجاز المعاملات المتعلّقة بالدولة، ودور خدماتي في التعليم العالي (الجامعات) والمستشفيات المتخصّصة.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15068, 2034, 2, 'النزوح اليومي وإنشاء مراكز العمل خارج المدينة يشجّعان السكان على البقاء في مساكنهم، فينهض الريف ويخفّ ضيقه الاقتصادي، ولا يبقى نشاطه محصوراً في زراعة الأرض وتربية الماشية. ودورا المدينة: دور إداري لإنجاز المعاملات المتعلّقة بالدولة، ودور خدماتي في التعليم العالي (الجامعات) والمستشفيات المتخصّصة.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15069, 2035, 1, 'لم تعد الحدود واضحة، بل تتراجع وتندثر. الأدلّة (اثنان منها): المدينة تتوسّع على حساب المساحات المتاخمة لها؛ تنشئ مصانع ومعامل ومراكز عمل في الريف؛ المجتمع والثقافة في الريف يقتربان من المدينة؛ أهل المدن يسكنون الريف ويستثمرون فيه.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15070, 2035, 2, 'لم تعد الحدود واضحة، بل تتراجع وتندثر. الأدلّة (اثنان منها): المدينة تتوسّع على حساب المساحات المتاخمة لها؛ تنشئ مصانع ومعامل ومراكز عمل في الريف؛ المجتمع والثقافة في الريف يقتربان من المدينة؛ أهل المدن يسكنون الريف ويستثمرون فيه.', 1, '2026-09-30 22:10:43', '2026-09-30 22:10:43'),
(15071, 2036, 1, '- السكّة الحديدية حرّرت المدن من حدودها القديمة واختصرت الوقت والمسافات.\n- الطائرة قرّبت المسافات وسهّلت نقل البضائع إلى البلدان البعيدة.\n- الإعلام صار في متناول الجميع بعد أن كان محصوراً بأهل المدن.\n- فساوى الإعلام بين الناس عامّة في اكتشاف المعرفة والتزوّد بالمعلومات.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15072, 2036, 2, '- السكّة الحديدية حرّرت المدن من حدودها القديمة واختصرت الوقت والمسافات.\n- الطائرة قرّبت المسافات وسهّلت نقل البضائع إلى البلدان البعيدة.\n- الإعلام صار في متناول الجميع بعد أن كان محصوراً بأهل المدن.\n- فساوى الإعلام بين الناس عامّة في اكتشاف المعرفة والتزوّد بالمعلومات.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15073, 2037, 1, 'نموّ أحياء المال والأعمال مرتبط بتدفّق الرساميل الأجنبية التي تبحث دائماً عن المشاريع الأكثر ربحاً، فيخضع نموّ المدينة لمشيئة أصحاب الأسهم والشركات الأجنبية. لذلك يهتزّ استقرار المدينة عند الأزمات المالية والتجارية الدولية، كما في هونغ كونغ، فازدهار المدينة لم يعد مرتبطاً بإرادتها الداخلية وحدها.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15074, 2037, 2, 'نموّ أحياء المال والأعمال مرتبط بتدفّق الرساميل الأجنبية التي تبحث دائماً عن المشاريع الأكثر ربحاً، فيخضع نموّ المدينة لمشيئة أصحاب الأسهم والشركات الأجنبية. لذلك يهتزّ استقرار المدينة عند الأزمات المالية والتجارية الدولية، كما في هونغ كونغ، فازدهار المدينة لم يعد مرتبطاً بإرادتها الداخلية وحدها.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15075, 2038, 1, 'الكون هو الفضاء الشاسع الذي تشغل ملايين المجرّات والسُّدُم جزءاً منه، وتفصل بينها مساحات هائلة. تُقاس أبعاده بالسنة الضوئية لأنّه يمتدّ إلى حوالى 15 مليار سنة ضوئية، وهذه مسافات كبيرة جداً لا يصلح الكيلومتر لقياسها.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15076, 2038, 2, 'الكون هو الفضاء الشاسع الذي تشغل ملايين المجرّات والسُّدُم جزءاً منه، وتفصل بينها مساحات هائلة. تُقاس أبعاده بالسنة الضوئية لأنّه يمتدّ إلى حوالى 15 مليار سنة ضوئية، وهذه مسافات كبيرة جداً لا يصلح الكيلومتر لقياسها.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15077, 2039, 1, 'سهولة المواصلات والاتصالات جعلت الكرة الأرضية ضيعة كونية، فضعفت الفوارق بين المناطق وانفتحت كلّها على حضارة العولمة. من ملامحها: التنميط الحاصل في طرق العيش وأنواع المأكل والملبس والأدوات (أشكال موحّدة للسلوك والسلع والاستهلاك والتفكير)، والاتصالات السريعة التي يؤمّنها الإنترنت والكمبيوتر ووسائل الإعلام.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15078, 2039, 2, 'سهولة المواصلات والاتصالات جعلت الكرة الأرضية ضيعة كونية، فضعفت الفوارق بين المناطق وانفتحت كلّها على حضارة العولمة. من ملامحها: التنميط الحاصل في طرق العيش وأنواع المأكل والملبس والأدوات (أشكال موحّدة للسلوك والسلع والاستهلاك والتفكير)، والاتصالات السريعة التي يؤمّنها الإنترنت والكمبيوتر ووسائل الإعلام.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15079, 2040, 1, 'الموقف الأوّل: بعض النظريات الفلكية ترى أن لا حدود زمنية لنشأة الكون. الموقف الثاني: نظريات أخرى تقدّر عمره بمليارات السنين، وترى أنّ الكون في تغيّر مستمرّ، وأنّ المجرّات تتباعد بعضها عن بعض.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15080, 2040, 2, 'الموقف الأوّل: بعض النظريات الفلكية ترى أن لا حدود زمنية لنشأة الكون. الموقف الثاني: نظريات أخرى تقدّر عمره بمليارات السنين، وترى أنّ الكون في تغيّر مستمرّ، وأنّ المجرّات تتباعد بعضها عن بعض.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15081, 2041, 1, 'الكواكب الصخريّة: عطارد والزهرة والأرض والمريخ؛ تتقارب في حجمها، ويغلب على تركيبها الصخر والمعادن، وخاصّة الحديد. الكواكب الغازيّة: المشتري وزحل وأورانوس ونبتون؛ تتميّز بحجمها الكبير وبالغازات المتجمّدة فيها.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15082, 2041, 2, 'الكواكب الصخريّة: عطارد والزهرة والأرض والمريخ؛ تتقارب في حجمها، ويغلب على تركيبها الصخر والمعادن، وخاصّة الحديد. الكواكب الغازيّة: المشتري وزحل وأورانوس ونبتون؛ تتميّز بحجمها الكبير وبالغازات المتجمّدة فيها.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15083, 2042, 1, 'صاحبها العالِم الروسي جورج غامو. خلاصتها: الكون الحالي نتيجة انفجار كبير لا يدّعي صاحب النظرية معرفة أسبابه، دام جزءاً صغيراً من الثانية، وكان الكون لحظتها إشعاعات شديدة الحرارة، ثمّ صارت الظروف كافية لتشكّل نوى الذرّات، وبالتالي المادّة. ومن براهينها وجود الدوتيريوم في سديم أوريون.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15084, 2042, 2, 'صاحبها العالِم الروسي جورج غامو. خلاصتها: الكون الحالي نتيجة انفجار كبير لا يدّعي صاحب النظرية معرفة أسبابه، دام جزءاً صغيراً من الثانية، وكان الكون لحظتها إشعاعات شديدة الحرارة، ثمّ صارت الظروف كافية لتشكّل نوى الذرّات، وبالتالي المادّة. ومن براهينها وجود الدوتيريوم في سديم أوريون.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15085, 2043, 1, 'أطلق بطليموس اليونانيّ نظريّة الأرض الثابتة، وبقيت آراؤه سائدة حتّى القرون الوسطى. ثمّ جعل كوبرنيك الشمس مركزاً والأرض تدور حولها. ودعم غاليلي الإيطاليّ نظريّة كوبرنيك، فاعتُقل وحوكم وأُجبر على التخلّي عن معتقده، وأمضى باقي حياته في السجن.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15086, 2043, 2, 'أطلق بطليموس اليونانيّ نظريّة الأرض الثابتة، وبقيت آراؤه سائدة حتّى القرون الوسطى. ثمّ جعل كوبرنيك الشمس مركزاً والأرض تدور حولها. ودعم غاليلي الإيطاليّ نظريّة كوبرنيك، فاعتُقل وحوكم وأُجبر على التخلّي عن معتقده، وأمضى باقي حياته في السجن.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15087, 2044, 1, 'تنقسم النظريّات إلى فئة تقول بوحدة النشأة، وفئة تقول بتعدّدها. نظريّة لابلاس: المجموعة، بما فيها الشمس، من أصل واحد هو سديم غازيّ متوهّج عظيم الحجم؛ أدّى دورانه حول نفسه إلى انتفاخ وسطه، فزادت القوّة الطاردة على قوّة الجذب؛ فانفصلت عنه حلقات غازيّة كوّنت الكواكب، وما بقي منه كوّن الشمس.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15088, 2044, 2, 'تنقسم النظريّات إلى فئة تقول بوحدة النشأة، وفئة تقول بتعدّدها. نظريّة لابلاس: المجموعة، بما فيها الشمس، من أصل واحد هو سديم غازيّ متوهّج عظيم الحجم؛ أدّى دورانه حول نفسه إلى انتفاخ وسطه، فزادت القوّة الطاردة على قوّة الجذب؛ فانفصلت عنه حلقات غازيّة كوّنت الكواكب، وما بقي منه كوّن الشمس.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15089, 2045, 1, '1- حركة الشمس الظاهريّة اليوميّة. 2- الجهات الأصليّة. 3- تعاقب الليل والنهار. 4- تعاقب الحرارة والبرودة. 5- اختلاف التوقيت. 6- انحراف الأجسام المتحرّكة. 7- تبدّل شكل الأرض (انتفاخ عند الاستواء وتفلطح عند القطبين).', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15090, 2045, 2, '1- حركة الشمس الظاهريّة اليوميّة. 2- الجهات الأصليّة. 3- تعاقب الليل والنهار. 4- تعاقب الحرارة والبرودة. 5- اختلاف التوقيت. 6- انحراف الأجسام المتحرّكة. 7- تبدّل شكل الأرض (انتفاخ عند الاستواء وتفلطح عند القطبين).', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15091, 2046, 1, 'الأرض تدور من الغرب إلى الشرق، لذلك نزيد ساعة عن كلّ حزمة شرقاً: 10 + 2 = الثانية عشرة ظهراً. وننقص ساعة عن كلّ حزمة غرباً: 10 − 2 = الثامنة صباحاً.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15092, 2046, 2, 'الأرض تدور من الغرب إلى الشرق، لذلك نزيد ساعة عن كلّ حزمة شرقاً: 10 + 2 = الثانية عشرة ظهراً. وننقص ساعة عن كلّ حزمة غرباً: 10 − 2 = الثامنة صباحاً.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15093, 2047, 1, 'التيّار المتّجه نحو القطب الشماليّ يقع في النصف الشماليّ فينحرف إلى يمين مساره، والتيّار المتّجه نحو القطب الجنوبيّ يقع في النصف الجنوبيّ فينحرف إلى يسار مساره. والقوّة المسبّبة هي قوّة كوريوليس، الناتجة عن الحركة المحوريّة وتفاوت السرعات على خطّ الطول الواحد.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15094, 2047, 2, 'التيّار المتّجه نحو القطب الشماليّ يقع في النصف الشماليّ فينحرف إلى يمين مساره، والتيّار المتّجه نحو القطب الجنوبيّ يقع في النصف الجنوبيّ فينحرف إلى يسار مساره. والقوّة المسبّبة هي قوّة كوريوليس، الناتجة عن الحركة المحوريّة وتفاوت السرعات على خطّ الطول الواحد.', 1, '2026-09-30 22:10:45', '2026-09-30 22:10:45'),
(15095, 2048, 1, 'يُتمّ القمر دورته حول الأرض في 27 يوماً و7 ساعات و43 دقيقة. أمّا الدورة الاقترانية فتبدأ في المحاق (الاقتران) وتنتهي في وضع الاقتران أيضاً، وتبلغ 29 يوماً و12 ساعة و44 دقيقة. وهي أطول لأنّ الأرض تكون خلال دورة القمر قد قطعت قوساً في دورتها حول الشمس، فيحتاج القمر إلى يومين وخمس ساعات إضافية ليبلغ الاقتران من جديد.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15096, 2049, 1, 'الأوج هو أبعد نقطة عن الشمس، وتبلغه الأرض في أوائل تموز (بعد أيام من الانقلاب الصيفي). الحضيض هو أقرب نقطة إلى الشمس، وتبلغه الأرض في أوائل كانون الثاني (بعد أيام من الانقلاب الشتوي). والسبب هو الشكل البيضاوي للمدار الإهليليجي.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15097, 2049, 2, 'الأوج هو أبعد نقطة عن الشمس، وتبلغه الأرض في أوائل تموز (بعد أيام من الانقلاب الصيفي). الحضيض هو أقرب نقطة إلى الشمس، وتبلغه الأرض في أوائل كانون الثاني (بعد أيام من الانقلاب الشتوي). والسبب هو الشكل البيضاوي للمدار الإهليليجي.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15098, 2048, 2, 'يُتمّ القمر دورته حول الأرض في 27 يوماً و7 ساعات و43 دقيقة. أمّا الدورة الاقترانية فتبدأ في المحاق (الاقتران) وتنتهي في وضع الاقتران أيضاً، وتبلغ 29 يوماً و12 ساعة و44 دقيقة. وهي أطول لأنّ الأرض تكون خلال دورة القمر قد قطعت قوساً في دورتها حول الشمس، فيحتاج القمر إلى يومين وخمس ساعات إضافية ليبلغ الاقتران من جديد.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15099, 2050, 1, 'الغلاف الجوّيّ غلاف غازيّ يحيط بالأرض، يتألّف من مجموعة كبيرة من الغازات ومن بعض الأجسام الصلبة والسائلة. يشكّل غازا الأزوت والأوكسجين معاً 99٪ منه، ويتوزّع الـ 1٪ الباقي على غازات كثيرة منها الأرغون وثاني أوكسيد الكربون والهيدروجين والرادون.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15100, 2050, 2, 'الغلاف الجوّيّ غلاف غازيّ يحيط بالأرض، يتألّف من مجموعة كبيرة من الغازات ومن بعض الأجسام الصلبة والسائلة. يشكّل غازا الأزوت والأوكسجين معاً 99٪ منه، ويتوزّع الـ 1٪ الباقي على غازات كثيرة منها الأرغون وثاني أوكسيد الكربون والهيدروجين والرادون.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15101, 2051, 1, 'لأنّ الدائرة الضوئية تقسم دائرة الاستواء إلى نصفين متساويين طوال السنة. وفي 21 حزيران تغمر الدائرة الضوئية المنطقة القطبية الشمالية، فتبقى مضاءة 24 ساعة، بينما يسود الظلام المنطقة القطبية الجنوبية المدّة نفسها.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15102, 2051, 2, 'لأنّ الدائرة الضوئية تقسم دائرة الاستواء إلى نصفين متساويين طوال السنة. وفي 21 حزيران تغمر الدائرة الضوئية المنطقة القطبية الشمالية، فتبقى مضاءة 24 ساعة، بينما يسود الظلام المنطقة القطبية الجنوبية المدّة نفسها.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15103, 2052, 1, 'المدّ هو تقدّم مياه المحيطات والبحار فوق الشواطئ، والجزر هو انحسارها عنها، وتعود هذه الحركة إلى جاذبية القمر والشمس على الأرض. عندما يمارس القمر والشمس جاذبيتهما على المحيط، تندفع المياه في اتّجاهين متعاكسين: نحو منطقة الجذب ونحو المنطقة المقابلة لها، وهذا يحدث توازناً في توزّع الثقل، لذلك تشهد كلّ منطقة مدّين خلال هذه المدّة.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15104, 2052, 2, 'المدّ هو تقدّم مياه المحيطات والبحار فوق الشواطئ، والجزر هو انحسارها عنها، وتعود هذه الحركة إلى جاذبية القمر والشمس على الأرض. عندما يمارس القمر والشمس جاذبيتهما على المحيط، تندفع المياه في اتّجاهين متعاكسين: نحو منطقة الجذب ونحو المنطقة المقابلة لها، وهذا يحدث توازناً في توزّع الثقل، لذلك تشهد كلّ منطقة مدّين خلال هذه المدّة.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15105, 2053, 1, 'لأنّ القطب الجنوبي يقع في المنطقة القطبية، حيث تغيب أشعة الشمس مدّة ستّة أشهر، وحين تصله الأشعة تكون شديدة الميل. لذلك يكون الصيف قصيراً والشتاء طويلاً، فيسيطر الجليد إجمالاً.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15106, 2053, 2, 'لأنّ القطب الجنوبي يقع في المنطقة القطبية، حيث تغيب أشعة الشمس مدّة ستّة أشهر، وحين تصله الأشعة تكون شديدة الميل. لذلك يكون الصيف قصيراً والشتاء طويلاً، فيسيطر الجليد إجمالاً.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15107, 2054, 1, 'التلوّث من المصانع والسيّارات يرفع نسبة ثاني أوكسيد الكربون، فيزداد امتصاص الأشعة التي تبثّها الأرض وترتفع حرارة سطحها، فيذوب قسم كبير من الجليديّات ويرتفع مستوى البحار. ومن النتائج: غمر مناطق ساحليّة منخفضة، وتلوّث المياه الجوفيّة العذبة القريبة من البحار.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15108, 2054, 2, 'التلوّث من المصانع والسيّارات يرفع نسبة ثاني أوكسيد الكربون، فيزداد امتصاص الأشعة التي تبثّها الأرض وترتفع حرارة سطحها، فيذوب قسم كبير من الجليديّات ويرتفع مستوى البحار. ومن النتائج: غمر مناطق ساحليّة منخفضة، وتلوّث المياه الجوفيّة العذبة القريبة من البحار.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15109, 2055, 1, 'يحدث الخسوف حين يكون القمر بدراً والأرض بين الشمس والقمر، ويحدث الكسوف حين يكون القمر محاقاً أي بين الشمس والأرض، وفي الحالتين تكون المراكز الثلاثة على استقامة واحدة. الخسوف نوعان: كلّي يختفي فيه القمر تماماً، وجزئي يقع فيه جزء من القمر في ظلّ الأرض. ولا يحدث الخسوف كلّ شهر لأنّ مدار القمر يتقاطع مع مدار الأرض بزاوية بسيطة لا تزيد على خمس درجات.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15110, 2055, 2, 'يحدث الخسوف حين يكون القمر بدراً والأرض بين الشمس والقمر، ويحدث الكسوف حين يكون القمر محاقاً أي بين الشمس والأرض، وفي الحالتين تكون المراكز الثلاثة على استقامة واحدة. الخسوف نوعان: كلّي يختفي فيه القمر تماماً، وجزئي يقع فيه جزء من القمر في ظلّ الأرض. ولا يحدث الخسوف كلّ شهر لأنّ مدار القمر يتقاطع مع مدار الأرض بزاوية بسيطة لا تزيد على خمس درجات.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15111, 2056, 1, 'من المخاطر: سرطان الجلد وخلل المناعة وأمراض العين عند الإنسان، وتدنّي العلقيّات المغذّية للأسماك وتباطؤ نموّ النباتات، وتغيّر مسار الرياح وتوزّع المناخات (تُقبل أيّ ثلاثة). والحلّ: الاستغناء كلّياً عن المركّبات الكلوريّة الفلوريّة الكربونيّة واستبدالها بمركّبات لا تضرّ بطبقة الأوزون، وقد نظّم بروتوكول مونتريال تخفيض إنتاجها واستهلاكها تدريجياً حتى الصفر.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15112, 2056, 2, 'من المخاطر: سرطان الجلد وخلل المناعة وأمراض العين عند الإنسان، وتدنّي العلقيّات المغذّية للأسماك وتباطؤ نموّ النباتات، وتغيّر مسار الرياح وتوزّع المناخات (تُقبل أيّ ثلاثة). والحلّ: الاستغناء كلّياً عن المركّبات الكلوريّة الفلوريّة الكربونيّة واستبدالها بمركّبات لا تضرّ بطبقة الأوزون، وقد نظّم بروتوكول مونتريال تخفيض إنتاجها واستهلاكها تدريجياً حتى الصفر.', 1, '2026-09-30 22:10:47', '2026-09-30 22:10:47'),
(15113, 2057, 1, 'في الليل، ومع غياب الشمس، يبثّ سطح الأرض الأشعة التي اختزنها نهاراً. يمتصّ بخار الماء وثاني أوكسيد الكربون قسماً كبيراً من هذه الأشعة، ثمّ يعيدان بثّها، فيتّجه قسم نحو الفضاء ويعود قسم آخر إلى الأرض ويدفئها. ولولا هذه العملية لكان معدّل حرارة سطح الأرض تحت الصفر.', 1, '2026-09-30 22:10:48', '2026-09-30 22:10:48'),
(15114, 2057, 2, 'في الليل، ومع غياب الشمس، يبثّ سطح الأرض الأشعة التي اختزنها نهاراً. يمتصّ بخار الماء وثاني أوكسيد الكربون قسماً كبيراً من هذه الأشعة، ثمّ يعيدان بثّها، فيتّجه قسم نحو الفضاء ويعود قسم آخر إلى الأرض ويدفئها. ولولا هذه العملية لكان معدّل حرارة سطح الأرض تحت الصفر.', 1, '2026-09-30 22:10:48', '2026-09-30 22:10:48'),
(15115, 2058, 1, 'المدى الحراري هو الفرق بين أعلى درجة وأدنى درجة. يصغر في المناطق الاستوائية ويتّسع نحو القطبين بسبب اختلاف مدّة الليل والنهار وميلان أشعة الشمس.', 1, '2026-09-30 22:10:48', '2026-09-30 22:10:48'),
(15116, 2058, 2, 'المدى الحراري هو الفرق بين أعلى درجة وأدنى درجة. يصغر في المناطق الاستوائية ويتّسع نحو القطبين بسبب اختلاف مدّة الليل والنهار وميلان أشعة الشمس.', 1, '2026-09-30 22:10:48', '2026-09-30 22:10:48'),
(15117, 2059, 1, 'بعد الثورة الصناعية زاد التلوّث في الجوّ، وازدادت غازات مثل ثاني أوكسيد الكربون والميتان وأكاسيد النيتروجين، فارتفعت قدرة الجوّ على الاحتباس الحراري وارتفعت درجات الحرارة. من النتائج (أيّ اثنتين): ذوبان جليديات القطبين، ارتفاع مستوى البحار الذي يهدّد بغمر مناطق ساحلية، تغيّر نطاقات الرطوبة والجفاف، تزحزح أماكن الزراعات الغذائية الأساسية.', 1, '2026-09-30 22:10:48', '2026-09-30 22:10:48'),
(15118, 2059, 2, 'بعد الثورة الصناعية زاد التلوّث في الجوّ، وازدادت غازات مثل ثاني أوكسيد الكربون والميتان وأكاسيد النيتروجين، فارتفعت قدرة الجوّ على الاحتباس الحراري وارتفعت درجات الحرارة. من النتائج (أيّ اثنتين): ذوبان جليديات القطبين، ارتفاع مستوى البحار الذي يهدّد بغمر مناطق ساحلية، تغيّر نطاقات الرطوبة والجفاف، تزحزح أماكن الزراعات الغذائية الأساسية.', 1, '2026-09-30 22:10:48', '2026-09-30 22:10:48'),
(15119, 2060, 1, 'المنخفض الحراريّ سببه تسخّن الهواء، فيتمدّد ويخفّ وزنه ويصعد. أمّا المنخفض الديناميكيّ فسببه تصادم تيّارين من الرياح، فتدفع الرياح الأقلّ حرارة الرياح الأكثر حرارة نحو الأعلى. وفي الحالتين يصعد الهواء فيخفّ الضغط عند السطح.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15120, 2060, 2, 'المنخفض الحراريّ سببه تسخّن الهواء، فيتمدّد ويخفّ وزنه ويصعد. أمّا المنخفض الديناميكيّ فسببه تصادم تيّارين من الرياح، فتدفع الرياح الأقلّ حرارة الرياح الأكثر حرارة نحو الأعلى. وفي الحالتين يصعد الهواء فيخفّ الضغط عند السطح.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15121, 2061, 1, 'الفروقات الحراريّة قليلة (لا تتعدّى ثلاث درجات) لأنّ أشعّة الشمس تبقى شبه عموديّة طوال السنة فتبقى الحرارة مرتفعة وثابتة، ولأنّ الهواء مشبع دائماً ببخار الماء.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15122, 2061, 2, 'الفروقات الحراريّة قليلة (لا تتعدّى ثلاث درجات) لأنّ أشعّة الشمس تبقى شبه عموديّة طوال السنة فتبقى الحرارة مرتفعة وثابتة، ولأنّ الهواء مشبع دائماً ببخار الماء.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15123, 2062, 1, 'يهبط الهواء فوق المناطق المداريّة مشكّلاً سلسلة من المرتفعات الجوّيّة، وهذا الهواء الهابط جافّ ومرتفع الحرارة، لذلك تسود الصحاري في نطاق تأثيره، ويسود فيها المناخ الصحراويّ لأنّها تحت التأثير الدائم للمرتفعات المداريّة.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15124, 2062, 2, 'يهبط الهواء فوق المناطق المداريّة مشكّلاً سلسلة من المرتفعات الجوّيّة، وهذا الهواء الهابط جافّ ومرتفع الحرارة، لذلك تسود الصحاري في نطاق تأثيره، ويسود فيها المناخ الصحراويّ لأنّها تحت التأثير الدائم للمرتفعات المداريّة.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15125, 2063, 1, 'رطوبة الإشباع تتغيّر مع الحرارة، فهي مرتفعة في الهواء الحارّ ومتدنّية في الهواء البارد. لذلك يستطيع الهواء الحارّ أن يمتصّ كميات كبيرة من بخار الماء قبل أن يبلغ الإشباع، وهذه الحمولة الكبيرة تعطي أمطاراً غزيرة، أمّا الهواء البارد فحمولته قليلة فتشحّ أمطاره.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15126, 2063, 2, 'رطوبة الإشباع تتغيّر مع الحرارة، فهي مرتفعة في الهواء الحارّ ومتدنّية في الهواء البارد. لذلك يستطيع الهواء الحارّ أن يمتصّ كميات كبيرة من بخار الماء قبل أن يبلغ الإشباع، وهذه الحمولة الكبيرة تعطي أمطاراً غزيرة، أمّا الهواء البارد فحمولته قليلة فتشحّ أمطاره.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15127, 2064, 1, 'في المناخين يكون الصيف ممطراً والشتاء جافّاً. يتأثّر المناخ المداريّ بالرياح التجاريّة الدائمة، أمّا المناخ الموسميّ فرياحه تهبّ صيفاً من المحيط الهنديّ نحو اليابسة مشبعة بالرطوبة، وشتاءً من اليابسة الباردة نحو المحيط باردة وجافّة. والفيضانات سببها الأمطار الغزيرة صيفاً التي تتزامن مع ذوبان الثلوج في جبال الهيمالايا.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15128, 2064, 2, 'في المناخين يكون الصيف ممطراً والشتاء جافّاً. يتأثّر المناخ المداريّ بالرياح التجاريّة الدائمة، أمّا المناخ الموسميّ فرياحه تهبّ صيفاً من المحيط الهنديّ نحو اليابسة مشبعة بالرطوبة، وشتاءً من اليابسة الباردة نحو المحيط باردة وجافّة. والفيضانات سببها الأمطار الغزيرة صيفاً التي تتزامن مع ذوبان الثلوج في جبال الهيمالايا.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15129, 2065, 1, 'تتحرّك خلايا الرياح الدائمة وفق الحركة الظاهريّة للشمس. في الصيف تتزحزح نحو الشمال فتقع المناطق المتوسّطيّة تحت تأثير المرتفعات المداريّة، وفي الشتاء تتزحزح نحو الجنوب فتقع تحت تأثير منخفضات المناطق المعتدلة.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15130, 2065, 2, 'تتحرّك خلايا الرياح الدائمة وفق الحركة الظاهريّة للشمس. في الصيف تتزحزح نحو الشمال فتقع المناطق المتوسّطيّة تحت تأثير المرتفعات المداريّة، وفي الشتاء تتزحزح نحو الجنوب فتقع تحت تأثير منخفضات المناطق المعتدلة.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15131, 2066, 1, 'تعترض التضاريس الجبلية الهواء الرطب فيرتفع ويبرد ويتكاثف، فيهطل أمطاراً غزيرة على السفوح الأمامية المواجهة له. ثمّ يصل إلى السفوح الخلفية وقد فقد جزءاً مهمّاً من حمولته بالرطوبة، فيسود فيها الجفاف. وتُعرف هذه السفوح الجافّة بمنطقة ظلّ المطر.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15132, 2066, 2, 'تعترض التضاريس الجبلية الهواء الرطب فيرتفع ويبرد ويتكاثف، فيهطل أمطاراً غزيرة على السفوح الأمامية المواجهة له. ثمّ يصل إلى السفوح الخلفية وقد فقد جزءاً مهمّاً من حمولته بالرطوبة، فيسود فيها الجفاف. وتُعرف هذه السفوح الجافّة بمنطقة ظلّ المطر.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15133, 2067, 1, 'في المناطق المداريّة يبقى الانتشار البشريّ محدوداً، ويتركّز في المرتفعات، كإثيوبيا مثلاً.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15134, 2067, 2, 'في المناطق المداريّة يبقى الانتشار البشريّ محدوداً، ويتركّز في المرتفعات، كإثيوبيا مثلاً.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15135, 2068, 1, 'الأمطار الحامضية أمطار ترتفع فيها نسبة الحموضة، تنتج عن امتزاج بخار الماء بالملوّثات المنبعثة من النشاطات الصناعية مثل أكاسيد الكبريت والنيتروجين والرصاص والكربون. من نتائجها (أيّ اثنتين): أضرار بالغة في البيئة والاقتصاد، أذى للغابات والبحيرات في الدول الصناعية، تسريع تآكل الصخور والأبنية والتماثيل.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15136, 2068, 2, 'الأمطار الحامضية أمطار ترتفع فيها نسبة الحموضة، تنتج عن امتزاج بخار الماء بالملوّثات المنبعثة من النشاطات الصناعية مثل أكاسيد الكبريت والنيتروجين والرصاص والكربون. من نتائجها (أيّ اثنتين): أضرار بالغة في البيئة والاقتصاد، أذى للغابات والبحيرات في الدول الصناعية، تسريع تآكل الصخور والأبنية والتماثيل.', 1, '2026-09-30 22:10:49', '2026-09-30 22:10:49'),
(15137, 2069, 1, 'تسيطر على الإقليم الصحراويّ المرتفعات الجوّيّة الديناميكيّة، أي تيّار هوائيّ هابط حارّ وجافّ. ويكون الإشماس قويّاً نهاراً فتسخن الأرض بسرعة، ويتدنّى الاحتباس الحراريّ ليلاً فتفقد الأرض حرارتها بسرعة. فتكون الحرارة عالية نهاراً ومتدنّية ليلاً، ويكون الفرق كبيراً.', 1, '2026-09-30 22:10:50', '2026-09-30 22:10:50'),
(15138, 2069, 2, 'تسيطر على الإقليم الصحراويّ المرتفعات الجوّيّة الديناميكيّة، أي تيّار هوائيّ هابط حارّ وجافّ. ويكون الإشماس قويّاً نهاراً فتسخن الأرض بسرعة، ويتدنّى الاحتباس الحراريّ ليلاً فتفقد الأرض حرارتها بسرعة. فتكون الحرارة عالية نهاراً ومتدنّية ليلاً، ويكون الفرق كبيراً.', 1, '2026-09-30 22:10:50', '2026-09-30 22:10:50'),
(15139, 2070, 1, 'نمت الغابات المتوسّطيّة في فترات سابقة كان مناخها أكثر مطراً، واستثمرها الإنسان منذ القدم فتدنّت رقعتها. وإذا قُطعت لا تتجدّد لأنّ المناخ الحاليّ طويل الجفاف. فحلّت محلّها الغيل، وهي تشكيلات متشابكة يصعب اجتيازها، والبراح، وهي تشكيلات قصيرة ومتباعدة.', 1, '2026-09-30 22:10:50', '2026-09-30 22:10:50'),
(15140, 2070, 2, 'نمت الغابات المتوسّطيّة في فترات سابقة كان مناخها أكثر مطراً، واستثمرها الإنسان منذ القدم فتدنّت رقعتها. وإذا قُطعت لا تتجدّد لأنّ المناخ الحاليّ طويل الجفاف. فحلّت محلّها الغيل، وهي تشكيلات متشابكة يصعب اجتيازها، والبراح، وهي تشكيلات قصيرة ومتباعدة.', 1, '2026-09-30 22:10:50', '2026-09-30 22:10:50'),
(15141, 2071, 1, 'يجذب حوض المتوسّط السيّاح بسبب اعتدال مناخه، وجمال طبيعته، وتنوّع آثاره التي تعود إلى مختلف الحقبات التاريخيّة. وقد أدّى النشاط السياحيّ إلى إشغال جديد للأرض، وإلى تغيير في المنظر الزراعيّ التقليديّ.', 1, '2026-09-30 22:10:50', '2026-09-30 22:10:50'),
(15142, 2071, 2, 'يجذب حوض المتوسّط السيّاح بسبب اعتدال مناخه، وجمال طبيعته، وتنوّع آثاره التي تعود إلى مختلف الحقبات التاريخيّة. وقد أدّى النشاط السياحيّ إلى إشغال جديد للأرض، وإلى تغيير في المنظر الزراعيّ التقليديّ.', 1, '2026-09-30 22:10:50', '2026-09-30 22:10:50'),
(15143, 2072, 1, 'تسيطر البرودة الشديدة على الإقليم القطبيّ لسببين: الأوّل أنّ أشعّة الشمس تسقط مائلة جدّاً على سطحه، والثاني أنّ الجليد يغطّي هذه المناطق معظم أشهر السنة فترتفع نسبة الأشعّة المنعكسة عنه.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15144, 2073, 1, 'المياه عنصر أساسي في الإنتاج: لا زراعة من دون مياه، وإذا توافرت بالقدر الكافي تضاعف المردود، لذلك يرتبط نجاح برامج التنمية الزراعية بزيادة مصادر المياه. وفي الصناعة تشكّل المياه مادة أوّلية في الإنتاج ووسيلة فيه. ونحتاجها كذلك في الاستعمال اليومي والمدني.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15145, 2073, 2, 'المياه عنصر أساسي في الإنتاج: لا زراعة من دون مياه، وإذا توافرت بالقدر الكافي تضاعف المردود، لذلك يرتبط نجاح برامج التنمية الزراعية بزيادة مصادر المياه. وفي الصناعة تشكّل المياه مادة أوّلية في الإنتاج ووسيلة فيه. ونحتاجها كذلك في الاستعمال اليومي والمدني.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15146, 2072, 2, 'تسيطر البرودة الشديدة على الإقليم القطبيّ لسببين: الأوّل أنّ أشعّة الشمس تسقط مائلة جدّاً على سطحه، والثاني أنّ الجليد يغطّي هذه المناطق معظم أشهر السنة فترتفع نسبة الأشعّة المنعكسة عنه.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15147, 2074, 1, 'تتزايد الحاجة إلى المياه من سنة إلى أخرى بسبب النموّ الديموغرافيّ والاقتصاديّ وزيادة المداخيل الفرديّة. ويزيد من حدّة التفاوت في توزّعها (عاملان من): موقع الدولة، نظام الأمطار، كثافة السكان.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15148, 2074, 2, 'تتزايد الحاجة إلى المياه من سنة إلى أخرى بسبب النموّ الديموغرافيّ والاقتصاديّ وزيادة المداخيل الفرديّة. ويزيد من حدّة التفاوت في توزّعها (عاملان من): موقع الدولة، نظام الأمطار، كثافة السكان.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15149, 2075, 1, 'مصادر التلوّث: الأسمدة، والنفايات الصناعية، ومياه الصرف الصحّي، والنفط المتسرّب من الناقلات (ثلاثة منها). نتائجه: تغيير خصائص المياه، وهلاك كمّيات كبيرة من الكائنات البحرية.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15150, 2075, 2, 'مصادر التلوّث: الأسمدة، والنفايات الصناعية، ومياه الصرف الصحّي، والنفط المتسرّب من الناقلات (ثلاثة منها). نتائجه: تغيير خصائص المياه، وهلاك كمّيات كبيرة من الكائنات البحرية.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15151, 2076, 1, 'الأطراف: ترفع التيّارات البحريّة الحارّة حرارتها فيبقى معدّلها السنوي فوق الصفر، وتتجاوز متساقطاتها ألف ملّيمتر موزّعة على مدار السنة، ونسبة الثلوج فيها أدنى. الداخل: بعيد عن هذه التيّارات فتسوده برودة شديدة، ومتساقطاته قليلة تتركّز في الأشهر الثلاثة الأكثر دفئاً ونسبة الثلوج فيها مرتفعة.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15152, 2076, 2, 'الأطراف: ترفع التيّارات البحريّة الحارّة حرارتها فيبقى معدّلها السنوي فوق الصفر، وتتجاوز متساقطاتها ألف ملّيمتر موزّعة على مدار السنة، ونسبة الثلوج فيها أدنى. الداخل: بعيد عن هذه التيّارات فتسوده برودة شديدة، ومتساقطاته قليلة تتركّز في الأشهر الثلاثة الأكثر دفئاً ونسبة الثلوج فيها مرتفعة.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15153, 2077, 1, 'اتّجهت الرساميل إلى الاستثمار في مزارع المائيات بفعل الطلب المتزايد على ثمار البحر والأسماك، ونظراً لندرة بعض الأنواع وغلاء ثمنها، ولأنّ إنتاجيّتها مرتفعة وأرباحها كبيرة تفوق أرباح الصيد بخمسين مرّة.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15154, 2077, 2, 'اتّجهت الرساميل إلى الاستثمار في مزارع المائيات بفعل الطلب المتزايد على ثمار البحر والأسماك، ونظراً لندرة بعض الأنواع وغلاء ثمنها، ولأنّ إنتاجيّتها مرتفعة وأرباحها كبيرة تفوق أرباح الصيد بخمسين مرّة.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15155, 2078, 1, 'الأمن المائي هو ضمان استمرار تدفّق المياه، والحفاظ على نوعيتها، وإيجاد مصادر جديدة لتلبية الحاجات. من شروط استثمار المياه (شرطان من): إعادة استعمال المياه المعالَجة في الري، معالجة المياه الصناعية قبل التخلّص منها، تجميع مياه المجاري المدينية لإعادة استعمالها، مسح الخزانات الجوفية، تحسين قنوات المياه للحدّ من التبخّر والتسرّب، استعمال الأسمدة والمبيدات وفق الأصول.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15156, 2078, 2, 'الأمن المائي هو ضمان استمرار تدفّق المياه، والحفاظ على نوعيتها، وإيجاد مصادر جديدة لتلبية الحاجات. من شروط استثمار المياه (شرطان من): إعادة استعمال المياه المعالَجة في الري، معالجة المياه الصناعية قبل التخلّص منها، تجميع مياه المجاري المدينية لإعادة استعمالها، مسح الخزانات الجوفية، تحسين قنوات المياه للحدّ من التبخّر والتسرّب، استعمال الأسمدة والمبيدات وفق الأصول.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15157, 2079, 1, 'جذب الإقليم المعتدل الإنسان للسكن فيه، فحلّت زراعات الحبوب والأشجار المثمرة مكان المراعي في مساحات واسعة، وأدّى هذا التوسّع الحضاري إلى تهديد بعض الأنواع الحيوانيّة والنباتيّة بالاندثار.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15158, 2079, 2, 'جذب الإقليم المعتدل الإنسان للسكن فيه، فحلّت زراعات الحبوب والأشجار المثمرة مكان المراعي في مساحات واسعة، وأدّى هذا التوسّع الحضاري إلى تهديد بعض الأنواع الحيوانيّة والنباتيّة بالاندثار.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15159, 2080, 1, 'تراجعت لسببين تجاريّين: الأوّل أنّ كلفة استخراج الملح المنجميّ أقلّ، والثاني أنّ استعمال المساحات الشاطئيّة للسياحة يعطي أضعاف ما يعطيه استخراج الملح. والأثر تبدّل منظر الشاطئ، وتحوّل بعض الملّاحات إلى مجمّعات سياحيّة ومراكز للنشاطات الرياضيّة المائيّة.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15160, 2080, 2, 'تراجعت لسببين تجاريّين: الأوّل أنّ كلفة استخراج الملح المنجميّ أقلّ، والثاني أنّ استعمال المساحات الشاطئيّة للسياحة يعطي أضعاف ما يعطيه استخراج الملح. والأثر تبدّل منظر الشاطئ، وتحوّل بعض الملّاحات إلى مجمّعات سياحيّة ومراكز للنشاطات الرياضيّة المائيّة.', 1, '2026-09-30 22:10:51', '2026-09-30 22:10:51'),
(15161, 2081, 1, 'غلافات الأرض: القشرة الأرضية، والوشاح، والنواة. تختلف في تركيبها الكيميائي (أي في معادنها)، وفي خصائصها الفيزيائية (أي في الحرارة والكثافة)، ويفصل بين كلّ غلاف وآخر سطوح الانقطاع.', 1, '2026-09-30 22:10:52', '2026-09-30 22:10:52'),
(15162, 2081, 2, 'غلافات الأرض: القشرة الأرضية، والوشاح، والنواة. تختلف في تركيبها الكيميائي (أي في معادنها)، وفي خصائصها الفيزيائية (أي في الحرارة والكثافة)، ويفصل بين كلّ غلاف وآخر سطوح الانقطاع.', 1, '2026-09-30 22:10:52', '2026-09-30 22:10:52'),
(15163, 2082, 1, 'رأى فيغنر أنّ اليابس كان كتلة سيالية واحدة هي بانجيا يحيط بها غلاف مائي شاسع، ثمّ تمزّقت وزحفت أجزاؤها إلى مواقعها الحالية، واستند إلى تشابه السواحل وإمكانية تداخلها، لكنّه لم يفسّر ذلك علمياً. أمّا نظرية تكتونية الصفائح فحدّدت المحرّك، وهو تيارات الحمل الباطنية الحارّة القادمة من النواة عبر الوشاح، التي تلتفّ أفقياً فتزحزح الصفائح وفق حركتي التباعد والتقارب.', 1, '2026-09-30 22:10:52', '2026-09-30 22:10:52'),
(15164, 2082, 2, 'رأى فيغنر أنّ اليابس كان كتلة سيالية واحدة هي بانجيا يحيط بها غلاف مائي شاسع، ثمّ تمزّقت وزحفت أجزاؤها إلى مواقعها الحالية، واستند إلى تشابه السواحل وإمكانية تداخلها، لكنّه لم يفسّر ذلك علمياً. أمّا نظرية تكتونية الصفائح فحدّدت المحرّك، وهو تيارات الحمل الباطنية الحارّة القادمة من النواة عبر الوشاح، التي تلتفّ أفقياً فتزحزح الصفائح وفق حركتي التباعد والتقارب.', 1, '2026-09-30 22:10:52', '2026-09-30 22:10:52'),
(15165, 2083, 1, 'كانت شبه الجزيرة العربية ملتصقة بأفريقيا. صعدت تيارات الحمل إلى أعلى الوشاح فرفعت القشرة فأخذت الطبقات السطحية شكلاً مقبّباً، ثمّ التفّت التيارات أفقياً دافعة الصفيحتين العربية والأفريقية في اتّجاهين متعاكسين، فتكسّر التقبّب وانهار مكوّناً أخدوداً عميقاً نسبياً اندفعت فيه مياه المحيط الهندي، فتشكّل البحر الأحمر ضيّقاً في بادئ الأمر (حركة تباعد).', 1, '2026-09-30 22:10:52', '2026-09-30 22:10:52'),
(15166, 2083, 2, 'كانت شبه الجزيرة العربية ملتصقة بأفريقيا. صعدت تيارات الحمل إلى أعلى الوشاح فرفعت القشرة فأخذت الطبقات السطحية شكلاً مقبّباً، ثمّ التفّت التيارات أفقياً دافعة الصفيحتين العربية والأفريقية في اتّجاهين متعاكسين، فتكسّر التقبّب وانهار مكوّناً أخدوداً عميقاً نسبياً اندفعت فيه مياه المحيط الهندي، فتشكّل البحر الأحمر ضيّقاً في بادئ الأمر (حركة تباعد).', 1, '2026-09-30 22:10:52', '2026-09-30 22:10:52'),
(15167, 2084, 1, 'جمعت تيّارات الحمل الباطنية الحارّة كتل الماغما الحارّة واللزجة في القسم الأعلى من الوشاح، فازداد ضغطها على القشرة الأرضية. وتنتشر نقاط ضعف جيولوجية عند خطوط التباعد أو عند خطوط التقارب والالتحام بين الصفائح، تتيح للحمم الملتهبة أن تخترق القشرة، فتحدث ظاهرة البركان.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15168, 2084, 2, 'جمعت تيّارات الحمل الباطنية الحارّة كتل الماغما الحارّة واللزجة في القسم الأعلى من الوشاح، فازداد ضغطها على القشرة الأرضية. وتنتشر نقاط ضعف جيولوجية عند خطوط التباعد أو عند خطوط التقارب والالتحام بين الصفائح، تتيح للحمم الملتهبة أن تخترق القشرة، فتحدث ظاهرة البركان.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15169, 2085, 1, 'ثلاث من: تغني سطح الأرض بالمعادن مثل الحديد والنحاس والكبريت؛ توفّر موادّ للبناء والعمران مثل البازلت؛ تفتّت الصخور البركانية يُنشئ تربة شديدة الخصوبة تجذب الزراعة؛ الينابيع والفوّارات الحارّة تصلح للسياحة والعلاج الصحّي؛ يُستفاد من طاقة الأرض الحرارية في توليد الكهرباء والتدفئة.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15170, 2086, 1, 'تتّسع الشقوق ويسهل تكسّر الصخر وتفتّته. والسبب أنّ المياه تتجمّد عندما تنخفض الحرارة إلى ما دون الصفر، فيزداد حجمها وتضغط على السطوح الملامسة لها، فيضعف تماسك الصخر.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15171, 2087, 1, 'تفتّت الصخور النارية في بعض المناخات يكوّن تربة شديدة الخصوبة بسبب تعدّد عناصرها المعدنية، وهي مصدر مهمّ للحجارة الصلبة المستعملة في البناء ورصف الطرقات، ومنها البازلت.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15172, 2085, 2, 'ثلاث من: تغني سطح الأرض بالمعادن مثل الحديد والنحاس والكبريت؛ توفّر موادّ للبناء والعمران مثل البازلت؛ تفتّت الصخور البركانية يُنشئ تربة شديدة الخصوبة تجذب الزراعة؛ الينابيع والفوّارات الحارّة تصلح للسياحة والعلاج الصحّي؛ يُستفاد من طاقة الأرض الحرارية في توليد الكهرباء والتدفئة.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15173, 2086, 2, 'تتّسع الشقوق ويسهل تكسّر الصخر وتفتّته. والسبب أنّ المياه تتجمّد عندما تنخفض الحرارة إلى ما دون الصفر، فيزداد حجمها وتضغط على السطوح الملامسة لها، فيضعف تماسك الصخر.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15174, 2087, 2, 'تفتّت الصخور النارية في بعض المناخات يكوّن تربة شديدة الخصوبة بسبب تعدّد عناصرها المعدنية، وهي مصدر مهمّ للحجارة الصلبة المستعملة في البناء ورصف الطرقات، ومنها البازلت.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15175, 2088, 1, 'ثلاثة من: تشييد أبنية مرنة تتجنّب الانهيار السريع؛ إقامة مراصد حديثة تسجّل الزلازل والاهتزازات الخفيفة التي تسبق تحرّك البركان؛ قياس حرارة فوّهات البراكين بشكل دوري؛ استخدام الطيران لتحويل مجاري اللافا بعيداً عن التجمّعات السكانية؛ دراسات لإقامة سدود تحوّل اللافا نحو مناطق خالية؛ رصد البراكين الناشطة بالأقمار الصناعية.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15176, 2088, 2, 'ثلاثة من: تشييد أبنية مرنة تتجنّب الانهيار السريع؛ إقامة مراصد حديثة تسجّل الزلازل والاهتزازات الخفيفة التي تسبق تحرّك البركان؛ قياس حرارة فوّهات البراكين بشكل دوري؛ استخدام الطيران لتحويل مجاري اللافا بعيداً عن التجمّعات السكانية؛ دراسات لإقامة سدود تحوّل اللافا نحو مناطق خالية؛ رصد البراكين الناشطة بالأقمار الصناعية.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15177, 2089, 1, 'تتكوّن بفعل التجوية التفاضليّة: تنشط التجوية الميكانيكيّة في الطبقات الليّنة من الصخر فتتفتّت بسرعة وتسقط أجزاؤها أرضاً، بينما تقاوم الطبقات الصلبة وتبقى في أعلى الصخر، فيتّخذ الصخر شكل نبات الفطر.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15178, 2089, 2, 'تتكوّن بفعل التجوية التفاضليّة: تنشط التجوية الميكانيكيّة في الطبقات الليّنة من الصخر فتتفتّت بسرعة وتسقط أجزاؤها أرضاً، بينما تقاوم الطبقات الصلبة وتبقى في أعلى الصخر، فيتّخذ الصخر شكل نبات الفطر.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15179, 2090, 1, 'الدفائن: تحتوي الصخور الرسوبية دفائن عضوية عديدة، أمّا المتحوّلة فتخلو منها. المسامية: كلا النوعين مسامي لكنّ السبب مختلف؛ فالرسوبية مسامية فتتكوّن فيها خزّانات مياه جوفية عند ظهور طبقة عازلة، والمتحوّلة مسامية بسبب فراغات خروج الغازات. مثالان من: النيس، الشيست، الأردواز، الرخام.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15180, 2090, 2, 'الدفائن: تحتوي الصخور الرسوبية دفائن عضوية عديدة، أمّا المتحوّلة فتخلو منها. المسامية: كلا النوعين مسامي لكنّ السبب مختلف؛ فالرسوبية مسامية فتتكوّن فيها خزّانات مياه جوفية عند ظهور طبقة عازلة، والمتحوّلة مسامية بسبب فراغات خروج الغازات. مثالان من: النيس، الشيست، الأردواز، الرخام.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15181, 2091, 1, 'تُعدّ خطراً لأنّ كتلاً من الحافات الصخريّة تسقط، فتهدّد المناطق السكنيّة وخطوط المواصلات. ومن فوائد التشجير والمدرّجات: الاحتفاظ بالمفتّتات الناعمة التي تكوّن التربة فيقوم استغلال زراعي مثمر، وتثبيت الصخور ومنع انهيارها بإعادة الغطاء النباتي.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15182, 2091, 2, 'تُعدّ خطراً لأنّ كتلاً من الحافات الصخريّة تسقط، فتهدّد المناطق السكنيّة وخطوط المواصلات. ومن فوائد التشجير والمدرّجات: الاحتفاظ بالمفتّتات الناعمة التي تكوّن التربة فيقوم استغلال زراعي مثمر، وتثبيت الصخور ومنع انهيارها بإعادة الغطاء النباتي.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15183, 2092, 1, 'الصخور في حركة مستمرّة وتتحوّل من نوع إلى آخر بفعل عوامل أبرزها الضغط والحرارة: تصعد الماغما من طبقة الوشاح فتتكوّن صخور نارية؛ وتحرّك تيارات الحمل الباطنية الصفائح أفقياً فتتصادم فيتحوّل الصخر بحرارة موقعه الجديد وضغطه؛ وتُدفن طبقات في العمق فتنصهر؛ وتتراكم نواتج تعرية الصخور القديمة طبقات ثمّ ترتفع سلاسل جبلية. هذه الحلقة المستمرّة هي الدورة الصخرية.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15184, 2092, 2, 'الصخور في حركة مستمرّة وتتحوّل من نوع إلى آخر بفعل عوامل أبرزها الضغط والحرارة: تصعد الماغما من طبقة الوشاح فتتكوّن صخور نارية؛ وتحرّك تيارات الحمل الباطنية الصفائح أفقياً فتتصادم فيتحوّل الصخر بحرارة موقعه الجديد وضغطه؛ وتُدفن طبقات في العمق فتنصهر؛ وتتراكم نواتج تعرية الصخور القديمة طبقات ثمّ ترتفع سلاسل جبلية. هذه الحلقة المستمرّة هي الدورة الصخرية.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15185, 2093, 1, 'تتسرّب من السقف مياه مشبعة بالجير الذائب، فتفقد جزءاً كبيراً من غاز ثاني أوكسيد الكربون، فتتبقّى كربونات الجير على هيئة بلّورات تتزايد حجماً بالتدريج، فيتكوّن عمود رفيع من الأعلى نحو الأسفل هو النوازل. وحين تسقط القطرات فوق أرضيّة الكهف تتجمّع كربونات الكالسيوم على شكل أعمدة صاعدة هي الصواعد.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15186, 2093, 2, 'تتسرّب من السقف مياه مشبعة بالجير الذائب، فتفقد جزءاً كبيراً من غاز ثاني أوكسيد الكربون، فتتبقّى كربونات الجير على هيئة بلّورات تتزايد حجماً بالتدريج، فيتكوّن عمود رفيع من الأعلى نحو الأسفل هو النوازل. وحين تسقط القطرات فوق أرضيّة الكهف تتجمّع كربونات الكالسيوم على شكل أعمدة صاعدة هي الصواعد.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15187, 2094, 1, 'يسرّع الإنسان التجوية حين يشقّ الطرق فوق المنحدرات الجبليّة فيكشف الصخور أمام التجوية الميكانيكيّة والكيميائيّة، وحين يزيل الغطاء النباتي في أثناء التوسّع العمراني فتقع انهيارات وانزلاقات. ويحدّ من أخطارها بإعادة التشجير وبإقامة جدران دعم تخفّف تساقط الصخور.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15188, 2094, 2, 'يسرّع الإنسان التجوية حين يشقّ الطرق فوق المنحدرات الجبليّة فيكشف الصخور أمام التجوية الميكانيكيّة والكيميائيّة، وحين يزيل الغطاء النباتي في أثناء التوسّع العمراني فتقع انهيارات وانزلاقات. ويحدّ من أخطارها بإعادة التشجير وبإقامة جدران دعم تخفّف تساقط الصخور.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15189, 2095, 1, 'لأنّ الصخر الجيري يتّصف بمساميّته واتّساع الفراغات بين حبيباته، والمياه المشبعة بثاني أوكسيد الكربون تذيب الجير، والرطوبة تُنشط التجوية الكيميائيّة. من الأشكال السطحيّة: الشخروب أو الجورة أو الدارة، ومن الأشكال الجوفيّة: الكهوف أو الصواعد أو النوازل.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15190, 2095, 2, 'لأنّ الصخر الجيري يتّصف بمساميّته واتّساع الفراغات بين حبيباته، والمياه المشبعة بثاني أوكسيد الكربون تذيب الجير، والرطوبة تُنشط التجوية الكيميائيّة. من الأشكال السطحيّة: الشخروب أو الجورة أو الدارة، ومن الأشكال الجوفيّة: الكهوف أو الصواعد أو النوازل.', 1, '2026-09-30 22:10:53', '2026-09-30 22:10:53'),
(15191, 2096, 1, 'الحتّ البحريّ عملية تغيير دائم في أشكال الشاطئ تقوم بها الأمواج بشكل أساسيّ. عملياته ثلاث: الهدم والنقل والترسيب. ينتج عن الهدم الجروف والكهوف والأقواس والمسلّات، وينتج عن الترسيب الشواطئ الرملية والحصوية.', 1, '2026-09-30 22:10:54', '2026-09-30 22:10:54'),
(15192, 2096, 2, 'الحتّ البحريّ عملية تغيير دائم في أشكال الشاطئ تقوم بها الأمواج بشكل أساسيّ. عملياته ثلاث: الهدم والنقل والترسيب. ينتج عن الهدم الجروف والكهوف والأقواس والمسلّات، وينتج عن الترسيب الشواطئ الرملية والحصوية.', 1, '2026-09-30 22:10:54', '2026-09-30 22:10:54'),
(15193, 2097, 1, 'تمرّ التربة بعمليات متتابعة: تسرّب المياه إلى داخلها فتتحلّل المواد المعدنية كيميائياً، وتحلّل البقايا النباتية وتداخلها مع التربة تدريجياً، ومؤازرة الكائنات المجهرية كالبكتيريا والطفيليات ومعها الديدان والنمل. فيتفتّت الصخر الأمّ، وتظهر التشكيلات النباتية الأولى، ثمّ يبرز أفق غنيّ بالدبال، حتّى تصبح التربة شبه مكتملة.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15194, 2097, 2, 'تمرّ التربة بعمليات متتابعة: تسرّب المياه إلى داخلها فتتحلّل المواد المعدنية كيميائياً، وتحلّل البقايا النباتية وتداخلها مع التربة تدريجياً، ومؤازرة الكائنات المجهرية كالبكتيريا والطفيليات ومعها الديدان والنمل. فيتفتّت الصخر الأمّ، وتظهر التشكيلات النباتية الأولى، ثمّ يبرز أفق غنيّ بالدبال، حتّى تصبح التربة شبه مكتملة.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15195, 2098, 1, 'تكتشف الأمواج مناطق الضعف الجيولوجيّ، أي تعاقب طبقات صلبة مع أخرى ليّنة، فتُحدث حركتها المستمرّة فجوات جانبية تتّسع مع الزمن فتكوّن كهوفاً بحرية. وحين تلتحم فجوتان متجاورتان باتجاهين متضادّين يتكوّن القوس، ثمّ يؤدّي الاستنزاف المتواصل للطبقات الليّنة إلى اختلال سقف القوس وانهياره، فتُعزل أعمدة صخرية هي المسلّات. فالطبقات الليّنة هي نقطة الضعف في كلّ مرحلة.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15196, 2098, 2, 'تكتشف الأمواج مناطق الضعف الجيولوجيّ، أي تعاقب طبقات صلبة مع أخرى ليّنة، فتُحدث حركتها المستمرّة فجوات جانبية تتّسع مع الزمن فتكوّن كهوفاً بحرية. وحين تلتحم فجوتان متجاورتان باتجاهين متضادّين يتكوّن القوس، ثمّ يؤدّي الاستنزاف المتواصل للطبقات الليّنة إلى اختلال سقف القوس وانهياره، فتُعزل أعمدة صخرية هي المسلّات. فالطبقات الليّنة هي نقطة الضعف في كلّ مرحلة.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15197, 2099, 1, 'في المجرى الأوسط تعتدل سرعة المياه وانحدارها وتنساب بانتظام، فيصلح لمشاريع توفّر كمّيّات ضخمة من المياه، كمشروع الليطاني ومشروع الفرات. أمّا في المجرى الأعلى فالانحدار شديد والصخور غير متجانسة، فتبرز المساقط المائيّة التي تحول دون الملاحة النهريّة.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15198, 2099, 2, 'في المجرى الأوسط تعتدل سرعة المياه وانحدارها وتنساب بانتظام، فيصلح لمشاريع توفّر كمّيّات ضخمة من المياه، كمشروع الليطاني ومشروع الفرات. أمّا في المجرى الأعلى فالانحدار شديد والصخور غير متجانسة، فتبرز المساقط المائيّة التي تحول دون الملاحة النهريّة.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15199, 2100, 1, 'الشاطئ الصخريّ ذو الجروف نتاج الهدم، لأنّ الأشكال الصخرية التي نحتتها الأمواج هي نتاج الهدم. والشاطئ الرمليّ نتاج الترسيب، لأنّ تراكم الرمل والحصى هو نتاج الترسيب.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15200, 2100, 2, 'الشاطئ الصخريّ ذو الجروف نتاج الهدم، لأنّ الأشكال الصخرية التي نحتتها الأمواج هي نتاج الهدم. والشاطئ الرمليّ نتاج الترسيب، لأنّ تراكم الرمل والحصى هو نتاج الترسيب.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15201, 2101, 1, 'تظهر منعطفات متتالية في السهل الفيضيّ في المجرى الأدنى، ثمّ تتعرّض لتغيّرات مناخيّة أو جيولوجيّة تعيد نشاط الحتّ الرأسيّ، فتتعمّق وتصبح جوانبها شديدة الانحدار كالحيطان العالية.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15202, 2101, 2, 'تظهر منعطفات متتالية في السهل الفيضيّ في المجرى الأدنى، ثمّ تتعرّض لتغيّرات مناخيّة أو جيولوجيّة تعيد نشاط الحتّ الرأسيّ، فتتعمّق وتصبح جوانبها شديدة الانحدار كالحيطان العالية.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15203, 2102, 1, 'التشرنوزيوم غنية بالمواد العضوية والمعادن والجير، لذلك هي خصبة جدّاً. أمّا اللاتريت فتتعرّض دائماً للغسل بفعل غزارة الأمطار، فتقلّ خصوبتها.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15204, 2102, 2, 'التشرنوزيوم غنية بالمواد العضوية والمعادن والجير، لذلك هي خصبة جدّاً. أمّا اللاتريت فتتعرّض دائماً للغسل بفعل غزارة الأمطار، فتقلّ خصوبتها.', 1, '2026-09-30 22:10:55', '2026-09-30 22:10:55'),
(15205, 2103, 1, 'من الحلول: اتّباع الدورات الزراعية، واستخدام الأسمدة، والجمع بين تربية الماشية والزراعة في آن واحد (يكفي حلّان). والهدف تحقيق زراعة مستدامة تجدّد نفسها بنفسها.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15206, 2103, 2, 'من الحلول: اتّباع الدورات الزراعية، واستخدام الأسمدة، والجمع بين تربية الماشية والزراعة في آن واحد (يكفي حلّان). والهدف تحقيق زراعة مستدامة تجدّد نفسها بنفسها.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15207, 2104, 1, 'لأنّ صبيب النهر يتغيّر وفق نظام الأمطار السائد على الحوض، وحوض النيل ينتشر في الإقليم الاستوائيّ والمداريّ والصحراويّ والمتوسّطيّ، فتتعدّد المناخات ويتعقّد نظام صبيبه.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15208, 2104, 2, 'لأنّ صبيب النهر يتغيّر وفق نظام الأمطار السائد على الحوض، وحوض النيل ينتشر في الإقليم الاستوائيّ والمداريّ والصحراويّ والمتوسّطيّ، فتتعدّد المناخات ويتعقّد نظام صبيبه.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15209, 2105, 1, 'تتكوّن الموائد الصخرية في هضيبات صغيرة المساحة، تتآكل صخورها اللينة السفلى بفعل الرياح وتصمد الصخور الصلبة العليا، وهذا هو الحتّ التفاضليّ. الحمادة ناتجة عن الحتّ لأنّ الرياح تزيل الطبقة السطحية اللينة، وتربة اللويس ناتجة عن الإرساب حين تنخفض سرعة الرياح فترسب الحبيبات الدقيقة.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15210, 2105, 2, 'تتكوّن الموائد الصخرية في هضيبات صغيرة المساحة، تتآكل صخورها اللينة السفلى بفعل الرياح وتصمد الصخور الصلبة العليا، وهذا هو الحتّ التفاضليّ. الحمادة ناتجة عن الحتّ لأنّ الرياح تزيل الطبقة السطحية اللينة، وتربة اللويس ناتجة عن الإرساب حين تنخفض سرعة الرياح فترسب الحبيبات الدقيقة.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15211, 2106, 1, 'تثبيت الكثبان المتحرّكة بغرس أشجار النخيل ونباتات مختلفة تعمل على تماسك أجزاء الكثيب. ومصدّات الرياح، وهي صفوف من الأشجار تغرس متعامدة مع اتّجاه الرياح السائدة، فتحدّ من سرعة الرياح وتعطّل دورها التخريبيّ وتحمي المزروعات من زحف الرمال.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15212, 2106, 2, 'تثبيت الكثبان المتحرّكة بغرس أشجار النخيل ونباتات مختلفة تعمل على تماسك أجزاء الكثيب. ومصدّات الرياح، وهي صفوف من الأشجار تغرس متعامدة مع اتّجاه الرياح السائدة، فتحدّ من سرعة الرياح وتعطّل دورها التخريبيّ وتحمي المزروعات من زحف الرمال.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15213, 2107, 1, 'الركامات الجليدية تراكمات هائلة من الفتات الصخريّ والرمال يدفعها الجليد أمامه، وبعد توقّفها تشكّل حاجزاً أمامياً تتجمّع وراءه المياه في بحيرات طولية الامتداد.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15214, 2107, 2, 'الركامات الجليدية تراكمات هائلة من الفتات الصخريّ والرمال يدفعها الجليد أمامه، وبعد توقّفها تشكّل حاجزاً أمامياً تتجمّع وراءه المياه في بحيرات طولية الامتداد.', 1, '2026-09-30 22:10:57', '2026-09-30 22:10:57'),
(15215, 2108, 1, 'من التدابير: 1) الضغط على المتصرّف المسيحي أوهانس باشا وإجباره على الاستقالة وتعيين متصرّف عثماني مسلم هو علي منيف بك دون العودة إلى الدول الضامنة. 2) حلّ مجلس إدارة المتصرفية ونفي رئيسه حبيب باشا السعد إلى الأناضول وتعيين مجلس جديد وموظفين أتراك ينفّذون أوامره. 3) إلغاء الامتيازات الأجنبية ومصادرة ممتلكات فرنسا وإنكلترا وروسيا وإيطاليا. (ويُقبل أيضاً: الضغط على البطريرك الياس الحويك حتى طلب الفرمان سنة 1915، والتنكيل السياسي). وقد نقضت هذه التدابير بروتوكول 1861 لأنّها نقلت القرار من مؤسسات المتصرفية إلى سلطة جمال باشا وحده.', 1, '2026-09-30 22:11:00', '2026-09-30 22:11:00'),
(15216, 2108, 2, 'من التدابير: 1) الضغط على المتصرّف المسيحي أوهانس باشا وإجباره على الاستقالة وتعيين متصرّف عثماني مسلم هو علي منيف بك دون العودة إلى الدول الضامنة. 2) حلّ مجلس إدارة المتصرفية ونفي رئيسه حبيب باشا السعد إلى الأناضول وتعيين مجلس جديد وموظفين أتراك ينفّذون أوامره. 3) إلغاء الامتيازات الأجنبية ومصادرة ممتلكات فرنسا وإنكلترا وروسيا وإيطاليا. (ويُقبل أيضاً: الضغط على البطريرك الياس الحويك حتى طلب الفرمان سنة 1915، والتنكيل السياسي). وقد نقضت هذه التدابير بروتوكول 1861 لأنّها نقلت القرار من مؤسسات المتصرفية إلى سلطة جمال باشا وحده.', 1, '2026-09-30 22:11:00', '2026-09-30 22:11:00'),
(15217, 2109, 1, 'من ردّات الفعل: الانضمام إلى الجمعيات والأحزاب السياسية السرية والعلنية في مصر والحجاز من أجل استقلال بلدهم؛ الفرار من الخدمة العسكرية العثمانية؛ تشكيل لجان لاستقبال المتطوعين في مصر وبلاد الاغتراب للحرب ضدّ العثمانيين؛ المشاركة في الثورة العربية الكبرى (حزيران 1916) في الحجاز تحت لواء الأمير فيصل. الربط: الفرار من الخدمة العسكرية ردّ على التجنيد الإجباري، أو العمل السياسي في الخارج ردّ على إغلاق الداخل بالأحكام العرفية والديوان العرفي.', 1, '2026-09-30 22:11:00', '2026-09-30 22:11:00'),
(15218, 2109, 2, 'من ردّات الفعل: الانضمام إلى الجمعيات والأحزاب السياسية السرية والعلنية في مصر والحجاز من أجل استقلال بلدهم؛ الفرار من الخدمة العسكرية العثمانية؛ تشكيل لجان لاستقبال المتطوعين في مصر وبلاد الاغتراب للحرب ضدّ العثمانيين؛ المشاركة في الثورة العربية الكبرى (حزيران 1916) في الحجاز تحت لواء الأمير فيصل. الربط: الفرار من الخدمة العسكرية ردّ على التجنيد الإجباري، أو العمل السياسي في الخارج ردّ على إغلاق الداخل بالأحكام العرفية والديوان العرفي.', 1, '2026-09-30 22:11:00', '2026-09-30 22:11:00'),
(15219, 2110, 1, 'أربعة ممّا يأتي: 1) السياسة الظالمة التي اتّبعها الإنكليز: فرض أعمال السخرة، والضرائب الباهظة، ومحاولة تهنيد العراق. 2) إثارة النعرات الطائفية وبثّ روح التفرقة العنصرية بين العراقيين. 3) رفض العراقيين الاحتلال البريطاني لبلادهم ورغبتهم في الاستقلال. 4) ارتفاع أسعار المواد الغذائية والحبوب وزيادة التضخّم النقدي. 5) تأثّر العراقيين بالثورة البلشفية في روسيا والثورة المصرية ضدّ الإنكليز. 6) نقمة العراقيين على الإنكليز بسبب تخلّيهم عن الأمير فيصل في سورية، ما أدّى إلى هزيمته في معركة ميسلون أمام فرنسا.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15220, 2111, 1, '1) تنظيم الإعاشة. 2) تنظيم مصلحة الصحة لمعالجة الأمراض. 3) إيواء الأيتام والمشرّدين واللاجئين الأرمن. 4) فتح المدارس. وتمّ التوصّل إلى النتائج المرجوّة فتحسّن الوضع.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15221, 2111, 2, '1) تنظيم الإعاشة. 2) تنظيم مصلحة الصحة لمعالجة الأمراض. 3) إيواء الأيتام والمشرّدين واللاجئين الأرمن. 4) فتح المدارس. وتمّ التوصّل إلى النتائج المرجوّة فتحسّن الوضع.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15222, 2110, 2, 'أربعة ممّا يأتي: 1) السياسة الظالمة التي اتّبعها الإنكليز: فرض أعمال السخرة، والضرائب الباهظة، ومحاولة تهنيد العراق. 2) إثارة النعرات الطائفية وبثّ روح التفرقة العنصرية بين العراقيين. 3) رفض العراقيين الاحتلال البريطاني لبلادهم ورغبتهم في الاستقلال. 4) ارتفاع أسعار المواد الغذائية والحبوب وزيادة التضخّم النقدي. 5) تأثّر العراقيين بالثورة البلشفية في روسيا والثورة المصرية ضدّ الإنكليز. 6) نقمة العراقيين على الإنكليز بسبب تخلّيهم عن الأمير فيصل في سورية، ما أدّى إلى هزيمته في معركة ميسلون أمام فرنسا.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15223, 2112, 1, 'فرض الأتراك حصاراً برياً فمنعوا إدخال الحبوب إلى الجبل، وفرضوا أعمال السخرة، ومنعوا الناس من الوصول إلى البحر لصيد الأسماك أو لأخذ الملح، وصادروا الأطباء لمداواة الجيش، وقطعوا الغابات للتدفئة ولبناء سكة الحديد. ومع الحصار البحري الذي فرضه الحلفاء صار الجبل محاصراً من الجهتين. من النتائج (اثنتان): المجاعة؛ الأمراض والأوبئة والوفيات؛ الهجرة من لبنان وإليه؛ توقّف المدارس.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15224, 2112, 2, 'فرض الأتراك حصاراً برياً فمنعوا إدخال الحبوب إلى الجبل، وفرضوا أعمال السخرة، ومنعوا الناس من الوصول إلى البحر لصيد الأسماك أو لأخذ الملح، وصادروا الأطباء لمداواة الجيش، وقطعوا الغابات للتدفئة ولبناء سكة الحديد. ومع الحصار البحري الذي فرضه الحلفاء صار الجبل محاصراً من الجهتين. من النتائج (اثنتان): المجاعة؛ الأمراض والأوبئة والوفيات؛ الهجرة من لبنان وإليه؛ توقّف المدارس.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15225, 2113, 1, 'أهالي الجبل (معظمهم من المسيحيين): طالبوا بالاستقلال التام وتوسيع الحدود وإعادة المناطق المسلوخة إلى لبنان وقبول المساعدة الفرنسية، وعبّروا عن موقفهم بقرارات مجلس الإدارة وبالوفود الثلاثة إلى مؤتمر الصلح. أهل الولاية (معظمهم من المسلمين): قالوا بالاستقلال الذاتي مع الارتباط بالحكم الفيصلي في دمشق، وكلّفوا الأمير فيصل التعبير عن رأيهم في مؤتمر الصلح. فالخلاف كان على طبيعة الاستقلال وعلى مرجعية البلاد.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15226, 2113, 2, 'أهالي الجبل (معظمهم من المسيحيين): طالبوا بالاستقلال التام وتوسيع الحدود وإعادة المناطق المسلوخة إلى لبنان وقبول المساعدة الفرنسية، وعبّروا عن موقفهم بقرارات مجلس الإدارة وبالوفود الثلاثة إلى مؤتمر الصلح. أهل الولاية (معظمهم من المسلمين): قالوا بالاستقلال الذاتي مع الارتباط بالحكم الفيصلي في دمشق، وكلّفوا الأمير فيصل التعبير عن رأيهم في مؤتمر الصلح. فالخلاف كان على طبيعة الاستقلال وعلى مرجعية البلاد.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15227, 2114, 1, 'الأسباب غير المباشرة هي أسباب متراكمة مهّدت للانفجار، مثل السياسة الظالمة بالسخرة والضرائب ومحاولة التهنيد (أو الغلاء والتضخّم، أو التأثّر بثورتي روسيا ومصر). أمّا السبب المباشر فهو الشرارة التي فجّرت الثورة، وهو إقدام الإنكليز على اعتقال أحد شيوخ العشائر في الرميثة، فهاجم رجاله الحكومة وأطلقوا سراحه بالقوّة. فالشرارة وحدها لا تكفي من دون تراكم سابق.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15228, 2114, 2, 'الأسباب غير المباشرة هي أسباب متراكمة مهّدت للانفجار، مثل السياسة الظالمة بالسخرة والضرائب ومحاولة التهنيد (أو الغلاء والتضخّم، أو التأثّر بثورتي روسيا ومصر). أمّا السبب المباشر فهو الشرارة التي فجّرت الثورة، وهو إقدام الإنكليز على اعتقال أحد شيوخ العشائر في الرميثة، فهاجم رجاله الحكومة وأطلقوا سراحه بالقوّة. فالشرارة وحدها لا تكفي من دون تراكم سابق.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15229, 2115, 1, 'الظروف (ثلاثة منها): إقرار مبدأ الانتداب؛ تزايد القلق عند اللبنانيين على مصير بلادهم تجاه نوايا الحلفاء؛ خوف اللبنانيين من تقرير لجنة كينغ كراين؛ غموض الموقف الدولي؛ عدم تحقيق الوفد الأول نتائج ملموسة. المطالب (ثلاثة منها): الاستقلال التام؛ استعادة لبنان حدوده الطبيعية والتاريخية؛ معاقبة المسؤولين عن جرائم الحرب والتعويض على اللبنانيين؛ قبول مساعدة فرنسا شرط عدم المسّ بالسيادة؛ رعاية فرنسا لهذه المطالب مع تقبّل انتدابها.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15230, 2115, 2, 'الظروف (ثلاثة منها): إقرار مبدأ الانتداب؛ تزايد القلق عند اللبنانيين على مصير بلادهم تجاه نوايا الحلفاء؛ خوف اللبنانيين من تقرير لجنة كينغ كراين؛ غموض الموقف الدولي؛ عدم تحقيق الوفد الأول نتائج ملموسة. المطالب (ثلاثة منها): الاستقلال التام؛ استعادة لبنان حدوده الطبيعية والتاريخية؛ معاقبة المسؤولين عن جرائم الحرب والتعويض على اللبنانيين؛ قبول مساعدة فرنسا شرط عدم المسّ بالسيادة؛ رعاية فرنسا لهذه المطالب مع تقبّل انتدابها.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15231, 2116, 1, 'السببان: مطالبة العراقيين بالاستقلال وتحديد العلاقة مع بريطانيا؛ رغبة بريطانيا في الحفاظ على مصالحها في العراق من خلال توقيع معاهدات. بندان يُظهران النفوذ البريطاني (اثنان ممّا يأتي): احتفاظ بريطانيا بقاعدتين عسكريتين جويتين في العراق؛ إعطاء السفير البريطاني الأفضلية على سائر السفراء؛ التشاور بين الدولتين في السياسة الخارجية؛ تقديم بريطانيا جميع التسهيلات العسكرية عند نشوب الحرب.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15232, 2116, 2, 'السببان: مطالبة العراقيين بالاستقلال وتحديد العلاقة مع بريطانيا؛ رغبة بريطانيا في الحفاظ على مصالحها في العراق من خلال توقيع معاهدات. بندان يُظهران النفوذ البريطاني (اثنان ممّا يأتي): احتفاظ بريطانيا بقاعدتين عسكريتين جويتين في العراق؛ إعطاء السفير البريطاني الأفضلية على سائر السفراء؛ التشاور بين الدولتين في السياسة الخارجية؛ تقديم بريطانيا جميع التسهيلات العسكرية عند نشوب الحرب.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15233, 2117, 1, '1) مطالبة اللبنانيين بالاستقلال وتوسيع مساحة لبنان عبر إعادة ما سُلخ منه أيام المتصرفية، من خلال الوفود اللبنانية إلى مؤتمر الصلح في باريس. 2) فرض الانتداب الفرنسي على لبنان وسوريا وتعيين الجنرال غورو مفوضاً سامياً عليهما وإطلاق فرنسا يده لتنفيذ سياستها. 3) إنهاء غورو الحكم الفيصلي في سوريا بعد معركة ميسلون (تموز 1920) وتقسيمها إلى أربع دويلات ورغبته في إقامة دولة لبنان الكبير. 4) تعهّد فرنسا بإعلان دولة لبنان الكبير من خلال رسالة كليمنصو إلى البطريرك الياس الحويك الذي ترأّس الوفد.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15234, 2117, 2, '1) مطالبة اللبنانيين بالاستقلال وتوسيع مساحة لبنان عبر إعادة ما سُلخ منه أيام المتصرفية، من خلال الوفود اللبنانية إلى مؤتمر الصلح في باريس. 2) فرض الانتداب الفرنسي على لبنان وسوريا وتعيين الجنرال غورو مفوضاً سامياً عليهما وإطلاق فرنسا يده لتنفيذ سياستها. 3) إنهاء غورو الحكم الفيصلي في سوريا بعد معركة ميسلون (تموز 1920) وتقسيمها إلى أربع دويلات ورغبته في إقامة دولة لبنان الكبير. 4) تعهّد فرنسا بإعلان دولة لبنان الكبير من خلال رسالة كليمنصو إلى البطريرك الياس الحويك الذي ترأّس الوفد.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15235, 2118, 1, 'السياسية (ثلاثة ممّا يأتي): الخضوع للانتداب الفرنسي المباشر يحكمه عسكريون فرنسيون؛ انتقال العاصمة من بعبدا إلى بيروت؛ اعتماد العلم الفرنسي الذي تتوسّطه أرزة خضراء؛ اللغتان الرسميتان العربية والفرنسية؛ رقابة اسمية لعصبة الأمم. البشري: ازداد عدد السكّان من نحو 414 ألف نسمة إلى نحو 628 ألف نسمة، وتحوّل التوازن من مسيحي درزي إلى توازن بين المسلمين والمسيحيين.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15236, 2118, 2, 'السياسية (ثلاثة ممّا يأتي): الخضوع للانتداب الفرنسي المباشر يحكمه عسكريون فرنسيون؛ انتقال العاصمة من بعبدا إلى بيروت؛ اعتماد العلم الفرنسي الذي تتوسّطه أرزة خضراء؛ اللغتان الرسميتان العربية والفرنسية؛ رقابة اسمية لعصبة الأمم. البشري: ازداد عدد السكّان من نحو 414 ألف نسمة إلى نحو 628 ألف نسمة، وتحوّل التوازن من مسيحي درزي إلى توازن بين المسلمين والمسيحيين.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15237, 2119, 1, 'المفوّض السامي فرنسي الجنسية، مركزه بيروت، ممثّل فرنسا في لبنان وسوريا والقائد الأعلى للجيش. سلطته مطلقة تتميّز بالاستبداد والتعسّف لأنّ بيده السلطات التشريعية والتنفيذية والقضائية معاً، ومن صلاحياته أيضاً إدارة السياسة الخارجية وعقد المعاهدات.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15238, 2119, 2, 'المفوّض السامي فرنسي الجنسية، مركزه بيروت، ممثّل فرنسا في لبنان وسوريا والقائد الأعلى للجيش. سلطته مطلقة تتميّز بالاستبداد والتعسّف لأنّ بيده السلطات التشريعية والتنفيذية والقضائية معاً، ومن صلاحياته أيضاً إدارة السياسة الخارجية وعقد المعاهدات.', 1, '2026-09-30 22:11:02', '2026-09-30 22:11:02'),
(15239, 2120, 1, 'المطالب: 1) جعل بيروت مدينة مفتوحة أسوةً بباريس. 2) احترام المدنيين وعدم التعرّض لهم. 3) وقف القتال على جميع الأراضي اللبنانية. الدافع: قصف الطائرات البريطانية المواقع الفيشية وخزانات النفط في المدن الساحلية وخاصة بيروت، وسقوط ضحايا، ونزوح السكان نحو الجبال، وتظاهر الوفود الشعبية أمام قصر رئيس الجمهورية وتقديم العرائض المطالبة بوقف القتال.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15240, 2120, 2, 'المطالب: 1) جعل بيروت مدينة مفتوحة أسوةً بباريس. 2) احترام المدنيين وعدم التعرّض لهم. 3) وقف القتال على جميع الأراضي اللبنانية. الدافع: قصف الطائرات البريطانية المواقع الفيشية وخزانات النفط في المدن الساحلية وخاصة بيروت، وسقوط ضحايا، ونزوح السكان نحو الجبال، وتظاهر الوفود الشعبية أمام قصر رئيس الجمهورية وتقديم العرائض المطالبة بوقف القتال.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15241, 2121, 1, 'شارل دباس مسيحي أرثوذكسي من بيروت، تعلّم لدى اليسوعيين وتابع دراسة الحقوق في باريس وتزوّج من فرنسية، وعمل في باريس في القضايا العربية، ثمّ عاد فمارس الصحافة والسياسة وشغل وظائف أبرزها إدارة العدلية، وانتُخب أول رئيس للجمهورية اللبنانية في 26 أيار 1926. من المنجزات (اثنان): محاولات لإصلاح الإدارة والتعليم؛ وضع برامج التعليم الثانوي (البكالوريا بقسميها وفرعيها)؛ وضع النشيد الوطني (كلمات رشيد نخلة وألحان وديع صبرا)؛ المباشرة ببناء المتحف الوطني في بيروت.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15242, 2121, 2, 'شارل دباس مسيحي أرثوذكسي من بيروت، تعلّم لدى اليسوعيين وتابع دراسة الحقوق في باريس وتزوّج من فرنسية، وعمل في باريس في القضايا العربية، ثمّ عاد فمارس الصحافة والسياسة وشغل وظائف أبرزها إدارة العدلية، وانتُخب أول رئيس للجمهورية اللبنانية في 26 أيار 1926. من المنجزات (اثنان): محاولات لإصلاح الإدارة والتعليم؛ وضع برامج التعليم الثانوي (البكالوريا بقسميها وفرعيها)؛ وضع النشيد الوطني (كلمات رشيد نخلة وألحان وديع صبرا)؛ المباشرة ببناء المتحف الوطني في بيروت.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15244, 2122, 1, 'أربعة ممّا يأتي: تعليق الدستور؛ إقالة الحكومة وتعيين مجلس مديرين برئاسة عبدالله بيهم أمين سر الدولة مع الإبقاء على إميل إدّه رئيساً للجمهورية؛ إعلان الأحكام العرفية؛ حلّ الأحزاب وملاحقة زعمائها وفي طليعتها الحزب الشيوعي والحزب السوري القومي؛ مراقبة الصحافة ومنع بعضها من الصدور؛ منع الاجتماعات السياسية وإشراف الفرنسيين على دوائر الدولة؛ صدور المراسيم بتوقيع رئيس الدولة ومصادقة المفوض السامي. الأثر: تعليق الدستور عطّل العمل الدستوري ونقل القرار إلى المفوض السامي، أو حلّ الأحزاب مع مراقبة الصحافة ومنع الاجتماعات خنق العمل السياسي والرأي العام.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15246, 2122, 2, 'أربعة ممّا يأتي: تعليق الدستور؛ إقالة الحكومة وتعيين مجلس مديرين برئاسة عبدالله بيهم أمين سر الدولة مع الإبقاء على إميل إدّه رئيساً للجمهورية؛ إعلان الأحكام العرفية؛ حلّ الأحزاب وملاحقة زعمائها وفي طليعتها الحزب الشيوعي والحزب السوري القومي؛ مراقبة الصحافة ومنع بعضها من الصدور؛ منع الاجتماعات السياسية وإشراف الفرنسيين على دوائر الدولة؛ صدور المراسيم بتوقيع رئيس الدولة ومصادقة المفوض السامي. الأثر: تعليق الدستور عطّل العمل الدستوري ونقل القرار إلى المفوض السامي، أو حلّ الأحزاب مع مراقبة الصحافة ومنع الاجتماعات خنق العمل السياسي والرأي العام.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15247, 2124, 1, 'ثلاثة ممّا يأتي: حلّ المجلس النيابي وتمديد ولاية دباس سنة قابلة للتجديد؛ بدء المطالبة بعودة الدستور والحياة البرلمانية؛ استقالة دباس في أواخر كانون الثاني 1934؛ تعيين رئيس فرنسي مؤقت للدولة هو بريفا أبوار وتشكيل مجلس نواب من 25 عضواً عيّن المفوض السامي سبعة منهم؛ تعيين حبيب باشا السعد رئيساً للجمهورية؛ ممارسة المفوض السامي صلاحيات السلطة التشريعية كما في الانتداب المباشر.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15248, 2124, 2, 'ثلاثة ممّا يأتي: حلّ المجلس النيابي وتمديد ولاية دباس سنة قابلة للتجديد؛ بدء المطالبة بعودة الدستور والحياة البرلمانية؛ استقالة دباس في أواخر كانون الثاني 1934؛ تعيين رئيس فرنسي مؤقت للدولة هو بريفا أبوار وتشكيل مجلس نواب من 25 عضواً عيّن المفوض السامي سبعة منهم؛ تعيين حبيب باشا السعد رئيساً للجمهورية؛ ممارسة المفوض السامي صلاحيات السلطة التشريعية كما في الانتداب المباشر.', 1, '2026-09-30 22:11:03', '2026-09-30 22:11:03'),
(15249, 2125, 1, 'لم يرد ذكر الفرنسيين الأحرار صراحةً في اتفاقية عكا، فلم يكن ثمّة ما يخوّل حركة ديغول أن تحلّ مكان الفيشيين في سوريا ولبنان، فغضب ديغول وأرسل عدّة برقيات احتجاج إلى المسؤولين الإنكليز. أهمّ ما في التعديل: نقل الإدارة في لبنان وسوريا إلى الفرنسيين الأحرار، واعتراف بريطانيا بمركز ممتاز لفرنسا الحرة في تلك البلاد. ومع ذلك استمرّ الصراع السياسي بين الفرنسيين والإنكليز حتى معركة الاستقلال في تشرين الثاني 1943.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15250, 2125, 2, 'لم يرد ذكر الفرنسيين الأحرار صراحةً في اتفاقية عكا، فلم يكن ثمّة ما يخوّل حركة ديغول أن تحلّ مكان الفيشيين في سوريا ولبنان، فغضب ديغول وأرسل عدّة برقيات احتجاج إلى المسؤولين الإنكليز. أهمّ ما في التعديل: نقل الإدارة في لبنان وسوريا إلى الفرنسيين الأحرار، واعتراف بريطانيا بمركز ممتاز لفرنسا الحرة في تلك البلاد. ومع ذلك استمرّ الصراع السياسي بين الفرنسيين والإنكليز حتى معركة الاستقلال في تشرين الثاني 1943.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15251, 2126, 1, 'ثلاثة ممّا يأتي: خنق الأنوار؛ حراسة الجسور؛ مراقبة الشواطئ؛ إقامة التحصينات عند الثغور التي تصلح لإنزال بحري؛ بناء بيوت للمدافع؛ فتح باب التطوّع في الجيش الفرنسي فتشكّلت فرقة الأنصار (فرقة الشرق الخاصة). الغاية: الاستعداد لاحتمال وصول الحرب إلى الساحل اللبناني، إذ كان الخطر المتوقّع إنزالاً بحرياً.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15252, 2126, 2, 'ثلاثة ممّا يأتي: خنق الأنوار؛ حراسة الجسور؛ مراقبة الشواطئ؛ إقامة التحصينات عند الثغور التي تصلح لإنزال بحري؛ بناء بيوت للمدافع؛ فتح باب التطوّع في الجيش الفرنسي فتشكّلت فرقة الأنصار (فرقة الشرق الخاصة). الغاية: الاستعداد لاحتمال وصول الحرب إلى الساحل اللبناني، إذ كان الخطر المتوقّع إنزالاً بحرياً.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15253, 2127, 1, 'مكسب للبنان (واحد ممّا يأتي): اعتراف فرنسا باستقلال لبنان وتعهّدها بإدخاله في عصبة الأمم خلال ثلاث سنوات؛ تعامل البلدين كدولتين مستقلتين وحليفتين؛ إنشاء تمثيل ديبلوماسي؛ تقديم المساعدات الفنية والعلمية؛ مساعدة لبنان على إنشاء قوة للدفاع عن أمنه. لفرنسا (اثنان): يصبح المفوض السامي سفيراً ويتمتّع بالأسبقية على سائر السفراء؛ يحقّ لفرنسا إبقاء قواتها في لبنان؛ يحقّ لها استخدام الأراضي والمياه والأجواء اللبنانية. الحيف: بقاء القوات الأجنبية والقواعد العسكرية على الأرض مدة خمس وعشرين سنة رغم الاعتراف بالاستقلال.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15254, 2127, 2, 'مكسب للبنان (واحد ممّا يأتي): اعتراف فرنسا باستقلال لبنان وتعهّدها بإدخاله في عصبة الأمم خلال ثلاث سنوات؛ تعامل البلدين كدولتين مستقلتين وحليفتين؛ إنشاء تمثيل ديبلوماسي؛ تقديم المساعدات الفنية والعلمية؛ مساعدة لبنان على إنشاء قوة للدفاع عن أمنه. لفرنسا (اثنان): يصبح المفوض السامي سفيراً ويتمتّع بالأسبقية على سائر السفراء؛ يحقّ لفرنسا إبقاء قواتها في لبنان؛ يحقّ لها استخدام الأراضي والمياه والأجواء اللبنانية. الحيف: بقاء القوات الأجنبية والقواعد العسكرية على الأرض مدة خمس وعشرين سنة رغم الاعتراف بالاستقلال.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15255, 2128, 1, 'قبل سقوط فرنسا: خاف اللبنانيون من تكرار مأساة الحرب الأولى فأسرعوا إلى شراء المواد الغذائية وعادوا إلى الأرض ولا سيّما زراعة القمح، ولم يصلوا إلى أزمة صعبة ولم تحدث مجاعة. في عهد فيشي: احتجّ الأهالي على الوضع الاقتصادي السيّئ، ووقعت تظاهرات واضطرابات، وارتفعت الأصوات تطالب بإنهاء الانتداب. التعليل: الضيق في المرحلة الثانية كان أشدّ بسبب تشديد الإنكليز الحصار البحري ومنع نفط العراق عن مصفاة طرابلس وتضاؤل التبادل التجاري، فبرزت مشكلة النقل وفُقدت مواد أساسية وارتفعت الأسعار.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15256, 2128, 2, 'قبل سقوط فرنسا: خاف اللبنانيون من تكرار مأساة الحرب الأولى فأسرعوا إلى شراء المواد الغذائية وعادوا إلى الأرض ولا سيّما زراعة القمح، ولم يصلوا إلى أزمة صعبة ولم تحدث مجاعة. في عهد فيشي: احتجّ الأهالي على الوضع الاقتصادي السيّئ، ووقعت تظاهرات واضطرابات، وارتفعت الأصوات تطالب بإنهاء الانتداب. التعليل: الضيق في المرحلة الثانية كان أشدّ بسبب تشديد الإنكليز الحصار البحري ومنع نفط العراق عن مصفاة طرابلس وتضاؤل التبادل التجاري، فبرزت مشكلة النقل وفُقدت مواد أساسية وارتفعت الأسعار.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15257, 2129, 1, 'البنود (ثلاثة): الإقرار بوحدة الأراضي اللبنانية؛ المساواة بين أبناء لبنان؛ حقّ لبنان في إنشاء قوة عسكرية (إعداد الجيش اللبناني)؛ ممارسة حقّه في التمثيل الخارجي مع دول العالم. المكاسب (اثنان): اعتراف فرنسا الحرة باستقلال لبنان لدى عصبة الأمم؛ اعتراف الدول الأجنبية (الولايات المتحدة وبريطانيا والاتحاد السوفياتي...) والدول العربية المستقلة آنذاك وتعيين سفراء لها؛ إبلاغ عصبة الأمم بمضمون هذا الاستقلال؛ حقّ اللبنانيين في إنشاء علاقات ديبلوماسية مع الخارج؛ حقّهم في إنشاء قوة عسكرية وطنية خاصة بهم.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15258, 2129, 2, 'البنود (ثلاثة): الإقرار بوحدة الأراضي اللبنانية؛ المساواة بين أبناء لبنان؛ حقّ لبنان في إنشاء قوة عسكرية (إعداد الجيش اللبناني)؛ ممارسة حقّه في التمثيل الخارجي مع دول العالم. المكاسب (اثنان): اعتراف فرنسا الحرة باستقلال لبنان لدى عصبة الأمم؛ اعتراف الدول الأجنبية (الولايات المتحدة وبريطانيا والاتحاد السوفياتي...) والدول العربية المستقلة آنذاك وتعيين سفراء لها؛ إبلاغ عصبة الأمم بمضمون هذا الاستقلال؛ حقّ اللبنانيين في إنشاء علاقات ديبلوماسية مع الخارج؛ حقّهم في إنشاء قوة عسكرية وطنية خاصة بهم.', 1, '2026-09-30 22:11:04', '2026-09-30 22:11:04'),
(15259, 2130, 1, 'لأنّه أُعلن بالكلام ولم يُترجَم كلّه على أرض الواقع: استمرّ تمتّع المفوّض السامي بصلاحياته الواسعة، وبقي الدستور معلّقاً، وقُيّدت صلاحيات رئيس الجمهورية، وبقي للفرنسيين حقّ تعيين رئيس الجمهورية والوزراء (ويُقبل أيضاً: تمسّك كاترو بروح معاهدة 1936 للحصول على مركز ممتاز لفرنسا، وتثبيت نقّاش بقرار منه). مطالب مؤتمر بكركي: الاستقلال الكامل للبنان؛ عودة الحياة الدستورية؛ إنشاء حكومة وطنية.', 1, '2026-09-30 22:11:05', '2026-09-30 22:11:05'),
(15260, 2130, 2, 'لأنّه أُعلن بالكلام ولم يُترجَم كلّه على أرض الواقع: استمرّ تمتّع المفوّض السامي بصلاحياته الواسعة، وبقي الدستور معلّقاً، وقُيّدت صلاحيات رئيس الجمهورية، وبقي للفرنسيين حقّ تعيين رئيس الجمهورية والوزراء (ويُقبل أيضاً: تمسّك كاترو بروح معاهدة 1936 للحصول على مركز ممتاز لفرنسا، وتثبيت نقّاش بقرار منه). مطالب مؤتمر بكركي: الاستقلال الكامل للبنان؛ عودة الحياة الدستورية؛ إنشاء حكومة وطنية.', 1, '2026-09-30 22:11:05', '2026-09-30 22:11:05'),
(15261, 2131, 1, 'أراد أيوب تابت إشراك المغتربين في الانتخابات واقترح أن يكون عدد النواب 54 (32 مسيحياً و22 مسلماً)، فاحتجّ المسلمون وجرت تظاهرات. فتدخّل المفوّض السامي الجديد الجنرال هلو فأقال تابت وعيّن مكانه بترو طراد، الذي أجرى مشاورات داخلية وعربية وحدّد عدد النواب بـ55 نائباً (30 مسيحياً و25 مسلماً) على قاعدة 6 للمسيحيين مقابل 5 للمسلمين.', 1, '2026-09-30 22:11:05', '2026-09-30 22:11:05'),
(15262, 2131, 2, 'أراد أيوب تابت إشراك المغتربين في الانتخابات واقترح أن يكون عدد النواب 54 (32 مسيحياً و22 مسلماً)، فاحتجّ المسلمون وجرت تظاهرات. فتدخّل المفوّض السامي الجديد الجنرال هلو فأقال تابت وعيّن مكانه بترو طراد، الذي أجرى مشاورات داخلية وعربية وحدّد عدد النواب بـ55 نائباً (30 مسيحياً و25 مسلماً) على قاعدة 6 للمسيحيين مقابل 5 للمسلمين.', 1, '2026-09-30 22:11:05', '2026-09-30 22:11:05'),
(15263, 2132, 1, 'اعتبرت فرنسا الجزائر جزءاً منها فعملت على فرنستها، ومن وسائلها (يكفي ثلاث): محاربة اللغة العربية وفرض اللغة الفرنسية في المناهج التعليمية؛ فرض التجنيد الإجباري على الجزائريين؛ تشجيع الفرنسيين على الهجرة إلى الجزائر واستملاك أراضٍ فيها؛ تعيين موظفين فرنسيين في الوظائف المهمّة؛ إصدار قانون يجعل كلّ جزائري فرنسياً يحمل الهوية الفرنسية. الهدف المشترك: دمج الجزائر في فرنسا ومحو شخصيتها.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15264, 2132, 2, 'اعتبرت فرنسا الجزائر جزءاً منها فعملت على فرنستها، ومن وسائلها (يكفي ثلاث): محاربة اللغة العربية وفرض اللغة الفرنسية في المناهج التعليمية؛ فرض التجنيد الإجباري على الجزائريين؛ تشجيع الفرنسيين على الهجرة إلى الجزائر واستملاك أراضٍ فيها؛ تعيين موظفين فرنسيين في الوظائف المهمّة؛ إصدار قانون يجعل كلّ جزائري فرنسياً يحمل الهوية الفرنسية. الهدف المشترك: دمج الجزائر في فرنسا ومحو شخصيتها.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15265, 2133, 1, 'السبب غير المباشر عامل متراكم يهيّئ الأرضية للثورة، ومثاله: رفض الجزائريين للسياسة الفرنسية وتمسّكهم بقوميتهم العربية وباللغة العربية، أو الوعي الوطني المطالب بالاستقلال، أو بروز حركات التحرّر في المستعمرات الفرنسية والإنكليزية، أو سعي فرنسا إلى إحكام السيطرة على اقتصاد الجزائر (الاستيلاء على الثروات الباطنية ومصادرة الأراضي الزراعية). أمّا السبب المباشر فهو الحادثة التي فجّرت الوضع، وهو حادثة 8 أيار 1945 حين أطلق الجيش الفرنسي النار على المتظاهرين المطالبين بالاستقلال فذهب ضحيتها خمسة وأربعون ألف شهيد.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15266, 2133, 2, 'السبب غير المباشر عامل متراكم يهيّئ الأرضية للثورة، ومثاله: رفض الجزائريين للسياسة الفرنسية وتمسّكهم بقوميتهم العربية وباللغة العربية، أو الوعي الوطني المطالب بالاستقلال، أو بروز حركات التحرّر في المستعمرات الفرنسية والإنكليزية، أو سعي فرنسا إلى إحكام السيطرة على اقتصاد الجزائر (الاستيلاء على الثروات الباطنية ومصادرة الأراضي الزراعية). أمّا السبب المباشر فهو الحادثة التي فجّرت الوضع، وهو حادثة 8 أيار 1945 حين أطلق الجيش الفرنسي النار على المتظاهرين المطالبين بالاستقلال فذهب ضحيتها خمسة وأربعون ألف شهيد.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15267, 2134, 1, 'منح الخديوي محمد سعيد المهندس الفرنسي دي لسبس الامتياز سنة 1854، وشروطه: 1) تستغلّ الشركة القناة 99 سنة تبدأ منذ افتتاحها ثمّ تعود ملكيتها إلى مصر. 2) تأخذ الشركة أراضي على جانبي القناة بعمق كيلومترين من كلّ جانب وتُعفى من دفع الضرائب. 3) تقدّم مصر أربعة أخماس عدد العمّال الإجمالي الذي يتطلّبه الحفر بصورة مجانية. 4) تحصل مصر على 15% من صافي أرباح الشركة. الشروط الثلاثة الأولى التزامات على مصر، والرابع وحده مردودها؛ فالتزاماتها ثقيلة ومردودها محدود.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15268, 2134, 2, 'منح الخديوي محمد سعيد المهندس الفرنسي دي لسبس الامتياز سنة 1854، وشروطه: 1) تستغلّ الشركة القناة 99 سنة تبدأ منذ افتتاحها ثمّ تعود ملكيتها إلى مصر. 2) تأخذ الشركة أراضي على جانبي القناة بعمق كيلومترين من كلّ جانب وتُعفى من دفع الضرائب. 3) تقدّم مصر أربعة أخماس عدد العمّال الإجمالي الذي يتطلّبه الحفر بصورة مجانية. 4) تحصل مصر على 15% من صافي أرباح الشركة. الشروط الثلاثة الأولى التزامات على مصر، والرابع وحده مردودها؛ فالتزاماتها ثقيلة ومردودها محدود.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15269, 2135, 1, 'تصرّفت الحكومة كحكومة دولة مستقلة وتجاهلت الانتداب في الممارسة، ومن خطواتها (يكفي ثلاث): 1) عدم زيارة المفوّض السامي واعتبار المندوب الفرنسي سفيراً كغيره من السفراء، ودلالتها رفض التبعية. 2) فرض العربية في الدواوين، إذ أوجبت بمذكّرة استعمال العربية في كلّ المعاملات وصارت أوامر الحرس والدرك بالعربية، ودلالتها سيادة اللغة الوطنية. 3) تحديد البيان الوزاري دون إطلاع الفرنسيين عليه قبل عرضه على المجلس النيابي، ودلالتها استقلال القرار. 4) المطالبة باستلام المصالح (20 تشرين الأول) ورفض أيّة معاهدة قبل الاستقلال الناجز، ودلالتها أنّ الاستقلال يجب أن يكون ناجزاً لا مشروطاً.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15270, 2135, 2, 'تصرّفت الحكومة كحكومة دولة مستقلة وتجاهلت الانتداب في الممارسة، ومن خطواتها (يكفي ثلاث): 1) عدم زيارة المفوّض السامي واعتبار المندوب الفرنسي سفيراً كغيره من السفراء، ودلالتها رفض التبعية. 2) فرض العربية في الدواوين، إذ أوجبت بمذكّرة استعمال العربية في كلّ المعاملات وصارت أوامر الحرس والدرك بالعربية، ودلالتها سيادة اللغة الوطنية. 3) تحديد البيان الوزاري دون إطلاع الفرنسيين عليه قبل عرضه على المجلس النيابي، ودلالتها استقلال القرار. 4) المطالبة باستلام المصالح (20 تشرين الأول) ورفض أيّة معاهدة قبل الاستقلال الناجز، ودلالتها أنّ الاستقلال يجب أن يكون ناجزاً لا مشروطاً.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15271, 2136, 1, 'المضمون: وُقّعت سنة 1962 بعد مفاوضات سرّية بين الحكومة الفرنسية وجبهة التحرير الجزائرية، ونصّت على استقلال الجزائر، مقابل تعاون اقتصادي وثقافي وعسكري مع فرنسا، وضمان سلامة الأوروبيين. النتيجتان: دخول الجزائر في المنظّمات الدولية والعربية، وعُرفت ثورتها بثورة المليون شهيد.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15272, 2136, 2, 'المضمون: وُقّعت سنة 1962 بعد مفاوضات سرّية بين الحكومة الفرنسية وجبهة التحرير الجزائرية، ونصّت على استقلال الجزائر، مقابل تعاون اقتصادي وثقافي وعسكري مع فرنسا، وضمان سلامة الأوروبيين. النتيجتان: دخول الجزائر في المنظّمات الدولية والعربية، وعُرفت ثورتها بثورة المليون شهيد.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15273, 2137, 1, 'الأسباب: خوفها من سيطرة فرنسا على مصر؛ امتلاكها طريقاً حول أفريقيا يؤمّن طريقها إلى الهند؛ سفنها شراعية لا تناسبها القناة؛ خوفها من أن يتضرّر خطّ سكة الحديد بين السويس والإسكندرية الذي حصلت على امتياز إنشائه. الوسائل (اثنتان ممّا يلي): الضغط على السلطان العثماني كي لا يوافق على الامتياز وإقناعه بأنّ فرنسا تسعى إلى السيطرة على مصر؛ رفض اقتراح دي لسبس إعطاء القناة صفة دولية؛ الامتناع عن شراء الأسهم ومحاولة إقناع الدول الأوروبية بعدم المشاركة.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15274, 2137, 2, 'الأسباب: خوفها من سيطرة فرنسا على مصر؛ امتلاكها طريقاً حول أفريقيا يؤمّن طريقها إلى الهند؛ سفنها شراعية لا تناسبها القناة؛ خوفها من أن يتضرّر خطّ سكة الحديد بين السويس والإسكندرية الذي حصلت على امتياز إنشائه. الوسائل (اثنتان ممّا يلي): الضغط على السلطان العثماني كي لا يوافق على الامتياز وإقناعه بأنّ فرنسا تسعى إلى السيطرة على مصر؛ رفض اقتراح دي لسبس إعطاء القناة صفة دولية؛ الامتناع عن شراء الأسهم ومحاولة إقناع الدول الأوروبية بعدم المشاركة.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15275, 2138, 1, 'الشعبية (اثنان ممّا يلي): إضراب بيروت وبقية المدن وإقفال المدارس والمحالّ التجارية؛ التظاهرات والصدامات مع الجيش الفرنسي وإحراق السيارات؛ توحيد حزبي الكتائب والنجادة جهودهما بقيادة الشيخ بيار الجميّل؛ المؤتمر الوطني في 12 تشرين الثاني؛ دور الجمعيات النسائية والطلاب وجريدة سرّية عليها علامتا استفهام. الرسمية (اثنان ممّا يلي): سبعة نوّاب وضعوا مذكّرة احتجاج وقرّروا تغيير شكل العلم اللبناني؛ اجتماع 33 نائباً في منزل صائب سلام وتكليف حبيب أبي شهلا ومجيد أرسلان أعمال السلطة التنفيذية المعلّقة؛ حكومة مؤقتة انتقلت إلى بشامون وانضمّ إليها صبري حمادة واتّخذت تدابير كتشكيل حرس وطني والطلب من الموظفين الامتناع عن العمل.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15276, 2138, 2, 'الشعبية (اثنان ممّا يلي): إضراب بيروت وبقية المدن وإقفال المدارس والمحالّ التجارية؛ التظاهرات والصدامات مع الجيش الفرنسي وإحراق السيارات؛ توحيد حزبي الكتائب والنجادة جهودهما بقيادة الشيخ بيار الجميّل؛ المؤتمر الوطني في 12 تشرين الثاني؛ دور الجمعيات النسائية والطلاب وجريدة سرّية عليها علامتا استفهام. الرسمية (اثنان ممّا يلي): سبعة نوّاب وضعوا مذكّرة احتجاج وقرّروا تغيير شكل العلم اللبناني؛ اجتماع 33 نائباً في منزل صائب سلام وتكليف حبيب أبي شهلا ومجيد أرسلان أعمال السلطة التنفيذية المعلّقة؛ حكومة مؤقتة انتقلت إلى بشامون وانضمّ إليها صبري حمادة واتّخذت تدابير كتشكيل حرس وطني والطلب من الموظفين الامتناع عن العمل.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15277, 2139, 1, 'الظرف: أغرق الخديوي إسماعيل مصر بالديون (ومنها ما دفعته لقاء التعديل ونفقات الاحتفال الباذخ) فأوشكت الخزينة على الإفلاس، فعرض بيع أسهم مصر في القناة. الحدث: سارعت بريطانيا واشترت الأسهم بأربعة ملايين جنيه إسترليني. النتائج: أصبحت بريطانيا تملك نحو 44% من أسهم القناة، وبدأت تسعى لبسط نفوذها ليس على القناة فحسب بل على مصر بكاملها.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15278, 2139, 2, 'الظرف: أغرق الخديوي إسماعيل مصر بالديون (ومنها ما دفعته لقاء التعديل ونفقات الاحتفال الباذخ) فأوشكت الخزينة على الإفلاس، فعرض بيع أسهم مصر في القناة. الحدث: سارعت بريطانيا واشترت الأسهم بأربعة ملايين جنيه إسترليني. النتائج: أصبحت بريطانيا تملك نحو 44% من أسهم القناة، وبدأت تسعى لبسط نفوذها ليس على القناة فحسب بل على مصر بكاملها.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15279, 2140, 1, 'أمام الضغط الداخلي والتأييد العربي والدولي (بريطانيا والولايات المتحدة والاتحاد السوفياتي)، أوفدت اللجنة الفرنسية في الجزائر الجنرال كاترو، فأفهمه الجميع، مسيحيين ومسلمين، أن لا مفاوضات إلّا مع الحكومة الشرعية الممثّلة برئيس الجمهورية والوزراء المعتقلين. فقابل بشارة الخوري ورياض الصلح سرّاً في 18 و19 تشرين الثاني، ثمّ أصدر قراراً بإلغاء تدابير هلّو وإطلاق المعتقلين صبيحة 22 تشرين الثاني، فصار هذا اليوم عيداً للاستقلال ورمزاً للإرادة الوطنية.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15280, 2140, 2, 'أمام الضغط الداخلي والتأييد العربي والدولي (بريطانيا والولايات المتحدة والاتحاد السوفياتي)، أوفدت اللجنة الفرنسية في الجزائر الجنرال كاترو، فأفهمه الجميع، مسيحيين ومسلمين، أن لا مفاوضات إلّا مع الحكومة الشرعية الممثّلة برئيس الجمهورية والوزراء المعتقلين. فقابل بشارة الخوري ورياض الصلح سرّاً في 18 و19 تشرين الثاني، ثمّ أصدر قراراً بإلغاء تدابير هلّو وإطلاق المعتقلين صبيحة 22 تشرين الثاني، فصار هذا اليوم عيداً للاستقلال ورمزاً للإرادة الوطنية.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15281, 2141, 1, 'الانتداب نظام جديد للعلاقات السياسية الدولية صدر عن عصبة الأمم، وهو حلّ وسط بين الاستعمار وحقّ تقرير المصير، يوصي بتوكيل دولة كبرى منتصرة في الحرب العالمية الأولى بالإشراف على المستعمرات التي كانت تخضع لحكم الدول المهزومة (ألمانيا والنمسا وتركيا) وتدريبها على إدارة شؤونها حتى تصبح قادرة على أن تحكم نفسها بنفسها. تمّ التوصّل إليه باقتراح من الجنرال سمطس رئيس وزراء اتحاد جنوب أفريقيا، حلّاً وسطاً بين فكرة حقّ الشعوب في تقرير مصيرها التي دعا إليها الرئيس الأميركي ولسون وفكرة الاستعمار التي أيّدتها فرنسا وبريطانيا؛ فأيّده ولسون ووافقت عليه باقي الدول الأوروبية في مؤتمر باريس.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15282, 2141, 2, 'الانتداب نظام جديد للعلاقات السياسية الدولية صدر عن عصبة الأمم، وهو حلّ وسط بين الاستعمار وحقّ تقرير المصير، يوصي بتوكيل دولة كبرى منتصرة في الحرب العالمية الأولى بالإشراف على المستعمرات التي كانت تخضع لحكم الدول المهزومة (ألمانيا والنمسا وتركيا) وتدريبها على إدارة شؤونها حتى تصبح قادرة على أن تحكم نفسها بنفسها. تمّ التوصّل إليه باقتراح من الجنرال سمطس رئيس وزراء اتحاد جنوب أفريقيا، حلّاً وسطاً بين فكرة حقّ الشعوب في تقرير مصيرها التي دعا إليها الرئيس الأميركي ولسون وفكرة الاستعمار التي أيّدتها فرنسا وبريطانيا؛ فأيّده ولسون ووافقت عليه باقي الدول الأوروبية في مؤتمر باريس.', 1, '2026-09-30 22:11:08', '2026-09-30 22:11:08'),
(15283, 2142, 1, 'صكّ الانتداب وثيقة دولية رسمية وضعتها لجنة من رجال القانون في لندن بتكليف من عصبة الأمم لتحديد مسؤوليات الدول المنتدبة وحقوقها في بلدان الانتداب، صدر في تموز 1922 وبوشر العمل به في أيلول 1923، ويتألّف من مقدّمة وعشرين مادة. من بنوده (أربعة): وضع دستور خلال ثلاث سنوات من بدء تنفيذ الوثيقة؛ حقّ إبقاء جيشها في البلاد وتنظيم قوى أمن من السكّان؛ السيطرة على جميع العلاقات الخارجية للبنان وسوريا؛ المحافظة على أرض البلدين؛ الفرنسية والعربية لغتان رسميتان؛ إلغاء الامتيازات الأجنبية السابقة مع المحافظة على المحاكم القنصلية الأجنبية؛ ضمان الحريات وحقّ العبادة والشعائر الدينية والتعليم وعدم التدخّل في قضايا الطوائف؛ الاهتمام بالآثار.', 1, '2026-09-30 22:11:09', '2026-09-30 22:11:09'),
(15284, 2142, 2, 'صكّ الانتداب وثيقة دولية رسمية وضعتها لجنة من رجال القانون في لندن بتكليف من عصبة الأمم لتحديد مسؤوليات الدول المنتدبة وحقوقها في بلدان الانتداب، صدر في تموز 1922 وبوشر العمل به في أيلول 1923، ويتألّف من مقدّمة وعشرين مادة. من بنوده (أربعة): وضع دستور خلال ثلاث سنوات من بدء تنفيذ الوثيقة؛ حقّ إبقاء جيشها في البلاد وتنظيم قوى أمن من السكّان؛ السيطرة على جميع العلاقات الخارجية للبنان وسوريا؛ المحافظة على أرض البلدين؛ الفرنسية والعربية لغتان رسميتان؛ إلغاء الامتيازات الأجنبية السابقة مع المحافظة على المحاكم القنصلية الأجنبية؛ ضمان الحريات وحقّ العبادة والشعائر الدينية والتعليم وعدم التدخّل في قضايا الطوائف؛ الاهتمام بالآثار.', 1, '2026-09-30 22:11:09', '2026-09-30 22:11:09'),
(15285, 2143, 1, 'التزمت فرنسا بمضمون الصكّ بشكل عامّ. الإيجابيات: وضعت القوانين ونظّمت الإدارة والأمن (قوانين التقسيمات الإدارية والجمارك والانتخابات والشؤون المالية)؛ أنشأت المؤسسات ووضعت مناهج التعليم والدستور واهتمّت بالآثار والزراعة والأشغال. السلبيات (اثنتان ممّا يلي): حكمت حكماً استعمارياً دكتاتورياً؛ استغلّت المصالح الاقتصادية واستولت على الآثار وموارد الجمارك؛ منحت مستشاريها وموظّفيها وشركاتها كثيراً من الامتيازات؛ أثارت النعرات الطائفية والمذهبية؛ تعدّت على حدود لبنان فأعطت مساحات منه للانتداب البريطاني في فلسطين (القرى السبع)؛ تنازلت عن لواء الإسكندرون لصالح تركيا. الاستنتاج: التزام في الشكل ومخالفة في الجوهر.', 1, '2026-09-30 22:11:09', '2026-09-30 22:11:09'),
(15286, 2143, 2, 'التزمت فرنسا بمضمون الصكّ بشكل عامّ. الإيجابيات: وضعت القوانين ونظّمت الإدارة والأمن (قوانين التقسيمات الإدارية والجمارك والانتخابات والشؤون المالية)؛ أنشأت المؤسسات ووضعت مناهج التعليم والدستور واهتمّت بالآثار والزراعة والأشغال. السلبيات (اثنتان ممّا يلي): حكمت حكماً استعمارياً دكتاتورياً؛ استغلّت المصالح الاقتصادية واستولت على الآثار وموارد الجمارك؛ منحت مستشاريها وموظّفيها وشركاتها كثيراً من الامتيازات؛ أثارت النعرات الطائفية والمذهبية؛ تعدّت على حدود لبنان فأعطت مساحات منه للانتداب البريطاني في فلسطين (القرى السبع)؛ تنازلت عن لواء الإسكندرون لصالح تركيا. الاستنتاج: التزام في الشكل ومخالفة في الجوهر.', 1, '2026-09-30 22:11:09', '2026-09-30 22:11:09'),
(15287, 2144, 1, 'أنشأ الفرنسيون في عهد الانتداب مصالح اقتصادية تولّوا إدارتها، وكانت على نوعين: 1) مصالح خاصة بلبنان وحده، مثل شركات المياه والكهرباء (والتراموي). 2) مصالح مشتركة بين لبنان وسوريا، مثل الجمارك وسكة الحديد (والنقد والمرافئ والمنارات).', 1, '2026-09-30 22:11:10', '2026-09-30 22:11:10'),
(15288, 2144, 2, 'أنشأ الفرنسيون في عهد الانتداب مصالح اقتصادية تولّوا إدارتها، وكانت على نوعين: 1) مصالح خاصة بلبنان وحده، مثل شركات المياه والكهرباء (والتراموي). 2) مصالح مشتركة بين لبنان وسوريا، مثل الجمارك وسكة الحديد (والنقد والمرافئ والمنارات).', 1, '2026-09-30 22:11:10', '2026-09-30 22:11:10'),
(15289, 2145, 1, 'تمّ تسليم المصالح الخاصة والمشتركة بموجب توقيع محاضر رسمية: محاضر المصالح الخاصة بلبنان يوقّعها ممثّلا لبنان وفرنسا (طرفان)، ومحاضر المصالح المشتركة يوقّعها ممثّلا لبنان وسوريا من جهة وممثّل فرنسا من جهة ثانية (ثلاثة أطراف). ويختلف الموقّعون لأنّ سوريا شريكة في المصالح المشتركة.', 1, '2026-09-30 22:11:10', '2026-09-30 22:11:10'),
(15290, 2145, 2, 'تمّ تسليم المصالح الخاصة والمشتركة بموجب توقيع محاضر رسمية: محاضر المصالح الخاصة بلبنان يوقّعها ممثّلا لبنان وفرنسا (طرفان)، ومحاضر المصالح المشتركة يوقّعها ممثّلا لبنان وسوريا من جهة وممثّل فرنسا من جهة ثانية (ثلاثة أطراف). ويختلف الموقّعون لأنّ سوريا شريكة في المصالح المشتركة.', 1, '2026-09-30 22:11:10', '2026-09-30 22:11:10'),
(15291, 2146, 1, 'اتفاقية سايكس - بيكو اتفاقية سرية لتقسيم أملاك السلطنة العثمانية بين أربع دول هي: بريطانيا وفرنسا والاتحاد السوفياتي وإيطاليا. (جرت مفاوضاتها السرية بين مندوب بريطانيا مارك سايكس والمندوب الفرنسي جورج بيكو.)', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15292, 2147, 1, '1) مطالبة اللبنانيين بجلاء الجيوش الفرنسية والإنكليزية لأنّ الاستقلال ناقص والسيادة غير تامة، ومماطلة الحلفاء متذرّعين بالضرورات الحربية ومطالبين بمعاهدة. 2) الشكوى اللبنانية السورية إلى مجلس الأمن المنعقد في لندن (الوفد اللبناني برئاسة حميد فرنجية). 3) الاقتراح الأميركي بالجلاء بعد اتفاق بين الدول ذات العلاقة، والفيتو الروسي تأييداً للانسحاب الفوري دون شروط. 4) استئناف المفاوضات ونقلها إلى باريس، وإقرار الحلفاء بالانسحاب بدءاً من نيسان 1946، واستكماله في كانون الأول 1946، وتخليده بلوحة على صخور نهر الكلب.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15293, 2147, 2, '1) مطالبة اللبنانيين بجلاء الجيوش الفرنسية والإنكليزية لأنّ الاستقلال ناقص والسيادة غير تامة، ومماطلة الحلفاء متذرّعين بالضرورات الحربية ومطالبين بمعاهدة. 2) الشكوى اللبنانية السورية إلى مجلس الأمن المنعقد في لندن (الوفد اللبناني برئاسة حميد فرنجية). 3) الاقتراح الأميركي بالجلاء بعد اتفاق بين الدول ذات العلاقة، والفيتو الروسي تأييداً للانسحاب الفوري دون شروط. 4) استئناف المفاوضات ونقلها إلى باريس، وإقرار الحلفاء بالانسحاب بدءاً من نيسان 1946، واستكماله في كانون الأول 1946، وتخليده بلوحة على صخور نهر الكلب.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15294, 2146, 2, 'اتفاقية سايكس - بيكو اتفاقية سرية لتقسيم أملاك السلطنة العثمانية بين أربع دول هي: بريطانيا وفرنسا والاتحاد السوفياتي وإيطاليا. (جرت مفاوضاتها السرية بين مندوب بريطانيا مارك سايكس والمندوب الفرنسي جورج بيكو.)', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15295, 2148, 1, 'جمعية الاتحاد والترقي جمعية قامت على يد مجموعة من الشباب التركي في باريس بالتنسيق مع المعارضة الموجودة في إسطنبول، وعُرف أتباعها بالاتحاديين، وكانت أهدافها التخلّص من الحكم الاستبدادي وإعادة العمل بالدستور وإصلاح أمور الدولة. من مظاهر التتريك (ثلاثة): محاولة ترجمة القرآن الكريم إلى التركية؛ جعل التركية اللغة الرسمية الوحيدة في السلطنة؛ تمجيد الحضارة التركية والقومية الطورانية وعدم المساواة بين العرب والأتراك؛ تسليم المراكز الأساسية والوظائف العليا للأتراك؛ اعتماد نظام المركزية الإدارية وحصر كلّ السلطات في إسطنبول؛ رفض نظام الحكم الذاتي للعرب.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15296, 2148, 2, 'جمعية الاتحاد والترقي جمعية قامت على يد مجموعة من الشباب التركي في باريس بالتنسيق مع المعارضة الموجودة في إسطنبول، وعُرف أتباعها بالاتحاديين، وكانت أهدافها التخلّص من الحكم الاستبدادي وإعادة العمل بالدستور وإصلاح أمور الدولة. من مظاهر التتريك (ثلاثة): محاولة ترجمة القرآن الكريم إلى التركية؛ جعل التركية اللغة الرسمية الوحيدة في السلطنة؛ تمجيد الحضارة التركية والقومية الطورانية وعدم المساواة بين العرب والأتراك؛ تسليم المراكز الأساسية والوظائف العليا للأتراك؛ اعتماد نظام المركزية الإدارية وحصر كلّ السلطات في إسطنبول؛ رفض نظام الحكم الذاتي للعرب.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15297, 2149, 1, 'المنطقة الزرقاء: تشمل الساحل اللبناني والسوري حتى كيليكيا، وإدارتها فرنسية مباشرة. المنطقة السمراء: تشمل فلسطين، وإدارتها دولية بإشراف بريطانيا. المنطقة الحمراء: تشمل ولايتي بغداد والبصرة، وإدارتها بريطانية مباشرة. (ويمكن الإضافة: دولتان عربيتان في الداخل بحكم عربي خاضع للنفوذ: الأولى دمشق وحلب والموصل للنفوذ الفرنسي، والثانية حتى نجد والحجاز للنفوذ البريطاني.)', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15298, 2149, 2, 'المنطقة الزرقاء: تشمل الساحل اللبناني والسوري حتى كيليكيا، وإدارتها فرنسية مباشرة. المنطقة السمراء: تشمل فلسطين، وإدارتها دولية بإشراف بريطانيا. المنطقة الحمراء: تشمل ولايتي بغداد والبصرة، وإدارتها بريطانية مباشرة. (ويمكن الإضافة: دولتان عربيتان في الداخل بحكم عربي خاضع للنفوذ: الأولى دمشق وحلب والموصل للنفوذ الفرنسي، والثانية حتى نجد والحجاز للنفوذ البريطاني.)', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15299, 2150, 1, 'الصفة: العربية الفتاة سرّية، وبيروت الإصلاحية علنية. المكان والسنة: العربية الفتاة في باريس سنة 1911، وبيروت الإصلاحية في بيروت سنة 1912 من جميع الطوائف اللبنانية. الهدف: العربية الفتاة استقلال العرب عن الحكم التركي، وبيروت الإصلاحية الإصلاح في ولاية بيروت والاستقلال الذاتي للعرب ضمن نظام اللامركزية وجعل العربية لغة رسمية إلى جانب التركية. النتيجة: العربية الفتاة أسهمت في عقد المؤتمر العربي في باريس وفي اندلاع الثورة العربية، أمّا بيروت الإصلاحية فحلّها العثمانيون واعتقلوا زعماءها.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15300, 2150, 2, 'الصفة: العربية الفتاة سرّية، وبيروت الإصلاحية علنية. المكان والسنة: العربية الفتاة في باريس سنة 1911، وبيروت الإصلاحية في بيروت سنة 1912 من جميع الطوائف اللبنانية. الهدف: العربية الفتاة استقلال العرب عن الحكم التركي، وبيروت الإصلاحية الإصلاح في ولاية بيروت والاستقلال الذاتي للعرب ضمن نظام اللامركزية وجعل العربية لغة رسمية إلى جانب التركية. النتيجة: العربية الفتاة أسهمت في عقد المؤتمر العربي في باريس وفي اندلاع الثورة العربية، أمّا بيروت الإصلاحية فحلّها العثمانيون واعتقلوا زعماءها.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15301, 2151, 1, 'التعديلات (ثلاثة ممّا يلي): تخلّي فرنسا عن الموصل لبريطانيا مقابل حصة من نفط العراق؛ تخلّي فرنسا عن كيليكيا لتركيا؛ وضع فلسطين تحت الانتداب البريطاني المباشر مع الالتزام بوعد بلفور؛ عدم نيل روسيا حصتها؛ عدم قيام الدولتين العربيتين المشار إليهما في الاتفاقية. سبب عدم نيل روسيا حصتها: انسحابها من الحرب.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15302, 2151, 2, 'التعديلات (ثلاثة ممّا يلي): تخلّي فرنسا عن الموصل لبريطانيا مقابل حصة من نفط العراق؛ تخلّي فرنسا عن كيليكيا لتركيا؛ وضع فلسطين تحت الانتداب البريطاني المباشر مع الالتزام بوعد بلفور؛ عدم نيل روسيا حصتها؛ عدم قيام الدولتين العربيتين المشار إليهما في الاتفاقية. سبب عدم نيل روسيا حصتها: انسحابها من الحرب.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15303, 2152, 1, 'المقرّرات (أربعة): ضرورة الإصلاح داخل السلطنة؛ اعتماد اللغة العربية في الولايات العربية ومدارسها؛ حصر الخدمة العسكرية للشبّان العرب في مناطقهم؛ تمثيل العرب بثلاثة وزراء وتعيين خمسة ولاة عرب وعشرة متصرّفين؛ اعتماد اللامركزية في الولايات العربية؛ دعم مالية متصرّفية جبل لبنان؛ المساواة بين العرب والأتراك. الموقف: ذهب وفد إلى إسطنبول وقابل وزير الداخلية التركي، فوافقت السلطنة على بعض البنود فقط (اللغة العربية، الموظّفين، الخدمة العسكرية، تمثيل العرب بثلاثة وزراء وخمسة ولاة) ثمّ ماطلت في التنفيذ. النتيجة: عند اندلاع الحرب العالمية الأولى تنكّرت السلطنة لهذه المطالب وعادت إلى سياسة التنكيل والقمع، فأدّى ذلك إلى الثورة العربية الكبرى.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15304, 2152, 2, 'المقرّرات (أربعة): ضرورة الإصلاح داخل السلطنة؛ اعتماد اللغة العربية في الولايات العربية ومدارسها؛ حصر الخدمة العسكرية للشبّان العرب في مناطقهم؛ تمثيل العرب بثلاثة وزراء وتعيين خمسة ولاة عرب وعشرة متصرّفين؛ اعتماد اللامركزية في الولايات العربية؛ دعم مالية متصرّفية جبل لبنان؛ المساواة بين العرب والأتراك. الموقف: ذهب وفد إلى إسطنبول وقابل وزير الداخلية التركي، فوافقت السلطنة على بعض البنود فقط (اللغة العربية، الموظّفين، الخدمة العسكرية، تمثيل العرب بثلاثة وزراء وخمسة ولاة) ثمّ ماطلت في التنفيذ. النتيجة: عند اندلاع الحرب العالمية الأولى تنكّرت السلطنة لهذه المطالب وعادت إلى سياسة التنكيل والقمع، فأدّى ذلك إلى الثورة العربية الكبرى.', 1, '2026-09-30 22:11:11', '2026-09-30 22:11:11'),
(15305, 2153, 1, '1) مطالبة اللبنانيين المستمرّة بتحديد العلاقة مع فرنسا وبوضع دستور ينقل البلاد من مرحلة الانتداب المباشر إلى مرحلة الحكم الوطني. 2) المادة الأولى من صك الانتداب ألزمت فرنسا بوضع دستور للبلاد خلال ثلاث سنوات من بدء العمل بالصك بالاتّفاق مع السلطات الوطنية. 3) الثورة السورية الكبرى وما رافقها من تعاطف معها أو التحاق بصفوفها. 4) التأثّر بالجوار العربي، إذ شاركت بريطانيا ووافقت على وضع دساتير للعراق والأردن ومصر.', 1, '2026-09-30 22:11:12', '2026-09-30 22:11:12'),
(15306, 2153, 2, '1) مطالبة اللبنانيين المستمرّة بتحديد العلاقة مع فرنسا وبوضع دستور ينقل البلاد من مرحلة الانتداب المباشر إلى مرحلة الحكم الوطني. 2) المادة الأولى من صك الانتداب ألزمت فرنسا بوضع دستور للبلاد خلال ثلاث سنوات من بدء العمل بالصك بالاتّفاق مع السلطات الوطنية. 3) الثورة السورية الكبرى وما رافقها من تعاطف معها أو التحاق بصفوفها. 4) التأثّر بالجوار العربي، إذ شاركت بريطانيا ووافقت على وضع دساتير للعراق والأردن ومصر.', 1, '2026-09-30 22:11:12', '2026-09-30 22:11:12'),
(15307, 2154, 1, 'كانت السلطة التشريعية أوّل الأمر بيد نوّاب منتخبين، وإلى جانبهم شيوخ عددهم ستة عشر شيخاً، يعيّن رئيس الجمهورية تسعة منهم والباقون منتخبون. وفي سنة 1927 أُلغي مجلس الشيوخ بدمجه بمجلس النوّاب، فانتقل لبنان من نظام المجلسين إلى مجلس واحد.', 1, '2026-09-30 22:11:12', '2026-09-30 22:11:12'),
(15308, 2154, 2, 'كانت السلطة التشريعية أوّل الأمر بيد نوّاب منتخبين، وإلى جانبهم شيوخ عددهم ستة عشر شيخاً، يعيّن رئيس الجمهورية تسعة منهم والباقون منتخبون. وفي سنة 1927 أُلغي مجلس الشيوخ بدمجه بمجلس النوّاب، فانتقل لبنان من نظام المجلسين إلى مجلس واحد.', 1, '2026-09-30 22:11:12', '2026-09-30 22:11:12'),
(15309, 2155, 1, 'لم يكن لبنان دولة كاملة السيادة، لأنّ الدستور نظّم السلطات اللبنانية لكنّه لم يُخرجها من تحت سلطة المفوّض السامي. المعطيات (ثلاثة): ظلّ المفوّض السامي عملياً حاكم البلاد الفعلي ورئيس الجمهورية يخضع له؛ من حقّه تعليق الدستور أو تعديله وحلّ المجلس النيابي ونقض التشريعات؛ من حقّه إقالة رئيس الجمهورية والوزراء وتعيين بدلاء منهم وتوقيع المعاهدات والإشراف على السياستين الداخلية والخارجية؛ يمنح الامتيازات للشركات الأجنبية ويعيّن الموظّفين ويقيلهم؛ ظلّ علم البلاد الفرنسي وداخله الأرزة.', 1, '2026-09-30 22:11:12', '2026-09-30 22:11:12'),
(15310, 2155, 2, 'لم يكن لبنان دولة كاملة السيادة، لأنّ الدستور نظّم السلطات اللبنانية لكنّه لم يُخرجها من تحت سلطة المفوّض السامي. المعطيات (ثلاثة): ظلّ المفوّض السامي عملياً حاكم البلاد الفعلي ورئيس الجمهورية يخضع له؛ من حقّه تعليق الدستور أو تعديله وحلّ المجلس النيابي ونقض التشريعات؛ من حقّه إقالة رئيس الجمهورية والوزراء وتعيين بدلاء منهم وتوقيع المعاهدات والإشراف على السياستين الداخلية والخارجية؛ يمنح الامتيازات للشركات الأجنبية ويعيّن الموظّفين ويقيلهم؛ ظلّ علم البلاد الفرنسي وداخله الأرزة.', 1, '2026-09-30 22:11:12', '2026-09-30 22:11:12'),
(15311, 2156, 1, 'يصعب تعريفها لأنّنا ننتسب دائماً إلى حضارة ما نحيا فيها وبها، ولأنّها واسعة ومتنوّعة ومتبدّلة فلا يحيط بها تعريف ضيّق. المعنى اللغوي يربط الحضارة بالمدينة، وبالحضر في مقابل البدو. أمّا المعنى الحديث فأوسع ولا يناقضه: هو مجموع الإنتاج المادّي والروحي، والعلمي والتقني، والفنون والحرف والتقاليد، وأنظمة الحكم وأساليب العيش والسلوك لمجتمع ما أو شعب ما، ولفترة طويلة نسبيّاً، وهو ليس حكراً على أهل المدن.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15312, 2156, 2, 'يصعب تعريفها لأنّنا ننتسب دائماً إلى حضارة ما نحيا فيها وبها، ولأنّها واسعة ومتنوّعة ومتبدّلة فلا يحيط بها تعريف ضيّق. المعنى اللغوي يربط الحضارة بالمدينة، وبالحضر في مقابل البدو. أمّا المعنى الحديث فأوسع ولا يناقضه: هو مجموع الإنتاج المادّي والروحي، والعلمي والتقني، والفنون والحرف والتقاليد، وأنظمة الحكم وأساليب العيش والسلوك لمجتمع ما أو شعب ما، ولفترة طويلة نسبيّاً، وهو ليس حكراً على أهل المدن.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15313, 2157, 1, 'مال الإنسان الأوّل إلى العيش في جماعة لسببين: ضعفه أمام الطبيعة والحيوان، وغريزة فيه تدفعه إلى الاجتماع. وقد مكّنه تماسك الجماعة من البقاء على قيد الحياة، وتوفير حاجات البقاء والتكاثر، ودرء الأخطار.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15314, 2157, 2, 'مال الإنسان الأوّل إلى العيش في جماعة لسببين: ضعفه أمام الطبيعة والحيوان، وغريزة فيه تدفعه إلى الاجتماع. وقد مكّنه تماسك الجماعة من البقاء على قيد الحياة، وتوفير حاجات البقاء والتكاثر، ودرء الأخطار.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15315, 2158, 1, 'المجموعات الأربع: العوامل الطبيعيّة والبيئيّة، والعوامل الاقتصاديّة، والعوامل الفكريّة والروحيّة، والعوامل الاجتماعيّة والسياسيّة. الموارد الطبيعيّة موجودة دائماً، لكنّ الإنسان وحده استطاع استغلالها وتطويرها بالإرادة والذكاء والإبداع وبالعلوم والفلسفات والفنون؛ فالطبيعة شرط مادّي تبقى كما هي ما لم يتوفّر الشرط الإنساني الفكري والروحي والثقافي، ولذلك يرى توينبي أنّ إرادة صنع الحضارة هي التي صنعتها.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15316, 2158, 2, 'المجموعات الأربع: العوامل الطبيعيّة والبيئيّة، والعوامل الاقتصاديّة، والعوامل الفكريّة والروحيّة، والعوامل الاجتماعيّة والسياسيّة. الموارد الطبيعيّة موجودة دائماً، لكنّ الإنسان وحده استطاع استغلالها وتطويرها بالإرادة والذكاء والإبداع وبالعلوم والفلسفات والفنون؛ فالطبيعة شرط مادّي تبقى كما هي ما لم يتوفّر الشرط الإنساني الفكري والروحي والثقافي، ولذلك يرى توينبي أنّ إرادة صنع الحضارة هي التي صنعتها.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15317, 2159, 1, 'من وظائف الدين (يكفي ثلاث): المعرفيّة، والاجتماعيّة، والرمزيّة، والقدسيّة، والسرّيّة. ويرى رانجي هيروا في كتابه «الأنتروبولوجيا والدين» أنّ ما يعبده الإنسان حقيقيّ عنده كالأشياء المادّيّة التي صنعها بيديه، وأنّ الإيمان بكائن مفارق وبخلود النفس يجب أن يُقبلا كحقيقتين؛ كما تؤكّد الممارسات الدينيّة وحدة الجماعة ولحمتها الداخليّة.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15318, 2159, 2, 'من وظائف الدين (يكفي ثلاث): المعرفيّة، والاجتماعيّة، والرمزيّة، والقدسيّة، والسرّيّة. ويرى رانجي هيروا في كتابه «الأنتروبولوجيا والدين» أنّ ما يعبده الإنسان حقيقيّ عنده كالأشياء المادّيّة التي صنعها بيديه، وأنّ الإيمان بكائن مفارق وبخلود النفس يجب أن يُقبلا كحقيقتين؛ كما تؤكّد الممارسات الدينيّة وحدة الجماعة ولحمتها الداخليّة.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15319, 2160, 1, 'لا يقوم السبب في الحضارة نفسها ولا في التقدّم العلمي بحدّ ذاته، بل في جشع بعض ذوي النفوذ الذين يقدّمون مصالحهم الفئويّة، وفي سياسات عاجزة عن الانفتاح والحوار الحرّ، وفي سوء استخدام المنجزات (ومن ذلك إفساد الإنسان للطبيعة وتلويثه إيّاها). والخلاص في الاتّزان والتوازن اللذين عرفتهما الطبيعة، وفي مصالحة الإنسان مع الطبيعة ومع مجتمعه ومع ضميره.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15320, 2160, 2, 'لا يقوم السبب في الحضارة نفسها ولا في التقدّم العلمي بحدّ ذاته، بل في جشع بعض ذوي النفوذ الذين يقدّمون مصالحهم الفئويّة، وفي سياسات عاجزة عن الانفتاح والحوار الحرّ، وفي سوء استخدام المنجزات (ومن ذلك إفساد الإنسان للطبيعة وتلويثه إيّاها). والخلاص في الاتّزان والتوازن اللذين عرفتهما الطبيعة، وفي مصالحة الإنسان مع الطبيعة ومع مجتمعه ومع ضميره.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15321, 2161, 1, 'الإنسان الجامع لطعامه يعيش على ما تقدّمه الطبيعة، فيتنقّل ويلتقط الغذاء ويصطاد، ويسكن الكهوف، وأسرته أموميّة. أمّا الإنسان المنتج لطعامه فيزرع ويدجّن الحيوان، ويستقرّ استقراراً نسبيّاً في الأكواخ والبيوت، ويخزّن طعامه في جلود مخيطة أو في حفر داخل الأرض، وصارت أسرته أبويّة. وسبب التحوّل ذوبان الحزام الجليدي مع اقتراب نهاية العصر الجليدي الرابع وتبدّل المناخ، فصار الحصول على الطعام أصعب، فسعى الإنسان إلى إنتاجه وحفظه.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15322, 2161, 2, 'الإنسان الجامع لطعامه يعيش على ما تقدّمه الطبيعة، فيتنقّل ويلتقط الغذاء ويصطاد، ويسكن الكهوف، وأسرته أموميّة. أمّا الإنسان المنتج لطعامه فيزرع ويدجّن الحيوان، ويستقرّ استقراراً نسبيّاً في الأكواخ والبيوت، ويخزّن طعامه في جلود مخيطة أو في حفر داخل الأرض، وصارت أسرته أبويّة. وسبب التحوّل ذوبان الحزام الجليدي مع اقتراب نهاية العصر الجليدي الرابع وتبدّل المناخ، فصار الحصول على الطعام أصعب، فسعى الإنسان إلى إنتاجه وحفظه.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15323, 2162, 1, 'كانت المنطقة مسرحاً مثاليّاً لتطوّر حضاري واضح: أوّلاً الماء الوفير مع تربة الطمي الخصبة، وهما معاً كانا كافيين لإحداث ثورة زراعيّة (وقد جفّف السكّان المستنقعات وشقّوا الترع، فتحوّلت القرى تدريجاً إلى مدن)، إضافةً إلى وفرة الكلأ واعتدال المناخ. ثانياً الموقع، فالمنطقة ممرّ للهجرات بين الهند ومصر تنتقل عبره الإنجازات التقنيّة والغذائيّة والفنّيّة. وما نقص من موارد بحثوا عنه بالتجارة والمقايضة وأحياناً بالحرب.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15324, 2162, 2, 'كانت المنطقة مسرحاً مثاليّاً لتطوّر حضاري واضح: أوّلاً الماء الوفير مع تربة الطمي الخصبة، وهما معاً كانا كافيين لإحداث ثورة زراعيّة (وقد جفّف السكّان المستنقعات وشقّوا الترع، فتحوّلت القرى تدريجاً إلى مدن)، إضافةً إلى وفرة الكلأ واعتدال المناخ. ثانياً الموقع، فالمنطقة ممرّ للهجرات بين الهند ومصر تنتقل عبره الإنجازات التقنيّة والغذائيّة والفنّيّة. وما نقص من موارد بحثوا عنه بالتجارة والمقايضة وأحياناً بالحرب.', 1, '2026-09-30 22:11:13', '2026-09-30 22:11:13'),
(15325, 2163, 1, '(يكفي ثلاث مع شرح) البحث عن الأنا في القوّة والسلطة والشهرة، فجلجامش ملك جبّار ثلثاه إله وثلثه إنسان يفعل ما يشاء. سؤال الموت الذي طرحه موت صديقه أنكيدو المفاجئ فقلب حياته. البحث عن الخلود (ماء الشباب، نبتة الحياة التي سرقتها أفعى) والانتهاء إلى أنّ الموت لا يُقهر. تأكيد قيم الصداقة والإخلاص والولاء للإله. التعبير عن مخاوف الإنسان ومطامحه في كلّ زمان ومكان، وهو سرّ خلودها.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15326, 2163, 2, '(يكفي ثلاث مع شرح) البحث عن الأنا في القوّة والسلطة والشهرة، فجلجامش ملك جبّار ثلثاه إله وثلثه إنسان يفعل ما يشاء. سؤال الموت الذي طرحه موت صديقه أنكيدو المفاجئ فقلب حياته. البحث عن الخلود (ماء الشباب، نبتة الحياة التي سرقتها أفعى) والانتهاء إلى أنّ الموت لا يُقهر. تأكيد قيم الصداقة والإخلاص والولاء للإله. التعبير عن مخاوف الإنسان ومطامحه في كلّ زمان ومكان، وهو سرّ خلودها.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15327, 2164, 1, 'هذه حضارات متعاقبة بلغت مستوى مدنيّاً متقدّماً. الكتابة: آلاف الألواح الطينيّة المرقّمة والمفهرسة، والمكتبات الكبرى في بابل ونينوى، وأغراض تمتدّ من تسجيل المعاملات والأحكام (إداريّة وقضائيّة) إلى تسجيل السِّيَر والأناشيد والملاحم (دينيّة وأدبيّة). التشريع: قانون حمورابي نظّم البيع والإيجار والإرث والأجور والأحوال الشخصيّة، وكفل حرّيّة الملكيّة والتعاقد. فهذا القانون لا يعكس مجتمعاً بدائيّاً بسيطاً، بل غنى مجتمع بلغ التقدّم والعمران.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15328, 2164, 2, 'هذه حضارات متعاقبة بلغت مستوى مدنيّاً متقدّماً. الكتابة: آلاف الألواح الطينيّة المرقّمة والمفهرسة، والمكتبات الكبرى في بابل ونينوى، وأغراض تمتدّ من تسجيل المعاملات والأحكام (إداريّة وقضائيّة) إلى تسجيل السِّيَر والأناشيد والملاحم (دينيّة وأدبيّة). التشريع: قانون حمورابي نظّم البيع والإيجار والإرث والأجور والأحوال الشخصيّة، وكفل حرّيّة الملكيّة والتعاقد. فهذا القانون لا يعكس مجتمعاً بدائيّاً بسيطاً، بل غنى مجتمع بلغ التقدّم والعمران.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15329, 2165, 1, 'تحتلّ مصر الزاوية الشماليّة الشرقيّة من أفريقيا، ويعبرها النيل من الجنوب إلى الشمال حتّى يصبّ في المتوسّط عبر الدلتا. وهي محاطة بصحراوين قاحلتين: العربيّة شرقاً والليبيّة غرباً، والنيل وحده يصنع شريط الخضرة في الوادي والدلتا. وطمي النيل هو أصل الأرض الخصبة التي قامت عليها الزراعة ثمّ الحضارة؛ فمياه النيل هي التي بعثت الحياة في مصر.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15330, 2165, 2, 'تحتلّ مصر الزاوية الشماليّة الشرقيّة من أفريقيا، ويعبرها النيل من الجنوب إلى الشمال حتّى يصبّ في المتوسّط عبر الدلتا. وهي محاطة بصحراوين قاحلتين: العربيّة شرقاً والليبيّة غرباً، والنيل وحده يصنع شريط الخضرة في الوادي والدلتا. وطمي النيل هو أصل الأرض الخصبة التي قامت عليها الزراعة ثمّ الحضارة؛ فمياه النيل هي التي بعثت الحياة في مصر.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15331, 2166, 1, 'أوّلاً، استقرار البيئة المصريّة، فالتقلّبات الحادّة نادرة. ثانياً، الترتيب الإداري المحكم ومفهوم الدولة المركزيّة الواحدة (الفرعون في القمّة، يليه الوزير، ثمّ الكهنة والقادة والحكّام). ثالثاً، الدين: فالملك ممثّل الإله أو الإله نفسه، وطاعته واجب ديني. رابعاً، الكهنة دعموا الحكم، لكنّهم نافسوا الملك على السلطة الفعليّة (ومجلس الكهنة أهمّ مجالسه)، كما ظهر في مواجهتهم لأخناتون واستعادتهم نفوذهم بعد موته.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15332, 2166, 2, 'أوّلاً، استقرار البيئة المصريّة، فالتقلّبات الحادّة نادرة. ثانياً، الترتيب الإداري المحكم ومفهوم الدولة المركزيّة الواحدة (الفرعون في القمّة، يليه الوزير، ثمّ الكهنة والقادة والحكّام). ثالثاً، الدين: فالملك ممثّل الإله أو الإله نفسه، وطاعته واجب ديني. رابعاً، الكهنة دعموا الحكم، لكنّهم نافسوا الملك على السلطة الفعليّة (ومجلس الكهنة أهمّ مجالسه)، كما ظهر في مواجهتهم لأخناتون واستعادتهم نفوذهم بعد موته.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15333, 2167, 1, 'في الطبّ: اعتقدوا أنّ الروح تعود لزيارة الجثّة فحنّطوها، فتقدّمت معرفتهم بالتشريح والعقاقير وبأعضاء الجسم (عرفوا أهمّيّة القلب واكتشفوا النبض). في الهندسة: كان فيضان النيل يغطّي الحقول بالطمي، فأعادوا تحديدها بعد انحساره، فنشأت مفاهيم الخطّ والزاوية والمساحة، والهندسة في أصلها قياس الأرض. في الفلك: أصلحوا التقويم وقسموا السنة ثلاثة فصول أوّلها الفيضان، وحدّدوا مواعيد أشعّة الشمس واستخدموها في معابدهم ومقابرهم، وابتكروا الساعات الشمسيّة والمائيّة. ولم يستقلّ العلم عندهم تماماً عن الدين والسحر.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15334, 2167, 2, 'في الطبّ: اعتقدوا أنّ الروح تعود لزيارة الجثّة فحنّطوها، فتقدّمت معرفتهم بالتشريح والعقاقير وبأعضاء الجسم (عرفوا أهمّيّة القلب واكتشفوا النبض). في الهندسة: كان فيضان النيل يغطّي الحقول بالطمي، فأعادوا تحديدها بعد انحساره، فنشأت مفاهيم الخطّ والزاوية والمساحة، والهندسة في أصلها قياس الأرض. في الفلك: أصلحوا التقويم وقسموا السنة ثلاثة فصول أوّلها الفيضان، وحدّدوا مواعيد أشعّة الشمس واستخدموها في معابدهم ومقابرهم، وابتكروا الساعات الشمسيّة والمائيّة. ولم يستقلّ العلم عندهم تماماً عن الدين والسحر.', 1, '2026-09-30 22:11:14', '2026-09-30 22:11:14'),
(15335, 2168, 1, 'كانت الكتابة الأولى (المسماريّة والهيروغليفيّة) تعبّر عن الشيء برسمه، فصارت الرموز التصويريّة لا تُحصى. ثمّ خطا الكنعانيّون خطوة نوعيّة نحو الكتابة المقطعيّة بعدد محدود من المقاطع. وجاء الفينيقيّون فأحصوا الرموز الصوتيّة وبسّطوها وخصّوا كلّ رمز بحرف، أي أحلّوا الرموز اللفظيّة مكان التصويريّة، فوُلدت الأبجديّة باثنين وعشرين حرفاً، ثمّ انتشرت غرباً (الإغريق ثمّ اللاتين) وشرقاً (الآراميّون). وأهمّيّتها أنّها سهّلت العلاقات بين البشر، ونقلت التراث، وأحدثت ثورة ثقافيّة، وقد تكون أفضل إسهام قدّمه شعب لسائر الشعوب.', 1, '2026-09-30 22:11:15', '2026-09-30 22:11:15'),
(15336, 2168, 2, 'كانت الكتابة الأولى (المسماريّة والهيروغليفيّة) تعبّر عن الشيء برسمه، فصارت الرموز التصويريّة لا تُحصى. ثمّ خطا الكنعانيّون خطوة نوعيّة نحو الكتابة المقطعيّة بعدد محدود من المقاطع. وجاء الفينيقيّون فأحصوا الرموز الصوتيّة وبسّطوها وخصّوا كلّ رمز بحرف، أي أحلّوا الرموز اللفظيّة مكان التصويريّة، فوُلدت الأبجديّة باثنين وعشرين حرفاً، ثمّ انتشرت غرباً (الإغريق ثمّ اللاتين) وشرقاً (الآراميّون). وأهمّيّتها أنّها سهّلت العلاقات بين البشر، ونقلت التراث، وأحدثت ثورة ثقافيّة، وقد تكون أفضل إسهام قدّمه شعب لسائر الشعوب.', 1, '2026-09-30 22:11:15', '2026-09-30 22:11:15'),
(15337, 2169, 1, 'الخطوة الأولى: الأتمان، وهو جوهر الإنسان، ليس جسمه ولا عقله بل وجود عميق صامت لا يولد ولا يموت. الثانية: البراهمن، وهو روح الوجود، وجود محض لا صفة له ولا صورة ويحوي الموجودات كلّها. الثالثة (أهمّها): الأتمان والبراهمن واحد، فيعود الجزء إلى الكلّ ويندمج فيه. والخلاص تحرّر من التناسخ الذي يحكمه قانون الكارما، بقتل الرغبات والشهوات والتخلّص من الفرديّة، فيعود الجزء إلى الكلّ كما تعود القطرة إلى المحيط.', 1, '2026-09-30 22:11:15', '2026-09-30 22:11:15'),
(15338, 2169, 2, 'الخطوة الأولى: الأتمان، وهو جوهر الإنسان، ليس جسمه ولا عقله بل وجود عميق صامت لا يولد ولا يموت. الثانية: البراهمن، وهو روح الوجود، وجود محض لا صفة له ولا صورة ويحوي الموجودات كلّها. الثالثة (أهمّها): الأتمان والبراهمن واحد، فيعود الجزء إلى الكلّ ويندمج فيه. والخلاص تحرّر من التناسخ الذي يحكمه قانون الكارما، بقتل الرغبات والشهوات والتخلّص من الفرديّة، فيعود الجزء إلى الكلّ كما تعود القطرة إلى المحيط.', 1, '2026-09-30 22:11:15', '2026-09-30 22:11:15'),
(15339, 2170, 1, '(يكفي ثلاث) أوغاريت هي رأس شمرا الحاليّة، ازدهرت منذ الألف الثالث قبل المسيح. عمرانها: شوارع جميلة التخطيط، وبيوت من طابق واحد فوق قبر العائلة. ثقافتها: مكتبات غنيّة، وهياكل لآلهة منها بعل وداغون، ونصوصها تدلّ على تطوّر الكتابة نحو الأبجديّة. تجارتها مع مصر وكريت وقبرص. وقد دمّرتها هجمات شعوب البحر.', 1, '2026-09-30 22:11:15', '2026-09-30 22:11:15'),
(15340, 2170, 2, '(يكفي ثلاث) أوغاريت هي رأس شمرا الحاليّة، ازدهرت منذ الألف الثالث قبل المسيح. عمرانها: شوارع جميلة التخطيط، وبيوت من طابق واحد فوق قبر العائلة. ثقافتها: مكتبات غنيّة، وهياكل لآلهة منها بعل وداغون، ونصوصها تدلّ على تطوّر الكتابة نحو الأبجديّة. تجارتها مع مصر وكريت وقبرص. وقد دمّرتها هجمات شعوب البحر.', 1, '2026-09-30 22:11:15', '2026-09-30 22:11:15'),
(15341, 2171, 1, 'الأصل: استعلاء الآريّين على السكّان الأصليّين منذ دخولهم الهند، ثمّ أعطته الهندوسيّة مشروعيّة دينيّة. الطبقات أربع مغلقة لا يُدخل إليها ولا يُخرج منها، لكلّ منها حقوقها ووظيفتها: البراهمة (الكهنة والمعلّمون والقضاة، وجسم الواحد منهم مقدّس)، ثمّ الجنود الكشاترية (حماة الوطن والدين)، ثمّ الويشية (التجّار والمزارعون)، ثمّ الطبقة الرابعة التي تعيش في التخلّف وتحرّم الطوائف كلّها الاتّصال بها. التبرير في فلسفة التناسخ، إذ ينتقل الإنسان بالولادة الثانية من طبقة إلى أخرى، فيبدو التقسيم عادلاً في نظرهم.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15342, 2171, 2, 'الأصل: استعلاء الآريّين على السكّان الأصليّين منذ دخولهم الهند، ثمّ أعطته الهندوسيّة مشروعيّة دينيّة. الطبقات أربع مغلقة لا يُدخل إليها ولا يُخرج منها، لكلّ منها حقوقها ووظيفتها: البراهمة (الكهنة والمعلّمون والقضاة، وجسم الواحد منهم مقدّس)، ثمّ الجنود الكشاترية (حماة الوطن والدين)، ثمّ الويشية (التجّار والمزارعون)، ثمّ الطبقة الرابعة التي تعيش في التخلّف وتحرّم الطوائف كلّها الاتّصال بها. التبرير في فلسفة التناسخ، إذ ينتقل الإنسان بالولادة الثانية من طبقة إلى أخرى، فيبدو التقسيم عادلاً في نظرهم.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15343, 2172, 1, 'ترتبط أهمّيّة الشعوب بإنجازها الحضاري. فالفينيقيّون لم يتوحّدوا وكانت رقعتهم ضيّقة، ومع ذلك وطّدوا علاقات سلميّة وتجاريّة مع معظم الشعوب من المصريّين إلى البابليّين، وزرعوا مستعمرات مثل قرطاجة. وقدّموا الأبجديّة، وقد تكون أفضل إسهام قدّمه شعب لسائر الشعوب، وأنجبوا أعلاماً مثل زينون مؤسّس الرواقيّة وإقليدس الصوريّ. فحافظوا رغم ضيق رقعتهم على بريق حضاري كبير.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15344, 2172, 2, 'ترتبط أهمّيّة الشعوب بإنجازها الحضاري. فالفينيقيّون لم يتوحّدوا وكانت رقعتهم ضيّقة، ومع ذلك وطّدوا علاقات سلميّة وتجاريّة مع معظم الشعوب من المصريّين إلى البابليّين، وزرعوا مستعمرات مثل قرطاجة. وقدّموا الأبجديّة، وقد تكون أفضل إسهام قدّمه شعب لسائر الشعوب، وأنجبوا أعلاماً مثل زينون مؤسّس الرواقيّة وإقليدس الصوريّ. فحافظوا رغم ضيق رقعتهم على بريق حضاري كبير.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15345, 2173, 1, 'الغاية المشتركة: التحرّر من تكرار المولد بقتل الرغبات والشهوات. الفروق: الطريق الهندوسيّ ينتهي بالاتّحاد بالبراهمن، أمّا الطريق البوذيّ فينتهي بالنرفانا. والطريق الهندوسيّ يمرّ بالتلقّي عن معلّم، أمّا بوذا فرأى أنّ الإنسان قادر بمفرده على بلوغ النرفانا بلا وساطة رجل دين، ونهى عن الهياكل والتماثيل والطقوس وشدّد على المبادئ العالية والأعمال الصالحة.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15346, 2173, 2, 'الغاية المشتركة: التحرّر من تكرار المولد بقتل الرغبات والشهوات. الفروق: الطريق الهندوسيّ ينتهي بالاتّحاد بالبراهمن، أمّا الطريق البوذيّ فينتهي بالنرفانا. والطريق الهندوسيّ يمرّ بالتلقّي عن معلّم، أمّا بوذا فرأى أنّ الإنسان قادر بمفرده على بلوغ النرفانا بلا وساطة رجل دين، ونهى عن الهياكل والتماثيل والطقوس وشدّد على المبادئ العالية والأعمال الصالحة.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15347, 2174, 1, 'تقوم على أنّ أصل العالم هو التضادّ بين النور والظلام، وعلى إلهين متصارعين: أهورا مزدا إله النور والخير، وأهرمان إله الظلام والشرّ. وينتهي الصراع بيوم الحساب وهلاك أهرمان، فتبدأ حياة خالية من الشرور. والإنسان حرّ في اختياره بين الخير والشرّ. وقد أخذت المانويّة عن الزردشتيّة أفكارها المتعلّقة بأصل العالم وثنائيّة النور والظلمة.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15348, 2174, 2, 'تقوم على أنّ أصل العالم هو التضادّ بين النور والظلام، وعلى إلهين متصارعين: أهورا مزدا إله النور والخير، وأهرمان إله الظلام والشرّ. وينتهي الصراع بيوم الحساب وهلاك أهرمان، فتبدأ حياة خالية من الشرور. والإنسان حرّ في اختياره بين الخير والشرّ. وقد أخذت المانويّة عن الزردشتيّة أفكارها المتعلّقة بأصل العالم وثنائيّة النور والظلمة.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15349, 2175, 1, '1) سلطة مطلقة لملك الملوك (الشاهنشاه) ذات شرعيّة دينيّة، فمراسيمه لا تُنقض لأنّها تُعدّ موحاة من أهورا مزدا. 2) حكومة مركزيّة يرأسها كبير الوزراء، وأنظمة متقدّمة في التجارة والضرائب والبريد والطرق. 3) تقسيم الدولة إلى ولايات على كلّ منها حاكم يقدّم حساباً سنويّاً. 4) قضاء هرميّ يحارب الرشوة ويعاقب الراشي والمرتشي بالإعدام، وجيش قائم على خدمة إجباريّة من سنّ الخامسة عشرة حتّى الخمسين.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15350, 2175, 2, '1) سلطة مطلقة لملك الملوك (الشاهنشاه) ذات شرعيّة دينيّة، فمراسيمه لا تُنقض لأنّها تُعدّ موحاة من أهورا مزدا. 2) حكومة مركزيّة يرأسها كبير الوزراء، وأنظمة متقدّمة في التجارة والضرائب والبريد والطرق. 3) تقسيم الدولة إلى ولايات على كلّ منها حاكم يقدّم حساباً سنويّاً. 4) قضاء هرميّ يحارب الرشوة ويعاقب الراشي والمرتشي بالإعدام، وجيش قائم على خدمة إجباريّة من سنّ الخامسة عشرة حتّى الخمسين.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15351, 2176, 1, 'انشغل الفرس بالحرب لكنّهم برزوا في فنّ النقش والعمارة؛ فالقصور والمقابر منذ أيّام قورش وداريوش تكشف اهتماماً كبيراً بالعمارة، كالأدراج الحجريّة والأعمدة المتعدّدة الأشكال. والتوليف أهمّ ما تميّزوا به: جمعوا منجزات معماريّة من حضارات مختلفة وحوّلوها إلى هيئة خاصّة بهم.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15352, 2176, 2, 'انشغل الفرس بالحرب لكنّهم برزوا في فنّ النقش والعمارة؛ فالقصور والمقابر منذ أيّام قورش وداريوش تكشف اهتماماً كبيراً بالعمارة، كالأدراج الحجريّة والأعمدة المتعدّدة الأشكال. والتوليف أهمّ ما تميّزوا به: جمعوا منجزات معماريّة من حضارات مختلفة وحوّلوها إلى هيئة خاصّة بهم.', 1, '2026-09-30 22:11:16', '2026-09-30 22:11:16'),
(15353, 2177, 1, '1) هيرقليطس (منحى العلم الطبيعيّ): الأشياء في تغيّر متّصل، وصراع الأضداد يفضي إلى الحركة، والاستقرار موت وعدم (لا تنزل النهر الواحد مرّتين). 2) برمنيدس: ينكر الحركة، فالعالم ساكن، والتغيّر وهم يزيله العقل؛ الوجود موجود واللاوجود غير موجود. 3) أرسطو (حلّ وسط): كلّ حركة تفترض ثباتاً وتغيّراً معاً، أي ماهيّة ثابتة وأعراضاً تتبدّل، وهي انتقال من القوّة إلى الفعل، والله محرّك أوّل لا يتحرّك. ويمكن ذكر أفلاطون الذي قال بعالمين: عالم المثل الثابت وعالم الظاهر المتغيّر.', 1, '2026-09-30 22:11:17', '2026-09-30 22:11:17'),
(15354, 2177, 2, '1) هيرقليطس (منحى العلم الطبيعيّ): الأشياء في تغيّر متّصل، وصراع الأضداد يفضي إلى الحركة، والاستقرار موت وعدم (لا تنزل النهر الواحد مرّتين). 2) برمنيدس: ينكر الحركة، فالعالم ساكن، والتغيّر وهم يزيله العقل؛ الوجود موجود واللاوجود غير موجود. 3) أرسطو (حلّ وسط): كلّ حركة تفترض ثباتاً وتغيّراً معاً، أي ماهيّة ثابتة وأعراضاً تتبدّل، وهي انتقال من القوّة إلى الفعل، والله محرّك أوّل لا يتحرّك. ويمكن ذكر أفلاطون الذي قال بعالمين: عالم المثل الثابت وعالم الظاهر المتغيّر.', 1, '2026-09-30 22:11:17', '2026-09-30 22:11:17'),
(15355, 2178, 1, '1) المنهج المادّيّ الحسّيّ: الحواسّ مصدر المعرفة؛ طاليس (الأشياء تُعرف بالحسّ) وديموقريطس (الإحساس هو المصدر الوحيد للمعرفة). 2) المنهج الماورائيّ: العقل مصدر المعرفة اليقينيّة؛ برمنيدس (الأشياء واحدة في العقل كثيرة في الحسّ)، وسقراط (نظريّة المفهوم أو الفكرة العامّة)، وأفلاطون (الفكرة هي الوجود الأصليّ والأشياء المرئيّة ظلال لها). 3) المنهج الأرسطيّ: يصل بين التجربة والعلم؛ العقل يدرك الماهيّة والحسّ يدرك الأعراض، ولا شيء يُفهم من غير الإحساس.', 1, '2026-09-30 22:11:17', '2026-09-30 22:11:17'),
(15356, 2178, 2, '1) المنهج المادّيّ الحسّيّ: الحواسّ مصدر المعرفة؛ طاليس (الأشياء تُعرف بالحسّ) وديموقريطس (الإحساس هو المصدر الوحيد للمعرفة). 2) المنهج الماورائيّ: العقل مصدر المعرفة اليقينيّة؛ برمنيدس (الأشياء واحدة في العقل كثيرة في الحسّ)، وسقراط (نظريّة المفهوم أو الفكرة العامّة)، وأفلاطون (الفكرة هي الوجود الأصليّ والأشياء المرئيّة ظلال لها). 3) المنهج الأرسطيّ: يصل بين التجربة والعلم؛ العقل يدرك الماهيّة والحسّ يدرك الأعراض، ولا شيء يُفهم من غير الإحساس.', 1, '2026-09-30 22:11:17', '2026-09-30 22:11:17'),
(15357, 2179, 1, 'سقراط: عمل في حواراته على تخليص محاوريه من العلم الزائف، وحاول معهم بالاستقراء أن يصل إلى حدّ مرضٍ لماهيّة العدالة، مقتنعاً بأنّ العقل يجب أن يسيطر. أفلاطون: العدالة في النفس حين تخضع الشهوانيّة للغضبيّة والغضبيّة للعاقلة، وعدالة سياسيّة تنسّق بين طبقات المدينة الثلاث: الحكّام والجند والشعب. أرسطو: يميّز العدالة التوزيعيّة التي تتولّاها الدولة فتمنح كلّ فرد على قدر فضله، والعدالة التعويضيّة، ثمّ يشير إلى الإنصاف الذي يصحّح عدالة القانون العامّ.', 1, '2026-09-30 22:11:17', '2026-09-30 22:11:17'),
(15358, 2179, 2, 'سقراط: عمل في حواراته على تخليص محاوريه من العلم الزائف، وحاول معهم بالاستقراء أن يصل إلى حدّ مرضٍ لماهيّة العدالة، مقتنعاً بأنّ العقل يجب أن يسيطر. أفلاطون: العدالة في النفس حين تخضع الشهوانيّة للغضبيّة والغضبيّة للعاقلة، وعدالة سياسيّة تنسّق بين طبقات المدينة الثلاث: الحكّام والجند والشعب. أرسطو: يميّز العدالة التوزيعيّة التي تتولّاها الدولة فتمنح كلّ فرد على قدر فضله، والعدالة التعويضيّة، ثمّ يشير إلى الإنصاف الذي يصحّح عدالة القانون العامّ.', 1, '2026-09-30 22:11:17', '2026-09-30 22:11:17'),
(15359, 2180, 1, 'يقول شيشرون إنّ الشريعة الحقيقيّة هي العقل المستقيم، موافقة للطبيعة، منتشرة في الجميع، مستمرّة، أزليّة؛ ليست في روما غير ما هي في أثينا، ولا الآن غير ما تكون فيما بعد، بل شريعة واحدة أزليّة لا متغيّرة لجميع الشعوب وفي كلّ زمان. وهي فكرة الشريعة الطبيعيّة التي أدخلتها الرواقيّة إلى المجال القانونيّ، والرواقيّة غذّت فكرة الأخوّة الإنسانيّة. والعبارة خاطئة، لأنّ الشريعة منتشرة في الجميع، وهي واحدة لجميع الشعوب وفي كلّ زمان.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15360, 2180, 2, 'يقول شيشرون إنّ الشريعة الحقيقيّة هي العقل المستقيم، موافقة للطبيعة، منتشرة في الجميع، مستمرّة، أزليّة؛ ليست في روما غير ما هي في أثينا، ولا الآن غير ما تكون فيما بعد، بل شريعة واحدة أزليّة لا متغيّرة لجميع الشعوب وفي كلّ زمان. وهي فكرة الشريعة الطبيعيّة التي أدخلتها الرواقيّة إلى المجال القانونيّ، والرواقيّة غذّت فكرة الأخوّة الإنسانيّة. والعبارة خاطئة، لأنّ الشريعة منتشرة في الجميع، وهي واحدة لجميع الشعوب وفي كلّ زمان.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15361, 2181, 1, '1) مركز النشاطات العامّة الرسميّة، وقربه قاعات مجلس الشيوخ والشعب. 2) مركز المبادلات التجاريّة. 3) مركز الطقوس الدينيّة، وأرضه مقدّسة بذكريات الأبطال وحضور الآلهة. ويمكن إضافة أنّ هندسته تطوّرت فأُضيفت الأروقة ثمّ البازيليك، وفيها تجري المعاملات التجاريّة والقضائيّة أيّام الشتاء.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15362, 2181, 2, '1) مركز النشاطات العامّة الرسميّة، وقربه قاعات مجلس الشيوخ والشعب. 2) مركز المبادلات التجاريّة. 3) مركز الطقوس الدينيّة، وأرضه مقدّسة بذكريات الأبطال وحضور الآلهة. ويمكن إضافة أنّ هندسته تطوّرت فأُضيفت الأروقة ثمّ البازيليك، وفيها تجري المعاملات التجاريّة والقضائيّة أيّام الشتاء.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15363, 2182, 1, 'إنجيل اختصار للّفظة اليونانيّة إيفانجيليوم، وتعني البشارة الطيّبة. واختلفت التأكيدات لأنّ كلّ كاتب خاطب جماعة مختلفة: متّى خاطب المتنصّرين من اليهود واليونانيّين في سوريا فقدّم يسوع موسى جديداً، ولوقا خاطب الوثنيّين واليونانيّين فقدّمه ابن الله الداعي جميع البشر إلى البنوّة الإلهيّة، ويوحنّا قدّمه اللوغس، كلمة الله. وقد تفاعل الكتّاب مع ثقافات مخاطَبيهم، مع حفظ الأمانة في نقل البشارة.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15364, 2182, 2, 'إنجيل اختصار للّفظة اليونانيّة إيفانجيليوم، وتعني البشارة الطيّبة. واختلفت التأكيدات لأنّ كلّ كاتب خاطب جماعة مختلفة: متّى خاطب المتنصّرين من اليهود واليونانيّين في سوريا فقدّم يسوع موسى جديداً، ولوقا خاطب الوثنيّين واليونانيّين فقدّمه ابن الله الداعي جميع البشر إلى البنوّة الإلهيّة، ويوحنّا قدّمه اللوغس، كلمة الله. وقد تفاعل الكتّاب مع ثقافات مخاطَبيهم، مع حفظ الأمانة في نقل البشارة.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15365, 2183, 1, 'كان الرومان من السبّاقين إلى رفض السلطة الوراثيّة حتّى في عهد الملكيّة. فحين حاول تركان المتكبّر أن يستبدّ قلبوا الحكم، فطردوا الملك وأنشأوا الجمهوريّة. ووزّعت الجمهوريّة السلطة بين حاكمين منتخبين كلّ سنة، وأعطت الشعب الفقير حقّ انتخاب من يدافع عن مصالحه. وحين صار يوليوس قيصر سيّد روما المطلق، دفع الخوف من العودة إلى السلطة المطلقة بروتوس وكاسيوس إلى التآمر عليه.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15366, 2183, 2, 'كان الرومان من السبّاقين إلى رفض السلطة الوراثيّة حتّى في عهد الملكيّة. فحين حاول تركان المتكبّر أن يستبدّ قلبوا الحكم، فطردوا الملك وأنشأوا الجمهوريّة. ووزّعت الجمهوريّة السلطة بين حاكمين منتخبين كلّ سنة، وأعطت الشعب الفقير حقّ انتخاب من يدافع عن مصالحه. وحين صار يوليوس قيصر سيّد روما المطلق، دفع الخوف من العودة إلى السلطة المطلقة بروتوس وكاسيوس إلى التآمر عليه.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15367, 2184, 1, '1) انحصرت اليهوديّة والديانة الرومانيّة التقليديّة في طقوس بلا قناعات داخليّة (هيكل أورشليم الذي وصفه يسوع بأنّه مغارة لصوص، وطقوس رومانيّة خارجيّة صارمة أهملها أكثر الشعب). 2) رأى أكثر الناس أنّ الفلسفات تخاطب العقل وتهمل العاطفة، وأنّ الحتميّة تخنق الخيال. 3) لجأ كثيرون إلى التنجيم، فربطوا حوادث الأرض بحركات النجوم. 4) أقبل الناس على ديانات الشرق الخلاصيّة التي تُعدّ طقوسها موتاً رمزيّاً تعقبه ولادة روحيّة جديدة، وعلى الغنوصيّة.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15368, 2184, 2, '1) انحصرت اليهوديّة والديانة الرومانيّة التقليديّة في طقوس بلا قناعات داخليّة (هيكل أورشليم الذي وصفه يسوع بأنّه مغارة لصوص، وطقوس رومانيّة خارجيّة صارمة أهملها أكثر الشعب). 2) رأى أكثر الناس أنّ الفلسفات تخاطب العقل وتهمل العاطفة، وأنّ الحتميّة تخنق الخيال. 3) لجأ كثيرون إلى التنجيم، فربطوا حوادث الأرض بحركات النجوم. 4) أقبل الناس على ديانات الشرق الخلاصيّة التي تُعدّ طقوسها موتاً رمزيّاً تعقبه ولادة روحيّة جديدة، وعلى الغنوصيّة.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15369, 2185, 1, 'الإنسان متقلّب في سلوكه، ومرتبط بالشرّ والخطيئة والألم. والمسيح يُدخل الغفران إلى حياته فيخلّصه من العبوديّة للشرّ، ويُدخله إلى المشاركة مع حياة الله. فيصير الألم فداءً، وتُقاد الحياة الإنسانيّة إلى الخلاص، ومن يسلك طريق الإيمان يبلغ الحياة الخالدة والقيامة الشخصيّة جسداً وروحاً معاً.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15370, 2185, 2, 'الإنسان متقلّب في سلوكه، ومرتبط بالشرّ والخطيئة والألم. والمسيح يُدخل الغفران إلى حياته فيخلّصه من العبوديّة للشرّ، ويُدخله إلى المشاركة مع حياة الله. فيصير الألم فداءً، وتُقاد الحياة الإنسانيّة إلى الخلاص، ومن يسلك طريق الإيمان يبلغ الحياة الخالدة والقيامة الشخصيّة جسداً وروحاً معاً.', 1, '2026-09-30 22:11:18', '2026-09-30 22:11:18'),
(15371, 2186, 1, 'في المنطق العاديّ يقوم السلام على العدالة، فيؤدّي كلّ فرد واجباته وينال حقوقه. أمّا في المنطق المسيحيّ فيتخطّى السلام المعاملة بالمثل، ويقوم على الصفح (سبعين مرّة سبع مرّات) والمحبّة التي تمتدّ حتّى إلى الأعداء؛ ولا تكتمل المصالحة مع الله ما لم تقترن بالمصالحة مع الآخرين.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15372, 2186, 2, 'في المنطق العاديّ يقوم السلام على العدالة، فيؤدّي كلّ فرد واجباته وينال حقوقه. أمّا في المنطق المسيحيّ فيتخطّى السلام المعاملة بالمثل، ويقوم على الصفح (سبعين مرّة سبع مرّات) والمحبّة التي تمتدّ حتّى إلى الأعداء؛ ولا تكتمل المصالحة مع الله ما لم تقترن بالمصالحة مع الآخرين.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15373, 2187, 1, 'النسك ليس وقفاً على المسيحيّة، فقد عرفته ديانات وتيّارات قبلها، مثل الآسينيّين ضمن اليهوديّة، وجماعات الصوفيّين الزهّاد في الهند، والمانويّة، والأفلاطونيّة والرواقيّة. أمّا خصوصيّة النسك المسيحيّ فهي أنّ مثاله الأوّل والأخير هو شخص المسيح، ودعوته إلى الزهد ترافقت مع تحرّر من الشريعة لا مع التزمّت.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15374, 2187, 2, 'النسك ليس وقفاً على المسيحيّة، فقد عرفته ديانات وتيّارات قبلها، مثل الآسينيّين ضمن اليهوديّة، وجماعات الصوفيّين الزهّاد في الهند، والمانويّة، والأفلاطونيّة والرواقيّة. أمّا خصوصيّة النسك المسيحيّ فهي أنّ مثاله الأوّل والأخير هو شخص المسيح، ودعوته إلى الزهد ترافقت مع تحرّر من الشريعة لا مع التزمّت.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15375, 2188, 1, 'في التقليد الأفلاطونيّ الجسد سجن للنفس، وعليها أن تتحرّر منه وتتطهّر. أمّا في المسيحيّة فالإنسان كائن واحد: أخذ الله تراباً وماءً ثمّ نفخ فيهما روحاً على صورته ومثاله؛ لذلك نجد في الإنسان منطقين، منطق الروح ومنطق الجسد، وقد يتواجهان أو يتكاملان.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15376, 2188, 2, 'في التقليد الأفلاطونيّ الجسد سجن للنفس، وعليها أن تتحرّر منه وتتطهّر. أمّا في المسيحيّة فالإنسان كائن واحد: أخذ الله تراباً وماءً ثمّ نفخ فيهما روحاً على صورته ومثاله؛ لذلك نجد في الإنسان منطقين، منطق الروح ومنطق الجسد، وقد يتواجهان أو يتكاملان.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15377, 2189, 1, 'حرّيّة الروح هي التحرّر من الخطيئة (الخلاص عبور من الخطيئة إلى الحرّيّة)، وهي امتلاك للذات وسيادة على أهوائها هدفها صنع الخير، ولا حرّيّة بدون معرفة. أمّا الحرّيّة العمليّة فأساسها صورة الله في الإنسان، ومن أمثلتها أنّ المسيحيّين الأوائل تجرّدوا عن المادّة فكانوا يشتركون في ما يملكون، وتحرّروا من العصبيّة فاختلطوا بالأمم (ومن حرفيّة الشريعة، ومن البغض حتّى تجاه الأعداء).', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15378, 2189, 2, 'حرّيّة الروح هي التحرّر من الخطيئة (الخلاص عبور من الخطيئة إلى الحرّيّة)، وهي امتلاك للذات وسيادة على أهوائها هدفها صنع الخير، ولا حرّيّة بدون معرفة. أمّا الحرّيّة العمليّة فأساسها صورة الله في الإنسان، ومن أمثلتها أنّ المسيحيّين الأوائل تجرّدوا عن المادّة فكانوا يشتركون في ما يملكون، وتحرّروا من العصبيّة فاختلطوا بالأمم (ومن حرفيّة الشريعة، ومن البغض حتّى تجاه الأعداء).', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15379, 2190, 1, 'المسيحيّون الأوائل رفضوا الإكراه في المعتقد وتحمّلوا الاضطهادات المنظّمة، لكنّهم بعد نيل حرّيّة المعتقد مع قسطنطين في إعلان ميلان دبّت بينهم الخلافات وخاضوا حروباً دُعيت بالحروب الدينيّة، ومارس بعضهم الإكراه على الآخرين. هذه أخطاء أشخاص لا تجيزها المبادئ المسيحيّة، لذلك نفرّق بين المسيحيّة والمسيحيّين.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15380, 2190, 2, 'المسيحيّون الأوائل رفضوا الإكراه في المعتقد وتحمّلوا الاضطهادات المنظّمة، لكنّهم بعد نيل حرّيّة المعتقد مع قسطنطين في إعلان ميلان دبّت بينهم الخلافات وخاضوا حروباً دُعيت بالحروب الدينيّة، ومارس بعضهم الإكراه على الآخرين. هذه أخطاء أشخاص لا تجيزها المبادئ المسيحيّة، لذلك نفرّق بين المسيحيّة والمسيحيّين.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15381, 2191, 1, 'الدور الأساسيّ للرهبان تبشير الأرياف، فقام الراهب بدور المبشّر والمرشد الحكيم والطبيب والمعلّم المربّي والحرفيّ والزراعيّ، وتكوّنت القرى حول التنظيمات الرهبانيّة في الشرق والغرب. واليوم يبني الرهبان الكنائس والأديرة، ويساعدون كهنة الرعايا، ويقدّمون خدمات في كلّ الحقول، وما زالوا أحد الوجوه الأساسيّة للمسيحيّة.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15382, 2191, 2, 'الدور الأساسيّ للرهبان تبشير الأرياف، فقام الراهب بدور المبشّر والمرشد الحكيم والطبيب والمعلّم المربّي والحرفيّ والزراعيّ، وتكوّنت القرى حول التنظيمات الرهبانيّة في الشرق والغرب. واليوم يبني الرهبان الكنائس والأديرة، ويساعدون كهنة الرعايا، ويقدّمون خدمات في كلّ الحقول، وما زالوا أحد الوجوه الأساسيّة للمسيحيّة.', 1, '2026-09-30 22:11:19', '2026-09-30 22:11:19'),
(15383, 2192, 1, 'النفس الروحيّة هي أوّل حقيقة يدركها الإنسان، والعلاقة بينها وبين الله ضروريّة ومباشرة ومستمرّة. النور الإلهيّ هو أنّ النفس العاقلة تتلقّى معرفتها بنور من الله، وتستمدّ وجودها من وجوده. والطريقان: في عمق الأنا، بالعودة إلى الذات حتى ينابيع الوعي وجذور الوجود؛ وفي الكون، بالتأمّل في تدرّج المخلوقات وجمالها (فتجيب الكائنات: لسنا إلهك، هو الذي صنعنا).', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15384, 2192, 2, 'النفس الروحيّة هي أوّل حقيقة يدركها الإنسان، والعلاقة بينها وبين الله ضروريّة ومباشرة ومستمرّة. النور الإلهيّ هو أنّ النفس العاقلة تتلقّى معرفتها بنور من الله، وتستمدّ وجودها من وجوده. والطريقان: في عمق الأنا، بالعودة إلى الذات حتى ينابيع الوعي وجذور الوجود؛ وفي الكون، بالتأمّل في تدرّج المخلوقات وجمالها (فتجيب الكائنات: لسنا إلهك، هو الذي صنعنا).', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15385, 2193, 1, 'يبقى الإنسان حرّاً ومسؤولاً. ففي رواية الخلق منع الله الإنسان، ووعده بالسعادة، وتوعّده بالعقاب، وهذا يعني أنّه حرّ ومسؤول. ومعرفة الله المسبقة ليست جبراً: فالله يريد الأفعال الصالحة ولا يريد الشرّيرة، بل يسمح بالسلوك الحرّ. ويسمح الله بالشرّ لأنّه يعرف أن يجعله خادماً للخير.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15386, 2193, 2, 'يبقى الإنسان حرّاً ومسؤولاً. ففي رواية الخلق منع الله الإنسان، ووعده بالسعادة، وتوعّده بالعقاب، وهذا يعني أنّه حرّ ومسؤول. ومعرفة الله المسبقة ليست جبراً: فالله يريد الأفعال الصالحة ولا يريد الشرّيرة، بل يسمح بالسلوك الحرّ. ويسمح الله بالشرّ لأنّه يعرف أن يجعله خادماً للخير.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15387, 2194, 1, 'الحبّ رباط الجماعة، وحبّان بنيا مدينتين: المدينة الأرضيّة بناها حبّ الذات حتى الازدراء بالله، وهدفها إنسانيّ فقط، وقد يقوم سلامها على قواعد خاطئة حين يحتلّ الحاكم المستبدّ مكان الله. والمدينة السماويّة بناها حبّ الله حتى الازدراء بالذات، وهي تصون الحرّيّات وتطلب الخير العامّ. تلتقي المدينتان في طلب السلام. والدولة لا تساوي المدينة الأرضيّة بل تحتضن المدينتين، ولا يجوز اللجوء إلى المقاومة العنيفة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15388, 2194, 2, 'الحبّ رباط الجماعة، وحبّان بنيا مدينتين: المدينة الأرضيّة بناها حبّ الذات حتى الازدراء بالله، وهدفها إنسانيّ فقط، وقد يقوم سلامها على قواعد خاطئة حين يحتلّ الحاكم المستبدّ مكان الله. والمدينة السماويّة بناها حبّ الله حتى الازدراء بالذات، وهي تصون الحرّيّات وتطلب الخير العامّ. تلتقي المدينتان في طلب السلام. والدولة لا تساوي المدينة الأرضيّة بل تحتضن المدينتين، ولا يجوز اللجوء إلى المقاومة العنيفة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15389, 2195, 1, 'دينيّاً: وثنيّة وديانات متعدّدة ومتباينة، ولكلّ قبيلة صنم. اجتماعيّاً وسياسيّاً: تناحر قبليّ وتشرذم سياسيّ، وجهالة وفوضى وخرافات وظلم، والقويّ يأكل الضعيف. ومن المنكرات: القتل والسلب والميسر (القمار) والزنى والخمر ووأد البنات، أي قتلهنّ خوفاً من الفقر والعار.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15390, 2195, 2, 'دينيّاً: وثنيّة وديانات متعدّدة ومتباينة، ولكلّ قبيلة صنم. اجتماعيّاً وسياسيّاً: تناحر قبليّ وتشرذم سياسيّ، وجهالة وفوضى وخرافات وظلم، والقويّ يأكل الضعيف. ومن المنكرات: القتل والسلب والميسر (القمار) والزنى والخمر ووأد البنات، أي قتلهنّ خوفاً من الفقر والعار.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15391, 2196, 1, 'جعل النبيّ إتمام مكارم الأخلاق غاية بعثته («بُعثت لأتمّم مكارم الأخلاق»)، وتوالت الآيات تأمر بالعدل والإحسان وإيتاء ذي القربى وتنهى عن الفحشاء والمنكر والبغي، فحرص المسلمون الأوائل على أخلاق الإسلام حرصهم على معتقداته، وطالبهم الإسلام بمحاسبة أنفسهم وحذّرهم من النفاق. ومن علاماته: إذا حدّث كذب، وإذا وعد أخلف (وإذا اؤتمن خان، وإذا خاصم فجر).', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15392, 2196, 2, 'جعل النبيّ إتمام مكارم الأخلاق غاية بعثته («بُعثت لأتمّم مكارم الأخلاق»)، وتوالت الآيات تأمر بالعدل والإحسان وإيتاء ذي القربى وتنهى عن الفحشاء والمنكر والبغي، فحرص المسلمون الأوائل على أخلاق الإسلام حرصهم على معتقداته، وطالبهم الإسلام بمحاسبة أنفسهم وحذّرهم من النفاق. ومن علاماته: إذا حدّث كذب، وإذا وعد أخلف (وإذا اؤتمن خان، وإذا خاصم فجر).', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15393, 2197, 1, 'قبل الإسلام كانت القبيلة إطار الجماعة وشريعة الصحراء، وكان الإنسان يملك إنساناً آخر خارج أيّ قانون فقد يعذّبه أو يقتله. بعد الإسلام صارت الأمّة إطاراً جامعاً للتنوّعات العرقيّة والطبقيّة، وصار الناس سواسية في الإنسانيّة كأسنان المشط وفي الحقوق والواجبات، وأكّدت العبادات الجماعيّة هذا البعد. والتسامح شمل المعاملات والمعتقد نفسه («لا إكراه في الدين»)، وغنى الحوار مع المذاهب والأفكار الأخرى كان جزءاً من أسباب وصول الإسلام إلى الصين شرقاً والمغرب والأندلس غرباً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15394, 2197, 2, 'قبل الإسلام كانت القبيلة إطار الجماعة وشريعة الصحراء، وكان الإنسان يملك إنساناً آخر خارج أيّ قانون فقد يعذّبه أو يقتله. بعد الإسلام صارت الأمّة إطاراً جامعاً للتنوّعات العرقيّة والطبقيّة، وصار الناس سواسية في الإنسانيّة كأسنان المشط وفي الحقوق والواجبات، وأكّدت العبادات الجماعيّة هذا البعد. والتسامح شمل المعاملات والمعتقد نفسه («لا إكراه في الدين»)، وغنى الحوار مع المذاهب والأفكار الأخرى كان جزءاً من أسباب وصول الإسلام إلى الصين شرقاً والمغرب والأندلس غرباً.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15395, 2198, 1, 'التعريف من زاوية الآخر (ابن خلدون والتهانوي) غايته إثبات العقائد الدينيّة على الغير بإيراد الحجج ودفع الشُّبَه، ومسلّمته أنّ المسلم لا تقلقه الشكوك. لكنّ الغزالي رأى أنّ الشكّ قد يصيب وجدان المؤمن فوجّه العوامّ إلى علم الكلام؛ لذلك يُعرَّف أيضاً من زاوية الأنا بأنّه صياغة المعتقدات الإسلاميّة في منظومة فكريّة تستمدّ عناصرها من النصّ القرآنيّ وتؤلّف بينها بمعقول يحكمه غالباً المنطق الأرسطيّ.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15396, 2198, 2, 'التعريف من زاوية الآخر (ابن خلدون والتهانوي) غايته إثبات العقائد الدينيّة على الغير بإيراد الحجج ودفع الشُّبَه، ومسلّمته أنّ المسلم لا تقلقه الشكوك. لكنّ الغزالي رأى أنّ الشكّ قد يصيب وجدان المؤمن فوجّه العوامّ إلى علم الكلام؛ لذلك يُعرَّف أيضاً من زاوية الأنا بأنّه صياغة المعتقدات الإسلاميّة في منظومة فكريّة تستمدّ عناصرها من النصّ القرآنيّ وتؤلّف بينها بمعقول يحكمه غالباً المنطق الأرسطيّ.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15397, 2199, 1, 'علم أصول الفقه علمٌ يُستنبَط بواسطة أصوله وقواعده حكمُ الشريعة في فعلٍ محدّد، فهو يضبط الأدلّة الشرعيّة وكيفيّة الاستدلال بها. في القرن الأوّل الهجريّ كان النبيّ يفتي ويقضي بما يوحى إليه، وأفتى الصحابة بملكتهم العربيّة السليمة. لكن حين اختلط العرب المسلمون بغيرهم وتغيّرت الظروف مكاناً وزماناً ظهرت الحاجة إلى قواعد وأصول، ومن هذه الضوابط تكوّن علم أصول الفقه.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15398, 2199, 2, 'علم أصول الفقه علمٌ يُستنبَط بواسطة أصوله وقواعده حكمُ الشريعة في فعلٍ محدّد، فهو يضبط الأدلّة الشرعيّة وكيفيّة الاستدلال بها. في القرن الأوّل الهجريّ كان النبيّ يفتي ويقضي بما يوحى إليه، وأفتى الصحابة بملكتهم العربيّة السليمة. لكن حين اختلط العرب المسلمون بغيرهم وتغيّرت الظروف مكاناً وزماناً ظهرت الحاجة إلى قواعد وأصول، ومن هذه الضوابط تكوّن علم أصول الفقه.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15399, 2200, 1, 'العوامل الداخليّة: أساليب القرآن بين المحكم والمتشابه (آيات تنزّه الله وآيات توهم التشبيه)، والخلاف السياسيّ حول الخلافة وشرعيّة الحكم، ومسألة المعاصي ومرتكب الكبيرة. العوامل الخارجيّة: حوار المسلمين مع علماء الأديان الذي أظهر دور الآخر في بناء الذات، وحركة التعريب عن اليونانيّة وانتفاع المتكلّمين بالمنطق والفلسفة اليونانيّة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15400, 2200, 2, 'العوامل الداخليّة: أساليب القرآن بين المحكم والمتشابه (آيات تنزّه الله وآيات توهم التشبيه)، والخلاف السياسيّ حول الخلافة وشرعيّة الحكم، ومسألة المعاصي ومرتكب الكبيرة. العوامل الخارجيّة: حوار المسلمين مع علماء الأديان الذي أظهر دور الآخر في بناء الذات، وحركة التعريب عن اليونانيّة وانتفاع المتكلّمين بالمنطق والفلسفة اليونانيّة.', 1, '2026-09-30 22:11:21', '2026-09-30 22:11:21'),
(15401, 2201, 1, 'المعيار هو صيغة الطلب ووجود العقوبة. المحرّم نهيٌ قطعيّ وعلى فاعله عقوبة، مثل السرقة والقتل، أمّا المكروه فنهيٌ بصيغة غير قطعيّة ولا عقاب عليه. الواجب طلبٌ محتَّم يُعاقَب تاركه، مثل الصلاة وبرّ الوالدين، أمّا المندوب فطلبٌ بغير إلزام، فتاركه لا يُعاقَب لكنّه قد يُلام، مثل الأمر بكتابة الدَّين إلى أجلٍ مسمّى.', 1, '2026-09-30 22:11:22', '2026-09-30 22:11:22'),
(15402, 2201, 2, 'المعيار هو صيغة الطلب ووجود العقوبة. المحرّم نهيٌ قطعيّ وعلى فاعله عقوبة، مثل السرقة والقتل، أمّا المكروه فنهيٌ بصيغة غير قطعيّة ولا عقاب عليه. الواجب طلبٌ محتَّم يُعاقَب تاركه، مثل الصلاة وبرّ الوالدين، أمّا المندوب فطلبٌ بغير إلزام، فتاركه لا يُعاقَب لكنّه قد يُلام، مثل الأمر بكتابة الدَّين إلى أجلٍ مسمّى.', 1, '2026-09-30 22:11:22', '2026-09-30 22:11:22'),
(15403, 2202, 1, 'آمن المسلمون الأوائل بالقضاء والقدر دون جدال. ثمّ قالت القدريّة (معبد الجهني وغيلان) إنّ الإنسان مخيَّر ومسؤول مستدلّة بآيات ظاهرها التخيير، وردّت الجبريّة (جهم بن صفوان) بأنّ الإنسان مجبور مستدلّة بآيات ظاهرها التسيير. وتمسّكت المعتزلة بحرّيّة الإرادة لأنّ الجبر يناقض العدل الإلهيّ والحرّيّة تفسّر وجود الشرّ، ولو كان الإنسان مجبراً لفقدت التكاليف معناها ولاستوى الكفر والإيمان. ووقف الأشعري وسطاً بنظريّة الكسب: الإنسان حرّ في اختيار أفعاله الإراديّة لكنّه لا يملك القدرة على إتيانها، ومع ذلك هو مسؤول عمّا اختار.', 1, '2026-09-30 22:11:22', '2026-09-30 22:11:22'),
(15404, 2202, 2, 'آمن المسلمون الأوائل بالقضاء والقدر دون جدال. ثمّ قالت القدريّة (معبد الجهني وغيلان) إنّ الإنسان مخيَّر ومسؤول مستدلّة بآيات ظاهرها التخيير، وردّت الجبريّة (جهم بن صفوان) بأنّ الإنسان مجبور مستدلّة بآيات ظاهرها التسيير. وتمسّكت المعتزلة بحرّيّة الإرادة لأنّ الجبر يناقض العدل الإلهيّ والحرّيّة تفسّر وجود الشرّ، ولو كان الإنسان مجبراً لفقدت التكاليف معناها ولاستوى الكفر والإيمان. ووقف الأشعري وسطاً بنظريّة الكسب: الإنسان حرّ في اختيار أفعاله الإراديّة لكنّه لا يملك القدرة على إتيانها، ومع ذلك هو مسؤول عمّا اختار.', 1, '2026-09-30 22:11:22', '2026-09-30 22:11:22'),
(15405, 2203, 1, 'الضروريّات الخمس: الدين، والنفس، والعقل، والنسل، والمال. فالشريعة وُضعت لمصالح العباد. مثال: حمى الإسلام المال بحماية الملكيّة الفرديّة ومنع السرقة والرشوة والربا والحضّ على توزيع المال بالعدل (أو: حمى العقل بكفالة حريّة الفكر وحمايته من الإسكار والتخدير...). وقد قال الغزالي في «المستصفى»: كلّ ما يفوّت هذه الأصول الخمسة فهو مفسدة ودفعها مصلحة.', 1, '2026-09-30 22:11:22', '2026-09-30 22:11:22'),
(15406, 2203, 2, 'الضروريّات الخمس: الدين، والنفس، والعقل، والنسل، والمال. فالشريعة وُضعت لمصالح العباد. مثال: حمى الإسلام المال بحماية الملكيّة الفرديّة ومنع السرقة والرشوة والربا والحضّ على توزيع المال بالعدل (أو: حمى العقل بكفالة حريّة الفكر وحمايته من الإسكار والتخدير...). وقد قال الغزالي في «المستصفى»: كلّ ما يفوّت هذه الأصول الخمسة فهو مفسدة ودفعها مصلحة.', 1, '2026-09-30 22:11:22', '2026-09-30 22:11:22'),
(15407, 2204, 1, 'من الآراء: أنّه من الصفاء، أو المصافاة، أو الصفوة، أو أهل الصفّة، أو الصفّ الأوّل، أو صوفة، أو من سوفيا اليونانيّة أي الحكمة (وقد رُدّ لأنّ السين اليونانيّة تُكتب في العربيّة سيناً لا صاداً). الراجح أنّه من لبس الصوف: تصوّف إذا لبس الصوف كما يقال تقمّص إذا لبس القميص؛ لأنّ الصوف كان شعار المتنسّكين، والتسمية بظاهر اللباس مألوفة، كما سمّى القرآن أصحاب عيسى بالحواريّين لأنّهم كانوا يلبسون البياض.', 1, '2026-09-30 22:11:26', '2026-09-30 22:11:26'),
(15408, 2204, 2, 'من الآراء: أنّه من الصفاء، أو المصافاة، أو الصفوة، أو أهل الصفّة، أو الصفّ الأوّل، أو صوفة، أو من سوفيا اليونانيّة أي الحكمة (وقد رُدّ لأنّ السين اليونانيّة تُكتب في العربيّة سيناً لا صاداً). الراجح أنّه من لبس الصوف: تصوّف إذا لبس الصوف كما يقال تقمّص إذا لبس القميص؛ لأنّ الصوف كان شعار المتنسّكين، والتسمية بظاهر اللباس مألوفة، كما سمّى القرآن أصحاب عيسى بالحواريّين لأنّهم كانوا يلبسون البياض.', 1, '2026-09-30 22:11:26', '2026-09-30 22:11:26'),
(15409, 2205, 1, 'في تيّار المعاملات موضوع التجربة ذات الإنسان بالرياضة والمجاهدة؛ وقد قسم الغزالي علوم طريق الآخرة إلى علم المعاملة وعلم المكاشفة، وجعل المعاملة فرض عين على كلّ مسلم وطريقاً إلى المكاشفة، فوفّق بين الفقه والتصوّف. أمّا في تيّار المشاهدات فيتّسع موضوع المكاشفة ليشمل الكون كلّه؛ وقال ابن عربي بوحدة وجود إسلاميّة: الوجود الحقيقي لله وحده وكلّ ما عداه يحتاج إلى موجده في كلّ لحظة، وهي وحدة لا تقبل الاتّحاد ولا الحلول.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15410, 2205, 2, 'في تيّار المعاملات موضوع التجربة ذات الإنسان بالرياضة والمجاهدة؛ وقد قسم الغزالي علوم طريق الآخرة إلى علم المعاملة وعلم المكاشفة، وجعل المعاملة فرض عين على كلّ مسلم وطريقاً إلى المكاشفة، فوفّق بين الفقه والتصوّف. أمّا في تيّار المشاهدات فيتّسع موضوع المكاشفة ليشمل الكون كلّه؛ وقال ابن عربي بوحدة وجود إسلاميّة: الوجود الحقيقي لله وحده وكلّ ما عداه يحتاج إلى موجده في كلّ لحظة، وهي وحدة لا تقبل الاتّحاد ولا الحلول.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15411, 2206, 1, 'الشطح حركة أسرار الواجدين إذا قوي وجدهم، ويشبّهه السرّاج الطوسي بالماء الكثير يجري في نهر ضيّق فيفيض من حافّتيه. يرى الغزالي أنّ الشاطحين استغرقوا في الواحد فسكروا سكراً دفع سلطان عقولهم، وكلام العشّاق في حال السكر يُطوى ولا يُحكى؛ فلمّا عادوا إلى سلطان العقل عرفوا أنّ ذلك ليس اتّحاداً حقيقيّاً بل شبه اتّحاد، مثل قول العاشق: أنا من أهوى ومن أهوى أنا.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15412, 2206, 2, 'الشطح حركة أسرار الواجدين إذا قوي وجدهم، ويشبّهه السرّاج الطوسي بالماء الكثير يجري في نهر ضيّق فيفيض من حافّتيه. يرى الغزالي أنّ الشاطحين استغرقوا في الواحد فسكروا سكراً دفع سلطان عقولهم، وكلام العشّاق في حال السكر يُطوى ولا يُحكى؛ فلمّا عادوا إلى سلطان العقل عرفوا أنّ ذلك ليس اتّحاداً حقيقيّاً بل شبه اتّحاد، مثل قول العاشق: أنا من أهوى ومن أهوى أنا.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15413, 2207, 1, 'المدارس السريانيّة مدارس لاهوتيّة ملحقة بالأديرة تُسمّى «أسكول». منها (ثلاث تكفي): الرها، علّمت الفلسفة والطبّ باليونانيّة وأقفلها الإمبراطور زينون؛ نصيبين، ازدهرت بعد انتقال أساتذة الرها إليها؛ حرّان، اشتهرت بالرياضيّات والفلك؛ جنديسابور، اشتهرت بالطبّ ومنها أسرتا بختيشوع وماسويه.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15414, 2207, 2, 'المدارس السريانيّة مدارس لاهوتيّة ملحقة بالأديرة تُسمّى «أسكول». منها (ثلاث تكفي): الرها، علّمت الفلسفة والطبّ باليونانيّة وأقفلها الإمبراطور زينون؛ نصيبين، ازدهرت بعد انتقال أساتذة الرها إليها؛ حرّان، اشتهرت بالرياضيّات والفلك؛ جنديسابور، اشتهرت بالطبّ ومنها أسرتا بختيشوع وماسويه.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15415, 2208, 1, '(ثلاثة ممّا يلي) فيها نُقلت أغلبيّة كتب الفلسفة والعلوم المهمّة؛ كان مترجموها مهرة يتقنون أكثر من لغتين؛ تميّز حنين بالدقّة والسرعة والمعرفة العميقة بالمضمون؛ تأسّس فيها المصطلح العلمي العربي؛ كانت عهد ضبط الترجمات السابقة وإصلاحها.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15416, 2208, 2, '(ثلاثة ممّا يلي) فيها نُقلت أغلبيّة كتب الفلسفة والعلوم المهمّة؛ كان مترجموها مهرة يتقنون أكثر من لغتين؛ تميّز حنين بالدقّة والسرعة والمعرفة العميقة بالمضمون؛ تأسّس فيها المصطلح العلمي العربي؛ كانت عهد ضبط الترجمات السابقة وإصلاحها.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15417, 2209, 1, 'في الفلسفة: انطلق الكندي والفارابي وابن سينا من الكتب المنقولة، وحتّى الغزالي عدوّ الفلاسفة أخذ في «تهافت الفلاسفة» حججهم من برقلس وردوده من يحيى النحوي. في اللغة: صارت العربيّة لغة العلوم الدقيقة، ودخلتها مصطلحات جديدة بالتوليد (دليل، منطق، قياس) والاشتقاق (ماهيّة، كيفيّة) وإدخال الكلمات الأعجميّة (هندسة، قانون).', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15418, 2209, 2, 'في الفلسفة: انطلق الكندي والفارابي وابن سينا من الكتب المنقولة، وحتّى الغزالي عدوّ الفلاسفة أخذ في «تهافت الفلاسفة» حججهم من برقلس وردوده من يحيى النحوي. في اللغة: صارت العربيّة لغة العلوم الدقيقة، ودخلتها مصطلحات جديدة بالتوليد (دليل، منطق، قياس) والاشتقاق (ماهيّة، كيفيّة) وإدخال الكلمات الأعجميّة (هندسة، قانون).', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15419, 2210, 1, 'التحقيق يتطلّب أمرين: الأوّل النظر في الخبر، هل هو ممكن في ذاته أم مستحيل، وهذا يكون بمعرفة طبائع العمران؛ والثاني التأكّد من صدق الرواة بالتعديل والتجريح. والأمر الأوّل سابق، لأنّ الخبر إذا كان مستحيلاً فلا حاجة إلى فحص رواته؛ لهذا خصّص ابن خلدون الجزء الأوّل من كتاب العبر لعلم العمران.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15420, 2210, 2, 'التحقيق يتطلّب أمرين: الأوّل النظر في الخبر، هل هو ممكن في ذاته أم مستحيل، وهذا يكون بمعرفة طبائع العمران؛ والثاني التأكّد من صدق الرواة بالتعديل والتجريح. والأمر الأوّل سابق، لأنّ الخبر إذا كان مستحيلاً فلا حاجة إلى فحص رواته؛ لهذا خصّص ابن خلدون الجزء الأوّل من كتاب العبر لعلم العمران.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15421, 2211, 1, 'ليس في كتاب «الجبر والمقابلة» أيّ رمز جبريّ ولا الأرقام الهنديّة التي كان الخوارزمي يعرفها، فقد كتب مسائله وحلولها بالكلام وحده، ولهذا وُصف جبره بالجبر الناطق. ومصطلحاته: الجذر أو الشيء، وهو الحدّ المجهول؛ والمال، وهو مربّع المجهول؛ والعدد المفرد، وهو الحدّ المعلوم.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15422, 2211, 2, 'ليس في كتاب «الجبر والمقابلة» أيّ رمز جبريّ ولا الأرقام الهنديّة التي كان الخوارزمي يعرفها، فقد كتب مسائله وحلولها بالكلام وحده، ولهذا وُصف جبره بالجبر الناطق. ومصطلحاته: الجذر أو الشيء، وهو الحدّ المجهول؛ والمال، وهو مربّع المجهول؛ والعدد المفرد، وهو الحدّ المعلوم.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15423, 2212, 1, 'للاعتبار معنى شائع هو استخلاص عبرة أو استنتاج رأي، لكنّ أهمّ معانيه عند ابن الهيثم الاختبار العلميّ. ومراحله ثلاث: مراقبة الظاهرة، ثمّ التجربة البسيطة بمقارنة الظواهر، ثمّ تركيب نموذج مصغّر أو أداة للتحقّق (كالبيت المظلم وثقب الباب والأنبوب الطويل). ويُعدّ عالماً وضعيّاً لأنّه لم يسعَ إلى معرفة جوهر الضوء، واكتفى بتفسير كيفيّة انتشاره لأنّها قابلة للمراقبة والاعتبار.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15424, 2212, 2, 'للاعتبار معنى شائع هو استخلاص عبرة أو استنتاج رأي، لكنّ أهمّ معانيه عند ابن الهيثم الاختبار العلميّ. ومراحله ثلاث: مراقبة الظاهرة، ثمّ التجربة البسيطة بمقارنة الظواهر، ثمّ تركيب نموذج مصغّر أو أداة للتحقّق (كالبيت المظلم وثقب الباب والأنبوب الطويل). ويُعدّ عالماً وضعيّاً لأنّه لم يسعَ إلى معرفة جوهر الضوء، واكتفى بتفسير كيفيّة انتشاره لأنّها قابلة للمراقبة والاعتبار.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15425, 2213, 1, 'الأصل في البداوة الاقتصار على الضروري بسبب التربة المجدبة. البدو يعيشون في القفر بلا حامية ولا أسوار فيدافعون عن أنفسهم، لذلك هم أشجع؛ وهم أقرب إلى الخير لقربهم من الفطرة. أمّا أهل الحضر فيعيشون من الصنائع والتجارة ويميلون إلى الدعة والسكون، والترف يفسد أخلاقهم ويذهب بشجاعتهم. وتنشأ الحضارة بطريقين: اتّساع أحوال البدو، والتفاعل بين الغالب والمغلوب.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15426, 2213, 2, 'الأصل في البداوة الاقتصار على الضروري بسبب التربة المجدبة. البدو يعيشون في القفر بلا حامية ولا أسوار فيدافعون عن أنفسهم، لذلك هم أشجع؛ وهم أقرب إلى الخير لقربهم من الفطرة. أمّا أهل الحضر فيعيشون من الصنائع والتجارة ويميلون إلى الدعة والسكون، والترف يفسد أخلاقهم ويذهب بشجاعتهم. وتنشأ الحضارة بطريقين: اتّساع أحوال البدو، والتفاعل بين الغالب والمغلوب.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15427, 2214, 1, 'الأطوار: الظفر بالملك بقوّة العصبيّة، ثمّ الاستبداد، ثمّ الفراغ والدعة، ثمّ القنوع والمسالمة وتقليد الأسلاف، ثمّ الإسراف والتبذير وفيه يصيب الدولة الهرم. يقوم الملك على العصبيّة والمال الذي هو قوام الجند. يبدأ ضعف العصبيّة منذ طور الاستبداد، فتقلّ الحماية في الأطراف وتقوم دعوات الانفصال؛ ومع الترف تزيد النفقات فتفرض الدولة المكوس ثمّ تصادر أموال الرعايا، فتضمحلّ كالفتيلة في السراج إذا فني زيتها.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15428, 2214, 2, 'الأطوار: الظفر بالملك بقوّة العصبيّة، ثمّ الاستبداد، ثمّ الفراغ والدعة، ثمّ القنوع والمسالمة وتقليد الأسلاف، ثمّ الإسراف والتبذير وفيه يصيب الدولة الهرم. يقوم الملك على العصبيّة والمال الذي هو قوام الجند. يبدأ ضعف العصبيّة منذ طور الاستبداد، فتقلّ الحماية في الأطراف وتقوم دعوات الانفصال؛ ومع الترف تزيد النفقات فتفرض الدولة المكوس ثمّ تصادر أموال الرعايا، فتضمحلّ كالفتيلة في السراج إذا فني زيتها.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15429, 2215, 1, '«الحاوي» أهمّ كتب الرازي، جمعه تلاميذه بعد وفاته فجاء غنيّاً لكنّه يفتقر إلى التنظيم؛ أمّا «القانون في الطبّ» لابن سينا ففاق الحاوي بترتيبه وحسن تبويبه، ودُرّس في جامعات أوروبا قروناً. من إسهامات الرازي: التمييز بين الجدري والحصبة، أو تجربة العقاقير على الحيوانات، أو تأكيد أثر النفس في العلاج. ومن إسهامات ابن سينا: التمييز بين أمراض متشابهة العوارض كالتهاب الرئة والتهاب غلافها، أو رأيه أنّ الطبّ والصيدلة لا ينفصلان.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15430, 2215, 2, '«الحاوي» أهمّ كتب الرازي، جمعه تلاميذه بعد وفاته فجاء غنيّاً لكنّه يفتقر إلى التنظيم؛ أمّا «القانون في الطبّ» لابن سينا ففاق الحاوي بترتيبه وحسن تبويبه، ودُرّس في جامعات أوروبا قروناً. من إسهامات الرازي: التمييز بين الجدري والحصبة، أو تجربة العقاقير على الحيوانات، أو تأكيد أثر النفس في العلاج. ومن إسهامات ابن سينا: التمييز بين أمراض متشابهة العوارض كالتهاب الرئة والتهاب غلافها، أو رأيه أنّ الطبّ والصيدلة لا ينفصلان.', 1, '2026-09-30 22:11:27', '2026-09-30 22:11:27'),
(15431, 2216, 1, 'تمّ التلاقي في ثلاثة مواقع: صقلية، حيث أبقى النورمانديّون بعد انتزاعها من العرب على كثير من العادات العربيّة وعلى حركة الترجمة؛ وطليطلة، حيث ازدهرت الترجمة طوال القرن الثاني عشر بعد أن أخذها الإسبان؛ والمشرق العربيّ زمن الحروب الصليبيّة. ولا يُعدّ انتقال العلماء البيزنطيّين منعطفاً كبيراً لأنّه جاء متأخّراً قروناً عدّة عن انتشار الترجمات من العربيّة.', 1, '2026-09-30 22:11:28', '2026-09-30 22:11:28'),
(15432, 2216, 2, 'تمّ التلاقي في ثلاثة مواقع: صقلية، حيث أبقى النورمانديّون بعد انتزاعها من العرب على كثير من العادات العربيّة وعلى حركة الترجمة؛ وطليطلة، حيث ازدهرت الترجمة طوال القرن الثاني عشر بعد أن أخذها الإسبان؛ والمشرق العربيّ زمن الحروب الصليبيّة. ولا يُعدّ انتقال العلماء البيزنطيّين منعطفاً كبيراً لأنّه جاء متأخّراً قروناً عدّة عن انتشار الترجمات من العربيّة.', 1, '2026-09-30 22:11:28', '2026-09-30 22:11:28'),
(15433, 2217, 1, 'الكتابان هما القانون في الطبّ لابن سينا والمنصوريّ للرازيّ، ونقلهما جيراردو الكريمونيّ. دخلا التعليم في جامعات باريس ومونبلييه وبولونيا، وصارت المقالة الأولى من القانون إلزاميّة في مونبلييه، واستند إليهما الأطبّاء في معالجة الطاعون. وتراجع هذا الأثر مع الثورة الطبّيّة في القرن السابع عشر على يد هارفي وفيساليوس، بعد سيطرة دامت سبعة قرون.', 1, '2026-09-30 22:11:28', '2026-09-30 22:11:28'),
(15434, 2217, 2, 'الكتابان هما القانون في الطبّ لابن سينا والمنصوريّ للرازيّ، ونقلهما جيراردو الكريمونيّ. دخلا التعليم في جامعات باريس ومونبلييه وبولونيا، وصارت المقالة الأولى من القانون إلزاميّة في مونبلييه، واستند إليهما الأطبّاء في معالجة الطاعون. وتراجع هذا الأثر مع الثورة الطبّيّة في القرن السابع عشر على يد هارفي وفيساليوس، بعد سيطرة دامت سبعة قرون.', 1, '2026-09-30 22:11:28', '2026-09-30 22:11:28'),
(15435, 2218, 1, 'النقل: ترجم مايكل سكوت على الأرجح شروح ابن رشد على أرسطو، فلُقّب ابن رشد بالشارح. التأثير: أخذ عنه توما الأكوينيّ القول بضرورة الوحي ونزعته العقليّة مع الإقرار بحدود العقل. المؤيّدون: سيجر البرابنتيّ وجان دو جاندان ومارسيليو البادوفيّ الذي طالب بالفصل بين الدين والدولة. الخصوم: دنس سكوت وبونافنتورا وجيل دو روما، وصدرت مراسيم كنسيّة تحرّم تعليم فلسفته. وبقي أثره حتّى أيّام ليبنتز.', 1, '2026-09-30 22:11:28', '2026-09-30 22:11:28'),
(15436, 2218, 2, 'النقل: ترجم مايكل سكوت على الأرجح شروح ابن رشد على أرسطو، فلُقّب ابن رشد بالشارح. التأثير: أخذ عنه توما الأكوينيّ القول بضرورة الوحي ونزعته العقليّة مع الإقرار بحدود العقل. المؤيّدون: سيجر البرابنتيّ وجان دو جاندان ومارسيليو البادوفيّ الذي طالب بالفصل بين الدين والدولة. الخصوم: دنس سكوت وبونافنتورا وجيل دو روما، وصدرت مراسيم كنسيّة تحرّم تعليم فلسفته. وبقي أثره حتّى أيّام ليبنتز.', 1, '2026-09-30 22:11:28', '2026-09-30 22:11:28'),
(15437, 2219, 1, 'الكلمة مركّبة من «فيلو» أي محبّة، و«سوفيا» أي الحكمة، فالفلسفة تعني محبّة الحكمة. والحكمة معرفة معنى الشيء أو حقيقته أو سرّه، مع العمل بموجب هذه المعرفة (لا يُغفل جانب العمل).', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15438, 2219, 2, 'الكلمة مركّبة من «فيلو» أي محبّة، و«سوفيا» أي الحكمة، فالفلسفة تعني محبّة الحكمة. والحكمة معرفة معنى الشيء أو حقيقته أو سرّه، مع العمل بموجب هذه المعرفة (لا يُغفل جانب العمل).', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15439, 2220, 1, '1) الوظيفة المعرفيّة: تقديم الإجابة الأكثر منطقاً وموضوعيّة عن أسئلة المعرفة واللغة والتفكير والمنهج. 2) طرح الأسئلة التي لا نستطيع حتّى طرحها في العلوم الأخرى، مثل أسئلة الحياة والموت والكون والغايات الأخيرة والحرّيّة. 3) النقد الدائم لكلّ التفسيرات والأجوبة، حتّى أجوبة الفلسفة نفسها، وهو مهمّة الفلسفة بامتياز.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15440, 2220, 2, '1) الوظيفة المعرفيّة: تقديم الإجابة الأكثر منطقاً وموضوعيّة عن أسئلة المعرفة واللغة والتفكير والمنهج. 2) طرح الأسئلة التي لا نستطيع حتّى طرحها في العلوم الأخرى، مثل أسئلة الحياة والموت والكون والغايات الأخيرة والحرّيّة. 3) النقد الدائم لكلّ التفسيرات والأجوبة، حتّى أجوبة الفلسفة نفسها، وهو مهمّة الفلسفة بامتياز.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15441, 2221, 1, 'وظيفة تاريخ الحضارات تسجيل وقائع صعود الحضارات وتطوّرها وسقوطها، موثّقة بمناهج علم التاريخ (مرحلة التسجيل). ووظيفة فلسفة الحضارة تفسير هذه الوقائع ونقدها والحكم عليها واستخلاص القوانين. وهما متكاملتان لأنّ كلّ تفسير يحتاج إلى وقائع موثّقة، ولأنّ المؤرّخ حين يفسّر يستند إلى فلسفة ما؛ ومثال المؤرّخ الفيلسوف ابن خلدون.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15442, 2221, 2, 'وظيفة تاريخ الحضارات تسجيل وقائع صعود الحضارات وتطوّرها وسقوطها، موثّقة بمناهج علم التاريخ (مرحلة التسجيل). ووظيفة فلسفة الحضارة تفسير هذه الوقائع ونقدها والحكم عليها واستخلاص القوانين. وهما متكاملتان لأنّ كلّ تفسير يحتاج إلى وقائع موثّقة، ولأنّ المؤرّخ حين يفسّر يستند إلى فلسفة ما؛ ومثال المؤرّخ الفيلسوف ابن خلدون.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15443, 2222, 1, 'فلسفة التاريخ هي التفكير في الأحداث التاريخيّة، أي العلاقة بين الوقائع والتفكير فيها؛ فهي لا تبحث في أفكار مجرّدة، بل تكشف العقل في جوهر الوقائع. ومنهجه الجدل: الانتقال من القضيّة إلى نقيضها، ومن تناقضهما ينشأ تركيب أعلى، يدخل بدوره في تناقض جديد، فتتحرّك الحضارات في صيرورة صاعدة.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15444, 2222, 2, 'فلسفة التاريخ هي التفكير في الأحداث التاريخيّة، أي العلاقة بين الوقائع والتفكير فيها؛ فهي لا تبحث في أفكار مجرّدة، بل تكشف العقل في جوهر الوقائع. ومنهجه الجدل: الانتقال من القضيّة إلى نقيضها، ومن تناقضهما ينشأ تركيب أعلى، يدخل بدوره في تناقض جديد، فتتحرّك الحضارات في صيرورة صاعدة.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15445, 2223, 1, 'المبدأ: المجتمع هو الميدان القابل للفهم، لا المدينة وحدها، والأمّة والدولة شكلان يتشكّلان داخله. المثال: واجهت المدن اليونانيّة تحدّياً واحداً هو ضغط السكّان على وسائل العيش، فأرسلت كورنث وخالسيس فائض سكّانها عبر البحر، وزادت أثينا إنتاجها أضعافاً وقامت بثورة اقتصاديّة وسياسيّة. الاستنتاج: لا ندرك معنى الفرق بينها إلّا بمقارنة بعضها ببعض داخل المجتمع الواحد.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15446, 2223, 2, 'المبدأ: المجتمع هو الميدان القابل للفهم، لا المدينة وحدها، والأمّة والدولة شكلان يتشكّلان داخله. المثال: واجهت المدن اليونانيّة تحدّياً واحداً هو ضغط السكّان على وسائل العيش، فأرسلت كورنث وخالسيس فائض سكّانها عبر البحر، وزادت أثينا إنتاجها أضعافاً وقامت بثورة اقتصاديّة وسياسيّة. الاستنتاج: لا ندرك معنى الفرق بينها إلّا بمقارنة بعضها ببعض داخل المجتمع الواحد.', 1, '2026-09-30 22:11:29', '2026-09-30 22:11:29'),
(15447, 2224, 1, 'نظريّة الجنس: ينتقدها بشدّة، إذ يبيّن أنّ الحضارات اشترك في صنعها غير عرق ولون. نظريّة البيئة: يعترف بدورها لكنّه يرفض أن يكون حاسماً أو وحيداً، فبيئات متشابهة أعطت نتائج مختلفة: حوض الدانوب يشبه حوض النهر الأصفر ولم ينتج حضارة مثله، ووادي الأردن لم ينتج حضارة مشابهة لحضارة وادي النيل. البديل: الحضارة استجابة إنسانيّة لتحدٍّ، والعامل الحاسم علاقة لا وحدة، تقوم على الإرادة والتصميم؛ و«إنّ السهولة عدوّ الحضارة».', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15448, 2224, 2, 'نظريّة الجنس: ينتقدها بشدّة، إذ يبيّن أنّ الحضارات اشترك في صنعها غير عرق ولون. نظريّة البيئة: يعترف بدورها لكنّه يرفض أن يكون حاسماً أو وحيداً، فبيئات متشابهة أعطت نتائج مختلفة: حوض الدانوب يشبه حوض النهر الأصفر ولم ينتج حضارة مثله، ووادي الأردن لم ينتج حضارة مشابهة لحضارة وادي النيل. البديل: الحضارة استجابة إنسانيّة لتحدٍّ، والعامل الحاسم علاقة لا وحدة، تقوم على الإرادة والتصميم؛ و«إنّ السهولة عدوّ الحضارة».', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15449, 2225, 1, '1) الاعتراف بالإنسان الفرد: انتزع الإغريق الفرد من الطبيعة ومن القبيلة، وصارت آلهتهم نفسها أفراداً. 2) دور الفنون والثقافة: الفنّ يتحوّل من المادّة إلى الروح، وأدنى الفنون العمارة وأعلاها الشعر. 3) الحرّية والديمقراطية: دولة القوانين المعروفة والحقوق المتساوية والفضيلة الأخلاقيّة. أمّا روما فدمجت الفرد في الكلّيّ المجرّد، وكانت الأرستقراطية ميزتها فقسمت المجتمع وأسّست للصراعات، لكنّها اكتشفت مبدأ القانون الوضعيّ.', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15450, 2225, 2, '1) الاعتراف بالإنسان الفرد: انتزع الإغريق الفرد من الطبيعة ومن القبيلة، وصارت آلهتهم نفسها أفراداً. 2) دور الفنون والثقافة: الفنّ يتحوّل من المادّة إلى الروح، وأدنى الفنون العمارة وأعلاها الشعر. 3) الحرّية والديمقراطية: دولة القوانين المعروفة والحقوق المتساوية والفضيلة الأخلاقيّة. أمّا روما فدمجت الفرد في الكلّيّ المجرّد، وكانت الأرستقراطية ميزتها فقسمت المجتمع وأسّست للصراعات، لكنّها اكتشفت مبدأ القانون الوضعيّ.', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15451, 2226, 1, 'يرفض توينبي أن تكون الحضارة كائناً بيولوجيّاً محكوماً بالموت، ويرى أنّ التراجع التكنولوجيّ والانحسار الجغرافيّ قد يرافقان الانهيار لكنّهما ليسا سببه. السبب الحقيقيّ فقدان الطاقة الإبداعيّة (الحيويّة) وتوقّف الإبداع، فتعجز الحضارة عن الاستجابة للتحدّيات وحلّ مشكلاتها. والنزعة الحربيّة تبدو قوّة، لكنّها تدفع الدول إلى تدمير متبادل، وتحوّل الأقليّة المبدعة إلى أقليّة مسيطرة مستبدّة تلجأ إلى العنف، كما في آشور وإسبارطة وروما.', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15452, 2226, 2, 'يرفض توينبي أن تكون الحضارة كائناً بيولوجيّاً محكوماً بالموت، ويرى أنّ التراجع التكنولوجيّ والانحسار الجغرافيّ قد يرافقان الانهيار لكنّهما ليسا سببه. السبب الحقيقيّ فقدان الطاقة الإبداعيّة (الحيويّة) وتوقّف الإبداع، فتعجز الحضارة عن الاستجابة للتحدّيات وحلّ مشكلاتها. والنزعة الحربيّة تبدو قوّة، لكنّها تدفع الدول إلى تدمير متبادل، وتحوّل الأقليّة المبدعة إلى أقليّة مسيطرة مستبدّة تلجأ إلى العنف، كما في آشور وإسبارطة وروما.', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15453, 2227, 1, 'لأنّ الجدل عند هيجل حركة صاعدة دائمة لا شيء فيها خارج الصيرورة، لكنّه أوقف هذه الحركة عند الشعوب الجرمانيّة والدولة البروسيّة دون مبرّر منطقيّ كافٍ، وهنا يكمن التناقض. وما يخفّفه أنّه قصد عصر الثورة الفرنسيّة ومجّد الدولة المثال التي يحكمها العقل. والتطوّر الحضاريّ لا يقف عند شعب واحد.', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15454, 2227, 2, 'لأنّ الجدل عند هيجل حركة صاعدة دائمة لا شيء فيها خارج الصيرورة، لكنّه أوقف هذه الحركة عند الشعوب الجرمانيّة والدولة البروسيّة دون مبرّر منطقيّ كافٍ، وهنا يكمن التناقض. وما يخفّفه أنّه قصد عصر الثورة الفرنسيّة ومجّد الدولة المثال التي يحكمها العقل. والتطوّر الحضاريّ لا يقف عند شعب واحد.', 1, '2026-09-30 22:11:30', '2026-09-30 22:11:30'),
(15455, 2228, 1, 'لأنّ فلسفة الحضارة محاولة في المنهج لا إضافة في الوقائع، ولا تدّعي المعرفة الأكيدة بأسباب صعود الحضارات وانحلالها. ووظيفة الفلسفة أن تكتشف الأسئلة وتميّزها وتصنّفها، وأن تصوغها بوضوح وتسهم في الإجابة عن بعضها، ثمّ تخضع الإجابات تكراراً للتحليل والنقد.', 1, '2026-09-30 22:11:33', '2026-09-30 22:11:33'),
(15456, 2228, 2, 'لأنّ فلسفة الحضارة محاولة في المنهج لا إضافة في الوقائع، ولا تدّعي المعرفة الأكيدة بأسباب صعود الحضارات وانحلالها. ووظيفة الفلسفة أن تكتشف الأسئلة وتميّزها وتصنّفها، وأن تصوغها بوضوح وتسهم في الإجابة عن بعضها، ثمّ تخضع الإجابات تكراراً للتحليل والنقد.', 1, '2026-09-30 22:11:33', '2026-09-30 22:11:33'),
(15457, 2229, 1, 'التعصّب للأنا (العنصرية المركزية) نزعة تضع ثقافة الأنا في الأعلى أو في المركز قياساً بسواها أو على حساب سواها. يظهر في ادّعاء شعوب معيّنة الحقّ أو الواجب في التفوّق ولو بالقوّة، وفي النظر إلى الآخر كهمج أو برابرة. يدينه توينبي لأنّه غير علمي ولا يمتّ إلى الوقائع بصلة، ويراه ديورانت إخفاقاً ذريعاً في تصوير الوقائع، ويؤكّد أنّ المدنية لا تتوقّف على جنس دون جنس.', 1, '2026-09-30 22:11:33', '2026-09-30 22:11:33'),
(15458, 2229, 2, 'التعصّب للأنا (العنصرية المركزية) نزعة تضع ثقافة الأنا في الأعلى أو في المركز قياساً بسواها أو على حساب سواها. يظهر في ادّعاء شعوب معيّنة الحقّ أو الواجب في التفوّق ولو بالقوّة، وفي النظر إلى الآخر كهمج أو برابرة. يدينه توينبي لأنّه غير علمي ولا يمتّ إلى الوقائع بصلة، ويراه ديورانت إخفاقاً ذريعاً في تصوير الوقائع، ويؤكّد أنّ المدنية لا تتوقّف على جنس دون جنس.', 1, '2026-09-30 22:11:33', '2026-09-30 22:11:33'),
(15459, 2230, 1, 'يستبعد توينبي العامل الواحد: فالعرق وحده لا يصنع الحضارة، والبيئة وحدها لا تصنعها ولا تمنعها، إذ لم تنتج بيئات مشابهة كوادي الأردن ووادي الدانوب حضارة مماثلة. فالحضارة تنشأ بالإبداع وبالاستجابات الناجحة للتحدّيات، وتموت حين يجمد الإبداع. إذاً السبب الحقيقي للانهيار هو جمود الإبداع، لا عامل واحد كالعرق أو البيئة.', 1, '2026-09-30 22:11:33', '2026-09-30 22:11:33'),
(15460, 2230, 2, 'يستبعد توينبي العامل الواحد: فالعرق وحده لا يصنع الحضارة، والبيئة وحدها لا تصنعها ولا تمنعها، إذ لم تنتج بيئات مشابهة كوادي الأردن ووادي الدانوب حضارة مماثلة. فالحضارة تنشأ بالإبداع وبالاستجابات الناجحة للتحدّيات، وتموت حين يجمد الإبداع. إذاً السبب الحقيقي للانهيار هو جمود الإبداع، لا عامل واحد كالعرق أو البيئة.', 1, '2026-09-30 22:11:33', '2026-09-30 22:11:33'),
(15461, 2231, 1, 'الحضارة هي مجموع الإنتاج المادّي والروحي والعلمي والتقني، ومعه الفنون والحرف والتقاليد وأنظمة الحكم وأساليب العيش، لمجتمع ما ولفترة طويلة نسبيّاً؛ إنّها كلّ ما أضافه الإنسان إلى الطبيعة ماديّاً وروحيّاً. وهي خاصّة بالإنسان لأنّ الحيوان يكتسب بعض المهارات والعادات لكنّه عاجز عن التعلّم الواعي، فالقرود وهي أذكى الحيوانات ما زالت تعيش كما كانت تعيش منذ عشرات آلاف السنين، أمّا الإنسان فيبدع وينقل إبداعه من جيل إلى جيل ويطوّره.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15462, 2231, 2, 'الحضارة هي مجموع الإنتاج المادّي والروحي والعلمي والتقني، ومعه الفنون والحرف والتقاليد وأنظمة الحكم وأساليب العيش، لمجتمع ما ولفترة طويلة نسبيّاً؛ إنّها كلّ ما أضافه الإنسان إلى الطبيعة ماديّاً وروحيّاً. وهي خاصّة بالإنسان لأنّ الحيوان يكتسب بعض المهارات والعادات لكنّه عاجز عن التعلّم الواعي، فالقرود وهي أذكى الحيوانات ما زالت تعيش كما كانت تعيش منذ عشرات آلاف السنين، أمّا الإنسان فيبدع وينقل إبداعه من جيل إلى جيل ويطوّره.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15463, 2232, 1, 'الحضارة نتاج عوامل متداخلة لا عامل واحد. فالموارد الطبيعيّة موجودة دائماً، لكنّ الإنسان وحده تمكّن من استغلالها وتطويرها بفضل ما امتلكه من عوامل فكريّة وعلميّة. ولذلك كانت إرادة الإنسان وعقله العامل الأساسي وأحياناً الحاسم في نشوء الحضارات.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15464, 2232, 2, 'الحضارة نتاج عوامل متداخلة لا عامل واحد. فالموارد الطبيعيّة موجودة دائماً، لكنّ الإنسان وحده تمكّن من استغلالها وتطويرها بفضل ما امتلكه من عوامل فكريّة وعلميّة. ولذلك كانت إرادة الإنسان وعقله العامل الأساسي وأحياناً الحاسم في نشوء الحضارات.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15465, 2233, 1, 'عاش الإنسان الأوّل في جماعة بسبب ضعفه أمام الطبيعة والحيوان، وغريزة تدفعه إلى الاجتماع، فاستطاع بفضلها البقاء وتوفير حاجات البقاء والتكاثر ودرء الأخطار. وكان مصدر حياته التنقّل والتقاط الغذاء والصيد (اتّباع الثمار البرّيّة، صيد السمك، البقاء قرب القطعان)، وكان ذلك سبباً لتطوّر أدواته ومهاراته وأشكال تنظيمه واجتماعه.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15466, 2233, 2, 'عاش الإنسان الأوّل في جماعة بسبب ضعفه أمام الطبيعة والحيوان، وغريزة تدفعه إلى الاجتماع، فاستطاع بفضلها البقاء وتوفير حاجات البقاء والتكاثر ودرء الأخطار. وكان مصدر حياته التنقّل والتقاط الغذاء والصيد (اتّباع الثمار البرّيّة، صيد السمك، البقاء قرب القطعان)، وكان ذلك سبباً لتطوّر أدواته ومهاراته وأشكال تنظيمه واجتماعه.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15467, 2234, 1, 'تنمو الحضارة بمقدار نجاح أبنائها في مواجهة التحدّيات (كالزلازل والجفاف والفيضانات ونقص الغذاء والأمراض المعدية)، وحين يتوقّف الإبداع والاستجابة الناجحة تخبو الحضارة. كما أنّ الحضارة التي تُشرك أكبر عدد من أفرادها تبلغ أعلى درجات التحضّر، أمّا التي تمنعهم فتحكم على نفسها بالجمود، مثل نظام الطبقات في أوروبا العصر الوسيط أو الطبقات المقفلة في الهند.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15468, 2234, 2, 'تنمو الحضارة بمقدار نجاح أبنائها في مواجهة التحدّيات (كالزلازل والجفاف والفيضانات ونقص الغذاء والأمراض المعدية)، وحين يتوقّف الإبداع والاستجابة الناجحة تخبو الحضارة. كما أنّ الحضارة التي تُشرك أكبر عدد من أفرادها تبلغ أعلى درجات التحضّر، أمّا التي تمنعهم فتحكم على نفسها بالجمود، مثل نظام الطبقات في أوروبا العصر الوسيط أو الطبقات المقفلة في الهند.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15469, 2235, 1, 'لأنّ السحر والعلم يشتركان في وظيفة واحدة هي معرفة العالم المحيط بنا وتكييفه حسب رغباتنا. لكنّ السحر يخلط الواقعيّ بالمتخيّل، والمنطقيّ بالوهميّ، والجدّ باللعب، وهو مهارة شخصيّة مغلقة، لذلك ضعف بصعود العلم ومناهجه ومعاييره الحديثة. وتبقى قيمته الرمزيّة في أنّه من أولى محاولات الإنسان للدخول إلى قوانين الطبيعة ووعي قدرته على السيطرة عليها.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15470, 2235, 2, 'لأنّ السحر والعلم يشتركان في وظيفة واحدة هي معرفة العالم المحيط بنا وتكييفه حسب رغباتنا. لكنّ السحر يخلط الواقعيّ بالمتخيّل، والمنطقيّ بالوهميّ، والجدّ باللعب، وهو مهارة شخصيّة مغلقة، لذلك ضعف بصعود العلم ومناهجه ومعاييره الحديثة. وتبقى قيمته الرمزيّة في أنّه من أولى محاولات الإنسان للدخول إلى قوانين الطبيعة ووعي قدرته على السيطرة عليها.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15471, 2236, 1, 'كانت الأسرة الأولى أموميّة لا أبويّة: اعتمدت على الأمّ لا على الأب إلّا في الصيد، لأنّ المرأة تكفل استمرار النسل وتعتني بالمواليد وتتعهّد حاجاتهم، وكان لها أن تكون الكاهن والعرّافة والقاضي ورئيس القبيلة والقائد في الحرب، وكان الرجل إذا تزوّج ينتقل للعيش مع أهل زوجته وعشيرتها. أمّا بعد التحوّل إلى الزراعة والاستقرار فصارت الأسرة أبويّة، وصارت المرأة هي التي تنتقل حاملة أملاكها وحصّتها من الإرث.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15472, 2236, 2, 'كانت الأسرة الأولى أموميّة لا أبويّة: اعتمدت على الأمّ لا على الأب إلّا في الصيد، لأنّ المرأة تكفل استمرار النسل وتعتني بالمواليد وتتعهّد حاجاتهم، وكان لها أن تكون الكاهن والعرّافة والقاضي ورئيس القبيلة والقائد في الحرب، وكان الرجل إذا تزوّج ينتقل للعيش مع أهل زوجته وعشيرتها. أمّا بعد التحوّل إلى الزراعة والاستقرار فصارت الأسرة أبويّة، وصارت المرأة هي التي تنتقل حاملة أملاكها وحصّتها من الإرث.', 1, '2026-09-30 22:11:34', '2026-09-30 22:11:34'),
(15473, 2237, 1, 'تحدّ جزيرة العرب من الشمال بادية الشام، ومن الشرق الخليج العربي أو الفارسي وبحر عُمان، ومن الجنوب المحيط الهندي، ومن الغرب البحر الأحمر. وكانت مدن اليمن (مثل صنعاء) والحجاز (مكّة ويثرب والطائف) أهمّ المراكز الحضاريّة، ويمكن أن نضيف إليها عُمان. ومناخها شديد الحرارة نهاراً، شديد البرودة ليلاً في أمكنة كثيرة، ويميل إلى الاعتدال في المناطق الجبليّة الجنوبيّة.', 1, '2026-09-30 22:11:35', '2026-09-30 22:11:35'),
(15474, 2237, 2, 'تحدّ جزيرة العرب من الشمال بادية الشام، ومن الشرق الخليج العربي أو الفارسي وبحر عُمان، ومن الجنوب المحيط الهندي، ومن الغرب البحر الأحمر. وكانت مدن اليمن (مثل صنعاء) والحجاز (مكّة ويثرب والطائف) أهمّ المراكز الحضاريّة، ويمكن أن نضيف إليها عُمان. ومناخها شديد الحرارة نهاراً، شديد البرودة ليلاً في أمكنة كثيرة، ويميل إلى الاعتدال في المناطق الجبليّة الجنوبيّة.', 1, '2026-09-30 22:11:35', '2026-09-30 22:11:35'),
(15475, 2238, 1, 'كانت الحضارة العربيّة عشيّة الإسلام متخلّفة نسبيّاً في العلوم قياساً على الحضارات المجاورة، لكنّ الحياة الأدبيّة، وخاصّة الشعر، كانت على مستوى رفيع، وقد رعت الممالك العربيّة الشعراء والحكماء في بلاط اللخميين والغساسنة. ومن القيم التي حافظ عليها الإسلام وأكّدها: المروءة، والكرم، ونصرة المحتاج والمظلوم، والشجاعة، والوفاء (تكفي ثلاث).', 1, '2026-09-30 22:11:35', '2026-09-30 22:11:35'),
(15476, 2238, 2, 'كانت الحضارة العربيّة عشيّة الإسلام متخلّفة نسبيّاً في العلوم قياساً على الحضارات المجاورة، لكنّ الحياة الأدبيّة، وخاصّة الشعر، كانت على مستوى رفيع، وقد رعت الممالك العربيّة الشعراء والحكماء في بلاط اللخميين والغساسنة. ومن القيم التي حافظ عليها الإسلام وأكّدها: المروءة، والكرم، ونصرة المحتاج والمظلوم، والشجاعة، والوفاء (تكفي ثلاث).', 1, '2026-09-30 22:11:35', '2026-09-30 22:11:35'),
(15477, 2239, 1, 'نعم، حضّ الإسلام على طلب العلم وعلى المساواة بين البشر، ومن الأحاديث: «اطلبوا العلم من المهد إلى اللحد»، و«اطلبوا العلم ولو في الصين». وقد تلاقت في الدولة الناشئة شعوب وحضارات عريقة، فقامت مثاقفة كبرى بواسطة اللغة العربيّة، لغة الدين ولغة الدولة، نقلت إليها هذه الشعوب تراثها، فنشأت العلوم الدينيّة وتطوّرت العلوم الوضعيّة بالعربيّة، وجرت حركة نقل وترجمة واسعة أفاد منها العرب في نهضتهم ثمّ الأوروبيّون في نهضتهم.', 1, '2026-09-30 22:11:35', '2026-09-30 22:11:35'),
(15478, 2239, 2, 'نعم، حضّ الإسلام على طلب العلم وعلى المساواة بين البشر، ومن الأحاديث: «اطلبوا العلم من المهد إلى اللحد»، و«اطلبوا العلم ولو في الصين». وقد تلاقت في الدولة الناشئة شعوب وحضارات عريقة، فقامت مثاقفة كبرى بواسطة اللغة العربيّة، لغة الدين ولغة الدولة، نقلت إليها هذه الشعوب تراثها، فنشأت العلوم الدينيّة وتطوّرت العلوم الوضعيّة بالعربيّة، وجرت حركة نقل وترجمة واسعة أفاد منها العرب في نهضتهم ثمّ الأوروبيّون في نهضتهم.', 1, '2026-09-30 22:11:35', '2026-09-30 22:11:35'),
(15479, 2240, 1, 'العوامل الأربعة: حاجة العرب إلى العلوم والفلسفة، وتشجيع الخلفاء والوزراء والأمراء، وثقافة المترجمين، وانتشار اللغة العربيّة. ومن الحاجات (تكفي اثنتان): رعاية الأغنياء للأطبّاء ← الطبّ والصيدلة؛ إدارة بيت المال والخراج ← الرياضيّات؛ تشييد القلاع والجسور والمساجد ← الهندسة؛ ضبط مواعيد الصيام والأعياد واتّجاه القبلة ← علم الفلك؛ الجدل الديني والنقاش بين المذاهب ← المنطق والإلهيّات.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15480, 2240, 2, 'العوامل الأربعة: حاجة العرب إلى العلوم والفلسفة، وتشجيع الخلفاء والوزراء والأمراء، وثقافة المترجمين، وانتشار اللغة العربيّة. ومن الحاجات (تكفي اثنتان): رعاية الأغنياء للأطبّاء ← الطبّ والصيدلة؛ إدارة بيت المال والخراج ← الرياضيّات؛ تشييد القلاع والجسور والمساجد ← الهندسة؛ ضبط مواعيد الصيام والأعياد واتّجاه القبلة ← علم الفلك؛ الجدل الديني والنقاش بين المذاهب ← المنطق والإلهيّات.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15481, 2241, 1, 'إنشاء بيت الحكمة نقطة الارتكاز في التقسيم. المرحلة الأولى قبل حنين، ومن نقلتها يحيى بن البطريق (وكانت ترجمته ركيكة لضعفه في العربيّة) وابن المقفّع. المرحلة الثانية مرحلة حنين بن إسحق وتلامذته، وهي العصر الذهبي للترجمة، ومن نقلتها ثابت بن قرّة وقسطا بن لوقا. المرحلة الثالثة اكتملت فيها ترجمة أهمّ المؤلّفات، وأشهر نقلتها متّى بن يونس ويحيى بن عدي، ثمّ صارت الترجمة أعمالاً فرديّة وانطلق الإبداع بالعربيّة.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15482, 2241, 2, 'إنشاء بيت الحكمة نقطة الارتكاز في التقسيم. المرحلة الأولى قبل حنين، ومن نقلتها يحيى بن البطريق (وكانت ترجمته ركيكة لضعفه في العربيّة) وابن المقفّع. المرحلة الثانية مرحلة حنين بن إسحق وتلامذته، وهي العصر الذهبي للترجمة، ومن نقلتها ثابت بن قرّة وقسطا بن لوقا. المرحلة الثالثة اكتملت فيها ترجمة أهمّ المؤلّفات، وأشهر نقلتها متّى بن يونس ويحيى بن عدي، ثمّ صارت الترجمة أعمالاً فرديّة وانطلق الإبداع بالعربيّة.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15483, 2242, 1, 'من الآثار السلبيّة أخطاء كنسبة كتب لغير أصحابها والترجمة الحرفيّة الركيكة، لكنّها جزئيّة ونادرة ومعظمها في المرحلة الأولى. أمّا الآثار الإيجابيّة فظاهرة: في الفلسفة أقرّ الكندي والفارابي وابن سينا وابن رشد بفضل أرسطو؛ وفي اللغة دخلت مصطلحات جديدة وأسلوب المقالة؛ وفي العلوم حفظت الترجمات مؤلّفات كثيرة من الضياع. وقد خلقت المثاقفة شخصيّة عربيّة جديدة هي «مزيج من الكلّ» كما يقول أحمد أمين، لذلك لا تكفي الأخطاء للحكم عليها بالسلب.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15484, 2242, 2, 'من الآثار السلبيّة أخطاء كنسبة كتب لغير أصحابها والترجمة الحرفيّة الركيكة، لكنّها جزئيّة ونادرة ومعظمها في المرحلة الأولى. أمّا الآثار الإيجابيّة فظاهرة: في الفلسفة أقرّ الكندي والفارابي وابن سينا وابن رشد بفضل أرسطو؛ وفي اللغة دخلت مصطلحات جديدة وأسلوب المقالة؛ وفي العلوم حفظت الترجمات مؤلّفات كثيرة من الضياع. وقد خلقت المثاقفة شخصيّة عربيّة جديدة هي «مزيج من الكلّ» كما يقول أحمد أمين، لذلك لا تكفي الأخطاء للحكم عليها بالسلب.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15485, 2243, 1, 'أخذ العرب الرياضيّات والفلك عن الهنود واليونانيّين، واعتُبرت في البداية «علوماً دخيلة». ومن أمثلة النقل: عرّب إبراهيم الفزاري كتاب السندهند الفلكي وحوّله إلى سنوات قمريّة، وترجم الحجّاج بن مطر عن اليونانيّة كتاب «الأصول» لإقليدس في الهندسة وكتاب «المجسطي» لبطليموس في الفلك.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15486, 2243, 2, 'أخذ العرب الرياضيّات والفلك عن الهنود واليونانيّين، واعتُبرت في البداية «علوماً دخيلة». ومن أمثلة النقل: عرّب إبراهيم الفزاري كتاب السندهند الفلكي وحوّله إلى سنوات قمريّة، وترجم الحجّاج بن مطر عن اليونانيّة كتاب «الأصول» لإقليدس في الهندسة وكتاب «المجسطي» لبطليموس في الفلك.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15487, 2244, 1, 'الزيج جداول فلكيّة وضعها الخوارزمي في نسختين: الصغير والكبير، وهو أوّل محاولة للجمع بين الفلك الهندي والفلك اليوناني، وكان الناس «قبل الرصد وبعده يعوّلون عليه» كما يقول الفهرست. بعد قرنين على وفاته رُوجع الزيج الصغير في الأندلس وعُدّل ليوافق خطّ زوال قرطبة، ثمّ تُرجم إلى اللاتينيّة في القرن الثاني عشر للميلاد فنال شهرة واسعة في أوروبا، وأخذ منه الزرقالي الأندلسي حين وضع جداول طليطلة.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15488, 2244, 2, 'الزيج جداول فلكيّة وضعها الخوارزمي في نسختين: الصغير والكبير، وهو أوّل محاولة للجمع بين الفلك الهندي والفلك اليوناني، وكان الناس «قبل الرصد وبعده يعوّلون عليه» كما يقول الفهرست. بعد قرنين على وفاته رُوجع الزيج الصغير في الأندلس وعُدّل ليوافق خطّ زوال قرطبة، ثمّ تُرجم إلى اللاتينيّة في القرن الثاني عشر للميلاد فنال شهرة واسعة في أوروبا، وأخذ منه الزرقالي الأندلسي حين وضع جداول طليطلة.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15489, 2245, 1, '1) تنوّع الميادين التي درسها: الرياضيّات والفلك وعلوم الطبيعة كالنبات والصيدلة وتاريخ الحضارات. 2) إتقانه لغات كثيرة، منها العربيّة والفارسيّة والسريانيّة والسنسكريتيّة واليونانيّة. 3) كثرة إنتاجه، فقد ترك نحو مئة وخمسين مؤلّفاً. (ويمكن إضافة كتاب «الآثار الباقية»، وهو موسوعة ضخمة متنوّعة المواضيع.)', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15490, 2245, 2, '1) تنوّع الميادين التي درسها: الرياضيّات والفلك وعلوم الطبيعة كالنبات والصيدلة وتاريخ الحضارات. 2) إتقانه لغات كثيرة، منها العربيّة والفارسيّة والسريانيّة والسنسكريتيّة واليونانيّة. 3) كثرة إنتاجه، فقد ترك نحو مئة وخمسين مؤلّفاً. (ويمكن إضافة كتاب «الآثار الباقية»، وهو موسوعة ضخمة متنوّعة المواضيع.)', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15491, 2246, 1, 'للخوارزمي مكانة مميّزة: فهو أوّل من وضع جداول فلكيّة (أزياجاً) بالعربيّة، وأوّل من ألّف في الأسطرلاب بالعربيّة، وإنجازه الأكبر أنّه جعل الجبر علماً مستقلّاً عن الحساب، وبفضله انتشرت كلمة الجبر والأرقام الهنديّة باسم الأرقام العربيّة. لكنّ إنجازه محدود: فقد تجاوزه بعد قرن واحد أبو كامل شجاع بن أسلم ثمّ عمر الخيّام، واعتمد فيبوناتشي الإيطالي على جبر أبي كامل لا على جبر الخوارزمي؛ كما أنّه لم يبتدع رموزاً، وتنبّه إلى الجذور التخيّليّة دون أن يعرف استخراجها.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15492, 2247, 1, 'قاس الفلكي اليوناني إراتوسثينس محيط الأرض، وكذلك فلكيّون عرب في زمن الخليفة المأمون منهم سند بن علي، لكن يبدو أنّ البيروني لم يطّلع على هذه البحوث. ثمّ إنّه استعمل حساب المثلّثات (علوّ جبل وزاوية انحطاط الأفق من قمّته) لاستخراج طول درجة من خطّ نصف النهار، ولا نجد قاعدته هذه عند أحد سواه؛ لذلك يدلّ عمله على عبقريّة مميّزة.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15493, 2246, 2, 'للخوارزمي مكانة مميّزة: فهو أوّل من وضع جداول فلكيّة (أزياجاً) بالعربيّة، وأوّل من ألّف في الأسطرلاب بالعربيّة، وإنجازه الأكبر أنّه جعل الجبر علماً مستقلّاً عن الحساب، وبفضله انتشرت كلمة الجبر والأرقام الهنديّة باسم الأرقام العربيّة. لكنّ إنجازه محدود: فقد تجاوزه بعد قرن واحد أبو كامل شجاع بن أسلم ثمّ عمر الخيّام، واعتمد فيبوناتشي الإيطالي على جبر أبي كامل لا على جبر الخوارزمي؛ كما أنّه لم يبتدع رموزاً، وتنبّه إلى الجذور التخيّليّة دون أن يعرف استخراجها.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15494, 2247, 2, 'قاس الفلكي اليوناني إراتوسثينس محيط الأرض، وكذلك فلكيّون عرب في زمن الخليفة المأمون منهم سند بن علي، لكن يبدو أنّ البيروني لم يطّلع على هذه البحوث. ثمّ إنّه استعمل حساب المثلّثات (علوّ جبل وزاوية انحطاط الأفق من قمّته) لاستخراج طول درجة من خطّ نصف النهار، ولا نجد قاعدته هذه عند أحد سواه؛ لذلك يدلّ عمله على عبقريّة مميّزة.', 1, '2026-09-30 22:11:36', '2026-09-30 22:11:36'),
(15495, 2248, 1, 'المنطلق: الفلك عند البيروني يقوم على الرياضيّات والأرصاد الدقيقة، لا على فلسفة الطبيعة عند أرسطو. الخطوات: 1) عرض المبادئ العامّة للمسألة، 2) عرض الحلول التي اقترحها الهنود وبطليموس والفلكيّون العرب، 3) نقد هذه الحلول، 4) عرض أشهر الأرصاد وأرصاده الخاصّة، 5) اختيار أحد الحلول أو اقتراح حلّ شخصي. الصلة: الرياضيّات عنده لغة العلوم الحقيقيّة لأنّها تتميّز بالدقّة التامّة، لذلك جعل الحساب والرصد معيار قبول أيّ حلّ.', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15496, 2248, 2, 'المنطلق: الفلك عند البيروني يقوم على الرياضيّات والأرصاد الدقيقة، لا على فلسفة الطبيعة عند أرسطو. الخطوات: 1) عرض المبادئ العامّة للمسألة، 2) عرض الحلول التي اقترحها الهنود وبطليموس والفلكيّون العرب، 3) نقد هذه الحلول، 4) عرض أشهر الأرصاد وأرصاده الخاصّة، 5) اختيار أحد الحلول أو اقتراح حلّ شخصي. الصلة: الرياضيّات عنده لغة العلوم الحقيقيّة لأنّها تتميّز بالدقّة التامّة، لذلك جعل الحساب والرصد معيار قبول أيّ حلّ.', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15497, 2249, 1, 'نُشر الحاوي بعد وفاة الرازي، وأضاف إليه شهرة كبيرة، ورأى علي بن العبّاس المجوسيّ أنّه يساعد الأطبّاء على حفظ الصحّة ومداواة الأمراض. ومن الانتقادات: أنّه لم يوضع قيد التداول لطول الكلام فيه فعجز أكثر العلماء عن اقتنائه ونسخه إلّا قلّة من الأغنياء؛ وأنّه لم يذكر الأمور الطبيعيّة كعلم الأمزجة والأخلاط وتشريح الأعضاء (بحسب المجوسيّ)؛ وأنّ معلوماته عُرضت بطريقة غير منظّمة. (يكفي انتقادان)', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15498, 2249, 2, 'نُشر الحاوي بعد وفاة الرازي، وأضاف إليه شهرة كبيرة، ورأى علي بن العبّاس المجوسيّ أنّه يساعد الأطبّاء على حفظ الصحّة ومداواة الأمراض. ومن الانتقادات: أنّه لم يوضع قيد التداول لطول الكلام فيه فعجز أكثر العلماء عن اقتنائه ونسخه إلّا قلّة من الأغنياء؛ وأنّه لم يذكر الأمور الطبيعيّة كعلم الأمزجة والأخلاط وتشريح الأعضاء (بحسب المجوسيّ)؛ وأنّ معلوماته عُرضت بطريقة غير منظّمة. (يكفي انتقادان)', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15499, 2250, 1, 'كان اهتمام الرازي بالجانب العلاجيّ أكبر من اهتمامه بالجانب النظريّ. ومن إنجازاته: 1) تجربة العقاقير على الحيوانات لاختبار جدواها قبل معالجة البشر؛ 2) تغليف بعض الأدوية أو مزجها بالعسل أو بعصير الفواكه، أو دسّها في الطعام، لإخفاء طعمها الكريه وتسهيل تناولها؛ 3) أنّه أوّل من استخدم الرصاص الأبيض في المراهم؛ (ويمكن ذكر اهتمامه بالنباتات الطبيّة). كلّها تهدف إلى علاج المريض فعليّاً لا إلى النظريّة.', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15500, 2250, 2, 'كان اهتمام الرازي بالجانب العلاجيّ أكبر من اهتمامه بالجانب النظريّ. ومن إنجازاته: 1) تجربة العقاقير على الحيوانات لاختبار جدواها قبل معالجة البشر؛ 2) تغليف بعض الأدوية أو مزجها بالعسل أو بعصير الفواكه، أو دسّها في الطعام، لإخفاء طعمها الكريه وتسهيل تناولها؛ 3) أنّه أوّل من استخدم الرصاص الأبيض في المراهم؛ (ويمكن ذكر اهتمامه بالنباتات الطبيّة). كلّها تهدف إلى علاج المريض فعليّاً لا إلى النظريّة.', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15501, 2251, 1, 'اعتمد الرازي وصفاً دقيقاً لكلّ مرحلة من مراحل المرض. في المرضين يظهر طفح على الجلد له علاقة بارتفاع حرارة الجسم، لكنّ طفح الجدري يترك آثاراً تبقى مدى الحياة، أمّا طفح الحصبة فيزول بعد الشفاء؛ ومن أخطار الجدري أنّه يسبّب العمى. ويمكن اكتشافهما في بدايتهما بفحص البراز، وجسّ النبض، ومراقبة إيقاع دقّات القلب وإيقاع التنفّس.', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15502, 2251, 2, 'اعتمد الرازي وصفاً دقيقاً لكلّ مرحلة من مراحل المرض. في المرضين يظهر طفح على الجلد له علاقة بارتفاع حرارة الجسم، لكنّ طفح الجدري يترك آثاراً تبقى مدى الحياة، أمّا طفح الحصبة فيزول بعد الشفاء؛ ومن أخطار الجدري أنّه يسبّب العمى. ويمكن اكتشافهما في بدايتهما بفحص البراز، وجسّ النبض، ومراقبة إيقاع دقّات القلب وإيقاع التنفّس.', 1, '2026-09-30 22:11:37', '2026-09-30 22:11:37'),
(15503, 2252, 1, 'اهتمّ ابن سينا بالصيدلة لأنّه لم يفصل في الطبّ بين العلم (معرفة طبيعة المرض) والعمل (معالجته)، والمعالجة تحتاج إلى الصيدلة بوصفها علم تركيب الدواء المناسب. المزاج الأوّل يحدث عن العناصر البسيطة، والمزاج الثاني يحصل من الاختلاط والتركيب، ومثاله اللبن الذي يمتزج من أجزاء مائيّة وجبنيّة وسمنيّة (أو الكرنب).', 1, '2026-09-30 22:11:40', '2026-09-30 22:11:40'),
(15504, 2252, 2, 'اهتمّ ابن سينا بالصيدلة لأنّه لم يفصل في الطبّ بين العلم (معرفة طبيعة المرض) والعمل (معالجته)، والمعالجة تحتاج إلى الصيدلة بوصفها علم تركيب الدواء المناسب. المزاج الأوّل يحدث عن العناصر البسيطة، والمزاج الثاني يحصل من الاختلاط والتركيب، ومثاله اللبن الذي يمتزج من أجزاء مائيّة وجبنيّة وسمنيّة (أو الكرنب).', 1, '2026-09-30 22:11:40', '2026-09-30 22:11:40'),
(15505, 2253, 1, 'أيّ أربع ممّا يلي: 1) أن يكون الدواء خالياً من كيفيّة مكتسبة؛ 2) أن يُجرَّب على علّة مفردة لا مركّبة؛ 3) أن يُجرَّب على علل متضادّة؛ 4) أن تقابل قوّة الدواء قوّة العلّة، فيُجرَّب أوّلاً على الأضعف؛ 5) أن يُراعى زمن ظهور أثره؛ 6) أن يستمرّ فعله دائماً أو في الأكثر؛ 7) أن تكون التجربة على بدن الإنسان.', 1, '2026-09-30 22:11:40', '2026-09-30 22:11:40'),
(15506, 2253, 2, 'أيّ أربع ممّا يلي: 1) أن يكون الدواء خالياً من كيفيّة مكتسبة؛ 2) أن يُجرَّب على علّة مفردة لا مركّبة؛ 3) أن يُجرَّب على علل متضادّة؛ 4) أن تقابل قوّة الدواء قوّة العلّة، فيُجرَّب أوّلاً على الأضعف؛ 5) أن يُراعى زمن ظهور أثره؛ 6) أن يستمرّ فعله دائماً أو في الأكثر؛ 7) أن تكون التجربة على بدن الإنسان.', 1, '2026-09-30 22:11:40', '2026-09-30 22:11:40'),
(15507, 2254, 1, 'تميّز ابن سينا من الرازي بأسلوبه الواضح وعرضه الموجز، وميّز بين أمراض متشابهة الأعراض (كالتهاب الرئة والتهاب غلافها، والمغص الكلوي والمغص المعوي)، وخالف الطبّ اليوناني حين عالج الدماغ المحتقن بالتبريد، ولم يفصل بين العلم والعمل، ووضع قواعد للتجربة. قامت مفاهيمه الطبيّة على فلسفة أرسطو في المادّة والصورة والعلل الأربع، لذلك كان أبرز ممثّلي الطبّ القديم. ونال «القانون» أوسع شهرة عند العرب وفي أوروبا حتّى القرن الثامن عشر ودخل برامج التدريس الجامعيّة، مع انتقادات متنوّعة.', 1, '2026-09-30 22:11:40', '2026-09-30 22:11:40'),
(15508, 2254, 2, 'تميّز ابن سينا من الرازي بأسلوبه الواضح وعرضه الموجز، وميّز بين أمراض متشابهة الأعراض (كالتهاب الرئة والتهاب غلافها، والمغص الكلوي والمغص المعوي)، وخالف الطبّ اليوناني حين عالج الدماغ المحتقن بالتبريد، ولم يفصل بين العلم والعمل، ووضع قواعد للتجربة. قامت مفاهيمه الطبيّة على فلسفة أرسطو في المادّة والصورة والعلل الأربع، لذلك كان أبرز ممثّلي الطبّ القديم. ونال «القانون» أوسع شهرة عند العرب وفي أوروبا حتّى القرن الثامن عشر ودخل برامج التدريس الجامعيّة، مع انتقادات متنوّعة.', 1, '2026-09-30 22:11:40', '2026-09-30 22:11:40'),
(15509, 2255, 1, 'من المصادر اليونانيّة (اثنان): كتاب ديسقوريدس «المادة الطبيّة» الذي تُرجم باسم «الحشائش»، مقالات جالينوس، كتاب النبات المنسوب خطأً إلى أرسطو. ومن المصادر العربيّة (اثنان): كتاب النبات لأبي حنيفة الدينوري، كتاب الأدوية المفردة للغافقي، كتاب الإدريسي، رحلة ابن الروميّة، كتاب ابن جلجل في تفسير أسماء الأدوية (وكتب الفلاحة).', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15510, 2255, 2, 'من المصادر اليونانيّة (اثنان): كتاب ديسقوريدس «المادة الطبيّة» الذي تُرجم باسم «الحشائش»، مقالات جالينوس، كتاب النبات المنسوب خطأً إلى أرسطو. ومن المصادر العربيّة (اثنان): كتاب النبات لأبي حنيفة الدينوري، كتاب الأدوية المفردة للغافقي، كتاب الإدريسي، رحلة ابن الروميّة، كتاب ابن جلجل في تفسير أسماء الأدوية (وكتب الفلاحة).', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15511, 2256, 1, '1) الشمول: جمع ما قاله ديسقوريدس وجالينوس وأضاف أقوال المحدثين. 2) الدقّة: أسند كلّ قول إلى قائله وتحرّى الدقّة في النقل، وضبط الأسماء بالشكل والنقط. 3) التجربة: نبّه على الأغلاط معتمداً على التجربة والمشاهدة. 4) الإضافة: ذكر أدوية لم يعرفها الإغريق (نحو أربعمئة)، وأسماء الأدوية بلغات مختلفة. (تكفي ثلاث)', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15512, 2256, 2, '1) الشمول: جمع ما قاله ديسقوريدس وجالينوس وأضاف أقوال المحدثين. 2) الدقّة: أسند كلّ قول إلى قائله وتحرّى الدقّة في النقل، وضبط الأسماء بالشكل والنقط. 3) التجربة: نبّه على الأغلاط معتمداً على التجربة والمشاهدة. 4) الإضافة: ذكر أدوية لم يعرفها الإغريق (نحو أربعمئة)، وأسماء الأدوية بلغات مختلفة. (تكفي ثلاث)', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15513, 2257, 1, 'نظريّة الصدور (عند علماء الرياضيّات): شعاع يخرج من العين إلى المبصَر، ومن أنصارها أفلاطون وأقليدس وبطليموس، ومن العرب الكندي. نظريّة الورود (عند علماء الطبيعة): صورة ترد من المبصَر إلى العين، ومن أنصارها أرسطو وابن سينا. كان ابن الهيثم يؤيّد الصدور عند بطليموس ثمّ تراجع عنها، فدحضها وتبنّى الورود.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15514, 2257, 2, 'نظريّة الصدور (عند علماء الرياضيّات): شعاع يخرج من العين إلى المبصَر، ومن أنصارها أفلاطون وأقليدس وبطليموس، ومن العرب الكندي. نظريّة الورود (عند علماء الطبيعة): صورة ترد من المبصَر إلى العين، ومن أنصارها أرسطو وابن سينا. كان ابن الهيثم يؤيّد الصدور عند بطليموس ثمّ تراجع عنها، فدحضها وتبنّى الورود.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15515, 2258, 1, 'نعم. فكتابه «الجامع» أكبر موسوعة في علم النبات والأدوية، غنيّ المضمون: نحو ثلاثة آلاف صنف من الأعشاب الطبيّة، ونحو ألف وخمسمئة عقار منها نحو أربعمئة لم يعرفها الإغريق، ونحو مئة وخمسين اسماً لأطباء وصيادلة ونباتيّين. وقد جمع أفضل ما قاله السابقون مع إسناد كلّ قول إلى قائله، وأضاف مشاهداته وتجاربه في أسفاره. لذلك عُدّ قمّة تطوّر علم النبات عند العرب.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15516, 2259, 1, 'المعنى الأهمّ للاعتبار هو الاختبار العلمي، وهو اختبار يلائم خصوصيّة البصريّات لأنّها مركّبة من العلوم الطبيعيّة والعلوم التعليميّة، والمعتبر هو العالِم الذي يراقب الظاهرة البصريّة أو الفلكيّة. وهناك المعنى الشائع: أخذ العبرة واستنتاج رأي من آراء سابقة. الأدوات (ثلاث منها): البيت المظلم، ثقب الباب، الأنبوب الطويل، المسطرة المرقّمة.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15517, 2259, 2, 'المعنى الأهمّ للاعتبار هو الاختبار العلمي، وهو اختبار يلائم خصوصيّة البصريّات لأنّها مركّبة من العلوم الطبيعيّة والعلوم التعليميّة، والمعتبر هو العالِم الذي يراقب الظاهرة البصريّة أو الفلكيّة. وهناك المعنى الشائع: أخذ العبرة واستنتاج رأي من آراء سابقة. الأدوات (ثلاث منها): البيت المظلم، ثقب الباب، الأنبوب الطويل، المسطرة المرقّمة.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15518, 2258, 2, 'نعم. فكتابه «الجامع» أكبر موسوعة في علم النبات والأدوية، غنيّ المضمون: نحو ثلاثة آلاف صنف من الأعشاب الطبيّة، ونحو ألف وخمسمئة عقار منها نحو أربعمئة لم يعرفها الإغريق، ونحو مئة وخمسين اسماً لأطباء وصيادلة ونباتيّين. وقد جمع أفضل ما قاله السابقون مع إسناد كلّ قول إلى قائله، وأضاف مشاهداته وتجاربه في أسفاره. لذلك عُدّ قمّة تطوّر علم النبات عند العرب.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15519, 2260, 1, '1) «المناظر» موسوعة كبرى من أوسع ما كُتب في البصريّات في القرون الوسطى (سبع مقالات). 2) جعل البصريّات نقطة تتقاطع فيها أربعة علوم: الهندسة، والفيزياء، وفيزيولوجيا العين، وعلم نفس الإدراك البصري. 3) قام بأهمّ إصلاح في هذا العلم منذ بطليموس، وكان أوّل من شدّد على جعل البصريّات علماً اختبارياً، ويعدّه جورج سارتون أكبر عالم بصريّات قبل ديكارت. 4) كان للمناظر أبلغ الأثر في نهضة البصريّات الأوروبيّة.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15520, 2260, 2, '1) «المناظر» موسوعة كبرى من أوسع ما كُتب في البصريّات في القرون الوسطى (سبع مقالات). 2) جعل البصريّات نقطة تتقاطع فيها أربعة علوم: الهندسة، والفيزياء، وفيزيولوجيا العين، وعلم نفس الإدراك البصري. 3) قام بأهمّ إصلاح في هذا العلم منذ بطليموس، وكان أوّل من شدّد على جعل البصريّات علماً اختبارياً، ويعدّه جورج سارتون أكبر عالم بصريّات قبل ديكارت. 4) كان للمناظر أبلغ الأثر في نهضة البصريّات الأوروبيّة.', 1, '2026-09-30 22:11:41', '2026-09-30 22:11:41'),
(15521, 2261, 1, 'التأريخ عند ابن خلدون فنّ عزيز المذهب. الدافع الأوّل: حياته المضطربة الحافلة بالأحداث وتجربته السياسيّة، فقد اتّصل بالعديد من الملوك والأمراء وشاهد قيام الدول وسقوطها فأراد أن يدوّن ذلك. الدافع الثاني: رغبته في أن يرسم نهجاً سويّاً لتدوين الوقائع، لأنّ كتب من سبقه لم تكن خالية من المطعن والمغمز. وكتابة التأريخ تحتاج إلى كفاءة علميّة وأخلاقيّة عالية.', 1, '2026-09-30 22:11:42', '2026-09-30 22:11:42'),
(15522, 2261, 2, 'التأريخ عند ابن خلدون فنّ عزيز المذهب. الدافع الأوّل: حياته المضطربة الحافلة بالأحداث وتجربته السياسيّة، فقد اتّصل بالعديد من الملوك والأمراء وشاهد قيام الدول وسقوطها فأراد أن يدوّن ذلك. الدافع الثاني: رغبته في أن يرسم نهجاً سويّاً لتدوين الوقائع، لأنّ كتب من سبقه لم تكن خالية من المطعن والمغمز. وكتابة التأريخ تحتاج إلى كفاءة علميّة وأخلاقيّة عالية.', 1, '2026-09-30 22:11:42', '2026-09-30 22:11:42'),
(15523, 2262, 1, 'لأنّ المجتمع يتطوّر وفق قوانين، لا وفق رغبات الأفراد وأهوائهم، و«كلّ حادث من الحوادث، ذاتاً كان أو فعلاً، لا بدّ له من طبيعة تخصّه». فمن عرف طبائع الحوادث استطاع أن يميّز الصدق من الكذب، أمّا من يجهلها فقد ينسب إلى المجتمع ما لا يلائمه، كأن ينسب إلى المجتمع البدوي علوماً متطوّرة وجامعات.', 1, '2026-09-30 22:11:42', '2026-09-30 22:11:42'),
(15524, 2262, 2, 'لأنّ المجتمع يتطوّر وفق قوانين، لا وفق رغبات الأفراد وأهوائهم، و«كلّ حادث من الحوادث، ذاتاً كان أو فعلاً، لا بدّ له من طبيعة تخصّه». فمن عرف طبائع الحوادث استطاع أن يميّز الصدق من الكذب، أمّا من يجهلها فقد ينسب إلى المجتمع ما لا يلائمه، كأن ينسب إلى المجتمع البدوي علوماً متطوّرة وجامعات.', 1, '2026-09-30 22:11:42', '2026-09-30 22:11:42'),
(15525, 2263, 1, '١- مآخذ ومعارف شاملة لجوانب الحياة الاجتماعيّة، كالعلم بقواعد السياسة وطبائع الموجودات وأصول الدول. ٢- المماثلة بين الحاضر والماضي، فمعرفة الحاضر تساعد على فهم الماضي، ومعرفة الماضي تضيء الحاضر. ٣- معرفة طبائع العمران والتنبّه لتبدّلها، فيرفض الخبر المخالف لقواعد هذا العلم ويتحقّق من وقوع الخبر الممكن.', 1, '2026-09-30 22:11:42', '2026-09-30 22:11:42'),
(15526, 2263, 2, '١- مآخذ ومعارف شاملة لجوانب الحياة الاجتماعيّة، كالعلم بقواعد السياسة وطبائع الموجودات وأصول الدول. ٢- المماثلة بين الحاضر والماضي، فمعرفة الحاضر تساعد على فهم الماضي، ومعرفة الماضي تضيء الحاضر. ٣- معرفة طبائع العمران والتنبّه لتبدّلها، فيرفض الخبر المخالف لقواعد هذا العلم ويتحقّق من وقوع الخبر الممكن.', 1, '2026-09-30 22:11:42', '2026-09-30 22:11:42'),
(15527, 2264, 1, 'حياة الإنسان لا تصحّ إلّا بالغذاء، لكنّ قدرة الفرد الواحد قاصرة عن تحصيل حاجته منه وحده. مثال ذلك قوت يوم واحد من الحنطة: لا يحصل إلّا بالطحن والعجن والطبخ، وكلّ عمل منها يحتاج إلى آلات لا تتمّ إلّا بصناعات متعدّدة. إذن لا بدّ من اجتماع كثيرين ليحصل القوت للجميع.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15528, 2264, 2, 'حياة الإنسان لا تصحّ إلّا بالغذاء، لكنّ قدرة الفرد الواحد قاصرة عن تحصيل حاجته منه وحده. مثال ذلك قوت يوم واحد من الحنطة: لا يحصل إلّا بالطحن والعجن والطبخ، وكلّ عمل منها يحتاج إلى آلات لا تتمّ إلّا بصناعات متعدّدة. إذن لا بدّ من اجتماع كثيرين ليحصل القوت للجميع.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15529, 2265, 1, 'الأرض الخصبة توفّر الغذاء بوفرة فتغني أهلها عن السعي وتغريهم بالفراغ والأهواء، والمآكل الدسمة تترك فضلات فاسدة تُضعف نشاطهم البدني والذهني. أمّا الأرض المجدبة فلا توفّر إلّا الضروري فتحثّ أهلها على النشاط والسعي، لذلك هم أحسن حالاً في أبدانهم وأخلاقهم، وأذهانهم أثقب في المعارف. ويلاحظ الأمر نفسه في حيوانات القفر كالمها والزرافة.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15530, 2265, 2, 'الأرض الخصبة توفّر الغذاء بوفرة فتغني أهلها عن السعي وتغريهم بالفراغ والأهواء، والمآكل الدسمة تترك فضلات فاسدة تُضعف نشاطهم البدني والذهني. أمّا الأرض المجدبة فلا توفّر إلّا الضروري فتحثّ أهلها على النشاط والسعي، لذلك هم أحسن حالاً في أبدانهم وأخلاقهم، وأذهانهم أثقب في المعارف. ويلاحظ الأمر نفسه في حيوانات القفر كالمها والزرافة.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15531, 2266, 1, '١- الحياة الاجتماعيّة وبخاصّة طريقة كسب العيش (نحلة المعاش والعادات): فالإنسان ابن عوائده ومألوفه، لا ابن طبيعته ومزاجه، والصنائع تكسب صاحبها عقلاً، وخصوصاً الكتابة والحساب. ٢- العمل الإنساني: فالكسب قيمة الأعمال، وكثرة الأعمال تزيد الثروة؛ فالأمصار الكثيرة العمران أوسع رزقاً، والقليلة السكّان يقلّ رزقها لقلّة الأعمال، والعيون لا تفور إلّا بالعمل.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15532, 2266, 2, '١- الحياة الاجتماعيّة وبخاصّة طريقة كسب العيش (نحلة المعاش والعادات): فالإنسان ابن عوائده ومألوفه، لا ابن طبيعته ومزاجه، والصنائع تكسب صاحبها عقلاً، وخصوصاً الكتابة والحساب. ٢- العمل الإنساني: فالكسب قيمة الأعمال، وكثرة الأعمال تزيد الثروة؛ فالأمصار الكثيرة العمران أوسع رزقاً، والقليلة السكّان يقلّ رزقها لقلّة الأعمال، والعيون لا تفور إلّا بالعمل.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15533, 2267, 1, 'البداوة تقوم على الضروريّ من العيش. فإذا اتّسعت أحوال أهل البدو حصل لهم ما فوق الحاجة من الغنى والرفه، فدعاهم ذلك إلى السكون والدعة والتعاون على الكماليّ (الزائد على الضرورة)، فيوسّعون البيوت ويختطّون المدن والأمصار. إذن الحضارة لا تأتي من خارج البداوة، بل تنمو منها.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15534, 2267, 2, 'البداوة تقوم على الضروريّ من العيش. فإذا اتّسعت أحوال أهل البدو حصل لهم ما فوق الحاجة من الغنى والرفه، فدعاهم ذلك إلى السكون والدعة والتعاون على الكماليّ (الزائد على الضرورة)، فيوسّعون البيوت ويختطّون المدن والأمصار. إذن الحضارة لا تأتي من خارج البداوة، بل تنمو منها.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15535, 2268, 1, 'نحلة المعاش هي التي تحدّد نوع الاجتماع. الزراعة تربط أهلها بالأرض فيستقرّون في القرى، فهم أقرب إلى الحضر. أمّا القائمون على الإبل فمضطرّون إلى التوغّل في القفار، فهم أكثر ظعناً (تنقّلاً). إذن كلّما ابتعدت نحلة المعاش عن الاستقرار اشتدّت البداوة.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43'),
(15536, 2268, 2, 'نحلة المعاش هي التي تحدّد نوع الاجتماع. الزراعة تربط أهلها بالأرض فيستقرّون في القرى، فهم أقرب إلى الحضر. أمّا القائمون على الإبل فمضطرّون إلى التوغّل في القفار، فهم أكثر ظعناً (تنقّلاً). إذن كلّما ابتعدت نحلة المعاش عن الاستقرار اشتدّت البداوة.', 1, '2026-09-30 22:11:43', '2026-09-30 22:11:43');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15537, 2269, 1, 'المبدأ: الإنسان ابن عوائده ومألوفه. ١- انحلال العصبيّة القائمة على صلة الرحم، بسبب اختلاط الأنساب وتوكيل الدفاع إلى الدولة والأسوار. ٢- فقدان الشجاعة، لأنّ جيشاً صار يقوم بالحماية. ٣- فساد الأخلاق، بسبب الترف وكثرة النفقات والحاجة إلى المال، فيكثر الغشّ والتحيّل على المال كالسرقة والربا والمقامرة.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15538, 2269, 2, 'المبدأ: الإنسان ابن عوائده ومألوفه. ١- انحلال العصبيّة القائمة على صلة الرحم، بسبب اختلاط الأنساب وتوكيل الدفاع إلى الدولة والأسوار. ٢- فقدان الشجاعة، لأنّ جيشاً صار يقوم بالحماية. ٣- فساد الأخلاق، بسبب الترف وكثرة النفقات والحاجة إلى المال، فيكثر الغشّ والتحيّل على المال كالسرقة والربا والمقامرة.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15539, 2270, 1, 'البدو يقتصرون على الضروريّ ولا يطلبون الكماليّ لعجزهم عمّا وراءه. ثمّ إنّ التقلّب الدائم يمنعهم من الاستقرار. والصنائع المتطوّرة تحتاج إلى العلم، والعلم لا يتوافر بلا استقرار. فتكون النتيجة قلّة الصنائع عندهم، وبدائيّة ما يوجد منها.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15540, 2270, 2, 'البدو يقتصرون على الضروريّ ولا يطلبون الكماليّ لعجزهم عمّا وراءه. ثمّ إنّ التقلّب الدائم يمنعهم من الاستقرار. والصنائع المتطوّرة تحتاج إلى العلم، والعلم لا يتوافر بلا استقرار. فتكون النتيجة قلّة الصنائع عندهم، وبدائيّة ما يوجد منها.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15541, 2271, 1, 'نقد ابن خلدون الحضارة كثيراً، فلم يترك نقيصة إلّا نسبها إلى أهل الحضر، وربط بين الترف والفساد (انحلال العصبيّة وفقدان الشجاعة وفساد الأخلاق). غير أنّه رأى فيها بعض الحسنات: فهي وراء تقدّم العلوم والصنائع، وتكسب الحضريّ ذكاءً وتفيده عقلاً، حتّى يظنّ البدويّ أنّ الحضريّ قد فاقه في إنسانيّته وعقله.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15542, 2272, 1, 'العصبيّة نزعة تحمل الإنسان على نصرة من ينتسب إليه، والعلاقة الجدليّة تأثير متبادل. فالعصبيّة تمكّن البدو من سكنى القفر، بتعاونهم على الجوع والعطش والحيوان المفترس والغزو، لأنّ المنفردين في أنسابهم لا يقدرون على ذلك. وفي المقابل، عزلة البادية تُبقي الأنساب صريحة فتحفظ العصبيّة. فكلّ منهما يحفظ الآخر.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15543, 2272, 2, 'العصبيّة نزعة تحمل الإنسان على نصرة من ينتسب إليه، والعلاقة الجدليّة تأثير متبادل. فالعصبيّة تمكّن البدو من سكنى القفر، بتعاونهم على الجوع والعطش والحيوان المفترس والغزو، لأنّ المنفردين في أنسابهم لا يقدرون على ذلك. وفي المقابل، عزلة البادية تُبقي الأنساب صريحة فتحفظ العصبيّة. فكلّ منهما يحفظ الآخر.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15544, 2271, 2, 'نقد ابن خلدون الحضارة كثيراً، فلم يترك نقيصة إلّا نسبها إلى أهل الحضر، وربط بين الترف والفساد (انحلال العصبيّة وفقدان الشجاعة وفساد الأخلاق). غير أنّه رأى فيها بعض الحسنات: فهي وراء تقدّم العلوم والصنائع، وتكسب الحضريّ ذكاءً وتفيده عقلاً، حتّى يظنّ البدويّ أنّ الحضريّ قد فاقه في إنسانيّته وعقله.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15545, 2273, 1, 'للدولة عمر كالأشخاص لا يعدو في الغالب ثلاثة أجيال (مائة وعشرون سنة). الجيل الأوّل على خلق البداوة من خشونة وشظف عيش وبسالة واشتراك في المجد، فتبقى العصبيّة محفوظة. الجيل الثاني يتحوّل إلى الحضارة والترف وينفرد صاحب الملك بالمجد، ويبقى لهم الكثير ممّا أدركوه من الجيل الأوّل. الجيل الثالث ينسى عهد البداوة وتسقط العصبيّة بالجملة فيصبحون عيالاً على الدولة. وتستند إلى نظريّة الحسب: الباني، المباشر، المقلّد، الهادم.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15546, 2273, 2, 'للدولة عمر كالأشخاص لا يعدو في الغالب ثلاثة أجيال (مائة وعشرون سنة). الجيل الأوّل على خلق البداوة من خشونة وشظف عيش وبسالة واشتراك في المجد، فتبقى العصبيّة محفوظة. الجيل الثاني يتحوّل إلى الحضارة والترف وينفرد صاحب الملك بالمجد، ويبقى لهم الكثير ممّا أدركوه من الجيل الأوّل. الجيل الثالث ينسى عهد البداوة وتسقط العصبيّة بالجملة فيصبحون عيالاً على الدولة. وتستند إلى نظريّة الحسب: الباني، المباشر، المقلّد، الهادم.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15547, 2274, 1, '١- طور الظفر والاستيلاء على الملك: يُشرك صاحب الدولة أهل عصبيّته في كلّ شيء ولا ينفرد دونهم بشيء. ٢- طور الاستبداد: ينفرد بالملك ويعنى باصطناع الرجال واتّخاذ الموالي. ٣- طور تحصيل ثمرات الملك: يبني القصور والمدن وينظّم شؤون الدولة، فتبلغ أوج قوّتها وتزدهر العلوم. ٤- طور القنوع والمسالمة: يقلّد الأوّلين فيبدأ الركود، لأنّ التقليد مؤذن بالانهيار. ٥- طور الإسراف والتبذير: يتلف ما جمعه أوّلوه في الشهوات والملاذّ. فالأطوار تسير من القوّة إلى الهرم.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15548, 2274, 2, '١- طور الظفر والاستيلاء على الملك: يُشرك صاحب الدولة أهل عصبيّته في كلّ شيء ولا ينفرد دونهم بشيء. ٢- طور الاستبداد: ينفرد بالملك ويعنى باصطناع الرجال واتّخاذ الموالي. ٣- طور تحصيل ثمرات الملك: يبني القصور والمدن وينظّم شؤون الدولة، فتبلغ أوج قوّتها وتزدهر العلوم. ٤- طور القنوع والمسالمة: يقلّد الأوّلين فيبدأ الركود، لأنّ التقليد مؤذن بالانهيار. ٥- طور الإسراف والتبذير: يتلف ما جمعه أوّلوه في الشهوات والملاذّ. فالأطوار تسير من القوّة إلى الهرم.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15549, 2275, 1, 'في أوّل الدولة تكون بدويّة، فترفق بالرعايا وتقتصد في النفقات وتتعفّف عن الأموال. ثمّ مع الاستيلاء يأتي الترف فتعظم النفقات وأعطيات الجند، وينتشر الترف في الرعيّة لأنّ الناس على دين ملوكها، فيضرب صاحب الدولة المكوس على البضائع. ثمّ لا تعود المكوس تفي بالحاجة فتلجأ الدولة إلى القهر وجمع أموال الرعايا. وأخيراً يبذل صاحب الدولة الأموال لمداراة الأمور، فيعظم الهرم ويتجاسر عليها أهل النواحي حتّى تُفضي إلى الهلاك.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15550, 2275, 2, 'في أوّل الدولة تكون بدويّة، فترفق بالرعايا وتقتصد في النفقات وتتعفّف عن الأموال. ثمّ مع الاستيلاء يأتي الترف فتعظم النفقات وأعطيات الجند، وينتشر الترف في الرعيّة لأنّ الناس على دين ملوكها، فيضرب صاحب الدولة المكوس على البضائع. ثمّ لا تعود المكوس تفي بالحاجة فتلجأ الدولة إلى القهر وجمع أموال الرعايا. وأخيراً يبذل صاحب الدولة الأموال لمداراة الأمور، فيعظم الهرم ويتجاسر عليها أهل النواحي حتّى تُفضي إلى الهلاك.', 1, '2026-09-30 22:11:44', '2026-09-30 22:11:44'),
(15551, 2276, 1, 'لأنّ المباني العظيمة موضوعة للعموم وتحتاج إلى اجتماع الأيدي الكثيرة وكثرة التعاون، وهي ليست من الضروريّات فلا يُقبل عليها الناس وحدهم، لذلك تسوقهم الدولة إليها بعصا الملك أو بالترغيب في الثواب والأجر، والملك الكثير المورد وحده يجمع العمّال الكثيرين. فالدولة للعمران كالصورة للمادّة.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15552, 2276, 2, 'لأنّ المباني العظيمة موضوعة للعموم وتحتاج إلى اجتماع الأيدي الكثيرة وكثرة التعاون، وهي ليست من الضروريّات فلا يُقبل عليها الناس وحدهم، لذلك تسوقهم الدولة إليها بعصا الملك أو بالترغيب في الثواب والأجر، والملك الكثير المورد وحده يجمع العمّال الكثيرين. فالدولة للعمران كالصورة للمادّة.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15553, 2277, 1, '1- الدولة الجديدة تقلّ نفقاتها في أوّلها وتخفّف الجباية، فيذهب ترف المصر. 2- أهل الدولة الجديدة يستنكرون ترف الدولة السابقة، فتتراجع الحضارة الأولى. 3- الدولة الجديدة تنقل كرسيّها إلى وطنها، كما نقل العبّاسيّون كرسيّهم من دمشق إلى بغداد (أو كما عدل العرب عن المدائن إلى الكوفة والبصرة).', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15554, 2277, 2, '1- الدولة الجديدة تقلّ نفقاتها في أوّلها وتخفّف الجباية، فيذهب ترف المصر. 2- أهل الدولة الجديدة يستنكرون ترف الدولة السابقة، فتتراجع الحضارة الأولى. 3- الدولة الجديدة تنقل كرسيّها إلى وطنها، كما نقل العبّاسيّون كرسيّهم من دمشق إلى بغداد (أو كما عدل العرب عن المدائن إلى الكوفة والبصرة).', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15555, 2278, 1, 'الحضارة هي التفنّن في الترف، وهي غاية العمران كما أنّ الملك غاية العصبيّة، وللعمران عمر محسوس كعمر الإنسان. فحين تعظم النفقات يلجأ الناس إلى الوسائل المشروعة وغير المشروعة للحصول على المال، فيعمّ الكذب والمقامرة والغشّ والسرقة والربا والانهماك في الشهوات، فيفسد العمران ويأخذ في الهرم.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15556, 2278, 2, 'الحضارة هي التفنّن في الترف، وهي غاية العمران كما أنّ الملك غاية العصبيّة، وللعمران عمر محسوس كعمر الإنسان. فحين تعظم النفقات يلجأ الناس إلى الوسائل المشروعة وغير المشروعة للحصول على المال، فيعمّ الكذب والمقامرة والغشّ والسرقة والربا والانهماك في الشهوات، فيفسد العمران ويأخذ في الهرم.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15557, 2279, 1, '1- المشرق العربيّ: خلال الحروب الصليبيّة التي دامت نحو قرنين، تعرّف الأوروبيّون إلى وجوه عدّة من الحضارة العربيّة الإسلاميّة. 2- جزيرة صقلية: عمل فيها مترجمان معاً على نقل كتاب المجسطي من العربيّة إلى اللاتينيّة. 3- المغرب العربيّ والأندلس، وبخاصّة طليطلة: بعد انتقالها إلى حكم الإسبان قاد رجال دين، مثل المطران ريموندو والشمّاس غونديسالفي، حركة ترجمة واسعة، ومنها انطلقت الترجمة إلى أوروبا.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15558, 2279, 2, '1- المشرق العربيّ: خلال الحروب الصليبيّة التي دامت نحو قرنين، تعرّف الأوروبيّون إلى وجوه عدّة من الحضارة العربيّة الإسلاميّة. 2- جزيرة صقلية: عمل فيها مترجمان معاً على نقل كتاب المجسطي من العربيّة إلى اللاتينيّة. 3- المغرب العربيّ والأندلس، وبخاصّة طليطلة: بعد انتقالها إلى حكم الإسبان قاد رجال دين، مثل المطران ريموندو والشمّاس غونديسالفي، حركة ترجمة واسعة، ومنها انطلقت الترجمة إلى أوروبا.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15559, 2280, 1, 'قبلها كانت العمليّات الحسابيّة بحساب الجُمّل وبالحساب الرومانيّ معقّدة وطويلة. انتقلت الأرقام عبر كتاب الخوارزميّ في الحساب الهنديّ بترجمته اللاتينيّة، ثمّ استعملها فيبوناتشي أوّلَ رياضيّ أوروبيّ. فكانت النتيجة تسهيل الحساب وانتشار هذه الأرقام حتّى صارت عالميّة، وهذا من أهمّ الإنجازات في تاريخ العلوم.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15560, 2280, 2, 'قبلها كانت العمليّات الحسابيّة بحساب الجُمّل وبالحساب الرومانيّ معقّدة وطويلة. انتقلت الأرقام عبر كتاب الخوارزميّ في الحساب الهنديّ بترجمته اللاتينيّة، ثمّ استعملها فيبوناتشي أوّلَ رياضيّ أوروبيّ. فكانت النتيجة تسهيل الحساب وانتشار هذه الأرقام حتّى صارت عالميّة، وهذا من أهمّ الإنجازات في تاريخ العلوم.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15561, 2281, 1, 'يرى بعض المؤرّخين أنّ النهضة الأوروبيّة تعود إلى المخطوطات اليونانيّة التي حملها العلماء البيزنطيّون بعد سقوط القسطنطينيّة، فيجعلون الثقافة العربيّة مجرّد وسيط. لكنّ هذا الحدث ليس الحاسم، فقد عرف الأوروبيّون الفلسفة والعلوم اليونانيّة قبله بنحو ثلاثة قرون عبر ترجماتها العربيّة، كما نقلوا مؤلّفات عربيّة أصيلة. فالعرب لم يكونوا مجرّد وسطاء بل مبدعين.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15562, 2281, 2, 'يرى بعض المؤرّخين أنّ النهضة الأوروبيّة تعود إلى المخطوطات اليونانيّة التي حملها العلماء البيزنطيّون بعد سقوط القسطنطينيّة، فيجعلون الثقافة العربيّة مجرّد وسيط. لكنّ هذا الحدث ليس الحاسم، فقد عرف الأوروبيّون الفلسفة والعلوم اليونانيّة قبله بنحو ثلاثة قرون عبر ترجماتها العربيّة، كما نقلوا مؤلّفات عربيّة أصيلة. فالعرب لم يكونوا مجرّد وسطاء بل مبدعين.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15563, 2282, 1, 'بقي مؤيّدو نظام كوبرنيكوس قلّة قليلة، أوّلهم ريتيكوس الذي نشر أوّل عرض مطبوع للنظريّة، وأشهرهم كبلر وغاليليو. وظهرت أنظمة فلكيّة تُبقي الأرض في مركز العالم، أبرزها نظام تيخو براهي الذي تدور فيه الشمس حول الأرض الثابتة. ودار نقاش حادّ حول نظام الكون (كردّ تيخو على خصومه ومنهم روتمان)، وهذا النقاش مهّد الطريق أمام كبلر.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15564, 2282, 2, 'بقي مؤيّدو نظام كوبرنيكوس قلّة قليلة، أوّلهم ريتيكوس الذي نشر أوّل عرض مطبوع للنظريّة، وأشهرهم كبلر وغاليليو. وظهرت أنظمة فلكيّة تُبقي الأرض في مركز العالم، أبرزها نظام تيخو براهي الذي تدور فيه الشمس حول الأرض الثابتة. ودار نقاش حادّ حول نظام الكون (كردّ تيخو على خصومه ومنهم روتمان)، وهذا النقاش مهّد الطريق أمام كبلر.', 1, '2026-09-30 22:11:45', '2026-09-30 22:11:45'),
(15565, 2283, 1, 'بدأ كبلر بفرض مدار دائريّ للمرّيخ، فظهر فرق ثماني دقائق بين حساباته ورصدين لتيخو. وبخلاف بطليموس الذي سمح لنفسه بتساهل قدره أربع دقائق، رفض كبلر هذا الفرق لأنّه وثق بدقّة أرصاد تيخو، ورأى أنّه لا بدّ للحسابات من أن توافق الرصد موافقة تامّة. فوضع تسع عشرة فرضيّة وأعاد حساباته أكثر من سبعين مرّة حتّى وصل إلى المدار البيضاويّ، ثمّ درس كلّ كوكب على حدة حتّى تأكّد أنّ الحكم يشمل الكواكب كلّها.', 1, '2026-09-30 22:11:46', '2026-09-30 22:11:46'),
(15566, 2283, 2, 'بدأ كبلر بفرض مدار دائريّ للمرّيخ، فظهر فرق ثماني دقائق بين حساباته ورصدين لتيخو. وبخلاف بطليموس الذي سمح لنفسه بتساهل قدره أربع دقائق، رفض كبلر هذا الفرق لأنّه وثق بدقّة أرصاد تيخو، ورأى أنّه لا بدّ للحسابات من أن توافق الرصد موافقة تامّة. فوضع تسع عشرة فرضيّة وأعاد حساباته أكثر من سبعين مرّة حتّى وصل إلى المدار البيضاويّ، ثمّ درس كلّ كوكب على حدة حتّى تأكّد أنّ الحكم يشمل الكواكب كلّها.', 1, '2026-09-30 22:11:46', '2026-09-30 22:11:46'),
(15567, 2284, 1, '1- هي قوانين كمّيّة، ومن أوائل القوانين المكتشفة في علوم الطبيعة (إذا استثنينا قانون أرخميدس). 2- جعلت قوانين السماء وقوانين الأرض واحدة، إذ اعتبر كبلر علم الفلك فرعاً من علم الفيزياء، فقضت على فيزياء أرسطو التي هيمنت أكثر من ألفي سنة. 3- دعمت نظام كوبرنيكوس وصحّحته. 4- كانت أساساً لنظريّة نيوتن في الجاذبيّة التي تُعدّ تأكيداً لقوانين كبلر وتعميماً لها. (تكفي ثلاث أفكار مشروحة.)', 1, '2026-09-30 22:11:46', '2026-09-30 22:11:46'),
(15568, 2284, 2, '1- هي قوانين كمّيّة، ومن أوائل القوانين المكتشفة في علوم الطبيعة (إذا استثنينا قانون أرخميدس). 2- جعلت قوانين السماء وقوانين الأرض واحدة، إذ اعتبر كبلر علم الفلك فرعاً من علم الفيزياء، فقضت على فيزياء أرسطو التي هيمنت أكثر من ألفي سنة. 3- دعمت نظام كوبرنيكوس وصحّحته. 4- كانت أساساً لنظريّة نيوتن في الجاذبيّة التي تُعدّ تأكيداً لقوانين كبلر وتعميماً لها. (تكفي ثلاث أفكار مشروحة.)', 1, '2026-09-30 22:11:46', '2026-09-30 22:11:46'),
(15569, 2285, 1, 'لأنّ القانون الفيزيائيّ الحديث قانون كمّيّ يُعبَّر عنه بلغة الرياضيّات والمعادلات الجبريّة، وقانون أرخميدس لم يبلغ هذه الصياغة، فهو أقرب إلى مبدأ عامّ. ولهذا لا يمكن الكلام على علم فيزياء له قوانين كمّيّة قبل القرن السابع عشر.', 1, '2026-09-30 22:11:46', '2026-09-30 22:11:46'),
(15570, 2285, 2, 'لأنّ القانون الفيزيائيّ الحديث قانون كمّيّ يُعبَّر عنه بلغة الرياضيّات والمعادلات الجبريّة، وقانون أرخميدس لم يبلغ هذه الصياغة، فهو أقرب إلى مبدأ عامّ. ولهذا لا يمكن الكلام على علم فيزياء له قوانين كمّيّة قبل القرن السابع عشر.', 1, '2026-09-30 22:11:46', '2026-09-30 22:11:46'),
(15571, 2286, 1, 'الجاذبيّة قوّة كونيّة، فالأجسام المادّيّة يجذب بعضها بعضاً. التفّاحة تسقط لأنّ الأرض تجذبها. أمّا القمر فلولا جاذبيّة الأرض لتحرّك في خطّ مستقيم مبتعداً عنها (مبدأ القصور الذاتي)، لكنّه يخضع لقوّتين متساويتين: قوّة طاردة تبعده عن مركز الأرض، وقوّة جاذبة تشدّه نحوه، فيبقى في مداره. وهكذا صار قانون واحد يفسّر حركة الأرض وحركة السماء.', 1, '2026-09-30 22:11:47', '2026-09-30 22:11:47'),
(15572, 2286, 2, 'الجاذبيّة قوّة كونيّة، فالأجسام المادّيّة يجذب بعضها بعضاً. التفّاحة تسقط لأنّ الأرض تجذبها. أمّا القمر فلولا جاذبيّة الأرض لتحرّك في خطّ مستقيم مبتعداً عنها (مبدأ القصور الذاتي)، لكنّه يخضع لقوّتين متساويتين: قوّة طاردة تبعده عن مركز الأرض، وقوّة جاذبة تشدّه نحوه، فيبقى في مداره. وهكذا صار قانون واحد يفسّر حركة الأرض وحركة السماء.', 1, '2026-09-30 22:11:47', '2026-09-30 22:11:47'),
(15573, 2287, 1, 'لا تكمن عبقريّة نيوتن في اكتشاف الجاذبيّة، فقد سبقه إليها كثيرون. قال كبلر بقوّة في الشمس شبيهة بالمغناطيس، أمّا نيوتن فاكتشف أنّ قوّة الجاذبيّة كونيّة تشمل كلّ الأجسام، وأنّها الأساس الذي تنضوي تحته القوى الأخرى، ووضع لها معادلة رياضيّة تفسّرها، فصارت الجاذبيّة قانوناً كمّيّاً كونيّاً.', 1, '2026-09-30 22:11:47', '2026-09-30 22:11:47'),
(15574, 2287, 2, 'لا تكمن عبقريّة نيوتن في اكتشاف الجاذبيّة، فقد سبقه إليها كثيرون. قال كبلر بقوّة في الشمس شبيهة بالمغناطيس، أمّا نيوتن فاكتشف أنّ قوّة الجاذبيّة كونيّة تشمل كلّ الأجسام، وأنّها الأساس الذي تنضوي تحته القوى الأخرى، ووضع لها معادلة رياضيّة تفسّرها، فصارت الجاذبيّة قانوناً كمّيّاً كونيّاً.', 1, '2026-09-30 22:11:47', '2026-09-30 22:11:47'),
(15575, 2288, 1, 'الزمان عند نيوتن مطلق، أمّا عند أينشتاين فيختلف بين حدث وآخر بحسب سرعة الجسم، فلا تواقت مطلق بين حدثين. والكتلة عند نيوتن ثابتة، أمّا عند أينشتاين فتزداد كلّما اقتربت سرعتها من سرعة الضوء.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15576, 2288, 2, 'الزمان عند نيوتن مطلق، أمّا عند أينشتاين فيختلف بين حدث وآخر بحسب سرعة الجسم، فلا تواقت مطلق بين حدثين. والكتلة عند نيوتن ثابتة، أمّا عند أينشتاين فتزداد كلّما اقتربت سرعتها من سرعة الضوء.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15577, 2289, 1, '1- ظهور الكهرومغناطيسيّة في القرن التاسع عشر، وقد عجزت معادلات نيوتن عن تفسير ظواهرها الكهربائيّة. 2- الجدل بين نظريّة الجسيمات ونظريّة الموجات، الذي حسم ماكسويل قسماً كبيراً منه بمعادلاته الأربع. 3- اكتشاف ميكلسون ومورلي ثبات سرعة الضوء. 4- نظريّة الكوانتا التي وضعها بلانك. 5- انقباض لورنتس، وفرضيّة البعد الرابع (المدى-الزمان) عند مينكوفسكي. (تكفي ثلاثة.)', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15578, 2289, 2, '1- ظهور الكهرومغناطيسيّة في القرن التاسع عشر، وقد عجزت معادلات نيوتن عن تفسير ظواهرها الكهربائيّة. 2- الجدل بين نظريّة الجسيمات ونظريّة الموجات، الذي حسم ماكسويل قسماً كبيراً منه بمعادلاته الأربع. 3- اكتشاف ميكلسون ومورلي ثبات سرعة الضوء. 4- نظريّة الكوانتا التي وضعها بلانك. 5- انقباض لورنتس، وفرضيّة البعد الرابع (المدى-الزمان) عند مينكوفسكي. (تكفي ثلاثة.)', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15579, 2290, 1, 'المادّة الحيّة تفعل شيئاً، أمّا غير الحيّة فإمّا ميتة وإمّا جامدة. والمادّة الحيّة تتغذّى وتُخرج الفضلات وتستجيب للحرارة والبرودة والضوء والظلمة وتعيد إنتاج الحياة، وهي بنية تعيد إنتاج حيويّتها وتستمرّ حيّة. لذلك لا نعدّ الحاسوب كائناً حيّاً مهما ضاهى أعمال العقل.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15580, 2290, 2, 'المادّة الحيّة تفعل شيئاً، أمّا غير الحيّة فإمّا ميتة وإمّا جامدة. والمادّة الحيّة تتغذّى وتُخرج الفضلات وتستجيب للحرارة والبرودة والضوء والظلمة وتعيد إنتاج الحياة، وهي بنية تعيد إنتاج حيويّتها وتستمرّ حيّة. لذلك لا نعدّ الحاسوب كائناً حيّاً مهما ضاهى أعمال العقل.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15581, 2291, 1, 'هذا القول قاصر وغير صحيح، فالنسبيّة وضعت مطلقات جديدة بصياغة جديدة مكان مطلقات ناقصة. وأينشتاين لم يحاول إلغاء فيزياء نيوتن بل صحّح قواعدها النظريّة، وتبقى فيزياء نيوتن صالحة على الأرض، على قياس الإنسان؛ فالفلك عند نيوتن، كما يرى باشلار، حال خاصّة من علم الفلك الكلّي عند أينشتاين.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15582, 2291, 2, 'هذا القول قاصر وغير صحيح، فالنسبيّة وضعت مطلقات جديدة بصياغة جديدة مكان مطلقات ناقصة. وأينشتاين لم يحاول إلغاء فيزياء نيوتن بل صحّح قواعدها النظريّة، وتبقى فيزياء نيوتن صالحة على الأرض، على قياس الإنسان؛ فالفلك عند نيوتن، كما يرى باشلار، حال خاصّة من علم الفلك الكلّي عند أينشتاين.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15583, 2292, 1, 'الافتراض هو نقطة الانطلاق. إذا تحقّقنا منه بالتفكير والنقد الاختباري (خضع للمنهج الاختباري) صار نظريّة. وإذا اكتفينا بالمنطق وحده صار نظاماً، أي افتراضاً زيدت عليه الوقائع بالتفكير بلا اختبار نقدي. وتتحوّل النظريّة إلى عقيدة حين نعدّها كاملة غير قابلة للتبدّل ونأخذها منطلقاً، ولا نخضعها بعد ذلك للتحقّق الاختباري.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15584, 2292, 2, 'الافتراض هو نقطة الانطلاق. إذا تحقّقنا منه بالتفكير والنقد الاختباري (خضع للمنهج الاختباري) صار نظريّة. وإذا اكتفينا بالمنطق وحده صار نظاماً، أي افتراضاً زيدت عليه الوقائع بالتفكير بلا اختبار نقدي. وتتحوّل النظريّة إلى عقيدة حين نعدّها كاملة غير قابلة للتبدّل ونأخذها منطلقاً، ولا نخضعها بعد ذلك للتحقّق الاختباري.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15585, 2293, 1, 'الفكرة الأولى: الحاجة تولّد الوظيفة والعضو الملائمين. الفكرة الثانية: الصفات المكتسبة تنتقل بالوراثة. مثال: الزرافة مدّت رقبتها عبر الأجيال لتبلغ أوراق الأغصان العالية؛ أو الثيران التي اعتادت التناطح فتكوّنت لها نتوءات صلبة.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15586, 2293, 2, 'الفكرة الأولى: الحاجة تولّد الوظيفة والعضو الملائمين. الفكرة الثانية: الصفات المكتسبة تنتقل بالوراثة. مثال: الزرافة مدّت رقبتها عبر الأجيال لتبلغ أوراق الأغصان العالية؛ أو الثيران التي اعتادت التناطح فتكوّنت لها نتوءات صلبة.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15587, 2294, 1, 'الواجب بذاته هو الذي لا نستطيع أن نتصوّر عدمه، ولا يحتاج إلى شيء آخر يُكسبه الوجود، ومثاله الله. أمّا الواجب بغيره فهو الذي يكتسب وجوده من مبدأ خارج عن ذاته، وهو الممكن بذاته، ويشمل سائر الأشياء الموجودة في هذا العالم، ومثاله الأربعة الواجبة بالأجزاء التي تتألّف منها، أو الاحتراق الذي لا يتحقّق بالفعل إلّا عند التقاء القوّة المحرقة بقوّة أخرى.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15588, 2294, 2, 'الواجب بذاته هو الذي لا نستطيع أن نتصوّر عدمه، ولا يحتاج إلى شيء آخر يُكسبه الوجود، ومثاله الله. أمّا الواجب بغيره فهو الذي يكتسب وجوده من مبدأ خارج عن ذاته، وهو الممكن بذاته، ويشمل سائر الأشياء الموجودة في هذا العالم، ومثاله الأربعة الواجبة بالأجزاء التي تتألّف منها، أو الاحتراق الذي لا يتحقّق بالفعل إلّا عند التقاء القوّة المحرقة بقوّة أخرى.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15589, 2295, 1, 'من صفاته (أربع ممّا يلي): واحد؛ لا إمكان فيه بل هو واجب الوجود من جميع جهاته؛ ثابت لا متغيّر؛ أزليّ أبديّ؛ خير محض مبرّأ من كلّ عيب؛ واحد بسيط ليست فيه كثرة ولا أجزاء؛ ليس بجسم ولا مادّة ولا صورة؛ تامّ ليست له حالة منتظرة ووجوده عين ذاته؛ عقل وعاقل ومعقول، وعشق وعاشق ومعشوق؛ أسعد الموجودات وأعظمها ابتهاجاً؛ لا ندّ له ولا ضدّ. التعليل (واحد ممّا يلي): هو واحد لأنّه لو كان تعيّنه لغيره لكان معلولاً لا واجباً؛ أو ثابت لخلوّه عن معنى القوّة والإمكان؛ أو أزليّ أبديّ لأنّ وجوده من ذاته؛ أو لا ضدّ له لأنّ الضدّ مساوٍ في القوّة ممانع، وكلّ ما سوى الأول معلول.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15590, 2295, 2, 'من صفاته (أربع ممّا يلي): واحد؛ لا إمكان فيه بل هو واجب الوجود من جميع جهاته؛ ثابت لا متغيّر؛ أزليّ أبديّ؛ خير محض مبرّأ من كلّ عيب؛ واحد بسيط ليست فيه كثرة ولا أجزاء؛ ليس بجسم ولا مادّة ولا صورة؛ تامّ ليست له حالة منتظرة ووجوده عين ذاته؛ عقل وعاقل ومعقول، وعشق وعاشق ومعشوق؛ أسعد الموجودات وأعظمها ابتهاجاً؛ لا ندّ له ولا ضدّ. التعليل (واحد ممّا يلي): هو واحد لأنّه لو كان تعيّنه لغيره لكان معلولاً لا واجباً؛ أو ثابت لخلوّه عن معنى القوّة والإمكان؛ أو أزليّ أبديّ لأنّ وجوده من ذاته؛ أو لا ضدّ له لأنّ الضدّ مساوٍ في القوّة ممانع، وكلّ ما سوى الأول معلول.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15591, 2296, 1, 'يخلط الطالب بين البحث عن الله والبحث في ذاته: فالبحث عن الله أمر فطري يعرف فيه الإنسان الشيء من آثاره البادية له، أمّا البحث في ذات الله فيتجاوز طاقة العقل، وفرق كبير بين أن نعرف الشيء من آثاره وأن نأبى الاعتراف به إلّا إذا قلّبناه بين أيدينا وعرفنا ذاته جملة وتفصيلاً. وقد دعا المعرّي إلى عدم البحث في ذات الله لأنّه ليس من نطاق العقل، ومنع القياس بين الله والعالم، مع إيمانه الراسخ بوجوده ووحدانيته.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15592, 2296, 2, 'يخلط الطالب بين البحث عن الله والبحث في ذاته: فالبحث عن الله أمر فطري يعرف فيه الإنسان الشيء من آثاره البادية له، أمّا البحث في ذات الله فيتجاوز طاقة العقل، وفرق كبير بين أن نعرف الشيء من آثاره وأن نأبى الاعتراف به إلّا إذا قلّبناه بين أيدينا وعرفنا ذاته جملة وتفصيلاً. وقد دعا المعرّي إلى عدم البحث في ذات الله لأنّه ليس من نطاق العقل، ومنع القياس بين الله والعالم، مع إيمانه الراسخ بوجوده ووحدانيته.', 1, '2026-09-30 22:11:48', '2026-09-30 22:11:48'),
(15593, 2297, 1, 'الفضائل الأربع هي: الحكمة والشجاعة والعفّة والعدل، وهي أمّهات محاسن الأخلاق والباقي فروعها، وقد اقتبسها الغزالي من نظرية أفلاطون. معانيها (اثنتان ممّا يلي): الحكمة حالة للنفس بها تسوس الغضب والشهوة، وتحملهما على مقتضى الحكمة، وتضبطهما من الاسترسال والانقباض؛ الشجاعة كون قوّة الغضب منقادة للعقل في إقدامها وإحجامها؛ العفّة تأدّب قوّة الشهوة بتأديب العقل والشرع؛ العدل اعتدال هذه الأصول، وعنها تصدر الأخلاق الجميلة.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15594, 2297, 2, 'الفضائل الأربع هي: الحكمة والشجاعة والعفّة والعدل، وهي أمّهات محاسن الأخلاق والباقي فروعها، وقد اقتبسها الغزالي من نظرية أفلاطون. معانيها (اثنتان ممّا يلي): الحكمة حالة للنفس بها تسوس الغضب والشهوة، وتحملهما على مقتضى الحكمة، وتضبطهما من الاسترسال والانقباض؛ الشجاعة كون قوّة الغضب منقادة للعقل في إقدامها وإحجامها؛ العفّة تأدّب قوّة الشهوة بتأديب العقل والشرع؛ العدل اعتدال هذه الأصول، وعنها تصدر الأخلاق الجميلة.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15595, 2298, 1, 'يرى المعري أنّ كلّ اجتماع يولّد الشر والفساد، ومن أمثلته: اجتماع النفس بالجسم، واجتماع العقل بالغريزة، واجتماع الرجل بالمرأة، واجتماع الإنسان بالناس؛ فإذا كثر الناس شاع الفساد، ويتأثّر الأفراد بعضهم ببعض فلا يعرفون إلّا الهوى والجهل والغرور ويتنازعون على المكاسب والمناصب والجاه. لذلك فالعاقل من جرّد نفسه من شواغل البدن زهداً ونسكاً، ومن شواغل المجتمع اعتزالاً وتفرّداً؛ فالعزلة أفضل سبيل للهروب من الشر، لأنّ الشر طبع البشر.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15596, 2298, 2, 'يرى المعري أنّ كلّ اجتماع يولّد الشر والفساد، ومن أمثلته: اجتماع النفس بالجسم، واجتماع العقل بالغريزة، واجتماع الرجل بالمرأة، واجتماع الإنسان بالناس؛ فإذا كثر الناس شاع الفساد، ويتأثّر الأفراد بعضهم ببعض فلا يعرفون إلّا الهوى والجهل والغرور ويتنازعون على المكاسب والمناصب والجاه. لذلك فالعاقل من جرّد نفسه من شواغل البدن زهداً ونسكاً، ومن شواغل المجتمع اعتزالاً وتفرّداً؛ فالعزلة أفضل سبيل للهروب من الشر، لأنّ الشر طبع البشر.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15597, 2299, 1, 'يرى ابن عربي أنّ الله لم يخلق الشر، فالشر المحض لا يوجد بحدّ ذاته، وهو العدم المحض، بخلاف الخير المحض الذي معناه الوجود المحض والنور المحض. والموجودات بعينها ليست خيراً ولا شرّاً؛ فالألم والمرض والفقر والجهل والقبح والخطيئة مُنيت بنقص فعُدّت شروراً، ولو تفادينا هذا النقص لما عادت شروراً. أمّا العلّة الموجبة لاختلاف الأخلاق فهي النفس، وللنفس ثلاث قوى تسمّى أيضاً نفوساً؛ فمن الأخلاق ما يختصّ بإحدى هذه القوى، ومنها ما تشترك فيه قوّتان أو القوى الثلاث؛ فالقوّة الشهوانية إذا كانت مهذّبة مؤدّبة كان صاحبها عفيفاً ضابطاً لنفسه، والقوّة الغضبية من ساسها وأدّبها كان حليماً وقوراً.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15598, 2299, 2, 'يرى ابن عربي أنّ الله لم يخلق الشر، فالشر المحض لا يوجد بحدّ ذاته، وهو العدم المحض، بخلاف الخير المحض الذي معناه الوجود المحض والنور المحض. والموجودات بعينها ليست خيراً ولا شرّاً؛ فالألم والمرض والفقر والجهل والقبح والخطيئة مُنيت بنقص فعُدّت شروراً، ولو تفادينا هذا النقص لما عادت شروراً. أمّا العلّة الموجبة لاختلاف الأخلاق فهي النفس، وللنفس ثلاث قوى تسمّى أيضاً نفوساً؛ فمن الأخلاق ما يختصّ بإحدى هذه القوى، ومنها ما تشترك فيه قوّتان أو القوى الثلاث؛ فالقوّة الشهوانية إذا كانت مهذّبة مؤدّبة كان صاحبها عفيفاً ضابطاً لنفسه، والقوّة الغضبية من ساسها وأدّبها كان حليماً وقوراً.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15599, 2300, 1, 'السعادة (الملكية) الداخلية تكون في الجسد، ومن أمثلتها الصحة والجمال. أمّا السعادة (الملكية) الخارجية فنوعان: مُلك اليد كالمال والمتاع، والأقران كالزوجة والولد والأخ والصديق والأستاذ والصاحب.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15600, 2300, 2, 'السعادة (الملكية) الداخلية تكون في الجسد، ومن أمثلتها الصحة والجمال. أمّا السعادة (الملكية) الخارجية فنوعان: مُلك اليد كالمال والمتاع، والأقران كالزوجة والولد والأخ والصديق والأستاذ والصاحب.', 1, '2026-09-30 22:11:49', '2026-09-30 22:11:49'),
(15601, 2301, 1, 'قال الماوردي بتوزيع العمل بين فئات المجتمع: المزارعون يهتمّون بزراعاتهم ومزارعهم، والصنّاع ينصرفون إلى صنائعهم، والتجّار يتوفّرون على متاجرهم، فلكلّ فئة عملها الذي تألفه. ودعم رأيه بكلام نقله عن ملك قال لوزيره: الناس أربع طبقات؛ طبقة للفروسية أُلحقت بالشرف، وطبقة لإقامة الديانة أُلحقت بالكفاية، وطبقة للزراعة والعمارة قُدّرت على الإنصاف، وطبقة للمهن. وإذا انتقلت فئة بأمر السلطان إلى عمل لا تألفه طرأ اختلال على النظام والحياة الاجتماعية، لأنّ ذلك يُخرج العملية الاجتماعية عن عادياتها ومألوفاتها، وقد يؤدّي إلى وهن في السلطة وربّما إلى ضياعها.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15602, 2301, 2, 'قال الماوردي بتوزيع العمل بين فئات المجتمع: المزارعون يهتمّون بزراعاتهم ومزارعهم، والصنّاع ينصرفون إلى صنائعهم، والتجّار يتوفّرون على متاجرهم، فلكلّ فئة عملها الذي تألفه. ودعم رأيه بكلام نقله عن ملك قال لوزيره: الناس أربع طبقات؛ طبقة للفروسية أُلحقت بالشرف، وطبقة لإقامة الديانة أُلحقت بالكفاية، وطبقة للزراعة والعمارة قُدّرت على الإنصاف، وطبقة للمهن. وإذا انتقلت فئة بأمر السلطان إلى عمل لا تألفه طرأ اختلال على النظام والحياة الاجتماعية، لأنّ ذلك يُخرج العملية الاجتماعية عن عادياتها ومألوفاتها، وقد يؤدّي إلى وهن في السلطة وربّما إلى ضياعها.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15603, 2302, 1, 'السياسة الذاتية هي معرفة الإنسان نفسه وأخلاقه، وتفقّد أفعاله وأقواله، والنظر في أموره. وغرض السياسات أنّ النفس هي التي ينبغي أن توجّه الجسد وتسوسه؛ فأيّ نفس أحسنت سياسة جسدها كما يجب أمكنها سياسة الأهل والخدم، ومن ساس أهله بسيرة عادلة أمكنه أن يسوس قبيلة.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15604, 2302, 2, 'السياسة الذاتية هي معرفة الإنسان نفسه وأخلاقه، وتفقّد أفعاله وأقواله، والنظر في أموره. وغرض السياسات أنّ النفس هي التي ينبغي أن توجّه الجسد وتسوسه؛ فأيّ نفس أحسنت سياسة جسدها كما يجب أمكنها سياسة الأهل والخدم، ومن ساس أهله بسيرة عادلة أمكنه أن يسوس قبيلة.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15605, 2303, 1, 'ذكر ابن خلدون ستّة مصادر للمعاش، ثمّ أغفل الحديث عن الاصطياد، واعتبر الجباية وجهاً خاصّاً بأهل الملك والسلطان، وأدخل تربية الحيوانات الداجنة في الفلاحة، فبقيت ثلاث نحل أساسية: الفلاحة والصناعة والتجارة. والنحلة المعاشية تؤثّر في طبائع المرء وسجاياه: فالتاجر الذي يتعاطى البيع والشراء طلباً للربح لا بدّ له من المكايسة والمماحكة وممارسة الخصومات، وهذه أوصاف تُنقص من الذكاء والمروءة. أمّا الصنائع فتُكسب صاحبها عقلاً، لأنّ النفس الناطقة تنتقل من القوة إلى الفعل بتجدّد العلوم والإدراكات، والقريحة كالضرع يدرّ بالامتراء ويجفّ بالترك والإهمال.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15606, 2303, 2, 'ذكر ابن خلدون ستّة مصادر للمعاش، ثمّ أغفل الحديث عن الاصطياد، واعتبر الجباية وجهاً خاصّاً بأهل الملك والسلطان، وأدخل تربية الحيوانات الداجنة في الفلاحة، فبقيت ثلاث نحل أساسية: الفلاحة والصناعة والتجارة. والنحلة المعاشية تؤثّر في طبائع المرء وسجاياه: فالتاجر الذي يتعاطى البيع والشراء طلباً للربح لا بدّ له من المكايسة والمماحكة وممارسة الخصومات، وهذه أوصاف تُنقص من الذكاء والمروءة. أمّا الصنائع فتُكسب صاحبها عقلاً، لأنّ النفس الناطقة تنتقل من القوة إلى الفعل بتجدّد العلوم والإدراكات، والقريحة كالضرع يدرّ بالامتراء ويجفّ بالترك والإهمال.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15607, 2304, 1, 'الرئيس الأول بمنزلة السبب الأول بالنسبة إلى الموجودات وبمنزلة القلب من البدن، ولا يرأسه إنسان آخر. خصاله نوعان: مكتسبة أساسها بلوغ رتبة العقل المستفاد، واتّصال العقل الفعّال به، وجودة التخيّل، والقدرة على الإرشاد إلى السعادة؛ وفطرية عدّتها اثنتا عشرة خصلة، منها جودة الفهم وحسن العبارة وحبّ التعلّم والصدق والعدل وقوّة العزيمة، وهو نادر لا يوجد إلّا الواحد بعد الواحد. أمّا الرئيس الثاني فيكون إذا لم يوجد الأول، فتؤخذ الشرائع والسنن التي شرّعها الأول، ويكفي أن تجتمع فيه ستّ خصال. وسبب قلّة خصاله أنّ الفارابي نبّه إلى صعوبة اجتماع الخصال الأولى في إنسان واحد، وأنّ الرئيس الثاني يأخذ بالشرائع التي وضعها الرئيس الأول، ولهذا لم يشترط فيه النبوّة بل اكتفى بالحكمة.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15608, 2304, 2, 'الرئيس الأول بمنزلة السبب الأول بالنسبة إلى الموجودات وبمنزلة القلب من البدن، ولا يرأسه إنسان آخر. خصاله نوعان: مكتسبة أساسها بلوغ رتبة العقل المستفاد، واتّصال العقل الفعّال به، وجودة التخيّل، والقدرة على الإرشاد إلى السعادة؛ وفطرية عدّتها اثنتا عشرة خصلة، منها جودة الفهم وحسن العبارة وحبّ التعلّم والصدق والعدل وقوّة العزيمة، وهو نادر لا يوجد إلّا الواحد بعد الواحد. أمّا الرئيس الثاني فيكون إذا لم يوجد الأول، فتؤخذ الشرائع والسنن التي شرّعها الأول، ويكفي أن تجتمع فيه ستّ خصال. وسبب قلّة خصاله أنّ الفارابي نبّه إلى صعوبة اجتماع الخصال الأولى في إنسان واحد، وأنّ الرئيس الثاني يأخذ بالشرائع التي وضعها الرئيس الأول، ولهذا لم يشترط فيه النبوّة بل اكتفى بالحكمة.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15609, 2305, 1, 'تصوّر الفارابي المدينة الفاضلة على غرار البدن التام الصحيح: فكما تتعاون أعضاء البدن على تتميم حياة الحيوان وحفظها، كذلك يخدم أفراد المدينة بعضهم بعضاً، ورئيسها بمنزلة القلب من البدن. لكنّ أعضاء البدن طبيعية، أمّا الهيئات والملكات التي يفعل بها أهل المدينة أفعالهم فإرادية، فالاجتماع وإن كان فطرياً تعبير عن إرادة أبنائه واختيارهم. وترتيب المدينة لا يختلف عن ترتيب النظام الكوني في نظرية الفيض: فنسبة السبب الأول إلى سائر الموجودات كنسبة ملك المدينة إلى سائر أجزائها، والعقول البريئة من المادة تقرب من الأول، ودونها الأجسام السماوية، ثمّ الأجسام الهيولانية. والسعادة لا تتحقّق إلّا إذا انتظمت أجزاء المدينة وترتّبت وفقاً للنظام الكوني.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15610, 2305, 2, 'تصوّر الفارابي المدينة الفاضلة على غرار البدن التام الصحيح: فكما تتعاون أعضاء البدن على تتميم حياة الحيوان وحفظها، كذلك يخدم أفراد المدينة بعضهم بعضاً، ورئيسها بمنزلة القلب من البدن. لكنّ أعضاء البدن طبيعية، أمّا الهيئات والملكات التي يفعل بها أهل المدينة أفعالهم فإرادية، فالاجتماع وإن كان فطرياً تعبير عن إرادة أبنائه واختيارهم. وترتيب المدينة لا يختلف عن ترتيب النظام الكوني في نظرية الفيض: فنسبة السبب الأول إلى سائر الموجودات كنسبة ملك المدينة إلى سائر أجزائها، والعقول البريئة من المادة تقرب من الأول، ودونها الأجسام السماوية، ثمّ الأجسام الهيولانية. والسعادة لا تتحقّق إلّا إذا انتظمت أجزاء المدينة وترتّبت وفقاً للنظام الكوني.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15611, 2306, 1, 'البراهين هي: برهان المغايرة، وبرهان البساطة، والبرهان الميتافيزيقي المعروف ببرهان المشابهة والمشاركة. الشرح (واحد ممّا يلي): برهان المغايرة: اتصال النفس بالبدن لا يخلو من احتمالات ثلاثة أثبت ابن سينا فسادها جميعاً، فيبقى أنّ الاتصال عرضي لا جوهري، وأنّ طبيعة النفس غير طبيعة البدن. برهان البساطة: الوجود صفة ذاتية في النفس، فلو كان الفناء صفة ذاتية فيها أيضاً لأصبح البسيط مركّباً من الوصف ونقيضه، وهذا مستحيل؛ فالنفس خالدة لأنّها جوهر بسيط غير مركّب، بخلاف البدن المركّب الذي يعتريه الفناء بتحلّل أجزائه. البرهان الميتافيزيقي: النفس من عالم الأمر المفارق للمادة، فلا بدّ من خلودها لبقاء خالقها، بخلاف البدن الذي هو من عالم العناصر؛ والنفس أصل والبدن تابع لها وهي المدبّرة له، فإذا فسد البدن لا تفسد النفس بفساده.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15612, 2306, 2, 'البراهين هي: برهان المغايرة، وبرهان البساطة، والبرهان الميتافيزيقي المعروف ببرهان المشابهة والمشاركة. الشرح (واحد ممّا يلي): برهان المغايرة: اتصال النفس بالبدن لا يخلو من احتمالات ثلاثة أثبت ابن سينا فسادها جميعاً، فيبقى أنّ الاتصال عرضي لا جوهري، وأنّ طبيعة النفس غير طبيعة البدن. برهان البساطة: الوجود صفة ذاتية في النفس، فلو كان الفناء صفة ذاتية فيها أيضاً لأصبح البسيط مركّباً من الوصف ونقيضه، وهذا مستحيل؛ فالنفس خالدة لأنّها جوهر بسيط غير مركّب، بخلاف البدن المركّب الذي يعتريه الفناء بتحلّل أجزائه. البرهان الميتافيزيقي: النفس من عالم الأمر المفارق للمادة، فلا بدّ من خلودها لبقاء خالقها، بخلاف البدن الذي هو من عالم العناصر؛ والنفس أصل والبدن تابع لها وهي المدبّرة له، فإذا فسد البدن لا تفسد النفس بفساده.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15613, 2307, 1, 'الاتفاق: يتّفق الطرفان على مبدأ خلود النفس؛ فهي عند ابن سينا جوهر بسيط مجرّد عن المادة خالد لا يفنى، وعند إخوان الصفاء حسّاسة درّاكة بالطبع لا تموت ولا تفنى بل تبقى مؤبّدة، إمّا ملتذّة وإمّا مؤتلمة. الاختلاف في المعاد: يرى ابن سينا أنّ عودة البدن محالة لأنّ الجسم لا يتكوّن إلّا من طريق طبيعي لا يتيسّر في العالم الآخر، فالمعاد عنده روحاني لا جسماني. أمّا إخوان الصفاء فيرون أنّ الرأي الأجود في البعث هو ردّ النفوس إلى الأجساد بعينها أو إلى أجساد أخرى تقوم مقامها، والبعث عندهم انتباه النفس من نوم غفلتها.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15614, 2307, 2, 'الاتفاق: يتّفق الطرفان على مبدأ خلود النفس؛ فهي عند ابن سينا جوهر بسيط مجرّد عن المادة خالد لا يفنى، وعند إخوان الصفاء حسّاسة درّاكة بالطبع لا تموت ولا تفنى بل تبقى مؤبّدة، إمّا ملتذّة وإمّا مؤتلمة. الاختلاف في المعاد: يرى ابن سينا أنّ عودة البدن محالة لأنّ الجسم لا يتكوّن إلّا من طريق طبيعي لا يتيسّر في العالم الآخر، فالمعاد عنده روحاني لا جسماني. أمّا إخوان الصفاء فيرون أنّ الرأي الأجود في البعث هو ردّ النفوس إلى الأجساد بعينها أو إلى أجساد أخرى تقوم مقامها، والبعث عندهم انتباه النفس من نوم غفلتها.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15615, 2308, 1, 'حركة البدن تكاد تتوقّف تماماً عند النوم، ومع ذلك تظلّ النفس باقية وحركتها مستمرّة، ويظهر ذلك في اطّلاعها على المغيّبات؛ وهذا دليل يقيني على استقلال النفس وبقائها. وكذلك من يكون مالكاً لشيء متصرّفاً فيه، إذا بطل ذلك الشيء لم يبطل المالك ببطلانه؛ فالنفس هي الأصل المدبّر للبدن، والبدن تابع لها، فإذا فسد البدن لا تفسد النفس بفساده.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15616, 2308, 2, 'حركة البدن تكاد تتوقّف تماماً عند النوم، ومع ذلك تظلّ النفس باقية وحركتها مستمرّة، ويظهر ذلك في اطّلاعها على المغيّبات؛ وهذا دليل يقيني على استقلال النفس وبقائها. وكذلك من يكون مالكاً لشيء متصرّفاً فيه، إذا بطل ذلك الشيء لم يبطل المالك ببطلانه؛ فالنفس هي الأصل المدبّر للبدن، والبدن تابع لها، فإذا فسد البدن لا تفسد النفس بفساده.', 1, '2026-09-30 22:11:50', '2026-09-30 22:11:50'),
(15617, 2309, 1, 'أوّلاً: العلم يسعى إلى فهم الطبيعة وتفسيرها، بينما تسعى التكنولوجيا إلى استخدامها والإفادة منها. ثانياً: العلم قوانين ومعادلات لا يمكن وصفها بالخير أو الشرّ، بل هي في جوهرها أقرب إلى الخير، بينما نتاجات التكنولوجيا هي بالضرورة إمّا خيّرة وإمّا شرّيرة. ومثال ذلك الطاقة النووية التي تولّد الكهرباء أو تصير سلاحاً مدمّراً.', 1, '2026-09-30 22:11:51', '2026-09-30 22:11:51'),
(15618, 2309, 2, 'أوّلاً: العلم يسعى إلى فهم الطبيعة وتفسيرها، بينما تسعى التكنولوجيا إلى استخدامها والإفادة منها. ثانياً: العلم قوانين ومعادلات لا يمكن وصفها بالخير أو الشرّ، بل هي في جوهرها أقرب إلى الخير، بينما نتاجات التكنولوجيا هي بالضرورة إمّا خيّرة وإمّا شرّيرة. ومثال ذلك الطاقة النووية التي تولّد الكهرباء أو تصير سلاحاً مدمّراً.', 1, '2026-09-30 22:11:51', '2026-09-30 22:11:51'),
(15619, 2310, 1, 'بلغ التقدّم في الأبحاث البيولوجية والجينية مبلغاً لا سابق له، وينذر بمخاطر تتعلّق بوجود الكائن البشري نفسه. فالدخول إلى العالم الداخلي للجينة والقدرة على التلاعب بمكوّناتها ومعادلاتها يفتحان الباب أمام احتمالات أغرب من الخيال، منها (يكفي اثنان): تغيير جنس المولود، تغيير الصفات الموروثة، التحكّم بالذكاء، إنتاج نسخ من أيّ كائن بيولوجي أو حتى بشري. وهذه احتمالات تدمّر كلّ الثوابت الإنسانية التي نعرفها، وتدفع إلى فوضى نعرف أين تبدأ ولكن ما من أحد يعرف نهايتها.', 1, '2026-09-30 22:11:51', '2026-09-30 22:11:51'),
(15620, 2310, 2, 'بلغ التقدّم في الأبحاث البيولوجية والجينية مبلغاً لا سابق له، وينذر بمخاطر تتعلّق بوجود الكائن البشري نفسه. فالدخول إلى العالم الداخلي للجينة والقدرة على التلاعب بمكوّناتها ومعادلاتها يفتحان الباب أمام احتمالات أغرب من الخيال، منها (يكفي اثنان): تغيير جنس المولود، تغيير الصفات الموروثة، التحكّم بالذكاء، إنتاج نسخ من أيّ كائن بيولوجي أو حتى بشري. وهذه احتمالات تدمّر كلّ الثوابت الإنسانية التي نعرفها، وتدفع إلى فوضى نعرف أين تبدأ ولكن ما من أحد يعرف نهايتها.', 1, '2026-09-30 22:11:51', '2026-09-30 22:11:51'),
(15621, 2311, 1, 'الحلّ هو الاتزان والموازنة بين حاجات التوسّع التكنولوجي من جهة، والمطالب الاجتماعية والبيئية والإنسانية من جهة ثانية، فالمطلوب أنسنة تكون في مستوى الأتمتة، حتى لا يتحوّل البشر إلى أرقام وأجزاء في آلة ضخمة. وبعض الحلّ تربية وثقافة وقيم وسياسة قادرة على ضبط التوسّع وإعادة توجيهه ليخدم الإنسان والمجتمع. ومسؤولية ذلك لا تقع على التقنيين وحدهم، بل على الفلاسفة وعلماء الاجتماع والتربية كذلك.', 1, '2026-09-30 22:11:51', '2026-09-30 22:11:51'),
(15622, 2311, 2, 'الحلّ هو الاتزان والموازنة بين حاجات التوسّع التكنولوجي من جهة، والمطالب الاجتماعية والبيئية والإنسانية من جهة ثانية، فالمطلوب أنسنة تكون في مستوى الأتمتة، حتى لا يتحوّل البشر إلى أرقام وأجزاء في آلة ضخمة. وبعض الحلّ تربية وثقافة وقيم وسياسة قادرة على ضبط التوسّع وإعادة توجيهه ليخدم الإنسان والمجتمع. ومسؤولية ذلك لا تقع على التقنيين وحدهم، بل على الفلاسفة وعلماء الاجتماع والتربية كذلك.', 1, '2026-09-30 22:11:51', '2026-09-30 22:11:51'),
(15623, 2312, 1, 'عناصر التواصل: المرسِل، والمرسَل إليه، ومضمون الرسالة، ونظامها الرمزي (وهو الوسيلة اللغوية للرسالة). والتواصل متداخل لأنّ المرسِل يتحوّل تلقائياً إلى مرسَل إليه، والعكس صحيح، بينما يبقى النظام الرمزي نفسه.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15624, 2312, 2, 'عناصر التواصل: المرسِل، والمرسَل إليه، ومضمون الرسالة، ونظامها الرمزي (وهو الوسيلة اللغوية للرسالة). والتواصل متداخل لأنّ المرسِل يتحوّل تلقائياً إلى مرسَل إليه، والعكس صحيح، بينما يبقى النظام الرمزي نفسه.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15625, 2313, 1, 'لغة الحيوان على العموم ملتصقة بالحاجات والحالات البيولوجية الغريزية، والانعكاس الشرطي هو اللغة الحيوانية المكتسبة (كهروب القرود عند سماع زئير الأسد). أمّا اللسان الإنساني فاصطلاحي ورمزي ومبتدع ومستخدم بوعي، ويدلّ على حالات ومواقف لا حدّ لها، لأنّه ملازم للفكر وآفاقه مفتوحة على كلّ أنواع الدلالات والاتصالات. ويقول بافلوف إنّ الكلام عند الإنسان مؤثّر شرطي كما عند الحيوان، لكنّ الكلمة تحمل أبعاداً وتشمل أشياء عدّة لا يقوم بها أيّ مؤثّر آخر، فلا تُقارَن لا من حيث الكمّ ولا من حيث الكيف بأيّ مؤثّر شرطي حيواني.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15626, 2313, 2, 'لغة الحيوان على العموم ملتصقة بالحاجات والحالات البيولوجية الغريزية، والانعكاس الشرطي هو اللغة الحيوانية المكتسبة (كهروب القرود عند سماع زئير الأسد). أمّا اللسان الإنساني فاصطلاحي ورمزي ومبتدع ومستخدم بوعي، ويدلّ على حالات ومواقف لا حدّ لها، لأنّه ملازم للفكر وآفاقه مفتوحة على كلّ أنواع الدلالات والاتصالات. ويقول بافلوف إنّ الكلام عند الإنسان مؤثّر شرطي كما عند الحيوان، لكنّ الكلمة تحمل أبعاداً وتشمل أشياء عدّة لا يقوم بها أيّ مؤثّر آخر، فلا تُقارَن لا من حيث الكمّ ولا من حيث الكيف بأيّ مؤثّر شرطي حيواني.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15627, 2314, 1, 'العادة عندما تُكتسب تصبح جزءاً دائماً من كياننا ومن شخصيتنا، أي تصبح طبيعة ثانية، فهي مهارة مكتسبة ودائمة؛ وكما يقول أرسطو، إذا كانت الغريزة طبيعة أولى فالعادة طبيعة ثانية. وتصوّر الفيزيولوجيون أنّ كلّ حركة تُترجم في الجهاز العصبي بدرب يُشقّ بين الخلايا، فإذا تكرّرت الحركة رسخ هذا الدرب، فالعادات دروب ترابطية محفورة بين خلايا الجهاز العصبي. غير أنّ هذا الرأي ما زال موضع نقاش وجدل، ولا يُعرف حتى الآن أصحيح هو أم غير صحيح.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15628, 2314, 2, 'العادة عندما تُكتسب تصبح جزءاً دائماً من كياننا ومن شخصيتنا، أي تصبح طبيعة ثانية، فهي مهارة مكتسبة ودائمة؛ وكما يقول أرسطو، إذا كانت الغريزة طبيعة أولى فالعادة طبيعة ثانية. وتصوّر الفيزيولوجيون أنّ كلّ حركة تُترجم في الجهاز العصبي بدرب يُشقّ بين الخلايا، فإذا تكرّرت الحركة رسخ هذا الدرب، فالعادات دروب ترابطية محفورة بين خلايا الجهاز العصبي. غير أنّ هذا الرأي ما زال موضع نقاش وجدل، ولا يُعرف حتى الآن أصحيح هو أم غير صحيح.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15629, 2315, 1, 'مخاطر اللغة هي المخاطر الناجمة عن العادة: الرتابة والتكرار التلقائي الأعمى وفقدان المبادرة الذاتية وتعطيل الذكاء والابتداع، وتظهر خصوصاً في الآداب والفنون والعلوم. فهذا الأديب الذي يكرّر أفكاراً سبق له أن ابتدعها لا تثبت موهبته، إذ لا يمكن الوصول إلى أفكار جديدة بصيغ لغوية قديمة مستهلكة؛ فاللغة هنا صارت عائقاً أمام الإبداع بعد أن كانت أداته. ولذلك يجد المبدع نفسه ملزماً بابتداع لغته الخاصة بشكل دائم لا يتوقّف.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15630, 2315, 2, 'مخاطر اللغة هي المخاطر الناجمة عن العادة: الرتابة والتكرار التلقائي الأعمى وفقدان المبادرة الذاتية وتعطيل الذكاء والابتداع، وتظهر خصوصاً في الآداب والفنون والعلوم. فهذا الأديب الذي يكرّر أفكاراً سبق له أن ابتدعها لا تثبت موهبته، إذ لا يمكن الوصول إلى أفكار جديدة بصيغ لغوية قديمة مستهلكة؛ فاللغة هنا صارت عائقاً أمام الإبداع بعد أن كانت أداته. ولذلك يجد المبدع نفسه ملزماً بابتداع لغته الخاصة بشكل دائم لا يتوقّف.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15631, 2316, 1, 'تفسّر نظرية الترابط الآلي العادة بأنّها حركة مركّبة من مجموعة حركات بسيطة متعاقبة، فكلّ حركة بسيطة تصير مؤثراً يُحدث الاستجابة التالية، وهذه تتحوّل بدورها إلى مؤثر جديد حتى تكتمل الحركة الكلّية؛ ومثالها حفظ قصيدة، إذ يستدعي كلّ مقطع المقطع الذي يليه. لكنّ التكرار وحده لا يكفي: فلا يوجد تكرار حقيقي، إذ لو كرّرنا حركاتنا الأولى المضطربة كما هي لما حصلنا على حركة سريعة ناجحة، وقد أظهرت تجربة تعلّم الطباعة أنّ في كلّ محاولة إلغاءً لحركة سابقة خاطئة أو زائدة. كما أنّ قانون يوست يشترط الوقت الأفضل بين التمارين، والطرق الناشطة أسرع من السلبية، والعادة في البدء فكرة للرغبة والإرادة والجهد الشخصي والذكاء دور أساسي في بلوغها.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15632, 2316, 2, 'تفسّر نظرية الترابط الآلي العادة بأنّها حركة مركّبة من مجموعة حركات بسيطة متعاقبة، فكلّ حركة بسيطة تصير مؤثراً يُحدث الاستجابة التالية، وهذه تتحوّل بدورها إلى مؤثر جديد حتى تكتمل الحركة الكلّية؛ ومثالها حفظ قصيدة، إذ يستدعي كلّ مقطع المقطع الذي يليه. لكنّ التكرار وحده لا يكفي: فلا يوجد تكرار حقيقي، إذ لو كرّرنا حركاتنا الأولى المضطربة كما هي لما حصلنا على حركة سريعة ناجحة، وقد أظهرت تجربة تعلّم الطباعة أنّ في كلّ محاولة إلغاءً لحركة سابقة خاطئة أو زائدة. كما أنّ قانون يوست يشترط الوقت الأفضل بين التمارين، والطرق الناشطة أسرع من السلبية، والعادة في البدء فكرة للرغبة والإرادة والجهد الشخصي والذكاء دور أساسي في بلوغها.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15635, 2318, 1, 'الميل طاقة حيويّة كامنة، غير مرئيّة، قصديّة، تحرّك الكائن (الإنسان والحيوان) باتجاه هدف معيّن، وقد تكون غير واعية لدى صاحبها، ولا تظهر إلا في حالة نشاط أو حركة، أو في حالة عاطفيّة انفعاليّة. أمّا الغريزة فميل حيوانيّ يشبعه الحيوان بمهارة فطريّة غير مكتسبة، تختلف من جنس إلى آخر، كبناء العشّ عند الطير والقفير عند النحل والشبكة عند العنكبوت. فالغريزة نوع من الميول، ولفظ الميل أعمّ وأشمل.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15636, 2318, 2, 'الميل طاقة حيويّة كامنة، غير مرئيّة، قصديّة، تحرّك الكائن (الإنسان والحيوان) باتجاه هدف معيّن، وقد تكون غير واعية لدى صاحبها، ولا تظهر إلا في حالة نشاط أو حركة، أو في حالة عاطفيّة انفعاليّة. أمّا الغريزة فميل حيوانيّ يشبعه الحيوان بمهارة فطريّة غير مكتسبة، تختلف من جنس إلى آخر، كبناء العشّ عند الطير والقفير عند النحل والشبكة عند العنكبوت. فالغريزة نوع من الميول، ولفظ الميل أعمّ وأشمل.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15637, 2319, 1, 'يخلط كونديّاك بين مستويين مختلفين من الوعي: فالميل على العموم سلوك عفويّ غير واعٍ، أمّا الرغبة فسلوك واعٍ لغايته ولهدفه (ميل واعٍ لذاته ولموضوعه)، وبهذا الوعي يمكن أن تتحوّل إلى فعل إراديّ من غير أن تكون الفعل الإراديّ نفسه. ثمّ إنّ ذكرى اللذّة لا تخلق ميلاً، بل العكس هو الصحيح: لولا ميل مسبق لما كانت هناك لذّة أصلاً، فالميل شرط اللذّة.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15638, 2319, 2, 'يخلط كونديّاك بين مستويين مختلفين من الوعي: فالميل على العموم سلوك عفويّ غير واعٍ، أمّا الرغبة فسلوك واعٍ لغايته ولهدفه (ميل واعٍ لذاته ولموضوعه)، وبهذا الوعي يمكن أن تتحوّل إلى فعل إراديّ من غير أن تكون الفعل الإراديّ نفسه. ثمّ إنّ ذكرى اللذّة لا تخلق ميلاً، بل العكس هو الصحيح: لولا ميل مسبق لما كانت هناك لذّة أصلاً، فالميل شرط اللذّة.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15639, 2320, 1, 'لم تعد السيجارة عند المدخّن حاجة عضويّة فحسب، بل ارتبطت على امتداد الممارسة بمعانٍ اجتماعيّة وعاطفيّة: صارت مرتبطة بانعكاس شرطيّ بفنجان القهوة أو بالانتهاء من عمل ما، وصارت ترمز إلى السمر مع الأصدقاء. فعادة التدخين نقطة تتقاطع فيها مجموعة من الميول، وهذا ما يفسّر صعوبة التخلّي عنها. والعادة لا تخلق حاجة جديدة ولا تزيد قوّة ميولنا، بل تسهّل إشباع ميل قائم وتختار له أسلوباً معيّناً.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15640, 2320, 2, 'لم تعد السيجارة عند المدخّن حاجة عضويّة فحسب، بل ارتبطت على امتداد الممارسة بمعانٍ اجتماعيّة وعاطفيّة: صارت مرتبطة بانعكاس شرطيّ بفنجان القهوة أو بالانتهاء من عمل ما، وصارت ترمز إلى السمر مع الأصدقاء. فعادة التدخين نقطة تتقاطع فيها مجموعة من الميول، وهذا ما يفسّر صعوبة التخلّي عنها. والعادة لا تخلق حاجة جديدة ولا تزيد قوّة ميولنا، بل تسهّل إشباع ميل قائم وتختار له أسلوباً معيّناً.', 1, '2026-09-30 22:11:55', '2026-09-30 22:11:55'),
(15641, 2321, 1, 'كانت العبارة المستعملة في المؤلفات الفلسفية التقليدية وفي علم النفس التقليدي هي الشخص، ولم تبرز مفردة الشخصيّة إلّا بعد منتصف القرن العشرين بقليل في المؤلفات الأوروبية ثمّ العربية. والشخصيّة من وجهة نظر علم النفس وظيفة يعي بها الفرد ذاته بوصفه أنا. والوحدة أنّ الفرد يوحّد في وعيه كلّ ما هو موجود في حياته النفسية؛ والفرادة أنّ الفرد واحد ووحيد لا شبيه له. وهو ذاته مستمرّ ثابت عبر مراحل حياته (الهويّة الشخصيّة)، من غير أن تلغي الوحدة تعدّد مواقفه، فالشخصيّة متطوّرة تُغتنى باستمرار.', 1, '2026-09-30 22:11:56', '2026-09-30 22:11:56'),
(15642, 2321, 2, 'كانت العبارة المستعملة في المؤلفات الفلسفية التقليدية وفي علم النفس التقليدي هي الشخص، ولم تبرز مفردة الشخصيّة إلّا بعد منتصف القرن العشرين بقليل في المؤلفات الأوروبية ثمّ العربية. والشخصيّة من وجهة نظر علم النفس وظيفة يعي بها الفرد ذاته بوصفه أنا. والوحدة أنّ الفرد يوحّد في وعيه كلّ ما هو موجود في حياته النفسية؛ والفرادة أنّ الفرد واحد ووحيد لا شبيه له. وهو ذاته مستمرّ ثابت عبر مراحل حياته (الهويّة الشخصيّة)، من غير أن تلغي الوحدة تعدّد مواقفه، فالشخصيّة متطوّرة تُغتنى باستمرار.', 1, '2026-09-30 22:11:56', '2026-09-30 22:11:56'),
(15643, 2322, 1, 'ترى نظرية الطباع أنّ شخصيّة الفرد محدّدة سلفاً بحسب طبعه الخاصّ الفطري الموروث، فالطبع سابق لتاريخنا الشخصي، ثابت مستمرّ لا يمكننا تغييره، وتاريخنا الشخصي يحمل طابعه (شخصيّة مكوّنة سلفاً). أمّا التحليل النفسي فليس عند فرويد طبع فطري موروث، بل الشخصيّة المؤلّفة من الهُو والأنا والأنا الأعلى نتاج علاقة الهُو بالأنا الأعلى (الروادع الاجتماعية)، والتاريخ الخاصّ بكلّ فرد يجعل منه شخصيّة فريدة (شخصيّة من صنع التاريخ)، ويستطيع الفرد أن يغيّر شخصيّته بوعي غرائزه المكبوتة. ومع تقابل الموقفين، تراهن كلتا النظريتين على الوعي.', 1, '2026-09-30 22:11:56', '2026-09-30 22:11:56'),
(15644, 2322, 2, 'ترى نظرية الطباع أنّ شخصيّة الفرد محدّدة سلفاً بحسب طبعه الخاصّ الفطري الموروث، فالطبع سابق لتاريخنا الشخصي، ثابت مستمرّ لا يمكننا تغييره، وتاريخنا الشخصي يحمل طابعه (شخصيّة مكوّنة سلفاً). أمّا التحليل النفسي فليس عند فرويد طبع فطري موروث، بل الشخصيّة المؤلّفة من الهُو والأنا والأنا الأعلى نتاج علاقة الهُو بالأنا الأعلى (الروادع الاجتماعية)، والتاريخ الخاصّ بكلّ فرد يجعل منه شخصيّة فريدة (شخصيّة من صنع التاريخ)، ويستطيع الفرد أن يغيّر شخصيّته بوعي غرائزه المكبوتة. ومع تقابل الموقفين، تراهن كلتا النظريتين على الوعي.', 1, '2026-09-30 22:11:56', '2026-09-30 22:11:56'),
(15645, 2323, 1, 'اعتقاد المراهق، صدقاً أم كذباً، بأنّه غبيّ يسدّ أمامه كثيراً من الطرق والأبواب التي كانت قد تكون مفتوحة أمامه لولا هذا الوهم، أمّا المقتنع بتوفّر المؤهّلات العقلية لديه فيستطيع أن يخطّط ويحلم على نطاق واسع؛ فالتقييم، واقعيّاً كان أم غير واقعي، يلعب دوراً رئيساً في تكوين نظرة الفرد نحو الحياة. ويستطيع الفرد أن يتعامل مع شخصيّته بكثير من الحرّيّة والفعاليّة ضمن قدراته، ووعيه هذه القدرات، وإرادته في إطارها، فالرهان على الوعي قاسم مشترك بين النظريات، والحرّيّة لا يجوز أن تعني التعامي (نيتشه: صِرْ ما أنت).', 1, '2026-09-30 22:11:56', '2026-09-30 22:11:56'),
(15646, 2323, 2, 'اعتقاد المراهق، صدقاً أم كذباً، بأنّه غبيّ يسدّ أمامه كثيراً من الطرق والأبواب التي كانت قد تكون مفتوحة أمامه لولا هذا الوهم، أمّا المقتنع بتوفّر المؤهّلات العقلية لديه فيستطيع أن يخطّط ويحلم على نطاق واسع؛ فالتقييم، واقعيّاً كان أم غير واقعي، يلعب دوراً رئيساً في تكوين نظرة الفرد نحو الحياة. ويستطيع الفرد أن يتعامل مع شخصيّته بكثير من الحرّيّة والفعاليّة ضمن قدراته، ووعيه هذه القدرات، وإرادته في إطارها، فالرهان على الوعي قاسم مشترك بين النظريات، والحرّيّة لا يجوز أن تعني التعامي (نيتشه: صِرْ ما أنت).', 1, '2026-09-30 22:11:56', '2026-09-30 22:11:56'),
(15647, 2324, 1, 'أخطأ التجريبيّون عندما ساووا بين الرغبات والحاجات. فالحاجات ميول عضويّة تولد مع الإنسان لحفظ حياته، أمّا الرغبات فميول واعية يدرك صاحبها غايتها ونتيجة إشباعها. فالأكل يؤدّي إلى إشباع حاجة عضويّة فطريّة لا دور للتجربة فيها، أمّا تفضيل نوع محدّد من الطعام على غيره فهو تعبير عن رغبة تلعب التجربة الحسّية دوراً في وجودها؛ فالجوع لا نتعلّمه، أمّا حبّ طبق بعينه فنتعلّمه.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15648, 2324, 2, 'أخطأ التجريبيّون عندما ساووا بين الرغبات والحاجات. فالحاجات ميول عضويّة تولد مع الإنسان لحفظ حياته، أمّا الرغبات فميول واعية يدرك صاحبها غايتها ونتيجة إشباعها. فالأكل يؤدّي إلى إشباع حاجة عضويّة فطريّة لا دور للتجربة فيها، أمّا تفضيل نوع محدّد من الطعام على غيره فهو تعبير عن رغبة تلعب التجربة الحسّية دوراً في وجودها؛ فالجوع لا نتعلّمه، أمّا حبّ طبق بعينه فنتعلّمه.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15649, 2325, 1, 'لأنّ الإنسان يستخدم لغة وأفكاراً اكتسبها من المجتمع الذي نشأ فيه، ولكلّ سلوك أصول في القواعد الجماعيّة التي يفهمها الآخرون. مثال: الشعور بالانتماء إلى الوطن عند إنشاد النشيد الوطني أو رفع العلم؛ فهذا الشعور لا يولد مع الإنسان بل يتعلّمه تدريجياً ممّن يتولّون تربيته وممّن يعيش معهم.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15650, 2325, 2, 'لأنّ الإنسان يستخدم لغة وأفكاراً اكتسبها من المجتمع الذي نشأ فيه، ولكلّ سلوك أصول في القواعد الجماعيّة التي يفهمها الآخرون. مثال: الشعور بالانتماء إلى الوطن عند إنشاد النشيد الوطني أو رفع العلم؛ فهذا الشعور لا يولد مع الإنسان بل يتعلّمه تدريجياً ممّن يتولّون تربيته وممّن يعيش معهم.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15651, 2326, 1, 'أوّلاً: لو كانت الميول مجرّد حركات لكانت حركاتنا كلّها ميولاً، وهذا مرفوض؛ فالانعكاسات حركات جسميّة لكنّها لا تعبّر عن ميول حقيقيّة، إنّها ردود فعل غريزيّة همّها تجنّب الخطر والابتعاد عن الألم، مثل حكّ الجسم عند الشعور بالحكّة، أو وضع اليدين أمام الجسم تفادياً للسقوط، أو وضع الإصبع في الأذن تفادياً للصوت المزعج. ثانياً: الحركات المكرّرة لا تكفي لتوليد ميول، فلا تصبح العادات ميولاً؛ فالتلميذ لا يكتسب ميلاً لسلوك طريق المدرسة خلال عطلته الصيفيّة مع أنّه اعتاده طيلة السنة، وضارب الدكتيلو لا يشعر أثناء عطلته بالميل إلى تحريك أصابعه كما يفعل وراء آلته.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15652, 2326, 2, 'أوّلاً: لو كانت الميول مجرّد حركات لكانت حركاتنا كلّها ميولاً، وهذا مرفوض؛ فالانعكاسات حركات جسميّة لكنّها لا تعبّر عن ميول حقيقيّة، إنّها ردود فعل غريزيّة همّها تجنّب الخطر والابتعاد عن الألم، مثل حكّ الجسم عند الشعور بالحكّة، أو وضع اليدين أمام الجسم تفادياً للسقوط، أو وضع الإصبع في الأذن تفادياً للصوت المزعج. ثانياً: الحركات المكرّرة لا تكفي لتوليد ميول، فلا تصبح العادات ميولاً؛ فالتلميذ لا يكتسب ميلاً لسلوك طريق المدرسة خلال عطلته الصيفيّة مع أنّه اعتاده طيلة السنة، وضارب الدكتيلو لا يشعر أثناء عطلته بالميل إلى تحريك أصابعه كما يفعل وراء آلته.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15653, 2327, 1, 'القيمة الاجتماعيّة فكرة أو إحساس يدفع الإنسان أو الجماعة إلى تمييز الأمور وتقييمها، واختيار السلوك الأمثل. وسائط التنشئة نوعان: وسائط مباشرة مثل العائلة والمدرسة (الأجهزة الثقافيّة)، ووسائط غير مباشرة مثل الأجهزة الإعلاميّة الحديثة، والمجلّات والجرائد، ووسائل التسلية والترفيه.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15654, 2327, 2, 'القيمة الاجتماعيّة فكرة أو إحساس يدفع الإنسان أو الجماعة إلى تمييز الأمور وتقييمها، واختيار السلوك الأمثل. وسائط التنشئة نوعان: وسائط مباشرة مثل العائلة والمدرسة (الأجهزة الثقافيّة)، ووسائط غير مباشرة مثل الأجهزة الإعلاميّة الحديثة، والمجلّات والجرائد، ووسائل التسلية والترفيه.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15655, 2328, 1, 'الإشكاليّة: ما هي طبيعة الميول؟ هل هي ذات طبيعة شعوريّة انفعاليّة تنتج عن خبراتنا الحسّية التي تتبعها لذّة؟ أم أنّها ذات طبيعة حركيّة مادّية تظهر في سلوكنا اليومي وتصرّفاتنا؟ التوليفة: لا يمكن إغفال كلا الجانبين العاطفي والحركي للميول؛ لكن لكلّ إنسان ظروف اجتماعيّة وعائليّة وتربويّة وثقافيّة تميّزه وتحدّد المدى الذي تتحرّك فيه ميوله، فالميول تختلف شكلاً وموضوعاً من إنسان لآخر بحسب المجتمع والتربية والدين؛ ولا يمكن إنكار دور القوى اللاواعية التي تتحكّم في حياتنا النفسيّة؛ وتبقى الميول ظاهرة إنسانيّة لا يصل فيها الباحث إلى حقائق ثابتة ونهائيّة وعامّة.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15656, 2328, 2, 'الإشكاليّة: ما هي طبيعة الميول؟ هل هي ذات طبيعة شعوريّة انفعاليّة تنتج عن خبراتنا الحسّية التي تتبعها لذّة؟ أم أنّها ذات طبيعة حركيّة مادّية تظهر في سلوكنا اليومي وتصرّفاتنا؟ التوليفة: لا يمكن إغفال كلا الجانبين العاطفي والحركي للميول؛ لكن لكلّ إنسان ظروف اجتماعيّة وعائليّة وتربويّة وثقافيّة تميّزه وتحدّد المدى الذي تتحرّك فيه ميوله، فالميول تختلف شكلاً وموضوعاً من إنسان لآخر بحسب المجتمع والتربية والدين؛ ولا يمكن إنكار دور القوى اللاواعية التي تتحكّم في حياتنا النفسيّة؛ وتبقى الميول ظاهرة إنسانيّة لا يصل فيها الباحث إلى حقائق ثابتة ونهائيّة وعامّة.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15657, 2329, 1, 'من القيم الأساسيّة التمسّك بالتراب الوطني، والحرّيّة، والديمقراطيّة، والعدالة الاجتماعيّة. أمّا القيم الثانويّة فقيم فرديّة لا يشكّل تنوّعها خطراً على المجتمع ككلّ، ومنها التهذيب، والاهتمام بالآخرين، والنجاح المهني والتعليمي، ومجاراة الموضة. والقيم ليست في المستوى نفسه من الأهميّة، لذلك يحتاج المجتمع إلى قيم أساسيّة يتمسّك بها أكبر عدد من الناس، كي يحافظ على ذاته وعلى حدّ أدنى من التضامن.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15658, 2329, 2, 'من القيم الأساسيّة التمسّك بالتراب الوطني، والحرّيّة، والديمقراطيّة، والعدالة الاجتماعيّة. أمّا القيم الثانويّة فقيم فرديّة لا يشكّل تنوّعها خطراً على المجتمع ككلّ، ومنها التهذيب، والاهتمام بالآخرين، والنجاح المهني والتعليمي، ومجاراة الموضة. والقيم ليست في المستوى نفسه من الأهميّة، لذلك يحتاج المجتمع إلى قيم أساسيّة يتمسّك بها أكبر عدد من الناس، كي يحافظ على ذاته وعلى حدّ أدنى من التضامن.', 1, '2026-09-30 22:11:57', '2026-09-30 22:11:57'),
(15659, 2330, 1, 'تتعلّم ندى إيقاعات النهار وتقسيماته؛ وأنّ الأكل والنظافة والنوم تتمّ في أوقات محدّدة؛ وأنّ لكلّ شخص في البيت دوراً، وأنّ لها هي دوراً وموقعاً. والعائلة مجتمع مصغّر لأنّها تضمّ علاقات متبادلة ومواقف وأدواراً تختزل المجتمع الكبير، لذلك تُعدّ الوسيط الأوّل في التنشئة الاجتماعيّة.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15660, 2330, 2, 'تتعلّم ندى إيقاعات النهار وتقسيماته؛ وأنّ الأكل والنظافة والنوم تتمّ في أوقات محدّدة؛ وأنّ لكلّ شخص في البيت دوراً، وأنّ لها هي دوراً وموقعاً. والعائلة مجتمع مصغّر لأنّها تضمّ علاقات متبادلة ومواقف وأدواراً تختزل المجتمع الكبير، لذلك تُعدّ الوسيط الأوّل في التنشئة الاجتماعيّة.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15661, 2331, 1, 'مقاربة التحليل النفسي (سيغموند فرويد) تركّز على العلاقات الشخصيّة، وتعطي الإشباع العاطفي أهمّيّة قصوى، وترى أنّ الحياة الجنسيّة العاطفيّة مع الأبوين أساس العلاقات الاجتماعيّة المستقبليّة. أمّا مقاربة الوسط الاجتماعي فترى أنّ الوسط يفرض قوالب السلوك، فيتعلّم الطفل بالإكراه الجسدي والمعنوي الممنوع والمسموح. وتتفرّع إلى: مدرسة القيم الاجتماعيّة (دوركهايم)، ومدرسة دور الإنسان في الإنتاج (ماركس)، ومدرسة تعدّد أنماط العائلات بحسب الثقافة والحضارة.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15662, 2331, 2, 'مقاربة التحليل النفسي (سيغموند فرويد) تركّز على العلاقات الشخصيّة، وتعطي الإشباع العاطفي أهمّيّة قصوى، وترى أنّ الحياة الجنسيّة العاطفيّة مع الأبوين أساس العلاقات الاجتماعيّة المستقبليّة. أمّا مقاربة الوسط الاجتماعي فترى أنّ الوسط يفرض قوالب السلوك، فيتعلّم الطفل بالإكراه الجسدي والمعنوي الممنوع والمسموح. وتتفرّع إلى: مدرسة القيم الاجتماعيّة (دوركهايم)، ومدرسة دور الإنسان في الإنتاج (ماركس)، ومدرسة تعدّد أنماط العائلات بحسب الثقافة والحضارة.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15663, 2332, 1, 'تتكاملان لأنّ المدرسة تتابع ما بدأه الأهل، ومثال ذلك تعليم اللغة. وقد تتناقضان لأنّ الطفل يتعلّم في المدرسة قيماً ومعارف جديدة، ويدخل علاقات تراتبيّة وسلطويّة تختلف عن علاقات البيت العاطفيّة. وتتزايد أهمّيّة المدرسة لسببين: انخفاض سنّ الدخول إليها حتّى ثلاثة أعوام، وكونها الوسيط الأطول احتضاناً للفرد والأعمق تأثيراً فيه.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15664, 2332, 2, 'تتكاملان لأنّ المدرسة تتابع ما بدأه الأهل، ومثال ذلك تعليم اللغة. وقد تتناقضان لأنّ الطفل يتعلّم في المدرسة قيماً ومعارف جديدة، ويدخل علاقات تراتبيّة وسلطويّة تختلف عن علاقات البيت العاطفيّة. وتتزايد أهمّيّة المدرسة لسببين: انخفاض سنّ الدخول إليها حتّى ثلاثة أعوام، وكونها الوسيط الأطول احتضاناً للفرد والأعمق تأثيراً فيه.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15665, 2333, 1, 'الخروج إلى الحيّ يوسّع دائرة العلاقات والمؤثّرات. التنشئة السياسيّة: يختبر الحيّ شأناً عامّاً، فيه أمكنة للنفايات ورصيف للمشاة، ويرى ممثّلي السلطة كالشرطي وشرطي السير وحاجز الجيش. التنشئة الاقتصاديّة: تبادل مصلحي بين الناس، فيتعلّم أنّ كلّ ما يريده يجب أن يدفع ثمنه، فعليه تأمين المال.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15666, 2333, 2, 'الخروج إلى الحيّ يوسّع دائرة العلاقات والمؤثّرات. التنشئة السياسيّة: يختبر الحيّ شأناً عامّاً، فيه أمكنة للنفايات ورصيف للمشاة، ويرى ممثّلي السلطة كالشرطي وشرطي السير وحاجز الجيش. التنشئة الاقتصاديّة: تبادل مصلحي بين الناس، فيتعلّم أنّ كلّ ما يريده يجب أن يدفع ثمنه، فعليه تأمين المال.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15667, 2334, 1, 'في المدينة يختبر الفرد التعدّد والاختلاط (الشوارع والساحات والأسواق والجامعات والمقاهي)، ويتعلّم احترام خصوصيّة المختلف وأهمّيّة القانون والتبادل الاقتصادي. وفي القرية تقوم العلاقات على القرابة والمعرفة الشخصيّة، ويسود الهدوء والرتابة والبساطة، وتلعب فئات الأعمار والطقوس الجماعيّة دوراً أساسياً. من قيم القرية (ثلاث منها): الخضوع للطبيعة والتبعيّة لها، الروتين وضعف حوافز التجدّد، بطء الحركة الاجتماعيّة وقوّة الانتماء العائلي والتقليد، التقوى وهيمنة الفكر الديني.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15668, 2334, 2, 'في المدينة يختبر الفرد التعدّد والاختلاط (الشوارع والساحات والأسواق والجامعات والمقاهي)، ويتعلّم احترام خصوصيّة المختلف وأهمّيّة القانون والتبادل الاقتصادي. وفي القرية تقوم العلاقات على القرابة والمعرفة الشخصيّة، ويسود الهدوء والرتابة والبساطة، وتلعب فئات الأعمار والطقوس الجماعيّة دوراً أساسياً. من قيم القرية (ثلاث منها): الخضوع للطبيعة والتبعيّة لها، الروتين وضعف حوافز التجدّد، بطء الحركة الاجتماعيّة وقوّة الانتماء العائلي والتقليد، التقوى وهيمنة الفكر الديني.', 1, '2026-09-30 22:11:58', '2026-09-30 22:11:58'),
(15669, 2335, 1, 'المركز الاجتماعي يُحدَّد انطلاقاً من الحقوق والامتيازات والحصانة من جهة، ومن الواجبات والمهامّ المكلّف بها الفرد من جهة أخرى. وتكون التنشئة ناجحة حين يتماهى العامل مع مؤسّسته فيقول: «هذه مؤسّستي». أمّا حين يشعر بالتهميش فقد يعزل نفسه، ثمّ يكتشف أهمّيّة التواصل مع زملائه والتضامن. والنقابة هيئة منتخبة للعاملين، بها يتعلّم الفرد إدارة الصراع الاجتماعي ويشارك فيه، ويتقوّى بها في مهنته، فيصبح التضامن المهني إحدى مؤسّسات التنشئة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15670, 2335, 2, 'المركز الاجتماعي يُحدَّد انطلاقاً من الحقوق والامتيازات والحصانة من جهة، ومن الواجبات والمهامّ المكلّف بها الفرد من جهة أخرى. وتكون التنشئة ناجحة حين يتماهى العامل مع مؤسّسته فيقول: «هذه مؤسّستي». أمّا حين يشعر بالتهميش فقد يعزل نفسه، ثمّ يكتشف أهمّيّة التواصل مع زملائه والتضامن. والنقابة هيئة منتخبة للعاملين، بها يتعلّم الفرد إدارة الصراع الاجتماعي ويشارك فيه، ويتقوّى بها في مهنته، فيصبح التضامن المهني إحدى مؤسّسات التنشئة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15671, 2336, 1, 'رقابة «عيون الناس» هي رقابة يمارسها المجتمع ذاتياً على أفراده بممارسات جماعيّة تقدّر السلوك أو تدينه. من الإدانات الشائعة: العيب والعار (والسخرية والإخلال بالواجبات الاجتماعيّة). وهي أكثر فعاليّة من أجهزة الضبط لأنّها تتناول أساس علاقات الفرد بالمجتمع.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15672, 2336, 2, 'رقابة «عيون الناس» هي رقابة يمارسها المجتمع ذاتياً على أفراده بممارسات جماعيّة تقدّر السلوك أو تدينه. من الإدانات الشائعة: العيب والعار (والسخرية والإخلال بالواجبات الاجتماعيّة). وهي أكثر فعاليّة من أجهزة الضبط لأنّها تتناول أساس علاقات الفرد بالمجتمع.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15673, 2337, 1, 'الإعلام وسيط جماهيري للتنشئة يصل إلى أوسع الفئات، وله تأثير عميق في المعرفة والمعلومات وبالتالي في تقييم الأحداث. ويتداخل في التنشئة بطريقتين: إمّا أن يستكمل ما بدأته العائلة والمدرسة وأمكنة السكن والعمل، وإمّا أن ينافس هذه الوسائط ويناقضها أحياناً.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15674, 2337, 2, 'الإعلام وسيط جماهيري للتنشئة يصل إلى أوسع الفئات، وله تأثير عميق في المعرفة والمعلومات وبالتالي في تقييم الأحداث. ويتداخل في التنشئة بطريقتين: إمّا أن يستكمل ما بدأته العائلة والمدرسة وأمكنة السكن والعمل، وإمّا أن ينافس هذه الوسائط ويناقضها أحياناً.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15675, 2338, 1, 'الصُّعُد الأربعة: الجسدي، والاقتصادي، والماورائي (يتعلّق بالدين والأخلاق وبالخرافات)، والاجتماعي (غير مكتوب وغير مقنّن). في الصعيد الاقتصادي: من العقاب الغرامة الماليّة أو العطل والضرر أو المقاطعة أو الحظر، ومن الثواب المكافأة الماليّة أو الجوائز كجائزة نوبل أو المنح الدراسيّة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15676, 2338, 2, 'الصُّعُد الأربعة: الجسدي، والاقتصادي، والماورائي (يتعلّق بالدين والأخلاق وبالخرافات)، والاجتماعي (غير مكتوب وغير مقنّن). في الصعيد الاقتصادي: من العقاب الغرامة الماليّة أو العطل والضرر أو المقاطعة أو الحظر، ومن الثواب المكافأة الماليّة أو الجوائز كجائزة نوبل أو المنح الدراسيّة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15677, 2339, 1, 'القيم المدنيّة: تتعلّق بالشأن العام، مثل تمجيد التاريخ والتراث، أو عرض الحياة السياسيّة، أو علاقة الفرد بالدولة. القيم الاجتماعيّة: تحكم حياة الجماعات، مثل العائلة والتربية وأدوار الرجل والمرأة، أو تثمين العمل والإنتاج، أو الزواج والتضامن الاجتماعي. القيم الفرديّة: تحكم الحياة الخاصّة، مثل الكرم والضيافة والاحترام والالتزام والمسؤوليّة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15678, 2339, 2, 'القيم المدنيّة: تتعلّق بالشأن العام، مثل تمجيد التاريخ والتراث، أو عرض الحياة السياسيّة، أو علاقة الفرد بالدولة. القيم الاجتماعيّة: تحكم حياة الجماعات، مثل العائلة والتربية وأدوار الرجل والمرأة، أو تثمين العمل والإنتاج، أو الزواج والتضامن الاجتماعي. القيم الفرديّة: تحكم الحياة الخاصّة، مثل الكرم والضيافة والاحترام والالتزام والمسؤوليّة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15679, 2340, 1, 'الجواب يتوقّف على نوع المجتمع. في المجتمع الديمقراطي المنفتح يكون التجدّد سلميّاً وتدريجياً، يتمّ بالمشاركة والممارسة الديمقراطيّة، ولا يحدّد انتشار الأفكار إلّا قناعة الناس بها. أمّا في المجتمع المغلق السلطوي فتُفرض التنشئة بالقوّة، ويتمّ التجدّد بالعنف الثوري وبالمواجهة بين المتمسّكين بالقيم القديمة والداعين إلى قيم جديدة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15680, 2340, 2, 'الجواب يتوقّف على نوع المجتمع. في المجتمع الديمقراطي المنفتح يكون التجدّد سلميّاً وتدريجياً، يتمّ بالمشاركة والممارسة الديمقراطيّة، ولا يحدّد انتشار الأفكار إلّا قناعة الناس بها. أمّا في المجتمع المغلق السلطوي فتُفرض التنشئة بالقوّة، ويتمّ التجدّد بالعنف الثوري وبالمواجهة بين المتمسّكين بالقيم القديمة والداعين إلى قيم جديدة.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15681, 2341, 1, 'لا، لا تقتصر على الأعضاء. فهناك تنشئة مباشرة، وهي تثقيف الأعضاء والراغبين في الالتحاق على مستوى العقيدة والبرنامج السياسي وتدريبهم على العمل السياسي. وهناك تنشئة غير مباشرة، يؤثّر فيها الحزب في عامّة الناس عبر الإعلام الذي يمتلكه من صحف ومجلّات ونشرات وإذاعات ومحطّات تلفزة. مثال من لبنان: نقلت الأحزاب قبل الحرب قيماً إلى الحياة السياسيّة كوحدة الدولة والديمقراطيّة والعدالة الاجتماعيّة، وأثناء الحرب نشرت تنشئة تُعلي شأن العنف المسلّح.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15682, 2341, 2, 'لا، لا تقتصر على الأعضاء. فهناك تنشئة مباشرة، وهي تثقيف الأعضاء والراغبين في الالتحاق على مستوى العقيدة والبرنامج السياسي وتدريبهم على العمل السياسي. وهناك تنشئة غير مباشرة، يؤثّر فيها الحزب في عامّة الناس عبر الإعلام الذي يمتلكه من صحف ومجلّات ونشرات وإذاعات ومحطّات تلفزة. مثال من لبنان: نقلت الأحزاب قبل الحرب قيماً إلى الحياة السياسيّة كوحدة الدولة والديمقراطيّة والعدالة الاجتماعيّة، وأثناء الحرب نشرت تنشئة تُعلي شأن العنف المسلّح.', 1, '2026-09-30 22:11:59', '2026-09-30 22:11:59'),
(15683, 2342, 1, 'لأنّ المراهقة تبدّل عميق في الأدوار الاجتماعيّة: انتهى دور المراهق كطفل ولم يحصل بعد تماماً على دوره كراشد، فهو يقف بين النضج البيولوجي والنضج الاجتماعي. وهذا الانتقال من دور إلى دور يجعلها مرحلة غير مستقرّة وشديدة التوتّر.', 1, '2026-09-30 22:12:00', '2026-09-30 22:12:00'),
(15684, 2342, 2, 'لأنّ المراهقة تبدّل عميق في الأدوار الاجتماعيّة: انتهى دور المراهق كطفل ولم يحصل بعد تماماً على دوره كراشد، فهو يقف بين النضج البيولوجي والنضج الاجتماعي. وهذا الانتقال من دور إلى دور يجعلها مرحلة غير مستقرّة وشديدة التوتّر.', 1, '2026-09-30 22:12:00', '2026-09-30 22:12:00'),
(15685, 2343, 1, 'تتولّد لدى المحيطين بالمراهق ممارسات جديدة أبرزها تراجع الإعجاب به، ويشعر بفقدان دعم الأهل والأقارب لأنّه لم يعد طفلاً؛ يبدأ ذلك عند الأبوين ثمّ ينتقل إلى سائر المحيط، فيعيشه كأنّه عدوان عليه. والنتيجة انقلاب في أحكامه: يكره من كان يحبّ، ويحتقر من كان يعجب به، ويتجاهل من كان يسعى إلى عشرته.', 1, '2026-09-30 22:12:00', '2026-09-30 22:12:00'),
(15686, 2343, 2, 'تتولّد لدى المحيطين بالمراهق ممارسات جديدة أبرزها تراجع الإعجاب به، ويشعر بفقدان دعم الأهل والأقارب لأنّه لم يعد طفلاً؛ يبدأ ذلك عند الأبوين ثمّ ينتقل إلى سائر المحيط، فيعيشه كأنّه عدوان عليه. والنتيجة انقلاب في أحكامه: يكره من كان يحبّ، ويحتقر من كان يعجب به، ويتجاهل من كان يسعى إلى عشرته.', 1, '2026-09-30 22:12:00', '2026-09-30 22:12:00'),
(15687, 2344, 1, 'مرحلة المواجهة (المعارضة) تلازم ما قبل البلوغ، وفيها يرفض المراهق بشكل دائم كلّ ما يُطلب إليه (النظام والترتيب وحتّى النظافة) ويعتمد الفظاظة. أمّا مرحلة تثبيت الذات فتلازم البلوغ، وفيها يطالب بالاستقلاليّة وبحرّية القرار ولا يتحمّل التدخّل في مظهره وأصدقائه. والعقبة هي استحالة الاستقلاليّة الماليّة لارتباطها بالدراسة، وهذا يحدّ من إرادة الاستقلال في المجالات الأخرى.', 1, '2026-09-30 22:12:00', '2026-09-30 22:12:00'),
(15688, 2344, 2, 'مرحلة المواجهة (المعارضة) تلازم ما قبل البلوغ، وفيها يرفض المراهق بشكل دائم كلّ ما يُطلب إليه (النظام والترتيب وحتّى النظافة) ويعتمد الفظاظة. أمّا مرحلة تثبيت الذات فتلازم البلوغ، وفيها يطالب بالاستقلاليّة وبحرّية القرار ولا يتحمّل التدخّل في مظهره وأصدقائه. والعقبة هي استحالة الاستقلاليّة الماليّة لارتباطها بالدراسة، وهذا يحدّ من إرادة الاستقلال في المجالات الأخرى.', 1, '2026-09-30 22:12:00', '2026-09-30 22:12:00'),
(15689, 2345, 1, '1) في حدّها الأدنى جماعات للهو وتنظيم أوقات الفراغ. 2) قد تتطوّر لتصبح جماعات فاعلة كاتّحادات الشبيبة وتنظيمات الطلاب. 3) قد ينزلق بعضها إلى الشرّ فيشكّل عصابات خارجة عن القانون، أو منعزلة، أو منسيّة في هامش المجتمع.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15690, 2345, 2, '1) في حدّها الأدنى جماعات للهو وتنظيم أوقات الفراغ. 2) قد تتطوّر لتصبح جماعات فاعلة كاتّحادات الشبيبة وتنظيمات الطلاب. 3) قد ينزلق بعضها إلى الشرّ فيشكّل عصابات خارجة عن القانون، أو منعزلة، أو منسيّة في هامش المجتمع.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15691, 2346, 1, '1) انقطاع التواصل: يعزل المراهق نفسه عن محيطه ويقطع الحوار، فيتوقّف عن استيعاب ما يُعرض عليه. 2) التمسّك برأي أو سلوك أو موقف متفرّد: فيتوقّف عن الإفادة من تجارب الآخرين. 3) الهروب: تدفعه حالته المتأزّمة إلى ترك كلّ شيء، فيهرب من محيطه وينسلخ عن علاقاته بصورة مباغتة.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15692, 2346, 2, '1) انقطاع التواصل: يعزل المراهق نفسه عن محيطه ويقطع الحوار، فيتوقّف عن استيعاب ما يُعرض عليه. 2) التمسّك برأي أو سلوك أو موقف متفرّد: فيتوقّف عن الإفادة من تجارب الآخرين. 3) الهروب: تدفعه حالته المتأزّمة إلى ترك كلّ شيء، فيهرب من محيطه وينسلخ عن علاقاته بصورة مباغتة.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15693, 2347, 1, 'لأنّ المراهقة مرتبطة بالتطوّر التاريخي وبالأوساط الاجتماعيّة المتنوّعة وبالثقافات المتباينة. المثال الأوّل: لدى قبائل متعدّدة يجري الانتقال خلال احتفال عام وطقوس خاصّة بالذكور وبالإناث، يغدو بعده الفرد عضواً في الجماعة يتمتّع بحقوق الكبار وواجباتهم. المثال الثاني: المراهقة كمصطلح عالمي مرتبطة بالعائلة النواتيّة وبتوسّع دور المدرسة وإطالة المرحلة الدراسيّة وبالاقتصاد المديني. لذلك لا تُجتاز المراهقة بالنموذج ذاته في كلّ فئات المجتمع وطبقاته.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15694, 2347, 2, 'لأنّ المراهقة مرتبطة بالتطوّر التاريخي وبالأوساط الاجتماعيّة المتنوّعة وبالثقافات المتباينة. المثال الأوّل: لدى قبائل متعدّدة يجري الانتقال خلال احتفال عام وطقوس خاصّة بالذكور وبالإناث، يغدو بعده الفرد عضواً في الجماعة يتمتّع بحقوق الكبار وواجباتهم. المثال الثاني: المراهقة كمصطلح عالمي مرتبطة بالعائلة النواتيّة وبتوسّع دور المدرسة وإطالة المرحلة الدراسيّة وبالاقتصاد المديني. لذلك لا تُجتاز المراهقة بالنموذج ذاته في كلّ فئات المجتمع وطبقاته.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15695, 2348, 1, '1) تفاقم ما يسمّى أزمات المراهقين في العالم، من إدمان وقلق وانتحار. 2) تعاظم أهمّيّة دور الشبيبة في بناء المجتمعات المعاصرة. 3) تطوّر البحث في مرحلة المراهقة، في مواصفاتها الجسديّة والنفسيّة، وفي ممارسات المراهقين ومشاكلهم الاجتماعيّة.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15696, 2348, 2, '1) تفاقم ما يسمّى أزمات المراهقين في العالم، من إدمان وقلق وانتحار. 2) تعاظم أهمّيّة دور الشبيبة في بناء المجتمعات المعاصرة. 3) تطوّر البحث في مرحلة المراهقة، في مواصفاتها الجسديّة والنفسيّة، وفي ممارسات المراهقين ومشاكلهم الاجتماعيّة.', 1, '2026-09-30 22:12:01', '2026-09-30 22:12:01'),
(15697, 2349, 1, '1) الانصياع: الخلاف بين المراهق وأبويه ينتهي في أغلب الأحوال باستسلامه لما يتوافق مع رأيهما. 2) التمرّد: يظهر بأجلى صوره في رفض السلطة السائدة والدعوة إلى بدائل بهدف التغيير. 3) اليقظة الدينيّة: تأخذ اليقظة العامّة المرافقة للنضج أحياناً شكلاً دينيّاً، فيشترك مراهقون كثيرون في عمل جماعيّ ويحملون لواء إقامة دعائم الفضيلة في المجتمع.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15698, 2349, 2, '1) الانصياع: الخلاف بين المراهق وأبويه ينتهي في أغلب الأحوال باستسلامه لما يتوافق مع رأيهما. 2) التمرّد: يظهر بأجلى صوره في رفض السلطة السائدة والدعوة إلى بدائل بهدف التغيير. 3) اليقظة الدينيّة: تأخذ اليقظة العامّة المرافقة للنضج أحياناً شكلاً دينيّاً، فيشترك مراهقون كثيرون في عمل جماعيّ ويحملون لواء إقامة دعائم الفضيلة في المجتمع.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15699, 2350, 1, 'انحراف الأحداث (جنوحهم) هو سلوك خاطئ يصدر عن الأطفال أو المراهقين، يخرقون فيه القاعدة القانونية أو الأخلاقية السائدة في المجتمع؛ أي الأخطاء البسيطة التي يرتكبها الأحداث الصغار ضدّ القانون أو ضدّ النظام الاجتماعي السائد.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15700, 2350, 2, 'انحراف الأحداث (جنوحهم) هو سلوك خاطئ يصدر عن الأطفال أو المراهقين، يخرقون فيه القاعدة القانونية أو الأخلاقية السائدة في المجتمع؛ أي الأخطاء البسيطة التي يرتكبها الأحداث الصغار ضدّ القانون أو ضدّ النظام الاجتماعي السائد.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15701, 2351, 1, 'الباحث عن اللذّة يسعى إلى الإشباع الآنيّ دون حساب للعواقب، فيظهر على السطح سعيداً راضياً مستمتعاً بملذّات الحياة، لكنّه في العمق معرّض للاغتراب وللانفصال النفسيّ عن الذات والمجتمع. والأنماط الأربعة ليست منفصلة تماماً بل تتداخل: فالنمط التقليديّ الشكليّ قد يكون مثاليّاً في طاعته وانصياعه، والعكس بالعكس.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15702, 2351, 2, 'الباحث عن اللذّة يسعى إلى الإشباع الآنيّ دون حساب للعواقب، فيظهر على السطح سعيداً راضياً مستمتعاً بملذّات الحياة، لكنّه في العمق معرّض للاغتراب وللانفصال النفسيّ عن الذات والمجتمع. والأنماط الأربعة ليست منفصلة تماماً بل تتداخل: فالنمط التقليديّ الشكليّ قد يكون مثاليّاً في طاعته وانصياعه، والعكس بالعكس.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15703, 2352, 1, 'الجنوح الاجتماعي (انحراف الزمر): يقوم به جماعات من الناشئة، وسببه الحرمان والإحباط والإهانة (وتزيده تعقيداً عوامل كالانحلال الأسري والقسوة والنبذ)، ويظهر في مخالفة النظام الاجتماعي مثل السرقة والضرب والممارسات المحظورة. الجنوح الفردي: يقوم به فرد، وسببه أسلوب الأهل في التربية والتأديب، ويظهر في نزعة نحو العدوان.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15704, 2352, 2, 'الجنوح الاجتماعي (انحراف الزمر): يقوم به جماعات من الناشئة، وسببه الحرمان والإحباط والإهانة (وتزيده تعقيداً عوامل كالانحلال الأسري والقسوة والنبذ)، ويظهر في مخالفة النظام الاجتماعي مثل السرقة والضرب والممارسات المحظورة. الجنوح الفردي: يقوم به فرد، وسببه أسلوب الأهل في التربية والتأديب، ويظهر في نزعة نحو العدوان.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15705, 2353, 1, '1) جوّ عاطفي صحّي وعلاقات ودّية في الأسرة، لأنّ النبذ والقسوة وفقدان الحبّ من أسباب السلوك المضادّ للمجتمع. 2) الاكتشاف المبكر، لأنّ الانحراف ينمو تدريجياً ويمكن معالجة إشاراته الأولى (الكذب والسرقة والاعتداء) في بدايته. 3) مراقبة القراءات والأفلام تربوياً، لأنّ مشاهد العنف قد تنقل تقنيات الجريمة إلى الطفل. (تُقبل أيضاً: تربية لا تجعل العنف طريقاً لحلّ المشكلات، توسيع الإمكانيات الترفيهية للأطفال المحرومين، فرض سلطة القانون بحزم، مع تعليل مناسب.)', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15706, 2353, 2, '1) جوّ عاطفي صحّي وعلاقات ودّية في الأسرة، لأنّ النبذ والقسوة وفقدان الحبّ من أسباب السلوك المضادّ للمجتمع. 2) الاكتشاف المبكر، لأنّ الانحراف ينمو تدريجياً ويمكن معالجة إشاراته الأولى (الكذب والسرقة والاعتداء) في بدايته. 3) مراقبة القراءات والأفلام تربوياً، لأنّ مشاهد العنف قد تنقل تقنيات الجريمة إلى الطفل. (تُقبل أيضاً: تربية لا تجعل العنف طريقاً لحلّ المشكلات، توسيع الإمكانيات الترفيهية للأطفال المحرومين، فرض سلطة القانون بحزم، مع تعليل مناسب.)', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15707, 2354, 1, 'المسار الأوّل: اختيار مهنة تؤمّن للشابّ حياته المادّيّة، ويجهّز نفسه لها، وكثيراً ما يباشر ممارستها دون إعداد كافٍ؛ وتستقبله مؤسّسات العمل والإنتاج. المسار الثاني: الاستمرار في الدراسة والتوغّل في مجال الاختصاص؛ وتستقبله مؤسّسات التحصيل العلميّ والاختصاص. من تأمّنت له شروط الاستمرار يتابع دراسته، ومن لم تتأمّن له يتّجه إلى سوق العمل.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15708, 2354, 2, 'المسار الأوّل: اختيار مهنة تؤمّن للشابّ حياته المادّيّة، ويجهّز نفسه لها، وكثيراً ما يباشر ممارستها دون إعداد كافٍ؛ وتستقبله مؤسّسات العمل والإنتاج. المسار الثاني: الاستمرار في الدراسة والتوغّل في مجال الاختصاص؛ وتستقبله مؤسّسات التحصيل العلميّ والاختصاص. من تأمّنت له شروط الاستمرار يتابع دراسته، ومن لم تتأمّن له يتّجه إلى سوق العمل.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15709, 2355, 1, 'الاصطفاء هو أن يخضع الطالب لامتحانات ومباريات واختبارات من ناحية، وأن يراعي حاجة المجتمع إليه في الاختصاص الذي اختاره من ناحية ثانية. أثره: يعيش الشابّ الطالب حالة اجتماعيّة مثقلة بالضغط بين أهله وفي محيطه، ويتوق إلى الاستقلاليّة والتمرّد، وتصبح علاقته بأهله وبعالم الراشدين علاقة ملتبسة.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15710, 2355, 2, 'الاصطفاء هو أن يخضع الطالب لامتحانات ومباريات واختبارات من ناحية، وأن يراعي حاجة المجتمع إليه في الاختصاص الذي اختاره من ناحية ثانية. أثره: يعيش الشابّ الطالب حالة اجتماعيّة مثقلة بالضغط بين أهله وفي محيطه، ويتوق إلى الاستقلاليّة والتمرّد، وتصبح علاقته بأهله وبعالم الراشدين علاقة ملتبسة.', 1, '2026-09-30 22:12:02', '2026-09-30 22:12:02'),
(15711, 2356, 1, 'الطلّاب الجامعيّون أجيال الطليعة، وعليهم يستند بناء مستقبل البلد، لذلك هم الجسم الاجتماعيّ الذي يحسّ قبل غيره بالأزمات والمشاكل الاجتماعيّة والقضايا الوطنيّة الكبرى. ولهذا يؤسّسون اتّحادات تدافع عن مصالحهم وتكون أداة للتعبير عن رأيهم، وهي تشكّل إطاراً أوّليّاً يبدأ فيه الشباب تعاطي الشأن العامّ.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15712, 2356, 2, 'الطلّاب الجامعيّون أجيال الطليعة، وعليهم يستند بناء مستقبل البلد، لذلك هم الجسم الاجتماعيّ الذي يحسّ قبل غيره بالأزمات والمشاكل الاجتماعيّة والقضايا الوطنيّة الكبرى. ولهذا يؤسّسون اتّحادات تدافع عن مصالحهم وتكون أداة للتعبير عن رأيهم، وهي تشكّل إطاراً أوّليّاً يبدأ فيه الشباب تعاطي الشأن العامّ.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15713, 2357, 1, 'النظرة الأولى ترى الشباب فريقاً ملحقاً بالدولة والسلطات العامّة، أو مجرّد قوى داعمة للهيئات الأمنيّة أحياناً. أمّا النظرة الثانية فتشجّع التدخّل الإصلاحيّ التنمويّ والتفاعل مع المجتمعات المحلّيّة.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15714, 2357, 2, 'النظرة الأولى ترى الشباب فريقاً ملحقاً بالدولة والسلطات العامّة، أو مجرّد قوى داعمة للهيئات الأمنيّة أحياناً. أمّا النظرة الثانية فتشجّع التدخّل الإصلاحيّ التنمويّ والتفاعل مع المجتمعات المحلّيّة.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15715, 2358, 1, 'المسار الأوّل: مسار الأحزاب السياسيّة التي تحوّلت بعد الحرب العالميّة الأولى من أحزاب نخبويّة إلى أحزاب جماهيريّة، فاكتشفت أهمّيّة الشباب وطاقتهم في التغيير الاجتماعيّ. المسار الثاني: مسار الشباب أنفسهم، فبعد تضحياتهم الهائلة في الحرب رأوا أنّه لم يعد ممكناً بقاؤهم خارج العمل السياسيّ والمشاركة في القرار.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15716, 2358, 2, 'المسار الأوّل: مسار الأحزاب السياسيّة التي تحوّلت بعد الحرب العالميّة الأولى من أحزاب نخبويّة إلى أحزاب جماهيريّة، فاكتشفت أهمّيّة الشباب وطاقتهم في التغيير الاجتماعيّ. المسار الثاني: مسار الشباب أنفسهم، فبعد تضحياتهم الهائلة في الحرب رأوا أنّه لم يعد ممكناً بقاؤهم خارج العمل السياسيّ والمشاركة في القرار.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15717, 2359, 1, 'عاملان من: صعوبة الحصول على مسكن، الضيق المادّيّ، الوضع الاقتصاديّ العامّ في البلاد، صورة المستقبل. ومع تحوّل البنى الاجتماعيّة بفعل الحداثة والتصنيع والتمدين تغيّرت سنّ الزواج تدريجياً فتأخّرت، بعد أن جرى التقليد أن يدخل الشباب مؤسّسة الأسرة في سنّ مبكرة.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15718, 2359, 2, 'عاملان من: صعوبة الحصول على مسكن، الضيق المادّيّ، الوضع الاقتصاديّ العامّ في البلاد، صورة المستقبل. ومع تحوّل البنى الاجتماعيّة بفعل الحداثة والتصنيع والتمدين تغيّرت سنّ الزواج تدريجياً فتأخّرت، بعد أن جرى التقليد أن يدخل الشباب مؤسّسة الأسرة في سنّ مبكرة.', 1, '2026-09-30 22:12:03', '2026-09-30 22:12:03'),
(15719, 2360, 1, 'المشاركة الاجتماعيّة (مثالان من): المساعدات الاجتماعيّة للعاطلين عن العمل والأمّهات في المنازل؛ المساهمة في إنشاء البنى التحتيّة في القرى كشقّ الطرق وجرّ المياه؛ قطاف المحاصيل الزراعيّة كقطاف العنب في فرنسا؛ حملات التنظيف والمحافظة على البيئة. المشاركة الثقافيّة (مثال من): الأجنحة المخصّصة للشباب في معارض الكتب في بيروت والمناطق؛ معارض الموسيقى والفنون وخصوصاً المسرح؛ المنشورات والوسائط المرئيّة والمسموعة المخصّصة للشباب.', 1, '2026-09-30 22:12:07', '2026-09-30 22:12:07'),
(15720, 2360, 2, 'المشاركة الاجتماعيّة (مثالان من): المساعدات الاجتماعيّة للعاطلين عن العمل والأمّهات في المنازل؛ المساهمة في إنشاء البنى التحتيّة في القرى كشقّ الطرق وجرّ المياه؛ قطاف المحاصيل الزراعيّة كقطاف العنب في فرنسا؛ حملات التنظيف والمحافظة على البيئة. المشاركة الثقافيّة (مثال من): الأجنحة المخصّصة للشباب في معارض الكتب في بيروت والمناطق؛ معارض الموسيقى والفنون وخصوصاً المسرح؛ المنشورات والوسائط المرئيّة والمسموعة المخصّصة للشباب.', 1, '2026-09-30 22:12:07', '2026-09-30 22:12:07'),
(15721, 2361, 1, 'لم يعد الشباب يريدون العودة إلى الحياة السياسيّة التقليديّة ولا العمل مع الأحزاب، لأنّهم فقدوا الثقة بها بسبب بعض الممارسات في فترة الحرب، ولم يتمكّنوا من دخول المعترك السياسيّ بلا مساعدة الكبار، فانكفأوا عن الصعيد الوطنيّ. وفي المقابل نما وعيهم في السنوات العشر الأخيرة من القرن العشرين بشؤون البيئة والتنمية والمرأة والرياضة والتكنولوجيا الحديثة، فاعتبروا العمل المحلّيّ أجدى نفعاً وأرادوا المساهمة في العمل البلديّ مباشرة، واختاروا الهيئات غير الحكوميّة لممارسة نشاطهم السياسيّ.', 1, '2026-09-30 22:12:07', '2026-09-30 22:12:07'),
(15722, 2361, 2, 'لم يعد الشباب يريدون العودة إلى الحياة السياسيّة التقليديّة ولا العمل مع الأحزاب، لأنّهم فقدوا الثقة بها بسبب بعض الممارسات في فترة الحرب، ولم يتمكّنوا من دخول المعترك السياسيّ بلا مساعدة الكبار، فانكفأوا عن الصعيد الوطنيّ. وفي المقابل نما وعيهم في السنوات العشر الأخيرة من القرن العشرين بشؤون البيئة والتنمية والمرأة والرياضة والتكنولوجيا الحديثة، فاعتبروا العمل المحلّيّ أجدى نفعاً وأرادوا المساهمة في العمل البلديّ مباشرة، واختاروا الهيئات غير الحكوميّة لممارسة نشاطهم السياسيّ.', 1, '2026-09-30 22:12:07', '2026-09-30 22:12:07'),
(15723, 2362, 1, 'لا يحقّ لكلّ شاب الاقتراع؛ ففي لبنان يحقّ ذلك لمن أتمّ الحادية والعشرين فقط، ليختار ممثّلي الأمّة في البرلمان أو أعضاء المجالس البلديّة. أمّا استطلاع رأي الشباب، فلأنّهم كتلة اجتماعيّة كبيرة وقوّة لا يُستهان بها، ويُعَدّون ممثّلين لرأي عامّ في المجتمع؛ لذلك تُستطلع آراؤهم لتكوين فكرة عن رأيهم ومواقفهم، ولمحاولة التأثير عليهم.', 1, '2026-09-30 22:12:07', '2026-09-30 22:12:07'),
(15724, 2362, 2, 'لا يحقّ لكلّ شاب الاقتراع؛ ففي لبنان يحقّ ذلك لمن أتمّ الحادية والعشرين فقط، ليختار ممثّلي الأمّة في البرلمان أو أعضاء المجالس البلديّة. أمّا استطلاع رأي الشباب، فلأنّهم كتلة اجتماعيّة كبيرة وقوّة لا يُستهان بها، ويُعَدّون ممثّلين لرأي عامّ في المجتمع؛ لذلك تُستطلع آراؤهم لتكوين فكرة عن رأيهم ومواقفهم، ولمحاولة التأثير عليهم.', 1, '2026-09-30 22:12:07', '2026-09-30 22:12:07'),
(15725, 2363, 1, 'التبعيّة النفسيّة: حين يكفّ المدمن عن المخدّر يظهر عليه القلق والانزعاج والكآبة. التبعيّة الجسديّة: عند الانقطاع تظهر اضطرابات عقليّة ووظائفيّة عنيفة، كأوجاع الجسم والتشنّجات والتقيّؤ.', 1, '2026-09-30 22:12:08', '2026-09-30 22:12:08'),
(15726, 2363, 2, 'التبعيّة النفسيّة: حين يكفّ المدمن عن المخدّر يظهر عليه القلق والانزعاج والكآبة. التبعيّة الجسديّة: عند الانقطاع تظهر اضطرابات عقليّة ووظائفيّة عنيفة، كأوجاع الجسم والتشنّجات والتقيّؤ.', 1, '2026-09-30 22:12:08', '2026-09-30 22:12:08'),
(15727, 2364, 1, 'المدمن يحتاج إلى مال كثير لشراء المخدّر، خاصّة حين يعاني عوارض الانقطاع، وضعف إرادته يفقده السيطرة على نفسه؛ لذلك يجد نفسه مرغماً على الاتّجار بالمخدّرات وتهريبها، أو على السرقة والتزوير. مراحل المعالجة، وهي متوازية في الأهمّيّة: الوقاية، ثمّ العلاج المباشر (الفطام)، ثمّ المتابعة اللاحقة. وينظر القانون اللبنانيّ إلى المدمن على أنّه إنسان مريض لا مجرم، ويتيح له العلاج المجّانيّ مع ضمان الكتمان.', 1, '2026-09-30 22:12:10', '2026-09-30 22:12:10'),
(15728, 2364, 2, 'المدمن يحتاج إلى مال كثير لشراء المخدّر، خاصّة حين يعاني عوارض الانقطاع، وضعف إرادته يفقده السيطرة على نفسه؛ لذلك يجد نفسه مرغماً على الاتّجار بالمخدّرات وتهريبها، أو على السرقة والتزوير. مراحل المعالجة، وهي متوازية في الأهمّيّة: الوقاية، ثمّ العلاج المباشر (الفطام)، ثمّ المتابعة اللاحقة. وينظر القانون اللبنانيّ إلى المدمن على أنّه إنسان مريض لا مجرم، ويتيح له العلاج المجّانيّ مع ضمان الكتمان.', 1, '2026-09-30 22:12:10', '2026-09-30 22:12:10'),
(15729, 2365, 1, 'يُفسَّر ذلك بأسباب على مستوى الفرد، ومنها: الفضول، والتمثّل بالآخرين، والإحباط، والفشل المتكرّر، وعدم الاستقرار في العلاقات، والعدوانيّة الزائدة (يكفي سببان). الأنوميا عند دوركهايم (في كتابه تقسيم العمل الاجتماعيّ): مرض يصيب المجتمع بسبب انقطاع الأحكام الأخلاقيّة والحقوقيّة التي تنظّم اقتصاده وسياسته، فينقطع التكافل الاجتماعيّ.', 1, '2026-09-30 22:12:10', '2026-09-30 22:12:10'),
(15730, 2365, 2, 'يُفسَّر ذلك بأسباب على مستوى الفرد، ومنها: الفضول، والتمثّل بالآخرين، والإحباط، والفشل المتكرّر، وعدم الاستقرار في العلاقات، والعدوانيّة الزائدة (يكفي سببان). الأنوميا عند دوركهايم (في كتابه تقسيم العمل الاجتماعيّ): مرض يصيب المجتمع بسبب انقطاع الأحكام الأخلاقيّة والحقوقيّة التي تنظّم اقتصاده وسياسته، فينقطع التكافل الاجتماعيّ.', 1, '2026-09-30 22:12:10', '2026-09-30 22:12:10'),
(15731, 2366, 1, 'لأنّه لا يشمل الحدث الذي ارتكب جرماً فحسب، بل يشمل أيضاً كلّ حدث تتهدّده المخاطر دون أن يرتكب جرماً. مثالان من: المتسوّل، المعرّض للانحراف، المهدّد في صحّته أو أخلاقه أو تربيته.', 1, '2026-09-30 22:12:11', '2026-09-30 22:12:11'),
(15732, 2366, 2, 'لأنّه لا يشمل الحدث الذي ارتكب جرماً فحسب، بل يشمل أيضاً كلّ حدث تتهدّده المخاطر دون أن يرتكب جرماً. مثالان من: المتسوّل، المعرّض للانحراف، المهدّد في صحّته أو أخلاقه أو تربيته.', 1, '2026-09-30 22:12:11', '2026-09-30 22:12:11'),
(15733, 2367, 1, 'تعدّدت النظريات المفسِّرة للانحراف: بعضها يرى للعوامل البيولوجيّة تأثيراً مباشراً في السلوك المنحرف والإجراميّ، وبعضها ينسبه إلى تجارب مرّ بها الفرد في حداثته، وأخرى ترى أنّ العوامل الاقتصاديّة والاجتماعيّة والسياسيّة والثقافيّة والمناخيّة تؤثّر في سلوك الإنسان. هذا التعدّد يجعل الانحراف مشكلة لا تخصّ الفرد وحده، فالمعالجة تتقصّى الدوافع الحقيقيّة وتشخّص المظاهر وتتفحّص المسبّبات وتعيد النظر في النظم والقواعد. وهي معالجة شاملة ومتكاملة تربط بين المنحرف وعائلته والمجتمع ككلّ، وتتناول الصعد الفرديّة والعائليّة والبيئيّة، والنواحي الصحّيّة والاجتماعيّة والاقتصاديّة والثقافيّة والنفسيّة والقانونيّة.', 1, '2026-09-30 22:12:11', '2026-09-30 22:12:11'),
(15734, 2367, 2, 'تعدّدت النظريات المفسِّرة للانحراف: بعضها يرى للعوامل البيولوجيّة تأثيراً مباشراً في السلوك المنحرف والإجراميّ، وبعضها ينسبه إلى تجارب مرّ بها الفرد في حداثته، وأخرى ترى أنّ العوامل الاقتصاديّة والاجتماعيّة والسياسيّة والثقافيّة والمناخيّة تؤثّر في سلوك الإنسان. هذا التعدّد يجعل الانحراف مشكلة لا تخصّ الفرد وحده، فالمعالجة تتقصّى الدوافع الحقيقيّة وتشخّص المظاهر وتتفحّص المسبّبات وتعيد النظر في النظم والقواعد. وهي معالجة شاملة ومتكاملة تربط بين المنحرف وعائلته والمجتمع ككلّ، وتتناول الصعد الفرديّة والعائليّة والبيئيّة، والنواحي الصحّيّة والاجتماعيّة والاقتصاديّة والثقافيّة والنفسيّة والقانونيّة.', 1, '2026-09-30 22:12:11', '2026-09-30 22:12:11'),
(15735, 2368, 1, 'السياسة الوقائيّة العامّة تهيّئ ظروفاً حياتيّة سليمة لنموّ الأفراد، وبخاصّة الأحداث والشباب، جسديّاً وفكريّاً واجتماعيّاً، فتمنع الانحراف قبل وقوعه. أمّا الوقاية الموجّهة فتخصّ فئات تعيش ظروفاً غير سويّة، كالأطفال الذين يعملون دون السنّ المسموح بها، وتتدخّل مباشرة لمعالجة انحرافهم وحمايتهم من الانتكاس، وتشمل تطوير أجهزة القضاء. ثلاثة عناصر من الوقاية العامّة من: المسكن اللائق، فرص العمل، التعليم، الخدمات الصحّيّة والاجتماعيّة، مجال الترفيه، التربية المدنيّة.', 1, '2026-09-30 22:12:11', '2026-09-30 22:12:11'),
(15736, 2368, 2, 'السياسة الوقائيّة العامّة تهيّئ ظروفاً حياتيّة سليمة لنموّ الأفراد، وبخاصّة الأحداث والشباب، جسديّاً وفكريّاً واجتماعيّاً، فتمنع الانحراف قبل وقوعه. أمّا الوقاية الموجّهة فتخصّ فئات تعيش ظروفاً غير سويّة، كالأطفال الذين يعملون دون السنّ المسموح بها، وتتدخّل مباشرة لمعالجة انحرافهم وحمايتهم من الانتكاس، وتشمل تطوير أجهزة القضاء. ثلاثة عناصر من الوقاية العامّة من: المسكن اللائق، فرص العمل، التعليم، الخدمات الصحّيّة والاجتماعيّة، مجال الترفيه، التربية المدنيّة.', 1, '2026-09-30 22:12:11', '2026-09-30 22:12:11'),
(15737, 2369, 1, 'العبارة تمثّل التفسير القدري للفقر الذي يعتبر الفقر والغنى قدراً مكتوباً لا مناص منه، ويبقى راجحاً إلى أن يصبح قبول الفقر خطراً يهدّد العيش. في المقابل، التفسير المغاير يربط الفقر بالتنظيم الاجتماعي السياسي ويستند إلى قيم العدل الاجتماعي، فيرى الفقر حالة اجتماعيّة يسبّبها النظام الاقتصادي السياسي حين يعتمد سياسة لصالح فئات على حساب فئات أخرى، ويحمّل المؤسّسات الاجتماعيّة (أهليّة أو مدنيّة أو حكوميّة) المسؤوليّة. لذلك لا نوافق على العبارة، فالعلاج سياسة تنمويّة متوازنة توفّر فرصاً متكافئة.', 1, '2026-09-30 22:12:12', '2026-09-30 22:12:12'),
(15738, 2369, 2, 'العبارة تمثّل التفسير القدري للفقر الذي يعتبر الفقر والغنى قدراً مكتوباً لا مناص منه، ويبقى راجحاً إلى أن يصبح قبول الفقر خطراً يهدّد العيش. في المقابل، التفسير المغاير يربط الفقر بالتنظيم الاجتماعي السياسي ويستند إلى قيم العدل الاجتماعي، فيرى الفقر حالة اجتماعيّة يسبّبها النظام الاقتصادي السياسي حين يعتمد سياسة لصالح فئات على حساب فئات أخرى، ويحمّل المؤسّسات الاجتماعيّة (أهليّة أو مدنيّة أو حكوميّة) المسؤوليّة. لذلك لا نوافق على العبارة، فالعلاج سياسة تنمويّة متوازنة توفّر فرصاً متكافئة.', 1, '2026-09-30 22:12:12', '2026-09-30 22:12:12'),
(15739, 2370, 1, '1) في الأرياف يقلّ دخل كثير من الأسر (ثلاثة أرباع الأسر العاملة في الزراعة) عن خطّ الفقر الأدنى، لكنّ نظام العيش الريفي يوفّر حدّاً أدنى من الموارد في الرعي والزرع، أمّا في الضواحي فلا يتوافر ذلك. 2) توفّر الأرياف الاندماج الاجتماعي والتكافل القرابي والمحلّي، أمّا فقر الضواحي فهو نتيجة النزوح إلى مدينة (بيروت) لم تشهد نموّاً في التصنيع، ويرافقه التهميش.', 1, '2026-09-30 22:12:12', '2026-09-30 22:12:12'),
(15740, 2370, 2, '1) في الأرياف يقلّ دخل كثير من الأسر (ثلاثة أرباع الأسر العاملة في الزراعة) عن خطّ الفقر الأدنى، لكنّ نظام العيش الريفي يوفّر حدّاً أدنى من الموارد في الرعي والزرع، أمّا في الضواحي فلا يتوافر ذلك. 2) توفّر الأرياف الاندماج الاجتماعي والتكافل القرابي والمحلّي، أمّا فقر الضواحي فهو نتيجة النزوح إلى مدينة (بيروت) لم تشهد نموّاً في التصنيع، ويرافقه التهميش.', 1, '2026-09-30 22:12:12', '2026-09-30 22:12:12'),
(15741, 2371, 1, 'تبقى ثمار الخطّة متعسّرة إن لم تُعتمد سياسة التنمية المتوازنة بين المناطق، لأنّ توسيع التعليم المهني يؤدّي عندئذٍ حكماً إلى تسهيل النزوح بحثاً عن فرص العمل في المناطق الأكثر نموّاً كبيروت الكبرى. فالشرط اللازم لنجاحها هو اعتماد سياسة تنمية متوازنة بين المناطق.', 1, '2026-09-30 22:12:12', '2026-09-30 22:12:12'),
(15742, 2371, 2, 'تبقى ثمار الخطّة متعسّرة إن لم تُعتمد سياسة التنمية المتوازنة بين المناطق، لأنّ توسيع التعليم المهني يؤدّي عندئذٍ حكماً إلى تسهيل النزوح بحثاً عن فرص العمل في المناطق الأكثر نموّاً كبيروت الكبرى. فالشرط اللازم لنجاحها هو اعتماد سياسة تنمية متوازنة بين المناطق.', 1, '2026-09-30 22:12:12', '2026-09-30 22:12:12'),
(15743, 2372, 1, 'كانت أعمال الرعي والزرع والصيد والحرف تتّسع مع توسّع العائلة. وكانت طاقة العاملين في العائلة التقليديّة تفيض غالباً عن حاجة مواسمها، فتظهر بطالة موسميّة أو ما يشبه البطالة. لكنّ العلاقات والعواطف العائليّة كانت تستوعب هذا الفائض وتُخفيه، فتتحوّل البطالة من سافرة إلى مقنّعة داخل العائلة.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15744, 2372, 2, 'كانت أعمال الرعي والزرع والصيد والحرف تتّسع مع توسّع العائلة. وكانت طاقة العاملين في العائلة التقليديّة تفيض غالباً عن حاجة مواسمها، فتظهر بطالة موسميّة أو ما يشبه البطالة. لكنّ العلاقات والعواطف العائليّة كانت تستوعب هذا الفائض وتُخفيه، فتتحوّل البطالة من سافرة إلى مقنّعة داخل العائلة.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15745, 2373, 1, 'أيّ اثنين ممّا يلي: 1) نقص النموّ وانتشار الكساد، بسبب تراجع الطلب على الاستهلاك وانخفاض القدرة الشرائيّة للمستهلكين. 2) ارتفاع كلفة الإنتاج من أجور متزايدة وفوائد مرتفعة نسبياً. 3) امتناع أصحاب الرساميل عن التوظيف في المناطق التي ترتفع فيها الأجور والضمانات الاجتماعيّة بفضل العمل النقابي، وانتقالهم إلى بلاد نامية فقيرة. 4) تحوّل أصحاب الرساميل إلى تجهيزات تكنولوجيّة ترفع الإنتاج ولا ترفع فرص العمل (لوحظ منذ مطلع السبعينات).', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15746, 2373, 2, 'أيّ اثنين ممّا يلي: 1) نقص النموّ وانتشار الكساد، بسبب تراجع الطلب على الاستهلاك وانخفاض القدرة الشرائيّة للمستهلكين. 2) ارتفاع كلفة الإنتاج من أجور متزايدة وفوائد مرتفعة نسبياً. 3) امتناع أصحاب الرساميل عن التوظيف في المناطق التي ترتفع فيها الأجور والضمانات الاجتماعيّة بفضل العمل النقابي، وانتقالهم إلى بلاد نامية فقيرة. 4) تحوّل أصحاب الرساميل إلى تجهيزات تكنولوجيّة ترفع الإنتاج ولا ترفع فرص العمل (لوحظ منذ مطلع السبعينات).', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15747, 2374, 1, 'في الأسرة الممتدّة كان الجدّ والجدّة محور الانتماء، ورؤساء العائلة من الشيوخ، وكان الوسط التقليدي القرابي أكثر رعاية لهم وحاجة إلى درايتهم. لكنّ التفكّك الاقتصادي والاجتماعي بين الأسر النواتية جعل كثيراً منهم يعانون العزلة في المدينة والأرياف، ويزيد ذلك تعاظم العجز ومعاناة حوالى ثلث المسنّين أمراضاً مزمنة ترتفع أكلافها، ممّا يُبرز أهمّية خدمات الرعاية الحكوميّة والأهليّة.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15748, 2374, 2, 'في الأسرة الممتدّة كان الجدّ والجدّة محور الانتماء، ورؤساء العائلة من الشيوخ، وكان الوسط التقليدي القرابي أكثر رعاية لهم وحاجة إلى درايتهم. لكنّ التفكّك الاقتصادي والاجتماعي بين الأسر النواتية جعل كثيراً منهم يعانون العزلة في المدينة والأرياف، ويزيد ذلك تعاظم العجز ومعاناة حوالى ثلث المسنّين أمراضاً مزمنة ترتفع أكلافها، ممّا يُبرز أهمّية خدمات الرعاية الحكوميّة والأهليّة.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15749, 2375, 1, 'لأنّ البطالة المتوسّعة، السافرة والمقنّعة، ولا سيّما في أعقاب الحروب، قد تؤدّي إلى اضطرابات اجتماعيّة وسياسيّة تهدّد النظام السياسي والاقتصادي، فنظّمت هذه الدول أجهزة الضمان لمواجهتها، وكانت إنكلترا هي المبادرة. وارتكز الضمان على تقرير وليام بفريدج: حماية الأجراء اجتماعياً مع المحافظة على قدرتهم الشرائيّة وكفايتهم المعيشيّة، فلكي تبيع يجب أن يملك الناس القدرة على الشراء.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15750, 2375, 2, 'لأنّ البطالة المتوسّعة، السافرة والمقنّعة، ولا سيّما في أعقاب الحروب، قد تؤدّي إلى اضطرابات اجتماعيّة وسياسيّة تهدّد النظام السياسي والاقتصادي، فنظّمت هذه الدول أجهزة الضمان لمواجهتها، وكانت إنكلترا هي المبادرة. وارتكز الضمان على تقرير وليام بفريدج: حماية الأجراء اجتماعياً مع المحافظة على قدرتهم الشرائيّة وكفايتهم المعيشيّة، فلكي تبيع يجب أن يملك الناس القدرة على الشراء.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15751, 2376, 1, '1) الرعاية المغلقة: في مؤسّسات تتعاقد معها وزارة الشؤون الاجتماعيّة. 2) الرعاية المفتوحة: رعاية العاجز في أسرته مع مساعدة الأسرة وتأهيلها. 3) دور ومراكز النقاهة: لا يقصدها إلّا القادرون على أكلافها. 4) الرعاية المستترة: يقوم بها بعض أهل الخير لدوافع دينيّة أو اجتماعيّة أو سياسيّة.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15752, 2376, 2, '1) الرعاية المغلقة: في مؤسّسات تتعاقد معها وزارة الشؤون الاجتماعيّة. 2) الرعاية المفتوحة: رعاية العاجز في أسرته مع مساعدة الأسرة وتأهيلها. 3) دور ومراكز النقاهة: لا يقصدها إلّا القادرون على أكلافها. 4) الرعاية المستترة: يقوم بها بعض أهل الخير لدوافع دينيّة أو اجتماعيّة أو سياسيّة.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15753, 2377, 1, '1) توسّع كلفة خدمات المضمونين وارتفاعها. 2) تراجع ما يدخل إلى صندوق الضمان مع زيادة مدفوعاته لتعويض التعطّل عن العمل. 3) ارتفاع نسبة المسنّين. ويُضاف ضغط القوى النقابيّة والسياسيّة المدافعة عن الضمانات المكتسبة. والنتيجة عجز متزايد تضطرّ الدولة إلى تغطيته، وجدل حول تخصيص الضمانات.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15754, 2377, 2, '1) توسّع كلفة خدمات المضمونين وارتفاعها. 2) تراجع ما يدخل إلى صندوق الضمان مع زيادة مدفوعاته لتعويض التعطّل عن العمل. 3) ارتفاع نسبة المسنّين. ويُضاف ضغط القوى النقابيّة والسياسيّة المدافعة عن الضمانات المكتسبة. والنتيجة عجز متزايد تضطرّ الدولة إلى تغطيته، وجدل حول تخصيص الضمانات.', 1, '2026-09-30 22:12:13', '2026-09-30 22:12:13'),
(15755, 2378, 1, 'التعريف الدولي: المعوق من يواجه حواجز ثقافيّة أو ماديّة أو اجتماعيّة تمنعه من الوصول إلى ما هو متاح للمواطنين الآخرين، والنتيجة فقدان الفرص أو تحديدها لتأدية دور في الحياة والمجتمع على قدم المساواة مع الآخرين. الاتفاقية العربيّة: المعاق من يعاني نقصاً في بعض قدراته الجسديّة أو الحسّيّة أو الذهنيّة نتيجة مرض أو حادث أو سبب خَلقي أو عامل وراثي، والنتيجة عجزه كلياً أو جزئياً عن العمل أو الاستمرار فيه أو الترقّي، وضعف قدرته على إحدى الوظائف الأساسيّة في الحياة. والتعريف العربي مشابه للدولي لكنّه يتضمّن تفاصيل أوسع.', 1, '2026-09-30 22:12:14', '2026-09-30 22:12:14'),
(15756, 2378, 2, 'التعريف الدولي: المعوق من يواجه حواجز ثقافيّة أو ماديّة أو اجتماعيّة تمنعه من الوصول إلى ما هو متاح للمواطنين الآخرين، والنتيجة فقدان الفرص أو تحديدها لتأدية دور في الحياة والمجتمع على قدم المساواة مع الآخرين. الاتفاقية العربيّة: المعاق من يعاني نقصاً في بعض قدراته الجسديّة أو الحسّيّة أو الذهنيّة نتيجة مرض أو حادث أو سبب خَلقي أو عامل وراثي، والنتيجة عجزه كلياً أو جزئياً عن العمل أو الاستمرار فيه أو الترقّي، وضعف قدرته على إحدى الوظائف الأساسيّة في الحياة. والتعريف العربي مشابه للدولي لكنّه يتضمّن تفاصيل أوسع.', 1, '2026-09-30 22:12:14', '2026-09-30 22:12:14'),
(15757, 2379, 1, 'المجتمعات الغنيّة قادرة على الوقاية وعلى تحويل المعوقين من عالة إلى طاقة منتجة. أمّا في البلدان الفقيرة والنامية فترتفع الإعاقة بسبب: الحروب، وسوء التغذية، وضعف الخدمات الطبّيّة الوقائيّة، ورواج المفاهيم والقيم التقليديّة الظالمة، والجهل بنتائج بعض الممارسات كالزواج من الأقارب. والنتيجة ازدياد أعداد المعوقين وعجز المجتمع عن رعايتهم وازدياد مأساويّة حياتهم.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15758, 2379, 2, 'المجتمعات الغنيّة قادرة على الوقاية وعلى تحويل المعوقين من عالة إلى طاقة منتجة. أمّا في البلدان الفقيرة والنامية فترتفع الإعاقة بسبب: الحروب، وسوء التغذية، وضعف الخدمات الطبّيّة الوقائيّة، ورواج المفاهيم والقيم التقليديّة الظالمة، والجهل بنتائج بعض الممارسات كالزواج من الأقارب. والنتيجة ازدياد أعداد المعوقين وعجز المجتمع عن رعايتهم وازدياد مأساويّة حياتهم.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15759, 2380, 1, 'العبارة خاطئة. فالتعريف الدولي يرى الإعاقة فقداناً للفرص بسبب حواجز، لا عجزاً مطلقاً. والمجتمعات المتطوّرة تحوّل المعوقين من عالة إلى طاقة منتجة. ومؤسّسات حكوميّة وخاصّة كثيرة تشغّل معوقين في مراكز لا تتطلّب جهداً حركياً أساسياً. ومن الأمثلة: طه حسين الأعمى، وبيتهوفن الأصمّ، والعضو المكفوف في المجلس البلدي لمدينة الميناء في طرابلس. فالمطلوب حقوق وفرص ودمج، لا إحسان فقط.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15760, 2380, 2, 'العبارة خاطئة. فالتعريف الدولي يرى الإعاقة فقداناً للفرص بسبب حواجز، لا عجزاً مطلقاً. والمجتمعات المتطوّرة تحوّل المعوقين من عالة إلى طاقة منتجة. ومؤسّسات حكوميّة وخاصّة كثيرة تشغّل معوقين في مراكز لا تتطلّب جهداً حركياً أساسياً. ومن الأمثلة: طه حسين الأعمى، وبيتهوفن الأصمّ، والعضو المكفوف في المجلس البلدي لمدينة الميناء في طرابلس. فالمطلوب حقوق وفرص ودمج، لا إحسان فقط.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15761, 2381, 1, 'المواقف الثلاثة: القبول ويدعو إلى تدعيم القيم، والتحفّظ ويدعو إلى إصلاحها، والرفض ويدعو إلى تغييرها. والرفض نوعان: رفض بالوسائل التي تسمح بها القوانين، ورفض بوسائل عنيفة تمنعها القوانين. والرفض العنيف الذي تمنعه القوانين هو ما يسمّى تطرّفاً.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15762, 2381, 2, 'المواقف الثلاثة: القبول ويدعو إلى تدعيم القيم، والتحفّظ ويدعو إلى إصلاحها، والرفض ويدعو إلى تغييرها. والرفض نوعان: رفض بالوسائل التي تسمح بها القوانين، ورفض بوسائل عنيفة تمنعها القوانين. والرفض العنيف الذي تمنعه القوانين هو ما يسمّى تطرّفاً.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15763, 2382, 1, 'تظهر الحركات المتطرّفة في الغالب ردود فعل عنيفة على هزائم كبرى، أو على أخطار خارجيّة تهدّد سيادة الأمّة وحضارتها، أو على أخطار داخليّة تهدّد جماعات معيّنة في وجودها وقيمها ومعتقداتها، ويزيد من ذلك التهميش وتقصير النخب الحاكمة، فتقدّم نفسها كمنقذة. وتجذب الطبقات الشعبيّة التي تعاني الانهزام أو التهميش، ويتعاظم جذبها حين ترتدي طابع التديّن فتضفي على أقوالها وأفعالها نوعاً من القداسة، وتعد الناس بالخلاص في دنياهم والفوز في آخرتهم.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15764, 2382, 2, 'تظهر الحركات المتطرّفة في الغالب ردود فعل عنيفة على هزائم كبرى، أو على أخطار خارجيّة تهدّد سيادة الأمّة وحضارتها، أو على أخطار داخليّة تهدّد جماعات معيّنة في وجودها وقيمها ومعتقداتها، ويزيد من ذلك التهميش وتقصير النخب الحاكمة، فتقدّم نفسها كمنقذة. وتجذب الطبقات الشعبيّة التي تعاني الانهزام أو التهميش، ويتعاظم جذبها حين ترتدي طابع التديّن فتضفي على أقوالها وأفعالها نوعاً من القداسة، وتعد الناس بالخلاص في دنياهم والفوز في آخرتهم.', 1, '2026-09-30 22:12:15', '2026-09-30 22:12:15'),
(15765, 2383, 1, 'التطرّف السياسي يقوم على فرض تعريف معيّن لحقوق الأفراد والجماعات، وفرض ذهنيّة متطرّفة في حكم البلاد. وهو يدفع إلى رفض الآخر وإقصائه عن المشاركة في الرأي والقرار، وأحياناً إلى القضاء عليه. مثاله ألمانيا النازيّة وإيطاليا الفاشيّة، ومن نتائجه أنّه دفعهما إلى اجتياح بلدان كثيرة في الحرب العالميّة الثانية.', 1, '2026-09-30 22:12:16', '2026-09-30 22:12:16'),
(15766, 2383, 2, 'التطرّف السياسي يقوم على فرض تعريف معيّن لحقوق الأفراد والجماعات، وفرض ذهنيّة متطرّفة في حكم البلاد. وهو يدفع إلى رفض الآخر وإقصائه عن المشاركة في الرأي والقرار، وأحياناً إلى القضاء عليه. مثاله ألمانيا النازيّة وإيطاليا الفاشيّة، ومن نتائجه أنّه دفعهما إلى اجتياح بلدان كثيرة في الحرب العالميّة الثانية.', 1, '2026-09-30 22:12:16', '2026-09-30 22:12:16'),
(15767, 2384, 1, 'أوّلاً، الطاقة البخارية طوّرت النقل البحري والتجارة. ثانياً، تجمّعت المصانع حول أسواق المدن، فجذبت اليد العاملة الفائضة عن حاجة الزراعة. ثالثاً، صنع التصنيع آلات زراعية كالجرّارات والحصّادات والبذّارات، فعوّض الأرياف عن نزوح عمّالها.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15768, 2384, 2, 'أوّلاً، الطاقة البخارية طوّرت النقل البحري والتجارة. ثانياً، تجمّعت المصانع حول أسواق المدن، فجذبت اليد العاملة الفائضة عن حاجة الزراعة. ثالثاً، صنع التصنيع آلات زراعية كالجرّارات والحصّادات والبذّارات، فعوّض الأرياف عن نزوح عمّالها.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15769, 2385, 1, 'أوّلاً، الآفتان تهدّدان صحة الفرد الجسديّة والنفسيّة الاجتماعيّة. ثانياً، تهدّدان عيش الأسرة وسلامتها وكرامتها ومستقبلها في محيطها الاجتماعي. ثالثاً، تطالان التنمية، وتحمّلان المجتمع أعباء متزايدة للوقاية والعلاج.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15770, 2385, 2, 'أوّلاً، الآفتان تهدّدان صحة الفرد الجسديّة والنفسيّة الاجتماعيّة. ثانياً، تهدّدان عيش الأسرة وسلامتها وكرامتها ومستقبلها في محيطها الاجتماعي. ثالثاً، تطالان التنمية، وتحمّلان المجتمع أعباء متزايدة للوقاية والعلاج.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15771, 2386, 1, 'التضامن شبكة الروابط الاجتماعية التي تشدّ أفراد المجتمع بعضهم إلى بعض فتوحّدهم. التضامن اللاإرادي يهيمن فيه على المجتمع كلّ ما هو عامّ وجماعي على حساب إرادة الفرد، ومثاله تضامن أفراد العائلة أو الطائفة أو الحيّ. التضامن الإرادي يبرز فيه الإنسان الفرد كعضو داخل المجتمع فتظهر كفاءاته ومهاراته، ومثاله الانضمام إلى النقابات أو الأحزاب أو الجمعيات. والمعيار الفاصل بينهما إرادة الفرد.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15772, 2386, 2, 'التضامن شبكة الروابط الاجتماعية التي تشدّ أفراد المجتمع بعضهم إلى بعض فتوحّدهم. التضامن اللاإرادي يهيمن فيه على المجتمع كلّ ما هو عامّ وجماعي على حساب إرادة الفرد، ومثاله تضامن أفراد العائلة أو الطائفة أو الحيّ. التضامن الإرادي يبرز فيه الإنسان الفرد كعضو داخل المجتمع فتظهر كفاءاته ومهاراته، ومثاله الانضمام إلى النقابات أو الأحزاب أو الجمعيات. والمعيار الفاصل بينهما إرادة الفرد.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15773, 2387, 1, '1) نزف القوى العاملة الشابّة المنفتحة على التطوّر التقني والاقتصادي. 2) تدهور الموارد الإنتاجية الزراعية. 3) تراجع الجدوى الاقتصادية والاجتماعية للخدمات العامّة. شرح الثالث: هذه المرافق صُمِّمت لكلّ السكان المسجّلين، لكنّ المقيمين وحدهم يستفيدون من أكلافها العالية، وعددهم قليل، وقد ينخفض إلى الثلث في الشتاء.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15774, 2387, 2, '1) نزف القوى العاملة الشابّة المنفتحة على التطوّر التقني والاقتصادي. 2) تدهور الموارد الإنتاجية الزراعية. 3) تراجع الجدوى الاقتصادية والاجتماعية للخدمات العامّة. شرح الثالث: هذه المرافق صُمِّمت لكلّ السكان المسجّلين، لكنّ المقيمين وحدهم يستفيدون من أكلافها العالية، وعددهم قليل، وقد ينخفض إلى الثلث في الشتاء.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15775, 2388, 1, 'المخدّرات تؤثّر في الجسد والنفس معاً، وتختلف المعالجة باختلاف أنواع المخدّرات وفاعليّتها. لذلك يحتاج المدمن أوّلاً إلى تدخّل طبي في الساعات الأولى لتطهير الجسم من آثار المخدّر وفطام الجهاز العصبي وتهدئة الانفعالات. لكنّ الدواء وحده لا يكفي، فالمعالجة النفسيّة الاجتماعيّة تساعد المدمن على التعبير بعفويّة عمّا يكبته واكتساب إرادة التحوّل إلى معايير جديدة يحقّق بها ذاته. واختيار الطريقة يتبع التشخيص ونوع المخدّر.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15776, 2388, 2, 'المخدّرات تؤثّر في الجسد والنفس معاً، وتختلف المعالجة باختلاف أنواع المخدّرات وفاعليّتها. لذلك يحتاج المدمن أوّلاً إلى تدخّل طبي في الساعات الأولى لتطهير الجسم من آثار المخدّر وفطام الجهاز العصبي وتهدئة الانفعالات. لكنّ الدواء وحده لا يكفي، فالمعالجة النفسيّة الاجتماعيّة تساعد المدمن على التعبير بعفويّة عمّا يكبته واكتساب إرادة التحوّل إلى معايير جديدة يحقّق بها ذاته. واختيار الطريقة يتبع التشخيص ونوع المخدّر.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15777, 2389, 1, 'يكون النزوح ضرورة للتقدّم حين يجذبه التصنيع وتعوّض الآلات الزراعة عن عمّالها، كما في أوروبا، أو حين يعود ادّخار النازحين على تحسين الزراعة والعمران الريفي، كما في موجات النزوح الأولى في لبنان. ويصبح عاملاً من عوامل التخلّف حين ينتج عن إهمال الزراعة، فيُفرغ الريف من شبابه، ويُغرق المدن بموجات لم يُخطَّط لها.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15778, 2389, 2, 'يكون النزوح ضرورة للتقدّم حين يجذبه التصنيع وتعوّض الآلات الزراعة عن عمّالها، كما في أوروبا، أو حين يعود ادّخار النازحين على تحسين الزراعة والعمران الريفي، كما في موجات النزوح الأولى في لبنان. ويصبح عاملاً من عوامل التخلّف حين ينتج عن إهمال الزراعة، فيُفرغ الريف من شبابه، ويُغرق المدن بموجات لم يُخطَّط لها.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15779, 2390, 1, 'التكيّف مجموعة الآليات التي يقوم بها الفرد ليجعل من نفسه أهلاً لعضوية المجتمع. جماعة الانتماء هي التي ينتمي إليها الفرد أصلاً وفعلاً وهي ذات أولوية عنده (العائلة، الطائفة، الحيّ)، وجماعة المرجع هي التي يقتدي بها ويقلّدها دون أن يكون عضواً فيها (الجامعة، النادي، الحزب، النقابة). ووجه الصراع أنّ الفرد مطالب بتغيير آرائه وقيمه ومواقفه لتناسب جماعة المرجع، بينما تشدّه جماعة انتمائه إلى قيمها هي.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15780, 2390, 2, 'التكيّف مجموعة الآليات التي يقوم بها الفرد ليجعل من نفسه أهلاً لعضوية المجتمع. جماعة الانتماء هي التي ينتمي إليها الفرد أصلاً وفعلاً وهي ذات أولوية عنده (العائلة، الطائفة، الحيّ)، وجماعة المرجع هي التي يقتدي بها ويقلّدها دون أن يكون عضواً فيها (الجامعة، النادي، الحزب، النقابة). ووجه الصراع أنّ الفرد مطالب بتغيير آرائه وقيمه ومواقفه لتناسب جماعة المرجع، بينما تشدّه جماعة انتمائه إلى قيمها هي.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15781, 2391, 1, 'في فرنسا، وهي بلد صناعي، جهود منظّمة وموازنات ملحوظة: تشكّلت لجان وزاريّة وبحثيّة ووُضعت برامج، ومن ثمارها المعالجة الثلاثيّة المكلفة التي خفّضت معدّل وفيات المصابين. أمّا في البلدان النامية والفقيرة فالعدوى تنتشر أحياناً بشكل رهيب، والجهود ما زالت ضئيلة، والآفة تكبر مع توسّع الفقر والجهل.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15782, 2391, 2, 'في فرنسا، وهي بلد صناعي، جهود منظّمة وموازنات ملحوظة: تشكّلت لجان وزاريّة وبحثيّة ووُضعت برامج، ومن ثمارها المعالجة الثلاثيّة المكلفة التي خفّضت معدّل وفيات المصابين. أمّا في البلدان النامية والفقيرة فالعدوى تنتشر أحياناً بشكل رهيب، والجهود ما زالت ضئيلة، والآفة تكبر مع توسّع الفقر والجهل.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15783, 2392, 1, 'أصناف الشروط ثلاثة: شروط اقتصادية واجتماعية، وشروط تربوية وثقافية، وشروط سياسية. الشروط السياسية: كلّما كان المجتمع أكثر ديمقراطية كان أكثر مشاركة، وكلّما تحقّقت المشاركة تحقّق الاندماج الاجتماعي؛ وإذا كان النظام ديكتاتورياً فلا تكون هناك مشاركة فتصعب عملية الاندماج. وشروط الديمقراطية: الحقّ بالعدالة والحماية، وحرية الإعلام والتعبير والنشر، وحرية الترشّح والانتخاب في مجلس النوّاب ومجلس البلدية.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15784, 2392, 2, 'أصناف الشروط ثلاثة: شروط اقتصادية واجتماعية، وشروط تربوية وثقافية، وشروط سياسية. الشروط السياسية: كلّما كان المجتمع أكثر ديمقراطية كان أكثر مشاركة، وكلّما تحقّقت المشاركة تحقّق الاندماج الاجتماعي؛ وإذا كان النظام ديكتاتورياً فلا تكون هناك مشاركة فتصعب عملية الاندماج. وشروط الديمقراطية: الحقّ بالعدالة والحماية، وحرية الإعلام والتعبير والنشر، وحرية الترشّح والانتخاب في مجلس النوّاب ومجلس البلدية.', 1, '2026-09-30 22:12:17', '2026-09-30 22:12:17'),
(15785, 2393, 1, 'التغير الطبيعي بطيء ومتدرّج ويحصل بنسب متفاوتة، ومثاله التصحّر أو الاحتباس الحراري أو الفيضانات أو الكوارث الطبيعية والبيئية. التغير الجذري تحوّل عميق وسريع يحصل في بنية المجتمع السياسية والاقتصادية والاجتماعية والثقافية والقيمية، ويسمّى عادةً الثورة. والفرق الجوهري بينهما في الإيقاع والعمق.', 1, '2026-09-30 22:12:18', '2026-09-30 22:12:18'),
(15786, 2393, 2, 'التغير الطبيعي بطيء ومتدرّج ويحصل بنسب متفاوتة، ومثاله التصحّر أو الاحتباس الحراري أو الفيضانات أو الكوارث الطبيعية والبيئية. التغير الجذري تحوّل عميق وسريع يحصل في بنية المجتمع السياسية والاقتصادية والاجتماعية والثقافية والقيمية، ويسمّى عادةً الثورة. والفرق الجوهري بينهما في الإيقاع والعمق.', 1, '2026-09-30 22:12:18', '2026-09-30 22:12:18'),
(15787, 2394, 1, 'نظرية الثورة (كارل ماركس): الثورة حتمية ولا بدّ للعمال أن يثوروا على الطبقة الحاكمة؛ التغير الحقيقي هو التغير الجذري الذي يبدأ من السلطة السياسية؛ التوتّرات بين الطبقات سببها التوزيع غير المتكافئ لوسائل الإنتاج. نظرية الإصلاح: التجارب في أكثرية دول أوروبا أثبتت أنّ الثورة ليست حتمية؛ يمكن للدول أن تقوم بإصلاحات كإنشاء الضمان الاجتماعي والنقابات للدفاع عن حقوق العاملين؛ هذه الإصلاحات خفّفت من التوتّر الطبقي بين الطبقات الاجتماعية.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15788, 2394, 2, 'نظرية الثورة (كارل ماركس): الثورة حتمية ولا بدّ للعمال أن يثوروا على الطبقة الحاكمة؛ التغير الحقيقي هو التغير الجذري الذي يبدأ من السلطة السياسية؛ التوتّرات بين الطبقات سببها التوزيع غير المتكافئ لوسائل الإنتاج. نظرية الإصلاح: التجارب في أكثرية دول أوروبا أثبتت أنّ الثورة ليست حتمية؛ يمكن للدول أن تقوم بإصلاحات كإنشاء الضمان الاجتماعي والنقابات للدفاع عن حقوق العاملين؛ هذه الإصلاحات خفّفت من التوتّر الطبقي بين الطبقات الاجتماعية.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15789, 2395, 1, 'مثلاً: مستوى التعليم، فكلّما ارتفع دلّ على تقدّم المجتمع وكلّما انخفض دلّ على تخلّفه. الأمل في الحياة أو العمر المتوقّع عند الولادة، فكلّما ارتفع دلّ على تحسّن الخدمات الصحية والطبية. مدى توزّع المداخيل، أي مدى إعادة توزيعها بين شرائح المجتمع، ويتعلّق بالضرائب التصاعدية التي تؤخذ من الأغنياء وتعطى للفقراء. (يُقبل أيضاً: مستوى المديونية، مستوى الدخل، مستوى الديمقراطية والمشاركة ومؤشّراته: حرية التعبير والإعلام والنشر، حرية الترشّح والانتخاب في المجالس النيابية، الحق في العدالة والحماية.)', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15790, 2395, 2, 'مثلاً: مستوى التعليم، فكلّما ارتفع دلّ على تقدّم المجتمع وكلّما انخفض دلّ على تخلّفه. الأمل في الحياة أو العمر المتوقّع عند الولادة، فكلّما ارتفع دلّ على تحسّن الخدمات الصحية والطبية. مدى توزّع المداخيل، أي مدى إعادة توزيعها بين شرائح المجتمع، ويتعلّق بالضرائب التصاعدية التي تؤخذ من الأغنياء وتعطى للفقراء. (يُقبل أيضاً: مستوى المديونية، مستوى الدخل، مستوى الديمقراطية والمشاركة ومؤشّراته: حرية التعبير والإعلام والنشر، حرية الترشّح والانتخاب في المجالس النيابية، الحق في العدالة والحماية.)', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15791, 2396, 1, 'دولة العناية هي الدولة الضامنة للعدالة الاجتماعية، ووجودها يدلّ على التقدّم والرقيّ، ولا يمكن تحقيقها من دون ربطها بمفهوم المواطنية. وظائفها: 1) الضبط والتوازن من خلال تشريع قانون العمل وقانون الأجور، فتضبط توازن النشاط الاقتصادي عن طريق دفع العجلة الاقتصادية في مراحل الجمود. 2) رصد الموارد العامّة، أي رصد اعتمادات التمويل للإدارات العامّة والرسمية ولأجهزة الدفاع العسكري. 3) تقديم الخدمات الاجتماعية، أي الإنعاش الاجتماعي من خلال وزارتَي التعليم والصحّة.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15792, 2396, 2, 'دولة العناية هي الدولة الضامنة للعدالة الاجتماعية، ووجودها يدلّ على التقدّم والرقيّ، ولا يمكن تحقيقها من دون ربطها بمفهوم المواطنية. وظائفها: 1) الضبط والتوازن من خلال تشريع قانون العمل وقانون الأجور، فتضبط توازن النشاط الاقتصادي عن طريق دفع العجلة الاقتصادية في مراحل الجمود. 2) رصد الموارد العامّة، أي رصد اعتمادات التمويل للإدارات العامّة والرسمية ولأجهزة الدفاع العسكري. 3) تقديم الخدمات الاجتماعية، أي الإنعاش الاجتماعي من خلال وزارتَي التعليم والصحّة.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15793, 2397, 1, 'الأسباب: ازدياد الهوّة بين الطبقات والفئات الاجتماعية؛ السياسة الإصلاحية الشاملة التي بدأ تطبيقها الرئيس فؤاد شهاب؛ التأكيد على التزام لبنان بالإعلان العالميّ لحقوق الإنسان الذي أكّد ضرورة تطبيق الضمان الاجتماعي حماية للمواطنين. الفرق: الخضوع الإلزاميّ يمثّل النظام العامّ للضمان ويشمل كلّ المواطنين أو أكثريّتهم ويتميّز بأربعة فروع، أمّا الخضوع الاختياريّ فيشمل غير المضمونين أو الذين يفقدون شروط الانتساب الإلزاميّ ويشمل ثلاثة فروع فقط، ما عدا فرع تعويض نهاية الخدمة.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15794, 2397, 2, 'الأسباب: ازدياد الهوّة بين الطبقات والفئات الاجتماعية؛ السياسة الإصلاحية الشاملة التي بدأ تطبيقها الرئيس فؤاد شهاب؛ التأكيد على التزام لبنان بالإعلان العالميّ لحقوق الإنسان الذي أكّد ضرورة تطبيق الضمان الاجتماعي حماية للمواطنين. الفرق: الخضوع الإلزاميّ يمثّل النظام العامّ للضمان ويشمل كلّ المواطنين أو أكثريّتهم ويتميّز بأربعة فروع، أمّا الخضوع الاختياريّ فيشمل غير المضمونين أو الذين يفقدون شروط الانتساب الإلزاميّ ويشمل ثلاثة فروع فقط، ما عدا فرع تعويض نهاية الخدمة.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15795, 2398, 1, 'النشاط الاقتصادي: يرتبط سكان المدن بالإنتاج التجاري والمالي وبالقطاعات الخدماتية، ويرتبط سكان الريف بقطاع الزراعة. شكل العائلة: في المدينة عائلة نواتية تعيش في منزل هو جزء من تجمّع سكاني يضمّ عائلات مختلفة يجمعها التجاور، وفي الريف عائلة ممتدّة يعيش أفرادها أو يسكنون بشكل متجاور. الانتماءات: تتعدّد في المدينة، وتنحصر في الريف في العائلة والطائفة. والاستنتاج أنّ اختلاف النشاط الاقتصادي يفسّر اختلاف شكل العائلة وطبيعة الانتماء.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15796, 2398, 2, 'النشاط الاقتصادي: يرتبط سكان المدن بالإنتاج التجاري والمالي وبالقطاعات الخدماتية، ويرتبط سكان الريف بقطاع الزراعة. شكل العائلة: في المدينة عائلة نواتية تعيش في منزل هو جزء من تجمّع سكاني يضمّ عائلات مختلفة يجمعها التجاور، وفي الريف عائلة ممتدّة يعيش أفرادها أو يسكنون بشكل متجاور. الانتماءات: تتعدّد في المدينة، وتنحصر في الريف في العائلة والطائفة. والاستنتاج أنّ اختلاف النشاط الاقتصادي يفسّر اختلاف شكل العائلة وطبيعة الانتماء.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15797, 2399, 1, 'المواطنية هي مشاركة الناس في صنع السياسات الاجتماعية، ولا يمكن الوصول إلى الديمقراطية ولا إلى دولة العناية من دون ربطها بها، أي بدور المواطن في المشاركة والبناء ودفع الضريبة للدولة والمشاركة في الحياة السياسية، لكي تؤمّن الدولة التعليم والصحّة والسكن. والضريبة أداة ماليّة تموّل خزينة الدولة، وهي في الوقت نفسه أداة اجتماعية لتنفيذ السياسات.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15798, 2399, 2, 'المواطنية هي مشاركة الناس في صنع السياسات الاجتماعية، ولا يمكن الوصول إلى الديمقراطية ولا إلى دولة العناية من دون ربطها بها، أي بدور المواطن في المشاركة والبناء ودفع الضريبة للدولة والمشاركة في الحياة السياسية، لكي تؤمّن الدولة التعليم والصحّة والسكن. والضريبة أداة ماليّة تموّل خزينة الدولة، وهي في الوقت نفسه أداة اجتماعية لتنفيذ السياسات.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15799, 2400, 1, 'الحراك الأفقي: انتقال من مستوى اجتماعي اقتصادي إلى مستوى اجتماعي اقتصادي مماثل من دون أن يترافق مع تغيير في مستوى العيش، مثاله عامل النسيج الذي أصبح عاملاً في مصنع أحذية. الحراك العامودي: انتقال من مستوى أدنى إلى مستوى أعلى أو العكس مع تغيّر في مستوى العيش؛ مثال الصاعد: تحوّل فلاح إلى صاحب أرض، ومثال الهابط: تحوّل ربّ عمل إلى عامل مأجور. المعيار الفاصل: تغيّر مستوى العيش.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15800, 2400, 2, 'الحراك الأفقي: انتقال من مستوى اجتماعي اقتصادي إلى مستوى اجتماعي اقتصادي مماثل من دون أن يترافق مع تغيير في مستوى العيش، مثاله عامل النسيج الذي أصبح عاملاً في مصنع أحذية. الحراك العامودي: انتقال من مستوى أدنى إلى مستوى أعلى أو العكس مع تغيّر في مستوى العيش؛ مثال الصاعد: تحوّل فلاح إلى صاحب أرض، ومثال الهابط: تحوّل ربّ عمل إلى عامل مأجور. المعيار الفاصل: تغيّر مستوى العيش.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15801, 2401, 1, 'وظائف أهل الحلّ والربط: حلّ المشاكل أو تعقيدها؛ المشاركة في الأفراح والأتراح والمناسبات الرسمية؛ المشاركة في الانتخابات البلدية والنيابية. أمّا رؤساء الجمعيات فيقدّمون خدمات للناس لازدياد شهرتهم، فيتصدّرون في الانتخابات، فيصلون إلى المجلس النيابي ومجلس الوزراء؛ فهم يستخدمون الجمعيات وسيلةً للوصول إلى السلطة.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15802, 2401, 2, 'وظائف أهل الحلّ والربط: حلّ المشاكل أو تعقيدها؛ المشاركة في الأفراح والأتراح والمناسبات الرسمية؛ المشاركة في الانتخابات البلدية والنيابية. أمّا رؤساء الجمعيات فيقدّمون خدمات للناس لازدياد شهرتهم، فيتصدّرون في الانتخابات، فيصلون إلى المجلس النيابي ومجلس الوزراء؛ فهم يستخدمون الجمعيات وسيلةً للوصول إلى السلطة.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15803, 2402, 1, 'العوامل: التغيّر الاجتماعي الواسع النطاق، ووسائل الاتّصال، وتقسيم العمل، والعامل الديمغرافي (النموّ السكّاني والنزوح والهجرة). التغيّر الجذري (الثورة) سبب من أسباب الحراك، لأنّ التغيّر الاجتماعي الواسع النطاق يسهّل الانتقال من مستوى أدنى إلى أعلى أو العكس، ويسهّل الدخول إلى الطبقة أو الخروج منها.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15804, 2402, 2, 'العوامل: التغيّر الاجتماعي الواسع النطاق، ووسائل الاتّصال، وتقسيم العمل، والعامل الديمغرافي (النموّ السكّاني والنزوح والهجرة). التغيّر الجذري (الثورة) سبب من أسباب الحراك، لأنّ التغيّر الاجتماعي الواسع النطاق يسهّل الانتقال من مستوى أدنى إلى أعلى أو العكس، ويسهّل الدخول إلى الطبقة أو الخروج منها.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15805, 2403, 1, 'الحداثة تعني إضفاء نظرة عقلية على العالم، كما تُطلق على مجموعة من المتغيّرات المؤثّرة في المجتمعات الإنسانية، وإن بنسب متفاوتة وبناءً على أولويات كلّ مجتمع. مظاهر التجديد: تبدّل عميق في طرق العيش والإنتاج؛ تراجع الإنتاج الزراعي أمام المؤسسات الصناعية والتجارية مع انحسار العمل الحرفي، فتغيّر شكل التضامن من أوّلي إلى ثانوي ومن آلي إلى عضوي؛ النزوح من الحارات والقرى إلى المدن، فتبدّلت علاقات السكان وتحوّلت العائلة من ممتدّة إلى نواتية.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15806, 2403, 2, 'الحداثة تعني إضفاء نظرة عقلية على العالم، كما تُطلق على مجموعة من المتغيّرات المؤثّرة في المجتمعات الإنسانية، وإن بنسب متفاوتة وبناءً على أولويات كلّ مجتمع. مظاهر التجديد: تبدّل عميق في طرق العيش والإنتاج؛ تراجع الإنتاج الزراعي أمام المؤسسات الصناعية والتجارية مع انحسار العمل الحرفي، فتغيّر شكل التضامن من أوّلي إلى ثانوي ومن آلي إلى عضوي؛ النزوح من الحارات والقرى إلى المدن، فتبدّلت علاقات السكان وتحوّلت العائلة من ممتدّة إلى نواتية.', 1, '2026-09-30 22:12:19', '2026-09-30 22:12:19'),
(15807, 2404, 1, 'أشكال النزوح: النزوح الدائم (انتقال دائم إلى المدن مع قطع كلّ العلاقات مع الأماكن التي وُلدوا فيها والاندماج في المناطق التي نزحوا إليها)، والنزوح شبه الدائم (تركوا منزلاً في القرية يعودون إليه في الصيف أو في العطل)، والنزوح المؤقّت (بسبب العمل أو الدراسة أو الأوضاع السياسية والأمنية، كالذين هُجّروا من جنوب لبنان نتيجة العدوان الإسرائيلي). نتيجتان سلبيتان للهجرة: خسارة الأدمغة وذوي الكفاءات العلمية والمهنية، وخسارة اليد العاملة الماهرة (أو: خلل في الهرم السكّاني مع تأخّر سنّ الزواج وارتفاع نسب العزوبة وانخفاض الولادات).', 1, '2026-09-30 22:12:20', '2026-09-30 22:12:20'),
(15808, 2404, 2, 'أشكال النزوح: النزوح الدائم (انتقال دائم إلى المدن مع قطع كلّ العلاقات مع الأماكن التي وُلدوا فيها والاندماج في المناطق التي نزحوا إليها)، والنزوح شبه الدائم (تركوا منزلاً في القرية يعودون إليه في الصيف أو في العطل)، والنزوح المؤقّت (بسبب العمل أو الدراسة أو الأوضاع السياسية والأمنية، كالذين هُجّروا من جنوب لبنان نتيجة العدوان الإسرائيلي). نتيجتان سلبيتان للهجرة: خسارة الأدمغة وذوي الكفاءات العلمية والمهنية، وخسارة اليد العاملة الماهرة (أو: خلل في الهرم السكّاني مع تأخّر سنّ الزواج وارتفاع نسب العزوبة وانخفاض الولادات).', 1, '2026-09-30 22:12:20', '2026-09-30 22:12:20'),
(15809, 2405, 1, 'التدرج الاجتماعي هو العملية التي عن طريقها يُرتَّب الأفراد والجماعات ضمن سلسلة متدرجة من المراكز، ويُسمّى أيضاً التفريق الاجتماعي أو الترتيب الاجتماعي. يُقاس وفق معيارين: المعيار الموضوعي ويشمل الدخل والممتلكات والتعليم والقوة والنفوذ التي يمتلكها الفرد، والمعيار الذاتي وهو المشاعر التي يحملها الشخص نحو طبقة معيّنة أو موقع معيّن.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15810, 2405, 2, 'التدرج الاجتماعي هو العملية التي عن طريقها يُرتَّب الأفراد والجماعات ضمن سلسلة متدرجة من المراكز، ويُسمّى أيضاً التفريق الاجتماعي أو الترتيب الاجتماعي. يُقاس وفق معيارين: المعيار الموضوعي ويشمل الدخل والممتلكات والتعليم والقوة والنفوذ التي يمتلكها الفرد، والمعيار الذاتي وهو المشاعر التي يحملها الشخص نحو طبقة معيّنة أو موقع معيّن.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15811, 2406, 1, 'من حيث الطبيعة: يرى الوظيفيون أنّ التفاوت والتدرج الاجتماعي حقيقة إنسانية طبيعية وأنّ وجود مجتمع لا طبقي مستحيل، بينما يعتبر ماركس التفاوت ظاهرة غير طبيعية استثنائية ولا إنسانية، أي ظاهرة اجتماعية. من حيث السبب: يردّه الوظيفيون إلى الاختلافات الفردية والطبيعية، لأنّ الناس غير متساوين بطبيعتهم في إمكاناتهم واستعداداتهم، بينما يردّه ماركس إلى امتلاك وسائل الإنتاج الذي أدّى إلى ظهور المجتمع الطبقي. (ملاحظة: ماركس لا يتحدث عن تدرج اجتماعي بل عن تركيب طبقي للمجتمع.)', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15812, 2406, 2, 'من حيث الطبيعة: يرى الوظيفيون أنّ التفاوت والتدرج الاجتماعي حقيقة إنسانية طبيعية وأنّ وجود مجتمع لا طبقي مستحيل، بينما يعتبر ماركس التفاوت ظاهرة غير طبيعية استثنائية ولا إنسانية، أي ظاهرة اجتماعية. من حيث السبب: يردّه الوظيفيون إلى الاختلافات الفردية والطبيعية، لأنّ الناس غير متساوين بطبيعتهم في إمكاناتهم واستعداداتهم، بينما يردّه ماركس إلى امتلاك وسائل الإنتاج الذي أدّى إلى ظهور المجتمع الطبقي. (ملاحظة: ماركس لا يتحدث عن تدرج اجتماعي بل عن تركيب طبقي للمجتمع.)', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15813, 2407, 1, 'سمات النظام الطبقي الحديث: تفاوت اجتماعي، ونظام مفتوح نسبياً أي إمكانية الحراك، وأساس الثروة فيه ملكية وسائل الإنتاج. هو مفتوح نسبياً لأنّ الحراك الاجتماعي فيه ممكن، إذ يقيّم الفرد على أساس كفاءته ومهارته لا على أساس مولده، بخلاف النظام العبودي والطائفة المغلقة حيث لا حراك. و«نسبياً» تعني أنّ الانتقال ممكن لا أنّ التفاوت قد زال. وإمكانية الحراك هذه هي التي تجعل الاندماج الاجتماعي يتحقق.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15814, 2407, 2, 'سمات النظام الطبقي الحديث: تفاوت اجتماعي، ونظام مفتوح نسبياً أي إمكانية الحراك، وأساس الثروة فيه ملكية وسائل الإنتاج. هو مفتوح نسبياً لأنّ الحراك الاجتماعي فيه ممكن، إذ يقيّم الفرد على أساس كفاءته ومهارته لا على أساس مولده، بخلاف النظام العبودي والطائفة المغلقة حيث لا حراك. و«نسبياً» تعني أنّ الانتقال ممكن لا أنّ التفاوت قد زال. وإمكانية الحراك هذه هي التي تجعل الاندماج الاجتماعي يتحقق.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15815, 2408, 1, 'الثقافة هي ذلك الكلّ المركّب المعقّد الذي يشتمل على مجموعة العادات والتقاليد واللغة والأخلاقيات والأزياء والأفكار والمعتقدات والفنون وغيرها من الأمور التي يكتسبها الإنسان من المجتمع. أجزاؤها: 1) جزء مرتبط بثقافة الوطن بشكل عامّ وهو الشخصية القاعدية؛ 2) جزء مرتبط ببيئة الطبقة التي يعيش فيها الإنسان أي البيئة الاجتماعية أو الحيّز الثقافي مثل المنزل أو الحيّ؛ 3) جزء نفسي يتمثّل بشخصية الفرد المستقلّة؛ 4) جزء واسع المدار يتعلّق بما يتلقّاه الإنسان من الثقافات الأخرى من خلال وسائل الإعلام والإنترنت والتلفزيون.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15816, 2408, 2, 'الثقافة هي ذلك الكلّ المركّب المعقّد الذي يشتمل على مجموعة العادات والتقاليد واللغة والأخلاقيات والأزياء والأفكار والمعتقدات والفنون وغيرها من الأمور التي يكتسبها الإنسان من المجتمع. أجزاؤها: 1) جزء مرتبط بثقافة الوطن بشكل عامّ وهو الشخصية القاعدية؛ 2) جزء مرتبط ببيئة الطبقة التي يعيش فيها الإنسان أي البيئة الاجتماعية أو الحيّز الثقافي مثل المنزل أو الحيّ؛ 3) جزء نفسي يتمثّل بشخصية الفرد المستقلّة؛ 4) جزء واسع المدار يتعلّق بما يتلقّاه الإنسان من الثقافات الأخرى من خلال وسائل الإعلام والإنترنت والتلفزيون.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15817, 2409, 1, 'المثاقفة وتسمّى أيضاً التفاعل الثقافي أو التثاقف، هي الانفتاح على الثقافات الأخرى. وهذا الانفتاح يؤدّي إلى اختلاف مواقع الأفراد في المجتمع، لأنّه يوسّع دائرة التلقّي للمعلومات لدى بعض الأفراد ويسمح لهم بالتواصل مع المجتمعات المغايرة، ممّا ينعكس على واقعهم المعاش فيؤهّلهم أكثر من غيرهم.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15818, 2409, 2, 'المثاقفة وتسمّى أيضاً التفاعل الثقافي أو التثاقف، هي الانفتاح على الثقافات الأخرى. وهذا الانفتاح يؤدّي إلى اختلاف مواقع الأفراد في المجتمع، لأنّه يوسّع دائرة التلقّي للمعلومات لدى بعض الأفراد ويسمح لهم بالتواصل مع المجتمعات المغايرة، ممّا ينعكس على واقعهم المعاش فيؤهّلهم أكثر من غيرهم.', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15819, 2410, 1, '1) المرحلة النظرية (ما قبل الميدان أو المرحلة الأولية): تحديد موضوع البحث أو مشكلته، تعيين الإطار العام للموضوع، تحديد حقل البحث (المكان والزمان)، بناء النماذج النظرية، صياغة الفرضيات. 2) المرحلة الميدانية: وضع الاستمارة الملائمة للبحث، تقديم وصف مفصّل لأدوات البحث، عرض الروابط بين الفرضيات، التحقّق من المعطيات، استخلاص النتائج. 3) المرحلة التحليلية النهائية: تجميع النتائج وجدولتها إحصائياً، تصنيف المعلومات، تحليل المعلومات وتفسيرها، تعميم النتائج وكتابة تقرير عن نتائج البحث. (تُقبل أيّ خطوتين صحيحتين من كلّ مرحلة.)', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15820, 2410, 2, '1) المرحلة النظرية (ما قبل الميدان أو المرحلة الأولية): تحديد موضوع البحث أو مشكلته، تعيين الإطار العام للموضوع، تحديد حقل البحث (المكان والزمان)، بناء النماذج النظرية، صياغة الفرضيات. 2) المرحلة الميدانية: وضع الاستمارة الملائمة للبحث، تقديم وصف مفصّل لأدوات البحث، عرض الروابط بين الفرضيات، التحقّق من المعطيات، استخلاص النتائج. 3) المرحلة التحليلية النهائية: تجميع النتائج وجدولتها إحصائياً، تصنيف المعلومات، تحليل المعلومات وتفسيرها، تعميم النتائج وكتابة تقرير عن نتائج البحث. (تُقبل أيّ خطوتين صحيحتين من كلّ مرحلة.)', 1, '2026-09-30 22:12:21', '2026-09-30 22:12:21'),
(15821, 2412, 1, 'السمة الثقافية هي الطابع العامّ المميّز للثقافة، أمّا المركّب الثقافي فهو مجموع سمات مترابطة تؤدّي إلى قيام نمط سلوكي يتضمّن التعبير عن العادات الشعبية والأعراف والنظم، وكلّ منهما قد يكون مكوّناً وظيفياً أو مادّياً. ويتحوّل اللقاء إلى سيطرة حين تريد الثقافة الأقوى إلغاء الثقافة الأضعف أو وضعها في حالة التبعية، كأن يقول شخص لآخر: يجب عليك تقبّل تقاليدي وعاداتي وإلّا ارجع حيث أنت؛ أمّا تبادل المعارف والعادات فيدلّ على المثاقفة.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15822, 2412, 2, 'السمة الثقافية هي الطابع العامّ المميّز للثقافة، أمّا المركّب الثقافي فهو مجموع سمات مترابطة تؤدّي إلى قيام نمط سلوكي يتضمّن التعبير عن العادات الشعبية والأعراف والنظم، وكلّ منهما قد يكون مكوّناً وظيفياً أو مادّياً. ويتحوّل اللقاء إلى سيطرة حين تريد الثقافة الأقوى إلغاء الثقافة الأضعف أو وضعها في حالة التبعية، كأن يقول شخص لآخر: يجب عليك تقبّل تقاليدي وعاداتي وإلّا ارجع حيث أنت؛ أمّا تبادل المعارف والعادات فيدلّ على المثاقفة.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15823, 2411, 1, 'الملاحظة المقنّنة: لا يتدخّل فيها الباحث بحياة المستجوبين بل يراقبهم عن كثب، ويكون حكماً من خارج الجماعة المدروسة، وتساعد على تكوين رأي عن الأنشطة المعتادة العامّة. الملاحظة بالمشاركة: يشارك فيها الباحث الجماعة ويعيش معهم بأدقّ تفاصيل حياتهم (مأكلهم وملابسهم وعاداتهم وتقاليدهم ومعتقداتهم) بهدف التعرّف بشكل دقيق وفعلي على ثقافة الجماعة. الملاحظة بالمشاركة أدقّ، فمشاركة الباحث عمّال المصنع إضرابهم وهو معهم يشاركهم الشعارات والنداءات أدقّ من المراقبة من شرفة المنزل.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15824, 2411, 2, 'الملاحظة المقنّنة: لا يتدخّل فيها الباحث بحياة المستجوبين بل يراقبهم عن كثب، ويكون حكماً من خارج الجماعة المدروسة، وتساعد على تكوين رأي عن الأنشطة المعتادة العامّة. الملاحظة بالمشاركة: يشارك فيها الباحث الجماعة ويعيش معهم بأدقّ تفاصيل حياتهم (مأكلهم وملابسهم وعاداتهم وتقاليدهم ومعتقداتهم) بهدف التعرّف بشكل دقيق وفعلي على ثقافة الجماعة. الملاحظة بالمشاركة أدقّ، فمشاركة الباحث عمّال المصنع إضرابهم وهو معهم يشاركهم الشعارات والنداءات أدقّ من المراقبة من شرفة المنزل.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15825, 2413, 1, 'من الأفضل أن تقدّم الدولة خدمات بحسب حاجات المناطق، لأنّ هناك مناطق يزداد حرمانها، فيجب وضع أولوية للمناطق الأكثر حرماناً لأنّها تتميّز بازدياد نسبة الفقر والجوع، وعلى الدولة أن تضع استراتيجيات لمساعدة هذه المناطق.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15826, 2413, 2, 'من الأفضل أن تقدّم الدولة خدمات بحسب حاجات المناطق، لأنّ هناك مناطق يزداد حرمانها، فيجب وضع أولوية للمناطق الأكثر حرماناً لأنّها تتميّز بازدياد نسبة الفقر والجوع، وعلى الدولة أن تضع استراتيجيات لمساعدة هذه المناطق.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15827, 2414, 1, 'مثال: كيف تصل إلى المدرسة صباحاً؟ لماذا تتأخّر عن الحصّة الأولى؟ (يُقبل كلّ سؤال سليم يبدأ بالأداة المطلوبة ويتعلّق بالموضوع.) يُمنع استعمال «هل» لأنّها لا تفتح إلّا جواباً بنعم أو لا، فتضيع المعلومة التي يريدها الباحث؛ والأدوات المسموح بها هي: كيف، ما، لماذا، أين، متى، ما هي.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15828, 2414, 2, 'مثال: كيف تصل إلى المدرسة صباحاً؟ لماذا تتأخّر عن الحصّة الأولى؟ (يُقبل كلّ سؤال سليم يبدأ بالأداة المطلوبة ويتعلّق بالموضوع.) يُمنع استعمال «هل» لأنّها لا تفتح إلّا جواباً بنعم أو لا، فتضيع المعلومة التي يريدها الباحث؛ والأدوات المسموح بها هي: كيف، ما، لماذا، أين، متى، ما هي.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15829, 2415, 1, 'العمل: إنسان الريف يعتمد على الزراعة، بينما أهل المدينة يعملون في الصناعة والتجارة والمصارف والإدارة. البيئة: الإنسان في الريف يعيش في بيئة طبيعية ويخضع لتقلّباتها المختلفة، بينما الإنسان في المدينة يعيش في بيئة صنعها بنفسه ولا يتأثّر بالطبيعة. الانتماء: إنسان الريف انتماؤه شديد إلى العائلة التي توفّر له مقوّمات حياته، بينما الإنسان في المدينة ينتمي إلى أكثر من وحدة اجتماعية ولا يشعر بانتماء شديد لأيّ منها.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15830, 2415, 2, 'العمل: إنسان الريف يعتمد على الزراعة، بينما أهل المدينة يعملون في الصناعة والتجارة والمصارف والإدارة. البيئة: الإنسان في الريف يعيش في بيئة طبيعية ويخضع لتقلّباتها المختلفة، بينما الإنسان في المدينة يعيش في بيئة صنعها بنفسه ولا يتأثّر بالطبيعة. الانتماء: إنسان الريف انتماؤه شديد إلى العائلة التي توفّر له مقوّمات حياته، بينما الإنسان في المدينة ينتمي إلى أكثر من وحدة اجتماعية ولا يشعر بانتماء شديد لأيّ منها.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15831, 2416, 1, 'المراكز المفروضة هي التي يحصل عليها الفرد من خلال ظروف ليست له سيطرة عليها، مثل ابن مدير أو زوجة قاضٍ. وهي أهمّ من المراكز المكتسبة لأنّ كلّ شخص يولد في طبقة وليس هناك من شيء يغيّر هذا الوضع. ويجب أن يكون تقييم الناس على أساس الكفاءة والمهارة والعلم، لا على أساس الانتماء العائلي والطائفي كما يحصل في الدول النامية.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15832, 2416, 2, 'المراكز المفروضة هي التي يحصل عليها الفرد من خلال ظروف ليست له سيطرة عليها، مثل ابن مدير أو زوجة قاضٍ. وهي أهمّ من المراكز المكتسبة لأنّ كلّ شخص يولد في طبقة وليس هناك من شيء يغيّر هذا الوضع. ويجب أن يكون تقييم الناس على أساس الكفاءة والمهارة والعلم، لا على أساس الانتماء العائلي والطائفي كما يحصل في الدول النامية.', 1, '2026-09-30 22:12:22', '2026-09-30 22:12:22'),
(15833, 2417, 1, 'العلم دراسة موضوعية لا تتأثّر بذاتية الباحث ولا تتغيّر نتائجها بتغيّر الباحثين، وهذه العلمية تامّة في الرياضيات والفيزياء والكيمياء. أمّا في علم الاجتماع فهي نسبية ومتفاوتة لسببين: لأنّ ذاتية الباحث وثقافته ومزاجه تؤثّر في تناوله للموضوع، ولأنّ الظواهر الإنسانية أكثر تشابكاً كونها متحرّكة ومتغيّرة.', 1, '2026-09-30 22:12:23', '2026-09-30 22:12:23'),
(15834, 2417, 2, 'العلم دراسة موضوعية لا تتأثّر بذاتية الباحث ولا تتغيّر نتائجها بتغيّر الباحثين، وهذه العلمية تامّة في الرياضيات والفيزياء والكيمياء. أمّا في علم الاجتماع فهي نسبية ومتفاوتة لسببين: لأنّ ذاتية الباحث وثقافته ومزاجه تؤثّر في تناوله للموضوع، ولأنّ الظواهر الإنسانية أكثر تشابكاً كونها متحرّكة ومتغيّرة.', 1, '2026-09-30 22:12:23', '2026-09-30 22:12:23'),
(15835, 2418, 1, '1) الاتجاه الأخلاقي: الفقراء مسؤولون عن فقرهم بسبب الكسل وقلّة المبادرة. 2) اتجاه يركّز على النظام الاجتماعي ويراه مسؤولاً عن التفاوت بين أوضاع الأفراد والجماعات. 3) الاتجاه الاقتصادي: طبيعة النظام الاقتصادي هي التي تؤدّي إلى الفقر.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15836, 2418, 2, '1) الاتجاه الأخلاقي: الفقراء مسؤولون عن فقرهم بسبب الكسل وقلّة المبادرة. 2) اتجاه يركّز على النظام الاجتماعي ويراه مسؤولاً عن التفاوت بين أوضاع الأفراد والجماعات. 3) الاتجاه الاقتصادي: طبيعة النظام الاقتصادي هي التي تؤدّي إلى الفقر.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15837, 2419, 1, 'ابن خلدون مؤسّس علم الاجتماع: رأى في العصبية رابطاً اجتماعياً ودرس من خلالها أطوار السلطة ونشأتها، وعالج الانتقال من البداوة إلى الحضارة وتكوّن الدول ونموّها وانهيارها. أوغست كونت أوّل من أعطى علم الاجتماع طابع العلم الوضعي وسمّاه الفيزياء الاجتماعية، وقسّمه إلى فرع يشرح مكوّنات المجتمع وفرع يشرح وظائفها.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15838, 2419, 2, 'ابن خلدون مؤسّس علم الاجتماع: رأى في العصبية رابطاً اجتماعياً ودرس من خلالها أطوار السلطة ونشأتها، وعالج الانتقال من البداوة إلى الحضارة وتكوّن الدول ونموّها وانهيارها. أوغست كونت أوّل من أعطى علم الاجتماع طابع العلم الوضعي وسمّاه الفيزياء الاجتماعية، وقسّمه إلى فرع يشرح مكوّنات المجتمع وفرع يشرح وظائفها.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15839, 2420, 1, 'قبل ظهور علم الاجتماع كان الناس يرون واقعهم مرتبطاً بقوى خارجة عن إرادتهم تتحكّم به ويستسلمون لها. أمّا بعد تقدّمه فقد كشف العوامل المؤثّرة في هذا الواقع، فأدرك الإنسان دوره في التأثير فيها وأصبح تعديل الواقع أو تغييره ممكناً، وصارت المجتمعات المعاصرة تستند إلى معطيات علم الاجتماع أكثر من المعتقدات الموروثة والعادات التقليدية.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15840, 2420, 2, 'قبل ظهور علم الاجتماع كان الناس يرون واقعهم مرتبطاً بقوى خارجة عن إرادتهم تتحكّم به ويستسلمون لها. أمّا بعد تقدّمه فقد كشف العوامل المؤثّرة في هذا الواقع، فأدرك الإنسان دوره في التأثير فيها وأصبح تعديل الواقع أو تغييره ممكناً، وصارت المجتمعات المعاصرة تستند إلى معطيات علم الاجتماع أكثر من المعتقدات الموروثة والعادات التقليدية.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15841, 2421, 1, 'الظاهرة الفيزيائية متشابهة ومتكرّرة في كلّ الحالات ومتجانسة ولو تغيّر الباحث، وتُدرس بالقياس المخبري، ومثالها تمدّد المعادن بفعل ارتفاع الحرارة. أمّا الظاهرة الاجتماعية فعناصرها مركّبة ومرتبطة بالزمان والمكان، ولا تُكشف بالقياس المخبري بل بالدراسة الاجتماعية الميدانية، ومثالها أدوار أفراد الأسرة. فالطريقة تتلاءم مع طبيعة الظاهرة.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15842, 2421, 2, 'الظاهرة الفيزيائية متشابهة ومتكرّرة في كلّ الحالات ومتجانسة ولو تغيّر الباحث، وتُدرس بالقياس المخبري، ومثالها تمدّد المعادن بفعل ارتفاع الحرارة. أمّا الظاهرة الاجتماعية فعناصرها مركّبة ومرتبطة بالزمان والمكان، ولا تُكشف بالقياس المخبري بل بالدراسة الاجتماعية الميدانية، ومثالها أدوار أفراد الأسرة. فالطريقة تتلاءم مع طبيعة الظاهرة.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15843, 2422, 1, '1) التنظيم الاجتماعي. 2) رسم السياسات الاقتصادية والاجتماعية. 3) مشاريع التنمية. 4) سلامة البيئة. 5) التربية. 6) التنظيم المدني.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15844, 2422, 2, '1) التنظيم الاجتماعي. 2) رسم السياسات الاقتصادية والاجتماعية. 3) مشاريع التنمية. 4) سلامة البيئة. 5) التربية. 6) التنظيم المدني.', 1, '2026-09-30 22:12:24', '2026-09-30 22:12:24'),
(15845, 2423, 1, 'الوصف العياني هو وصف الوقائع والسلوكيات كما نشاهدها بالعين، فنلاحظها في الحياة اليومية وعند اتّخاذ القرارات ثمّ نصفها. لكنّ الملاحظة الوصفية لا تكفي لدراسة الظاهرة بشكل عميق، لذلك نلجأ إلى التوثيق فنجمع المعلومات من الكتب والمجلّات والنشرات ومن دراسات مشابهة.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15846, 2423, 2, 'الوصف العياني هو وصف الوقائع والسلوكيات كما نشاهدها بالعين، فنلاحظها في الحياة اليومية وعند اتّخاذ القرارات ثمّ نصفها. لكنّ الملاحظة الوصفية لا تكفي لدراسة الظاهرة بشكل عميق، لذلك نلجأ إلى التوثيق فنجمع المعلومات من الكتب والمجلّات والنشرات ومن دراسات مشابهة.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15847, 2424, 1, 'تتّصل حوادث السير بسلوك الناس وتنظيم المجتمع، فيمكن لعلم الاجتماع أن يُسهم في فهمها لأنّه يكشف العوامل المؤثّرة في الواقع. وترتبط بمجال التنظيم المدني (مشكلات مدينية كازدحام السير). وتُدرس بجمع المعلومات وإجراء المقابلات والدراسة الميدانية للتعرّف إلى واقع السكّان وحاجاتهم وآرائهم.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15848, 2424, 2, 'تتّصل حوادث السير بسلوك الناس وتنظيم المجتمع، فيمكن لعلم الاجتماع أن يُسهم في فهمها لأنّه يكشف العوامل المؤثّرة في الواقع. وترتبط بمجال التنظيم المدني (مشكلات مدينية كازدحام السير). وتُدرس بجمع المعلومات وإجراء المقابلات والدراسة الميدانية للتعرّف إلى واقع السكّان وحاجاتهم وآرائهم.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15849, 2425, 1, 'تتشابه المجتمعات في عناصر تركيبها وتختلف في ترتيبها وأشكالها ودلالاتها. من العناصر المشتركة: السكن في بيوت ومبانٍ، وارتداء الملابس، وتبادل العلاقات، وممارسة الأعمال (والتنقّل). ومن أوجه الاختلاف: أشكال المباني، وأنواع الملابس، وأنماط السلوك، وطبيعة المؤسسات. ويتباين ذلك وفقاً لدرجة تقدّم الفئات الاجتماعية أو تخلّفها.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15850, 2425, 2, 'تتشابه المجتمعات في عناصر تركيبها وتختلف في ترتيبها وأشكالها ودلالاتها. من العناصر المشتركة: السكن في بيوت ومبانٍ، وارتداء الملابس، وتبادل العلاقات، وممارسة الأعمال (والتنقّل). ومن أوجه الاختلاف: أشكال المباني، وأنواع الملابس، وأنماط السلوك، وطبيعة المؤسسات. ويتباين ذلك وفقاً لدرجة تقدّم الفئات الاجتماعية أو تخلّفها.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15851, 2426, 1, '1) تحديد موضوع البحث: تعريف المفهوم وتحديد عناصره، كتعريف الفقر وتحديد تكاليف المعيشة من غذاء وملبس ومسكن. 2) الموضوعية: ملاحظة الظاهرة ملاحظة موضوعية وتجاوز الأفكار الشائعة بشكل منهجي واعٍ. 3) الانطلاق من ملاحظة الظاهرة الاجتماعية الواقعية، مباشرةً بالوصف والإحصاء والمشاركة، أو غير مباشرة بالتوثيق والمراجع التاريخية.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15852, 2426, 2, '1) تحديد موضوع البحث: تعريف المفهوم وتحديد عناصره، كتعريف الفقر وتحديد تكاليف المعيشة من غذاء وملبس ومسكن. 2) الموضوعية: ملاحظة الظاهرة ملاحظة موضوعية وتجاوز الأفكار الشائعة بشكل منهجي واعٍ. 3) الانطلاق من ملاحظة الظاهرة الاجتماعية الواقعية، مباشرةً بالوصف والإحصاء والمشاركة، أو غير مباشرة بالتوثيق والمراجع التاريخية.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15853, 2427, 1, 'في المنزل يغلب الطابع الخاص لأنّ الصلة تقوم على روابط الأسرة والعائلة. وخارج المنزل يغلب الطابع العام لأنّنا ندخل المجال العام. وسبب الاختلاف أنّ الروابط العامة تجمع أفراد المجتمع بقطع النظر عن انتماءاتهم وأسرهم وعقائدهم، في إطار مهني أو سياسي أو اقتصادي أو تربوي، ويلتزم الناس فيه بقواعد سلوكية وضوابط نظامية يُجمعون عليها.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15854, 2427, 2, 'في المنزل يغلب الطابع الخاص لأنّ الصلة تقوم على روابط الأسرة والعائلة. وخارج المنزل يغلب الطابع العام لأنّنا ندخل المجال العام. وسبب الاختلاف أنّ الروابط العامة تجمع أفراد المجتمع بقطع النظر عن انتماءاتهم وأسرهم وعقائدهم، في إطار مهني أو سياسي أو اقتصادي أو تربوي، ويلتزم الناس فيه بقواعد سلوكية وضوابط نظامية يُجمعون عليها.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15855, 2428, 1, 'البنية الاجتماعية ليست ساكنة بل ذات حركية تنشأ من: تشابك المصالح بين الأفراد والجماعات، وتبادل المنافع، والصراع الناتج عن التفاوت في المستويات الاقتصادية، وتباين الآراء والتوجّهات السياسية. وتنظّمها ضوابط هي التشريعات والقوانين (كقوانين العمل ونظام الامتحانات وقانون السير وقانون العقوبات) تطبّقها مؤسسات رسمية كقوى الأمن والقضاء والوزارات، بهدف الحفاظ على الاستقرار والنظام في المجتمع.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15856, 2428, 2, 'البنية الاجتماعية ليست ساكنة بل ذات حركية تنشأ من: تشابك المصالح بين الأفراد والجماعات، وتبادل المنافع، والصراع الناتج عن التفاوت في المستويات الاقتصادية، وتباين الآراء والتوجّهات السياسية. وتنظّمها ضوابط هي التشريعات والقوانين (كقوانين العمل ونظام الامتحانات وقانون السير وقانون العقوبات) تطبّقها مؤسسات رسمية كقوى الأمن والقضاء والوزارات، بهدف الحفاظ على الاستقرار والنظام في المجتمع.', 1, '2026-09-30 22:12:25', '2026-09-30 22:12:25'),
(15857, 2429, 1, 'العائلة خليّة إنسانية أولى لأنّ الحياة تنشأ عبرها وتُبنى فيها الصلات الإنسانية الجامعة، وصلة القربى تمنح الفرد الشعور بالحماية والأمان. وهي نواة مؤسّسة اجتماعية لأنّها تخضع لقواعد تحكم تكوينها كقواعد الزواج والإنجاب، ولتنظيم الأدوار بين الأب والأمّ والأولاد. من عوامل الحالة السكانية (اثنان): نسب الفئات العمرية من الجنسين، نسب الولادات والوفيات والهجرة، تطوّر الوسائل الطبية والعناية الصحية، القيم الاجتماعية والدينية.', 1, '2026-09-30 22:12:26', '2026-09-30 22:12:26'),
(15858, 2429, 2, 'العائلة خليّة إنسانية أولى لأنّ الحياة تنشأ عبرها وتُبنى فيها الصلات الإنسانية الجامعة، وصلة القربى تمنح الفرد الشعور بالحماية والأمان. وهي نواة مؤسّسة اجتماعية لأنّها تخضع لقواعد تحكم تكوينها كقواعد الزواج والإنجاب، ولتنظيم الأدوار بين الأب والأمّ والأولاد. من عوامل الحالة السكانية (اثنان): نسب الفئات العمرية من الجنسين، نسب الولادات والوفيات والهجرة، تطوّر الوسائل الطبية والعناية الصحية، القيم الاجتماعية والدينية.', 1, '2026-09-30 22:12:26', '2026-09-30 22:12:26'),
(15859, 2430, 1, 'المجتمع بناء مؤلّف من عناصر متعدّدة ومتنوّعة ومترابطة تتفاعل فيما بينها بشكل ضمني وفق نظام حركي يعطيها وحدتها. أبعاد التكوين المدني: البعد السياسي (أطر المشاركة في أخذ القرارات العامّة وتنفيذها ومراقبتها)، البعد الاجتماعي المدني (تنظيمات تحدّد قواعد السلوك للعيش المشترك في وطن واحد)، البعد الاقتصادي (الانتقال من الاكتفاء على مستوى الفرد والعائلة إلى المشاركة في تأمين موارد العيش للجميع).', 1, '2026-09-30 22:12:26', '2026-09-30 22:12:26'),
(15860, 2430, 2, 'المجتمع بناء مؤلّف من عناصر متعدّدة ومتنوّعة ومترابطة تتفاعل فيما بينها بشكل ضمني وفق نظام حركي يعطيها وحدتها. أبعاد التكوين المدني: البعد السياسي (أطر المشاركة في أخذ القرارات العامّة وتنفيذها ومراقبتها)، البعد الاجتماعي المدني (تنظيمات تحدّد قواعد السلوك للعيش المشترك في وطن واحد)، البعد الاقتصادي (الانتقال من الاكتفاء على مستوى الفرد والعائلة إلى المشاركة في تأمين موارد العيش للجميع).', 1, '2026-09-30 22:12:26', '2026-09-30 22:12:26'),
(15861, 2431, 1, 'الثقافة مجموعة المعتقدات والقيم والعادات والخبرات التي يكتسبها الناس أفراداً وجماعات، وهي ما يضيفه الإنسان على الطبيعة ويتناقله من جيل إلى آخر، وتنعكس في الفنون والآداب والنشاطات الإبداعية. تنتقل باللغة والتربية والتقليد والآثار الفنية والفكرية (يكفي ذكر وسيلتين).', 1, '2026-09-30 22:12:26', '2026-09-30 22:12:26'),
(15862, 2431, 2, 'الثقافة مجموعة المعتقدات والقيم والعادات والخبرات التي يكتسبها الناس أفراداً وجماعات، وهي ما يضيفه الإنسان على الطبيعة ويتناقله من جيل إلى آخر، وتنعكس في الفنون والآداب والنشاطات الإبداعية. تنتقل باللغة والتربية والتقليد والآثار الفنية والفكرية (يكفي ذكر وسيلتين).', 1, '2026-09-30 22:12:26', '2026-09-30 22:12:26'),
(15863, 2432, 1, 'لكلّ مرحلة عمرية أدوار اجتماعية مختلفة، وحين تضيق فسحة الحوار بين الأجيال ينشأ صراع الأجيال. سببه أنّ الشباب ينزعون إلى التجديد تلبيةً لحاجات جديدة، كالاعتماد على النفس والاستقلال عن سلطة الأهل والتقاليد. والحلّ فرص أكبر للحوار وتوسيع قاعدته.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15864, 2432, 2, 'لكلّ مرحلة عمرية أدوار اجتماعية مختلفة، وحين تضيق فسحة الحوار بين الأجيال ينشأ صراع الأجيال. سببه أنّ الشباب ينزعون إلى التجديد تلبيةً لحاجات جديدة، كالاعتماد على النفس والاستقلال عن سلطة الأهل والتقاليد. والحلّ فرص أكبر للحوار وتوسيع قاعدته.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15865, 2433, 1, 'ينزح العمّال بفعل التفاوت في المداخيل والإنتاجية بين القطاعات، مثل النزوح من الزراعة إلى الصناعة ثمّ إلى التجارة والخدمات. وتحدّ الدول من هذا التفاوت بتحديث القطاعات المتراجعة كالزراعة والصناعة، وتمويلها بقروض ميسّرة، وتأهيل العاملين، وتأمين الضمانات الاجتماعية لهم (تُقبل أيّ وسيلتين).', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15866, 2433, 2, 'ينزح العمّال بفعل التفاوت في المداخيل والإنتاجية بين القطاعات، مثل النزوح من الزراعة إلى الصناعة ثمّ إلى التجارة والخدمات. وتحدّ الدول من هذا التفاوت بتحديث القطاعات المتراجعة كالزراعة والصناعة، وتمويلها بقروض ميسّرة، وتأهيل العاملين، وتأمين الضمانات الاجتماعية لهم (تُقبل أيّ وسيلتين).', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15867, 2434, 1, 'ثقافة المجتمع تطبع أفراده بسمات مشتركة كاللغة وبعض أنماط السلوك، لكنّ كلّ فئة اجتماعية تتميّز بخصائص في سلوكها وأنماط عيشها. مثال أوّل: أنماط عيش الفئات الميسورة تختلف عن الفئات الأقلّ دخلاً. مثال ثانٍ: المثقّفون أقلّ تمسّكاً بالعادات والتقاليد ويسعون إلى تغيير بعض مضامين الثقافة السائدة.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15868, 2434, 2, 'ثقافة المجتمع تطبع أفراده بسمات مشتركة كاللغة وبعض أنماط السلوك، لكنّ كلّ فئة اجتماعية تتميّز بخصائص في سلوكها وأنماط عيشها. مثال أوّل: أنماط عيش الفئات الميسورة تختلف عن الفئات الأقلّ دخلاً. مثال ثانٍ: المثقّفون أقلّ تمسّكاً بالعادات والتقاليد ويسعون إلى تغيير بعض مضامين الثقافة السائدة.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15869, 2435, 1, 'مصدر الشرعية في المسار التقليدي معتقدات وعادات موروثة، وفي المسار القانوني القوانين والأنظمة التي يضعها المجتمع. وانتقال السلطة في التقليدي يتمّ بالوراثة، وفي القانوني تحدّده القوانين. وموقف الناس في التقليدي هو الخضوع، أمّا في القانوني فالقيادة مسؤولية حكم وإدارة للشؤون العامّة.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15870, 2435, 2, 'مصدر الشرعية في المسار التقليدي معتقدات وعادات موروثة، وفي المسار القانوني القوانين والأنظمة التي يضعها المجتمع. وانتقال السلطة في التقليدي يتمّ بالوراثة، وفي القانوني تحدّده القوانين. وموقف الناس في التقليدي هو الخضوع، أمّا في القانوني فالقيادة مسؤولية حكم وإدارة للشؤون العامّة.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15871, 2436, 1, '1- خصائص قيادية تؤمّن النجاح في المجال القيادي المعيّن. 2- كفاءات علمية تؤهّله لممارسة الحكم وإدارة الشؤون العامّة في إطار القوانين. 3- مزايا خلقية وقيم إنسانية ترفع من مستوى السلطة وتميّز القائمين عليها.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15872, 2436, 2, '1- خصائص قيادية تؤمّن النجاح في المجال القيادي المعيّن. 2- كفاءات علمية تؤهّله لممارسة الحكم وإدارة الشؤون العامّة في إطار القوانين. 3- مزايا خلقية وقيم إنسانية ترفع من مستوى السلطة وتميّز القائمين عليها.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15873, 2437, 1, 'التطوّر انتقال من طور إلى طور ضمن الحالة نفسها، أمّا التحوّل فهو الانتقال من حال إلى حال، أي انقلاب شامل في الغايات والأهداف. مثال التطوّر: تطوّر موديلات السيّارات وفعالية محرّكاتها، فالسيّارة بقيت سيّارة لكنّها تحسّنت.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15874, 2437, 2, 'التطوّر انتقال من طور إلى طور ضمن الحالة نفسها، أمّا التحوّل فهو الانتقال من حال إلى حال، أي انقلاب شامل في الغايات والأهداف. مثال التطوّر: تطوّر موديلات السيّارات وفعالية محرّكاتها، فالسيّارة بقيت سيّارة لكنّها تحسّنت.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15875, 2438, 1, 'العامل الأساسي تزايد وعي الإنسان ومعرفته بطبائع الحيوانات، فاستأنس بعض أنواعها البرّية ودجّنها ونشأت حرفة الرعي. ومن النتائج: استخدام بعض الحيوانات في النقل والاستفادة من لبن أنواع أخرى وجلدها ولحمها، وغذاء مستقرّ نسبياً، وزيادة سكانية ملحوظة، وسيطرة أكبر على بعض مظاهر الطبيعة (تُقبل أيّ نتيجتين).', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15876, 2438, 2, 'العامل الأساسي تزايد وعي الإنسان ومعرفته بطبائع الحيوانات، فاستأنس بعض أنواعها البرّية ودجّنها ونشأت حرفة الرعي. ومن النتائج: استخدام بعض الحيوانات في النقل والاستفادة من لبن أنواع أخرى وجلدها ولحمها، وغذاء مستقرّ نسبياً، وزيادة سكانية ملحوظة، وسيطرة أكبر على بعض مظاهر الطبيعة (تُقبل أيّ نتيجتين).', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15877, 2439, 1, 'تشهد غالبية المجتمعات المعاصرة تحرّكات لتأمين شروط بروز القيادة الديمقراطية في ثلاثة اتّجاهات: 1- تطوير الشخصية القيادية وأساليب القيادة والحكم. 2- تطوير المشاركة الشعبية في اتّخاذ القرارات العامّة وفي تنفيذها. 3- تطوير المراقبة والمساءلة، وسبل معالجة النزاعات والمعارضة.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15878, 2439, 2, 'تشهد غالبية المجتمعات المعاصرة تحرّكات لتأمين شروط بروز القيادة الديمقراطية في ثلاثة اتّجاهات: 1- تطوير الشخصية القيادية وأساليب القيادة والحكم. 2- تطوير المشاركة الشعبية في اتّخاذ القرارات العامّة وفي تنفيذها. 3- تطوير المراقبة والمساءلة، وسبل معالجة النزاعات والمعارضة.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15879, 2440, 1, 'تختلف عوامل التأثير وتختلف طبيعة كلّ مجتمع. وتختلف الظروف، فلا تسلك البلدان خطّاً واحداً رغم خصائصها المشتركة. وقد يأتي التأثير من عامل خارجي مصدره مجتمعات أخرى. والتطوّر لا يحمل دائماً طابع التقدّم، فقد يكون تراجعاً أو مراوحة بطيئة، ومثال ذلك الهوّة بين البلدان الصناعية وغير الصناعية.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15880, 2440, 2, 'تختلف عوامل التأثير وتختلف طبيعة كلّ مجتمع. وتختلف الظروف، فلا تسلك البلدان خطّاً واحداً رغم خصائصها المشتركة. وقد يأتي التأثير من عامل خارجي مصدره مجتمعات أخرى. والتطوّر لا يحمل دائماً طابع التقدّم، فقد يكون تراجعاً أو مراوحة بطيئة، ومثال ذلك الهوّة بين البلدان الصناعية وغير الصناعية.', 1, '2026-09-30 22:12:27', '2026-09-30 22:12:27'),
(15881, 2441, 1, '1- كانت الزراعة القطاع السائد وشبه الوحيد في الإنتاج، ويعمل فيها معظم القادرين على العمل. 2- تدرّجت علاقات الإنتاج من المشاعيّة إلى العبوديّة فالإقطاعيّة، وكانت الأجور غالباً عينيّة (حصّة من الإنتاج). 3- كانت الزراعة قوتيّة للاكتفاء الذاتي، متنوّعة المحاصيل، بدائيّة الوسائل، محدودة الإنتاج. 4- تعاون أهل الضيعة أو أفراد العائلة الممتدّة في حفر أقنية المياه وشقّ الطرقات والإنتاج وتقاسم الخيرات (تُقبل أيّ ثلاث).', 1, '2026-09-30 22:12:28', '2026-09-30 22:12:28'),
(15882, 2441, 2, '1- كانت الزراعة القطاع السائد وشبه الوحيد في الإنتاج، ويعمل فيها معظم القادرين على العمل. 2- تدرّجت علاقات الإنتاج من المشاعيّة إلى العبوديّة فالإقطاعيّة، وكانت الأجور غالباً عينيّة (حصّة من الإنتاج). 3- كانت الزراعة قوتيّة للاكتفاء الذاتي، متنوّعة المحاصيل، بدائيّة الوسائل، محدودة الإنتاج. 4- تعاون أهل الضيعة أو أفراد العائلة الممتدّة في حفر أقنية المياه وشقّ الطرقات والإنتاج وتقاسم الخيرات (تُقبل أيّ ثلاث).', 1, '2026-09-30 22:12:28', '2026-09-30 22:12:28'),
(15883, 2442, 1, 'أرادت النقابات حماية أعضائها من المنافسة والخسارة، فحدّدت كمّيّات الإنتاج والحدّ الأدنى للأسعار وعدد العاملين، ومنعت أهل الأرياف من مزاولة الحرف، فبقيت أدوات الإنتاج تقليديّة بلا تغيير مهمّ وركدت الصناعة. أمّا الصناعات المنزليّة فانتشرت خارج المدن تجنّباً لقيود نظام النقابات.', 1, '2026-09-30 22:12:28', '2026-09-30 22:12:28'),
(15884, 2442, 2, 'أرادت النقابات حماية أعضائها من المنافسة والخسارة، فحدّدت كمّيّات الإنتاج والحدّ الأدنى للأسعار وعدد العاملين، ومنعت أهل الأرياف من مزاولة الحرف، فبقيت أدوات الإنتاج تقليديّة بلا تغيير مهمّ وركدت الصناعة. أمّا الصناعات المنزليّة فانتشرت خارج المدن تجنّباً لقيود نظام النقابات.', 1, '2026-09-30 22:12:28', '2026-09-30 22:12:28'),
(15885, 2443, 1, 'بعد اكتشاف أميركا والوصول إلى الهند عن طريق رأس الرجاء الصالح: 1- صار المحيط الأطلسي مركز التجارة الدوليّة بدل البحر المتوسّط. 2- تراجع دور البلدان العربيّة على السواحل الشرقيّة والجنوبيّة للمتوسّط، وانهارت حضارات المتوسّط الأوروبيّة مثل البندقيّة وجنوى. 3- انتقل مركز الثقل إلى هولندا وإنكلترا، فصارتا مهد الثورة الصناعيّة وجسر التمدّد الأوروبي إلى العالم الجديد.', 1, '2026-09-30 22:12:28', '2026-09-30 22:12:28'),
(15886, 2443, 2, 'بعد اكتشاف أميركا والوصول إلى الهند عن طريق رأس الرجاء الصالح: 1- صار المحيط الأطلسي مركز التجارة الدوليّة بدل البحر المتوسّط. 2- تراجع دور البلدان العربيّة على السواحل الشرقيّة والجنوبيّة للمتوسّط، وانهارت حضارات المتوسّط الأوروبيّة مثل البندقيّة وجنوى. 3- انتقل مركز الثقل إلى هولندا وإنكلترا، فصارتا مهد الثورة الصناعيّة وجسر التمدّد الأوروبي إلى العالم الجديد.', 1, '2026-09-30 22:12:28', '2026-09-30 22:12:28'),
(15887, 2444, 1, 'لم تُسمَّ ثورة لأنّها مفاجئة أو عنيفة، بل لأنّها غيّرت بنية الصناعة تغييراً شاملاً وحقّقت زيادة هائلة في الإنتاج، فطال التحوّل مستويات الحياة الاجتماعية والاقتصادية كافّة. والآلات تديرها قوى محرّكة من الهواء والماء والبخار، فانتقلت الصناعة من المنازل والورش الحرفية إلى مناطق قريبة من المجاري المائية أو مناجم الفحم، ثمّ مع الكهرباء تأسّست المصانع في مناطق متعدّدة.', 1, '2026-09-30 22:12:29', '2026-09-30 22:12:29'),
(15888, 2444, 2, 'لم تُسمَّ ثورة لأنّها مفاجئة أو عنيفة، بل لأنّها غيّرت بنية الصناعة تغييراً شاملاً وحقّقت زيادة هائلة في الإنتاج، فطال التحوّل مستويات الحياة الاجتماعية والاقتصادية كافّة. والآلات تديرها قوى محرّكة من الهواء والماء والبخار، فانتقلت الصناعة من المنازل والورش الحرفية إلى مناطق قريبة من المجاري المائية أو مناجم الفحم، ثمّ مع الكهرباء تأسّست المصانع في مناطق متعدّدة.', 1, '2026-09-30 22:12:29', '2026-09-30 22:12:29'),
(15889, 2445, 1, '1- تسارع نموّ السكان، فلزم زيادة الإنتاج. 2- توسّع التجارة بعد الفتوحات الجغرافية الكبرى. 3- توفّر رأس المال لتمويل الاختراعات. 4- إطلاق بعض الدول الأوروبية عدداً من الحريّات الأساسية، كحريّة التجارة وحريّة التصرّف في الممتلكات الفردية وحريّة التعاقد وحريّة البقاء في مكان معيّن أو مغادرته (تُقبل أيّ ثلاثة).', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(15890, 2446, 1, 'شهد النصف الثاني من القرن العشرين، وخاصّة ربعه الأخير، سلسلة تحوّلات علميّة كبيرة كان لثورة المعلومات والاتصالات دور الريادة فيها. أظهرت الاكتشافات العلميّة الدور المحوري للمعرفة، فنشطت الأبحاث لامتلاكها واستثمارها واختراع آلات تخزّنها وتحلّلها كما يفعل الدماغ البشري، وكان ظهور الكومبيوتر في منتصف القرن العشرين الخطوة الأولى. ونتج عن ذلك تغيّر جذري في أنماط السلوك على المستويات الفرديّة والوطنيّة والعالميّة، وصار اقتصاد البلدان أكثر تشابكاً وتخصّصاً وتركيباً.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15891, 2445, 2, '1- تسارع نموّ السكان، فلزم زيادة الإنتاج. 2- توسّع التجارة بعد الفتوحات الجغرافية الكبرى. 3- توفّر رأس المال لتمويل الاختراعات. 4- إطلاق بعض الدول الأوروبية عدداً من الحريّات الأساسية، كحريّة التجارة وحريّة التصرّف في الممتلكات الفردية وحريّة التعاقد وحريّة البقاء في مكان معيّن أو مغادرته (تُقبل أيّ ثلاثة).', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15892, 2446, 2, 'شهد النصف الثاني من القرن العشرين، وخاصّة ربعه الأخير، سلسلة تحوّلات علميّة كبيرة كان لثورة المعلومات والاتصالات دور الريادة فيها. أظهرت الاكتشافات العلميّة الدور المحوري للمعرفة، فنشطت الأبحاث لامتلاكها واستثمارها واختراع آلات تخزّنها وتحلّلها كما يفعل الدماغ البشري، وكان ظهور الكومبيوتر في منتصف القرن العشرين الخطوة الأولى. ونتج عن ذلك تغيّر جذري في أنماط السلوك على المستويات الفرديّة والوطنيّة والعالميّة، وصار اقتصاد البلدان أكثر تشابكاً وتخصّصاً وتركيباً.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15893, 2447, 1, 'تشترك مع السلع المادّيّة في أنّها تخضع لقانون العرض والطلب ويمكن تصديرها واستيرادها. وتختلف عنها في أنّها (يكفي أمران): تتوافر بشكل متزايد متخطّية حركة الحاجات؛ لا تفنى بعد الاستعمال بل إنّ استهلاكها يزيد من قيمتها؛ تتجدّد باستمرار ويمكن أن يستخدمها عدد كبير من الناس في آن واحد؛ وهي سلعة غير ملموسة تكاد تكون ملكيّة عامّة يصعب حصرها والسيطرة عليها ضمن حدود الدول والمجتمعات.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15894, 2447, 2, 'تشترك مع السلع المادّيّة في أنّها تخضع لقانون العرض والطلب ويمكن تصديرها واستيرادها. وتختلف عنها في أنّها (يكفي أمران): تتوافر بشكل متزايد متخطّية حركة الحاجات؛ لا تفنى بعد الاستعمال بل إنّ استهلاكها يزيد من قيمتها؛ تتجدّد باستمرار ويمكن أن يستخدمها عدد كبير من الناس في آن واحد؛ وهي سلعة غير ملموسة تكاد تكون ملكيّة عامّة يصعب حصرها والسيطرة عليها ضمن حدود الدول والمجتمعات.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15895, 2448, 1, '1- استمرار بعض سمات العائلة الموسّعة في نماذج الإقامة والمساعدة المتبادلة وبعض أشكال هيمنة الرجال. 2- مزارعون ومربّو مواشٍ ينقلون منتجاتهم أيّام الآحاد والأعياد إلى المدن ويبيعونها بأنفسهم. 3- استمرار حرف تقليدية وبعض مظاهر البداوة كالغجر. 4- أحياء في بعض المدن تحمل الكثير من الماضي. 5- بقاء الأميّة والإيمان بعلم الغيب وقراءة الكفّ، وأشكال من التمييز المناطقي والديني والعرقي (تُقبل أيّ أربعة).', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15896, 2448, 2, '1- استمرار بعض سمات العائلة الموسّعة في نماذج الإقامة والمساعدة المتبادلة وبعض أشكال هيمنة الرجال. 2- مزارعون ومربّو مواشٍ ينقلون منتجاتهم أيّام الآحاد والأعياد إلى المدن ويبيعونها بأنفسهم. 3- استمرار حرف تقليدية وبعض مظاهر البداوة كالغجر. 4- أحياء في بعض المدن تحمل الكثير من الماضي. 5- بقاء الأميّة والإيمان بعلم الغيب وقراءة الكفّ، وأشكال من التمييز المناطقي والديني والعرقي (تُقبل أيّ أربعة).', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15897, 2449, 1, 'تستند هذه المجتمعات إلى التطوّر العلمي مصدراً للإبداع التكنولوجي وإعادة إنتاج المعرفة، وتشهد تصاعداً في حركة المعرفة وسرعة تطبيقها. ومن خصائصها (يكفي أربع): اقتصاد يتجاوز الإطار القومي ليأخذ أبعاداً عالميّة؛ زيادة هائلة في الثروة القوميّة ومعدّلات عالية من الاستهلاك والتراكم المالي؛ قطاع الخدمات، لا القطاع الصناعي، مركز الثقل في الاقتصاد؛ دخول التنظيم والإدارة عنصراً فاعلاً في الإنتاج؛ تزايد دور العمل الذهني؛ انخفاض معدّلات الزيادة السكّانيّة وصغر حجم الأسرة.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15898, 2449, 2, 'تستند هذه المجتمعات إلى التطوّر العلمي مصدراً للإبداع التكنولوجي وإعادة إنتاج المعرفة، وتشهد تصاعداً في حركة المعرفة وسرعة تطبيقها. ومن خصائصها (يكفي أربع): اقتصاد يتجاوز الإطار القومي ليأخذ أبعاداً عالميّة؛ زيادة هائلة في الثروة القوميّة ومعدّلات عالية من الاستهلاك والتراكم المالي؛ قطاع الخدمات، لا القطاع الصناعي، مركز الثقل في الاقتصاد؛ دخول التنظيم والإدارة عنصراً فاعلاً في الإنتاج؛ تزايد دور العمل الذهني؛ انخفاض معدّلات الزيادة السكّانيّة وصغر حجم الأسرة.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15899, 2450, 1, 'يولد الطفل عاجزاً عن تأمين شروط بقائه، ويحتاج منذ اللحظة الأولى إلى الغذاء وإلى الأمان العاطفي، وإشباعهما مرتبط بوالديه ومن معهما. فيرتبط بأسرته برابط القربى، من دون قصد أو اختيار. والأسرة جماعة أولية تهتمّ بذاته وتلبّي حاجاته الأساسية، فينشأ عنده ترابط عفوي مع أفرادها ترافقه مشاعر الإشباع والاطمئنان، ثمّ يتحوّل هذا الترابط إلى انتماء يستحيل الانسحاب منه. هذه هي الصلة الاجتماعية الأولية.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15900, 2450, 2, 'يولد الطفل عاجزاً عن تأمين شروط بقائه، ويحتاج منذ اللحظة الأولى إلى الغذاء وإلى الأمان العاطفي، وإشباعهما مرتبط بوالديه ومن معهما. فيرتبط بأسرته برابط القربى، من دون قصد أو اختيار. والأسرة جماعة أولية تهتمّ بذاته وتلبّي حاجاته الأساسية، فينشأ عنده ترابط عفوي مع أفرادها ترافقه مشاعر الإشباع والاطمئنان، ثمّ يتحوّل هذا الترابط إلى انتماء يستحيل الانسحاب منه. هذه هي الصلة الاجتماعية الأولية.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15901, 2451, 1, 'في الانتماء: الانتماء إلى الجماعة الأولية عفوي، وإلى الجماعة الثانوية إرادي يختاره الإنسان. في أساس الرابط: الأولية تعتمد على معايير الولاء والقربى، والثانوية مبنيّة على التعاقد الاختياري والقانون. في مكانة الفرد: هو تابع وغير مستقلّ في الأولية، وشريك في الثانوية. ويمكن أن يضاف أنّ وجود الجماعة الثانوية محدود ومؤقّت، فتتفكّك إذا توقّفت عن نشاطها.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15902, 2451, 2, 'في الانتماء: الانتماء إلى الجماعة الأولية عفوي، وإلى الجماعة الثانوية إرادي يختاره الإنسان. في أساس الرابط: الأولية تعتمد على معايير الولاء والقربى، والثانوية مبنيّة على التعاقد الاختياري والقانون. في مكانة الفرد: هو تابع وغير مستقلّ في الأولية، وشريك في الثانوية. ويمكن أن يضاف أنّ وجود الجماعة الثانوية محدود ومؤقّت، فتتفكّك إذا توقّفت عن نشاطها.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15903, 2452, 1, 'في التجمّع لا فروق واضحة بين الأعضاء، فكلّهم متساوون ولا سلطة لأحدهم على الآخر، وتربطهم صلات غير محدّدة. فإذا امتلك التجمّع مشروعاً وتبنّى أهدافاً معيّنة وصارت له ديمومة مادية اتّخذ صفة الجماعة، فتصبح العلاقات منتظمة ومتراتبة، وتُدوَّن مقتضياتها، وتُنظَّم مواعيد اجتماعاتها، وتُوزَّع الأدوار. ثمّ تتحوّل الجماعة إلى جمعية حين تُقرّ لنفسها نظاماً يُلزم المنتسبين بضوابط وقواعد تحكم سلوكهم.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15904, 2452, 2, 'في التجمّع لا فروق واضحة بين الأعضاء، فكلّهم متساوون ولا سلطة لأحدهم على الآخر، وتربطهم صلات غير محدّدة. فإذا امتلك التجمّع مشروعاً وتبنّى أهدافاً معيّنة وصارت له ديمومة مادية اتّخذ صفة الجماعة، فتصبح العلاقات منتظمة ومتراتبة، وتُدوَّن مقتضياتها، وتُنظَّم مواعيد اجتماعاتها، وتُوزَّع الأدوار. ثمّ تتحوّل الجماعة إلى جمعية حين تُقرّ لنفسها نظاماً يُلزم المنتسبين بضوابط وقواعد تحكم سلوكهم.', 1, '2026-09-30 22:12:30', '2026-09-30 22:12:30'),
(15905, 2453, 1, 'نعم، يقع الفارق في طبيعة الرابط. الأسرة وحدة معيشية يربط أفرادها الزواج والعيش المشترك، ومن أنواعها الأسرة الزوجية النواتية والأسرة المركّبة. أمّا العائلة فوحدة سكانية يجمع أفرادها رابط الدم والقرابة، ومن أنواعها العائلة الممتدة والعائلة الواسعة.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15906, 2453, 2, 'نعم، يقع الفارق في طبيعة الرابط. الأسرة وحدة معيشية يربط أفرادها الزواج والعيش المشترك، ومن أنواعها الأسرة الزوجية النواتية والأسرة المركّبة. أمّا العائلة فوحدة سكانية يجمع أفرادها رابط الدم والقرابة، ومن أنواعها العائلة الممتدة والعائلة الواسعة.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15907, 2454, 1, 'قامت القرابة قديماً على الأمّ، لأنّ المرأة هي التي تلد وترضع وترعى شؤون الأبناء بينما ينصرف الرجل إلى شؤون أخرى. وترتكز القرابة في العصور الحديثة على الأب والأمّ معاً، مع أرجحية قرابة الدم على قرابة المصاهرة. ومن نتائج نظام القرابة ما يتعلّق بالميراث والنفقة، وبالحقوق والواجبات المتبادلة في الزواج والأسرة.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15908, 2454, 2, 'قامت القرابة قديماً على الأمّ، لأنّ المرأة هي التي تلد وترضع وترعى شؤون الأبناء بينما ينصرف الرجل إلى شؤون أخرى. وترتكز القرابة في العصور الحديثة على الأب والأمّ معاً، مع أرجحية قرابة الدم على قرابة المصاهرة. ومن نتائج نظام القرابة ما يتعلّق بالميراث والنفقة، وبالحقوق والواجبات المتبادلة في الزواج والأسرة.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15909, 2455, 1, 'يكفي ثلاث ممّا يلي: الإنجاب: لم تعد الولادات مرتبطة دائماً بالزواج، وتتطوّر هذه الوظيفة مع التقدّم الطبي. تأمين المعيشة (غذاء وكساء ومسكن وتعليم وعناية طبية وتنقّل): تحوّلت بعض الكماليات إلى أساسيات، فصارت الأسرة تتحمّل أكثر من العائلة التقليدية. التربية والتنشئة: ضعف الأخذ الحرفي عن الآباء، وشجّعت وسائل الإعلام استقلال الأبناء، فصارت التربية مسألة صعبة ومعقّدة. التنشئة العاطفية: تراجعت سلطة الأسرة، لكنّ المحبّة والتقدير والحماية بقيت نقطة الثقل وأساس الصحّة النفسية والتوازن العاطفي.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15910, 2455, 2, 'يكفي ثلاث ممّا يلي: الإنجاب: لم تعد الولادات مرتبطة دائماً بالزواج، وتتطوّر هذه الوظيفة مع التقدّم الطبي. تأمين المعيشة (غذاء وكساء ومسكن وتعليم وعناية طبية وتنقّل): تحوّلت بعض الكماليات إلى أساسيات، فصارت الأسرة تتحمّل أكثر من العائلة التقليدية. التربية والتنشئة: ضعف الأخذ الحرفي عن الآباء، وشجّعت وسائل الإعلام استقلال الأبناء، فصارت التربية مسألة صعبة ومعقّدة. التنشئة العاطفية: تراجعت سلطة الأسرة، لكنّ المحبّة والتقدير والحماية بقيت نقطة الثقل وأساس الصحّة النفسية والتوازن العاطفي.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15911, 2456, 1, 'شكّل توسّع الثورة الصناعيّة في أوروبا، وفي إنكلترا خصوصاً، قوّة جذب للفلّاحين والرعاة فنزحوا إلى المناطق الصناعيّة، لكنّ ظروفهم لم تسمح بأكثر من دخل بسيط ومستوى معيشة متردٍّ. فأدّت شروط الاستغلال والتشريد من جهة، والأفكار الإصلاحيّة والثوريّة من جهة أخرى، إلى ظهور مفهوم النقابة بوصفها تنظيماً يعالج نزاع المصالح بين أصحاب رأس المال وأصحاب قوّة العمل. وساد الساحة النقابيّة اتّجاهان: اتّجاه إصلاحيّ محافظ، واتّجاه ثوريّ.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15912, 2456, 2, 'شكّل توسّع الثورة الصناعيّة في أوروبا، وفي إنكلترا خصوصاً، قوّة جذب للفلّاحين والرعاة فنزحوا إلى المناطق الصناعيّة، لكنّ ظروفهم لم تسمح بأكثر من دخل بسيط ومستوى معيشة متردٍّ. فأدّت شروط الاستغلال والتشريد من جهة، والأفكار الإصلاحيّة والثوريّة من جهة أخرى، إلى ظهور مفهوم النقابة بوصفها تنظيماً يعالج نزاع المصالح بين أصحاب رأس المال وأصحاب قوّة العمل. وساد الساحة النقابيّة اتّجاهان: اتّجاه إصلاحيّ محافظ، واتّجاه ثوريّ.', 1, '2026-09-30 22:12:31', '2026-09-30 22:12:31'),
(15913, 2457, 1, 'من وظائف النقابة (يكفي اثنتان): تحسين شروط العمل وتعزيز الضمانات الاجتماعيّة والاقتصاديّة ومعالجة البطالة والدفاع عن الحرّيّات النقابيّة والاجتماعيّة؛ الاطّلاع على تغيّرات مزاولة المهنة وتطويرها لتحسين أداء العاملين وإنتاجيّتهم؛ المساهمة في التنشئة الاجتماعيّة والمدنيّة للعاملين؛ الدفاع بالطرق القانونيّة عن النقابيّين عموماً والناشطين خصوصاً. وعقد العمل الجماعيّ اتّفاق تعقده التنظيمات النقابيّة الأكثر تمثيلاً مع ممثّلي أصحاب العمل، على مستوى قطاع كامل كالمصارف أو داخل مؤسّسة واحدة، ويفصّل حقوق الأجير وواجباته. ويراقب الممثّلون النقابيّون تقيّد ربّ العمل به، فإن خرجت الإدارة عليه نبّهوا مفتّش العمل ورفعوا دعوى عليها.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15914, 2457, 2, 'من وظائف النقابة (يكفي اثنتان): تحسين شروط العمل وتعزيز الضمانات الاجتماعيّة والاقتصاديّة ومعالجة البطالة والدفاع عن الحرّيّات النقابيّة والاجتماعيّة؛ الاطّلاع على تغيّرات مزاولة المهنة وتطويرها لتحسين أداء العاملين وإنتاجيّتهم؛ المساهمة في التنشئة الاجتماعيّة والمدنيّة للعاملين؛ الدفاع بالطرق القانونيّة عن النقابيّين عموماً والناشطين خصوصاً. وعقد العمل الجماعيّ اتّفاق تعقده التنظيمات النقابيّة الأكثر تمثيلاً مع ممثّلي أصحاب العمل، على مستوى قطاع كامل كالمصارف أو داخل مؤسّسة واحدة، ويفصّل حقوق الأجير وواجباته. ويراقب الممثّلون النقابيّون تقيّد ربّ العمل به، فإن خرجت الإدارة عليه نبّهوا مفتّش العمل ورفعوا دعوى عليها.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15915, 2458, 1, 'من حيث النشأة: يرتبط التجمّع بحدث أو مناسبة محدّدة تتطلّب تحرّكاً جماعيّاً للمؤازرة أو الاحتجاج أو الضغط، أمّا التيّار فيقوم على اتّجاه سياسيّ معيّن (كالليبراليّ الرأسماليّ أو اليساريّ الاشتراكيّ)، أو على قضيّة تطول فئات من الناس، أو على قائد يطرح قضيّة بأسلوبه الخاصّ. من حيث الاستمرار: يبقى التجمّع إلى أن يتحقّق هدفه فقط، أمّا التيّار فيقوم على التزام وولاء مستمرّين.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15916, 2458, 2, 'من حيث النشأة: يرتبط التجمّع بحدث أو مناسبة محدّدة تتطلّب تحرّكاً جماعيّاً للمؤازرة أو الاحتجاج أو الضغط، أمّا التيّار فيقوم على اتّجاه سياسيّ معيّن (كالليبراليّ الرأسماليّ أو اليساريّ الاشتراكيّ)، أو على قضيّة تطول فئات من الناس، أو على قائد يطرح قضيّة بأسلوبه الخاصّ. من حيث الاستمرار: يبقى التجمّع إلى أن يتحقّق هدفه فقط، أمّا التيّار فيقوم على التزام وولاء مستمرّين.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15917, 2459, 1, 'الأحزاب الدينيّة: تستند إلى نصوص مستمدّة من عقائد دينيّة تسعى إلى تطبيقها. الأحزاب الطائفيّة: تنطلق من مبادئ وأفكار دينيّة وسياسيّة، وتجذب خصوصاً الفئات الشعبيّة داخل الطائفة. الأحزاب السياسيّة المدنيّة: غير دينيّة وغير طائفيّة، تلتزم بأفكار سياسيّة معاصرة تنبع من الفلسفات والعقائد والأفكار غير الدينيّة، وقد تراوحت بين الرأسماليّة الليبراليّة والاشتراكيّة والشيوعيّة.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15918, 2459, 2, 'الأحزاب الدينيّة: تستند إلى نصوص مستمدّة من عقائد دينيّة تسعى إلى تطبيقها. الأحزاب الطائفيّة: تنطلق من مبادئ وأفكار دينيّة وسياسيّة، وتجذب خصوصاً الفئات الشعبيّة داخل الطائفة. الأحزاب السياسيّة المدنيّة: غير دينيّة وغير طائفيّة، تلتزم بأفكار سياسيّة معاصرة تنبع من الفلسفات والعقائد والأفكار غير الدينيّة، وقد تراوحت بين الرأسماليّة الليبراليّة والاشتراكيّة والشيوعيّة.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15919, 2460, 1, 'التحوّلات: انحسار الصناعات الميكانيكيّة الضخمة التي كانت تضمّ أعداداً كثيفة من العمّال، في ظلّ تقنيّات جديدة في الإنتاج والتوزيع والاتّصالات والخدمات، فانحسرت التجمّعات العمّاليّة وصار الفنّيّون والمهندسون غالبيّة العاملين، وصارت فئة العمّال غير الفنّيّين محدودة وسهلة الاستبدال بسبب تنامي البطالة. النتائج: تراجع قدرة الجماهير على الضغط والتهديد بالإضراب، وضعف روح النضال النقابيّ لصالح الاتّجاه التفاوضيّ، وتراجع معدّل الانتساب إلى النقابات في لبنان كما في فرنسا.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15920, 2460, 2, 'التحوّلات: انحسار الصناعات الميكانيكيّة الضخمة التي كانت تضمّ أعداداً كثيفة من العمّال، في ظلّ تقنيّات جديدة في الإنتاج والتوزيع والاتّصالات والخدمات، فانحسرت التجمّعات العمّاليّة وصار الفنّيّون والمهندسون غالبيّة العاملين، وصارت فئة العمّال غير الفنّيّين محدودة وسهلة الاستبدال بسبب تنامي البطالة. النتائج: تراجع قدرة الجماهير على الضغط والتهديد بالإضراب، وضعف روح النضال النقابيّ لصالح الاتّجاه التفاوضيّ، وتراجع معدّل الانتساب إلى النقابات في لبنان كما في فرنسا.', 1, '2026-09-30 22:12:32', '2026-09-30 22:12:32'),
(15921, 2461, 1, 'الوظائف: إعداد الرأي العامّ وإشراكه في النقاش حول القضايا العامّة؛ اختيار المرشّحين للانتخابات من صفوفه وفق مقاييس محدّدة؛ حمل مطالب الناس إلى الندوة البرلمانيّة وتشكيل كتل نيابيّة لإقرارها؛ تشكيل قوى ضغط تعزّز الشأن العامّ وتحدّ من اتّجاه التسلّط. لكنّ الأحزاب قلّما تنجح في هذه المهامّ في الواقع، وخاصّة في البلدان الفقيرة. وفي لبنان يرتبط ذلك بدور الأحزاب والميليشيات في الحرب، وبغلبة الطابع العسكريّ الميليشياويّ على الروح النضاليّة المدنيّة الديمقراطيّة داخلها.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15922, 2461, 2, 'الوظائف: إعداد الرأي العامّ وإشراكه في النقاش حول القضايا العامّة؛ اختيار المرشّحين للانتخابات من صفوفه وفق مقاييس محدّدة؛ حمل مطالب الناس إلى الندوة البرلمانيّة وتشكيل كتل نيابيّة لإقرارها؛ تشكيل قوى ضغط تعزّز الشأن العامّ وتحدّ من اتّجاه التسلّط. لكنّ الأحزاب قلّما تنجح في هذه المهامّ في الواقع، وخاصّة في البلدان الفقيرة. وفي لبنان يرتبط ذلك بدور الأحزاب والميليشيات في الحرب، وبغلبة الطابع العسكريّ الميليشياويّ على الروح النضاليّة المدنيّة الديمقراطيّة داخلها.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15923, 2462, 1, 'الدوافع: تنامي حاجات الأفراد وتنوّعها وتشعّبها؛ بروز ضرورة تنظيم شؤون حياتهم المشتركة والتكتّل لتأمين مشاركتهم في النشاطات الاجتماعيّة؛ حاجة أوضاع الفئات الاجتماعيّة إلى معالجات خاصّة تتّسم بالتخصّص والاستمراريّة، فظهرت الحاجة إلى تنظيمات وثيقة الصلة بهذه الفئات. التعريف: الجمعيّة التطوّعيّة (المنظّمة غير الحكوميّة) منظّمة تتشكّل من أعضاء تجمعهم أهداف إنسانيّة مشتركة، تنشأ على أساس العمل التطوّعيّ، وتتبنّى أنظمة وقوانين خاصّة بها.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15924, 2462, 2, 'الدوافع: تنامي حاجات الأفراد وتنوّعها وتشعّبها؛ بروز ضرورة تنظيم شؤون حياتهم المشتركة والتكتّل لتأمين مشاركتهم في النشاطات الاجتماعيّة؛ حاجة أوضاع الفئات الاجتماعيّة إلى معالجات خاصّة تتّسم بالتخصّص والاستمراريّة، فظهرت الحاجة إلى تنظيمات وثيقة الصلة بهذه الفئات. التعريف: الجمعيّة التطوّعيّة (المنظّمة غير الحكوميّة) منظّمة تتشكّل من أعضاء تجمعهم أهداف إنسانيّة مشتركة، تنشأ على أساس العمل التطوّعيّ، وتتبنّى أنظمة وقوانين خاصّة بها.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15925, 2463, 1, 'لأنّ الجمعيّة وثيقة الصلة بالفئات الاجتماعيّة وتعالج حاجاتها بتخصّص واستمرار؛ وهي توعّي الناس على حقيقة أوضاعهم، وتشدّ انتباه الأجهزة الحكوميّة إلى ضرورة معالجة حاجات الناس؛ كما أنّها وسيط يربط الجمهور الذي تعمل من أجله بالأجهزة الرسميّة (الإدارات العامّة)، فتتفاعل معها حيناً وتواجهها حيناً آخر.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15926, 2463, 2, 'لأنّ الجمعيّة وثيقة الصلة بالفئات الاجتماعيّة وتعالج حاجاتها بتخصّص واستمرار؛ وهي توعّي الناس على حقيقة أوضاعهم، وتشدّ انتباه الأجهزة الحكوميّة إلى ضرورة معالجة حاجات الناس؛ كما أنّها وسيط يربط الجمهور الذي تعمل من أجله بالأجهزة الرسميّة (الإدارات العامّة)، فتتفاعل معها حيناً وتواجهها حيناً آخر.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15927, 2464, 1, 'كثرة الجمعيّات المسجّلة تعكس مستوى ديمقراطيّاً في التأسيس، لكنّ الترخيص وحده لا يعني النشاط. فعدم مراعاة الاختصاص في استخدام العاملين الاجتماعيّين يُفقد الجمعيّات فرص التمويل من الجهات الأجنبيّة والرسميّة، فيعجز معظمها عن تلبية شروط المموّلين، ويواجه صعوبات ماليّة وإداريّة وبشريّة تهدّد وجوده وتعيق أدواره، فيتراجع نشاطه أو يتوقّف.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15928, 2464, 2, 'كثرة الجمعيّات المسجّلة تعكس مستوى ديمقراطيّاً في التأسيس، لكنّ الترخيص وحده لا يعني النشاط. فعدم مراعاة الاختصاص في استخدام العاملين الاجتماعيّين يُفقد الجمعيّات فرص التمويل من الجهات الأجنبيّة والرسميّة، فيعجز معظمها عن تلبية شروط المموّلين، ويواجه صعوبات ماليّة وإداريّة وبشريّة تهدّد وجوده وتعيق أدواره، فيتراجع نشاطه أو يتوقّف.', 1, '2026-09-30 22:12:33', '2026-09-30 22:12:33'),
(15929, 2465, 1, 'التنظيمات الكشفيّة حركة طوعيّة تربويّة للشبيبة، تقوم هيكليّتها على فرق وأفواج تتوزّع فيها المسؤوليّات وفق تراتب داخلي. من وظائفها (ثلاث ممّا يلي): تنظيم الشبيبة في أطر دائمة وفاعلة وتعويدهم التقيّد بالنظام واحترامه؛ تنمية استقلاليّتهم؛ تطوير قدرتهم على التكيّف مع ظروف الحياة الصعبة؛ دعوتهم إلى خدمة المجتمع والفرد والالتزام بالقيم الإنسانيّة؛ إشراكهم في تنظيم المشاريع ونشر فكرة التطوّع.', 1, '2026-09-30 22:12:35', '2026-09-30 22:12:35'),
(15930, 2465, 2, 'التنظيمات الكشفيّة حركة طوعيّة تربويّة للشبيبة، تقوم هيكليّتها على فرق وأفواج تتوزّع فيها المسؤوليّات وفق تراتب داخلي. من وظائفها (ثلاث ممّا يلي): تنظيم الشبيبة في أطر دائمة وفاعلة وتعويدهم التقيّد بالنظام واحترامه؛ تنمية استقلاليّتهم؛ تطوير قدرتهم على التكيّف مع ظروف الحياة الصعبة؛ دعوتهم إلى خدمة المجتمع والفرد والالتزام بالقيم الإنسانيّة؛ إشراكهم في تنظيم المشاريع ونشر فكرة التطوّع.', 1, '2026-09-30 22:12:35', '2026-09-30 22:12:35'),
(15931, 2466, 1, 'النادي الرياضي يدرّب الشباب على ممارسة لعبة أو أكثر من الألعاب المنظّمة دولياً، وينمّي قدراتهم الجسديّة والنفسيّة، ويعوّدهم التعاون والمنافسة بروح رياضيّة. أمّا النادي الثقافي فينظّم الندوات والمعارض والرحلات والنشاطات الثقافيّة، وينمّي وعي الشباب ومواهبهم. فالأوّل يعنى بالصحّة والقدرات الجسديّة، والثاني يعنى بالوعي والثقافة.', 1, '2026-09-30 22:12:35', '2026-09-30 22:12:35'),
(15932, 2466, 2, 'النادي الرياضي يدرّب الشباب على ممارسة لعبة أو أكثر من الألعاب المنظّمة دولياً، وينمّي قدراتهم الجسديّة والنفسيّة، ويعوّدهم التعاون والمنافسة بروح رياضيّة. أمّا النادي الثقافي فينظّم الندوات والمعارض والرحلات والنشاطات الثقافيّة، وينمّي وعي الشباب ومواهبهم. فالأوّل يعنى بالصحّة والقدرات الجسديّة، والثاني يعنى بالوعي والثقافة.', 1, '2026-09-30 22:12:35', '2026-09-30 22:12:35'),
(15933, 2467, 1, 'يمثّل ذلك تحوّلاً إيجابيّاً، هو انتقال النادي من ممارسة هواية محدودة إلى تنمية المجتمع المحلّي وخدمته. ومن التحوّلات السلبيّة (اثنان ممّا يلي): دخول التعصّب الطائفي والسياسي خلال الحرب وبعدها؛ غياب الانتخاب الحرّ للقيادات الكفوءة؛ تغليب الروح الفئويّة.', 1, '2026-09-30 22:12:36', '2026-09-30 22:12:36'),
(15934, 2467, 2, 'يمثّل ذلك تحوّلاً إيجابيّاً، هو انتقال النادي من ممارسة هواية محدودة إلى تنمية المجتمع المحلّي وخدمته. ومن التحوّلات السلبيّة (اثنان ممّا يلي): دخول التعصّب الطائفي والسياسي خلال الحرب وبعدها؛ غياب الانتخاب الحرّ للقيادات الكفوءة؛ تغليب الروح الفئويّة.', 1, '2026-09-30 22:12:36', '2026-09-30 22:12:36'),
(15935, 2468, 1, 'من وسائل الإعلام الجماهيري: الإذاعة، التلفزيون، الفيديو، المطبوعات (خصوصاً الصحف اليومية والمجلات). وتتميّز وسيلة الاتصال المتعدّدة بأنّها تجمع، من خلال شبكات المعلوماتية، في جهاز واحد وظائف الإذاعة والتلفزيون والفيديو والطباعة، إلى جانب وسائل الاتصال الشخصي كالهاتف والفاكس والمراسلة، وهي مبنيّة على تقنية قاعدية مشتركة هي البثّ اللاسلكي الموجّه إلى الجمهور العام.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15936, 2468, 2, 'من وسائل الإعلام الجماهيري: الإذاعة، التلفزيون، الفيديو، المطبوعات (خصوصاً الصحف اليومية والمجلات). وتتميّز وسيلة الاتصال المتعدّدة بأنّها تجمع، من خلال شبكات المعلوماتية، في جهاز واحد وظائف الإذاعة والتلفزيون والفيديو والطباعة، إلى جانب وسائل الاتصال الشخصي كالهاتف والفاكس والمراسلة، وهي مبنيّة على تقنية قاعدية مشتركة هي البثّ اللاسلكي الموجّه إلى الجمهور العام.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15937, 2469, 1, 'التواصل قائم على تبادل الرسائل والمعلومات وعلى فهمها. والدائرة الاتصالية علاقة مثلّثة العناصر: المرسل أو المصدر، والرسالة، والمتلقي. ولكي تفي الرسالة بغرضها يجب أن تخضع لاتفاق ضمنيّ بين المصدر والمتلقي يجعلها مفهومة منهما، يشمل لغة مشتركة يفهمها الطرفان بسهولة، ووسيلة يسهل عليهما استخدامها، والمضمون (خاصّ أو عامّ).', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15938, 2469, 2, 'التواصل قائم على تبادل الرسائل والمعلومات وعلى فهمها. والدائرة الاتصالية علاقة مثلّثة العناصر: المرسل أو المصدر، والرسالة، والمتلقي. ولكي تفي الرسالة بغرضها يجب أن تخضع لاتفاق ضمنيّ بين المصدر والمتلقي يجعلها مفهومة منهما، يشمل لغة مشتركة يفهمها الطرفان بسهولة، ووسيلة يسهل عليهما استخدامها، والمضمون (خاصّ أو عامّ).', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15939, 2470, 1, 'بدأ الإعلام المتلفز مع شركتين: شركة تلفزيون لبنان، وشركة تلفزيون لبنان والمشرق؛ ومع أنّهما خاصّتان كانت برامجهما خاضعة لرقابة حكومية مباشرة، ونشرات الأخبار والبرامج السياسية رسمية بالكامل. ثمّ دُمجت الشركتان في تلفزيون لبنان تملك الدولة نصف أسهمه، ثمّ اشترت الدولة كامل الأسهم. وخلال الأزمة اللبنانية ظهرت أوّل مؤسّسة تلفزيونية خاصة تعبّر عن فريق معيّن، ثمّ نشأت أعداد متزايدة من التلفزيونات الخاصة.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15940, 2470, 2, 'بدأ الإعلام المتلفز مع شركتين: شركة تلفزيون لبنان، وشركة تلفزيون لبنان والمشرق؛ ومع أنّهما خاصّتان كانت برامجهما خاضعة لرقابة حكومية مباشرة، ونشرات الأخبار والبرامج السياسية رسمية بالكامل. ثمّ دُمجت الشركتان في تلفزيون لبنان تملك الدولة نصف أسهمه، ثمّ اشترت الدولة كامل الأسهم. وخلال الأزمة اللبنانية ظهرت أوّل مؤسّسة تلفزيونية خاصة تعبّر عن فريق معيّن، ثمّ نشأت أعداد متزايدة من التلفزيونات الخاصة.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15941, 2471, 1, 'المعنى المحدّد للغة هو اللسان، كالعربية والفرنسية والإنكليزية، نؤلّف فيه من الكلمات جملاً نعبّر بها عن أفكارنا. والمعنى العامّ يشمل وسائل تفاهم لا تستخدم الكلمات، ومنها (مثالان): لغة الحركات باليد والأصابع التي يستخدمها الصمّ والبكم؛ لغة اللمس (برايل) التي يستخدمها العميان؛ لغة الإشارات والرموز كإشارات السير؛ لغة الجسد للتعبير عن الفرح والحزن والخوف.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15942, 2471, 2, 'المعنى المحدّد للغة هو اللسان، كالعربية والفرنسية والإنكليزية، نؤلّف فيه من الكلمات جملاً نعبّر بها عن أفكارنا. والمعنى العامّ يشمل وسائل تفاهم لا تستخدم الكلمات، ومنها (مثالان): لغة الحركات باليد والأصابع التي يستخدمها الصمّ والبكم؛ لغة اللمس (برايل) التي يستخدمها العميان؛ لغة الإشارات والرموز كإشارات السير؛ لغة الجسد للتعبير عن الفرح والحزن والخوف.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15943, 2472, 1, 'لأنّ الإعلام قويّ التأثير، فهو يؤدّي في بناء أفكار الناس دوراً معادلاً لدور العائلة والمدرسة وحتى الجامعة. وهو خطير، إذ قد يستغلّ غرائزنا وميولنا ليفرض علينا كلّ شيء، من الثياب العصرية إلى الزعماء السياسيين، ويصنع آراءنا وأذواقنا وسلوكنا. ولأنّ الجمهور له آراؤه وقناعاته، أصبح مطلوباً قيام علاقة جدلية مع الإعلام تنمّي الحسّ النقدي لدى الرأي العام.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15944, 2472, 2, 'لأنّ الإعلام قويّ التأثير، فهو يؤدّي في بناء أفكار الناس دوراً معادلاً لدور العائلة والمدرسة وحتى الجامعة. وهو خطير، إذ قد يستغلّ غرائزنا وميولنا ليفرض علينا كلّ شيء، من الثياب العصرية إلى الزعماء السياسيين، ويصنع آراءنا وأذواقنا وسلوكنا. ولأنّ الجمهور له آراؤه وقناعاته، أصبح مطلوباً قيام علاقة جدلية مع الإعلام تنمّي الحسّ النقدي لدى الرأي العام.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15945, 2473, 1, 'في التلفزيون: المصدر مؤسسة إعلامية، والمتلقي عامّ وواسع جداً وشديد التنوّع، والرسالة بمضمون وأسلوب صالحين للجميع؛ فهو تواصل جماهيري. في المدرسة: المصدر الأستاذ أو المدير، والمتلقي صفّ التلاميذ وهو متلقٍّ محدّد، فيكون الاتصال هادفاً لأنّ المصدر يعرف خصائص المتلقي ويضع المضمون تبعاً لها.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15946, 2473, 2, 'في التلفزيون: المصدر مؤسسة إعلامية، والمتلقي عامّ وواسع جداً وشديد التنوّع، والرسالة بمضمون وأسلوب صالحين للجميع؛ فهو تواصل جماهيري. في المدرسة: المصدر الأستاذ أو المدير، والمتلقي صفّ التلاميذ وهو متلقٍّ محدّد، فيكون الاتصال هادفاً لأنّ المصدر يعرف خصائص المتلقي ويضع المضمون تبعاً لها.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15947, 2474, 1, 'الكومبيوتر أساساً آلة حاسبة إلكترونيّة. من قدراته (ثلاث ممّا يلي): تحليل المعلومات بسرعة فائقة بفضل قوّته الحسابيّة؛ تحويلها إلى أحرف وصور وإشارات من خلال البرامج المسجّلة داخله؛ تخزينها في ذاكرة كبيرة؛ التدخّل في النصّ وإعادة تركيبه بسرعة كبيرة؛ العمل على الصورة والحركة وحساب تفاصيل حركات الجسم (مثل تحريك صورة الديناصور).', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15948, 2474, 2, 'الكومبيوتر أساساً آلة حاسبة إلكترونيّة. من قدراته (ثلاث ممّا يلي): تحليل المعلومات بسرعة فائقة بفضل قوّته الحسابيّة؛ تحويلها إلى أحرف وصور وإشارات من خلال البرامج المسجّلة داخله؛ تخزينها في ذاكرة كبيرة؛ التدخّل في النصّ وإعادة تركيبه بسرعة كبيرة؛ العمل على الصورة والحركة وحساب تفاصيل حركات الجسم (مثل تحريك صورة الديناصور).', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15949, 2475, 1, 'ثلاثة ممّا يلي: سهّل الاتصال الهاتفي وخاصّة عبر الجهاز الخليوي؛ سمح بتخزين المعلومات وتبادلها على مستوى عالمي عبر الإنترنت؛ أحدث ثورة في السينما والتلفزيون في التصوير والتركيب والمؤثّرات؛ سهّل تصنيف المراجع والكتب وطوّر علم المكتبات وتبادل المعلومات في ما بينها؛ سرّع الاتصالات الشخصيّة عبر البريد الإلكتروني؛ أدّى دوراً كبيراً في الإدارة العامّة خدمةً للمواطنين.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15950, 2475, 2, 'ثلاثة ممّا يلي: سهّل الاتصال الهاتفي وخاصّة عبر الجهاز الخليوي؛ سمح بتخزين المعلومات وتبادلها على مستوى عالمي عبر الإنترنت؛ أحدث ثورة في السينما والتلفزيون في التصوير والتركيب والمؤثّرات؛ سهّل تصنيف المراجع والكتب وطوّر علم المكتبات وتبادل المعلومات في ما بينها؛ سرّع الاتصالات الشخصيّة عبر البريد الإلكتروني؛ أدّى دوراً كبيراً في الإدارة العامّة خدمةً للمواطنين.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15951, 2476, 1, 'العولمة الثقافيّة هي انتشار منتجات برمجة تنتمي في غالبيّتها العظمى، وخاصّة الترفيهيّة، إلى ثقافة واحدة هي الثقافة الأميركيّة، في كلّ البلدان. ويحصل الصراع لأنّ المنافسة شديدة بين القوى التكنولوجيّة الكبرى، وتؤدّي الولايات المتّحدة دوراً مسيطراً لأنّها الأولى في إنتاج تكنولوجيا البرمجة. والموقف: الاستفادة منها شيء والرضوخ لها شيء آخر؛ فالانفتاح مفيد لمن يحسن التعامل معه، فيكتشف العالم ما لدى ثقافتنا ويطالب بالمزيد فتتطوّر مساهماتنا العالميّة.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15952, 2476, 2, 'العولمة الثقافيّة هي انتشار منتجات برمجة تنتمي في غالبيّتها العظمى، وخاصّة الترفيهيّة، إلى ثقافة واحدة هي الثقافة الأميركيّة، في كلّ البلدان. ويحصل الصراع لأنّ المنافسة شديدة بين القوى التكنولوجيّة الكبرى، وتؤدّي الولايات المتّحدة دوراً مسيطراً لأنّها الأولى في إنتاج تكنولوجيا البرمجة. والموقف: الاستفادة منها شيء والرضوخ لها شيء آخر؛ فالانفتاح مفيد لمن يحسن التعامل معه، فيكتشف العالم ما لدى ثقافتنا ويطالب بالمزيد فتتطوّر مساهماتنا العالميّة.', 1, '2026-09-30 22:12:37', '2026-09-30 22:12:37'),
(15953, 2477, 1, 'القيم الإنسانيّة مبادئ سامية ومُثُل عليا تُبعد الإنسان عن السلوك الغريزيّ وتغذّي فيه الأخلاق النبيلة. من يلتزم القيم ينعم براحة البال ورضى الضمير، ويفوز بمحبّة الآخرين واحترامهم، فيعيش حياة هادئة. ومن هذه القيم العمل الذي يُبعد عنه السأم والرذيلة والحاجة.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15954, 2477, 2, 'القيم الإنسانيّة مبادئ سامية ومُثُل عليا تُبعد الإنسان عن السلوك الغريزيّ وتغذّي فيه الأخلاق النبيلة. من يلتزم القيم ينعم براحة البال ورضى الضمير، ويفوز بمحبّة الآخرين واحترامهم، فيعيش حياة هادئة. ومن هذه القيم العمل الذي يُبعد عنه السأم والرذيلة والحاجة.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15955, 2478, 1, 'الجماعة يضرّها التفرّق وتفشّي الخلافات والبغضاء، ويحفظها التعاون والتضامن والتضحية. العدل: أولى مراتبه أن ينظر الإنسان إلى نفسه كواحد من أفراد المجتمع، وأعلاها المساعدة على رفع الظلم عن المظلوم ومقاومة العدوان. السلام: يزرع الحبّ بين الناس ويمحو من قلوبهم البغضاء ويصلح بين المتخاصمين، بخلاف النميمة والفتنة اللتين تنشران الأحقاد.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15956, 2478, 2, 'الجماعة يضرّها التفرّق وتفشّي الخلافات والبغضاء، ويحفظها التعاون والتضامن والتضحية. العدل: أولى مراتبه أن ينظر الإنسان إلى نفسه كواحد من أفراد المجتمع، وأعلاها المساعدة على رفع الظلم عن المظلوم ومقاومة العدوان. السلام: يزرع الحبّ بين الناس ويمحو من قلوبهم البغضاء ويصلح بين المتخاصمين، بخلاف النميمة والفتنة اللتين تنشران الأحقاد.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15957, 2479, 1, 'عبر الزمان: قالت المجتمعات الغابرة بالرقّ والعبوديّة وقدسيّة الحكّام، والأمم المعاصرة تدينها. في الزمان الواحد: التحيّة في اليابان ليست هي نفسها في بريطانيا، وبعض المجتمعات يُسند الاقتصاص من المجرم إلى المحاكم وبعضها يعتمد الأخذ بالثأر. ومع ذلك تلتقي الشعوب على قيم مشتركة كالخير والكرم والتسامح والرحمة والعدل ومحبّة الآخر.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15958, 2479, 2, 'عبر الزمان: قالت المجتمعات الغابرة بالرقّ والعبوديّة وقدسيّة الحكّام، والأمم المعاصرة تدينها. في الزمان الواحد: التحيّة في اليابان ليست هي نفسها في بريطانيا، وبعض المجتمعات يُسند الاقتصاص من المجرم إلى المحاكم وبعضها يعتمد الأخذ بالثأر. ومع ذلك تلتقي الشعوب على قيم مشتركة كالخير والكرم والتسامح والرحمة والعدل ومحبّة الآخر.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15959, 2480, 1, 'الديمقراطيّة حكمٌ تنبثق السلطة فيه من الشعب. كانت ديمقراطيّة أثينا نظاماً يقوم على الشورى بين الأحرار ويشركهم في الحكم، لكنّ المجتمع كان منقسماً إلى أحرار وعبيد، والعبيد أرقّاء محصورة مهمّتهم في الأعمال اليدويّة ولم ينالوا حقوقهم الاجتماعيّة، فانتهى الأمر إلى زوال هذه الديمقراطيّة.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15960, 2480, 2, 'الديمقراطيّة حكمٌ تنبثق السلطة فيه من الشعب. كانت ديمقراطيّة أثينا نظاماً يقوم على الشورى بين الأحرار ويشركهم في الحكم، لكنّ المجتمع كان منقسماً إلى أحرار وعبيد، والعبيد أرقّاء محصورة مهمّتهم في الأعمال اليدويّة ولم ينالوا حقوقهم الاجتماعيّة، فانتهى الأمر إلى زوال هذه الديمقراطيّة.', 1, '2026-09-30 22:12:38', '2026-09-30 22:12:38'),
(15961, 2481, 1, 'الديمقراطيّة بمضمونها السياسيّ تعترف للمواطن بحقوقه وحرّيّاته الأساسيّة، مثل الحقّ في المشاركة في الحكم عبر الاقتراع العامّ وحرّيّة التعبير عن الرأي (أو الاجتماع والنشر). أمّا بمضمونها الاجتماعيّ فتهدف إلى تحسين المستوى المعيشيّ للمواطنين وتحريرهم من الحاجة، فتعترف لهم بحقوق كالحقّ في التعلّم والعمل (أو الضمان الصحّيّ وضمان الشيخوخة) وتوفّر الشروط المادّيّة للتمتّع بها.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15962, 2481, 2, 'الديمقراطيّة بمضمونها السياسيّ تعترف للمواطن بحقوقه وحرّيّاته الأساسيّة، مثل الحقّ في المشاركة في الحكم عبر الاقتراع العامّ وحرّيّة التعبير عن الرأي (أو الاجتماع والنشر). أمّا بمضمونها الاجتماعيّ فتهدف إلى تحسين المستوى المعيشيّ للمواطنين وتحريرهم من الحاجة، فتعترف لهم بحقوق كالحقّ في التعلّم والعمل (أو الضمان الصحّيّ وضمان الشيخوخة) وتوفّر الشروط المادّيّة للتمتّع بها.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15963, 2482, 1, 'الديمقراطيّة حكم الأكثريّة الملتزمة بقيم الديمقراطيّة ومبادئها وقواعدها. فالقوانين والقواعد الدستوريّة ونظام الحكم لا قيمة لها إلّا بقدر ما يتمسّك الشعب بمبادئها وقيمها. مثال: لا يجوز لحكومة في نظام ديمقراطيّ أن تتّخذ قراراً يجيز التمييز العنصريّ، ولا يُعَدّ قرارها ديمقراطيّاً حتّى لو عبّر عن إرادة الأكثريّة.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15964, 2482, 2, 'الديمقراطيّة حكم الأكثريّة الملتزمة بقيم الديمقراطيّة ومبادئها وقواعدها. فالقوانين والقواعد الدستوريّة ونظام الحكم لا قيمة لها إلّا بقدر ما يتمسّك الشعب بمبادئها وقيمها. مثال: لا يجوز لحكومة في نظام ديمقراطيّ أن تتّخذ قراراً يجيز التمييز العنصريّ، ولا يُعَدّ قرارها ديمقراطيّاً حتّى لو عبّر عن إرادة الأكثريّة.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15965, 2483, 1, 'لأنّ الديمقراطيّة في جوهرها قيم ومبادئ تحكم سلوك الإنسان، فهي تعيش في تصرّفات الناس لا في النصوص وحدها. على المؤسّسات أن تفسح في المجال أمام الشعب ليشارك في القرار وفي إدارة الشأن العامّ، وعلى الشعب أن يتمسّك بحقوقه وحرّيّاته ويدافع عنها ويواجه الظلم، والغاية أن تتحوّل القيم الديمقراطيّة إلى واقع.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15966, 2483, 2, 'لأنّ الديمقراطيّة في جوهرها قيم ومبادئ تحكم سلوك الإنسان، فهي تعيش في تصرّفات الناس لا في النصوص وحدها. على المؤسّسات أن تفسح في المجال أمام الشعب ليشارك في القرار وفي إدارة الشأن العامّ، وعلى الشعب أن يتمسّك بحقوقه وحرّيّاته ويدافع عنها ويواجه الظلم، والغاية أن تتحوّل القيم الديمقراطيّة إلى واقع.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15967, 2484, 1, 'المساواة هي تساوي المواطنين أمام القانون وفي الحقوق والواجبات. من الممارسات المرفوضة: سجن الأبرياء اعتباطاً، والاستيلاء على ممتلكاتهم، وتعريضهم للتعذيب أو النفي دون جرم قانونيّ.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15968, 2484, 2, 'المساواة هي تساوي المواطنين أمام القانون وفي الحقوق والواجبات. من الممارسات المرفوضة: سجن الأبرياء اعتباطاً، والاستيلاء على ممتلكاتهم، وتعريضهم للتعذيب أو النفي دون جرم قانونيّ.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15969, 2485, 1, 'التزام الحكّام والمواطنين القيم الديمقراطيّة في السلوك يؤدّي إلى التراضي والتوافق. لكنّ ذلك لا ينفي إمكان حصول الخلاف والنزاع، وفي هذه الحال تقضي القيم الديمقراطيّة بتقبّل فكرة الخلاف وإدارته بين الأفراد والجماعات. وإذا أساء الحكّام استعمال السلطة يصبح التصدّي لهم مشروعاً وضروريّاً، مع بقاء الأساليب الديمقراطيّة الأهمّ لأنّ الغاية لا تبرّر الوسيلة.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15970, 2485, 2, 'التزام الحكّام والمواطنين القيم الديمقراطيّة في السلوك يؤدّي إلى التراضي والتوافق. لكنّ ذلك لا ينفي إمكان حصول الخلاف والنزاع، وفي هذه الحال تقضي القيم الديمقراطيّة بتقبّل فكرة الخلاف وإدارته بين الأفراد والجماعات. وإذا أساء الحكّام استعمال السلطة يصبح التصدّي لهم مشروعاً وضروريّاً، مع بقاء الأساليب الديمقراطيّة الأهمّ لأنّ الغاية لا تبرّر الوسيلة.', 1, '2026-09-30 22:12:39', '2026-09-30 22:12:39'),
(15971, 2486, 1, 'الإيمان هو الاعتقاد بالله ورسله ووحيه. وتتّفق الأديان كلّها على إرساء قواعدها على التقوى، وتغليب الخير على الشرّ، وتزكية النفس من خلال تمرّسها بالقيم الرفيعة.', 1, '2026-09-30 22:12:40', '2026-09-30 22:12:40'),
(15972, 2486, 2, 'الإيمان هو الاعتقاد بالله ورسله ووحيه. وتتّفق الأديان كلّها على إرساء قواعدها على التقوى، وتغليب الخير على الشرّ، وتزكية النفس من خلال تمرّسها بالقيم الرفيعة.', 1, '2026-09-30 22:12:40', '2026-09-30 22:12:40'),
(15973, 2487, 1, 'من قيم الهندوسيّة (ثلاث ممّا يلي): القناعة، الطهارة، مقابلة الإساءة بالإحسان، الاستقامة، كبح جماح الحواسّ، الصبر، الصدق، اجتناب الغضب. الممرّ الأوسط عند بوذا سلوكٌ بين التلذّذ والزهد الخالص.', 1, '2026-09-30 22:12:40', '2026-09-30 22:12:40'),
(15974, 2487, 2, 'من قيم الهندوسيّة (ثلاث ممّا يلي): القناعة، الطهارة، مقابلة الإساءة بالإحسان، الاستقامة، كبح جماح الحواسّ، الصبر، الصدق، اجتناب الغضب. الممرّ الأوسط عند بوذا سلوكٌ بين التلذّذ والزهد الخالص.', 1, '2026-09-30 22:12:40', '2026-09-30 22:12:40'),
(15975, 2488, 1, 'أمثلة على التلاقي: مقابلة الإساءة بالإحسان في الهندوسيّة والإحسان في المسيحيّة والإسلام (فلنحسن إلى جميع الناس / لن تنالوا البرّ حتّى تنفقوا ممّا تحبّون)، وبرّ الوالدين (أكرم أباك وأمّك / فلا تقل لهما أفّ). ويدلّ التلاقي على أنّ الأديان كلّها تتّفق على التقوى وتغليب الخير على الشرّ وتزكية النفس، وهذا يدعونا في لبنان إلى احترام التنوّع.', 1, '2026-09-30 22:12:40', '2026-09-30 22:12:40'),
(15976, 2488, 2, 'أمثلة على التلاقي: مقابلة الإساءة بالإحسان في الهندوسيّة والإحسان في المسيحيّة والإسلام (فلنحسن إلى جميع الناس / لن تنالوا البرّ حتّى تنفقوا ممّا تحبّون)، وبرّ الوالدين (أكرم أباك وأمّك / فلا تقل لهما أفّ). ويدلّ التلاقي على أنّ الأديان كلّها تتّفق على التقوى وتغليب الخير على الشرّ وتزكية النفس، وهذا يدعونا في لبنان إلى احترام التنوّع.', 1, '2026-09-30 22:12:40', '2026-09-30 22:12:40'),
(15977, 2489, 1, 'الفلسفة محبّة الحكمة، وهي بحث عن الأسباب الأخيرة للوجود وسعي إلى بلوغ الحقيقة. دعا سقراط إلى ممارسة الفضيلة والابتعاد عن الرذيلة وإلى طلب العلم لأنّه فضيلة، والجهل رذيلة. عالم المثل عند أفلاطون عالم ثابت للحقائق، على رأسه الخير والحقّ والجمال.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15978, 2489, 2, 'الفلسفة محبّة الحكمة، وهي بحث عن الأسباب الأخيرة للوجود وسعي إلى بلوغ الحقيقة. دعا سقراط إلى ممارسة الفضيلة والابتعاد عن الرذيلة وإلى طلب العلم لأنّه فضيلة، والجهل رذيلة. عالم المثل عند أفلاطون عالم ثابت للحقائق، على رأسه الخير والحقّ والجمال.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15979, 2490, 1, 'تطوّرت قدرة الإنسان الماديّة بشكل هائل بفضل التقنيات الحديثة، فصار يواجه مسائل خطيرة كالموت الرحيم والهندسة الجينيّة والاستنساخ (النعجة دوللي). والقيم الأخلاقيّة تحدّد علاقات الإنسان بذاته ومع الآخرين، وبدونها يصبح البشر فريسة التناقض والكبرياء والأنانيّة ويصبح العالم مرتعاً للفوضى والشقاء، لذلك هي الموجِّه والضابط لسلوك الفرد والحاكم والجماعة.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15980, 2490, 2, 'تطوّرت قدرة الإنسان الماديّة بشكل هائل بفضل التقنيات الحديثة، فصار يواجه مسائل خطيرة كالموت الرحيم والهندسة الجينيّة والاستنساخ (النعجة دوللي). والقيم الأخلاقيّة تحدّد علاقات الإنسان بذاته ومع الآخرين، وبدونها يصبح البشر فريسة التناقض والكبرياء والأنانيّة ويصبح العالم مرتعاً للفوضى والشقاء، لذلك هي الموجِّه والضابط لسلوك الفرد والحاكم والجماعة.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15981, 2491, 1, 'الفلسفة العربيّة ركّزت على الزهد والتقوى وتطهير النفس، وتناولت حرّيّة الإنسان والتعاون ومساواة المرأة بالرجل وخُلُقيّة الحاكم، ومن فلاسفتها ابن رشد (أو الفارابي). والفلسفة الغربيّة نادت بالعدالة والحرّيّة والمساواة ونشرت الأفكار الديمقراطيّة، ومن مفكّريها مونتسكيو الذي نبّه إلى فصل السلطات (أو روسو). وقد أصبحت هذه القيم في صلب الإعلان العالمي لحقوق الإنسان.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15982, 2491, 2, 'الفلسفة العربيّة ركّزت على الزهد والتقوى وتطهير النفس، وتناولت حرّيّة الإنسان والتعاون ومساواة المرأة بالرجل وخُلُقيّة الحاكم، ومن فلاسفتها ابن رشد (أو الفارابي). والفلسفة الغربيّة نادت بالعدالة والحرّيّة والمساواة ونشرت الأفكار الديمقراطيّة، ومن مفكّريها مونتسكيو الذي نبّه إلى فصل السلطات (أو روسو). وقد أصبحت هذه القيم في صلب الإعلان العالمي لحقوق الإنسان.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15983, 2492, 1, 'الحقّ إمكانيّة أو سلطة أو امتياز يمنحه القانون. ويمارسه الشخص بوجوه لا تخالف القانون والنظام العامّ ولا تتعارض مع الأخلاق والآداب العامّة. مثال: مالك العقار المبنيّ يحقّ له أن يبيعه أو يؤجّره أو يستثمره، لكن لا يحقّ له أن يستعمله مستودعاً لموادّ ممنوعة كالمخدّرات.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15984, 2492, 2, 'الحقّ إمكانيّة أو سلطة أو امتياز يمنحه القانون. ويمارسه الشخص بوجوه لا تخالف القانون والنظام العامّ ولا تتعارض مع الأخلاق والآداب العامّة. مثال: مالك العقار المبنيّ يحقّ له أن يبيعه أو يؤجّره أو يستثمره، لكن لا يحقّ له أن يستعمله مستودعاً لموادّ ممنوعة كالمخدّرات.', 1, '2026-09-30 22:12:41', '2026-09-30 22:12:41'),
(15985, 2493, 1, 'في النزاع يرى كلّ طرف أنّ الحقّ معه، والقوّة والوعيد لا يحقّقان العدالة، لذلك لا يجوز للشخص أن يستوفي حقّه بنفسه بل بواسطة القضاء، ووظيفة القضاء الأساسيّة حماية حقوق الأفراد وحرّيّاتهم وتحقيق العدالة بين المتنازعين. أمّا حقوق المجتمع في الأمن والاستقرار والتقدّم فتُحمى برفع دعوى الحقّ العامّ ضدّ منتهكيها، بمعاونة هيئات قضائيّة وأمنيّة تتولّى الإبلاغ والملاحقة وجمع الأدلّة والتحقيق.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15986, 2493, 2, 'في النزاع يرى كلّ طرف أنّ الحقّ معه، والقوّة والوعيد لا يحقّقان العدالة، لذلك لا يجوز للشخص أن يستوفي حقّه بنفسه بل بواسطة القضاء، ووظيفة القضاء الأساسيّة حماية حقوق الأفراد وحرّيّاتهم وتحقيق العدالة بين المتنازعين. أمّا حقوق المجتمع في الأمن والاستقرار والتقدّم فتُحمى برفع دعوى الحقّ العامّ ضدّ منتهكيها، بمعاونة هيئات قضائيّة وأمنيّة تتولّى الإبلاغ والملاحقة وجمع الأدلّة والتحقيق.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15987, 2494, 1, 'لا يحقّ لي ذلك. فبناء السور حقّ لي بصفتي مالكاً، لكنّ ممارسة الحقّ مقيّدة بحدود القانون والنظام، ولا يجوز أن أسيء استعمال حقّي فأُلحق ضرراً بغيري، وحجب النور عن الجار ضرر به.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15988, 2494, 2, 'لا يحقّ لي ذلك. فبناء السور حقّ لي بصفتي مالكاً، لكنّ ممارسة الحقّ مقيّدة بحدود القانون والنظام، ولا يجوز أن أسيء استعمال حقّي فأُلحق ضرراً بغيري، وحجب النور عن الجار ضرر به.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15989, 2495, 1, 'استقلاليّة القضاء تعني أنّ القضاء سلطة مستقلّة تجاه السلطات الأخرى في تحقيق الدعاوى والحكم فيها، فلا يحقّ للسلطتين التشريعيّة والإجرائيّة ولا لأيّ جهة نافذة أن تتدخّل في شؤون المحاكم، والقضاة لا يستجيبون إلّا لنداء القانون والعدالة والضمير. من النصوص: الدستور اللبنانيّ، والمادّة الأولى من قانون أصول المحاكمات المدنيّة، وقانون تنظيم القضاء العدليّ (نصّان منها).', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15990, 2495, 2, 'استقلاليّة القضاء تعني أنّ القضاء سلطة مستقلّة تجاه السلطات الأخرى في تحقيق الدعاوى والحكم فيها، فلا يحقّ للسلطتين التشريعيّة والإجرائيّة ولا لأيّ جهة نافذة أن تتدخّل في شؤون المحاكم، والقضاة لا يستجيبون إلّا لنداء القانون والعدالة والضمير. من النصوص: الدستور اللبنانيّ، والمادّة الأولى من قانون أصول المحاكمات المدنيّة، وقانون تنظيم القضاء العدليّ (نصّان منها).', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15991, 2496, 1, 'القاعدة الأولى: لا يجوز الجمع بين الوظيفة القضائيّة والوظائف العامّة أو أيّ مهنة أو عمل مأجور، باستثناء التدريس في الجامعات والمعاهد العليا. القاعدة الثانية: كلّ قاضٍ يرشّح نفسه للانتخابات النيابيّة أو البلديّة يُفصل حكماً عن سلك القضاء ولا يجوز أن يُعيَّن بعدها في وظيفة قضائيّة. وتضمن الدولة التعويض لأنّ أحكام القضاة لا ترضي كلّ الأطراف، فتكون أحياناً سبباً لتعرّضهم للأذى.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15992, 2496, 2, 'القاعدة الأولى: لا يجوز الجمع بين الوظيفة القضائيّة والوظائف العامّة أو أيّ مهنة أو عمل مأجور، باستثناء التدريس في الجامعات والمعاهد العليا. القاعدة الثانية: كلّ قاضٍ يرشّح نفسه للانتخابات النيابيّة أو البلديّة يُفصل حكماً عن سلك القضاء ولا يجوز أن يُعيَّن بعدها في وظيفة قضائيّة. وتضمن الدولة التعويض لأنّ أحكام القضاة لا ترضي كلّ الأطراف، فتكون أحياناً سبباً لتعرّضهم للأذى.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15993, 2497, 1, 'المحافظة على سرّ المهنة فلا يفشي سرّاً عرفه عن طريق مهنته ولو بعد انتهاء الوكالة؛ ألّا يشهد ضدّ موكّله في الدعوى التي يتولّى الوكالة فيها؛ ألّا يقبل الوكالة عن خصم موكّله أو يقدّم له أيّ معونة ولو على سبيل الرأي؛ المحافظة على آداب المهنة وتقاليدها والامتناع عن أيّ تصرّف يحطّ من الثقة به؛ ارتداء رداء المحامين الخاصّ عند المثول أمام المحاكم (ثلاثة منها).', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15994, 2497, 2, 'المحافظة على سرّ المهنة فلا يفشي سرّاً عرفه عن طريق مهنته ولو بعد انتهاء الوكالة؛ ألّا يشهد ضدّ موكّله في الدعوى التي يتولّى الوكالة فيها؛ ألّا يقبل الوكالة عن خصم موكّله أو يقدّم له أيّ معونة ولو على سبيل الرأي؛ المحافظة على آداب المهنة وتقاليدها والامتناع عن أيّ تصرّف يحطّ من الثقة به؛ ارتداء رداء المحامين الخاصّ عند المثول أمام المحاكم (ثلاثة منها).', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15995, 2498, 1, '1- تقام الدعوى أمام المحكمة المختصّة بورقة استحضار. 2- يردّ المدّعى عليه بلائحة جوابيّة وللمدّعي الردّ على الردّ. 3- المناقشات ثمّ الحكم باسم الشعب اللبناني بعد مداولة سرّيّة. 4- الاستئناف لخاسر الدعوى. 5- الطعن تمييزاً إذا توافرت شروط النقض. 6- التنفيذ بواسطة دائرة الإجراء. ويقع عبء الإثبات على المدّعي.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15996, 2498, 2, '1- تقام الدعوى أمام المحكمة المختصّة بورقة استحضار. 2- يردّ المدّعى عليه بلائحة جوابيّة وللمدّعي الردّ على الردّ. 3- المناقشات ثمّ الحكم باسم الشعب اللبناني بعد مداولة سرّيّة. 4- الاستئناف لخاسر الدعوى. 5- الطعن تمييزاً إذا توافرت شروط النقض. 6- التنفيذ بواسطة دائرة الإجراء. ويقع عبء الإثبات على المدّعي.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15997, 2499, 1, 'تقوم المحاكمة على مبادئ العلنيّة (بحضور الجمهور إلّا حفظاً للنظام العام والآداب العامّة) والشفاهيّة (كلّ المحاضر والمستندات موضوع نقاش) والوجاهيّة (بحضور أطراف الدعوى)، ومخالفتها تبطل الإجراءات. ومن الضمانات أيضاً ضرورة وجود المحامي، وعدم دخول المنازل إلّا بإذن النيابة العامّة أو في الجرم المشهود، ويمين الشاهد، وحقّ الطعن. وهذه الأصول تكفل إحقاق الحقّ وإدانة المذنب وحماية البريء.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15998, 2499, 2, 'تقوم المحاكمة على مبادئ العلنيّة (بحضور الجمهور إلّا حفظاً للنظام العام والآداب العامّة) والشفاهيّة (كلّ المحاضر والمستندات موضوع نقاش) والوجاهيّة (بحضور أطراف الدعوى)، ومخالفتها تبطل الإجراءات. ومن الضمانات أيضاً ضرورة وجود المحامي، وعدم دخول المنازل إلّا بإذن النيابة العامّة أو في الجرم المشهود، ويمين الشاهد، وحقّ الطعن. وهذه الأصول تكفل إحقاق الحقّ وإدانة المذنب وحماية البريء.', 1, '2026-09-30 22:12:42', '2026-09-30 22:12:42'),
(15999, 2500, 1, 'من يخسر دعواه أمام محكمة الدرجة الأولى يحقّ له أن يستأنف الحكم، فتصدّقه محكمة الاستئناف أو تفسخه. والهدف توخّي العدالة، وتدارك أخطاء الأحكام في تطبيق القانون وتفسيره.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16000, 2500, 2, 'من يخسر دعواه أمام محكمة الدرجة الأولى يحقّ له أن يستأنف الحكم، فتصدّقه محكمة الاستئناف أو تفسخه. والهدف توخّي العدالة، وتدارك أخطاء الأحكام في تطبيق القانون وتفسيره.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16001, 2501, 1, 'لأنّ التشريع ينظّم علاقات الأفراد وعلاقاتهم بالسلطة التي تحكمهم، وفي الأنظمة الديمقراطيّة لا شرعيّة لأيّ تشريع إن لم يكن صادراً عن الإرادة الشعبيّة، فمصدر الشرعيّة هو الشعب. لذلك لا بدّ من أن يكون واضع التشريع منبثقاً عن إرادة الشعب، وإلّا فقد التشريع شرعيّته.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16002, 2501, 2, 'لأنّ التشريع ينظّم علاقات الأفراد وعلاقاتهم بالسلطة التي تحكمهم، وفي الأنظمة الديمقراطيّة لا شرعيّة لأيّ تشريع إن لم يكن صادراً عن الإرادة الشعبيّة، فمصدر الشرعيّة هو الشعب. لذلك لا بدّ من أن يكون واضع التشريع منبثقاً عن إرادة الشعب، وإلّا فقد التشريع شرعيّته.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16003, 2502, 1, 'يستمدّ التشريع شرعيّته من شرطين: أن تكون السلطة التي تضعه شرعيّة، وأن يكون النصّ الصادر عنها غير مخالف للنصوص التي تسمو عليه (القانون لا يخالف الدستور، والنظام لا يخالف القانون). ويتوقّف استمرار تطبيق القوانين والأنظمة على تحقيقها العدالة والمصلحة العامّة وملاءمتها الأوضاع والظروف، فإذا لم تعد كذلك وجب تعديلها أو إلغاؤها.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16004, 2502, 2, 'يستمدّ التشريع شرعيّته من شرطين: أن تكون السلطة التي تضعه شرعيّة، وأن يكون النصّ الصادر عنها غير مخالف للنصوص التي تسمو عليه (القانون لا يخالف الدستور، والنظام لا يخالف القانون). ويتوقّف استمرار تطبيق القوانين والأنظمة على تحقيقها العدالة والمصلحة العامّة وملاءمتها الأوضاع والظروف، فإذا لم تعد كذلك وجب تعديلها أو إلغاؤها.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16005, 2503, 1, 'تعدّ الحكومة مشروع القانون، فيُدرس ويناقش في اللجان النيابيّة المختصّة. ومجلس النوّاب سيّد نفسه: قد يوافق عليه كما ورد، أو يدخل عليه تعديلات، أو يردّه. عندما يصدّقه المجلس يعاد إلى الحكومة لإصداره، فيوقّعه رئيس الجمهوريّة ورئيس الحكومة بعد مروره في مجلس الوزراء، ثمّ يُنشر.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16006, 2503, 2, 'تعدّ الحكومة مشروع القانون، فيُدرس ويناقش في اللجان النيابيّة المختصّة. ومجلس النوّاب سيّد نفسه: قد يوافق عليه كما ورد، أو يدخل عليه تعديلات، أو يردّه. عندما يصدّقه المجلس يعاد إلى الحكومة لإصداره، فيوقّعه رئيس الجمهوريّة ورئيس الحكومة بعد مروره في مجلس الوزراء، ثمّ يُنشر.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16007, 2504, 1, 'العقد غير صحيح لسببين: موضوع العقد غير موجود لأنّ السيارة احترقت قبل التعاقد، والموضوع يجب أن يكون موجوداً؛ والأهليّة القانونية غير متوافرة لأنّ البائع لم يتمّ الثامنة عشرة، والمرء يكون أهلاً للتعاقد إذا أتمّ الثامنة عشرة وكان راشداً متمتّعاً بقواه العقلية.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16008, 2504, 2, 'العقد غير صحيح لسببين: موضوع العقد غير موجود لأنّ السيارة احترقت قبل التعاقد، والموضوع يجب أن يكون موجوداً؛ والأهليّة القانونية غير متوافرة لأنّ البائع لم يتمّ الثامنة عشرة، والمرء يكون أهلاً للتعاقد إذا أتمّ الثامنة عشرة وكان راشداً متمتّعاً بقواه العقلية.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16009, 2505, 1, 'ليس كلّ اتفاق عقداً: العقد اتفاق يُرتّب التزامات على أطرافه (كالاتفاق مع السائق)، أمّا الاتفاق العادي كالاتفاق مع الأصدقاء على نشاط فلا يُعدّ عقداً وإن وجب احترامه. الالتزام الطبيعي لا يمكن المطالبة بتنفيذه ولا الادّعاء به أمام القضاء، مثل شقيق ينفق على شقيقه الأصغر ثمّ يتوقّف. الالتزام المدني يمكن المطالبة بتنفيذه أمام القضاء، مثل قرض من مصرف يحقّ للمصرف أن يقاضي المقترض لإلزامه بالدفع.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16010, 2505, 2, 'ليس كلّ اتفاق عقداً: العقد اتفاق يُرتّب التزامات على أطرافه (كالاتفاق مع السائق)، أمّا الاتفاق العادي كالاتفاق مع الأصدقاء على نشاط فلا يُعدّ عقداً وإن وجب احترامه. الالتزام الطبيعي لا يمكن المطالبة بتنفيذه ولا الادّعاء به أمام القضاء، مثل شقيق ينفق على شقيقه الأصغر ثمّ يتوقّف. الالتزام المدني يمكن المطالبة بتنفيذه أمام القضاء، مثل قرض من مصرف يحقّ للمصرف أن يقاضي المقترض لإلزامه بالدفع.', 1, '2026-09-30 22:12:43', '2026-09-30 22:12:43'),
(16011, 2506, 1, 'يلجأ المتعاقدون إلى الكاتب العدل لتوثيق عقودهم نظراً لأهمية الحقوق وضرورة احترامها وتنفيذها، فالتوثيق يحفظ الحقوق. ويقسم قبل مباشرة عمله أن يحافظ على سرّ مهنته وآدابها، وأن يقوم بأعمالها بأمانة، وأن يتقيّد بقوانينها وأنظمتها، وأن يتصرّف تصرّفاً يوحي الثقة والاحترام.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(16012, 2506, 2, 'يلجأ المتعاقدون إلى الكاتب العدل لتوثيق عقودهم نظراً لأهمية الحقوق وضرورة احترامها وتنفيذها، فالتوثيق يحفظ الحقوق. ويقسم قبل مباشرة عمله أن يحافظ على سرّ مهنته وآدابها، وأن يقوم بأعمالها بأمانة، وأن يتقيّد بقوانينها وأنظمتها، وأن يتصرّف تصرّفاً يوحي الثقة والاحترام.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16013, 2507, 1, 'نعم، أداؤه سليم. الدليل الأوّل: أصلح السيّارة وأعادها إلى وضعها الطبيعيّ (إتقان العمل). الثاني: صارح صاحبها بأنّ العطل بسيط فلم يستغلّه. الثالث: احتفظ بالقطعة المسبّبة للعطل ليثبت صدقه. وسلوكه يجسّد قيمتي النزاهة والاستقامة، واحترام الآخر.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16014, 2507, 2, 'نعم، أداؤه سليم. الدليل الأوّل: أصلح السيّارة وأعادها إلى وضعها الطبيعيّ (إتقان العمل). الثاني: صارح صاحبها بأنّ العطل بسيط فلم يستغلّه. الثالث: احتفظ بالقطعة المسبّبة للعطل ليثبت صدقه. وسلوكه يجسّد قيمتي النزاهة والاستقامة، واحترام الآخر.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16015, 2508, 1, 'خلقيّة العمل مهما تطوّرت لم تشكّل ضمانة كافية للأداء السليم لأنّها تبقى قاصرة عن الإحاطة بمختلف جوانب المهنة. لذلك وضعت المجتمعات الحديثة نصوصاً وشرائع ترعى الأداء في مهن كثيرة، فيصبح الأداء إلزامياً ويخضع للتقييم ولمحاسبة هيئات المجتمع الإداريّة والقضائيّة لا للمحاسبة الذاتيّة فقط. مثال: معاقبة الغشّ الذي يضرّ بالصحّة العامّة بالحبس والغرامة وإقفال المحلّ، أو قانون الآداب الطبّيّة.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16016, 2508, 2, 'خلقيّة العمل مهما تطوّرت لم تشكّل ضمانة كافية للأداء السليم لأنّها تبقى قاصرة عن الإحاطة بمختلف جوانب المهنة. لذلك وضعت المجتمعات الحديثة نصوصاً وشرائع ترعى الأداء في مهن كثيرة، فيصبح الأداء إلزامياً ويخضع للتقييم ولمحاسبة هيئات المجتمع الإداريّة والقضائيّة لا للمحاسبة الذاتيّة فقط. مثال: معاقبة الغشّ الذي يضرّ بالصحّة العامّة بالحبس والغرامة وإقفال المحلّ، أو قانون الآداب الطبّيّة.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16017, 2509, 1, 'خلقيّة العمل هي مجموعة الصفات والقيم التي يلتزمها صاحب المهنة في عمله. ومن العوامل: الكفاية والخبرة، إتقان العمل، حسن التعامل مع الآخر واحترامه وعدم استغلاله، الالتزام بالمواعيد والعهود، توخّي المصلحة العامّة، مراعاة الحالات الإنسانيّة (أربعة منها).', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16018, 2509, 2, 'خلقيّة العمل هي مجموعة الصفات والقيم التي يلتزمها صاحب المهنة في عمله. ومن العوامل: الكفاية والخبرة، إتقان العمل، حسن التعامل مع الآخر واحترامه وعدم استغلاله، الالتزام بالمواعيد والعهود، توخّي المصلحة العامّة، مراعاة الحالات الإنسانيّة (أربعة منها).', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16019, 2510, 1, 'لا يتوافق. فالموظّف المرتشي يخالف مبدأ استيحاء المصلحة العامّة، ويخالف حظر التماس الهدايا أو قبولها (وقد يخالف أيضاً الاستقامة والتجرّد). والنتيجة أنّه يسخّر وظيفته لمصلحة خاصّة فيلحق الضرر بالمجتمع، ولا يستقيم وضعه إلّا بالتزام المبادئ الأخلاقيّة.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16020, 2510, 2, 'لا يتوافق. فالموظّف المرتشي يخالف مبدأ استيحاء المصلحة العامّة، ويخالف حظر التماس الهدايا أو قبولها (وقد يخالف أيضاً الاستقامة والتجرّد). والنتيجة أنّه يسخّر وظيفته لمصلحة خاصّة فيلحق الضرر بالمجتمع، ولا يستقيم وضعه إلّا بالتزام المبادئ الأخلاقيّة.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16021, 2511, 1, 'حين تُؤدّى مهامّ الوظيفة العامّة بأمانة وإخلاص تتمكّن الدولة من تحقيق غايتها: تأمين الخدمات للجميع، وتحقيق الأمن والاستقرار، وحفظ الحقوق. ولها دور في تحقيق السلم الأهليّ لأنّ كلّ مواطن يشعر أنّ إدارات الدولة مفتوحة للجميع وتسهر على مصالحه دون تمييز.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16022, 2511, 2, 'حين تُؤدّى مهامّ الوظيفة العامّة بأمانة وإخلاص تتمكّن الدولة من تحقيق غايتها: تأمين الخدمات للجميع، وتحقيق الأمن والاستقرار، وحفظ الحقوق. ولها دور في تحقيق السلم الأهليّ لأنّ كلّ مواطن يشعر أنّ إدارات الدولة مفتوحة للجميع وتسهر على مصالحه دون تمييز.', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16023, 2512, 1, 'استيحاء المصلحة العامّة، السهر على تطبيق الأنظمة والقوانين، العمل بالاستقامة والإخلاص والتجرّد، تنفيذ الأوامر، الحفاظ على سرّ المهنة (ثلاثة منها).', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16024, 2512, 2, 'استيحاء المصلحة العامّة، السهر على تطبيق الأنظمة والقوانين، العمل بالاستقامة والإخلاص والتجرّد، تنفيذ الأوامر، الحفاظ على سرّ المهنة (ثلاثة منها).', 1, '2026-09-30 22:12:44', '2026-09-30 22:12:44'),
(16025, 2513, 1, 'لأنّ المهنة تحتاج أيضاً إلى اكتساب الكفاية العلميّة المتخصّصة، وإلى تنمية الخبرة من خلال الممارسة المتأنّية والاستعانة بالمراجع والقيام بالدراسات والبحوث. والعلوم تتطوّر ويخضع كثير من المفاهيم القديمة للتبديل أو التعديل، فيواكبها العامل بالاطّلاع على المجلّات العلميّة، والاشتراك في المؤتمرات المهنيّة، والتعرّف إلى التشريعات المستحدثة.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16026, 2513, 2, 'لأنّ المهنة تحتاج أيضاً إلى اكتساب الكفاية العلميّة المتخصّصة، وإلى تنمية الخبرة من خلال الممارسة المتأنّية والاستعانة بالمراجع والقيام بالدراسات والبحوث. والعلوم تتطوّر ويخضع كثير من المفاهيم القديمة للتبديل أو التعديل، فيواكبها العامل بالاطّلاع على المجلّات العلميّة، والاشتراك في المؤتمرات المهنيّة، والتعرّف إلى التشريعات المستحدثة.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16027, 2514, 1, 'من النتائج: انحراف الناشئة، تفشّي الأمراض والأوبئة وصعوبة معالجتها، ضياع الحقوق، توقّف الازدهار العمرانيّ، فقدان الحرّيّات العامّة، ظهور الفرقة والانقسامات بين المواطنين (أربع منها). ويُلاحَق المخالف من خلال المجالس التأديبيّة التي تشرف عليها النقابات المهنيّة وتتراوح عقوباتها بين التنبيه والمنع من مزاولة المهنة، ومن خلال المحاكم الجزائيّة وعقوباتها الغرامات والحبس.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16028, 2514, 2, 'من النتائج: انحراف الناشئة، تفشّي الأمراض والأوبئة وصعوبة معالجتها، ضياع الحقوق، توقّف الازدهار العمرانيّ، فقدان الحرّيّات العامّة، ظهور الفرقة والانقسامات بين المواطنين (أربع منها). ويُلاحَق المخالف من خلال المجالس التأديبيّة التي تشرف عليها النقابات المهنيّة وتتراوح عقوباتها بين التنبيه والمنع من مزاولة المهنة، ومن خلال المحاكم الجزائيّة وعقوباتها الغرامات والحبس.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16029, 2515, 1, 'لأنّ المحاماة خدمة ذات طابع إنسانيّ لا عمليّة تجاريّة، والدعاية والسمسرة تعيبان الأداء السليم لأنّهما تربطان العمل بالربح. والقيمة الأخلاقيّة هي تقديم الخدمة نصرةً للقيم الإنسانيّة والديمقراطيّة، ويؤكّد ذلك أنّ القانون يحظر على المحامي السعي إلى اكتساب الزبائن.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16030, 2515, 2, 'لأنّ المحاماة خدمة ذات طابع إنسانيّ لا عمليّة تجاريّة، والدعاية والسمسرة تعيبان الأداء السليم لأنّهما تربطان العمل بالربح. والقيمة الأخلاقيّة هي تقديم الخدمة نصرةً للقيم الإنسانيّة والديمقراطيّة، ويؤكّد ذلك أنّ القانون يحظر على المحامي السعي إلى اكتساب الزبائن.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16031, 2516, 1, 'المقوّمات الثلاثة: المعرفة بأصول المهنة، وإتقان العمل، والصدق في التعامل. والتعامل غير الصادق (إخلاف المواعيد، استغلال حاجات الناس في الحالات الاضطراريّة) يُفقد صاحب المهنة ثقة الناس، لأنّ ثقة المواطنين لا تُكتسب إلّا بالتعامل الصادق قولاً وفعلاً، ومن يفقد الثقة ينتهي إلى الفشل.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16032, 2516, 2, 'المقوّمات الثلاثة: المعرفة بأصول المهنة، وإتقان العمل، والصدق في التعامل. والتعامل غير الصادق (إخلاف المواعيد، استغلال حاجات الناس في الحالات الاضطراريّة) يُفقد صاحب المهنة ثقة الناس، لأنّ ثقة المواطنين لا تُكتسب إلّا بالتعامل الصادق قولاً وفعلاً، ومن يفقد الثقة ينتهي إلى الفشل.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16033, 2517, 1, 'الرابح الحقيقي هو صانع المفاتيح، فقد أتقن عمله فكسب السمعة الطيّبة وثقة الناس، وهذا هو الربح الدائم. أمّا العامل الثاني فأخذ أجراً مرتفعاً، لكنّ أعطالاً ظهرت في عمله فاستعان زبونه بعامل آخر لإصلاح ما أفسده، فخسر ثقته.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16034, 2517, 2, 'الرابح الحقيقي هو صانع المفاتيح، فقد أتقن عمله فكسب السمعة الطيّبة وثقة الناس، وهذا هو الربح الدائم. أمّا العامل الثاني فأخذ أجراً مرتفعاً، لكنّ أعطالاً ظهرت في عمله فاستعان زبونه بعامل آخر لإصلاح ما أفسده، فخسر ثقته.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16035, 2518, 1, 'يساهمون في تنفيذ مشاريع الخطط الإنمائيّة، ويقومون بعمليّات البناء الكبيرة والصغيرة وبصيانتها، ويتركون أعمالاً خالدة من أبنية وجسور وأبراج وتماثيل وزخارف إذا أتقنوا مهنهم وأخلصوا لها.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16036, 2518, 2, 'يساهمون في تنفيذ مشاريع الخطط الإنمائيّة، ويقومون بعمليّات البناء الكبيرة والصغيرة وبصيانتها، ويتركون أعمالاً خالدة من أبنية وجسور وأبراج وتماثيل وزخارف إذا أتقنوا مهنهم وأخلصوا لها.', 1, '2026-09-30 22:12:45', '2026-09-30 22:12:45'),
(16037, 2519, 1, 'من أشكال الإخلال: الاتّجار بلحوم فاسدة أو بيع منتجات سامّة؛ تسويق بضاعة انتهت مدّة صلاحيّتها؛ إخفاء حقيقة السلعة في الوزن أو الحجم أو بلد المنشأ أو النوع؛ عدم الوفاء بالالتزامات ومواعيد الإنتاج والتسليم. وأبرز الخطر أن يمرض المستهلك.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16038, 2519, 2, 'من أشكال الإخلال: الاتّجار بلحوم فاسدة أو بيع منتجات سامّة؛ تسويق بضاعة انتهت مدّة صلاحيّتها؛ إخفاء حقيقة السلعة في الوزن أو الحجم أو بلد المنشأ أو النوع؛ عدم الوفاء بالالتزامات ومواعيد الإنتاج والتسليم. وأبرز الخطر أن يمرض المستهلك.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16039, 2520, 1, 'الخلقيّتان معاً. فعلى ربّ العمل الصدق في السلعة والوفاء بالتزاماته وتأمين حقوق العمّال (إجازات، أجور عادلة، رعاية صحّيّة، وسائل وقاية)، وعلى العامل الالتزام بالنظام العام والانضباط واحترام أصول العمل، والهدف سلعة تحوز المواصفات الفنيّة. والخلقيّتان متكاملتان، فلا ينجح المصنع بإحداهما دون الأخرى.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16040, 2520, 2, 'الخلقيّتان معاً. فعلى ربّ العمل الصدق في السلعة والوفاء بالتزاماته وتأمين حقوق العمّال (إجازات، أجور عادلة، رعاية صحّيّة، وسائل وقاية)، وعلى العامل الالتزام بالنظام العام والانضباط واحترام أصول العمل، والهدف سلعة تحوز المواصفات الفنيّة. والخلقيّتان متكاملتان، فلا ينجح المصنع بإحداهما دون الأخرى.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16041, 2521, 1, 'لا أشتري البضاعة الفاسدة، وأنبّه صاحب المحلّ إلى المخالفة، وأبلّغ الجهة المختصّة كالبلديّة التي تراقب أعمال الإنتاج والتجارة. ومن العقوبات: مصادرة البضاعة الفاسدة، وإقفال المؤسّسة أو المحلّ موقّتاً أو نهائيّاً.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16042, 2521, 2, 'لا أشتري البضاعة الفاسدة، وأنبّه صاحب المحلّ إلى المخالفة، وأبلّغ الجهة المختصّة كالبلديّة التي تراقب أعمال الإنتاج والتجارة. ومن العقوبات: مصادرة البضاعة الفاسدة، وإقفال المؤسّسة أو المحلّ موقّتاً أو نهائيّاً.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16043, 2522, 1, 'لم يعد التضامن العربي وليد المشاعر وحدها، فالتكامل بين إمكانات الدول العربيّة وحاجاتها ينتج واقعاً جديداً يستفيد منه جميع العرب. مثال: تعاون الدول العربيّة المالكة رؤوس الأموال مع الدول ذات الإمكانات الزراعيّة كالسودان، ما يسمح بتحقيق خطوات على طريق الأمن الغذائي.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16044, 2522, 2, 'لم يعد التضامن العربي وليد المشاعر وحدها، فالتكامل بين إمكانات الدول العربيّة وحاجاتها ينتج واقعاً جديداً يستفيد منه جميع العرب. مثال: تعاون الدول العربيّة المالكة رؤوس الأموال مع الدول ذات الإمكانات الزراعيّة كالسودان، ما يسمح بتحقيق خطوات على طريق الأمن الغذائي.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16045, 2523, 1, 'الضرورات: تحقيق الرخاء الاقتصادي والأمن وتنمية عربيّة على قاعدة التقدّم العلمي؛ التحوّل من دول مبعثرة إلى كتلة سياسيّة واقتصاديّة لها وزنها في الحرب والمفاوضات؛ تسريع الإنجازات في الرعاية الصحّيّة والتعليميّة ومكافحة الأمّيّة ورفع مستوى المعيشة ومحاربة الفقر والبطالة. أمّا سياسة الانفراد فتشتّت القوى العربيّة، وتسمح للأعداء بتمرير خططهم، وتُحدث نزاعات عربيّة عربيّة قد تصل إلى حروب أهليّة، وتؤدّي إلى تعدّد المسارات وضعف المواجهة.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16046, 2523, 2, 'الضرورات: تحقيق الرخاء الاقتصادي والأمن وتنمية عربيّة على قاعدة التقدّم العلمي؛ التحوّل من دول مبعثرة إلى كتلة سياسيّة واقتصاديّة لها وزنها في الحرب والمفاوضات؛ تسريع الإنجازات في الرعاية الصحّيّة والتعليميّة ومكافحة الأمّيّة ورفع مستوى المعيشة ومحاربة الفقر والبطالة. أمّا سياسة الانفراد فتشتّت القوى العربيّة، وتسمح للأعداء بتمرير خططهم، وتُحدث نزاعات عربيّة عربيّة قد تصل إلى حروب أهليّة، وتؤدّي إلى تعدّد المسارات وضعف المواجهة.', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16047, 2524, 1, 'التضامن العربي هو العمل على توثيق الصلات بين الدول والشعوب العربيّة حمايةً للمصالح العربيّة، في المجالات السياسيّة والدفاعيّة والاقتصاديّة. ومن مرتكزاته: الموقع الجغرافي، اللغة والتاريخ، اعتبارات الأمن القومي، المصالح المشتركة، التحدّيات الراهنة، الأماني والطموحات المستقبليّة (ثلاثة منها).', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16048, 2524, 2, 'التضامن العربي هو العمل على توثيق الصلات بين الدول والشعوب العربيّة حمايةً للمصالح العربيّة، في المجالات السياسيّة والدفاعيّة والاقتصاديّة. ومن مرتكزاته: الموقع الجغرافي، اللغة والتاريخ، اعتبارات الأمن القومي، المصالح المشتركة، التحدّيات الراهنة، الأماني والطموحات المستقبليّة (ثلاثة منها).', 1, '2026-09-30 22:12:46', '2026-09-30 22:12:46'),
(16049, 2525, 1, 'السوق المشتركة تهدف إلى تحرير التجارة في كافّة السلع ذات المنشأ العربيّ (حرّيّة التجارة العربيّة)، فتكاملها أوسع، ومثالها منطقة التجارة الحرّة العربيّة الكبرى. أمّا المشروع المشترك فوسيلة لتكامل جزئيّ لأنّه لا يمسّ إلّا جزءاً من الاقتصاد، ومثاله الشركة العامّة للشرق في الزراعة أو مشروع الربط الكهربائيّ.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16050, 2525, 2, 'السوق المشتركة تهدف إلى تحرير التجارة في كافّة السلع ذات المنشأ العربيّ (حرّيّة التجارة العربيّة)، فتكاملها أوسع، ومثالها منطقة التجارة الحرّة العربيّة الكبرى. أمّا المشروع المشترك فوسيلة لتكامل جزئيّ لأنّه لا يمسّ إلّا جزءاً من الاقتصاد، ومثاله الشركة العامّة للشرق في الزراعة أو مشروع الربط الكهربائيّ.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16051, 2526, 1, 'لأنّها هدف عربيّ يوفّر مزايا اقتصاديّة متعدّدة: تحقّق حرّيّة التجارة العربيّة، وتوسّع السوق لتشمل ملايين العرب، وتعزّز الأمن الاقتصاديّ العربيّ ثمّ الأمن القوميّ. وتزداد أهمّيّتها في ظلّ النظام العالميّ الجديد الذي طُرح بعد انتهاء الحرب الباردة وزوال الاتّحاد السوفياتيّ.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16052, 2526, 2, 'لأنّها هدف عربيّ يوفّر مزايا اقتصاديّة متعدّدة: تحقّق حرّيّة التجارة العربيّة، وتوسّع السوق لتشمل ملايين العرب، وتعزّز الأمن الاقتصاديّ العربيّ ثمّ الأمن القوميّ. وتزداد أهمّيّتها في ظلّ النظام العالميّ الجديد الذي طُرح بعد انتهاء الحرب الباردة وزوال الاتّحاد السوفياتيّ.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16053, 2527, 1, 'الاقتصاد: منطقة التجارة الحرّة العربيّة الكبرى. الطاقة: الربط الكهربائيّ بين مصر والأردن. الاتّصالات: القمر الصناعيّ العربيّ (خدمات الهاتف والبثّ التلفزيونيّ). الثقافة: شبكة لمعلومات التراث المخطوط وفهرسة المخطوطات. (ثلاثة منها في مجالات مختلفة).', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16054, 2527, 2, 'الاقتصاد: منطقة التجارة الحرّة العربيّة الكبرى. الطاقة: الربط الكهربائيّ بين مصر والأردن. الاتّصالات: القمر الصناعيّ العربيّ (خدمات الهاتف والبثّ التلفزيونيّ). الثقافة: شبكة لمعلومات التراث المخطوط وفهرسة المخطوطات. (ثلاثة منها في مجالات مختلفة).', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16055, 2528, 1, '1- شارك في تأسيس جامعة الدول العربيّة (من الدول السبع المؤسِّسة) ووقّع ميثاقها. 2- دافع عن الحقوق العربيّة مباشرة، كما في معركة المالكيّة، ودافع رؤساؤه (فرنجيّة، الهراوي) عن الحقّ العربيّ في الأمم المتّحدة. 3- استقبل اللاجئين الفلسطينيّين وساند المقاومة الفلسطينيّة. ويصحّ أيضاً: التزام المقاطعة العربيّة لإسرائيل، مساندة الجزائر ومصر، توقيع المواثيق كمعاهدة الدفاع العربيّ المشترك، استضافة المكاتب والمؤتمرات.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16056, 2528, 2, '1- شارك في تأسيس جامعة الدول العربيّة (من الدول السبع المؤسِّسة) ووقّع ميثاقها. 2- دافع عن الحقوق العربيّة مباشرة، كما في معركة المالكيّة، ودافع رؤساؤه (فرنجيّة، الهراوي) عن الحقّ العربيّ في الأمم المتّحدة. 3- استقبل اللاجئين الفلسطينيّين وساند المقاومة الفلسطينيّة. ويصحّ أيضاً: التزام المقاطعة العربيّة لإسرائيل، مساندة الجزائر ومصر، توقيع المواثيق كمعاهدة الدفاع العربيّ المشترك، استضافة المكاتب والمؤتمرات.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16057, 2529, 1, 'دليل سياسيّ: دعم العرب لبنان في معركة الاستقلال بالبيانات والتظاهرات والإضرابات والمطالبة بجلاء الجيوش الأجنبيّة، وآزروه في الأمم المتّحدة بوجه الاعتداءات الإسرائيليّة. دليل أمنيّ: ساعدوا على إعادة السلام عبر قمّة الدار البيضاء ومؤتمر الطائف ووثيقة الوفاق الوطنيّ. دليل اقتصاديّ: الاقتصاد اللبنانيّ يتنفّس برئة عربيّة (أسواق الصادرات، العمل في الدول العربيّة، المساعدات). والعمل المشترك عنصر قوّة وأداة حماية للبنان.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16058, 2529, 2, 'دليل سياسيّ: دعم العرب لبنان في معركة الاستقلال بالبيانات والتظاهرات والإضرابات والمطالبة بجلاء الجيوش الأجنبيّة، وآزروه في الأمم المتّحدة بوجه الاعتداءات الإسرائيليّة. دليل أمنيّ: ساعدوا على إعادة السلام عبر قمّة الدار البيضاء ومؤتمر الطائف ووثيقة الوفاق الوطنيّ. دليل اقتصاديّ: الاقتصاد اللبنانيّ يتنفّس برئة عربيّة (أسواق الصادرات، العمل في الدول العربيّة، المساعدات). والعمل المشترك عنصر قوّة وأداة حماية للبنان.', 1, '2026-09-30 22:12:47', '2026-09-30 22:12:47'),
(16059, 2530, 1, 'عقد العرب مؤتمر قمّة غير عاديّ في الدار البيضاء لمعالجة الأزمة اللبنانيّة، ثمّ نظّموا مؤتمراً في الطائف اجتمع فيه النوّاب اللبنانيّون، ثمّ ساعدوا على صدور وثيقة الوفاق الوطنيّ.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16060, 2530, 2, 'عقد العرب مؤتمر قمّة غير عاديّ في الدار البيضاء لمعالجة الأزمة اللبنانيّة، ثمّ نظّموا مؤتمراً في الطائف اجتمع فيه النوّاب اللبنانيّون، ثمّ ساعدوا على صدور وثيقة الوفاق الوطنيّ.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16061, 2531, 1, 'سلاح الغذاء يعني أنّ من يملك الغذاء يستطيع الضغط على من يستورده، فالبلد الذي يستورد غذاءه يقع تحت رحمة مالكي هذا السلاح، والعالم العربيّ يعاني عجزاً غذائيّاً. ولتحقيق الأمن الغذائيّ (توفير الطعام الأساسيّ على الأقلّ) نحتاج إلى التعاون العربيّ وحشد الطاقات العلميّة والماليّة للتنمية الزراعيّة: إيجاد مصادر إضافيّة للريّ، تحديث الأساليب الزراعيّة لزيادة الإنتاجيّة، زراعة الأصناف والسلالات المحسّنة من المحاصيل.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16062, 2531, 2, 'سلاح الغذاء يعني أنّ من يملك الغذاء يستطيع الضغط على من يستورده، فالبلد الذي يستورد غذاءه يقع تحت رحمة مالكي هذا السلاح، والعالم العربيّ يعاني عجزاً غذائيّاً. ولتحقيق الأمن الغذائيّ (توفير الطعام الأساسيّ على الأقلّ) نحتاج إلى التعاون العربيّ وحشد الطاقات العلميّة والماليّة للتنمية الزراعيّة: إيجاد مصادر إضافيّة للريّ، تحديث الأساليب الزراعيّة لزيادة الإنتاجيّة، زراعة الأصناف والسلالات المحسّنة من المحاصيل.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16063, 2532, 1, 'الأمن اليوم أمن الناس لا الدول فقط. المجال الأمنيّ: التعاون الأمنيّ العربيّ يوفّر الأمن من داخل النظام العربيّ بدل أمن أجنبيّ مكلف اقتصاديّاً وسياسيّاً. المجال المائيّ والغذائيّ: بناء السدود والمشاريع المائيّة وحمايتها، والتنمية الزراعيّة لتحقيق الأمن الغذائيّ. المجال الاقتصاديّ: منطقة التجارة الحرّة العربيّة الكبرى والسوق المشتركة تتيحان فرص النموّ للصناعة والزراعة وتواجهان المتغيّرات الدوليّة. ومبرّرات التعاون ما زالت قائمة.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16064, 2532, 2, 'الأمن اليوم أمن الناس لا الدول فقط. المجال الأمنيّ: التعاون الأمنيّ العربيّ يوفّر الأمن من داخل النظام العربيّ بدل أمن أجنبيّ مكلف اقتصاديّاً وسياسيّاً. المجال المائيّ والغذائيّ: بناء السدود والمشاريع المائيّة وحمايتها، والتنمية الزراعيّة لتحقيق الأمن الغذائيّ. المجال الاقتصاديّ: منطقة التجارة الحرّة العربيّة الكبرى والسوق المشتركة تتيحان فرص النموّ للصناعة والزراعة وتواجهان المتغيّرات الدوليّة. ومبرّرات التعاون ما زالت قائمة.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16065, 2533, 1, 'المصدر الأوّل إسرائيل، التي تحتلّ أرضاً عربيّة في فلسطين والجولان وجنوب لبنان غير آبهة بالقرارات الدوليّة. والثاني القوى العسكريّة الأجنبيّة المنتشرة في المحيط العربيّ من حشود وقواعد وأساطيل (في الخليج العربيّ مثلاً). وتستغلّ إسرائيل خلافات بين دول عربيّة وبعض دول الجوار كتركيا لتدفعها إلى سياسات وتحالفات معادية للعرب.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16066, 2533, 2, 'المصدر الأوّل إسرائيل، التي تحتلّ أرضاً عربيّة في فلسطين والجولان وجنوب لبنان غير آبهة بالقرارات الدوليّة. والثاني القوى العسكريّة الأجنبيّة المنتشرة في المحيط العربيّ من حشود وقواعد وأساطيل (في الخليج العربيّ مثلاً). وتستغلّ إسرائيل خلافات بين دول عربيّة وبعض دول الجوار كتركيا لتدفعها إلى سياسات وتحالفات معادية للعرب.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16067, 2534, 1, 'لأنّه أداة لحماية الوجود ولمجابهة الأخطار المصيريّة ومشاريع الهيمنة على المستقبل، وهو المظلّة لطموحات العرب المستقبليّة ولا سيّما التنمية الاقتصاديّة. ويتحقّق إذا تضامن العرب وأوجدوا آليّة لفضّ النزاعات العربيّة، وقوّة تكفل أمن العالم العربيّ بأدوات عربيّة بدل الأمن الأجنبيّ المستأجر ذي الكلفة الباهظة.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16068, 2534, 2, 'لأنّه أداة لحماية الوجود ولمجابهة الأخطار المصيريّة ومشاريع الهيمنة على المستقبل، وهو المظلّة لطموحات العرب المستقبليّة ولا سيّما التنمية الاقتصاديّة. ويتحقّق إذا تضامن العرب وأوجدوا آليّة لفضّ النزاعات العربيّة، وقوّة تكفل أمن العالم العربيّ بأدوات عربيّة بدل الأمن الأجنبيّ المستأجر ذي الكلفة الباهظة.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16069, 2535, 1, 'التنمية الاقتصاديّة تستند إلى التكامل بين الدول العربيّة في الإمكانات والحاجات، ومن وسائلها إنشاء السوق العربيّة المشتركة. أمّا التنمية البشريّة فتتطلّب الإنماء المتوازن للمناطق والقطاعات، وحملة مكثّفة لمحو الأميّة، واشتراك المرأة العربيّة في النشاطات الاجتماعيّة والاقتصاديّة، وغايتها تحسين نوعيّة حياة المواطن وزيادة حصّته من الدخل القومي. وكلتاهما تحتاج إلى التعاون العربيّ.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16070, 2535, 2, 'التنمية الاقتصاديّة تستند إلى التكامل بين الدول العربيّة في الإمكانات والحاجات، ومن وسائلها إنشاء السوق العربيّة المشتركة. أمّا التنمية البشريّة فتتطلّب الإنماء المتوازن للمناطق والقطاعات، وحملة مكثّفة لمحو الأميّة، واشتراك المرأة العربيّة في النشاطات الاجتماعيّة والاقتصاديّة، وغايتها تحسين نوعيّة حياة المواطن وزيادة حصّته من الدخل القومي. وكلتاهما تحتاج إلى التعاون العربيّ.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16071, 2536, 1, '1- الإفلات من المديونيّة. 2- الاعتماد على الذات لتحقيق التنمية الزراعيّة (ومدخلها إحياء السوق العربيّة المشتركة). 3- الإفلات من التبعيّة الأمنيّة بتفعيل مؤسّسات الدفاع العربيّ المشترك واعتماد الحوار بدل القوّات الأجنبيّة. 4- التحرّر من التبعيّة الثقافيّة والإعلاميّة.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16072, 2536, 2, '1- الإفلات من المديونيّة. 2- الاعتماد على الذات لتحقيق التنمية الزراعيّة (ومدخلها إحياء السوق العربيّة المشتركة). 3- الإفلات من التبعيّة الأمنيّة بتفعيل مؤسّسات الدفاع العربيّ المشترك واعتماد الحوار بدل القوّات الأجنبيّة. 4- التحرّر من التبعيّة الثقافيّة والإعلاميّة.', 1, '2026-09-30 22:12:48', '2026-09-30 22:12:48'),
(16073, 2537, 1, 'النزاع الدوليّ خلاف بين دولتين أو أكثر حول قضايا سياسيّة أو اقتصاديّة أو ثقافيّة، وقد يصل إلى المواجهة المسلّحة. من مصادره: مواجهة الشعوب المستعمَرة للاستعمار وطلبها الاستقلال؛ احتلال دولة أراضي دولة أخرى فيضطرّ الشعب إلى المقاومة؛ التنافس على الموارد والثروات الطبيعيّة كالنفط واليورانيوم ومياه الأنهار؛ الخلاف على السيطرة على مواقع استراتيجيّة كالممرّات وطرق المواصلات البرّيّة والبحريّة (ثلاثة منها).', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16074, 2537, 2, 'النزاع الدوليّ خلاف بين دولتين أو أكثر حول قضايا سياسيّة أو اقتصاديّة أو ثقافيّة، وقد يصل إلى المواجهة المسلّحة. من مصادره: مواجهة الشعوب المستعمَرة للاستعمار وطلبها الاستقلال؛ احتلال دولة أراضي دولة أخرى فيضطرّ الشعب إلى المقاومة؛ التنافس على الموارد والثروات الطبيعيّة كالنفط واليورانيوم ومياه الأنهار؛ الخلاف على السيطرة على مواقع استراتيجيّة كالممرّات وطرق المواصلات البرّيّة والبحريّة (ثلاثة منها).', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16075, 2538, 1, 'للنزاعات نتائج خطيرة: الخسائر البشريّة (البوسنة والهرسك وكوسوفو)، الحصار الاقتصاديّ المدمّر (العراق)، تعثّر مشاريع التنمية، تهجير الجماعات البشريّة (رواندا وبوروندي)، تهديد البيئة وزحف التصحّر. وكلّما اتّسعت النزاعات شملت أقاليم ودولاً إضافيّة. لذلك تؤكّد تسوية النزاعات بالطرق السلميّة وإحلال الأمن والسلام ضرورة التعاون الدوليّ وانتظام الدول في هيئة دوليّة كالأمم المتّحدة، مع المنظّمات الإقليميّة.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16076, 2538, 2, 'للنزاعات نتائج خطيرة: الخسائر البشريّة (البوسنة والهرسك وكوسوفو)، الحصار الاقتصاديّ المدمّر (العراق)، تعثّر مشاريع التنمية، تهجير الجماعات البشريّة (رواندا وبوروندي)، تهديد البيئة وزحف التصحّر. وكلّما اتّسعت النزاعات شملت أقاليم ودولاً إضافيّة. لذلك تؤكّد تسوية النزاعات بالطرق السلميّة وإحلال الأمن والسلام ضرورة التعاون الدوليّ وانتظام الدول في هيئة دوليّة كالأمم المتّحدة، مع المنظّمات الإقليميّة.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16077, 2539, 1, 'العسكريّ: استخدام القوّة أو حشد الجيوش على طرفي الحدود أو إجراء المناورات. الاقتصاديّ: الحصار ومنع وصول التكنولوجيا الحديثة. الإعلاميّ الدعائيّ: تشويه صورة الدولة الخصم في أذهان الرأي العامّ. الدبلوماسيّ: قطع العلاقات وقد يصل إلى قطعها الشامل.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16078, 2539, 2, 'العسكريّ: استخدام القوّة أو حشد الجيوش على طرفي الحدود أو إجراء المناورات. الاقتصاديّ: الحصار ومنع وصول التكنولوجيا الحديثة. الإعلاميّ الدعائيّ: تشويه صورة الدولة الخصم في أذهان الرأي العامّ. الدبلوماسيّ: قطع العلاقات وقد يصل إلى قطعها الشامل.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16079, 2540, 1, 'الحرب الأهليّة داخل الدولة تقع بين مجموعات سكّانيّة في الدولة نفسها، وتنشأ حين تصل التناقضات الاجتماعيّة والاقتصاديّة والعرقيّة والطائفيّة بينها إلى مرحلة الصراع، كالحرب الأهليّة الأميركيّة. أمّا الحرب بين الجيوش النظاميّة فتنشأ حين يصل النزاع الدوليّ إلى درجة خطرة من التصعيد، كما في الحربين العالميّتين.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16080, 2540, 2, 'الحرب الأهليّة داخل الدولة تقع بين مجموعات سكّانيّة في الدولة نفسها، وتنشأ حين تصل التناقضات الاجتماعيّة والاقتصاديّة والعرقيّة والطائفيّة بينها إلى مرحلة الصراع، كالحرب الأهليّة الأميركيّة. أمّا الحرب بين الجيوش النظاميّة فتنشأ حين يصل النزاع الدوليّ إلى درجة خطرة من التصعيد، كما في الحربين العالميّتين.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16081, 2541, 1, 'لاجئو أفغانستان انتقلوا إلى إيران وباكستان ثمّ جمهوريّات آسيا الوسطى. ونزح مليونا ألبانيّ من إقليم كوسوفو. واستدعت حرب كوسوفو تدخّل حلف شماليّ الأطلسيّ بغارات جوّيّة وتشكيل قوّات دوليّة لحفظ السلام وإدارة مدنيّة دوليّة. فهذه الحروب تهدّد الأمن الإقليميّ في مناطق النزاع.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16082, 2541, 2, 'لاجئو أفغانستان انتقلوا إلى إيران وباكستان ثمّ جمهوريّات آسيا الوسطى. ونزح مليونا ألبانيّ من إقليم كوسوفو. واستدعت حرب كوسوفو تدخّل حلف شماليّ الأطلسيّ بغارات جوّيّة وتشكيل قوّات دوليّة لحفظ السلام وإدارة مدنيّة دوليّة. فهذه الحروب تهدّد الأمن الإقليميّ في مناطق النزاع.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16083, 2542, 1, 'على الإنسان: قتلى وجرحى ومعوّقون، وتهجير ونزوح، وضحايا الألغام. على الدولة: تهديد كيانها، وازدياد الفقر، وتعثّر التنمية. على الأرض والعمران: دمار وخراب كتدمير آلات الريّ في أفغانستان. وتهدّد الأمن الإقليميّ، ونتائجها لا تنحصر في جيل واحد.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16084, 2542, 2, 'على الإنسان: قتلى وجرحى ومعوّقون، وتهجير ونزوح، وضحايا الألغام. على الدولة: تهديد كيانها، وازدياد الفقر، وتعثّر التنمية. على الأرض والعمران: دمار وخراب كتدمير آلات الريّ في أفغانستان. وتهدّد الأمن الإقليميّ، ونتائجها لا تنحصر في جيل واحد.', 1, '2026-09-30 22:12:49', '2026-09-30 22:12:49'),
(16085, 2543, 1, 'في الفصل السادس: على أطراف النزاع اتّباع الطرق السلميّة بناءً على دعوة يوجّهها إليهم مجلس الأمن، ويحقّ للمجلس أن يحقّق في طبيعة النزاع ومدى خطورته وأن يوصي بما يراه مناسباً. في الفصل السابع: يُطبَّق إذا فشل الأطراف في التسوية السلميّة، فيُعرض النزاع على مجلس الأمن الذي يملك سلطات واسعة وملزمة، فيقرّر إن كان قد وقع تهديد للسلام أو إخلال به أو عمل عدوان، ويتّخذ تدابير رادعة تتدرّج من الحصار الاقتصادي إلى استخدام القوّة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16086, 2543, 2, 'في الفصل السادس: على أطراف النزاع اتّباع الطرق السلميّة بناءً على دعوة يوجّهها إليهم مجلس الأمن، ويحقّ للمجلس أن يحقّق في طبيعة النزاع ومدى خطورته وأن يوصي بما يراه مناسباً. في الفصل السابع: يُطبَّق إذا فشل الأطراف في التسوية السلميّة، فيُعرض النزاع على مجلس الأمن الذي يملك سلطات واسعة وملزمة، فيقرّر إن كان قد وقع تهديد للسلام أو إخلال به أو عمل عدوان، ويتّخذ تدابير رادعة تتدرّج من الحصار الاقتصادي إلى استخدام القوّة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16087, 2544, 1, 'قوّات حفظ السلام وحدات عسكريّة دوليّة تنتشر في منطقة النزاع لفترة محدّدة بعد الاتصال بأطراف النزاع والتنسيق معها، كقوّات الطوارئ الدوليّة في جنوب لبنان. التجربة الناجحة: كمبوديا، حيث أشرفت سلطة الأمم المتّحدة المؤقّتة على الإعلام والتعليم وأهّلت الإدارة المدنيّة وقوّات الشرطة. التجربة الصعبة: الصومال، حيث جاءت القوّات لوقف المجاعة فتورّطت في صراع الفصائل.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16088, 2544, 2, 'قوّات حفظ السلام وحدات عسكريّة دوليّة تنتشر في منطقة النزاع لفترة محدّدة بعد الاتصال بأطراف النزاع والتنسيق معها، كقوّات الطوارئ الدوليّة في جنوب لبنان. التجربة الناجحة: كمبوديا، حيث أشرفت سلطة الأمم المتّحدة المؤقّتة على الإعلام والتعليم وأهّلت الإدارة المدنيّة وقوّات الشرطة. التجربة الصعبة: الصومال، حيث جاءت القوّات لوقف المجاعة فتورّطت في صراع الفصائل.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16089, 2545, 1, 'حفظ السلام مجموعة إجراءات لتسوية نزاع دولي بعد إخفاق الدول المعنيّة مباشرةً في تسويته بالطرق السلميّة. تبدأ الأمم المتّحدة بإجراءات وقائيّة سلميّة (كالنشاط الدبلوماسي) لإزالة أسباب التوتّر ومنع تحوّل النزاع إلى مواجهة مسلّحة، فإذا لم تنجح هذه الوسائل السلميّة لجأت إلى قمع أعمال العدوان.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16090, 2545, 2, 'حفظ السلام مجموعة إجراءات لتسوية نزاع دولي بعد إخفاق الدول المعنيّة مباشرةً في تسويته بالطرق السلميّة. تبدأ الأمم المتّحدة بإجراءات وقائيّة سلميّة (كالنشاط الدبلوماسي) لإزالة أسباب التوتّر ومنع تحوّل النزاع إلى مواجهة مسلّحة، فإذا لم تنجح هذه الوسائل السلميّة لجأت إلى قمع أعمال العدوان.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16091, 2546, 1, 'تزداد حجماً وأهمّيّة، فالإقليميّة تعود إلى الظهور بقوّة. الأسباب: قيام مزيد من الكتل الاقتصاديّة والإقليميّة في إطار التنافس الاقتصادي والتكنولوجي؛ مشاريع التنمية؛ حماية البيئة الطبيعيّة؛ تلبية متطلّبات حقوق الإنسان؛ العولمة الاقتصاديّة التي جعلت العالم قرية صغيرة بفعل تطوّر الاتّصالات والمواصلات. وهي تعمل بالتكامل مع المنظّمات الدوليّة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16092, 2546, 2, 'تزداد حجماً وأهمّيّة، فالإقليميّة تعود إلى الظهور بقوّة. الأسباب: قيام مزيد من الكتل الاقتصاديّة والإقليميّة في إطار التنافس الاقتصادي والتكنولوجي؛ مشاريع التنمية؛ حماية البيئة الطبيعيّة؛ تلبية متطلّبات حقوق الإنسان؛ العولمة الاقتصاديّة التي جعلت العالم قرية صغيرة بفعل تطوّر الاتّصالات والمواصلات. وهي تعمل بالتكامل مع المنظّمات الدوليّة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16093, 2547, 1, 'نعم. فالميثاق يجعل عملها متلائماً مع مقاصد الأمم المتّحدة ومبادئها. ومن أشكال التعاون: التشاور حيال النزاعات القائمة، والاشتراك في الإجراءات التنفيذيّة، وتنفيذ عمليّات مشتركة. أمثلة: الصومال (الحوار بين الفصائل والتنمية)، طاجيكستان (وقف الحرب الأهليّة)، البوسنة (حماية سراييفو)، إنجاح المؤتمرات العالميّة كقمّة الأرض ومؤتمر فيينا. فدورها تكامليّ مع الأمم المتّحدة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16094, 2547, 2, 'نعم. فالميثاق يجعل عملها متلائماً مع مقاصد الأمم المتّحدة ومبادئها. ومن أشكال التعاون: التشاور حيال النزاعات القائمة، والاشتراك في الإجراءات التنفيذيّة، وتنفيذ عمليّات مشتركة. أمثلة: الصومال (الحوار بين الفصائل والتنمية)، طاجيكستان (وقف الحرب الأهليّة)، البوسنة (حماية سراييفو)، إنجاح المؤتمرات العالميّة كقمّة الأرض ومؤتمر فيينا. فدورها تكامليّ مع الأمم المتّحدة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16095, 2548, 1, 'بنشاطاتها الخاصّة، مثل إنشاء منظّمة الوحدة الأفريقيّة مجلس أمن أفريقي لفضّ النزاعات؛ وبالتعاون مع الأمم المتّحدة، مثل تعاون منظّمة المؤتمر الإسلامي مع الأمم المتّحدة لتأمين الحوار بين الفصائل الصوماليّة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16096, 2548, 2, 'بنشاطاتها الخاصّة، مثل إنشاء منظّمة الوحدة الأفريقيّة مجلس أمن أفريقي لفضّ النزاعات؛ وبالتعاون مع الأمم المتّحدة، مثل تعاون منظّمة المؤتمر الإسلامي مع الأمم المتّحدة لتأمين الحوار بين الفصائل الصوماليّة.', 1, '2026-09-30 22:12:50', '2026-09-30 22:12:50'),
(16097, 2549, 1, 'ازدواجيّة المعايير هي تطبيق القواعد الدوليّة بمعايير مختلفة بين دولة ودولة وبين منطقة وأخرى، وقد أوجدتها السياسة الدوليّة السائدة بعد الحرب الباردة، وتظهر في المساعدات الدوليّة والتجارة الدوليّة (ومثالها وجود إسرائيل في الشرق الأوسط وما يرتبط به من استيطان توسّعيّ وتسلّح). وهي تتعارض مع الاحترام المتبادل والتكافؤ في العلاقات بين الدول، وهما أساس التعاون الأشمل.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16098, 2549, 2, 'ازدواجيّة المعايير هي تطبيق القواعد الدوليّة بمعايير مختلفة بين دولة ودولة وبين منطقة وأخرى، وقد أوجدتها السياسة الدوليّة السائدة بعد الحرب الباردة، وتظهر في المساعدات الدوليّة والتجارة الدوليّة (ومثالها وجود إسرائيل في الشرق الأوسط وما يرتبط به من استيطان توسّعيّ وتسلّح). وهي تتعارض مع الاحترام المتبادل والتكافؤ في العلاقات بين الدول، وهما أساس التعاون الأشمل.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16099, 2550, 1, 'معالجة الأزمات العالميّة الضاغطة (المديونيّة، البطالة، المرض، الأمّيّة، تهديد البيئة)؛ تطوير أداء الأمم المتّحدة بتوسيع مجلس الأمن ليكون أكثر تمثيلاً وتفعيل النشاط الاقتصاديّ وحلّ أزمتها الماليّة المرتبطة بالاشتراكات السنويّة؛ إيجاد تكافؤ في العلاقات بين الدول بإزالة الخلل الذي يمكّن الدول الصناعيّة الكبرى من السيطرة على الموارد؛ معالجة ازدواجيّة المعايير (ثلاث منها).', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16100, 2550, 2, 'معالجة الأزمات العالميّة الضاغطة (المديونيّة، البطالة، المرض، الأمّيّة، تهديد البيئة)؛ تطوير أداء الأمم المتّحدة بتوسيع مجلس الأمن ليكون أكثر تمثيلاً وتفعيل النشاط الاقتصاديّ وحلّ أزمتها الماليّة المرتبطة بالاشتراكات السنويّة؛ إيجاد تكافؤ في العلاقات بين الدول بإزالة الخلل الذي يمكّن الدول الصناعيّة الكبرى من السيطرة على الموارد؛ معالجة ازدواجيّة المعايير (ثلاث منها).', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16101, 2551, 1, 'المنظّمات غير الحكوميّة تعمل خارج إطار الاتّفاقات الرسميّة بين الحكومات، ويمكنها أن تُشيع أجواء السلام والعدالة والتعاون بين الشعوب، وأن تُعدّ دراسات وآراء استشاريّة في خطط التنمية، وأن تعمل في حماية البيئة والدفاع عن حقوق الإنسان (ومثالها اللجنة الدوليّة للصليب الأحمر).', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16102, 2551, 2, 'المنظّمات غير الحكوميّة تعمل خارج إطار الاتّفاقات الرسميّة بين الحكومات، ويمكنها أن تُشيع أجواء السلام والعدالة والتعاون بين الشعوب، وأن تُعدّ دراسات وآراء استشاريّة في خطط التنمية، وأن تعمل في حماية البيئة والدفاع عن حقوق الإنسان (ومثالها اللجنة الدوليّة للصليب الأحمر).', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16103, 2552, 1, 'يدفع التخلّف الريفيّين إلى الهجرة، وتجذبهم إغراءات المدينة في الصحّة والتعليم وفرص العمل والترفيه والحرّيّة. والنتيجة أنّ النازحين يلفّون المدينة بأحزمة الفقر، ويهاجر أغنياؤها إلى الريف بسبب تردّي الأوضاع في قلبها، فينشأ تبدّل ديموغرافيّ وعدم استقرار اجتماعيّ. والحلّ تنفيذ خطّة تؤهّل الريف والمدينة معاً لأنّ العلاقة بينهما علاقة تبادل.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16104, 2552, 2, 'يدفع التخلّف الريفيّين إلى الهجرة، وتجذبهم إغراءات المدينة في الصحّة والتعليم وفرص العمل والترفيه والحرّيّة. والنتيجة أنّ النازحين يلفّون المدينة بأحزمة الفقر، ويهاجر أغنياؤها إلى الريف بسبب تردّي الأوضاع في قلبها، فينشأ تبدّل ديموغرافيّ وعدم استقرار اجتماعيّ. والحلّ تنفيذ خطّة تؤهّل الريف والمدينة معاً لأنّ العلاقة بينهما علاقة تبادل.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16105, 2553, 1, 'تلبّي المدينة وظائف السكن والإنتاج والخدمات، وقلبها مركز لإنتاج البضائع وتبادلها ولاتّخاذ القرارات ولتجمّع رؤوس الأموال والشركات والمؤسّسات، وينشأ فيها جوّ من الحرّيّة والحداثة. في الدول الغنيّة تشكّل المدن العملاقة محرّك الاقتصاد الوطنيّ والعالميّ في التجارة والمال والثقافة (طوكيو). أمّا في الدول الفقيرة (مصر، الهند، بنغلادش، الباكستان) فتولّد عدم توازن داخليّ واجتماعيّ واقتصاديّ يهدّد مستقبلها واستقرارها.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16106, 2553, 2, 'تلبّي المدينة وظائف السكن والإنتاج والخدمات، وقلبها مركز لإنتاج البضائع وتبادلها ولاتّخاذ القرارات ولتجمّع رؤوس الأموال والشركات والمؤسّسات، وينشأ فيها جوّ من الحرّيّة والحداثة. في الدول الغنيّة تشكّل المدن العملاقة محرّك الاقتصاد الوطنيّ والعالميّ في التجارة والمال والثقافة (طوكيو). أمّا في الدول الفقيرة (مصر، الهند، بنغلادش، الباكستان) فتولّد عدم توازن داخليّ واجتماعيّ واقتصاديّ يهدّد مستقبلها واستقرارها.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16107, 2554, 1, 'التغيّرات الماديّة والفكريّة التي أحدثتها الثورتان الصناعيّة والعلميّة؛ انخفاض نسبة الوفيات؛ تزايد الهجرة من الريف إلى المدينة بسبب إغراءاتها في الصحّة والتعليم وفرص العمل والترفيه والحرّيّة.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16108, 2554, 2, 'التغيّرات الماديّة والفكريّة التي أحدثتها الثورتان الصناعيّة والعلميّة؛ انخفاض نسبة الوفيات؛ تزايد الهجرة من الريف إلى المدينة بسبب إغراءاتها في الصحّة والتعليم وفرص العمل والترفيه والحرّيّة.', 1, '2026-09-30 22:12:51', '2026-09-30 22:12:51'),
(16109, 2555, 1, 'من مشاكل المدن: تزايد النفايات والمياه المبتذلة، ازدحام السير، التلوّث، الضجيج. وهي تشكّل خلفيّة للنزعات العنيفة والجريمة والاستنزاف العصبي والأمراض. ويؤكّد علماء الاجتماع وعلماء النفس أنّ كثافة السكّان وفقرهم على علاقة بالأمراض النفسيّة وإدمان المخدّرات واللجوء إلى الجريمة، فالجنوح إلى الجريمة مرتبط بالكثافة السكنيّة والفقر معاً.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16110, 2555, 2, 'من مشاكل المدن: تزايد النفايات والمياه المبتذلة، ازدحام السير، التلوّث، الضجيج. وهي تشكّل خلفيّة للنزعات العنيفة والجريمة والاستنزاف العصبي والأمراض. ويؤكّد علماء الاجتماع وعلماء النفس أنّ كثافة السكّان وفقرهم على علاقة بالأمراض النفسيّة وإدمان المخدّرات واللجوء إلى الجريمة، فالجنوح إلى الجريمة مرتبط بالكثافة السكنيّة والفقر معاً.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16111, 2556, 1, 'التراث يربط ماضي الجماعة بحاضرها ومستقبلها وينسج هويّتها، وتدميره يقضي على الذاكرة والتاريخ المشتركين، وسكّان المدن التي أزيل تراثها فقدوا جزءاً من هويّتهم وارتباطهم بالأرض. لذلك على المواطن المحافظة على التراث وتأهيله، باستعمال الأبنية القديمة مطاعم ومقاهي ودوراً للثقافة، ودعم هندسة للأبنية الجديدة تراعي هذا التراث.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16112, 2556, 2, 'التراث يربط ماضي الجماعة بحاضرها ومستقبلها وينسج هويّتها، وتدميره يقضي على الذاكرة والتاريخ المشتركين، وسكّان المدن التي أزيل تراثها فقدوا جزءاً من هويّتهم وارتباطهم بالأرض. لذلك على المواطن المحافظة على التراث وتأهيله، باستعمال الأبنية القديمة مطاعم ومقاهي ودوراً للثقافة، ودعم هندسة للأبنية الجديدة تراعي هذا التراث.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16113, 2557, 1, 'من النتائج: أمراض الجهاز التنفّسي وسرطان الرئة؛ تغيير المناخ برفع حرارة الأرض؛ ثقب طبقة الأوزون. ومن وسائل محاربته معالجة مصادره: نقل المصانع إلى خارج المدن وإخضاعها للشروط الصحيّة، وتجهيز وسائل النقل العام.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16114, 2557, 2, 'من النتائج: أمراض الجهاز التنفّسي وسرطان الرئة؛ تغيير المناخ برفع حرارة الأرض؛ ثقب طبقة الأوزون. ومن وسائل محاربته معالجة مصادره: نقل المصانع إلى خارج المدن وإخضاعها للشروط الصحيّة، وتجهيز وسائل النقل العام.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16115, 2558, 1, 'نزح الناس من الأرياف إلى المدن فتضخّم عدد سكّانها، وازدادت وسائل النقل، وكثرت أكواخ السكن في الضواحي، واشتدّت الحاجة إلى الخدمات العامّة. هذا الواقع دفع الدولة إلى التدخّل للحدّ من الفوضى والمعاناة.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16116, 2558, 2, 'نزح الناس من الأرياف إلى المدن فتضخّم عدد سكّانها، وازدادت وسائل النقل، وكثرت أكواخ السكن في الضواحي، واشتدّت الحاجة إلى الخدمات العامّة. هذا الواقع دفع الدولة إلى التدخّل للحدّ من الفوضى والمعاناة.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16117, 2559, 1, 'المنحى الوظيفيّ الإصلاحيّ يقسم الأراضي إلى مراكز للعمل أو للسكن أو للترفيه، ويسعى إلى نموذج مدنيّ متكامل يُطبَّق في كلّ زمان ومكان، وأبنيته كبيرة محاطة بمساحة خضراء (لوكوربيزيه). أمّا المنحى الإنسانيّ فيحافظ على قلب المدينة وأطرافها، ويقوم على استقصاء مسبق لنواحي الحياة الجغرافيّة والتاريخيّة والاجتماعيّة والبيئيّة مع التوسّع المستقبليّ، ويحمي المناطق ويؤهّل المباني ذات الأهمّيّة. الفرق: نموذج عامّ في الأوّل، ومراعاة لخصوصيّة المكان في الثاني.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16118, 2559, 2, 'المنحى الوظيفيّ الإصلاحيّ يقسم الأراضي إلى مراكز للعمل أو للسكن أو للترفيه، ويسعى إلى نموذج مدنيّ متكامل يُطبَّق في كلّ زمان ومكان، وأبنيته كبيرة محاطة بمساحة خضراء (لوكوربيزيه). أمّا المنحى الإنسانيّ فيحافظ على قلب المدينة وأطرافها، ويقوم على استقصاء مسبق لنواحي الحياة الجغرافيّة والتاريخيّة والاجتماعيّة والبيئيّة مع التوسّع المستقبليّ، ويحمي المناطق ويؤهّل المباني ذات الأهمّيّة. الفرق: نموذج عامّ في الأوّل، ومراعاة لخصوصيّة المكان في الثاني.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16119, 2560, 1, 'تمديدات الماء والكهرباء والهاتف والمجاري الصحّيّة؛ تخطيط الشوارع والساحات والحدائق؛ البناء (شكله وارتفاعه ووجهة استعماله وشروطه الصحّيّة ومواقفه)؛ تحديد مناطق السكن والتجارة والصناعة؛ ربط المدينة بالمطارات والمرافئ ومحطّات سكك الحديد والنقل العامّ (ثلاثة منها).', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16120, 2560, 2, 'تمديدات الماء والكهرباء والهاتف والمجاري الصحّيّة؛ تخطيط الشوارع والساحات والحدائق؛ البناء (شكله وارتفاعه ووجهة استعماله وشروطه الصحّيّة ومواقفه)؛ تحديد مناطق السكن والتجارة والصناعة؛ ربط المدينة بالمطارات والمرافئ ومحطّات سكك الحديد والنقل العامّ (ثلاثة منها).', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16121, 2561, 1, 'السبب الأوّل: انتشار التمدّد الفوضويّ للعمران في المدن والكثافة السكّانيّة في الساحل وفي بيروت وضواحيها. السبب الثاني: تأخّر تطوير البنية التحتيّة البيئيّة والاجتماعيّة عن مواكبة الانتشار السريع للسكّان في المدن. ومن العقبات: تدنّي المستوى التقنيّ والمهنيّ، تفشّي الفساد والرشوة في الإدارة، طغيان القطاع الخاصّ والمضاربات العقاريّة، صدور قوانين متتالية لتسوية مخالفات البناء شجّعت المخالفين (اثنتان منها).', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16122, 2561, 2, 'السبب الأوّل: انتشار التمدّد الفوضويّ للعمران في المدن والكثافة السكّانيّة في الساحل وفي بيروت وضواحيها. السبب الثاني: تأخّر تطوير البنية التحتيّة البيئيّة والاجتماعيّة عن مواكبة الانتشار السريع للسكّان في المدن. ومن العقبات: تدنّي المستوى التقنيّ والمهنيّ، تفشّي الفساد والرشوة في الإدارة، طغيان القطاع الخاصّ والمضاربات العقاريّة، صدور قوانين متتالية لتسوية مخالفات البناء شجّعت المخالفين (اثنتان منها).', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16123, 2562, 1, 'التراث في لبنان غنيّ ومتنوّع، والآثار تراث مشترك نحن مسؤولون عن حفظه للأجيال المقبلة (شرعة البندقية). ومن أهداف التنظيم المدنيّ: حماية الأراضي الزراعيّة والثروة الطبيعيّة من جبال وأودية وغابات؛ المحافظة على جمال المدن والقرى وعلى التراث الثقافيّ والمعماريّ؛ تخفيف العبء عن المدن الكبرى (كثافة السكّان وازدحام السير) مع الفسحات الخضراء والطرق المشجّرة؛ الحدّ من تلوّث المياه والهواء والتربة بتصريف المياه المبتذلة ومعالجة الصناعات الملوِّثة.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16124, 2562, 2, 'التراث في لبنان غنيّ ومتنوّع، والآثار تراث مشترك نحن مسؤولون عن حفظه للأجيال المقبلة (شرعة البندقية). ومن أهداف التنظيم المدنيّ: حماية الأراضي الزراعيّة والثروة الطبيعيّة من جبال وأودية وغابات؛ المحافظة على جمال المدن والقرى وعلى التراث الثقافيّ والمعماريّ؛ تخفيف العبء عن المدن الكبرى (كثافة السكّان وازدحام السير) مع الفسحات الخضراء والطرق المشجّرة؛ الحدّ من تلوّث المياه والهواء والتربة بتصريف المياه المبتذلة ومعالجة الصناعات الملوِّثة.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16125, 2563, 1, 'التلوّث الذي يشوّه المدن والقرى؛ ردم الشاطئ وسحب رمال البحر؛ تعميم المقالع والمرامل والكسّارات التي تشوّه المواقع الطبيعيّة.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16126, 2563, 2, 'التلوّث الذي يشوّه المدن والقرى؛ ردم الشاطئ وسحب رمال البحر؛ تعميم المقالع والمرامل والكسّارات التي تشوّه المواقع الطبيعيّة.', 1, '2026-09-30 22:12:52', '2026-09-30 22:12:52'),
(16127, 2564, 1, 'التشويه البيئيّ الكبير، كما حدث عند توسيع مجرى نهر أبو علي في طرابلس دون مراعاة التنظيم المدنيّ. وإتلاف التراث، كما في بيروت حيث أتلفت مخالفات قانون البناء الكثير من تراثها منذ الستّينيّات، وهي مخالفات تتعلّق بعلوّ الأبنية والتراجع والاستثمار وتغيير وجهة استعمال مواقف السيّارات.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16128, 2564, 2, 'التشويه البيئيّ الكبير، كما حدث عند توسيع مجرى نهر أبو علي في طرابلس دون مراعاة التنظيم المدنيّ. وإتلاف التراث، كما في بيروت حيث أتلفت مخالفات قانون البناء الكثير من تراثها منذ الستّينيّات، وهي مخالفات تتعلّق بعلوّ الأبنية والتراجع والاستثمار وتغيير وجهة استعمال مواقف السيّارات.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16129, 2565, 1, 'تتولّى البلديّات التنظيم (منذ أواخر القرن التاسع عشر) بالتعاون مع أجهزة التنظيم المدنيّ التي أنشأها قانون التنظيم المدنيّ سنة 1962. والمواطن والمجتمع الأهليّ شركاء في حماية المدينة، إذ تأسّست أحزاب وجمعيّات ونوادٍ هدفها حماية البيئة والتراث وحقوق الإنسان والمستهلك. مثال: في طرابلس حافظت البلديّة بدعم الناشطين البيئيّين على المساحات الخضراء.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16130, 2565, 2, 'تتولّى البلديّات التنظيم (منذ أواخر القرن التاسع عشر) بالتعاون مع أجهزة التنظيم المدنيّ التي أنشأها قانون التنظيم المدنيّ سنة 1962. والمواطن والمجتمع الأهليّ شركاء في حماية المدينة، إذ تأسّست أحزاب وجمعيّات ونوادٍ هدفها حماية البيئة والتراث وحقوق الإنسان والمستهلك. مثال: في طرابلس حافظت البلديّة بدعم الناشطين البيئيّين على المساحات الخضراء.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16131, 2566, 1, 'حافظت على طبيعتها الخضراء وحدّت من انتشار البناء، وقُسّمت المدينة سنة 1967 إلى مناطق سكنيّة وتجاريّة وأخرى خضراء لا تتجاوز نسبة البناء فيها عشرين في المئة، وشهدت واحداً من أوائل مشاريع الضمّ والفرز في لبنان، مع بقاء صيدا القديمة متحفاً كبيراً.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16132, 2566, 2, 'حافظت على طبيعتها الخضراء وحدّت من انتشار البناء، وقُسّمت المدينة سنة 1967 إلى مناطق سكنيّة وتجاريّة وأخرى خضراء لا تتجاوز نسبة البناء فيها عشرين في المئة، وشهدت واحداً من أوائل مشاريع الضمّ والفرز في لبنان، مع بقاء صيدا القديمة متحفاً كبيراً.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16133, 2567, 1, 'حرّيّة الرأي والتعبير هي الإمكانيّة المتاحة لكلّ فرد في المجتمع أن يكوّن رأياً خاصّاً به وأن يعبّر عنه بحرّيّة، وتحميها نصوص دستوريّة وقانونيّة. أهمّيّتها: تعكس الاعتراف بشخصيّة الفرد وقيمته كإنسان، وتمكّنه من المشاركة في الحياة العامّة.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16134, 2567, 2, 'حرّيّة الرأي والتعبير هي الإمكانيّة المتاحة لكلّ فرد في المجتمع أن يكوّن رأياً خاصّاً به وأن يعبّر عنه بحرّيّة، وتحميها نصوص دستوريّة وقانونيّة. أهمّيّتها: تعكس الاعتراف بشخصيّة الفرد وقيمته كإنسان، وتمكّنه من المشاركة في الحياة العامّة.', 1, '2026-09-30 22:12:53', '2026-09-30 22:12:53'),
(16135, 2568, 1, 'لأنّ الدستور يكفلها ضمن دائرة القانون، والغاية من الضوابط حسن ممارستها في المجتمع المدني واحترام حقوق الآخرين وحماية الأمن الوطني والنظام العامّ والأخلاق العامّة، على ألّا تلغيها. من القوانين (ثلاثة ممّا يلي): قانون العقوبات، قانون المطبوعات، قانون الإعلام المرئي والمسموع، قانون الرقابة على الأشرطة السينمائيّة. الجهة المخوّلة: السلطة التشريعيّة، أي مجلس النوّاب.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16136, 2568, 2, 'لأنّ الدستور يكفلها ضمن دائرة القانون، والغاية من الضوابط حسن ممارستها في المجتمع المدني واحترام حقوق الآخرين وحماية الأمن الوطني والنظام العامّ والأخلاق العامّة، على ألّا تلغيها. من القوانين (ثلاثة ممّا يلي): قانون العقوبات، قانون المطبوعات، قانون الإعلام المرئي والمسموع، قانون الرقابة على الأشرطة السينمائيّة. الجهة المخوّلة: السلطة التشريعيّة، أي مجلس النوّاب.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16137, 2569, 1, 'في الظروف العاديّة: الجهة هي السلطة التشريعيّة (مجلس النوّاب)، والأداة هي القانون، ومثالها قانون المطبوعات. في حالة الطوارئ: تعلنها الحكومة بمرسوم يُتّخذ في مجلس الوزراء، وتتولّى السلطة العسكريّة العليا المحافظة على الأمن، ومثالها منع النشرات المخلّة وفرض الرقابة المسبقة على الصحف والمطبوعات والإذاعات.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16138, 2569, 2, 'في الظروف العاديّة: الجهة هي السلطة التشريعيّة (مجلس النوّاب)، والأداة هي القانون، ومثالها قانون المطبوعات. في حالة الطوارئ: تعلنها الحكومة بمرسوم يُتّخذ في مجلس الوزراء، وتتولّى السلطة العسكريّة العليا المحافظة على الأمن، ومثالها منع النشرات المخلّة وفرض الرقابة المسبقة على الصحف والمطبوعات والإذاعات.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16139, 2570, 1, 'لأنّ الشعب مصدر السلطات ويختارها بالانتخاب، والمواطنيّة لا تتحقّق إلّا بالمشاركة في الحياة السياسيّة للبلد عبر الانتخاب ومتابعة الشأن العامّ ومحاسبة المسؤولين ومساءلتهم. ومن يمتنع عن الانتخاب يتخلّى عن الوسيلة الأساسيّة التي تتحقّق بها مواطنيّته.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16140, 2570, 2, 'لأنّ الشعب مصدر السلطات ويختارها بالانتخاب، والمواطنيّة لا تتحقّق إلّا بالمشاركة في الحياة السياسيّة للبلد عبر الانتخاب ومتابعة الشأن العامّ ومحاسبة المسؤولين ومساءلتهم. ومن يمتنع عن الانتخاب يتخلّى عن الوسيلة الأساسيّة التي تتحقّق بها مواطنيّته.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16141, 2571, 1, 'الناخب: لبنانيّ أكمل الحادية والعشرين من عمره، متمتّع بحقوقه المدنيّة والسياسيّة، واسمه وارد في قائمة الناخبين. المرشّح: لبنانيّ منذ أكثر من عشر سنوات، أتمّ الخامسة والعشرين، متعلّم، إضافة إلى تمتّعه بحقوقه وورود اسمه في القائمة. فشروط المرشّح أشدّ من شروط الناخب.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16142, 2571, 2, 'الناخب: لبنانيّ أكمل الحادية والعشرين من عمره، متمتّع بحقوقه المدنيّة والسياسيّة، واسمه وارد في قائمة الناخبين. المرشّح: لبنانيّ منذ أكثر من عشر سنوات، أتمّ الخامسة والعشرين، متعلّم، إضافة إلى تمتّعه بحقوقه وورود اسمه في القائمة. فشروط المرشّح أشدّ من شروط الناخب.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16143, 2572, 1, 'موقف سلبيّ، لأنّ الانتخاب واجب ومسؤوليّة. من نتائجه (اثنتان): أنّ المتخلّف يتخلّى عن الوسيلة الأساسيّة لتحقيق مواطنيّته؛ ويضعف تعبير الشعب عن إرادته وهو مصدر السلطات؛ وتضعف متابعة الشأن العامّ ومحاسبة المسؤولين.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16144, 2572, 2, 'موقف سلبيّ، لأنّ الانتخاب واجب ومسؤوليّة. من نتائجه (اثنتان): أنّ المتخلّف يتخلّى عن الوسيلة الأساسيّة لتحقيق مواطنيّته؛ ويضعف تعبير الشعب عن إرادته وهو مصدر السلطات؛ وتضعف متابعة الشأن العامّ ومحاسبة المسؤولين.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16145, 2573, 1, 'مستويات التعاون: بين أفراد الأسرة الواحدة، وبين مؤسّسات المجتمع الأهلي كالجمعيّات، وبين الدول. عناصر تعريف الجمعيّة: عدّة أشخاص، يوحّدون معلوماتهم أو مساعيهم، بصورة دائمة، لغرض لا يُقصد به الربح.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54'),
(16146, 2573, 2, 'مستويات التعاون: بين أفراد الأسرة الواحدة، وبين مؤسّسات المجتمع الأهلي كالجمعيّات، وبين الدول. عناصر تعريف الجمعيّة: عدّة أشخاص، يوحّدون معلوماتهم أو مساعيهم، بصورة دائمة، لغرض لا يُقصد به الربح.', 1, '2026-09-30 22:12:54', '2026-09-30 22:12:54');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(16147, 2574, 1, 'تنشأ الجمعيّة بمجرّد الاتفاق على تأسيسها، ولا تحتاج إلى رخصة في أوّل الأمر، ثمّ تُعلَم وزارة الداخليّة (الحكومة) بها بعد التأسيس فتُمنح العلم والخبر. من الجمعيّات الممنوعة (نوعان): الجمعيّات السرّيّة، الجمعيّات الهادفة إلى الإخلال بالأمن وباستقلال البلاد، الجمعيّات المستندة إلى أساس غير مشروع، جمعيّات الأشرار الهادفة إلى ارتكاب الجرائم كالعصابات.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16148, 2574, 2, 'تنشأ الجمعيّة بمجرّد الاتفاق على تأسيسها، ولا تحتاج إلى رخصة في أوّل الأمر، ثمّ تُعلَم وزارة الداخليّة (الحكومة) بها بعد التأسيس فتُمنح العلم والخبر. من الجمعيّات الممنوعة (نوعان): الجمعيّات السرّيّة، الجمعيّات الهادفة إلى الإخلال بالأمن وباستقلال البلاد، الجمعيّات المستندة إلى أساس غير مشروع، جمعيّات الأشرار الهادفة إلى ارتكاب الجرائم كالعصابات.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16149, 2575, 1, 'لأنّ الأحزاب تعدّ المواطنين لتحمّل المسؤوليّة السياسيّة، وتدرّبهم على المشاركة في وضع المشاريع والبرامج فيسهمون في تولّي شؤون الحكم والإدارة. ويمكن للحزب أن يتحوّل إلى معارضة، والمعارضة من وسائل الخدمة الوطنيّة. والحرّيّة والديمقراطيّة هما ضمان العمل الحزبيّ.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16150, 2575, 2, 'لأنّ الأحزاب تعدّ المواطنين لتحمّل المسؤوليّة السياسيّة، وتدرّبهم على المشاركة في وضع المشاريع والبرامج فيسهمون في تولّي شؤون الحكم والإدارة. ويمكن للحزب أن يتحوّل إلى معارضة، والمعارضة من وسائل الخدمة الوطنيّة. والحرّيّة والديمقراطيّة هما ضمان العمل الحزبيّ.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16151, 2576, 1, 'الاستبداد هو التفرّد والاستئثار بالقرار. من أشكال الظلم (ثلاثة): استرقاق الأسرى وتجارة الرقيق، التسخير بالأعمال الشاقّة والمذلّة، الاعتقال بغير مبرّر والتعذيب، تطبيق العقوبات الوحشيّة، الاعتداء على ممتلكات الغير، التمييز بسبب اللون أو الجنس أو المعتقد.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16152, 2576, 2, 'الاستبداد هو التفرّد والاستئثار بالقرار. من أشكال الظلم (ثلاثة): استرقاق الأسرى وتجارة الرقيق، التسخير بالأعمال الشاقّة والمذلّة، الاعتقال بغير مبرّر والتعذيب، تطبيق العقوبات الوحشيّة، الاعتداء على ممتلكات الغير، التمييز بسبب اللون أو الجنس أو المعتقد.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16153, 2577, 1, 'الاستبداد السياسيّ هو الطغيان. من خصائص المستبدّ (أربع): لا يقيم وزناً للروادع القانونيّة أو الخلقيّة؛ لا يمتثل للشرائع بل يسعى إلى تلبية رغباته وأنانيّته وميوله؛ لا يراعي ظروف المحكومين إذا طبّق القوانين؛ يضع القانون ويطبّقه على هواه؛ يعلّق العمل بالدستور حين يهدّد استمرار طغيانه؛ يجمع كلّ السلطات في قبضته.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16154, 2577, 2, 'الاستبداد السياسيّ هو الطغيان. من خصائص المستبدّ (أربع): لا يقيم وزناً للروادع القانونيّة أو الخلقيّة؛ لا يمتثل للشرائع بل يسعى إلى تلبية رغباته وأنانيّته وميوله؛ لا يراعي ظروف المحكومين إذا طبّق القوانين؛ يضع القانون ويطبّقه على هواه؛ يعلّق العمل بالدستور حين يهدّد استمرار طغيانه؛ يجمع كلّ السلطات في قبضته.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16155, 2578, 1, 'الإعلان العالميّ يقرّ حقّ مقاومة الظلم إذا لم تنصف المحاكم الفرد. والقانون اللبنانيّ يحمي التظاهر السلميّ وحقّ التجمّع، ولا يقيّد التجمّع إلّا لضرورات المصلحة العامّة وحفظ النظام العامّ. أمّا قانون العقوبات فيعاقب على الشغب وعلى مقاومة الموظّف بالعنف. فالتعبير السلميّ المنظّم حقّ مصون، والشغب والعنف يعاقب عليهما القانون.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16156, 2578, 2, 'الإعلان العالميّ يقرّ حقّ مقاومة الظلم إذا لم تنصف المحاكم الفرد. والقانون اللبنانيّ يحمي التظاهر السلميّ وحقّ التجمّع، ولا يقيّد التجمّع إلّا لضرورات المصلحة العامّة وحفظ النظام العامّ. أمّا قانون العقوبات فيعاقب على الشغب وعلى مقاومة الموظّف بالعنف. فالتعبير السلميّ المنظّم حقّ مصون، والشغب والعنف يعاقب عليهما القانون.', 1, '2026-09-30 22:12:55', '2026-09-30 22:12:55'),
(16157, 2579, 1, 'الاستقلال هو ممارسة الدولة السيادة الكاملة على أراضيها ضمن حدودها المعترف بها دوليّاً، وهذا يمنع الدول الأخرى من التدخّل في شؤونها الداخليّة. ويحقّ للدولة المعتدى عليها أن تقاوم لأنّ الاعتداء عليها (كاحتلال أراضيها أو جزء منها) عدوان صارخ وانتهاك لحقّها في السيادة والاستقلال، فتقاوم بكلّ الوسائل المشروعة صوناً لاستقلالها وسيادتها.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16158, 2579, 2, 'الاستقلال هو ممارسة الدولة السيادة الكاملة على أراضيها ضمن حدودها المعترف بها دوليّاً، وهذا يمنع الدول الأخرى من التدخّل في شؤونها الداخليّة. ويحقّ للدولة المعتدى عليها أن تقاوم لأنّ الاعتداء عليها (كاحتلال أراضيها أو جزء منها) عدوان صارخ وانتهاك لحقّها في السيادة والاستقلال، فتقاوم بكلّ الوسائل المشروعة صوناً لاستقلالها وسيادتها.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16159, 2580, 1, 'لأنّه ليس كلّ قانون عادلاً، لذلك نقول دولة القانون العادل؛ فالدولة عادلة بقدر ما توازن بين الحقوق والواجبات، وبقدر ما توفّر من ضمانات اجتماعيّة (مثل الصندوق الوطنيّ للضمان الاجتماعيّ). ويسعى المواطن الواعي إلى تعديل القانون غير العادل بالطرق الديمقراطيّة، أي بانتخاب ممثّلين يعملون على تعديله.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16160, 2580, 2, 'لأنّه ليس كلّ قانون عادلاً، لذلك نقول دولة القانون العادل؛ فالدولة عادلة بقدر ما توازن بين الحقوق والواجبات، وبقدر ما توفّر من ضمانات اجتماعيّة (مثل الصندوق الوطنيّ للضمان الاجتماعيّ). ويسعى المواطن الواعي إلى تعديل القانون غير العادل بالطرق الديمقراطيّة، أي بانتخاب ممثّلين يعملون على تعديله.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16161, 2581, 1, '١- تسوية النزاع بالطرق السلميّة، كالمفاوضة والتحقيق والوساطة والتحكيم والتسوية القضائيّة. ٢- تدابير غير عسكريّة (جزاءات)، كالحصار الاقتصاديّ ووقف الصلات الاقتصاديّة والمواصلات وقطع العلاقات الدبلوماسيّة. ٣- تدابير عسكريّة تقوم بها القوّات الجوّيّة والبحريّة والبرّيّة تقتضيها ضرورة حفظ السلم أو إعادته إلى نصابه.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16162, 2581, 2, '١- تسوية النزاع بالطرق السلميّة، كالمفاوضة والتحقيق والوساطة والتحكيم والتسوية القضائيّة. ٢- تدابير غير عسكريّة (جزاءات)، كالحصار الاقتصاديّ ووقف الصلات الاقتصاديّة والمواصلات وقطع العلاقات الدبلوماسيّة. ٣- تدابير عسكريّة تقوم بها القوّات الجوّيّة والبحريّة والبرّيّة تقتضيها ضرورة حفظ السلم أو إعادته إلى نصابه.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16163, 2582, 1, 'احتلّت إسرائيل الجنوب اللبنانيّ والبقاع الغربيّ، والاحتلال عدوان صارخ وانتهاك لسيادة لبنان واستقلاله. ويؤكّد ميثاق الأمم المتّحدة (المادّة ٥١) حقّ الدفاع عن النفس، وتؤكّد الاتفاقيّتان الدوليّتان حقّ الشعوب في تقرير مصيرها، وقد دعا القرار ٤٢٥ إسرائيل إلى سحب قوّاتها. لذلك فالمقاومة حقّ للشعب اللبنانيّ وواجب وطنيّ.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16164, 2583, 1, 'تكافؤ الفرص هو تساوي الإمكانيّات في الحصول على حقّ أو منفعة، وهو يرفض الامتيازات المجحفة ويحقّق مبدأ الشخص المناسب في المكان المناسب. ويجب أن تكون العلاقة مباشرة بلا وسيط سياسيّ (كالطائفة أو الحزب أو الزعيم السياسيّ أو النائب)، حتّى يشعر كلّ مواطن أنّ الدولة ترعاه لذاته، وأنّ خدماتها للجميع.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16165, 2582, 2, 'احتلّت إسرائيل الجنوب اللبنانيّ والبقاع الغربيّ، والاحتلال عدوان صارخ وانتهاك لسيادة لبنان واستقلاله. ويؤكّد ميثاق الأمم المتّحدة (المادّة ٥١) حقّ الدفاع عن النفس، وتؤكّد الاتفاقيّتان الدوليّتان حقّ الشعوب في تقرير مصيرها، وقد دعا القرار ٤٢٥ إسرائيل إلى سحب قوّاتها. لذلك فالمقاومة حقّ للشعب اللبنانيّ وواجب وطنيّ.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16166, 2583, 2, 'تكافؤ الفرص هو تساوي الإمكانيّات في الحصول على حقّ أو منفعة، وهو يرفض الامتيازات المجحفة ويحقّق مبدأ الشخص المناسب في المكان المناسب. ويجب أن تكون العلاقة مباشرة بلا وسيط سياسيّ (كالطائفة أو الحزب أو الزعيم السياسيّ أو النائب)، حتّى يشعر كلّ مواطن أنّ الدولة ترعاه لذاته، وأنّ خدماتها للجميع.', 1, '2026-09-30 22:12:56', '2026-09-30 22:12:56'),
(16167, 2584, 1, 'السلطة الاشتراعيّة ويمثّلها مجلس النوّاب، والسلطة الإجرائيّة (التنفيذيّة) ويمثّلها مجلس الوزراء، والسلطة القضائيّة وتمثّلها المحاكم. وجب الفصل بينها لأنّها إذا اجتمعت في شخص واحد أو جماعة واحدة ساد الظلم والاستبداد؛ فالفصل يصون العدل، ويتمكّن به النوّاب من محاسبة الوزراء والحكومة، ويُطبَّق القانون باسم الشعب.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16168, 2584, 2, 'السلطة الاشتراعيّة ويمثّلها مجلس النوّاب، والسلطة الإجرائيّة (التنفيذيّة) ويمثّلها مجلس الوزراء، والسلطة القضائيّة وتمثّلها المحاكم. وجب الفصل بينها لأنّها إذا اجتمعت في شخص واحد أو جماعة واحدة ساد الظلم والاستبداد؛ فالفصل يصون العدل، ويتمكّن به النوّاب من محاسبة الوزراء والحكومة، ويُطبَّق القانون باسم الشعب.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16169, 2585, 1, 'لأنّه لا تقوم دولة ديمقراطيّة دون ضوابط قانونيّة؛ فالقانون يحمي الحرّيات ويحدّد طريقة ممارستها منعاً للفوضى، وينظّم الحقوق والواجبات، ويضمن المشاركة الفاعلة بين الدولة والمواطن. والقوانين يضعها الشعب من خلال ممثّليه، أي النوّاب.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16170, 2585, 2, 'لأنّه لا تقوم دولة ديمقراطيّة دون ضوابط قانونيّة؛ فالقانون يحمي الحرّيات ويحدّد طريقة ممارستها منعاً للفوضى، وينظّم الحقوق والواجبات، ويضمن المشاركة الفاعلة بين الدولة والمواطن. والقوانين يضعها الشعب من خلال ممثّليه، أي النوّاب.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16171, 2586, 1, 'عملاً بمبدأ المساواة يسهم كلّ مواطن بحسب إمكاناته في نفقات المرافق العامّة، والضرائب من الموارد الرئيسيّة للدولة، فتموّل بها التقديمات الاجتماعيّة مثل التعليم والاستشفاء ورعاية المعوّقين والعناية بالمسنّين. وبذلك تسهم في الإنماء المتوازن للمناطق الذي جعلته وثيقة الوفاق الوطني ركناً أساسياً من أركان وحدة الدولة واستقرار النظام.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16172, 2586, 2, 'عملاً بمبدأ المساواة يسهم كلّ مواطن بحسب إمكاناته في نفقات المرافق العامّة، والضرائب من الموارد الرئيسيّة للدولة، فتموّل بها التقديمات الاجتماعيّة مثل التعليم والاستشفاء ورعاية المعوّقين والعناية بالمسنّين. وبذلك تسهم في الإنماء المتوازن للمناطق الذي جعلته وثيقة الوفاق الوطني ركناً أساسياً من أركان وحدة الدولة واستقرار النظام.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16173, 2587, 1, 'لأنّ الدفاع عن الوطن واجب وطني ومسؤوليّة وطنيّة يسهم فيها جميع أفراد الشعب القادرين على حمل السلاح. الأنواع: الخدمة العسكريّة لإعداد المواطن لمهمّات الدفاع العسكري في القوى المسلّحة؛ الخدمة المدنيّة لمساندة القوى المسلّحة في الدفاع الداخلي والخارجي ولا سيّما الدفاع المدني؛ الخدمة الإنمائيّة لتهيئة المواطن واستخدامه في القطاعات العامّة والخاصّة ذات المنفعة العامّة داخل البلاد وخارجها.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16174, 2587, 2, 'لأنّ الدفاع عن الوطن واجب وطني ومسؤوليّة وطنيّة يسهم فيها جميع أفراد الشعب القادرين على حمل السلاح. الأنواع: الخدمة العسكريّة لإعداد المواطن لمهمّات الدفاع العسكري في القوى المسلّحة؛ الخدمة المدنيّة لمساندة القوى المسلّحة في الدفاع الداخلي والخارجي ولا سيّما الدفاع المدني؛ الخدمة الإنمائيّة لتهيئة المواطن واستخدامه في القطاعات العامّة والخاصّة ذات المنفعة العامّة داخل البلاد وخارجها.', 1, '2026-09-30 22:12:57', '2026-09-30 22:12:57'),
(16175, 2588, 1, 'لا. فقد تبدّل وضع الإنسان تبعاً لتطوّر أدواته ولأنظمة الحكم السائدة، وقاسى فترة طويلة أنواعاً من التمييز والظلم والاضطهاد والامتهان قبل الاعتراف بكرامته وحرمة جسده وحرّيّة فكره ومعتقده. ومصادر حقوق الإنسان: الفلسفة، والدين، ونضالات الشعوب.', 1, '2026-09-30 22:12:58', '2026-09-30 22:12:58'),
(16176, 2588, 2, 'لا. فقد تبدّل وضع الإنسان تبعاً لتطوّر أدواته ولأنظمة الحكم السائدة، وقاسى فترة طويلة أنواعاً من التمييز والظلم والاضطهاد والامتهان قبل الاعتراف بكرامته وحرمة جسده وحرّيّة فكره ومعتقده. ومصادر حقوق الإنسان: الفلسفة، والدين، ونضالات الشعوب.', 1, '2026-09-30 22:12:58', '2026-09-30 22:12:58'),
(16177, 2589, 1, 'اتفاقيّة الحقوق المدنيّة والسياسيّة: الحقّ في التجمّع السلميّ، وحقّ تشكيل النقابات. اتفاقيّة الحقوق الاقتصاديّة والاجتماعيّة والثقافيّة: الحقّ في الرعاية الصحّيّة، والحقّ في مستوى معيشة لائق.', 1, '2026-09-30 22:12:58', '2026-09-30 22:12:58'),
(16178, 2589, 2, 'اتفاقيّة الحقوق المدنيّة والسياسيّة: الحقّ في التجمّع السلميّ، وحقّ تشكيل النقابات. اتفاقيّة الحقوق الاقتصاديّة والاجتماعيّة والثقافيّة: الحقّ في الرعاية الصحّيّة، والحقّ في مستوى معيشة لائق.', 1, '2026-09-30 22:12:58', '2026-09-30 22:12:58'),
(16179, 2590, 1, 'أدّى لبنان دوراً فاعلاً في بلورة المشروع: فقد كان ممثّله لدى الأمم المتّحدة شارل مالك (فيلسوف ودبلوماسيّ ومفكّر لبنانيّ) مقرّر لجنة حقوق الإنسان، فطبع المشروع بفلسفته، ووضع نصّه العربيّ الذي نقّحه الشاعر أمين نخلة.', 1, '2026-09-30 22:12:58', '2026-09-30 22:12:58'),
(16180, 2590, 2, 'أدّى لبنان دوراً فاعلاً في بلورة المشروع: فقد كان ممثّله لدى الأمم المتّحدة شارل مالك (فيلسوف ودبلوماسيّ ومفكّر لبنانيّ) مقرّر لجنة حقوق الإنسان، فطبع المشروع بفلسفته، ووضع نصّه العربيّ الذي نقّحه الشاعر أمين نخلة.', 1, '2026-09-30 22:12:58', '2026-09-30 22:12:58'),
(16181, 2591, 1, 'نشأت بعد الحرب العالميّة الثانية. هدفها الأساسي تأمين السلام وتوطيد الاستقرار في العالم. ووسائلها سلميّة، كالحوار والتوافق والتحكيم، لحلّ النزاعات.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16182, 2591, 2, 'نشأت بعد الحرب العالميّة الثانية. هدفها الأساسي تأمين السلام وتوطيد الاستقرار في العالم. ووسائلها سلميّة، كالحوار والتوافق والتحكيم، لحلّ النزاعات.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16183, 2592, 1, 'يتألّف مجلس الأمن حاليّاً من خمسة عشر عضواً: خمسة دائمون هم الولايات المتّحدة الأميركيّة وروسيا وبريطانيا وفرنسا والصين، والعشرة الباقون تنتخبهم الجمعيّة العامّة. وحقّ الفيتو تتمتّع به الدول الخمس الدائمة، ويعني أن يسقط القرار إذا عارضه أيّ عضو دائم.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16184, 2592, 2, 'يتألّف مجلس الأمن حاليّاً من خمسة عشر عضواً: خمسة دائمون هم الولايات المتّحدة الأميركيّة وروسيا وبريطانيا وفرنسا والصين، والعشرة الباقون تنتخبهم الجمعيّة العامّة. وحقّ الفيتو تتمتّع به الدول الخمس الدائمة، ويعني أن يسقط القرار إذا عارضه أيّ عضو دائم.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16185, 2593, 1, 'أتاح البروتوكول الاختياري للأفراد أن يشتكوا مباشرة أمام اللجنة الخاصّة التي تدرس انتهاكات الدول المنتمية إليها لأحد الحقوق الواردة في الاتفاقيّة. الإجراء تدبير تنفيذي يُطبَّق فعلاً، أمّا التوصية فنصائح وإرشادات سلوكيّة غير ملزمة لا يُعاقَب مخالفوها.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16186, 2593, 2, 'أتاح البروتوكول الاختياري للأفراد أن يشتكوا مباشرة أمام اللجنة الخاصّة التي تدرس انتهاكات الدول المنتمية إليها لأحد الحقوق الواردة في الاتفاقيّة. الإجراء تدبير تنفيذي يُطبَّق فعلاً، أمّا التوصية فنصائح وإرشادات سلوكيّة غير ملزمة لا يُعاقَب مخالفوها.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16187, 2594, 1, 'طبيعته القانونيّة لا تجعله ملزِماً، لكنّه يتمتّع بقوّة أدبيّة كبيرة. ويرى أبرز رجال القانون أنّه جزء من القانون العرفي للأمم، فهو ملزِم لكلّ الدول. ويدعم ذلك أنّ دولاً كثيرة أدخلته في دساتيرها فصار جزءاً لا يتجزّأ من أحكامها القانونيّة، وقد سار لبنان على هذه الخطى عند تعديل دستوره.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16188, 2594, 2, 'طبيعته القانونيّة لا تجعله ملزِماً، لكنّه يتمتّع بقوّة أدبيّة كبيرة. ويرى أبرز رجال القانون أنّه جزء من القانون العرفي للأمم، فهو ملزِم لكلّ الدول. ويدعم ذلك أنّ دولاً كثيرة أدخلته في دساتيرها فصار جزءاً لا يتجزّأ من أحكامها القانونيّة، وقد سار لبنان على هذه الخطى عند تعديل دستوره.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16189, 2595, 1, 'الاتفاقيّة الأوروبيّة اتفاقيّة قائمة ولها بروتوكولات، منها بروتوكول يحظر عقوبة الإعدام. أمّا في المنطقة العربيّة فبقي الميثاق مشروعاً (وُضع تنفيذاً لقرار من مجلس الجامعة)، ولم يتّخذ مجلس الجامعة أيّ إجراء سوى إدراجه على جدول أعماله. فالحماية العربيّة لم تتجاوز إطار المشاريع، أي لم تنتقل من مستوى التمنّيات إلى مستوى الإجراءات.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16190, 2595, 2, 'الاتفاقيّة الأوروبيّة اتفاقيّة قائمة ولها بروتوكولات، منها بروتوكول يحظر عقوبة الإعدام. أمّا في المنطقة العربيّة فبقي الميثاق مشروعاً (وُضع تنفيذاً لقرار من مجلس الجامعة)، ولم يتّخذ مجلس الجامعة أيّ إجراء سوى إدراجه على جدول أعماله. فالحماية العربيّة لم تتجاوز إطار المشاريع، أي لم تنتقل من مستوى التمنّيات إلى مستوى الإجراءات.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16191, 2596, 1, 'المنظّمات غير الحكوميّة (الأهليّة) جمعيّات أنشأتها مجموعات من المؤيّدين في دولة معيّنة للدفاع دولياً عن حقّ محدّد من حقوق الإنسان، مثل منظّمة العفو الدوليّة. من إنجازاتها (اثنان): معرفة الواقع وإظهاره بفضل حضورها على الأرض؛ إبلاغ الجهات الرسميّة المختصّة بكلّ إخلال والمطالبة بتصحيح الأوضاع؛ الإسهام في إعداد الاتّفاقيّة الدوليّة المناهضة للتعذيب والاتّفاقيّة حول حقوق الطفل؛ دفع الأمم المتّحدة إلى تعيين مقرّر خاصّ بشأن حماية المهجّرين.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16192, 2596, 2, 'المنظّمات غير الحكوميّة (الأهليّة) جمعيّات أنشأتها مجموعات من المؤيّدين في دولة معيّنة للدفاع دولياً عن حقّ محدّد من حقوق الإنسان، مثل منظّمة العفو الدوليّة. من إنجازاتها (اثنان): معرفة الواقع وإظهاره بفضل حضورها على الأرض؛ إبلاغ الجهات الرسميّة المختصّة بكلّ إخلال والمطالبة بتصحيح الأوضاع؛ الإسهام في إعداد الاتّفاقيّة الدوليّة المناهضة للتعذيب والاتّفاقيّة حول حقوق الطفل؛ دفع الأمم المتّحدة إلى تعيين مقرّر خاصّ بشأن حماية المهجّرين.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16193, 2597, 1, 'ثلاثة ممّا يلي: الحاجة إلى مقاعد تعليم ومساكن وخدمات طبيّة؛ توفير فرص العمل ووسائل النقل؛ ازدياد استهلاك الموارد الطبيعيّة كالمياه والمعادن والضغط على الغذاء. وحين تعجز الدولة عن تلبية هذه الحاجات تتفاقم المشكلات الاجتماعيّة، والحلّ هو التوازن بين الموارد وعدد السكان.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16194, 2597, 2, 'ثلاثة ممّا يلي: الحاجة إلى مقاعد تعليم ومساكن وخدمات طبيّة؛ توفير فرص العمل ووسائل النقل؛ ازدياد استهلاك الموارد الطبيعيّة كالمياه والمعادن والضغط على الغذاء. وحين تعجز الدولة عن تلبية هذه الحاجات تتفاقم المشكلات الاجتماعيّة، والحلّ هو التوازن بين الموارد وعدد السكان.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16195, 2598, 1, 'يتحوّل الدور الإنجابيّ إلى عبء حين تكثر الولادات وتُهمل صحّة المرأة، ويزداد العبء بسبب انخفاض مستواها التعليميّ وانحصار دورها التقليديّ داخل الأسرة بالأعمال المنزليّة. والنتيجة ضعف مشاركتها في النشاط الاقتصاديّ وفي تحسين المستوى الاقتصاديّ لأطفالها وأسرتها.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16196, 2598, 2, 'يتحوّل الدور الإنجابيّ إلى عبء حين تكثر الولادات وتُهمل صحّة المرأة، ويزداد العبء بسبب انخفاض مستواها التعليميّ وانحصار دورها التقليديّ داخل الأسرة بالأعمال المنزليّة. والنتيجة ضعف مشاركتها في النشاط الاقتصاديّ وفي تحسين المستوى الاقتصاديّ لأطفالها وأسرتها.', 1, '2026-09-30 22:12:59', '2026-09-30 22:12:59'),
(16197, 2599, 1, 'نعم، تنظيم الأسرة أحد الحلول، لأنّه يقيم التوازن بين الموارد وعدد السكان، ويخفّف أعباء الدولة في التعليم والسكن والصحّة والعمل، ويحمي الموارد الطبيعيّة، ويحمي صحّة المرأة ويتيح لها المشاركة في التنمية.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16198, 2599, 2, 'نعم، تنظيم الأسرة أحد الحلول، لأنّه يقيم التوازن بين الموارد وعدد السكان، ويخفّف أعباء الدولة في التعليم والسكن والصحّة والعمل، ويحمي الموارد الطبيعيّة، ويحمي صحّة المرأة ويتيح لها المشاركة في التنمية.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16199, 2600, 1, 'تنظيم الأسرة تخطيط لمستقبلها. من العوامل: العامل الاقتصادي (حجم يراعي مداخيل الأسرة وإمكاناتها والتوازن بين المداخيل والمصاريف)؛ العامل الصحّي (المباعدة بين مولود وآخر حفاظاً على صحّة الأم والطفل)؛ العوامل السياسيّة والاجتماعيّة والدينيّة. والتنظيم الناجح يفترض اتّفاقاً بين الزوج والزوجة.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16200, 2600, 2, 'تنظيم الأسرة تخطيط لمستقبلها. من العوامل: العامل الاقتصادي (حجم يراعي مداخيل الأسرة وإمكاناتها والتوازن بين المداخيل والمصاريف)؛ العامل الصحّي (المباعدة بين مولود وآخر حفاظاً على صحّة الأم والطفل)؛ العوامل السياسيّة والاجتماعيّة والدينيّة. والتنظيم الناجح يفترض اتّفاقاً بين الزوج والزوجة.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16201, 2601, 1, 'لأنّ الإنجاب مجموعة مسؤوليّات إضافيّة تُلقى على الأهل؛ فللمولود الجديد حاجات آنيّة وحاجات مستقبليّة، وتأمينها يتطلّب توازناً بين دخل الأسرة ومصروفها. لذلك على الأهل دراسة إمكاناتهم قبل الإقدام على الإنجاب.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16202, 2601, 2, 'لأنّ الإنجاب مجموعة مسؤوليّات إضافيّة تُلقى على الأهل؛ فللمولود الجديد حاجات آنيّة وحاجات مستقبليّة، وتأمينها يتطلّب توازناً بين دخل الأسرة ومصروفها. لذلك على الأهل دراسة إمكاناتهم قبل الإقدام على الإنجاب.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16203, 2602, 1, 'هناك أمور تحتاج إلى قرارات رشيدة، مثل حجم الأسرة والتخطيط لمستقبلها واختيار شريك الحياة. يقوم القرار على اتّفاق الزوج والزوجة، مع إشراك الأولاد بحسب أعمارهم وثقافتهم ووعيهم الاجتماعي. ورأي الأهل اليوم أساسي لكنّه يقرّ برأي الأبناء في خياراتهم الشخصيّة، بخلاف الماضي حين كان وليّ الأمر يختار بنفسه. والمشاركة تكسب الأولاد المعرفة والخبرة.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16204, 2602, 2, 'هناك أمور تحتاج إلى قرارات رشيدة، مثل حجم الأسرة والتخطيط لمستقبلها واختيار شريك الحياة. يقوم القرار على اتّفاق الزوج والزوجة، مع إشراك الأولاد بحسب أعمارهم وثقافتهم ووعيهم الاجتماعي. ورأي الأهل اليوم أساسي لكنّه يقرّ برأي الأبناء في خياراتهم الشخصيّة، بخلاف الماضي حين كان وليّ الأمر يختار بنفسه. والمشاركة تكسب الأولاد المعرفة والخبرة.', 1, '2026-09-30 22:13:00', '2026-09-30 22:13:00'),
(16205, 2603, 1, 'الخلاف ظاهرة طبيعية موجودة في كلّ المجتمعات، لكنّه يصبح خطراً عندما يتفاقم ويستمرّ، فيهدّد وحدة الأسرة واستقرارها وقدرتها على تحقيق أهداف أعضائها. من مظاهر التفكّك: ارتفاع حالات الطلاق، وتزايد حالات الانتحار.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16206, 2603, 2, 'الخلاف ظاهرة طبيعية موجودة في كلّ المجتمعات، لكنّه يصبح خطراً عندما يتفاقم ويستمرّ، فيهدّد وحدة الأسرة واستقرارها وقدرتها على تحقيق أهداف أعضائها. من مظاهر التفكّك: ارتفاع حالات الطلاق، وتزايد حالات الانتحار.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16207, 2604, 1, '١- الميدان العاطفي والنفسي: اختلاف الطباع بين الزوجين وضعف المودّة والاحترام، أو شجار الأبناء للاستئثار بالمكاسب. ٢- الميدان الاقتصادي (تضاؤل الموارد): تدنّي الدخل وضيق المسكن ومقارنة الأسرة بأسر أغنى منها. ٣- الميدان الاجتماعي (صراع الأجيال): سعي المراهقين إلى التغيير واعتراض الكبار باسم التقاليد وثقافة المجتمع.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16208, 2604, 2, '١- الميدان العاطفي والنفسي: اختلاف الطباع بين الزوجين وضعف المودّة والاحترام، أو شجار الأبناء للاستئثار بالمكاسب. ٢- الميدان الاقتصادي (تضاؤل الموارد): تدنّي الدخل وضيق المسكن ومقارنة الأسرة بأسر أغنى منها. ٣- الميدان الاجتماعي (صراع الأجيال): سعي المراهقين إلى التغيير واعتراض الكبار باسم التقاليد وثقافة المجتمع.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16209, 2605, 1, 'يبدأ ذلك بتحديد السبب، وهو اختلاف الطباع وضعف المودّة والاحترام. وإخماد النزاع (القمع) لا يكفي لأنّه لا يعالج أسبابه. لذلك يُركن إلى المشورة والتشارك العاطفي داخل الأسرة، وتُعزّز أجواء المودّة والاحترام، في إطار الحوار والاعتراف العادل بالخلافات.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16210, 2605, 2, 'يبدأ ذلك بتحديد السبب، وهو اختلاف الطباع وضعف المودّة والاحترام. وإخماد النزاع (القمع) لا يكفي لأنّه لا يعالج أسبابه. لذلك يُركن إلى المشورة والتشارك العاطفي داخل الأسرة، وتُعزّز أجواء المودّة والاحترام، في إطار الحوار والاعتراف العادل بالخلافات.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16211, 2606, 1, 'نعم. لأنّ الإنسان كائن اجتماعيّ وشخصيّ منشطر بين قطبين متضادّين، والعلاقات الإنسانيّة تقوم عادةً على أرضيّة من الصراع والتناقض والتوتّر. لذلك فالنزاع ليس حادثاً عابراً، بل الوضع النزاعيّ مستمرّ في الزمن وشامل نواحي الحياة كافّة.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16212, 2606, 2, 'نعم. لأنّ الإنسان كائن اجتماعيّ وشخصيّ منشطر بين قطبين متضادّين، والعلاقات الإنسانيّة تقوم عادةً على أرضيّة من الصراع والتناقض والتوتّر. لذلك فالنزاع ليس حادثاً عابراً، بل الوضع النزاعيّ مستمرّ في الزمن وشامل نواحي الحياة كافّة.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16213, 2607, 1, '١- مصادر نفسيّة أو ذهنيّة: سوء الاتّصال، اختلاف النظرة، سوء الفهم (مثل اختلاف الإدراك في رسم الصبيّة والعجوز). ٢- حاجات ومصالح مادّيّة: انتهاك الحقوق، الطمع والاستغلال، الحرمان، عدم المساواة. ٣- مبادئ وتوجّهات معنويّة: التيّارات الإيديولوجيّة والسياسيّة، المبادئ الدينيّة والقوميّة والوطنيّة. ٤- طبيعة العلاقات بين الناس: التحكّم والهيمنة والتسلّط، التنافس على النفوذ والثروة (مثل الحروب الاستعماريّة).', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16214, 2607, 2, '١- مصادر نفسيّة أو ذهنيّة: سوء الاتّصال، اختلاف النظرة، سوء الفهم (مثل اختلاف الإدراك في رسم الصبيّة والعجوز). ٢- حاجات ومصالح مادّيّة: انتهاك الحقوق، الطمع والاستغلال، الحرمان، عدم المساواة. ٣- مبادئ وتوجّهات معنويّة: التيّارات الإيديولوجيّة والسياسيّة، المبادئ الدينيّة والقوميّة والوطنيّة. ٤- طبيعة العلاقات بين الناس: التحكّم والهيمنة والتسلّط، التنافس على النفوذ والثروة (مثل الحروب الاستعماريّة).', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16215, 2608, 1, 'عناصر النزاع: طرفان على الأقلّ، وموضوع واحد يدور حوله النزاع، وتعارض في الرغبات والحاجات والرؤية والإدراك. في نصّ جيرار: الأطراف هم الأطفال في الغرفة، والموضوع هو اللعبة ذاتها، والتعارض قائم في الرغبات إذ يرغب كلّ منهم في الحصول على اللعبة التي اختارها رفيقه.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16216, 2608, 2, 'عناصر النزاع: طرفان على الأقلّ، وموضوع واحد يدور حوله النزاع، وتعارض في الرغبات والحاجات والرؤية والإدراك. في نصّ جيرار: الأطراف هم الأطفال في الغرفة، والموضوع هو اللعبة ذاتها، والتعارض قائم في الرغبات إذ يرغب كلّ منهم في الحصول على اللعبة التي اختارها رفيقه.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16217, 2609, 1, 'المرحلة الأولى: اتّهامات حول موضوع المشكلة وبداية تأزّم الوضع. المرحلة الثانية: يقع الطرف الآخر في فخّ الانفعال والمبارزة والتحدّي. المرحلة الثالثة: يصل الطرفان بسرعة إلى وضعيّة العراك. والنتيجة: غالب ومهزوم، أو يخرج الطرفان مهزومَين معاً.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16218, 2609, 2, 'المرحلة الأولى: اتّهامات حول موضوع المشكلة وبداية تأزّم الوضع. المرحلة الثانية: يقع الطرف الآخر في فخّ الانفعال والمبارزة والتحدّي. المرحلة الثالثة: يصل الطرفان بسرعة إلى وضعيّة العراك. والنتيجة: غالب ومهزوم، أو يخرج الطرفان مهزومَين معاً.', 1, '2026-09-30 22:13:01', '2026-09-30 22:13:01'),
(16219, 2610, 1, 'الوساطة اشتراك طرف ثالث في الحوار والمفاوضات بين طرفين لمساعدتهما على بلوغ مرحلة الحلول. يساعدهما الوسيط على: إعادة توضيح المشكلة كما حصلت، واستكشاف الحاجات الحقيقيّة لكلّ منهما، وإيضاح الالتباسات ورفض الافتراضات اللاعقلانيّة، واستكشاف النقاط المشتركة، واستعادة اللقاء والاتّصال. والوسيط ليس بديلاً عن الطرفين، وليس قاضياً ولا حكماً، وليس مسؤولاً عن إيجاد الحلّ.', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16220, 2610, 2, 'الوساطة اشتراك طرف ثالث في الحوار والمفاوضات بين طرفين لمساعدتهما على بلوغ مرحلة الحلول. يساعدهما الوسيط على: إعادة توضيح المشكلة كما حصلت، واستكشاف الحاجات الحقيقيّة لكلّ منهما، وإيضاح الالتباسات ورفض الافتراضات اللاعقلانيّة، واستكشاف النقاط المشتركة، واستعادة اللقاء والاتّصال. والوسيط ليس بديلاً عن الطرفين، وليس قاضياً ولا حكماً، وليس مسؤولاً عن إيجاد الحلّ.', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16221, 2611, 1, 'الوقت عامل حاسم في مسار النزاع؛ ففي لحظة النزاع ترتفع الأصوات وتسيطر ردود الفعل، والمشاكل الحادّة تحتاج إلى وقت لتدوير زواياها الحادّة وتبريد الانفعالات والغضب، وهذا يمهّد لإعادة إعمال العقل والحوار (العدّ للعشرة).', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16222, 2611, 2, 'الوقت عامل حاسم في مسار النزاع؛ ففي لحظة النزاع ترتفع الأصوات وتسيطر ردود الفعل، والمشاكل الحادّة تحتاج إلى وقت لتدوير زواياها الحادّة وتبريد الانفعالات والغضب، وهذا يمهّد لإعادة إعمال العقل والحوار (العدّ للعشرة).', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16223, 2612, 1, 'المساواة: لم يخاطب الأب ابنه من فوق، ولم يكن الابن في موقع أدنى، بل بدا الاثنان متساويين. الإصغاء: عاش الأب مشاعر ابنه وحاجاته من موقع الابن، ثمّ انطلق يوضح رأيه (أنّه يحبّ أن يقدّم له درّاجة لكنّه غير قادر الآن). والنتيجة تفاهم وقبول.', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16224, 2612, 2, 'المساواة: لم يخاطب الأب ابنه من فوق، ولم يكن الابن في موقع أدنى، بل بدا الاثنان متساويين. الإصغاء: عاش الأب مشاعر ابنه وحاجاته من موقع الابن، ثمّ انطلق يوضح رأيه (أنّه يحبّ أن يقدّم له درّاجة لكنّه غير قادر الآن). والنتيجة تفاهم وقبول.', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16225, 2613, 1, 'ثلاثة ممّا يلي: الاتّهام (قول الأب: أنت لا تكتفي يوماً بما لديك)؛ قلّة الاكتراث بحاجة الآخر ومشاعره (لم يهتمّ بحاجة الابن)؛ إغفال موضوع المشكلة (انتقل إلى الدروس ووسائل التسلية)؛ عدم الوقوف على حقيقة المطلب واقتراح الحلول (لم يقترح حلّاً).', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16226, 2613, 2, 'ثلاثة ممّا يلي: الاتّهام (قول الأب: أنت لا تكتفي يوماً بما لديك)؛ قلّة الاكتراث بحاجة الآخر ومشاعره (لم يهتمّ بحاجة الابن)؛ إغفال موضوع المشكلة (انتقل إلى الدروس ووسائل التسلية)؛ عدم الوقوف على حقيقة المطلب واقتراح الحلول (لم يقترح حلّاً).', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16227, 2614, 1, 'الحوار سبيل ديمقراطيّ سلميّ لحلّ النزاعات؛ فهو يهدم جدار الخلاف بين المتنازعين، ويعطي الحقائق أحجامها الحقيقيّة دون تضخيم، ويساعد على بناء اتّفاقات تحلّ النزاعات وتكون قابلة للحياة، ويتيح للطرفين التعبير عن مشاعرهما وأمانيهما. وبدونه يصعب الوصول إلى مناخ من التفاهم يعطّل فتيل النزاع وينهي القطيعة.', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16228, 2614, 2, 'الحوار سبيل ديمقراطيّ سلميّ لحلّ النزاعات؛ فهو يهدم جدار الخلاف بين المتنازعين، ويعطي الحقائق أحجامها الحقيقيّة دون تضخيم، ويساعد على بناء اتّفاقات تحلّ النزاعات وتكون قابلة للحياة، ويتيح للطرفين التعبير عن مشاعرهما وأمانيهما. وبدونه يصعب الوصول إلى مناخ من التفاهم يعطّل فتيل النزاع وينهي القطيعة.', 1, '2026-09-30 22:13:02', '2026-09-30 22:13:02'),
(16229, 2615, 1, 'بحلّ النزاعات بالوسائل السلميّة كما دعا ميثاق الأمم المتحدة، كالحوار والمفاوضات والوساطات والتحكيم. ومن سبل الأمم المتحدة: الدبلوماسيّة الوقائيّة التي تمنع نشوب النزاع، وصنع السلام الذي يسوّيه بالطرائق السلميّة، وحفظ السلام الذي يضع أفراداً بين الأطراف المتعادية لمراقبته، وبناء السلام الذي يبني الثقة بالتعمير والمصالحة. ويمكن أيضاً اللجوء إلى محكمة العدل الدوليّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16230, 2615, 2, 'بحلّ النزاعات بالوسائل السلميّة كما دعا ميثاق الأمم المتحدة، كالحوار والمفاوضات والوساطات والتحكيم. ومن سبل الأمم المتحدة: الدبلوماسيّة الوقائيّة التي تمنع نشوب النزاع، وصنع السلام الذي يسوّيه بالطرائق السلميّة، وحفظ السلام الذي يضع أفراداً بين الأطراف المتعادية لمراقبته، وبناء السلام الذي يبني الثقة بالتعمير والمصالحة. ويمكن أيضاً اللجوء إلى محكمة العدل الدوليّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16231, 2616, 1, 'لا. فالعنف المباشر ليس طريق العلاج، بل يكون العلاج بضغط جماعي سلمي. وإصدار القوانين وحده لا يكفي، لأنّ العنف الاجتماعي يظهر في المؤسّسات والقوانين نفسها ويكرّسه المجتمع في قيمه وعاداته، والقوانين لا تفيد إلّا إذا عُرفت وطُبّقت؛ لذلك يُمارَس الضغط الجماعي السلمي لفرض تطبيق القانون أو تعديله. والحلّ السليم هو الإنماء المتوازن، لأنّ الفروقات المتراكمة تزيد من احتمال النزاع.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16232, 2616, 2, 'لا. فالعنف المباشر ليس طريق العلاج، بل يكون العلاج بضغط جماعي سلمي. وإصدار القوانين وحده لا يكفي، لأنّ العنف الاجتماعي يظهر في المؤسّسات والقوانين نفسها ويكرّسه المجتمع في قيمه وعاداته، والقوانين لا تفيد إلّا إذا عُرفت وطُبّقت؛ لذلك يُمارَس الضغط الجماعي السلمي لفرض تطبيق القانون أو تعديله. والحلّ السليم هو الإنماء المتوازن، لأنّ الفروقات المتراكمة تزيد من احتمال النزاع.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16233, 2617, 1, '١- القانون معيار الحقوق والواجبات. ٢- يعيّن الحقوق ويرسم حدودها ويؤمّن ضماناتها، ويضع قوّة الإكراه التي تتمتّع بها السلطة العامّة في خدمة حقوق المواطن وحريّاته. ٣- به انتقل البشر من العدالة الخاصّة (الثأر والانتقام) إلى العدالة العامّة (المحاكم والتنظيم القضائي). وهو مرجع الدول أيضاً، إذ تفصل محكمة العدل الدوليّة وفق القانون الدولي.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16234, 2617, 2, '١- القانون معيار الحقوق والواجبات. ٢- يعيّن الحقوق ويرسم حدودها ويؤمّن ضماناتها، ويضع قوّة الإكراه التي تتمتّع بها السلطة العامّة في خدمة حقوق المواطن وحريّاته. ٣- به انتقل البشر من العدالة الخاصّة (الثأر والانتقام) إلى العدالة العامّة (المحاكم والتنظيم القضائي). وهو مرجع الدول أيضاً، إذ تفصل محكمة العدل الدوليّة وفق القانون الدولي.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16235, 2618, 1, 'الثأر هو الانتقام لشخص المجني عليه من الجاني أو من أحد أقاربه المقرّبين، على يد الأقرباء الخُلّص للمجني عليه. وهو معالجة ذاتيّة للنزاع يتولّاها أقرباء الضحيّة بدل السلطة القضائيّة، أي عدم اعتراف بالسلطة القانونيّة الرسميّة، ولهذا يسمّى عدالة خاصّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16236, 2618, 2, 'الثأر هو الانتقام لشخص المجني عليه من الجاني أو من أحد أقاربه المقرّبين، على يد الأقرباء الخُلّص للمجني عليه. وهو معالجة ذاتيّة للنزاع يتولّاها أقرباء الضحيّة بدل السلطة القضائيّة، أي عدم اعتراف بالسلطة القانونيّة الرسميّة، ولهذا يسمّى عدالة خاصّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16237, 2619, 1, 'مثلاً: العريضة (العريضة الوطنيّة في مصر أيّام الاحتلال البريطانيّ للمطالبة بمشاركتها في مؤتمر فرساي)؛ الاعتصام (اعتصام النساء في هولندا لفرض منحهنّ حقّ الاقتراع)؛ المقاطعة (مقاطعة الملبوسات والملح الإنكليزيّ في الهند). الرأي: هذه الوسائل تتوجّه إلى العقل والضمير، وقد حقّقت نتائج دون أن تدمّر أحداً.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16238, 2619, 2, 'مثلاً: العريضة (العريضة الوطنيّة في مصر أيّام الاحتلال البريطانيّ للمطالبة بمشاركتها في مؤتمر فرساي)؛ الاعتصام (اعتصام النساء في هولندا لفرض منحهنّ حقّ الاقتراع)؛ المقاطعة (مقاطعة الملبوسات والملح الإنكليزيّ في الهند). الرأي: هذه الوسائل تتوجّه إلى العقل والضمير، وقد حقّقت نتائج دون أن تدمّر أحداً.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16239, 2620, 1, 'العنف لا يحلّ النزاعات. الحجّة الأولى: العنف يثير العنف، ويسيء إلى من يلجأ إليه وإلى من يتلقّاه، فهو تدمير للاثنين معاً. الحجّة الثانية: الثأر عدالة خاصّة لا تعترف بالقانون، وقد يصيب شخصاً لا علاقة له بالحادثة. البديل: اللجوء إلى عدالة القانون، واعتماد الوسائل المدنيّة اللاعنفيّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16240, 2620, 2, 'العنف لا يحلّ النزاعات. الحجّة الأولى: العنف يثير العنف، ويسيء إلى من يلجأ إليه وإلى من يتلقّاه، فهو تدمير للاثنين معاً. الحجّة الثانية: الثأر عدالة خاصّة لا تعترف بالقانون، وقد يصيب شخصاً لا علاقة له بالحادثة. البديل: اللجوء إلى عدالة القانون، واعتماد الوسائل المدنيّة اللاعنفيّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16241, 2621, 1, 'الملك العامّ هو الأشياء المعدّة لاستعمال الجميع أو لتأمين مصلحة عموميّة، مثل: الطرق العامّة، الشاطئ، مياه الأنهر ومجاريها، وسائل النقل العامّ، الساحات العامّة. الملك الخاصّ هو ما يملكه فرد، مثل: المسكن، السيارة الخاصّة، الحديقة الخاصّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16242, 2621, 2, 'الملك العامّ هو الأشياء المعدّة لاستعمال الجميع أو لتأمين مصلحة عموميّة، مثل: الطرق العامّة، الشاطئ، مياه الأنهر ومجاريها، وسائل النقل العامّ، الساحات العامّة. الملك الخاصّ هو ما يملكه فرد، مثل: المسكن، السيارة الخاصّة، الحديقة الخاصّة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16243, 2622, 1, 'الحديقة العامّة ملك عامّ معدّ لاستعمال الجميع، ومن واجب المواطن حماية الملك العامّ واحترامه، لذلك أنبّه العائلة بهدوء واحترام. وهذا التصرّف يضرّ بالمصلحة العامّة لأنّه يعتدي على ملك معدّ لاستعمال الجميع ويحرم الآخرين من الانتفاع بالحديقة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16244, 2622, 2, 'الحديقة العامّة ملك عامّ معدّ لاستعمال الجميع، ومن واجب المواطن حماية الملك العامّ واحترامه، لذلك أنبّه العائلة بهدوء واحترام. وهذا التصرّف يضرّ بالمصلحة العامّة لأنّه يعتدي على ملك معدّ لاستعمال الجميع ويحرم الآخرين من الانتفاع بالحديقة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16245, 2623, 1, 'المبادئ (اثنان ممّا يلي): تأمين الاستمراريّة، تحقيق المساواة بين المنتفعين، تطوير أداء الخدمات العامّة، مضاعفة الشفافية وتبسيط المعاملات وتسهيل الحصول على الخدمات، مشاركة المستفيدين في مراقبة الأداء وإدارة المرافق. الواجبات (ثلاثة ممّا يلي): حماية الملك العامّ واحترامه، الاهتمام بالشأن العامّ، دفع الضرائب، مراقبة أعمال السلطة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16246, 2623, 2, 'المبادئ (اثنان ممّا يلي): تأمين الاستمراريّة، تحقيق المساواة بين المنتفعين، تطوير أداء الخدمات العامّة، مضاعفة الشفافية وتبسيط المعاملات وتسهيل الحصول على الخدمات، مشاركة المستفيدين في مراقبة الأداء وإدارة المرافق. الواجبات (ثلاثة ممّا يلي): حماية الملك العامّ واحترامه، الاهتمام بالشأن العامّ، دفع الضرائب، مراقبة أعمال السلطة.', 1, '2026-09-30 22:13:03', '2026-09-30 22:13:03'),
(16247, 2624, 1, 'تؤمّن المرافق العامّة الحاجات للجميع بصورة متكافئة تحقيقاً للمساواة ومنعاً للاحتكار. لكنّ إشباع هذه الحاجات يتوقّف بدرجة كبيرة على إمكانيّات الدولة الماديّة، لذلك تحتاج الدولة إلى وضع سلّم أولويّات، وتأمين حسن إدارة إمكانيّاتها، وإيجاد سياسة ضريبيّة عادلة.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16248, 2624, 2, 'تؤمّن المرافق العامّة الحاجات للجميع بصورة متكافئة تحقيقاً للمساواة ومنعاً للاحتكار. لكنّ إشباع هذه الحاجات يتوقّف بدرجة كبيرة على إمكانيّات الدولة الماديّة، لذلك تحتاج الدولة إلى وضع سلّم أولويّات، وتأمين حسن إدارة إمكانيّاتها، وإيجاد سياسة ضريبيّة عادلة.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16249, 2625, 1, 'نظريّاً: شارك لبنان في وضع الإعلان العالميّ لحقوق الإنسان والتزمه في مقدّمة دستوره، ووقّع عهوداً ومواثيق دوليّة كثيرة. واقعيّاً: المجّانيّة لم تتحقّق إلّا في المدارس الرسميّة وبعض المدارس الخاصّة المدعومة من الدولة والجامعة اللبنانيّة، ومعدّل الأمّيّة متفاوت بين الذكور والإناث.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16250, 2625, 2, 'نظريّاً: شارك لبنان في وضع الإعلان العالميّ لحقوق الإنسان والتزمه في مقدّمة دستوره، ووقّع عهوداً ومواثيق دوليّة كثيرة. واقعيّاً: المجّانيّة لم تتحقّق إلّا في المدارس الرسميّة وبعض المدارس الخاصّة المدعومة من الدولة والجامعة اللبنانيّة، ومعدّل الأمّيّة متفاوت بين الذكور والإناث.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16251, 2626, 1, 'التربية حقّ أقرّه الإعلان العالميّ لحقوق الإنسان، وهي واجب لأنّها تؤدّي خدمات جُلّى للمجتمع: فهي تغني الرأسمال البشريّ وتسهم في نموّه، وتدعم النظام الديمقراطيّ والتفاعل بين المواطنين والتماسك الاجتماعيّ، وتشجّع النقد لدى التلاميذ والطلاب وتعزّز اتّجاهات التسامح.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16252, 2626, 2, 'التربية حقّ أقرّه الإعلان العالميّ لحقوق الإنسان، وهي واجب لأنّها تؤدّي خدمات جُلّى للمجتمع: فهي تغني الرأسمال البشريّ وتسهم في نموّه، وتدعم النظام الديمقراطيّ والتفاعل بين المواطنين والتماسك الاجتماعيّ، وتشجّع النقد لدى التلاميذ والطلاب وتعزّز اتّجاهات التسامح.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16253, 2627, 1, 'الخدمات: الماء، الكهرباء، الاتّصالات، المواصلات، النظافة العامّة (التخلّص من النفايات والمياه المبتذلة). فائدتان: تؤمّن الراحة للمواطنين؛ النظافة تحمي الصحّة وتقي من الأمراض؛ الاتّصالات والمواصلات تسهّل الخدمات وتختصر المسافات والوقت.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16254, 2627, 2, 'الخدمات: الماء، الكهرباء، الاتّصالات، المواصلات، النظافة العامّة (التخلّص من النفايات والمياه المبتذلة). فائدتان: تؤمّن الراحة للمواطنين؛ النظافة تحمي الصحّة وتقي من الأمراض؛ الاتّصالات والمواصلات تسهّل الخدمات وتختصر المسافات والوقت.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16255, 2628, 1, 'أربعة ممّا يلي: التقيّد بإشارات السير الكهربائيّة وبإشارة رجل الأمن؛ التزام الجانب الأيمن عندما تكون الرؤية غير كافية؛ إضاءة المصابيح ليلاً أو وقت الضباب؛ عدم القيادة دون رخصة؛ الامتناع عن القيادة في حالة سكر؛ تجهيز المركبة بالمصابيح ومكابح صالحة؛ ترك مسافة أمان. هدف قانون السير: تأمين سلامة السائقين والمشاة معاً والحدّ من المخاطر والحفاظ على أرواح الناس.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16256, 2628, 2, 'أربعة ممّا يلي: التقيّد بإشارات السير الكهربائيّة وبإشارة رجل الأمن؛ التزام الجانب الأيمن عندما تكون الرؤية غير كافية؛ إضاءة المصابيح ليلاً أو وقت الضباب؛ عدم القيادة دون رخصة؛ الامتناع عن القيادة في حالة سكر؛ تجهيز المركبة بالمصابيح ومكابح صالحة؛ ترك مسافة أمان. هدف قانون السير: تأمين سلامة السائقين والمشاة معاً والحدّ من المخاطر والحفاظ على أرواح الناس.', 1, '2026-09-30 22:13:04', '2026-09-30 22:13:04'),
(16257, 2629, 1, 'أربعة ممّا يلي: عدم هدر الماء والكهرباء؛ المحافظة على أجهزة الاتّصالات؛ تسديد الفواتير والبدلات الماليّة؛ احترام قوانين السير؛ الامتناع عن تلويث البيئة ورمي النفايات في غير أماكنها؛ عدم التعدّي على المرافق العامّة.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16258, 2629, 2, 'أربعة ممّا يلي: عدم هدر الماء والكهرباء؛ المحافظة على أجهزة الاتّصالات؛ تسديد الفواتير والبدلات الماليّة؛ احترام قوانين السير؛ الامتناع عن تلويث البيئة ورمي النفايات في غير أماكنها؛ عدم التعدّي على المرافق العامّة.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16259, 2630, 1, 'ملك عام: البحر، المياه، الشاطئ. ملك خاص: الأرض، الأحراج. ويُقيَّد التصرّف بالملك الخاص لأنّ الضرر بالثروة الطبيعيّة ينعكس سلباً على مقوّمات الحياة للجميع، لذلك نحتاج إلى ضوابط توازن بين المصلحة الفرديّة والمصلحة العامّة.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16260, 2630, 2, 'ملك عام: البحر، المياه، الشاطئ. ملك خاص: الأرض، الأحراج. ويُقيَّد التصرّف بالملك الخاص لأنّ الضرر بالثروة الطبيعيّة ينعكس سلباً على مقوّمات الحياة للجميع، لذلك نحتاج إلى ضوابط توازن بين المصلحة الفرديّة والمصلحة العامّة.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16261, 2631, 1, 'للشاطئ أدوار: ثروة بيئيّة (مساحات رمليّة وصخريّة وثروة نباتيّة وحيوانيّة)، مورد سياحي وترفيهي، دور اقتصادي عبر المرافئ، وهو ملك عام وفسحة تلاقٍ بين المواطنين كافّة. البناء عليه يحجب رؤية البحر ويقطع تواصل الشاطئ فيحرم المواطنين من الانتفاع بملك عام. العقوبة: الحبس من أربعين يوماً إلى سنة ونصف السنة، مع إعادة الحال إلى ما كانت عليه والغرامات.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16262, 2631, 2, 'للشاطئ أدوار: ثروة بيئيّة (مساحات رمليّة وصخريّة وثروة نباتيّة وحيوانيّة)، مورد سياحي وترفيهي، دور اقتصادي عبر المرافئ، وهو ملك عام وفسحة تلاقٍ بين المواطنين كافّة. البناء عليه يحجب رؤية البحر ويقطع تواصل الشاطئ فيحرم المواطنين من الانتفاع بملك عام. العقوبة: الحبس من أربعين يوماً إلى سنة ونصف السنة، مع إعادة الحال إلى ما كانت عليه والغرامات.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16263, 2632, 1, '١- عدم تصريف المياه المبتذلة في مجاري المياه قبل معالجتها، لأنّ القانون يعاقب على ذلك. ٢- على الدولة تطبيق القانون وتأهيل خدمات المياه وحسن إدارتها. ٣- على المواطن حسن الاستعمال وعدم رمي النفايات في الأنهر والبحر. والهدف حماية الصحّة العامّة ومصلحة الأجيال الحاضرة والمقبلة.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16264, 2632, 2, '١- عدم تصريف المياه المبتذلة في مجاري المياه قبل معالجتها، لأنّ القانون يعاقب على ذلك. ٢- على الدولة تطبيق القانون وتأهيل خدمات المياه وحسن إدارتها. ٣- على المواطن حسن الاستعمال وعدم رمي النفايات في الأنهر والبحر. والهدف حماية الصحّة العامّة ومصلحة الأجيال الحاضرة والمقبلة.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16265, 2633, 1, 'التراث الطبيعيّ هو عطاء الطبيعة، مثل المواقع الطبيعيّة والأحراج والتنوّع البيولوجيّ (مثال: محميّة حرج إهدن). التراث الثقافيّ من صنع الإنسان، يتكوّن مع كلّ حضارة وكلّ عصر، مثل القلاع والمعابد والقصور (مثال: مباني بعلبك التاريخيّة). والنوعان يتكاملان ولا ينفصلان.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16266, 2633, 2, 'التراث الطبيعيّ هو عطاء الطبيعة، مثل المواقع الطبيعيّة والأحراج والتنوّع البيولوجيّ (مثال: محميّة حرج إهدن). التراث الثقافيّ من صنع الإنسان، يتكوّن مع كلّ حضارة وكلّ عصر، مثل القلاع والمعابد والقصور (مثال: مباني بعلبك التاريخيّة). والنوعان يتكاملان ولا ينفصلان.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16267, 2634, 1, 'لأنّها غنيّة بالتنوّع البيولوجيّ، وتحمي التربة من الانجراف، وتضبط ثاني أوكسيد الكربون. من الإجراءات: منع قطع الأشجار ونزع العشب؛ منع إضرام النار ورمي النفايات؛ وجوب الحصول على ترخيص مسبق من وزارة الزراعة لقطع أيّ شجرة حرجيّة تحت طائلة الحبس (وتخضع حتّى الأحراج الخاصّة لهذه الضوابط).', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16268, 2634, 2, 'لأنّها غنيّة بالتنوّع البيولوجيّ، وتحمي التربة من الانجراف، وتضبط ثاني أوكسيد الكربون. من الإجراءات: منع قطع الأشجار ونزع العشب؛ منع إضرام النار ورمي النفايات؛ وجوب الحصول على ترخيص مسبق من وزارة الزراعة لقطع أيّ شجرة حرجيّة تحت طائلة الحبس (وتخضع حتّى الأحراج الخاصّة لهذه الضوابط).', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16269, 2635, 1, 'لبنان غنيّ بتنوّعه البيولوجيّ بفضل موقعه ومناخاته وتكوينه الجيولوجيّ، وهذا التنوّع ينفع في الغذاء والصناعة والطبّ، لذلك فهو ثروة وطنيّة عامّة (وقد وقّع لبنان اتفاقيّة ريو للحفاظ عليه). يهدّده إتلاف الأحراج وتهديم الطبيعة وشفط الرمل وردم البحر. ومن سبل حمايته: حماية المياه من الاستنزاف والتلوّث، وتنظيم عمل المقالع والكسّارات والمرامل.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16270, 2635, 2, 'لبنان غنيّ بتنوّعه البيولوجيّ بفضل موقعه ومناخاته وتكوينه الجيولوجيّ، وهذا التنوّع ينفع في الغذاء والصناعة والطبّ، لذلك فهو ثروة وطنيّة عامّة (وقد وقّع لبنان اتفاقيّة ريو للحفاظ عليه). يهدّده إتلاف الأحراج وتهديم الطبيعة وشفط الرمل وردم البحر. ومن سبل حمايته: حماية المياه من الاستنزاف والتلوّث، وتنظيم عمل المقالع والكسّارات والمرامل.', 1, '2026-09-30 22:13:05', '2026-09-30 22:13:05'),
(16271, 2636, 1, 'الفقر حالة حرمان من واحدة أو أكثر من الاحتياجات الإنسانيّة الأساسيّة، كالغذاء ومياه الشرب المأمونة والمسكن والخدمات التي تلبّي حاجات الإنسان وحقوقه الأساسيّة. المعيار هو خطّ الفقر (الخطّ الأدنى للفقر)، أي العيش بأقلّ من دولار واحد يوميّاً.', 1, '2026-09-30 22:13:06', '2026-09-30 22:13:06'),
(16272, 2636, 2, 'الفقر حالة حرمان من واحدة أو أكثر من الاحتياجات الإنسانيّة الأساسيّة، كالغذاء ومياه الشرب المأمونة والمسكن والخدمات التي تلبّي حاجات الإنسان وحقوقه الأساسيّة. المعيار هو خطّ الفقر (الخطّ الأدنى للفقر)، أي العيش بأقلّ من دولار واحد يوميّاً.', 1, '2026-09-30 22:13:06', '2026-09-30 22:13:06'),
(16273, 2637, 1, 'يتركّز الفقر المدقع في أقضية بعلبك والهرمل وعكّار. من مظاهره: في السكن، مساكن مدمّرة جزئيّاً بسبب الحرب أو الإهمال، وكثافة غير مقبولة، ونقص في شبكتي المجارير ومياه الشفة؛ وفي الصحّة، أمراض مزمنة وتكرّر حالات المرض بسبب عدم القدرة على تحمّل أعباء العلاج وبسبب الإهمال والجهل.', 1, '2026-09-30 22:13:06', '2026-09-30 22:13:06'),
(16274, 2637, 2, 'يتركّز الفقر المدقع في أقضية بعلبك والهرمل وعكّار. من مظاهره: في السكن، مساكن مدمّرة جزئيّاً بسبب الحرب أو الإهمال، وكثافة غير مقبولة، ونقص في شبكتي المجارير ومياه الشفة؛ وفي الصحّة، أمراض مزمنة وتكرّر حالات المرض بسبب عدم القدرة على تحمّل أعباء العلاج وبسبب الإهمال والجهل.', 1, '2026-09-30 22:13:06', '2026-09-30 22:13:06'),
(16275, 2638, 1, 'من نتائج الفقر (ثلاث): الجوع وسوء التغذية، الجهل، اعتلال الصحّة وانتشار الأمراض، عدم السلامة البيئيّة، الرضوخ الاجتماعيّ. من وسائل المعالجة (اثنتان): جعل الأمن الغذائيّ للجميع هدفاً أساسيّاً للدول والمنظّمات الدوليّة؛ مواجهة الهدر في الموارد الغذائيّة؛ التحكّم بالموارد الطبيعيّة؛ توجيه التعاون الدوليّ لوضع منجزات التكنولوجيا في خدمة الفقراء وتحسين شروط حياتهم.', 1, '2026-09-30 22:13:06', '2026-09-30 22:13:06'),
(16276, 2638, 2, 'من نتائج الفقر (ثلاث): الجوع وسوء التغذية، الجهل، اعتلال الصحّة وانتشار الأمراض، عدم السلامة البيئيّة، الرضوخ الاجتماعيّ. من وسائل المعالجة (اثنتان): جعل الأمن الغذائيّ للجميع هدفاً أساسيّاً للدول والمنظّمات الدوليّة؛ مواجهة الهدر في الموارد الغذائيّة؛ التحكّم بالموارد الطبيعيّة؛ توجيه التعاون الدوليّ لوضع منجزات التكنولوجيا في خدمة الفقراء وتحسين شروط حياتهم.', 1, '2026-09-30 22:13:06', '2026-09-30 22:13:06'),
(16277, 2639, 1, 'المناعة مقاومة ترتبط بوجود أضداد. وفيروس السيدا يهاجم جهاز المناعة ويعطّل وظائفه، فيبقى الجسم بلا دفاع أمام الميكروبات والأمراض والأورام ويصبح ضحيّة لها، ولا يوجد حتّى اليوم دواء شافٍ ولا لقاح.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16278, 2639, 2, 'المناعة مقاومة ترتبط بوجود أضداد. وفيروس السيدا يهاجم جهاز المناعة ويعطّل وظائفه، فيبقى الجسم بلا دفاع أمام الميكروبات والأمراض والأورام ويصبح ضحيّة لها، ولا يوجد حتّى اليوم دواء شافٍ ولا لقاح.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16279, 2640, 1, 'لا، فهي ضروريّة لكنّها غير كافية. الحجّة الأولى: الإدمان مؤشّر على أوضاع صعبة كالانسحاب من العالم الواقعيّ واليأس من الحياة والحاجة إلى العطف والحنان، والشرطة لا تعالج هذه الأوضاع. الحجّة الثانية: تزايد استخدام المخدّرات رغم إجراءات الحكومات والمنظّمات. البديل: التوعية، وإجراءات اجتماعيّة لتحسين الأوضاع، ودعم برامج التنمية الدوليّة للقضاء على زراعة المخدّرات.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16280, 2640, 2, 'لا، فهي ضروريّة لكنّها غير كافية. الحجّة الأولى: الإدمان مؤشّر على أوضاع صعبة كالانسحاب من العالم الواقعيّ واليأس من الحياة والحاجة إلى العطف والحنان، والشرطة لا تعالج هذه الأوضاع. الحجّة الثانية: تزايد استخدام المخدّرات رغم إجراءات الحكومات والمنظّمات. البديل: التوعية، وإجراءات اجتماعيّة لتحسين الأوضاع، ودعم برامج التنمية الدوليّة للقضاء على زراعة المخدّرات.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16281, 2641, 1, 'ثلاثة ممّا يلي: صحّيّاً، يُضعف الإدمان الجسم ويضرّ بالصحّة؛ عقليّاً، يخدّر العقل ويضيّع الرشد؛ أخلاقيّاً، يرفع الزواجر الأخلاقيّة ويحمل على تصرّفات شاذّة؛ تربويّاً، يخفض معدّل التحصيل؛ إنتاجيّاً، يضرّ بالتنمية لأنّ معظم المدمنين من الشباب فيُصرفون من العمل ويتعرّضون لحوادث السير؛ سلوكيّاً، يرتبط به كثير من أعمال العنف كالسطو والسلب؛ ديموغرافيّاً، تزداد الوفيات الناتجة عن الجرعة الزائدة.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16282, 2641, 2, 'ثلاثة ممّا يلي: صحّيّاً، يُضعف الإدمان الجسم ويضرّ بالصحّة؛ عقليّاً، يخدّر العقل ويضيّع الرشد؛ أخلاقيّاً، يرفع الزواجر الأخلاقيّة ويحمل على تصرّفات شاذّة؛ تربويّاً، يخفض معدّل التحصيل؛ إنتاجيّاً، يضرّ بالتنمية لأنّ معظم المدمنين من الشباب فيُصرفون من العمل ويتعرّضون لحوادث السير؛ سلوكيّاً، يرتبط به كثير من أعمال العنف كالسطو والسلب؛ ديموغرافيّاً، تزداد الوفيات الناتجة عن الجرعة الزائدة.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16283, 2642, 1, 'المصادر: المنزليّة، الزراعيّة، الصناعيّة، التجاريّة، وسائل النقل. الأنواع (ثلاثة): البقايا الصلبة (الموادّ البلاستيكيّة)؛ التلوّث العضويّ (جثث الحيوانات)؛ التلوّث الكيميائيّ (دخان المصانع والغازات السامّة والأسمدة الكيماويّة)؛ التلوّث بالموادّ النفطيّة (بقع النفط المتسرّبة من الناقلات)؛ التلوّث الإشعاعيّ (الإشعاعات المتسرّبة من المفاعلات الذرّيّة كما في تشرنوبيل).', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16284, 2642, 2, 'المصادر: المنزليّة، الزراعيّة، الصناعيّة، التجاريّة، وسائل النقل. الأنواع (ثلاثة): البقايا الصلبة (الموادّ البلاستيكيّة)؛ التلوّث العضويّ (جثث الحيوانات)؛ التلوّث الكيميائيّ (دخان المصانع والغازات السامّة والأسمدة الكيماويّة)؛ التلوّث بالموادّ النفطيّة (بقع النفط المتسرّبة من الناقلات)؛ التلوّث الإشعاعيّ (الإشعاعات المتسرّبة من المفاعلات الذرّيّة كما في تشرنوبيل).', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16285, 2643, 1, 'أربعة ممّا يلي: تلوّث الهواء بعوادم السيّارات ودخان المعامل والمصانع؛ تراجع الأحراج والمراعي والمساحات الخضراء أمام هجمة الباطون والإسفلت؛ تلوّث المياه بالنفايات وبمياه الصرف الصحّيّ (خطر الكوليرا)؛ تغيير معالم الشاطئ بالمرافئ والمجمّعات السياحيّة والردم، وتدمير الثروة السمكيّة بالشباك الضيّقة والديناميت؛ أضرار الكسّارات والمرامل.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16286, 2643, 2, 'أربعة ممّا يلي: تلوّث الهواء بعوادم السيّارات ودخان المعامل والمصانع؛ تراجع الأحراج والمراعي والمساحات الخضراء أمام هجمة الباطون والإسفلت؛ تلوّث المياه بالنفايات وبمياه الصرف الصحّيّ (خطر الكوليرا)؛ تغيير معالم الشاطئ بالمرافئ والمجمّعات السياحيّة والردم، وتدمير الثروة السمكيّة بالشباك الضيّقة والديناميت؛ أضرار الكسّارات والمرامل.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(16287, 2644, 1, 'الفعاليّة البيئيّة هي استخدام موادّ أوّليّة أقلّ وإنتاج نفايات أقلّ، بهدف توفير الموارد الطبيعيّة (مثال: سيّارة تقطع مسافة أطول بكمّيّة بنزين أقلّ). والطاقة النظيفة تقوم على الاستغناء عن توليد الطاقة من الفحم الحجريّ، وإعادة تأهيل محطّات الطاقة القديمة، والاعتماد على مصادر بديلة كالشمس والرياح والمياه، فتخفّف تلوّث البيئة.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16288, 2644, 2, 'الفعاليّة البيئيّة هي استخدام موادّ أوّليّة أقلّ وإنتاج نفايات أقلّ، بهدف توفير الموارد الطبيعيّة (مثال: سيّارة تقطع مسافة أطول بكمّيّة بنزين أقلّ). والطاقة النظيفة تقوم على الاستغناء عن توليد الطاقة من الفحم الحجريّ، وإعادة تأهيل محطّات الطاقة القديمة، والاعتماد على مصادر بديلة كالشمس والرياح والمياه، فتخفّف تلوّث البيئة.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16289, 2645, 1, '١- الاستعمار: احتلال الدول الصناعيّة أراضي في مختلف القارّات والسيطرة على ثرواتها وتسخير سكّانها. ٢- الصراع للسيطرة على المناطق النفطيّة والغنيّة بالمعادن (النفط في الشرق الأوسط والمعادن في أفريقيا). ٣- الصراعات القوميّة والعرقيّة والإثنيّة (الهوتو والتوتسي). والمصالح حاضرة في هذه الأسباب كلّها، حتّى في النزاعات الإثنيّة التي قد تستغلّها دول كبرى للسيطرة على موارد الدول النامية وأسواقها.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16290, 2645, 2, '١- الاستعمار: احتلال الدول الصناعيّة أراضي في مختلف القارّات والسيطرة على ثرواتها وتسخير سكّانها. ٢- الصراع للسيطرة على المناطق النفطيّة والغنيّة بالمعادن (النفط في الشرق الأوسط والمعادن في أفريقيا). ٣- الصراعات القوميّة والعرقيّة والإثنيّة (الهوتو والتوتسي). والمصالح حاضرة في هذه الأسباب كلّها، حتّى في النزاعات الإثنيّة التي قد تستغلّها دول كبرى للسيطرة على موارد الدول النامية وأسواقها.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16291, 2646, 1, 'ثلاث ممّا يلي: الإساءة إلى استقرار البلاد وإضعاف أجهزتها؛ الضرر بالاقتصاد والنموّ؛ خسائر ماديّة بمليارات الدولارات؛ سقوط قتلى وآلاف المعاقين؛ هجرة عدد كبير من المواطنين بينهم الأدمغة واليد العاملة الماهرة وخرّيجو الجامعات. هجرة الأدمغة هي هجرة المثقّفين والفنّيّين من بلدانهم الأصليّة، وهي ظاهرة منتشرة في العالم النامي.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16292, 2646, 2, 'ثلاث ممّا يلي: الإساءة إلى استقرار البلاد وإضعاف أجهزتها؛ الضرر بالاقتصاد والنموّ؛ خسائر ماديّة بمليارات الدولارات؛ سقوط قتلى وآلاف المعاقين؛ هجرة عدد كبير من المواطنين بينهم الأدمغة واليد العاملة الماهرة وخرّيجو الجامعات. هجرة الأدمغة هي هجرة المثقّفين والفنّيّين من بلدانهم الأصليّة، وهي ظاهرة منتشرة في العالم النامي.', 1, '2026-09-30 22:13:07', '2026-09-30 22:13:07'),
(16293, 2647, 1, 'لأنّ التنمية تخفّف الصراع على الموارد والسلطة، وتحدّ من الظروف الملائمة للعنف، وهي ببعدها الاقتصادي أساس الأمن الاجتماعي والسلم الأهلي. والتنمية المتوازنة لجميع المناطق تقلّل مخاطر العنف وتحصّن وحدة المجتمع تجاه التدخّلات الخارجيّة، فهي تعالج أسباب النزاع لا نتائجه فقط.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16294, 2647, 2, 'لأنّ التنمية تخفّف الصراع على الموارد والسلطة، وتحدّ من الظروف الملائمة للعنف، وهي ببعدها الاقتصادي أساس الأمن الاجتماعي والسلم الأهلي. والتنمية المتوازنة لجميع المناطق تقلّل مخاطر العنف وتحصّن وحدة المجتمع تجاه التدخّلات الخارجيّة، فهي تعالج أسباب النزاع لا نتائجه فقط.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16295, 2648, 1, 'المصادر المتجدّدة لا تنضب عند الاستهلاك، مثل: المياه، الرياح، المدّ والجزر. المصادر غير المتجدّدة تنضب وتحتاج في تكوّنها إلى ملايين السنين، مثل: الفحم الحجري، البترول، الغاز الطبيعي، الذرّة.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16296, 2648, 2, 'المصادر المتجدّدة لا تنضب عند الاستهلاك، مثل: المياه، الرياح، المدّ والجزر. المصادر غير المتجدّدة تنضب وتحتاج في تكوّنها إلى ملايين السنين، مثل: الفحم الحجري، البترول، الغاز الطبيعي، الذرّة.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16297, 2649, 1, 'الكوكب الأزرق اسم أُطلق على الأرض لكثرة المياه فيها. لكنّ المياه العذبة لا تشكّل سوى نسبة صغيرة من مجمل مياهه والباقي مياه بحار ومحيطات مالحة، وكثير من المياه العذبة محبوس في الجليد القطبي أو مخزون في جوف الأرض. ويضاف إلى ذلك توزّعها غير المتساوي بين القارّات والدول وتزايد السكّان.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16298, 2649, 2, 'الكوكب الأزرق اسم أُطلق على الأرض لكثرة المياه فيها. لكنّ المياه العذبة لا تشكّل سوى نسبة صغيرة من مجمل مياهه والباقي مياه بحار ومحيطات مالحة، وكثير من المياه العذبة محبوس في الجليد القطبي أو مخزون في جوف الأرض. ويضاف إلى ذلك توزّعها غير المتساوي بين القارّات والدول وتزايد السكّان.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16299, 2650, 1, 'لأنّ المياه العذبة قليلة وغير موزّعة بالتساوي، والسكّان يتزايدون وحاجات الأمن الغذائي تكبر، فتشتدّ النزاعات كما في دجلة والفرات والنيل وروافد نهر الأردن. من الحلول (اثنان): ترشيد استخدام المياه وحسن إدارته؛ التحوّل نحو الطاقة النظيفة (الرياح ومساقط المياه والشمس)؛ الاقتصاد في استعمال السيّارات والمحرّكات والتوفير في الكهرباء؛ التعاون الإقليمي والدولي وحماية منابع المياه.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16300, 2650, 2, 'لأنّ المياه العذبة قليلة وغير موزّعة بالتساوي، والسكّان يتزايدون وحاجات الأمن الغذائي تكبر، فتشتدّ النزاعات كما في دجلة والفرات والنيل وروافد نهر الأردن. من الحلول (اثنان): ترشيد استخدام المياه وحسن إدارته؛ التحوّل نحو الطاقة النظيفة (الرياح ومساقط المياه والشمس)؛ الاقتصاد في استعمال السيّارات والمحرّكات والتوفير في الكهرباء؛ التعاون الإقليمي والدولي وحماية منابع المياه.', 1, '2026-09-30 22:13:08', '2026-09-30 22:13:08'),
(16301, 2651, 1, 'تعني أنّ سكّان العالم تقاربوا بفعل سرعة وسائل الاتّصال والتواصل. ولا يستطيع أيّ بلد أن يبقى بعيداً عن العولمة لأنّها اتّجاه إلزاميّ: فسرعة الاتّصال تتزايد، وتدفّق رؤوس الأموال والتجارة العالميّة وحركة السفر ازدادت أضعافاً، وتتشكّل ثقافة عالميّة عبر وسائل الإعلام.', 1, '2026-09-30 22:13:09', '2026-09-30 22:13:09'),
(16302, 2651, 2, 'تعني أنّ سكّان العالم تقاربوا بفعل سرعة وسائل الاتّصال والتواصل. ولا يستطيع أيّ بلد أن يبقى بعيداً عن العولمة لأنّها اتّجاه إلزاميّ: فسرعة الاتّصال تتزايد، وتدفّق رؤوس الأموال والتجارة العالميّة وحركة السفر ازدادت أضعافاً، وتتشكّل ثقافة عالميّة عبر وسائل الإعلام.', 1, '2026-09-30 22:13:09', '2026-09-30 22:13:09'),
(16303, 2652, 1, 'الفقر بمعناه الشامل ندرة الموارد أو تبديدها أو توزيعها بشكل غير عادل. فبلدان العالم الثالث غنيّة بمواردها الطبيعيّة، والمساحة المزروعة جزء صغير ممّا يمكن زراعته، والعلم يسمح بمضاعفة الغذاء عبر صناعة الزراعة، وبعض البلدان تتلف محاصيل للحفاظ على الأسعار. ويرتبط الفقر بالعلاقات الدوليّة عبر انهيار أسعار منتجات العالم الثالث الزراعيّة أمام الإنتاج المدعوم، وحرّيّة نقل الرساميل وسحبها، وانهيار صناعات بعوامل خارجة عن إرادتها، فتتّسع الفوارق بين الشمال والجنوب.', 1, '2026-09-30 22:13:09', '2026-09-30 22:13:09'),
(16304, 2652, 2, 'الفقر بمعناه الشامل ندرة الموارد أو تبديدها أو توزيعها بشكل غير عادل. فبلدان العالم الثالث غنيّة بمواردها الطبيعيّة، والمساحة المزروعة جزء صغير ممّا يمكن زراعته، والعلم يسمح بمضاعفة الغذاء عبر صناعة الزراعة، وبعض البلدان تتلف محاصيل للحفاظ على الأسعار. ويرتبط الفقر بالعلاقات الدوليّة عبر انهيار أسعار منتجات العالم الثالث الزراعيّة أمام الإنتاج المدعوم، وحرّيّة نقل الرساميل وسحبها، وانهيار صناعات بعوامل خارجة عن إرادتها، فتتّسع الفوارق بين الشمال والجنوب.', 1, '2026-09-30 22:13:09', '2026-09-30 22:13:09'),
(16305, 2653, 1, 'نعم، لأنّ مشكلات العالم مترابطة ولا يحلّها بلد وحده. في الفقر: يساعد تكامل الدول النامية في إطار إقليميّ على تنظيم اقتصادها والدفاع عن أسعار منتجاتها. في المرض: قضت الأمم المتّحدة على الجدريّ ونشرت التحصين ضدّ السعال الديكيّ والسلّ. في الحروب: تعمل الدول المتعاونة على التوازن الدوليّ وحفظ الأمن والسلام.', 1, '2026-09-30 22:13:09', '2026-09-30 22:13:09'),
(16306, 2653, 2, 'نعم، لأنّ مشكلات العالم مترابطة ولا يحلّها بلد وحده. في الفقر: يساعد تكامل الدول النامية في إطار إقليميّ على تنظيم اقتصادها والدفاع عن أسعار منتجاتها. في المرض: قضت الأمم المتّحدة على الجدريّ ونشرت التحصين ضدّ السعال الديكيّ والسلّ. في الحروب: تعمل الدول المتعاونة على التوازن الدوليّ وحفظ الأمن والسلام.', 1, '2026-09-30 22:13:09', '2026-09-30 22:13:09'),
(16307, 2654, 1, 'المعنى الحقيقيّ: مدّ له ذراعيه، وهو معنى جائز. اللازم المقصود: رحّب به. القيمة: تقدّم المعنى مصحوبًا بصورة محسوسة تبقى في الذهن، وتُشرك القارئ في الفهم فيستنتج المعنى بنفسه فيتلذّذ به.', 1, '2026-09-30 22:14:09', '2026-09-30 22:14:09'),
(16308, 2654, 2, 'المعنى الحقيقيّ: مدّ له ذراعيه، وهو معنى جائز. اللازم المقصود: رحّب به. القيمة: تقدّم المعنى مصحوبًا بصورة محسوسة تبقى في الذهن، وتُشرك القارئ في الفهم فيستنتج المعنى بنفسه فيتلذّذ به.', 1, '2026-09-30 22:14:09', '2026-09-30 22:14:09'),
(16309, 2655, 1, 'طَوِيلُ اللِّسَانِ: كثير الكلام أو بذيء. خَفِيفُ الدَّمِ: ظريف محبوب. رَفَعَ يَدَهُ عَنْهُ: تركه وتخلّى عنه.', 1, '2026-09-30 22:14:09', '2026-09-30 22:14:09'),
(16310, 2655, 2, 'طَوِيلُ اللِّسَانِ: كثير الكلام أو بذيء. خَفِيفُ الدَّمِ: ظريف محبوب. رَفَعَ يَدَهُ عَنْهُ: تركه وتخلّى عنه.', 1, '2026-09-30 22:14:09', '2026-09-30 22:14:09'),
(16311, 2656, 1, 'الكناية كلام أُريد به لازم معناه، مع جواز إرادة معناه الحقيقيّ. من قيمها: تقدّم المعنى مصحوبًا بصورة محسوسة تبقى في الذهن؛ تعبّر عن المعنى بأدب فتُلطّف ما يقسو أو يُحرج؛ تُشرك القارئ في الفهم فيستنتج المعنى بنفسه فيتلذّذ به.', 1, '2026-09-30 22:14:09', '2026-09-30 22:14:09'),
(16312, 2656, 2, 'الكناية كلام أُريد به لازم معناه، مع جواز إرادة معناه الحقيقيّ. من قيمها: تقدّم المعنى مصحوبًا بصورة محسوسة تبقى في الذهن؛ تعبّر عن المعنى بأدب فتُلطّف ما يقسو أو يُحرج؛ تُشرك القارئ في الفهم فيستنتج المعنى بنفسه فيتلذّذ به.', 1, '2026-09-30 22:14:09', '2026-09-30 22:14:09'),
(16313, 2657, 1, '(١ علامة) أ) صاحب القول الجاحظ، وهو أقدم من أثار المسألة، ويُعلي اللفظ (المبنى): فيرفع المبنى فوق المعنى. (١ علامة) ب) لأنّ المعاني مطروحة في الطريق، يعرفها العجميّ والقرويّ والبدويّ، أي مشتركة بين الناس جميعًا، فلا يتفاضل فيها الأدباء، بل الشأن في إقامة الوزن وتخيّر اللفظ وسهولة المخرج. (١ علامة) ج) أبو هلال العسكريّ يرى الألفاظ خدم المعاني، فيقدّم المعنى. (١ علامة) أمّا رئيف خوري فيدعو إلى التوازن بين العنصرين وتوفية كلّ عنصر حقّه، فالعلاقة بينهما علاقة الجسد بالروح: «فوجه القضيّة إذًا ليس اهتمامًا بالمبنى أكثر من المعنى».', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16314, 2658, 1, '(١ علامة) النصّ من «حكاية عمر»، وهي سيرة ذاتيّة في جزءين موجّهة إلى حفيده، والطابع الفرديّ للمعالجة ينسجم مع السيرة الذاتيّة. (١ علامة) فموقف الكاتب شخصيّ وإن سعى إلى تعميمه: هو شخصيّ في الاتّجاه، وموضوعيّ في السعي إلى التعميم، وأحكامه القاسية لا تخلو من صدق. (١ علامة) قيمة النصّ: نظرة واقعيّة إلى الريف تخالف السائد، مقارنة مع رأي «ما أطيب الأرض مسكنًا» ونظرة أدباء المهجر.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16315, 2657, 2, '(١ علامة) أ) صاحب القول الجاحظ، وهو أقدم من أثار المسألة، ويُعلي اللفظ (المبنى): فيرفع المبنى فوق المعنى. (١ علامة) ب) لأنّ المعاني مطروحة في الطريق، يعرفها العجميّ والقرويّ والبدويّ، أي مشتركة بين الناس جميعًا، فلا يتفاضل فيها الأدباء، بل الشأن في إقامة الوزن وتخيّر اللفظ وسهولة المخرج. (١ علامة) ج) أبو هلال العسكريّ يرى الألفاظ خدم المعاني، فيقدّم المعنى. (١ علامة) أمّا رئيف خوري فيدعو إلى التوازن بين العنصرين وتوفية كلّ عنصر حقّه، فالعلاقة بينهما علاقة الجسد بالروح: «فوجه القضيّة إذًا ليس اهتمامًا بالمبنى أكثر من المعنى».', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16316, 2658, 2, '(١ علامة) النصّ من «حكاية عمر»، وهي سيرة ذاتيّة في جزءين موجّهة إلى حفيده، والطابع الفرديّ للمعالجة ينسجم مع السيرة الذاتيّة. (١ علامة) فموقف الكاتب شخصيّ وإن سعى إلى تعميمه: هو شخصيّ في الاتّجاه، وموضوعيّ في السعي إلى التعميم، وأحكامه القاسية لا تخلو من صدق. (١ علامة) قيمة النصّ: نظرة واقعيّة إلى الريف تخالف السائد، مقارنة مع رأي «ما أطيب الأرض مسكنًا» ونظرة أدباء المهجر.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16317, 2659, 1, '(١ علامة) أ- التقابل: المعاني تتشكّل بأضدادها؛ وطرفاه في البيت الثاني نار الصدر وأدمع العين. (١ علامة) ب- تكرار الكلمات (النار، صدري) يولّد إيقاعًا جميلًا في النصّ. (١ علامة) ج- عاطفة شاكية صادقة، تعبّر عن الذات من خلال واقع الغربة وتنفّس عن مشاعر المحبّة والحنين.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16318, 2659, 2, '(١ علامة) أ- التقابل: المعاني تتشكّل بأضدادها؛ وطرفاه في البيت الثاني نار الصدر وأدمع العين. (١ علامة) ب- تكرار الكلمات (النار، صدري) يولّد إيقاعًا جميلًا في النصّ. (١ علامة) ج- عاطفة شاكية صادقة، تعبّر عن الذات من خلال واقع الغربة وتنفّس عن مشاعر المحبّة والحنين.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16319, 2660, 1, '(١ علامة) أ) شبّهت الكاتبة تعلّق العرب بالقوالب (الألفاظ والشكل) بالعبادة، فالصورة تدلّ على شغفهم بجمال التعبير وأناقته، وعلى أنّ أكثرهم فضّل اللفظ على المعنى بعد أن أقاموا حدًّا فاصلًا بينهما. (١ علامة) ب) لأنّ الفصحى انحصرت في الأدباء والمتأدّبين، فظلّت لغة أناقة وترف. (١ علامة) ج) غلّب الصراع في النهاية تيّار المساواة بين اللفظ والمعنى، مع بقاء الشغف بقوّة الألفاظ وجمال سبكها.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16320, 2660, 2, '(١ علامة) أ) شبّهت الكاتبة تعلّق العرب بالقوالب (الألفاظ والشكل) بالعبادة، فالصورة تدلّ على شغفهم بجمال التعبير وأناقته، وعلى أنّ أكثرهم فضّل اللفظ على المعنى بعد أن أقاموا حدًّا فاصلًا بينهما. (١ علامة) ب) لأنّ الفصحى انحصرت في الأدباء والمتأدّبين، فظلّت لغة أناقة وترف. (١ علامة) ج) غلّب الصراع في النهاية تيّار المساواة بين اللفظ والمعنى، مع بقاء الشغف بقوّة الألفاظ وجمال سبكها.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16321, 2661, 1, '(١ علامة) أ- استفهام إنكاريّ، وهو وقفة إنشائيّة تقطع السياق الإخباريّ الوصفيّ، يعبّر عن نفور من المدينة وفرح بلقيا الريف. (١ علامة) ب- التكرار، وهو يزيد وطأة الوجدانيّة. (١ علامة) ج- لأنّ صيغة الجمع (مواكب المسافرين، الكلّ متعبون) تتحوّل إلى المتكلّم المفرد قرب القرية، فيعبّر الشاعر عن تخلّصه من الشعور بالغربة والفراغ النفسيّ وعن الحرّيّة التي وجدها في الريف.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16322, 2661, 2, '(١ علامة) أ- استفهام إنكاريّ، وهو وقفة إنشائيّة تقطع السياق الإخباريّ الوصفيّ، يعبّر عن نفور من المدينة وفرح بلقيا الريف. (١ علامة) ب- التكرار، وهو يزيد وطأة الوجدانيّة. (١ علامة) ج- لأنّ صيغة الجمع (مواكب المسافرين، الكلّ متعبون) تتحوّل إلى المتكلّم المفرد قرب القرية، فيعبّر الشاعر عن تخلّصه من الشعور بالغربة والفراغ النفسيّ وعن الحرّيّة التي وجدها في الريف.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16323, 2662, 1, '(١ علامة) أ- ينتمي إلى المقدّمة (البيتان ١–٢)، وفكرته تحقّق فكرة العودة. (١ علامة) ب- الثنائيّة: الجمر والرماد؛ ونفض الجمر يدلّ على ذكريات الصبا المائلة في الذهن، وفيه نفاذ من المحسوس إلى ما وراء المحسوس. (١ علامة) ج- البيت خبر: موقف إخباريّ في سيرة الشاعر الذاتيّة (صدقت ذمّة الزمان)، بجمل فعليّة حركيّة (صدقت، عدنا، ننفض).', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16324, 2662, 2, '(١ علامة) أ- ينتمي إلى المقدّمة (البيتان ١–٢)، وفكرته تحقّق فكرة العودة. (١ علامة) ب- الثنائيّة: الجمر والرماد؛ ونفض الجمر يدلّ على ذكريات الصبا المائلة في الذهن، وفيه نفاذ من المحسوس إلى ما وراء المحسوس. (١ علامة) ج- البيت خبر: موقف إخباريّ في سيرة الشاعر الذاتيّة (صدقت ذمّة الزمان)، بجمل فعليّة حركيّة (صدقت، عدنا، ننفض).', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16325, 2663, 1, '(١ علامة) التفاعل مع الفرس واليونان فتح النقد على التجديد. (١ علامة) الفئة الأولى محافظة، منها: الكسائيّ وابن الأعرابيّ وأبو عمرو (يُكتفى باسمين). (١ علامة) الفئة الثانية لا تفرّق بين قديم وجديد، منها: الجاحظ وابن قتيبة صاحب «الشعر والشعراء».', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16326, 2663, 2, '(١ علامة) التفاعل مع الفرس واليونان فتح النقد على التجديد. (١ علامة) الفئة الأولى محافظة، منها: الكسائيّ وابن الأعرابيّ وأبو عمرو (يُكتفى باسمين). (١ علامة) الفئة الثانية لا تفرّق بين قديم وجديد، منها: الجاحظ وابن قتيبة صاحب «الشعر والشعراء».', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16327, 2664, 1, '(١ علامة) حجازي يعود من المدينة إلى الريف فيجد فيه الانعتاق: الريف نقطة الوصول، مبتغى السعادة وعنوان الاستقرار: «هنا أنا حرّ». (١ علامة) الحيدري يحسم تردّده برفض العودة: «لن أعود». (١ علامة) لأنّ قريته فقدت هويّتها: «لمن أعود وقريتي أمست مدينة»، فضاعت العودة. (١ علامة) هذا الرفض جوهر الإشكاليّة لأنّ الريف والمدينة إطاران متمايزان ونمطان من العيش يتمزّق بينهما الإنسان.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16328, 2664, 2, '(١ علامة) حجازي يعود من المدينة إلى الريف فيجد فيه الانعتاق: الريف نقطة الوصول، مبتغى السعادة وعنوان الاستقرار: «هنا أنا حرّ». (١ علامة) الحيدري يحسم تردّده برفض العودة: «لن أعود». (١ علامة) لأنّ قريته فقدت هويّتها: «لمن أعود وقريتي أمست مدينة»، فضاعت العودة. (١ علامة) هذا الرفض جوهر الإشكاليّة لأنّ الريف والمدينة إطاران متمايزان ونمطان من العيش يتمزّق بينهما الإنسان.', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16329, 2665, 1, '(١ علامة) التعليل: المهاجرون انفصلوا بالجسد وظلّوا متّصلين بالروح، فوحدة أحاسيسهم تقارب معاني قصائدهم؛ ويحفزهم شعور واحد هو الغربة والحنين. (١ علامة) شفيق المعلوف: ذكريات الصبا، وهو من العصبة الأندلسيّة (شارك في تأسيسها وترأسها). (١ علامة) رشيد أيّوب: التغنّي بالوطن والجراح، وهو من الرابطة القلميّة (انضمّ إليها سنة ١٩٢٠). (١ علامة) الشاعر القرويّ: التنديد بالظروف القاسية، وهو من العصبة الأندلسيّة (عضو مؤسّس ثمّ رئيسها).', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16330, 2665, 2, '(١ علامة) التعليل: المهاجرون انفصلوا بالجسد وظلّوا متّصلين بالروح، فوحدة أحاسيسهم تقارب معاني قصائدهم؛ ويحفزهم شعور واحد هو الغربة والحنين. (١ علامة) شفيق المعلوف: ذكريات الصبا، وهو من العصبة الأندلسيّة (شارك في تأسيسها وترأسها). (١ علامة) رشيد أيّوب: التغنّي بالوطن والجراح، وهو من الرابطة القلميّة (انضمّ إليها سنة ١٩٢٠). (١ علامة) الشاعر القرويّ: التنديد بالظروف القاسية، وهو من العصبة الأندلسيّة (عضو مؤسّس ثمّ رئيسها).', 1, '2026-09-30 22:53:57', '2026-09-30 22:53:57'),
(16333, 2667, 1, '(١ علامة) الفكرة: الجهاد هو الطريق إلى الحرّيّة؛ فالشاعر وقومه يصاحبون الموت ولا يعدّون الحياة حياة إلّا بفداء الوطن، ولن يروا أمّة حرّة ودنيا جديدة إلّا إذا ماتوا في هواها (الشهادة). (١ علامة) الظاهرة الأسلوبيّة: الترجيع النفسيّ «أو نفدّي… لن نراها… نحن لا نحسب» واختصار المواقف في شعارات كالأناشيد (ويُقبل أيضًا: الأسلوب الخطابيّ المباشر). (١ علامة) تنتهي القصيدة بنبرة حماسيّة: «لن نراها إن لم نمت في هواها · أمّة حرّة ودنيا جديدة».', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16334, 2667, 2, '(١ علامة) الفكرة: الجهاد هو الطريق إلى الحرّيّة؛ فالشاعر وقومه يصاحبون الموت ولا يعدّون الحياة حياة إلّا بفداء الوطن، ولن يروا أمّة حرّة ودنيا جديدة إلّا إذا ماتوا في هواها (الشهادة). (١ علامة) الظاهرة الأسلوبيّة: الترجيع النفسيّ «أو نفدّي… لن نراها… نحن لا نحسب» واختصار المواقف في شعارات كالأناشيد (ويُقبل أيضًا: الأسلوب الخطابيّ المباشر). (١ علامة) تنتهي القصيدة بنبرة حماسيّة: «لن نراها إن لم نمت في هواها · أمّة حرّة ودنيا جديدة».', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16335, 2668, 1, '(١ علامة) أ- البيان هو الوضوح: كلّ ما يكشف قناع المعنى ويهتك الحجاب دون الضمير. (١ علامة) ب- يتوقّف إظهار المعنى على وضوح الدلالة، وصواب الإشارة، وحسن الاختصار. (١ علامة) ج- البيان سليقة وطبع، أمّا التبيين فصنعة وممارسة، أي صناعة الكلام.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16336, 2668, 2, '(١ علامة) أ- البيان هو الوضوح: كلّ ما يكشف قناع المعنى ويهتك الحجاب دون الضمير. (١ علامة) ب- يتوقّف إظهار المعنى على وضوح الدلالة، وصواب الإشارة، وحسن الاختصار. (١ علامة) ج- البيان سليقة وطبع، أمّا التبيين فصنعة وممارسة، أي صناعة الكلام.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16337, 2669, 1, '(١ علامة) الحداثة عند الخال إبداع وخروج على ما سلف، لا ترتبط بزمن (ما نعتبره اليوم حديثًا يصبح قديمًا)، وتفترض شخصيّة شعريّة جديدة ذات تجربة معاصرة تعبّر عن ذاتها في المضمون والشكل معًا. (١ علامة) جورج غانم حين كتب عن لبنان والحرب والموت لم يكن قادرًا على الكتابة بلغة الماضي لأنّ كلّ شيء تهدّم؛ فالشاعر ابن زمانه يكتب بلغته، فكتب قصيدة النثر. (١ علامة) يلتقيان في ربط الشكل الشعريّ بزمانه وبالتجربة المعاصرة، من غير رفض للقديم: الخال يرى أنّ الحداثة لا تمتاز بالضرورة على القدامة، وغانم يكتب بلغة عصره دون أن يكون ذلك على حساب التراث، وقد كتب الشعر العموديّ وأجاد فيه.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16338, 2669, 2, '(١ علامة) الحداثة عند الخال إبداع وخروج على ما سلف، لا ترتبط بزمن (ما نعتبره اليوم حديثًا يصبح قديمًا)، وتفترض شخصيّة شعريّة جديدة ذات تجربة معاصرة تعبّر عن ذاتها في المضمون والشكل معًا. (١ علامة) جورج غانم حين كتب عن لبنان والحرب والموت لم يكن قادرًا على الكتابة بلغة الماضي لأنّ كلّ شيء تهدّم؛ فالشاعر ابن زمانه يكتب بلغته، فكتب قصيدة النثر. (١ علامة) يلتقيان في ربط الشكل الشعريّ بزمانه وبالتجربة المعاصرة، من غير رفض للقديم: الخال يرى أنّ الحداثة لا تمتاز بالضرورة على القدامة، وغانم يكتب بلغة عصره دون أن يكون ذلك على حساب التراث، وقد كتب الشعر العموديّ وأجاد فيه.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16339, 2670, 1, '(١ علامة) نشأته الفقيرة: فقد أباه صغيرًا ونشأ فقيرًا في إعالة أمّه، وكان يبيع السمك والخبز على نهر سيحان، وأصله من الموالي. (١ علامة) صلاته الوثيقة بالبيئات الشعبيّة: غشي الكتّاب وحلقات المسجد والمربد حيث الشعراء والرواة والأعراب الفصحاء، وبات في دكاكين الورّاقين، فعايش مجتمعه وعاين أبناء عصره. (١ علامة) في «البخلاء» التفت إلى الناس الكادحين والطبقة الوسطى، فرسم نماذج اجتماعيّة حيّة (مريم الصنّاع، الكنديّ، أسد بن جاني) تصطبغ بمدلولات أخلاقيّة واقتصاديّة، وكشف أخلاق الطبقة الوسطى ودور المال.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16340, 2670, 2, '(١ علامة) نشأته الفقيرة: فقد أباه صغيرًا ونشأ فقيرًا في إعالة أمّه، وكان يبيع السمك والخبز على نهر سيحان، وأصله من الموالي. (١ علامة) صلاته الوثيقة بالبيئات الشعبيّة: غشي الكتّاب وحلقات المسجد والمربد حيث الشعراء والرواة والأعراب الفصحاء، وبات في دكاكين الورّاقين، فعايش مجتمعه وعاين أبناء عصره. (١ علامة) في «البخلاء» التفت إلى الناس الكادحين والطبقة الوسطى، فرسم نماذج اجتماعيّة حيّة (مريم الصنّاع، الكنديّ، أسد بن جاني) تصطبغ بمدلولات أخلاقيّة واقتصاديّة، وكشف أخلاق الطبقة الوسطى ودور المال.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16341, 2671, 1, '(١ علامة) التهمة أنّه «يتصنّع ويتهاوى عاطفيًّا»، ولهذا طالبه مارون عبّود بالصدق. (١ علامة) يردّ عليها أنّ غزله تجربة ذاتيّة لا غزل نظريّ، وقصائد «الهوى والشباب» مذكّرات سجّل فيها أسرار حياته العاطفيّة، والحبّ عنده معاناة: «أيّها الخافق المعذّب يا قلبي · نزحت الدموع من مقلتيّا»، وقصائد غزله غنيّة بالتعبير عن العاطفة الإنسانيّة في الحبّ. (١ علامة) غير أنّ تقييم غزله يُظهر أنّه اكتفى بالتعبير عن الجمال الخارجيّ دون الدخول إلى حقيقة المعاناة النفسيّة أو الروحيّة، فلا يُعدّ التمثيل مطلقًا ولا الصدق كاملًا.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16342, 2671, 2, '(١ علامة) التهمة أنّه «يتصنّع ويتهاوى عاطفيًّا»، ولهذا طالبه مارون عبّود بالصدق. (١ علامة) يردّ عليها أنّ غزله تجربة ذاتيّة لا غزل نظريّ، وقصائد «الهوى والشباب» مذكّرات سجّل فيها أسرار حياته العاطفيّة، والحبّ عنده معاناة: «أيّها الخافق المعذّب يا قلبي · نزحت الدموع من مقلتيّا»، وقصائد غزله غنيّة بالتعبير عن العاطفة الإنسانيّة في الحبّ. (١ علامة) غير أنّ تقييم غزله يُظهر أنّه اكتفى بالتعبير عن الجمال الخارجيّ دون الدخول إلى حقيقة المعاناة النفسيّة أو الروحيّة، فلا يُعدّ التمثيل مطلقًا ولا الصدق كاملًا.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16343, 2672, 1, '(١ علامة) أ- يبنون حكمهم على وفرة المال: فالكلام يُقاس بحجم الثروة، وهم «أشدّ تعظيمًا للأغنياء»؛ إنّه موقف طبقيّ. (١ علامة) ب- يكشف الخبر أخلاق الطبقة التي تبني قيمها وأحكامها على وفرة المال في جيوبها، ويبيّن أنّ المال يخفض ويعلي، ويحطّ ويرفع.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16344, 2672, 2, '(١ علامة) أ- يبنون حكمهم على وفرة المال: فالكلام يُقاس بحجم الثروة، وهم «أشدّ تعظيمًا للأغنياء»؛ إنّه موقف طبقيّ. (١ علامة) ب- يكشف الخبر أخلاق الطبقة التي تبني قيمها وأحكامها على وفرة المال في جيوبها، ويبيّن أنّ المال يخفض ويعلي، ويحطّ ويرفع.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16345, 2673, 1, '(١ علامة) في مدخل المحور: تسرّبت حركة الشعر الحديث إلى جميع الأقطار العربيّة واتّخذت أشكالًا وصلت إلى حدّ التطرّف مع القصيدة النثريّة، وكثيرون استسهلوا كتابة «الشعر الحديث» فتسلّلت إلى مدارجه مجموعات تستهويها الأشكال الجديدة النافرة. (١ علامة) في خلاصة المحور: الشعر النثريّ سبّب نوعًا من الفوضى الشعريّة لا تعرف نموذجًا أو نظامًا، بعد أن كان التجديد قد انتقل من رفض الشعر التقليديّ إلى شعر التفعيلة.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16346, 2674, 1, '(١ علامة) أنشأ الأخطل جريدة «البرق» سنة ١٩٠٨ وتحوّلت إلى نادٍ يضمّ كبار الأدباء، وكتب فيها مقالات (١٩٠٨–١٩٣٢) بين السياسة والأدب والمجتمع. (١ علامة) لذلك كانت الصحافة «جرثومة» رافقته، فهو أديب يعايش الناس في همومهم اليوميّة، وجاءت قصائد المناسبات عنده تعليقًا شعريًّا على الأخبار، شعبيّة لا تقليديّة.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16347, 2673, 2, '(١ علامة) في مدخل المحور: تسرّبت حركة الشعر الحديث إلى جميع الأقطار العربيّة واتّخذت أشكالًا وصلت إلى حدّ التطرّف مع القصيدة النثريّة، وكثيرون استسهلوا كتابة «الشعر الحديث» فتسلّلت إلى مدارجه مجموعات تستهويها الأشكال الجديدة النافرة. (١ علامة) في خلاصة المحور: الشعر النثريّ سبّب نوعًا من الفوضى الشعريّة لا تعرف نموذجًا أو نظامًا، بعد أن كان التجديد قد انتقل من رفض الشعر التقليديّ إلى شعر التفعيلة.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16348, 2674, 2, '(١ علامة) أنشأ الأخطل جريدة «البرق» سنة ١٩٠٨ وتحوّلت إلى نادٍ يضمّ كبار الأدباء، وكتب فيها مقالات (١٩٠٨–١٩٣٢) بين السياسة والأدب والمجتمع. (١ علامة) لذلك كانت الصحافة «جرثومة» رافقته، فهو أديب يعايش الناس في همومهم اليوميّة، وجاءت قصائد المناسبات عنده تعليقًا شعريًّا على الأخبار، شعبيّة لا تقليديّة.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16349, 2675, 1, '(١ علامة) التقابل بين الكدح والحلم: الملايين التي تكدح هم الكادحون والفقراء في كلّ مكان، لا وقت لهم للحلم بموت فراشة أو بأحزان البنفسج، وهي من رموز الرومنطيقيّة الحالمة التي لا تعني الكادحين. (١ علامة) يدلّ ذلك على انتماء القصيدة إلى الشعر الحديث في التزامه بقضايا الإنسان: فهي عكس الرومنطيقيّة، ومنحازة إلى الكادحين، والبيّاتي شاعر ملتزم.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16350, 2675, 2, '(١ علامة) التقابل بين الكدح والحلم: الملايين التي تكدح هم الكادحون والفقراء في كلّ مكان، لا وقت لهم للحلم بموت فراشة أو بأحزان البنفسج، وهي من رموز الرومنطيقيّة الحالمة التي لا تعني الكادحين. (١ علامة) يدلّ ذلك على انتماء القصيدة إلى الشعر الحديث في التزامه بقضايا الإنسان: فهي عكس الرومنطيقيّة، ومنحازة إلى الكادحين، والبيّاتي شاعر ملتزم.', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16351, 2676, 1, '(١ علامة) اعتمد المقارنات والوقائع العقليّة: فقصور الأغنياء بناها الفقراء، وأطباقهم اللذيذة طبخها الفقراء؛ فالتوتّر لم يمنعه من المحاجّة. (١ علامة) مظهر واحد مع شاهده، مثل: الأسلوب الحماسيّ المباشر بالمخاطبة «أيّها الأغنياء»، أو التكرار في الألفاظ والمعاني (لفظة «الفقراء» في القوافي)، أو الألفاظ من القاموس اليوميّ (الطعام).', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16352, 2677, 1, '(١ علامة) أ- الطباق، وهو التعانق بالثنائيّة الضدّيّة في أسلوب الجاحظ. (١ علامة) ب- المثال: «قديم / مولّد».', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16353, 2676, 2, '(١ علامة) اعتمد المقارنات والوقائع العقليّة: فقصور الأغنياء بناها الفقراء، وأطباقهم اللذيذة طبخها الفقراء؛ فالتوتّر لم يمنعه من المحاجّة. (١ علامة) مظهر واحد مع شاهده، مثل: الأسلوب الحماسيّ المباشر بالمخاطبة «أيّها الأغنياء»، أو التكرار في الألفاظ والمعاني (لفظة «الفقراء» في القوافي)، أو الألفاظ من القاموس اليوميّ (الطعام).', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16354, 2677, 2, '(١ علامة) أ- الطباق، وهو التعانق بالثنائيّة الضدّيّة في أسلوب الجاحظ. (١ علامة) ب- المثال: «قديم / مولّد».', 1, '2026-09-30 22:53:58', '2026-09-30 22:53:58'),
(16355, 2678, 1, '(١ علامة) رفض غوته أساليب الثورة الفرنسيّة لأنّها أساليب عنفيّة، والعنف في رأيه قاتل للتفكير. (١ علامة) ولأنّه يعتقد أنّ العلاقة بين الطبقات الاجتماعيّة ينبغي أن تقوم على الوفاق لا على الصراع.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16356, 2678, 2, '(١ علامة) رفض غوته أساليب الثورة الفرنسيّة لأنّها أساليب عنفيّة، والعنف في رأيه قاتل للتفكير. (١ علامة) ولأنّه يعتقد أنّ العلاقة بين الطبقات الاجتماعيّة ينبغي أن تقوم على الوفاق لا على الصراع.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16357, 2679, 1, '(١ علامة) الشخصيّة الرئيسيّة هي الخيط الرابط لمسار الحوادث، تتجمّع لديها الحوادث وتنبثق منها بفعل تأثيرها في الآخرين، وتستأثر بمعظم الحوادث. (١ علامة) سعيد مهران شخصيّة رئيسيّة لأنّه سدى الحوادث ولحمتها، أي يحرّك بنية النصّ الروائيّ من البداية إلى النهاية، منشغلًا انشغالًا كاملًا بالمطاردة «لتصفية الحساب» والقضاء على «الخونة». (١ علامة) تميمة تتصدّر الأسماء جميعًا مع كثرتها في الرواية، وقد جعلها الكاتب محور عمله القصصيّ: الحالمة ببيروت التي ينبثق من موقفها صراع مع الأمّ والأخ جابر.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16358, 2679, 2, '(١ علامة) الشخصيّة الرئيسيّة هي الخيط الرابط لمسار الحوادث، تتجمّع لديها الحوادث وتنبثق منها بفعل تأثيرها في الآخرين، وتستأثر بمعظم الحوادث. (١ علامة) سعيد مهران شخصيّة رئيسيّة لأنّه سدى الحوادث ولحمتها، أي يحرّك بنية النصّ الروائيّ من البداية إلى النهاية، منشغلًا انشغالًا كاملًا بالمطاردة «لتصفية الحساب» والقضاء على «الخونة». (١ علامة) تميمة تتصدّر الأسماء جميعًا مع كثرتها في الرواية، وقد جعلها الكاتب محور عمله القصصيّ: الحالمة ببيروت التي ينبثق من موقفها صراع مع الأمّ والأخ جابر.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16359, 2680, 1, '(١ علامة) أ- القائل دون كيخوته يخاطب خادمه سانتشو، بعد مبارزة طواحين الهواء التي حطّمت رمحه وطرحته وجواده أرضًا. (١ علامة) ب- يفسّره بأنّ شؤون الحرب تبقى عرضة للتقلّبات، وبأنّ كتب الفروسيّة تحذّر من مكايد الأشرار. (١ علامة) ج- لم تنل الهزيمة من عزيمته: فهو لا يشكو ولا يتأوّه لأنّ ذلك ليس من شيم الفرسان، ويرى أنّ الأذرع العملاقة لن تقضي على الهدف الذي من أجله يحمل السلاح.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16360, 2680, 2, '(١ علامة) أ- القائل دون كيخوته يخاطب خادمه سانتشو، بعد مبارزة طواحين الهواء التي حطّمت رمحه وطرحته وجواده أرضًا. (١ علامة) ب- يفسّره بأنّ شؤون الحرب تبقى عرضة للتقلّبات، وبأنّ كتب الفروسيّة تحذّر من مكايد الأشرار. (١ علامة) ج- لم تنل الهزيمة من عزيمته: فهو لا يشكو ولا يتأوّه لأنّ ذلك ليس من شيم الفرسان، ويرى أنّ الأذرع العملاقة لن تقضي على الهدف الذي من أجله يحمل السلاح.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16361, 2681, 1, '(١ علامة) ظهرت عبقريّة سرڤانتس في عمر متقدّم، إذ كان ابن سبع وخمسين سنة عندما أنهى القسم الأوّل من روايته، فجاءت شخصيّته مميّزة في عمر النضج. (١ علامة) عرف حياة مضطربة: نشأ في أسرة وضيعة فقيرة، وخدم في الجيش الإسبانيّ في إيطاليا، وأصيب في معركة ليبانتو ١٥٧١ ففقد يده اليسرى (أقطع ليبانتو). (١ علامة) أُسر خمس سنوات في الجزائر وعاد إلى إسبانيا فقيرًا، ثمّ سُجن مرّتين بسبب الديون، وأنهى القسم الأوّل من «دون كيخوته» في السجن.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16362, 2682, 1, '(١ علامة) أ- يعترف ڤرتر بعجزه عن الرسم: يده لا تقدر على إبراز ما أثّر في نفسه من المناظر على القرطاس، فبهاء الصور وسناء الرؤى يملكان عليه طريق العمل فيقف إزاءها وضيعًا (عجز الريشة). (١ علامة) ب- الطبيعة عند ڤرتر يتجلّى فيها الخالق، فهو يحسّ فيها «حضور القويّ القادر»، والألوهيّة المحسوسة من خلال الطبيعة الخلّابة تنتقل إلى الإنسان؛ وهي الملهم الحقيقيّ. (١ علامة) ج- اندماج الذات في الطبيعة، أو الحساسيّة المفرطة (تُقبل إحداهما).', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16363, 2683, 1, '(١ علامة) (أ) شعور ليس هو الحزن الهادئ الثقيل، بل شعور غريب قويّ وضعيف في آن واحد: قوّته تدفعه لملاقاة الموت كأنّه يحسّ بثقل العاصفة، وضعفه يهبط بقلبه فيفكّر في الموت والحياة وفي ماضيه ومستقبله وفي شفيق. (١ علامة) (ب) يتخلّل السردَ المباشر تيّارُ الشعور (التيّار الداخليّ) والترجمة الذاتيّة في خواطر سامي. (١ علامة) (ج) شفيق العلايلي رئيس الحرّاس الذي هرب مع سامي من السجن والتحقا بالثورة العربيّة ضابطين في الجيش العربيّ؛ مات في ساحة القتال وكانت كلمته الأخيرة «العهد!».', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16364, 2681, 2, '(١ علامة) ظهرت عبقريّة سرڤانتس في عمر متقدّم، إذ كان ابن سبع وخمسين سنة عندما أنهى القسم الأوّل من روايته، فجاءت شخصيّته مميّزة في عمر النضج. (١ علامة) عرف حياة مضطربة: نشأ في أسرة وضيعة فقيرة، وخدم في الجيش الإسبانيّ في إيطاليا، وأصيب في معركة ليبانتو ١٥٧١ ففقد يده اليسرى (أقطع ليبانتو). (١ علامة) أُسر خمس سنوات في الجزائر وعاد إلى إسبانيا فقيرًا، ثمّ سُجن مرّتين بسبب الديون، وأنهى القسم الأوّل من «دون كيخوته» في السجن.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16365, 2682, 2, '(١ علامة) أ- يعترف ڤرتر بعجزه عن الرسم: يده لا تقدر على إبراز ما أثّر في نفسه من المناظر على القرطاس، فبهاء الصور وسناء الرؤى يملكان عليه طريق العمل فيقف إزاءها وضيعًا (عجز الريشة). (١ علامة) ب- الطبيعة عند ڤرتر يتجلّى فيها الخالق، فهو يحسّ فيها «حضور القويّ القادر»، والألوهيّة المحسوسة من خلال الطبيعة الخلّابة تنتقل إلى الإنسان؛ وهي الملهم الحقيقيّ. (١ علامة) ج- اندماج الذات في الطبيعة، أو الحساسيّة المفرطة (تُقبل إحداهما).', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16366, 2683, 2, '(١ علامة) (أ) شعور ليس هو الحزن الهادئ الثقيل، بل شعور غريب قويّ وضعيف في آن واحد: قوّته تدفعه لملاقاة الموت كأنّه يحسّ بثقل العاصفة، وضعفه يهبط بقلبه فيفكّر في الموت والحياة وفي ماضيه ومستقبله وفي شفيق. (١ علامة) (ب) يتخلّل السردَ المباشر تيّارُ الشعور (التيّار الداخليّ) والترجمة الذاتيّة في خواطر سامي. (١ علامة) (ج) شفيق العلايلي رئيس الحرّاس الذي هرب مع سامي من السجن والتحقا بالثورة العربيّة ضابطين في الجيش العربيّ؛ مات في ساحة القتال وكانت كلمته الأخيرة «العهد!».', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16367, 2684, 1, '(١ علامة) «روك» أحد قطّاع الطرق المشهورين بكرمهم وسماحتهم، صادفه دون كيخوته على طريق برشلونة على رأس رجاله الستّين. (١ علامة) لُقّب بـ«اللصّ الشريف» لأنّه كان خيّرًا في مهنته، يعرف ما يلجم صحبه، ويكتفي بضريبة معتدلة يدفعها المسافرون، وقد ساعد دون كيخوته وخادمه فقدّم لهما الطعام.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16368, 2685, 1, '(½ علامة) الروايتان: «الرغيف» (١٩٣٩) و«طواحين بيروت» (١٩٧٣). (½ علامة) من قصصه القصيرة: «الصبيّ الأعرج» (١٩٣٦) و«قميص الصوف» (١٩٣٧) (أو «العذارى»). (١ علامة) «الرغيف» أسهمت في إرساء التيّار الواقعيّ في الرواية العربيّة، وهي من نتاج ما بين الحربين.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16369, 2684, 2, '(١ علامة) «روك» أحد قطّاع الطرق المشهورين بكرمهم وسماحتهم، صادفه دون كيخوته على طريق برشلونة على رأس رجاله الستّين. (١ علامة) لُقّب بـ«اللصّ الشريف» لأنّه كان خيّرًا في مهنته، يعرف ما يلجم صحبه، ويكتفي بضريبة معتدلة يدفعها المسافرون، وقد ساعد دون كيخوته وخادمه فقدّم لهما الطعام.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16370, 2685, 2, '(½ علامة) الروايتان: «الرغيف» (١٩٣٩) و«طواحين بيروت» (١٩٧٣). (½ علامة) من قصصه القصيرة: «الصبيّ الأعرج» (١٩٣٦) و«قميص الصوف» (١٩٣٧) (أو «العذارى»). (١ علامة) «الرغيف» أسهمت في إرساء التيّار الواقعيّ في الرواية العربيّة، وهي من نتاج ما بين الحربين.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16371, 2686, 1, '(١ علامة) طه حسين يُعجَب بالكتاب وصاحبه: «إنّ كتاب آلام ڤرتر قد عرفه الناس جميعًا في أوروبا فأحبّوه وكلفوا به»، وهو عنده كتاب كلّ شابّ، و«كان جوته رجلًا عظيمًا فرضت عظمته على الإنسانيّة العاقلة الحسّاسة أن تحبّه». (١ علامة) أمّا محمد عوض محمد فيقف عند حبّ غوته نفسه، فيرى أنّه «لم يكن يحبّ حبًّا مبرّحًا، بل كان يحبّ أن يرى نفسه محبًّا»، أي إنّ التجربة الفنّيّة غير التجربة الحياتيّة.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16372, 2686, 2, '(١ علامة) طه حسين يُعجَب بالكتاب وصاحبه: «إنّ كتاب آلام ڤرتر قد عرفه الناس جميعًا في أوروبا فأحبّوه وكلفوا به»، وهو عنده كتاب كلّ شابّ، و«كان جوته رجلًا عظيمًا فرضت عظمته على الإنسانيّة العاقلة الحسّاسة أن تحبّه». (١ علامة) أمّا محمد عوض محمد فيقف عند حبّ غوته نفسه، فيرى أنّه «لم يكن يحبّ حبًّا مبرّحًا، بل كان يحبّ أن يرى نفسه محبًّا»، أي إنّ التجربة الفنّيّة غير التجربة الحياتيّة.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16373, 2687, 1, '(½ علامة) القائل حسنين. (١ علامة) يكشف عن شخصيّة الطموح المتبرّم الذي يخجل من الماضي والفقر ويطلب الثراء. (½ علامة) من تصرّفاته: يفسخ خطوبته لبهيّة ويتّجه بتفكيره إلى مصاهرة الثريّ أحمد بك يسري (أو: يطلب أن تنقطع نفيسة عن عملها لأنّه لا يجوز لأخت الضابط أن تكون خيّاطة).', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16374, 2688, 1, '(١ علامة) كان البطلان في صراع دائم مع آفات المجتمع التي يتكرّر بعضها مع كلّ عصر؛ فهي علاقة صراع بين الخير والشرّ: حاول دون كيخوته اقتلاع الشرّ لينمو الخير، وحاول المجتمع تجريد البطلين من قيمهما وإنزالهما إلى الأوحال. (١ علامة) في نصّ «الغلام والفلّاح» أمر دون كيخوته الفلّاح بدفع أجر الغلام الذي كان يجلده، لكنّه ما إن انطلق حتّى قيّد الفلّاح الغلام إلى جذع الشجرة مجدّدًا وعاد إلى جلده بدون رحمة وضحكاته الساخرة تتبعه، فانتهت نصرة المظلوم بجلد أقسى.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16375, 2687, 2, '(½ علامة) القائل حسنين. (١ علامة) يكشف عن شخصيّة الطموح المتبرّم الذي يخجل من الماضي والفقر ويطلب الثراء. (½ علامة) من تصرّفاته: يفسخ خطوبته لبهيّة ويتّجه بتفكيره إلى مصاهرة الثريّ أحمد بك يسري (أو: يطلب أن تنقطع نفيسة عن عملها لأنّه لا يجوز لأخت الضابط أن تكون خيّاطة).', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16376, 2688, 2, '(١ علامة) كان البطلان في صراع دائم مع آفات المجتمع التي يتكرّر بعضها مع كلّ عصر؛ فهي علاقة صراع بين الخير والشرّ: حاول دون كيخوته اقتلاع الشرّ لينمو الخير، وحاول المجتمع تجريد البطلين من قيمهما وإنزالهما إلى الأوحال. (١ علامة) في نصّ «الغلام والفلّاح» أمر دون كيخوته الفلّاح بدفع أجر الغلام الذي كان يجلده، لكنّه ما إن انطلق حتّى قيّد الفلّاح الغلام إلى جذع الشجرة مجدّدًا وعاد إلى جلده بدون رحمة وضحكاته الساخرة تتبعه، فانتهت نصرة المظلوم بجلد أقسى.', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16377, 2689, 1, '(١ علامة) الموقف صراع بين النفس الأمّارة التي تحرّض ڤرتر على الضمّ واللثم وبين حرصه على الحبّ العفيف الطاهر، فالحبّ العذريّ يقف بين الرغبة والبراءة. (١ علامة) فشرلوت عنده معبودة يجلّها ويقدّسها، والقرب منها يبعث الاضطراب في أعصابه، كما يأنس العذريّون لما مسّته الحبيبة. (١ علامة) شاهد مناسب، مثل: «فإذا كنت معها سكنت رغباتي وفنيت نزعاتي، ثمّ لا أدري في أيّة حال أكون إذا دانيتها»، أو «كما كان العذريّون يأنسون للريح لأنّها مرّت بدار الحبيبة».', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16378, 2689, 2, '(١ علامة) الموقف صراع بين النفس الأمّارة التي تحرّض ڤرتر على الضمّ واللثم وبين حرصه على الحبّ العفيف الطاهر، فالحبّ العذريّ يقف بين الرغبة والبراءة. (١ علامة) فشرلوت عنده معبودة يجلّها ويقدّسها، والقرب منها يبعث الاضطراب في أعصابه، كما يأنس العذريّون لما مسّته الحبيبة. (١ علامة) شاهد مناسب، مثل: «فإذا كنت معها سكنت رغباتي وفنيت نزعاتي، ثمّ لا أدري في أيّة حال أكون إذا دانيتها»، أو «كما كان العذريّون يأنسون للريح لأنّها مرّت بدار الحبيبة».', 1, '2026-09-30 22:54:00', '2026-09-30 22:54:00'),
(16379, 2690, 1, '(١ علامة) في «صافحني رجل كريم كالبحر» ذُكر طرفا التشبيه: المشبّه (رجل كريم) والمشبّه به (البحر) مع الأداة (الكاف)، فهو تشبيه. (١ علامة) في «صافحني بحر» حُذف أحد الطرفين (المشبّه: الرجل الكريم)، والاستعارة تشبيه حُذف أحد طرفيه، وهي مجاز لفظيّ علاقته المشابهة. (١ علامة) هي استعارة تصريحيّة، لأنّه صُرّح فيها بالمستعار منه (البحر) وحُذف المستعار له (الرجل الكريم).', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16380, 2690, 2, '(١ علامة) في «صافحني رجل كريم كالبحر» ذُكر طرفا التشبيه: المشبّه (رجل كريم) والمشبّه به (البحر) مع الأداة (الكاف)، فهو تشبيه. (١ علامة) في «صافحني بحر» حُذف أحد الطرفين (المشبّه: الرجل الكريم)، والاستعارة تشبيه حُذف أحد طرفيه، وهي مجاز لفظيّ علاقته المشابهة. (١ علامة) هي استعارة تصريحيّة، لأنّه صُرّح فيها بالمستعار منه (البحر) وحُذف المستعار له (الرجل الكريم).', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16381, 2691, 1, '(١ علامة) أ- رمز فعولن (//ه/ه)، وتتكوّن من وتد مجموع (//ه: متحرّكان يليهما ساكن) يليه سبب خفيف (/ه: متحرّك فساكن). (١ علامة) ب- هي تفعيلة خماسيّة، وهي مع فاعلن التفعيلتان الخماسيّتان من التفاعيل العشر. (١ علامة) ج- لأنّ ما يبدأ بفعولن يكون طويلًا أو متقاربًا، وتكملة النسق هي التي تحسم: فلو تلتها مفاعيلن لكان الطويل، أمّا هنا فتتكرّر فعولن وحدها (فعولن فعولن فعولن فعولن)، فهو المتقارب.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16382, 2691, 2, '(١ علامة) أ- رمز فعولن (//ه/ه)، وتتكوّن من وتد مجموع (//ه: متحرّكان يليهما ساكن) يليه سبب خفيف (/ه: متحرّك فساكن). (١ علامة) ب- هي تفعيلة خماسيّة، وهي مع فاعلن التفعيلتان الخماسيّتان من التفاعيل العشر. (١ علامة) ج- لأنّ ما يبدأ بفعولن يكون طويلًا أو متقاربًا، وتكملة النسق هي التي تحسم: فلو تلتها مفاعيلن لكان الطويل، أمّا هنا فتتكرّر فعولن وحدها (فعولن فعولن فعولن فعولن)، فهو المتقارب.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16383, 2692, 1, '(١ علامة) عُدَّ المالُ: الفعل «عَدَّ» ماضٍ مضعّف، والماضي المضعّف يُبنى للمجهول بضمّ الأوّل فقط. (١ علامة) المالُ: نائب فاعل مرفوع وعلامة رفعه الضمّة؛ حُذف الفاعل فأخذ المفعول به مرتبته في الإسناد وصار مرفوعًا. (١ علامة) لا يصلح «عِنْدَ» لأنّه ظرف غير متصرّف لا يقبل حركات الإعراب، فلا يتحقّق فيه شرط التصرّف اللازم للنيابة عن الفاعل.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16384, 2692, 2, '(١ علامة) عُدَّ المالُ: الفعل «عَدَّ» ماضٍ مضعّف، والماضي المضعّف يُبنى للمجهول بضمّ الأوّل فقط. (١ علامة) المالُ: نائب فاعل مرفوع وعلامة رفعه الضمّة؛ حُذف الفاعل فأخذ المفعول به مرتبته في الإسناد وصار مرفوعًا. (١ علامة) لا يصلح «عِنْدَ» لأنّه ظرف غير متصرّف لا يقبل حركات الإعراب، فلا يتحقّق فيه شرط التصرّف اللازم للنيابة عن الفاعل.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16385, 2693, 1, '(١ علامة) الكناية تعبير له معنى قريب حقيقيّ ومعنى بعيد مجازيّ هو المقصود، ويجوز فيها إرادة المعنى القريب: «نشاطًا خفافًا» معناها القريب خفّة الحركة، والبعيد المقصود الإفراط في الكرم، ويصحّ إرادة المعنى القريب. (١ علامة) أمّا الاستعارة فلا تسمح بإرادة المعنى الحقيقيّ: «ترنّح الضجيج» لا يمكن حملها على الحقيقة، لأنّ الضجيج لا يترنّح.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16386, 2693, 2, '(١ علامة) الكناية تعبير له معنى قريب حقيقيّ ومعنى بعيد مجازيّ هو المقصود، ويجوز فيها إرادة المعنى القريب: «نشاطًا خفافًا» معناها القريب خفّة الحركة، والبعيد المقصود الإفراط في الكرم، ويصحّ إرادة المعنى القريب. (١ علامة) أمّا الاستعارة فلا تسمح بإرادة المعنى الحقيقيّ: «ترنّح الضجيج» لا يمكن حملها على الحقيقة، لأنّ الضجيج لا يترنّح.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16387, 2694, 1, '(١ علامة) أ- البيت الأوّل من البحر البسيط، والبحر هو وزنه، أي موسيقاه الخارجيّة التي تُقاس بالتفاعيل. (١ علامة) ب- تكرار الراء والقاف (الترجيع، وتر، الرنين، يغرورق، الوتر) يُحدث تجاوب صوت وصدى. (١ علامة) ج- لأنّ الإيقاع موسيقى داخليّة لا تُقاس بالتفاعيل، تنجم عن تكرار الأصوات وتجاوبها وتتغيّر بتغيّر الحروف وحركاتها، أمّا الوزن فموسيقى خارجيّة تُقاس بالتفاعيل العروضيّة وهو نظام ثابت المعياريّة.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16388, 2694, 2, '(١ علامة) أ- البيت الأوّل من البحر البسيط، والبحر هو وزنه، أي موسيقاه الخارجيّة التي تُقاس بالتفاعيل. (١ علامة) ب- تكرار الراء والقاف (الترجيع، وتر، الرنين، يغرورق، الوتر) يُحدث تجاوب صوت وصدى. (١ علامة) ج- لأنّ الإيقاع موسيقى داخليّة لا تُقاس بالتفاعيل، تنجم عن تكرار الأصوات وتجاوبها وتتغيّر بتغيّر الحروف وحركاتها، أمّا الوزن فموسيقى خارجيّة تُقاس بالتفاعيل العروضيّة وهو نظام ثابت المعياريّة.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16389, 2695, 1, '(١ علامة) زِيادٌ: اسم كان مؤخّر مرفوع وعلامة رفعه الضمّة. (١ علامة) عِنْدَ أَخيهِ: شبه جملة (ظرف ومضاف إليه) في موضع خبر كان المقدّم؛ وجاء قبل الاسم لأنّه يجوز تقديم خبر كان وأخواتها على اسمها.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16390, 2695, 2, '(١ علامة) زِيادٌ: اسم كان مؤخّر مرفوع وعلامة رفعه الضمّة. (١ علامة) عِنْدَ أَخيهِ: شبه جملة (ظرف ومضاف إليه) في موضع خبر كان المقدّم؛ وجاء قبل الاسم لأنّه يجوز تقديم خبر كان وأخواتها على اسمها.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16391, 2696, 1, '(١ علامة) «يتساقط الثلج» خبر لأنّه قُصد فيه الإخبار عن شيء، فيحتمل الصدق والكذب بمعيار مطابقة الواقع؛ و«ما أجمل هذا المنظر!» إنشاء لأنّه ينطلق من اعتبارات ذاتيّة فلا يحتمل صدقًا ولا كذبًا. (١ علامة) الخبر ابتدائيّ لخلوّه من أيّ أداة توكيد؛ والإنشاء غير طلبيّ (تعجّب) لأنّه لا يستدعي مطلوبًا. (١ علامة) يبيّن أنّ الخبر والإنشاء يتكاملان في التعبير الأدبيّ.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16392, 2696, 2, '(١ علامة) «يتساقط الثلج» خبر لأنّه قُصد فيه الإخبار عن شيء، فيحتمل الصدق والكذب بمعيار مطابقة الواقع؛ و«ما أجمل هذا المنظر!» إنشاء لأنّه ينطلق من اعتبارات ذاتيّة فلا يحتمل صدقًا ولا كذبًا. (١ علامة) الخبر ابتدائيّ لخلوّه من أيّ أداة توكيد؛ والإنشاء غير طلبيّ (تعجّب) لأنّه لا يستدعي مطلوبًا. (١ علامة) يبيّن أنّ الخبر والإنشاء يتكاملان في التعبير الأدبيّ.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16393, 2697, 1, '(١ علامة) الرويّ النون، والردف الياء الساكنة التي قبلها مباشرة (حرف لين قبل الرويّ بلا فاصل)، والوصل الياء الناجمة عن إشباع كسرة النون. (١ علامة) القافية مطلقة، لأنّ رويّها (النون) متحرّك؛ ولو كان الرويّ ساكنًا لكانت مقيّدة.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16394, 2697, 2, '(١ علامة) الرويّ النون، والردف الياء الساكنة التي قبلها مباشرة (حرف لين قبل الرويّ بلا فاصل)، والوصل الياء الناجمة عن إشباع كسرة النون. (١ علامة) القافية مطلقة، لأنّ رويّها (النون) متحرّك؛ ولو كان الرويّ ساكنًا لكانت مقيّدة.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16395, 2698, 1, '(١ علامة) نعت سببيّ، لأنّه يبيّن صفة لما له تعلّق بالمنعوت (الصوت)، وجاء بعده اسم متّصل بضمير يعود على المنعوت (صوتُهم، صوتُهنّ). (١ علامة) لأنّ النعت السببيّ يكون مفردًا دائمًا، ويراعي في التذكير والتأنيث ما بعده لا منعوته، و«صَوْت» مذكّر. (١ علامة) أَقْبَلَتِ النِّساءُ الجَميلاتُ الصَّوْتِ: يطابق النعت منعوته في العدد والجنس والإعراب والتعريف، و«الصَّوْتِ» مضاف إليه مجرور.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16396, 2698, 2, '(١ علامة) نعت سببيّ، لأنّه يبيّن صفة لما له تعلّق بالمنعوت (الصوت)، وجاء بعده اسم متّصل بضمير يعود على المنعوت (صوتُهم، صوتُهنّ). (١ علامة) لأنّ النعت السببيّ يكون مفردًا دائمًا، ويراعي في التذكير والتأنيث ما بعده لا منعوته، و«صَوْت» مذكّر. (١ علامة) أَقْبَلَتِ النِّساءُ الجَميلاتُ الصَّوْتِ: يطابق النعت منعوته في العدد والجنس والإعراب والتعريف، و«الصَّوْتِ» مضاف إليه مجرور.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16397, 2699, 1, '(١ علامة) كلاهما مجاز لفظيّ؛ الاستعارة علاقتها المشابهة، وهي تشبيه حُذف أحد طرفيه، مثل: «كانت الأخلاقيّات مصونة بالتديّن». (١ علامة) المجاز المرسل علاقته غير المشابهة، وهي علاقات شتّى، مثل: «شملت الغرب» (مكانيّة) أو «كانوا يحرفون الثلج عن البيوت» (كلّيّة).', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16398, 2699, 2, '(١ علامة) كلاهما مجاز لفظيّ؛ الاستعارة علاقتها المشابهة، وهي تشبيه حُذف أحد طرفيه، مثل: «كانت الأخلاقيّات مصونة بالتديّن». (١ علامة) المجاز المرسل علاقته غير المشابهة، وهي علاقات شتّى، مثل: «شملت الغرب» (مكانيّة) أو «كانوا يحرفون الثلج عن البيوت» (كلّيّة).', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16399, 2700, 1, '(١ علامة) يتألّف الموشّح، وقد شاع في الأندلس منذ القرن الثالث الهجريّ، من: مطلع (مذهب)، ودور، وبيت، وخرجة. (١ علامة) وهو نوعان: نوع يلتزم بحور الخليل، مثل موشّح ابن الخطيب من الرمل؛ ونوع يخالفها، مثل موشّح ابن بقيّ «معذّبي كفاني».', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16400, 2700, 2, '(١ علامة) يتألّف الموشّح، وقد شاع في الأندلس منذ القرن الثالث الهجريّ، من: مطلع (مذهب)، ودور، وبيت، وخرجة. (١ علامة) وهو نوعان: نوع يلتزم بحور الخليل، مثل موشّح ابن الخطيب من الرمل؛ ونوع يخالفها، مثل موشّح ابن بقيّ «معذّبي كفاني».', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16401, 2701, 1, '(١ علامة) «هَواؤُهُ عَطِرٌ» جملة اسميّة في محلّ رفع خبر «إنّ»، لأنّ «إنّ» تنصب اسمها وترفع خبرها، والجملة تُؤوَّل بمفرد مرفوع. (١ علامة) «نَتَّكِلُ» (مع متعلّقها «عَلى الأَحْسابِ») جملة فعليّة في محلّ نصب خبر «ليس»، لأنّ «ليس» من أخوات كان التي ترفع اسمها وتنصب خبرها، والجملة تُؤوَّل بمفرد منصوب.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16402, 2701, 2, '(١ علامة) «هَواؤُهُ عَطِرٌ» جملة اسميّة في محلّ رفع خبر «إنّ»، لأنّ «إنّ» تنصب اسمها وترفع خبرها، والجملة تُؤوَّل بمفرد مرفوع. (١ علامة) «نَتَّكِلُ» (مع متعلّقها «عَلى الأَحْسابِ») جملة فعليّة في محلّ نصب خبر «ليس»، لأنّ «ليس» من أخوات كان التي ترفع اسمها وتنصب خبرها، والجملة تُؤوَّل بمفرد منصوب.', 1, '2026-09-30 22:54:01', '2026-09-30 22:54:01'),
(16403, 2702, 1, '(١ علامة) أ- التمنّع («وتمنّع الشفة البخيلة»)، فالشاعر عرّف سمراءه معتمدًا إبراز الصفات الخلقيّة كالبراعة والتمنّع والعفّة. (١ علامة) ب- يطلب منها ألّا تقترب منه وأن تظلّ له «فكرة لغد جميلة»، لتبقى رمزًا للجمال والأخلاق، فهو يرفض التواصل الجسديّ خوفًا على الحبّ. (١ علامة) ج- ليعبّر عن حبّ يحيا بالشوق ويحافظ على طهر حلم الطفولة، أي حبّ حقيقيّ مقدّس بعيد عن المادّة.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16404, 2702, 2, '(١ علامة) أ- التمنّع («وتمنّع الشفة البخيلة»)، فالشاعر عرّف سمراءه معتمدًا إبراز الصفات الخلقيّة كالبراعة والتمنّع والعفّة. (١ علامة) ب- يطلب منها ألّا تقترب منه وأن تظلّ له «فكرة لغد جميلة»، لتبقى رمزًا للجمال والأخلاق، فهو يرفض التواصل الجسديّ خوفًا على الحبّ. (١ علامة) ج- ليعبّر عن حبّ يحيا بالشوق ويحافظ على طهر حلم الطفولة، أي حبّ حقيقيّ مقدّس بعيد عن المادّة.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16405, 2703, 1, '(١ علامة) أ- الجملة: «لكنّ الذي أدرك اللغة وارد عليها من قبل الأمّة التي تخلّفت في حلبة الحضارة»؛ فالهرم إذًا في أبناء الأمّة لا في اللغة. (١ علامة) ب- في العصر العبّاسيّ أخذ العرب عن الفرس والروم ما لا عهد به للعرب، وزادوا كثيرًا من مصطلحات الأمم التي اجتاحوها، فكانت اللغة مشايعة لهم في كلّ ما أخذوا، ولم يشكُ أحد منها عجزًا ولا تقصيرًا؛ أي أنّها شهدت نموًّا ملحوظًا حين تقدّمت الأمّة. (١ علامة) ج- سمة واحدة: قوّة الحجّة وبراعة الاستنتاج والتعليل (يسلّم بالمظهر ثمّ يستدرك بـ«لكنّ» ليردّ العلّة إلى الأمّة)، أو الأسلوب الواضح المتين البعيد عن السجع والصيغ الشاذّة.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16406, 2703, 2, '(١ علامة) أ- الجملة: «لكنّ الذي أدرك اللغة وارد عليها من قبل الأمّة التي تخلّفت في حلبة الحضارة»؛ فالهرم إذًا في أبناء الأمّة لا في اللغة. (١ علامة) ب- في العصر العبّاسيّ أخذ العرب عن الفرس والروم ما لا عهد به للعرب، وزادوا كثيرًا من مصطلحات الأمم التي اجتاحوها، فكانت اللغة مشايعة لهم في كلّ ما أخذوا، ولم يشكُ أحد منها عجزًا ولا تقصيرًا؛ أي أنّها شهدت نموًّا ملحوظًا حين تقدّمت الأمّة. (١ علامة) ج- سمة واحدة: قوّة الحجّة وبراعة الاستنتاج والتعليل (يسلّم بالمظهر ثمّ يستدرك بـ«لكنّ» ليردّ العلّة إلى الأمّة)، أو الأسلوب الواضح المتين البعيد عن السجع والصيغ الشاذّة.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16407, 2704, 1, '(١ علامة) أ- الطباق بين «مؤلم» و«لذيذ» (في قوله: فخّ مؤلم ولذيذ). (١ علامة) ب- لأنّ صوتها مادّة شعريّة، في حجمها وطاقاتها، من نوع الحبّ أو القدر أو الموضوعات الأساسيّة، فهو يوحي بالشعر كما توحي به هذه الموضوعات الكبرى، لا بالكتابة عنه وحده.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16408, 2704, 2, '(١ علامة) أ- الطباق بين «مؤلم» و«لذيذ» (في قوله: فخّ مؤلم ولذيذ). (١ علامة) ب- لأنّ صوتها مادّة شعريّة، في حجمها وطاقاتها، من نوع الحبّ أو القدر أو الموضوعات الأساسيّة، فهو يوحي بالشعر كما توحي به هذه الموضوعات الكبرى، لا بالكتابة عنه وحده.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16409, 2705, 1, '(١ علامة) لأنّ العلم اكتسب، منذ أوائل هذا القرن، أهمّيّة تفوق أيّ إنجاز آخر طوال تاريخ البشريّة، مع أنّ للإنسانيّة أن تفتخر بفلسفاتها وآدابها وفنونها. (١ علامة) ولأنّه الإنجاز المصيريّ بحقّ: فلأوّل مرّة يدرك الإنسان أنّ العلم هو الذي سيحدّد مصيره سلبًا أو إيجابًا. (١ علامة) وجها الأمل: مستقبل أفضل، وحلّ مشكلاتها الغذائيّة والصحّيّة (ويُقبل أيضًا: حلّ مشكلات الحياة اليوميّة كالغذاء والإسكان والمواصلات والطاقة والبيئة).', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16410, 2706, 1, '(١ علامة) أ- هذه الأشياء الصغيرة من آثار الحبيب توقظ القلب وتجعل نسيانه مستحيلًا، فيتبيّن لها أنّ حبّها لم يذبل وأنّ صورة حبيبها لم تبرح جفنيها. (١ علامة) ب- نداء الكبرياء الذي يريد طيّ الصفحة، ونداء القلب الذي توقظه الأشياء الصغيرة. (١ علامة) ج- لغة يوميّة بعيدة عن غريب الألفاظ، فالقصيدة «خبز يوميّ يتناوله الجميع»، وهذا ما أعطى نزار قاعدة شعبيّة واسعة (الأسلوب النزاريّ واللغة النزاريّة).', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(16411, 2705, 2, '(١ علامة) لأنّ العلم اكتسب، منذ أوائل هذا القرن، أهمّيّة تفوق أيّ إنجاز آخر طوال تاريخ البشريّة، مع أنّ للإنسانيّة أن تفتخر بفلسفاتها وآدابها وفنونها. (١ علامة) ولأنّه الإنجاز المصيريّ بحقّ: فلأوّل مرّة يدرك الإنسان أنّ العلم هو الذي سيحدّد مصيره سلبًا أو إيجابًا. (١ علامة) وجها الأمل: مستقبل أفضل، وحلّ مشكلاتها الغذائيّة والصحّيّة (ويُقبل أيضًا: حلّ مشكلات الحياة اليوميّة كالغذاء والإسكان والمواصلات والطاقة والبيئة).', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16412, 2706, 2, '(١ علامة) أ- هذه الأشياء الصغيرة من آثار الحبيب توقظ القلب وتجعل نسيانه مستحيلًا، فيتبيّن لها أنّ حبّها لم يذبل وأنّ صورة حبيبها لم تبرح جفنيها. (١ علامة) ب- نداء الكبرياء الذي يريد طيّ الصفحة، ونداء القلب الذي توقظه الأشياء الصغيرة. (١ علامة) ج- لغة يوميّة بعيدة عن غريب الألفاظ، فالقصيدة «خبز يوميّ يتناوله الجميع»، وهذا ما أعطى نزار قاعدة شعبيّة واسعة (الأسلوب النزاريّ واللغة النزاريّة).', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16413, 2707, 1, '(١ علامة) أ- شبّه الأعمدة المرمريّة الكثيرة الرشيقة بغابة (من النخيل)، لكثرتها وتقاربها وارتفاعها. (١ علامة) ب- الجمال يبهر الناظر: البصر يُردّ حاسرًا خاشعًا، والعقول تُذهل، والأحلام تطوف به؛ فهو ذهول وانبهار يقود الكاتب إلى الصمت. (١ علامة) ج- الفنّ هذّب المرمر الجامد فردّه جنّة غنّاء، أي إنّ الفنّ يُدخل الحياة إلى الجماد ويحوّله إلى جمال مُذهل.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16414, 2707, 2, '(١ علامة) أ- شبّه الأعمدة المرمريّة الكثيرة الرشيقة بغابة (من النخيل)، لكثرتها وتقاربها وارتفاعها. (١ علامة) ب- الجمال يبهر الناظر: البصر يُردّ حاسرًا خاشعًا، والعقول تُذهل، والأحلام تطوف به؛ فهو ذهول وانبهار يقود الكاتب إلى الصمت. (١ علامة) ج- الفنّ هذّب المرمر الجامد فردّه جنّة غنّاء، أي إنّ الفنّ يُدخل الحياة إلى الجماد ويحوّله إلى جمال مُذهل.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16415, 2708, 1, '(١ علامة) أ- يتّفقان على أنّ للعلم وجهين: فهو عند زكريّا «سيف ذو حدّين» يتسابق في خير البشريّة وشرّها، وهو عند سركيس يوفّر أسباب الرفاهية والصحّة والعلاج لكنّه لا يكفل الاستقرار. (١ علامة) ب- زكريّا يركّز على الخوف الدائم من حرب نوويّة أو بيولوجيّة تدمّر حياة البشريّة وحضارتها. (١ علامة) وسركيس يركّز على الإنسان في داخله: تبدّل نظام المعيشة أنتج ضغطًا مستمرًّا تنشأ منه العلل النفسيّة، والعلم عاجز عن إراحة النفس، ومدنيّة الآلة نمت نموًّا غير طبيعيّ. (١ علامة) ج- أسلوب زكريّا تواصليّ علميّ بسيط بعيد عن الزخرف، لا تشابيه فيه ولا استعارات، واللغة فيه وسيلة لا غاية؛ أمّا سركيس فمقاله فكريّ يعتمد الحجّة والاستدلال ويستعين بصور معبّرة مثل «ربيب الغابات والكهوف».', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16416, 2708, 2, '(١ علامة) أ- يتّفقان على أنّ للعلم وجهين: فهو عند زكريّا «سيف ذو حدّين» يتسابق في خير البشريّة وشرّها، وهو عند سركيس يوفّر أسباب الرفاهية والصحّة والعلاج لكنّه لا يكفل الاستقرار. (١ علامة) ب- زكريّا يركّز على الخوف الدائم من حرب نوويّة أو بيولوجيّة تدمّر حياة البشريّة وحضارتها. (١ علامة) وسركيس يركّز على الإنسان في داخله: تبدّل نظام المعيشة أنتج ضغطًا مستمرًّا تنشأ منه العلل النفسيّة، والعلم عاجز عن إراحة النفس، ومدنيّة الآلة نمت نموًّا غير طبيعيّ. (١ علامة) ج- أسلوب زكريّا تواصليّ علميّ بسيط بعيد عن الزخرف، لا تشابيه فيه ولا استعارات، واللغة فيه وسيلة لا غاية؛ أمّا سركيس فمقاله فكريّ يعتمد الحجّة والاستدلال ويستعين بصور معبّرة مثل «ربيب الغابات والكهوف».', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16417, 2709, 1, '(١ علامة) طبيعة الحبّ في «سمراء»: حبّ حقيقيّ مقدّس بعيد عن المادّة، هو «فكرة لغد جميلة» و«لذّة مستحيلة»، يحيا بالشوق ويرفض التواصل الجسديّ خوفًا على الحبّ. (١ علامة) طبيعة الحبّ في رسالة كنفاني: حبّ حميم صادق عميق يقارب العذاب والموت، حبّ رجل مجروح يعطي ولا يطلب، يقاوم الغياب والمسافات والحواجز. (١ علامة) الألفاظ: عند سعيد عقل ألفاظ متناقضة في معانٍ موحّدة («قلبي مليء بالفراغ الحلو») ونغم هادئ وتجنّب للألفاظ الثقيلة، وعند كنفاني غشاوة سوداويّة (الموت، الجحيم، الحريق، السياط، الجثث) سببها الخوف من الفقدان. (١ علامة) تفسير الخلاصة: الحبّ عاطفة إنسانيّة ذات طبيعة خاصّة بكلّ فرد، فكلّ ينظر إليه من خلال موقعه ومنظاره الخاصّ، وترتبط نظرته بأوضاعه وميوله وثقافته.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16418, 2709, 2, '(١ علامة) طبيعة الحبّ في «سمراء»: حبّ حقيقيّ مقدّس بعيد عن المادّة، هو «فكرة لغد جميلة» و«لذّة مستحيلة»، يحيا بالشوق ويرفض التواصل الجسديّ خوفًا على الحبّ. (١ علامة) طبيعة الحبّ في رسالة كنفاني: حبّ حميم صادق عميق يقارب العذاب والموت، حبّ رجل مجروح يعطي ولا يطلب، يقاوم الغياب والمسافات والحواجز. (١ علامة) الألفاظ: عند سعيد عقل ألفاظ متناقضة في معانٍ موحّدة («قلبي مليء بالفراغ الحلو») ونغم هادئ وتجنّب للألفاظ الثقيلة، وعند كنفاني غشاوة سوداويّة (الموت، الجحيم، الحريق، السياط، الجثث) سببها الخوف من الفقدان. (١ علامة) تفسير الخلاصة: الحبّ عاطفة إنسانيّة ذات طبيعة خاصّة بكلّ فرد، فكلّ ينظر إليه من خلال موقعه ومنظاره الخاصّ، وترتبط نظرته بأوضاعه وميوله وثقافته.', 1, '2026-09-30 22:54:02', '2026-09-30 22:54:02'),
(16419, 2710, 1, '(١ علامة) الموسيقى محرّك كبير لإلهام كلّ كاتب أو شاعر أو فيلسوف، وكان الشعراء دومًا، وفي طليعتهم الشعراء العرب، أشدّ الناس تعبيرًا عن ولعهم بالموسيقى. (١ علامة) والشعراء ينافسون إيقاع الموسيقى ويشتقّون الأوزان منها.', 1, '2026-09-30 22:54:03', '2026-09-30 22:54:03'),
(16420, 2710, 2, '(١ علامة) الموسيقى محرّك كبير لإلهام كلّ كاتب أو شاعر أو فيلسوف، وكان الشعراء دومًا، وفي طليعتهم الشعراء العرب، أشدّ الناس تعبيرًا عن ولعهم بالموسيقى. (١ علامة) والشعراء ينافسون إيقاع الموسيقى ويشتقّون الأوزان منها.', 1, '2026-09-30 22:54:03', '2026-09-30 22:54:03'),
(16421, 2711, 1, '(١ علامة) أنسي الحاج تناول فنّ الغناء: وصف تأثير صوت فيروز في سامعها، ورأى أنّ صوتها مادّة شعريّة تنبع من أصالتها وغنى حياتها الداخليّة؛ ومن براعته الجمل القصيرة الاسميّة والصور والطباق (الطمأنينة والتحريض، الصراخ والهمس). (١ علامة) مصطفى فرّوخ تناول جمال ساحة الأسود في قصر الحمراء بعين الرسّام: الأعمدة والنقوش والتخاريم والبركة المثمّنة على اثني عشر أسدًا؛ ومن براعته الوصف الأنيق والتعابير الشعريّة (غابة من المرمر هذّبها الفنّ فردّها جنّة غنّاء). (١ علامة) فكلاهما كاتب فنّان يتمتّع بثقافة فنّيّة وحسّ مرهف وقدرة أسلوبيّة، فجاء نصّه في مستوى يحاكي الفنّ الذي يصوّره، وهذا يؤكّد أنّ الأدب مجال رحب للتعبير عن الفنّ والجمال.', 1, '2026-09-30 22:54:03', '2026-09-30 22:54:03'),
(16422, 2711, 2, '(١ علامة) أنسي الحاج تناول فنّ الغناء: وصف تأثير صوت فيروز في سامعها، ورأى أنّ صوتها مادّة شعريّة تنبع من أصالتها وغنى حياتها الداخليّة؛ ومن براعته الجمل القصيرة الاسميّة والصور والطباق (الطمأنينة والتحريض، الصراخ والهمس). (١ علامة) مصطفى فرّوخ تناول جمال ساحة الأسود في قصر الحمراء بعين الرسّام: الأعمدة والنقوش والتخاريم والبركة المثمّنة على اثني عشر أسدًا؛ ومن براعته الوصف الأنيق والتعابير الشعريّة (غابة من المرمر هذّبها الفنّ فردّها جنّة غنّاء). (١ علامة) فكلاهما كاتب فنّان يتمتّع بثقافة فنّيّة وحسّ مرهف وقدرة أسلوبيّة، فجاء نصّه في مستوى يحاكي الفنّ الذي يصوّره، وهذا يؤكّد أنّ الأدب مجال رحب للتعبير عن الفنّ والجمال.', 1, '2026-09-30 22:54:03', '2026-09-30 22:54:03'),
(16423, 2712, 1, '(١ علامة) أ- يرى دون كيخوته عمالقة متمرّدين يشوّهون أرضه فيصيح بهم «أيّتها الجبناء»، والحقيقة أنّها مطاحن هوائيّة (ثلاثون مطحنة)؛ وهذه المفارقة بين الوهم والحقيقة. (١ علامة) ب- لم يعترف بخطئه بل فسّر سقوطه بأنّ شؤون الحرب عرضة للتقلّبات وأنّ كتب الفروسيّة تحذّر من مكايد الأشرار، ولم يشكُ ولم يتأوّه لأنّ ذلك ليس من شيم الفرسان. (١ علامة) ج- التناقض بين السيّد والخادم: سانتشو الواقعيّ يتوسّل إليه ويصحّح له، والسيّد يندفع غير مصغٍ لتوسّلاته.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16424, 2712, 2, '(١ علامة) أ- يرى دون كيخوته عمالقة متمرّدين يشوّهون أرضه فيصيح بهم «أيّتها الجبناء»، والحقيقة أنّها مطاحن هوائيّة (ثلاثون مطحنة)؛ وهذه المفارقة بين الوهم والحقيقة. (١ علامة) ب- لم يعترف بخطئه بل فسّر سقوطه بأنّ شؤون الحرب عرضة للتقلّبات وأنّ كتب الفروسيّة تحذّر من مكايد الأشرار، ولم يشكُ ولم يتأوّه لأنّ ذلك ليس من شيم الفرسان. (١ علامة) ج- التناقض بين السيّد والخادم: سانتشو الواقعيّ يتوسّل إليه ويصحّح له، والسيّد يندفع غير مصغٍ لتوسّلاته.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16425, 2713, 1, '(١ علامة) أ- لبنان ملتقى الأمم والثقافات وهمزة وصل بين الشرق والغرب، فهو صلة وصل لا يتنكّر للشرق ولا ينغلق عن الغرب، ورسالته ثقافة تواصل. (١ علامة) ب- الجمل المتناسقة التي تقدّم إيقاعات موسيقيّة لفظيّة: «ملتقى/معترك/مزدحم» و«المتفرّقة/المتنافسة/المتقاطعة»، فتتآلف مع جزالة المعاني والمباني. (١ علامة) ج- لأنّ موضوع النصّ يتطلّب تحليلًا موضوعيًّا استقرائيًّا بعيدًا عن الانفعال والعاطفة المتدفّقة، فابتعد عن الإبهام المضلّل أو التلميح الذي لا يقود إلى صلب الحقيقة.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16426, 2713, 2, '(١ علامة) أ- لبنان ملتقى الأمم والثقافات وهمزة وصل بين الشرق والغرب، فهو صلة وصل لا يتنكّر للشرق ولا ينغلق عن الغرب، ورسالته ثقافة تواصل. (١ علامة) ب- الجمل المتناسقة التي تقدّم إيقاعات موسيقيّة لفظيّة: «ملتقى/معترك/مزدحم» و«المتفرّقة/المتنافسة/المتقاطعة»، فتتآلف مع جزالة المعاني والمباني. (١ علامة) ج- لأنّ موضوع النصّ يتطلّب تحليلًا موضوعيًّا استقرائيًّا بعيدًا عن الانفعال والعاطفة المتدفّقة، فابتعد عن الإبهام المضلّل أو التلميح الذي لا يقود إلى صلب الحقيقة.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16427, 2714, 1, '(١ علامة) ظهرت عبقريّة سرڤانتس في عمر متقدّم، إذ كان ابن سبع وخمسين سنة عندما أنهى القسم الأوّل من روايته، فجاءت شخصيّته مميّزة في عمر النضج بعدما شحذتها حياته المضطربة. (٢ علامتان: ثلاث محطّات صحيحة) من محطّات حياته: نشأ في أسرة وضيعة تتقلّب في مصاعب الحياة؛ شارك في معركة ليبانتو وأصيب في عدّة أماكن من جسمه («أقطع ليبانتو»)؛ أُسر في الجزائر خمس سنوات وفشلت أربع محاولات فرار ثمّ عاد إلى إسبانيا فقيرًا؛ تعثّر نشاطه الأدبيّ ماديًّا فعمل في تموين الأرمادا وجباية الضرائب، وسُجن مرّتين بسبب الديون، وأنهى القسم الأوّل من «دون كيخوته» في السجن سنة ١٥٩٧.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16428, 2714, 2, '(١ علامة) ظهرت عبقريّة سرڤانتس في عمر متقدّم، إذ كان ابن سبع وخمسين سنة عندما أنهى القسم الأوّل من روايته، فجاءت شخصيّته مميّزة في عمر النضج بعدما شحذتها حياته المضطربة. (٢ علامتان: ثلاث محطّات صحيحة) من محطّات حياته: نشأ في أسرة وضيعة تتقلّب في مصاعب الحياة؛ شارك في معركة ليبانتو وأصيب في عدّة أماكن من جسمه («أقطع ليبانتو»)؛ أُسر في الجزائر خمس سنوات وفشلت أربع محاولات فرار ثمّ عاد إلى إسبانيا فقيرًا؛ تعثّر نشاطه الأدبيّ ماديًّا فعمل في تموين الأرمادا وجباية الضرائب، وسُجن مرّتين بسبب الديون، وأنهى القسم الأوّل من «دون كيخوته» في السجن سنة ١٥٩٧.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16429, 2715, 1, '(١ علامة) أ- تعني تبدّل الأحوال بين الحضارتين: مضى زمن كانت أوروبا فيه تتلقّى الحضارة العربيّة وتُقبل على كلّ ما هو عربيّ، ثمّ صار أبناء الشرق يُقبلون على كلّ ما هو أوروبيّ؛ فالحضارة دَين تتوارثه الأمم بين أخذ وعطاء. (١ علامة) ب- لأنّ الولع بكلّ جديد لأنّه جديد هو تعليم القصور، وهو دليل على نقص في التمييز كالولع بكلّ قديم، والحرّيّة الحقّة مقياسها التمييز والاختيار. (١ علامة) ج- جديد/قديم، شرقيّ/أوروبيّ (نصف علامة لكلّ مقابلة).', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16430, 2715, 2, '(١ علامة) أ- تعني تبدّل الأحوال بين الحضارتين: مضى زمن كانت أوروبا فيه تتلقّى الحضارة العربيّة وتُقبل على كلّ ما هو عربيّ، ثمّ صار أبناء الشرق يُقبلون على كلّ ما هو أوروبيّ؛ فالحضارة دَين تتوارثه الأمم بين أخذ وعطاء. (١ علامة) ب- لأنّ الولع بكلّ جديد لأنّه جديد هو تعليم القصور، وهو دليل على نقص في التمييز كالولع بكلّ قديم، والحرّيّة الحقّة مقياسها التمييز والاختيار. (١ علامة) ج- جديد/قديم، شرقيّ/أوروبيّ (نصف علامة لكلّ مقابلة).', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16431, 2716, 1, '(١ علامة) يكشفان أنّ البطل يعيش في عالم هو مزيج من الواقع والخيال، فيحوّل الأشياء العاديّة إلى أعداء يستوجبون المبارزة كما في كتب الفروسيّة. (١ علامة) والسبب أنّ ألونسو كيخانو شغف بكتب الفروسيّة شغفًا جعله أسيرها، فراح يخلط الواقع بالخيال.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16432, 2717, 1, '(١ علامة) أ- زريق يكتب بمنهج العالم: ملاحظة واستنتاج وتجرّد عن العاطفة والخيال، بجمل قصيرة وعبارات متوازنة وأدوات استنتاج. (١ علامة) وصدقي يكتب بأسلوب المحاضر: جمل قصيرة تقريريّة وثنائيّات تنظّم الفكر (السطح/الصميم، العقل/الروح)، وصور قليلة مركّزة. (١ علامة) ب- العقّاد يرى الحضارة دَينًا متوارثًا بين الأمم: تعلّمت أوروبا من الشرق القديم، ثمّ تعلّم الشرق الحديث من أوروبا. (١ علامة) وصدقي يرى أنّ العرب لم ينقلوا تراث الإغريق بل أعادوا إنشاءه، وأنّ أوروبا أقامت على المعقوليّة الأرسطيّة العلم؛ فالتفاعل عندهما أخذ وعطاء، تكامل لا تبعيّة.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16433, 2716, 2, '(١ علامة) يكشفان أنّ البطل يعيش في عالم هو مزيج من الواقع والخيال، فيحوّل الأشياء العاديّة إلى أعداء يستوجبون المبارزة كما في كتب الفروسيّة. (١ علامة) والسبب أنّ ألونسو كيخانو شغف بكتب الفروسيّة شغفًا جعله أسيرها، فراح يخلط الواقع بالخيال.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16434, 2717, 2, '(١ علامة) أ- زريق يكتب بمنهج العالم: ملاحظة واستنتاج وتجرّد عن العاطفة والخيال، بجمل قصيرة وعبارات متوازنة وأدوات استنتاج. (١ علامة) وصدقي يكتب بأسلوب المحاضر: جمل قصيرة تقريريّة وثنائيّات تنظّم الفكر (السطح/الصميم، العقل/الروح)، وصور قليلة مركّزة. (١ علامة) ب- العقّاد يرى الحضارة دَينًا متوارثًا بين الأمم: تعلّمت أوروبا من الشرق القديم، ثمّ تعلّم الشرق الحديث من أوروبا. (١ علامة) وصدقي يرى أنّ العرب لم ينقلوا تراث الإغريق بل أعادوا إنشاءه، وأنّ أوروبا أقامت على المعقوليّة الأرسطيّة العلم؛ فالتفاعل عندهما أخذ وعطاء، تكامل لا تبعيّة.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16435, 2718, 1, '(١ علامة) يدعو أناتول فرانس كلّ إنسان إلى أن يرى العمالقة في طواحين الهواء لئلّا يغفل عن رؤية الحقيقة المخبّأة، أي ألّا يكتفي بظاهر الواقع ويحمل حلمًا يدفعه إلى المواجهة. (١ علامة) ويلتقي ذلك مع قول شوبنهاور: «يجسّد دون كيخوته حياة كلّ رجل يرفض واقعه ويسعى إلى هدف سامٍ»؛ فكلاهما يرى في دون كيخوته رمزًا إنسانيًّا عامًّا، وفي كلّ إنسان نقاط يمكن أن تجعل منه «دون كيخوته» آخر.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16436, 2718, 2, '(١ علامة) يدعو أناتول فرانس كلّ إنسان إلى أن يرى العمالقة في طواحين الهواء لئلّا يغفل عن رؤية الحقيقة المخبّأة، أي ألّا يكتفي بظاهر الواقع ويحمل حلمًا يدفعه إلى المواجهة. (١ علامة) ويلتقي ذلك مع قول شوبنهاور: «يجسّد دون كيخوته حياة كلّ رجل يرفض واقعه ويسعى إلى هدف سامٍ»؛ فكلاهما يرى في دون كيخوته رمزًا إنسانيًّا عامًّا، وفي كلّ إنسان نقاط يمكن أن تجعل منه «دون كيخوته» آخر.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16437, 2719, 1, '(١ علامة) «أَدْخَلَهُ» على وزن أَفْعَلَ، ومعنى الزيادة فيه التعدية. (١ علامة) «انْكَسَرَ» على وزن انْفَعَلَ، ومعنى الزيادة فيه مطاوعة فَعَلَ (كَسَرَهُ فَانْكَسَرَ). (١ علامة) مصدر أَفْعَلَ على وزن إِفْعال: إِدْخال. (١ علامة) مصدر انْفَعَلَ على وزن انْفِعال: انْكِسار.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16438, 2719, 2, '(١ علامة) «أَدْخَلَهُ» على وزن أَفْعَلَ، ومعنى الزيادة فيه التعدية. (١ علامة) «انْكَسَرَ» على وزن انْفَعَلَ، ومعنى الزيادة فيه مطاوعة فَعَلَ (كَسَرَهُ فَانْكَسَرَ). (١ علامة) مصدر أَفْعَلَ على وزن إِفْعال: إِدْخال. (١ علامة) مصدر انْفَعَلَ على وزن انْفِعال: انْكِسار.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16439, 2720, 1, '(١ علامة) «مُسْتَلَذٌّ» اسم مفعول من غير الثلاثيّ (اسْتَلَذَّ)، صيغ من المضارع المجهول بإبدال حرف المضارعة ميمًا مضمومة. (١ علامة) «بَسِيطُهُ» نائب فاعل مرفوع، لأنّ اسم المفعول يعمل عمل الفعل المجهول فيرفع نائب فاعل.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16440, 2720, 2, '(١ علامة) «مُسْتَلَذٌّ» اسم مفعول من غير الثلاثيّ (اسْتَلَذَّ)، صيغ من المضارع المجهول بإبدال حرف المضارعة ميمًا مضمومة. (١ علامة) «بَسِيطُهُ» نائب فاعل مرفوع، لأنّ اسم المفعول يعمل عمل الفعل المجهول فيرفع نائب فاعل.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16441, 2721, 1, '(١ علامة) أداة الشرط «مَهْما»، وهي أداة شرط جازمة، وهي اسم (أدوات الشرط الجازمة أسماء كلّها ما عدا إِنْ). (١ علامة) اقترن الجواب «فَإِنَّنِي مُسْتَعِدٌّ» بالفاء وجوبًا لأنّه جملة اسميّة.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16442, 2721, 2, '(١ علامة) أداة الشرط «مَهْما»، وهي أداة شرط جازمة، وهي اسم (أدوات الشرط الجازمة أسماء كلّها ما عدا إِنْ). (١ علامة) اقترن الجواب «فَإِنَّنِي مُسْتَعِدٌّ» بالفاء وجوبًا لأنّه جملة اسميّة.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16443, 2722, 1, '(١ علامة) الفاصلة وقفة قصيرة وُضعت بين الشرط «كلّما صغرت القرية» والجزاء «كبر شرّ أهلها»، ومن مواضع الفاصلة الفصل بين الشرط والجزاء. (١ علامة) النقطة وُضعت في نهاية جملة تمّ معناها.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16444, 2722, 2, '(١ علامة) الفاصلة وقفة قصيرة وُضعت بين الشرط «كلّما صغرت القرية» والجزاء «كبر شرّ أهلها»، ومن مواضع الفاصلة الفصل بين الشرط والجزاء. (١ علامة) النقطة وُضعت في نهاية جملة تمّ معناها.', 1, '2026-09-30 22:54:04', '2026-09-30 22:54:04'),
(16445, 2723, 1, '(١ علامة) (أ) الشركة من مجموعة المؤسّسات غير الماليّة، ومن الأمور التي تشملها وظيفتها (يكفي اثنان): شراء عناصر الإنتاج لتحويلها إلى سلع وخدمات تُسوَّق في الداخل والخارج؛ عقد القروض أو إصدار الأسهم وسندات الدين لتكوين رأس المال الثابت؛ توزيع القيمة المضافة على شكل مداخيل لعناصر الإنتاج؛ تغذية الدولة بالضرائب المباشرة وغير المباشرة. (١ علامة) (ب) القيمة المضافة = رقم الأعمال − قيمة السلع الوسيطة = 1500 − 900 = 600 مليون ليرة لبنانيّة (½ للعلاقة و½ للنتيجة). (١ علامة) (ج) تنال المصارف فوائد لأنّها مقرضة للمنشأة (½)، وتنال الدولة ضرائب ورسومًا لأنّها تقدّم البنى التحتيّة والخدمات العامّة (½).', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16446, 2723, 2, '(١ علامة) (أ) الشركة من مجموعة المؤسّسات غير الماليّة، ومن الأمور التي تشملها وظيفتها (يكفي اثنان): شراء عناصر الإنتاج لتحويلها إلى سلع وخدمات تُسوَّق في الداخل والخارج؛ عقد القروض أو إصدار الأسهم وسندات الدين لتكوين رأس المال الثابت؛ توزيع القيمة المضافة على شكل مداخيل لعناصر الإنتاج؛ تغذية الدولة بالضرائب المباشرة وغير المباشرة. (١ علامة) (ب) القيمة المضافة = رقم الأعمال − قيمة السلع الوسيطة = 1500 − 900 = 600 مليون ليرة لبنانيّة (½ للعلاقة و½ للنتيجة). (١ علامة) (ج) تنال المصارف فوائد لأنّها مقرضة للمنشأة (½)، وتنال الدولة ضرائب ورسومًا لأنّها تقدّم البنى التحتيّة والخدمات العامّة (½).', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16447, 2724, 1, '(١ علامة) المعادلة النهائيّة: الناتج المحلّي القائم + الاستيراد = الاستهلاك + التكوين القائم لرأس المال الثابت + الصادرات + تغيّر المخزون. (١ علامة) 800 + 200 = 600 + التكوين القائم لرأس المال الثابت + 150 + 30، أي 1000 = 780 + التكوين القائم لرأس المال الثابت، فالتكوين القائم لرأس المال الثابت = 1000 − 780 = 220. (١ علامة) التحقّق: الناتج المحلّي القائم + الاستيراد − التصدير = الاستهلاك + تكوين رأس المال + التغيّر في المخزون، أي 800 + 200 − 150 = 850، و600 + 220 + 30 = 850، فالكفّتان متعادلتان والنتيجة صحيحة. (١ علامة) معدّل الاستثمار = التكوين القائم لرأس المال الثابت ÷ الناتج المحلّي القائم = 220 ÷ 800 = 0,275 أي 27,5%.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16448, 2724, 2, '(١ علامة) المعادلة النهائيّة: الناتج المحلّي القائم + الاستيراد = الاستهلاك + التكوين القائم لرأس المال الثابت + الصادرات + تغيّر المخزون. (١ علامة) 800 + 200 = 600 + التكوين القائم لرأس المال الثابت + 150 + 30، أي 1000 = 780 + التكوين القائم لرأس المال الثابت، فالتكوين القائم لرأس المال الثابت = 1000 − 780 = 220. (١ علامة) التحقّق: الناتج المحلّي القائم + الاستيراد − التصدير = الاستهلاك + تكوين رأس المال + التغيّر في المخزون، أي 800 + 200 − 150 = 850، و600 + 220 + 30 = 850، فالكفّتان متعادلتان والنتيجة صحيحة. (١ علامة) معدّل الاستثمار = التكوين القائم لرأس المال الثابت ÷ الناتج المحلّي القائم = 220 ÷ 800 = 0,275 أي 27,5%.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16449, 2725, 1, '(١ علامة) (أ) الموارد = الناتج المحلّي + الاستيراد = 800 + 300 = 1100 مليار. (١ علامة) (ب) لأنّ الموارد نفسها هي التي تُستعمل في المجالات الخمسة (استهلاك القطاع الخاصّ واستثماراته، واستهلاك الإدارات العامّة واستثماراتها، والتصدير)، فكلّ سلعة دخلت البلد أو أُنتجت فيه لا بدّ أن تكون قد استُهلكت أو استُثمرت أو صُدِّرت؛ لذا يوجد توازن تامّ بين الموارد والاستعمالات (التوازن العامّ لحساب السلع والخدمات). (١ علامة) (ج) الاستعمالات = 1100، ومجموع الاستعمالات من دون التصدير = 650 + 150 + 100 + 50 = 950، إذاً التصدير = 1100 − 950 = 150 مليار.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16450, 2725, 2, '(١ علامة) (أ) الموارد = الناتج المحلّي + الاستيراد = 800 + 300 = 1100 مليار. (١ علامة) (ب) لأنّ الموارد نفسها هي التي تُستعمل في المجالات الخمسة (استهلاك القطاع الخاصّ واستثماراته، واستهلاك الإدارات العامّة واستثماراتها، والتصدير)، فكلّ سلعة دخلت البلد أو أُنتجت فيه لا بدّ أن تكون قد استُهلكت أو استُثمرت أو صُدِّرت؛ لذا يوجد توازن تامّ بين الموارد والاستعمالات (التوازن العامّ لحساب السلع والخدمات). (١ علامة) (ج) الاستعمالات = 1100، ومجموع الاستعمالات من دون التصدير = 650 + 150 + 100 + 50 = 950، إذاً التصدير = 1100 − 950 = 150 مليار.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16451, 2726, 1, '(١ علامة) أ- عائدات عناصر الإنتاج التي يملكونها: الرواتب والأجور والإيجارات والريوع والأرباح، إضافةً إلى التحويلات التي تردهم من قطاعات أخرى. (١ علامة) ب- مثالان من: المزيّن، النجّار، المزارع، الحرفي (نصف علامة لكلّ مثال). (١ علامة) ج- لأنّ وحدات القطاع العائلي لا تمسك محاسبة خاصّة بها، ولذلك يُعتبر قطاعاً غير واضح المعالم؛ أمّا المشاريع الفرديّة فلا تُعدّ من شبه الشركات إلّا إذا أمسكت محاسبة منتظمة، وتمتّعت باستقلال في قرارات التمويل وتوزيع الدخل، وكانت ذمّتها الماليّة منفصلة عن ذمّة أصحابها.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16452, 2726, 2, '(١ علامة) أ- عائدات عناصر الإنتاج التي يملكونها: الرواتب والأجور والإيجارات والريوع والأرباح، إضافةً إلى التحويلات التي تردهم من قطاعات أخرى. (١ علامة) ب- مثالان من: المزيّن، النجّار، المزارع، الحرفي (نصف علامة لكلّ مثال). (١ علامة) ج- لأنّ وحدات القطاع العائلي لا تمسك محاسبة خاصّة بها، ولذلك يُعتبر قطاعاً غير واضح المعالم؛ أمّا المشاريع الفرديّة فلا تُعدّ من شبه الشركات إلّا إذا أمسكت محاسبة منتظمة، وتمتّعت باستقلال في قرارات التمويل وتوزيع الدخل، وكانت ذمّتها الماليّة منفصلة عن ذمّة أصحابها.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16453, 2727, 1, '(١ علامة) (أ) عمليّة متعلّقة بالسلع والخدمات (استثمارات الإدارات العامّة)، وتظهر في دارة العمليّات المتعلّقة بالسلع والخدمات. (١ علامة) (ب) عمليّة توزيع (إعادة توزيع)، وتظهر في دارة عمليّات التوزيع التي تربط المنشآت الاقتصاديّة والأسر والإدارات العامّة. (١ علامة) (ج) عمليّة ماليّة (تمويل)، وتظهر في دارة العمليّات الماليّة. (١ علامة) تؤدّي السوق الماليّة دور الوسيط المالي: تستقطب مدّخرات الأسر والمنشآت ذات الفائض المالي عن طريق الودائع المصرفيّة أو بيع الأدوات الماليّة، ثمّ تزوّد بالمال المنشآت التي تحتاج إلى تمويل كهذه المنشأة.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16454, 2727, 2, '(١ علامة) (أ) عمليّة متعلّقة بالسلع والخدمات (استثمارات الإدارات العامّة)، وتظهر في دارة العمليّات المتعلّقة بالسلع والخدمات. (١ علامة) (ب) عمليّة توزيع (إعادة توزيع)، وتظهر في دارة عمليّات التوزيع التي تربط المنشآت الاقتصاديّة والأسر والإدارات العامّة. (١ علامة) (ج) عمليّة ماليّة (تمويل)، وتظهر في دارة العمليّات الماليّة. (١ علامة) تؤدّي السوق الماليّة دور الوسيط المالي: تستقطب مدّخرات الأسر والمنشآت ذات الفائض المالي عن طريق الودائع المصرفيّة أو بيع الأدوات الماليّة، ثمّ تزوّد بالمال المنشآت التي تحتاج إلى تمويل كهذه المنشأة.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16455, 2728, 1, '(١ علامة) الفائدة الأولى: تُلزم قواعد المحاسبة علماء الاقتصاد بتوضيح تعاريفهم وتعابيرهم، وبالتالي بتوضيح مضمون النظريّات التي يطلقونها، لأنّها تعبّر عن كميّات يجب جمعها لاستخراج أرصدتها. (١ علامة) الفائدة الثانية: تسهّل هذه القواعد، بسبب مرونتها، تفصيل الحسابات أو إعادة تجميعها ضمن مجموعات تسمّى قطاعات. (١ علامة) ولأنّها مفيدة لتوضيح النظريّات الاقتصاديّة، تفرض المحاسبة الوطنيّة نفسها على رسم السياسات الاقتصاديّة للدولة العصريّة؛ فتداخل العناصر في الاقتصاد العصري يفرض آليّة تنسيق لم تعد تجاذبات السوق قادرة عليها، فتأخذ الدولة، بصفتها الممثّل الوحيد للمصلحة العامّة، مهمّة الحكم العامّ، وهي مهمّة تتطلّب اطّلاعاً كاملاً على أرقام القطاعات وأوضاعها لا تدخّلاً دائماً.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16456, 2728, 2, '(١ علامة) الفائدة الأولى: تُلزم قواعد المحاسبة علماء الاقتصاد بتوضيح تعاريفهم وتعابيرهم، وبالتالي بتوضيح مضمون النظريّات التي يطلقونها، لأنّها تعبّر عن كميّات يجب جمعها لاستخراج أرصدتها. (١ علامة) الفائدة الثانية: تسهّل هذه القواعد، بسبب مرونتها، تفصيل الحسابات أو إعادة تجميعها ضمن مجموعات تسمّى قطاعات. (١ علامة) ولأنّها مفيدة لتوضيح النظريّات الاقتصاديّة، تفرض المحاسبة الوطنيّة نفسها على رسم السياسات الاقتصاديّة للدولة العصريّة؛ فتداخل العناصر في الاقتصاد العصري يفرض آليّة تنسيق لم تعد تجاذبات السوق قادرة عليها، فتأخذ الدولة، بصفتها الممثّل الوحيد للمصلحة العامّة، مهمّة الحكم العامّ، وهي مهمّة تتطلّب اطّلاعاً كاملاً على أرقام القطاعات وأوضاعها لا تدخّلاً دائماً.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16457, 2729, 1, 'أ- (١ علامة) لا يقبل الفرد النقد لقيمته الذاتيّة، فقيمته السلعيّة في حدّ ذاتها لا تساوي شيئاً (كورقة من فئة مئة ألف ليرة لبنانيّة)، بل لإيمانه بأنّه محلّ قبول جماعيّ ضمن مجتمع محدّد، أي لإيمانه بأنّ غيره سيقبله؛ فلا تؤدّي سلعة دور النقد إلّا إذا قبل بها أفراد المجتمع. (١ علامة) وهذا القبول العامّ مدعوم بقوّة القانون على مستوى الوطن: فالنقد الرمزي يصدره المصرف المركزي ويتمتّع بحكم القانون بالتعامل الإجباري، ولا يستطيع حامله طلب إبداله بالمعدن الثمين (ومثاله الليرة اللبنانيّة في لبنان).\nب- (١ علامة) لا، الشك ليس نقداً، لأنّ مجتمعه أضيق من مجتمع النقد الورقيّ: استخدامه محصور بفئة محدّدة من ذوي الدخل المرتفع نسبيّاً ممّن لديهم حسابات دائنة في المصارف، أمّا النقد الورقيّ فيقبله أفراد المجتمع كافّة. (١ علامة) وهو ليس شكلاً مستقلّاً من النقد، بل أداة لتحريك الحساب (النقد الخطّي، أي الحساب لحين الطلب المفتوح لدى أحد المصارف) ونقل النقد من حساب المدين إلى حساب الدائن.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16458, 2729, 2, 'أ- (١ علامة) لا يقبل الفرد النقد لقيمته الذاتيّة، فقيمته السلعيّة في حدّ ذاتها لا تساوي شيئاً (كورقة من فئة مئة ألف ليرة لبنانيّة)، بل لإيمانه بأنّه محلّ قبول جماعيّ ضمن مجتمع محدّد، أي لإيمانه بأنّ غيره سيقبله؛ فلا تؤدّي سلعة دور النقد إلّا إذا قبل بها أفراد المجتمع. (١ علامة) وهذا القبول العامّ مدعوم بقوّة القانون على مستوى الوطن: فالنقد الرمزي يصدره المصرف المركزي ويتمتّع بحكم القانون بالتعامل الإجباري، ولا يستطيع حامله طلب إبداله بالمعدن الثمين (ومثاله الليرة اللبنانيّة في لبنان).\nب- (١ علامة) لا، الشك ليس نقداً، لأنّ مجتمعه أضيق من مجتمع النقد الورقيّ: استخدامه محصور بفئة محدّدة من ذوي الدخل المرتفع نسبيّاً ممّن لديهم حسابات دائنة في المصارف، أمّا النقد الورقيّ فيقبله أفراد المجتمع كافّة. (١ علامة) وهو ليس شكلاً مستقلّاً من النقد، بل أداة لتحريك الحساب (النقد الخطّي، أي الحساب لحين الطلب المفتوح لدى أحد المصارف) ونقل النقد من حساب المدين إلى حساب الدائن.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16459, 2730, 1, 'أ- (١ علامة) مضاعف الائتمان = 1 ÷ معدّل السيولة = 1 ÷ 0.1 = 10؛ مجموع الودائع = 1000 × 10 = 10000 ليرة.\nب- (١ علامة) المضاعف الجديد = 1 ÷ 0.2 = 5؛ مجموع الودائع = 1000 × 5 = 5000 ليرة. العلاقة بين معدّل السيولة والمضاعف عكسيّة: ارتفاع معدّل السيولة يصغّر المضاعف ويقلّل قدرة المصارف على خلق النقد الخطيّ؛ ويتوجّب على المصرف زيادة هذه النسبة عند شعوره بازدياد المخاطر بسبب الأزمات الاقتصاديّة أو عدم الاستقرار السياسيّ أو الأحداث الأمنيّة.\nج- (١ علامة) يشتري المصرف المال من الزبائن المودعين مقابل ثمن هو الفائدة الدائنة، ويبيعه للمستثمرين مقابل ثمن أعلى هو الفائدة المدينة، والفرق بينهما يغطّي تكاليفه ويحقّق ربحه؛ لذلك يزيد تسليفاته ليحقّق ربحيّة أعلى. لكنّ السيولة والربحيّة عنصران يؤثّران في اتجاهين متعاكسين: زيادة التسليفات تخفض نسبة السيولة، فيصبح المصرف أكثر عرضةً للتعثّر في حال حصول أزمة سحوبات.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16460, 2730, 2, 'أ- (١ علامة) مضاعف الائتمان = 1 ÷ معدّل السيولة = 1 ÷ 0.1 = 10؛ مجموع الودائع = 1000 × 10 = 10000 ليرة.\nب- (١ علامة) المضاعف الجديد = 1 ÷ 0.2 = 5؛ مجموع الودائع = 1000 × 5 = 5000 ليرة. العلاقة بين معدّل السيولة والمضاعف عكسيّة: ارتفاع معدّل السيولة يصغّر المضاعف ويقلّل قدرة المصارف على خلق النقد الخطيّ؛ ويتوجّب على المصرف زيادة هذه النسبة عند شعوره بازدياد المخاطر بسبب الأزمات الاقتصاديّة أو عدم الاستقرار السياسيّ أو الأحداث الأمنيّة.\nج- (١ علامة) يشتري المصرف المال من الزبائن المودعين مقابل ثمن هو الفائدة الدائنة، ويبيعه للمستثمرين مقابل ثمن أعلى هو الفائدة المدينة، والفرق بينهما يغطّي تكاليفه ويحقّق ربحه؛ لذلك يزيد تسليفاته ليحقّق ربحيّة أعلى. لكنّ السيولة والربحيّة عنصران يؤثّران في اتجاهين متعاكسين: زيادة التسليفات تخفض نسبة السيولة، فيصبح المصرف أكثر عرضةً للتعثّر في حال حصول أزمة سحوبات.', 1, '2026-09-30 22:54:05', '2026-09-30 22:54:05'),
(16461, 2731, 1, 'أ- (١ علامة) رفع نسبة الاحتياطيّ الإلزاميّ: تودع المصارف لدى المصرف المركزيّ ودائع لا تقلّ عن الاحتياطيّ الإلزاميّ، فإذا رفع مصرف لبنان هذه النسبة انخفضت السيولة المتاحة للمصارف وانخفضت قدرتها على التسليف. (١ علامة) زيادة معدّل فائدة إعادة الحسم: حين تحتاج المصارف إلى السيولة يقدّم لها مصرف لبنان تسهيلات بحسم سندات تجاريّة لديها، فزيادة هذا المعدّل تزيد كلفة المصارف، فيرتفع معدّل الفائدة المدينة ويحجم الزبائن عن طلب القروض لأنّها أصبحت باهظة الثمن، ويرتفع معدّل الفائدة الدائنة فيزيد الزبائن ودائعهم بدل الاحتفاظ بالنقد للاستهلاك.\nب- (١ علامة) لأنّ صلاحيّات السلطة النقديّة لا تخوّلها التدخّل للتأثير مباشرةً في كميّة السلع المنتجة، فتدخّلها تمهيد لسياسة اقتصاديّة أكثر فعاليّة تتّخذها الحكومة بأجهزتها كافّة، ومن عناصرها (يكفي عنصران): زيادة الإنتاج في مختلف القطاعات وتخفيض كلفته؛ مراقبة الأسعار وتحديدها؛ اتّباع سياسة ضريبيّة تحوّل قسماً أكبر من المدّخرات المتاحة للاستهلاك التضخّميّ نحو استثمارات منتجة تزيد حجم العرض.', 1, '2026-09-30 22:54:06', '2026-09-30 22:54:06'),
(16462, 2731, 2, 'أ- (١ علامة) رفع نسبة الاحتياطيّ الإلزاميّ: تودع المصارف لدى المصرف المركزيّ ودائع لا تقلّ عن الاحتياطيّ الإلزاميّ، فإذا رفع مصرف لبنان هذه النسبة انخفضت السيولة المتاحة للمصارف وانخفضت قدرتها على التسليف. (١ علامة) زيادة معدّل فائدة إعادة الحسم: حين تحتاج المصارف إلى السيولة يقدّم لها مصرف لبنان تسهيلات بحسم سندات تجاريّة لديها، فزيادة هذا المعدّل تزيد كلفة المصارف، فيرتفع معدّل الفائدة المدينة ويحجم الزبائن عن طلب القروض لأنّها أصبحت باهظة الثمن، ويرتفع معدّل الفائدة الدائنة فيزيد الزبائن ودائعهم بدل الاحتفاظ بالنقد للاستهلاك.\nب- (١ علامة) لأنّ صلاحيّات السلطة النقديّة لا تخوّلها التدخّل للتأثير مباشرةً في كميّة السلع المنتجة، فتدخّلها تمهيد لسياسة اقتصاديّة أكثر فعاليّة تتّخذها الحكومة بأجهزتها كافّة، ومن عناصرها (يكفي عنصران): زيادة الإنتاج في مختلف القطاعات وتخفيض كلفته؛ مراقبة الأسعار وتحديدها؛ اتّباع سياسة ضريبيّة تحوّل قسماً أكبر من المدّخرات المتاحة للاستهلاك التضخّميّ نحو استثمارات منتجة تزيد حجم العرض.', 1, '2026-09-30 22:54:06', '2026-09-30 22:54:06'),
(16463, 2732, 1, 'أ- (١ علامة) العلاقة طرديّة: الدخل يشكّل القوّة الشرائيّة للمستهلك التي تحدّد قدرته على الشراء، أي حجم الطلب؛ فعندما يرتفع الدخل يرتفع معه الطلب، والعكس صحيح.\nب- (١ علامة) كولن كلارك يربط تزايد نسبة الدخل المخصّصة للكماليّات بوصول الدخل إلى مستوى معيّن، أي أنّ الفرد حين يتجاوز دخله حدّاً معيّناً يوجّه جزءاً أكبر منه إلى الكماليّات؛ أمّا فريدمان فيُدخل الزمن بأوجهه الثلاثة في قرار الاستهلاك: الدخل الماضي والدخل الحاضر والدخل المتوقّع مستقبلاً.\nج- (٠٫٥ علامة) نسبة الدخل المخصّصة لشراء المواد الغذائيّة تنخفض كلّما ازداد الدخل، والمرونة أصغر من واحد. (٠٫٥ علامة) نسبة الدخل المخصّصة للكساء وأثاث المنزل (سلع يمكن الاستغناء عنها مؤقّتاً) تزداد بنسبة مماثلة لزيادة الدخل، والمرونة تساوي واحداً.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16464, 2732, 2, 'أ- (١ علامة) العلاقة طرديّة: الدخل يشكّل القوّة الشرائيّة للمستهلك التي تحدّد قدرته على الشراء، أي حجم الطلب؛ فعندما يرتفع الدخل يرتفع معه الطلب، والعكس صحيح.\nب- (١ علامة) كولن كلارك يربط تزايد نسبة الدخل المخصّصة للكماليّات بوصول الدخل إلى مستوى معيّن، أي أنّ الفرد حين يتجاوز دخله حدّاً معيّناً يوجّه جزءاً أكبر منه إلى الكماليّات؛ أمّا فريدمان فيُدخل الزمن بأوجهه الثلاثة في قرار الاستهلاك: الدخل الماضي والدخل الحاضر والدخل المتوقّع مستقبلاً.\nج- (٠٫٥ علامة) نسبة الدخل المخصّصة لشراء المواد الغذائيّة تنخفض كلّما ازداد الدخل، والمرونة أصغر من واحد. (٠٫٥ علامة) نسبة الدخل المخصّصة للكساء وأثاث المنزل (سلع يمكن الاستغناء عنها مؤقّتاً) تزداد بنسبة مماثلة لزيادة الدخل، والمرونة تساوي واحداً.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16465, 2733, 1, 'أ- (١ علامة) يضمّ ميزان الحساب الجاري: الميزان التجاريّ، وميزان الخدمات، وميزان التحويلات الخاصّة. ب- (١ علامة) الميزان التجاريّ في لبنان في حالة عجز لأنّ البلد يستورد سلعاً أكثر ممّا يصدّر، فينتج عن ذلك عجز في الحساب الجاري، أي رصيد سلبيّ يدلّ على حاجة الاقتصاد إلى التمويل. ج- (١ علامة) يسعى الاقتصاد إلى جلب رساميل (موارد ماليّة) من الخارج عبر ميزان العمليّات الرأسماليّة، فيحقّق هذا الميزان فائضاً (رصيداً إيجابيّاً) يسدّ عجز ميزان الحساب الجاري.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16466, 2733, 2, 'أ- (١ علامة) يضمّ ميزان الحساب الجاري: الميزان التجاريّ، وميزان الخدمات، وميزان التحويلات الخاصّة. ب- (١ علامة) الميزان التجاريّ في لبنان في حالة عجز لأنّ البلد يستورد سلعاً أكثر ممّا يصدّر، فينتج عن ذلك عجز في الحساب الجاري، أي رصيد سلبيّ يدلّ على حاجة الاقتصاد إلى التمويل. ج- (١ علامة) يسعى الاقتصاد إلى جلب رساميل (موارد ماليّة) من الخارج عبر ميزان العمليّات الرأسماليّة، فيحقّق هذا الميزان فائضاً (رصيداً إيجابيّاً) يسدّ عجز ميزان الحساب الجاري.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16467, 2734, 1, '(١ علامة) واقع جغرافي: السلعة لا توجد إلّا في مكان معيّن، كالأورانيوم وغيره من المعادن.\n(١ علامة) عقد قانوني: يحصر إنتاج السلعة أو الخدمة وبيعها بالمستفيد وحده، لمدّة زمنيّة محدّدة.\n(١ علامة) القدرات الماليّة لبعض المنتجين: تسمح لهم بالسيطرة على السوق.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16468, 2734, 2, '(١ علامة) واقع جغرافي: السلعة لا توجد إلّا في مكان معيّن، كالأورانيوم وغيره من المعادن.\n(١ علامة) عقد قانوني: يحصر إنتاج السلعة أو الخدمة وبيعها بالمستفيد وحده، لمدّة زمنيّة محدّدة.\n(١ علامة) القدرات الماليّة لبعض المنتجين: تسمح لهم بالسيطرة على السوق.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16469, 2735, 1, 'أ- (١ علامة) لا تستطيع الدولة أن تؤمّن كلّ حاجاتها وأن تعيش في اقتصاد مغلق يكفي نفسه، لذلك تتخصّص في إنتاج السلع التي تؤهّلها لها طبيعتها وظروفها وإمكاناتها. والميزات الفضلى هي الكفاءات والمهارات الأعلى التي تسمح لها بإنتاج هذه السلع بأقلّ كلفة ممكنة، أي السلع التي تتوافق مع قدراتها الفنّية ووفرة عوامل الإنتاج لديها. ب- (١ علامة) مدى التخصّص يتوقّف على حجم السوق، لذلك فإنّ اتّساع التجارة الدوليّة شرط لإمكانيّات التخصّص الدولي. ج- (١ علامة) تقسيم العمل يتوقّف على اتّساع السوق، وحرّية التبادل تجعل السوق أوسع، فتتخصّص كلّ دولة في السلع التي تناسب ظروفها الطبيعيّة والتاريخيّة وبتكاليف أقلّ. د- (١ علامة) سياسة التبادل الحرّ، لأنّ أنصارها ينادون بتجارة دوليّة حرّة بلا قيود ولا عقبات، وهو ما يتوافق مع رفض التقليديّين وضع أيّة قيود أو عوائق أمام التبادل الدولي.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16470, 2735, 2, 'أ- (١ علامة) لا تستطيع الدولة أن تؤمّن كلّ حاجاتها وأن تعيش في اقتصاد مغلق يكفي نفسه، لذلك تتخصّص في إنتاج السلع التي تؤهّلها لها طبيعتها وظروفها وإمكاناتها. والميزات الفضلى هي الكفاءات والمهارات الأعلى التي تسمح لها بإنتاج هذه السلع بأقلّ كلفة ممكنة، أي السلع التي تتوافق مع قدراتها الفنّية ووفرة عوامل الإنتاج لديها. ب- (١ علامة) مدى التخصّص يتوقّف على حجم السوق، لذلك فإنّ اتّساع التجارة الدوليّة شرط لإمكانيّات التخصّص الدولي. ج- (١ علامة) تقسيم العمل يتوقّف على اتّساع السوق، وحرّية التبادل تجعل السوق أوسع، فتتخصّص كلّ دولة في السلع التي تناسب ظروفها الطبيعيّة والتاريخيّة وبتكاليف أقلّ. د- (١ علامة) سياسة التبادل الحرّ، لأنّ أنصارها ينادون بتجارة دوليّة حرّة بلا قيود ولا عقبات، وهو ما يتوافق مع رفض التقليديّين وضع أيّة قيود أو عوائق أمام التبادل الدولي.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16471, 2736, 1, 'أ- (١ علامة) السعر هو ما يتمّ الاتّفاق عليه رضائيّاً بين طالب السلعة وعارضها في العمليّة التبادليّة؛ وعند نقطة الالتقاء يتحدّد السعر وتكون السوق في حالة توازن، أي أنّ الكميّات المطلوبة تتعادل عند هذا المستوى من الأسعار مع الكميّات المعروضة، ويكون العارض والطالب كلاهما راضيين.\nب- (١ علامة) ذرّيّة السوق تعني وجود أعداد كبيرة من العارضين والطالبين، فلا يستطيع أيّ واحد منهم التأثير في سعر السلع، فيبقى السعر نتيجة التقاء العرض بالطلب.\nج- (١ علامة) في الاحتكار يوجد منتج أو عارض واحد في السوق يستطيع تحديد الكمّيّة أو السعر الذي يريد في زمن معيّن، وفي أغلب الأحيان يكون السعر المفروض أعلى من سعر السوق الحرّة. (١ علامة) تكون سوق المحتكر مضمونة لأنّ الاحتكار يقوم على أساسين: وجود عارض واحد للسلعة، وعدم وجود بدائل لها في السوق.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16472, 2736, 2, 'أ- (١ علامة) السعر هو ما يتمّ الاتّفاق عليه رضائيّاً بين طالب السلعة وعارضها في العمليّة التبادليّة؛ وعند نقطة الالتقاء يتحدّد السعر وتكون السوق في حالة توازن، أي أنّ الكميّات المطلوبة تتعادل عند هذا المستوى من الأسعار مع الكميّات المعروضة، ويكون العارض والطالب كلاهما راضيين.\nب- (١ علامة) ذرّيّة السوق تعني وجود أعداد كبيرة من العارضين والطالبين، فلا يستطيع أيّ واحد منهم التأثير في سعر السلع، فيبقى السعر نتيجة التقاء العرض بالطلب.\nج- (١ علامة) في الاحتكار يوجد منتج أو عارض واحد في السوق يستطيع تحديد الكمّيّة أو السعر الذي يريد في زمن معيّن، وفي أغلب الأحيان يكون السعر المفروض أعلى من سعر السوق الحرّة. (١ علامة) تكون سوق المحتكر مضمونة لأنّ الاحتكار يقوم على أساسين: وجود عارض واحد للسلعة، وعدم وجود بدائل لها في السوق.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16475, 2738, 1, 'أ- (١ علامة) الدولة الحديثة لم تعد محايدة تجاه حياة مواطنيها، بل تراقب النشاط الاقتصادي وتوجّهه، وتعمل على رفع المستوى المعيشي والاجتماعي. ب- (١ علامة) لأنّ الدولة ترسم فيها برنامجها في المجالات الصحّيّة والثقافيّة والاقتصاديّة والاجتماعيّة لسنة مقبلة، ثمّ تعرضه على السلطة التشريعيّة لتوافق عليه، فتصبح أداة فعّالة لتنفيذ سياستها. ج- (١ علامة) ثلاثة ممّا يأتي: الزراعة، الصناعة، الحرف، السياحة، الأشغال العامّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16476, 2738, 2, 'أ- (١ علامة) الدولة الحديثة لم تعد محايدة تجاه حياة مواطنيها، بل تراقب النشاط الاقتصادي وتوجّهه، وتعمل على رفع المستوى المعيشي والاجتماعي. ب- (١ علامة) لأنّ الدولة ترسم فيها برنامجها في المجالات الصحّيّة والثقافيّة والاقتصاديّة والاجتماعيّة لسنة مقبلة، ثمّ تعرضه على السلطة التشريعيّة لتوافق عليه، فتصبح أداة فعّالة لتنفيذ سياستها. ج- (١ علامة) ثلاثة ممّا يأتي: الزراعة، الصناعة، الحرف، السياحة، الأشغال العامّة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16477, 2739, 1, '(١ علامة) تحدّد الدولة برنامج إنفاقها أوّلاً، ثمّ تقدّر الواردات اللازمة لتغطيته، فالأولويّة في الموازنة لتقدير النفقات. (١ علامة) أرقام الموازنة تقديريّة: فهي تضع سقفاً للنفقات لا يُتجاوز، أمّا الواردات فتترقّب الدولة تحصيلها دون أيّ سقف.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16478, 2739, 2, '(١ علامة) تحدّد الدولة برنامج إنفاقها أوّلاً، ثمّ تقدّر الواردات اللازمة لتغطيته، فالأولويّة في الموازنة لتقدير النفقات. (١ علامة) أرقام الموازنة تقديريّة: فهي تضع سقفاً للنفقات لا يُتجاوز، أمّا الواردات فتترقّب الدولة تحصيلها دون أيّ سقف.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16479, 2740, 1, 'أ- (١ علامة) موازنة الدولة العامّة صكّ تشريعي تُقدَّر فيه نفقات الدولة ووارداتها عن سنة مقبلة، وتُجاز بموجبه الجباية والإنفاق؛ والموازنة البلديّة وثيقة تقدّر فيها نفقات البلديّة ووارداتها عن سنة مقبلة؛ فكلتاهما تُعَدّ لسنة مقبلة. ب- (١ علامة) في موازنة الدولة تشكّل القروض الجزء الثاني من الواردات، أي الواردات الاستثنائيّة، لأنّه من المفروض ألّا تتكرّر؛ وفي الموازنة البلديّة تدخل القروض في الباب الرابع، العائدات المتنوّعة وغير العاديّة، لأنّها لا تتحقّق بانتظام. ج- (١ علامة) في موازنة الدولة يُخصَّص الجزء الثاني لنفقات التجهيز والإنشاء التي يتطلّب تنفيذها أكثر من سنة، وفيها باب لاحتياطي الموازنة؛ وفي الموازنة البلديّة الباب الثالث للمشاريع الإنشائيّة كإنارة الشوارع وإنشاء الحدائق، والباب السادس للاحتياطي.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16480, 2740, 2, 'أ- (١ علامة) موازنة الدولة العامّة صكّ تشريعي تُقدَّر فيه نفقات الدولة ووارداتها عن سنة مقبلة، وتُجاز بموجبه الجباية والإنفاق؛ والموازنة البلديّة وثيقة تقدّر فيها نفقات البلديّة ووارداتها عن سنة مقبلة؛ فكلتاهما تُعَدّ لسنة مقبلة. ب- (١ علامة) في موازنة الدولة تشكّل القروض الجزء الثاني من الواردات، أي الواردات الاستثنائيّة، لأنّه من المفروض ألّا تتكرّر؛ وفي الموازنة البلديّة تدخل القروض في الباب الرابع، العائدات المتنوّعة وغير العاديّة، لأنّها لا تتحقّق بانتظام. ج- (١ علامة) في موازنة الدولة يُخصَّص الجزء الثاني لنفقات التجهيز والإنشاء التي يتطلّب تنفيذها أكثر من سنة، وفيها باب لاحتياطي الموازنة؛ وفي الموازنة البلديّة الباب الثالث للمشاريع الإنشائيّة كإنارة الشوارع وإنشاء الحدائق، والباب السادس للاحتياطي.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16481, 2741, 1, '(١ علامة) اعتماد إنارة الشوارع من باب المشاريع الإنشائيّة، وبما أنّه عُقد أصولاً ولم يُصرف، يمكن تدويره، أي نقله إلى السنة التالية، بقرار من المجلس البلديّ قبل أوّل آذار. (١ علامة) اعتماد الاحتفال من باب النفقات المتنوّعة، وبما أنّه لم يُعقد خلال السنة الماليّة، يسقط ويبطل حقّ استعماله في السنة اللاحقة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16482, 2741, 2, '(١ علامة) اعتماد إنارة الشوارع من باب المشاريع الإنشائيّة، وبما أنّه عُقد أصولاً ولم يُصرف، يمكن تدويره، أي نقله إلى السنة التالية، بقرار من المجلس البلديّ قبل أوّل آذار. (١ علامة) اعتماد الاحتفال من باب النفقات المتنوّعة، وبما أنّه لم يُعقد خلال السنة الماليّة، يسقط ويبطل حقّ استعماله في السنة اللاحقة.', 1, '2026-09-30 22:54:07', '2026-09-30 22:54:07'),
(16483, 2742, 1, 'أ- (١ علامة) تدخل في الأموال الدائمة سندات الدين والقروض المتوسّطة والطويلة الأجل، لأنّها تتمتّع بطابع الديمومة، فتوظّفها المنشأة في الميادين نفسها التي توظّف فيها الأموال الخاصّة؛ ومن هنا العلاقة: الأموال الدائمة = الأموال الخاصّة + الديون الطويلة الأجل. ب- (١ علامة) تسمّى الموجودات الثابتة ثابتة لأنّها تبقى مدّة طويلة في ملكيّة المنشأة (كالأرض والمباني والآلات)، ولا تتبدّل عادة مع تغيّر حجم الإنتاج؛ وهي ميادين تتطلّب رأسمالاً كبيراً، فيناسب تمويلها بأموال لا أجل محدّداً لتسديدها أو أجلها طويل، أي بالأموال الدائمة التي تبقى بتصرّف المنشأة، ولذلك توضع بموازاتها في الميزانيّة.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16484, 2742, 2, 'أ- (١ علامة) تدخل في الأموال الدائمة سندات الدين والقروض المتوسّطة والطويلة الأجل، لأنّها تتمتّع بطابع الديمومة، فتوظّفها المنشأة في الميادين نفسها التي توظّف فيها الأموال الخاصّة؛ ومن هنا العلاقة: الأموال الدائمة = الأموال الخاصّة + الديون الطويلة الأجل. ب- (١ علامة) تسمّى الموجودات الثابتة ثابتة لأنّها تبقى مدّة طويلة في ملكيّة المنشأة (كالأرض والمباني والآلات)، ولا تتبدّل عادة مع تغيّر حجم الإنتاج؛ وهي ميادين تتطلّب رأسمالاً كبيراً، فيناسب تمويلها بأموال لا أجل محدّداً لتسديدها أو أجلها طويل، أي بالأموال الدائمة التي تبقى بتصرّف المنشأة، ولذلك توضع بموازاتها في الميزانيّة.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16485, 2743, 1, 'أ- (١ علامة) الموجودات الثابتة = 300 + 200 + 50 = 550 مليون ل.ل (حسيّة: الأرض والبناء والآلات والمعدّات؛ غير حسيّة: شهادة الاختراع). الموجودات الجارية = 80 (مخزون) + 40 (أموال مسلفة للغير) + 30 (سيولة) = 150 مليون ل.ل. مجموع الموجودات = 550 + 150 = 700 مليون ل.ل. ب- (١ علامة) مجموع الديون = 150 + 60 + 20 = 230 مليون ل.ل؛ الوضعيّة الصافية = مجموع قيم الموجودات − مجموع الديون = 700 − 230 = 470 مليون ل.ل. ج- (١ علامة) مجموع المطلوبات يساوي دائماً مجموع الموجودات، فهو 700 مليون ل.ل؛ والمطلوبات أموال خاصّة وديون، إذن الأموال الخاصّة = 700 − 230 = 470 مليون ل.ل.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16486, 2743, 2, 'أ- (١ علامة) الموجودات الثابتة = 300 + 200 + 50 = 550 مليون ل.ل (حسيّة: الأرض والبناء والآلات والمعدّات؛ غير حسيّة: شهادة الاختراع). الموجودات الجارية = 80 (مخزون) + 40 (أموال مسلفة للغير) + 30 (سيولة) = 150 مليون ل.ل. مجموع الموجودات = 550 + 150 = 700 مليون ل.ل. ب- (١ علامة) مجموع الديون = 150 + 60 + 20 = 230 مليون ل.ل؛ الوضعيّة الصافية = مجموع قيم الموجودات − مجموع الديون = 700 − 230 = 470 مليون ل.ل. ج- (١ علامة) مجموع المطلوبات يساوي دائماً مجموع الموجودات، فهو 700 مليون ل.ل؛ والمطلوبات أموال خاصّة وديون، إذن الأموال الخاصّة = 700 − 230 = 470 مليون ل.ل.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16487, 2744, 1, 'أ- (١ علامة) المياه العذبة تنقص إذا وزّعناها، فهي ليست بلا حدود. (١ علامة) ويطلبها الناس تلبية لحاجة فعلية، بل يزداد الطلب عليها، فيتحقّق فيها شرطا الندرة الاقتصادية ولو كانت كثيرة.\nب- (١ علامة) الندرة هي المشكلة الأساسية التي نشأ علم الاقتصاد لمعالجتها: فلولا محدودية الموارد أمام حاجات لا محدودة لما ابتكر الإنسان علم الاقتصاد، إذ يدرس هذا العلم نشاطات الإنسان لإشباع حاجاته في ظلّ موارد محدودة ونادرة.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16488, 2744, 2, 'أ- (١ علامة) المياه العذبة تنقص إذا وزّعناها، فهي ليست بلا حدود. (١ علامة) ويطلبها الناس تلبية لحاجة فعلية، بل يزداد الطلب عليها، فيتحقّق فيها شرطا الندرة الاقتصادية ولو كانت كثيرة.\nب- (١ علامة) الندرة هي المشكلة الأساسية التي نشأ علم الاقتصاد لمعالجتها: فلولا محدودية الموارد أمام حاجات لا محدودة لما ابتكر الإنسان علم الاقتصاد، إذ يدرس هذا العلم نشاطات الإنسان لإشباع حاجاته في ظلّ موارد محدودة ونادرة.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16489, 2745, 1, 'أ- (١ علامة) إيرادات الاستثمار: مبيعات السلع التي أنتجتها المنشأة 400 + مبيعات الفواضل الصناعيّة 30 = 430 مليون ل.ل. الإيرادات الماليّة: أنصبة الربح 20 + الفوائد على الودائع المصرفيّة 15 = 35 مليون ل.ل. الإيرادات الاستثنائيّة: تعويضات التأمين = 25 مليون ل.ل. ب- (١ علامة) المنشأة قادرة على الاستمرار، لأنّها تعتمد بالدرجة الأولى على إيرادات الاستثمار (430 مقابل 35 و25)، أي على نشاطها العادي؛ أمّا الإيرادات الماليّة والاستثنائيّة فغير أكيدة، ولا يمكن الاعتماد عليها دائماً لتأمين استمراريّة المنشأة.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16490, 2745, 2, 'أ- (١ علامة) إيرادات الاستثمار: مبيعات السلع التي أنتجتها المنشأة 400 + مبيعات الفواضل الصناعيّة 30 = 430 مليون ل.ل. الإيرادات الماليّة: أنصبة الربح 20 + الفوائد على الودائع المصرفيّة 15 = 35 مليون ل.ل. الإيرادات الاستثنائيّة: تعويضات التأمين = 25 مليون ل.ل. ب- (١ علامة) المنشأة قادرة على الاستمرار، لأنّها تعتمد بالدرجة الأولى على إيرادات الاستثمار (430 مقابل 35 و25)، أي على نشاطها العادي؛ أمّا الإيرادات الماليّة والاستثنائيّة فغير أكيدة، ولا يمكن الاعتماد عليها دائماً لتأمين استمراريّة المنشأة.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16491, 2746, 1, 'أ- (١ علامة) الطحين رزق وسيط، لأنّه يدخل في إنتاج سلعة أخرى هي الحلوى. (١ علامة) المكابس سلع تجهيز، لأنّها تُستعمل في المعامل لإنتاج سلع معيّنة. (١ علامة) الصابون رزق معدّ للاستهلاك النهائي، لأنّ العمّال يستهلكونه مباشرة ولا يدخل في إنتاج سلعة أخرى.\nب- (١ علامة) الصابون سلعة غير معمّرة لأنّه يزول عند أوّل استعمال له، أمّا السيارة فسلعة معمّرة (مديدة الاستهلاك) لأنّها تُستعمل أكثر من مرّة قبل إتلافها.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16492, 2746, 2, 'أ- (١ علامة) الطحين رزق وسيط، لأنّه يدخل في إنتاج سلعة أخرى هي الحلوى. (١ علامة) المكابس سلع تجهيز، لأنّها تُستعمل في المعامل لإنتاج سلع معيّنة. (١ علامة) الصابون رزق معدّ للاستهلاك النهائي، لأنّ العمّال يستهلكونه مباشرة ولا يدخل في إنتاج سلعة أخرى.\nب- (١ علامة) الصابون سلعة غير معمّرة لأنّه يزول عند أوّل استعمال له، أمّا السيارة فسلعة معمّرة (مديدة الاستهلاك) لأنّها تُستعمل أكثر من مرّة قبل إتلافها.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16493, 2747, 1, 'أ- (١ علامة) إيرادات الاستثمار = 600 (مبيعات سلع أنتجتها المنشأة). نفقات الاستثمار = شراء موادّ أوليّة 250 + أجور ومكافآت (نفقات العمل) 150 + إيجارات ونقل (أعباء خارجيّة) 40 + مخصّصات الاهتلاك 30 = 470. نتيجة الاستثمار = 600 − 470 = 130 مليون ل.ل. ب- (١ علامة) النتيجة الماليّة = الإيرادات الماليّة 20 (فوائد على الودائع) − الأعباء الماليّة 35 (فوائد على القرض المصرفي) = −15 مليون ل.ل. النتيجة الاستثنائيّة = الإيرادات الاستثنائيّة 10 (تعويضات التأمين) − الأعباء الاستثنائيّة 15 (الغرامة) = −5 مليون ل.ل. ج- (١ علامة) النتيجة = 130 + (−15) + (−5) = 110 مليون ل.ل، وهي ربح لأنّ الإيرادات (630) تفوق النفقات (520). النتيجة الصافية بعد الضريبة = النتيجة − الضريبة على الأرباح = 110 − 20 = 90 مليون ل.ل.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16494, 2747, 2, 'أ- (١ علامة) إيرادات الاستثمار = 600 (مبيعات سلع أنتجتها المنشأة). نفقات الاستثمار = شراء موادّ أوليّة 250 + أجور ومكافآت (نفقات العمل) 150 + إيجارات ونقل (أعباء خارجيّة) 40 + مخصّصات الاهتلاك 30 = 470. نتيجة الاستثمار = 600 − 470 = 130 مليون ل.ل. ب- (١ علامة) النتيجة الماليّة = الإيرادات الماليّة 20 (فوائد على الودائع) − الأعباء الماليّة 35 (فوائد على القرض المصرفي) = −15 مليون ل.ل. النتيجة الاستثنائيّة = الإيرادات الاستثنائيّة 10 (تعويضات التأمين) − الأعباء الاستثنائيّة 15 (الغرامة) = −5 مليون ل.ل. ج- (١ علامة) النتيجة = 130 + (−15) + (−5) = 110 مليون ل.ل، وهي ربح لأنّ الإيرادات (630) تفوق النفقات (520). النتيجة الصافية بعد الضريبة = النتيجة − الضريبة على الأرباح = 110 − 20 = 90 مليون ل.ل.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16495, 2748, 1, '(١ علامة) تؤكّد هذه المقارنة نسبية الحاجات والندرة، أي أنّ درجة الندرة تختلف من مجتمع إلى آخر. (١ علامة) فحاجات المجتمعات البدائية كانت قليلة ومتجانسة. (١ علامة) أمّا المجتمعات الصناعية الحديثة فحاجاتها متنوّعة وكبيرة جدّاً، لذلك تختلف درجة الإحساس بالندرة بينها.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16496, 2748, 2, '(١ علامة) تؤكّد هذه المقارنة نسبية الحاجات والندرة، أي أنّ درجة الندرة تختلف من مجتمع إلى آخر. (١ علامة) فحاجات المجتمعات البدائية كانت قليلة ومتجانسة. (١ علامة) أمّا المجتمعات الصناعية الحديثة فحاجاتها متنوّعة وكبيرة جدّاً، لذلك تختلف درجة الإحساس بالندرة بينها.', 1, '2026-09-30 22:54:08', '2026-09-30 22:54:08'),
(16497, 2749, 1, 'أ- (١ علامة) يتحدّث النصّ عن التايلورية والفوردية (العمل المتسلسل على خطّ الإنتاج). ب- (١ علامة) بدل أن يبقى العامل ثابتاً يكرّر الحركة نفسها، تقسّم التويوتية العمّال إلى فرق داخل كلّ قسم من أقسام الإنتاج وتدرّبهم على تعدّد المهام ضمن نظام المداورة، فتحفّز العمّال. (١ علامة) وبدل أن ينتقل الخطأ على خطّ الإنتاج ولا يُصحَّح إلّا بعد ساعات، تسمح المداورة بتصحيح الخطأ ووقف الخلل في أداء أيّ مهمّة فور اكتشافه، مع التركيز على النوعية.', 1, '2026-09-30 22:54:09', '2026-09-30 22:54:09'),
(16498, 2749, 2, 'أ- (١ علامة) يتحدّث النصّ عن التايلورية والفوردية (العمل المتسلسل على خطّ الإنتاج). ب- (١ علامة) بدل أن يبقى العامل ثابتاً يكرّر الحركة نفسها، تقسّم التويوتية العمّال إلى فرق داخل كلّ قسم من أقسام الإنتاج وتدرّبهم على تعدّد المهام ضمن نظام المداورة، فتحفّز العمّال. (١ علامة) وبدل أن ينتقل الخطأ على خطّ الإنتاج ولا يُصحَّح إلّا بعد ساعات، تسمح المداورة بتصحيح الخطأ ووقف الخلل في أداء أيّ مهمّة فور اكتشافه، مع التركيز على النوعية.', 1, '2026-09-30 22:54:09', '2026-09-30 22:54:09'),
(16499, 2750, 1, 'أ- (١ علامة) تقلّص الفئات العمرية الشابّة: انخفاض نسبة الفتيان دون الخامسة عشرة من مجموع المقيمين، وارتفاع نسب الفئات العمرية فوق الخامسة عشرة، فتضيق قاعدة الهرم. ب- (١ علامة) المجتمع الفتيّ في بنيته العمرية يطلق كلّ سنة أعداداً كبيرة ومتزايدة إلى سوق العمل قد لا يستطيع الاقتصاد استيعابها، خصوصاً إذا كان قليل التنوّع وأحاديّ الطابع، فيصبح عرض العمل أكبر من الطلب. (١ علامة) أمّا إذا كان المجتمع أقلّ فتوّة، كما صار المجتمع اللبناني، فإنّ خطر بروز هذا الفائض في عرض العمل يتّجه مبدئياً نحو الانحسار.', 1, '2026-09-30 22:54:09', '2026-09-30 22:54:09'),
(16500, 2750, 2, 'أ- (١ علامة) تقلّص الفئات العمرية الشابّة: انخفاض نسبة الفتيان دون الخامسة عشرة من مجموع المقيمين، وارتفاع نسب الفئات العمرية فوق الخامسة عشرة، فتضيق قاعدة الهرم. ب- (١ علامة) المجتمع الفتيّ في بنيته العمرية يطلق كلّ سنة أعداداً كبيرة ومتزايدة إلى سوق العمل قد لا يستطيع الاقتصاد استيعابها، خصوصاً إذا كان قليل التنوّع وأحاديّ الطابع، فيصبح عرض العمل أكبر من الطلب. (١ علامة) أمّا إذا كان المجتمع أقلّ فتوّة، كما صار المجتمع اللبناني، فإنّ خطر بروز هذا الفائض في عرض العمل يتّجه مبدئياً نحو الانحسار.', 1, '2026-09-30 22:54:09', '2026-09-30 22:54:09');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(16501, 2751, 1, 'أ- (١ علامة) طرفا الإنتاج هما العمّال (الأجراء) وإدارة المصنع (صاحب العمل)؛ وينتمي هؤلاء العمّال إلى فئة الأجراء من عمّال وموظّفين. ب- (١ علامة) منع الصرف الكيفي: يتعلّق بشرط الصرف من الخدمة وتعويض الصرف. (١ علامة) تطبيق الحدّ الأدنى للأجور: يتعلّق بشرط الأجر والحدّ الأدنى للأجور (ويُقبل: عدم حسم أيّام التعطيل ← الإجازات، أو أجر الساعات المرهقة ← الأجر ومدّة العمل). ج- (١ علامة) لأنّ شروط العمل موضع نقاش دائم بين طرفي الإنتاج، وهذا الحوار يجري بصورة فردية أو جماعية؛ فتعطي القوانين لكلّ من أصحاب العمل والأجراء في كلّ مهنة حقّ تأليف نقابة خاصّة به، غايتها حماية المهنة ورفع مستواها والدفاع عن مصالح المنتسبين إليها.', 1, '2026-09-30 22:54:09', '2026-09-30 22:54:09'),
(16502, 2751, 2, 'أ- (١ علامة) طرفا الإنتاج هما العمّال (الأجراء) وإدارة المصنع (صاحب العمل)؛ وينتمي هؤلاء العمّال إلى فئة الأجراء من عمّال وموظّفين. ب- (١ علامة) منع الصرف الكيفي: يتعلّق بشرط الصرف من الخدمة وتعويض الصرف. (١ علامة) تطبيق الحدّ الأدنى للأجور: يتعلّق بشرط الأجر والحدّ الأدنى للأجور (ويُقبل: عدم حسم أيّام التعطيل ← الإجازات، أو أجر الساعات المرهقة ← الأجر ومدّة العمل). ج- (١ علامة) لأنّ شروط العمل موضع نقاش دائم بين طرفي الإنتاج، وهذا الحوار يجري بصورة فردية أو جماعية؛ فتعطي القوانين لكلّ من أصحاب العمل والأجراء في كلّ مهنة حقّ تأليف نقابة خاصّة به، غايتها حماية المهنة ورفع مستواها والدفاع عن مصالح المنتسبين إليها.', 1, '2026-09-30 22:54:09', '2026-09-30 22:54:09'),
(16503, 2752, 1, '(١ علامة) أ- الديمومة: الإنتاج عمليّة متكرّرة ودائمة، فيجب أن يبقى رأس المال كاملاً وسليماً، وهذا لا يعني أنّه لا يفنى. (١ علامة) ب- يستبدل الآلة عند فنائها، أو عند عطلها الدائم، أو عند ظهور آلات أفضل. (١ علامة) ج- الآلة رأس مال ثابت، لأنّها تُستعمل مدداً طويلة ولعمليّات إنتاجيّة عديدة ومتكرّرة، ولا تُستهلك إلّا تدريجيّاً. (١ علامة) والموادّ الأوّليّة رأس مال متداول، لأنّها تتحوّل بواسطة رأس المال الثابت من سلع وسيطة إلى سلع نهائيّة، لذلك يجب إعادة تكوين مخزونها لاستمرار العمليّة الإنتاجيّة.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16504, 2752, 2, '(١ علامة) أ- الديمومة: الإنتاج عمليّة متكرّرة ودائمة، فيجب أن يبقى رأس المال كاملاً وسليماً، وهذا لا يعني أنّه لا يفنى. (١ علامة) ب- يستبدل الآلة عند فنائها، أو عند عطلها الدائم، أو عند ظهور آلات أفضل. (١ علامة) ج- الآلة رأس مال ثابت، لأنّها تُستعمل مدداً طويلة ولعمليّات إنتاجيّة عديدة ومتكرّرة، ولا تُستهلك إلّا تدريجيّاً. (١ علامة) والموادّ الأوّليّة رأس مال متداول، لأنّها تتحوّل بواسطة رأس المال الثابت من سلع وسيطة إلى سلع نهائيّة، لذلك يجب إعادة تكوين مخزونها لاستمرار العمليّة الإنتاجيّة.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16505, 2753, 1, '(١ علامة) أ- تقترض مباشرة من السوق المالي بإصدار سندات دين، أو تزيد رأس مالها بإصدار أسهم جديدة. (١ علامة) ب- سامر، لأنّ السهم يجعله شريكاً في المؤسسة يتقاضى حصّة من أرباحها تقرّرها الجمعية العمومية، وتزيد أو تنقص بحسب الربح السنوي. (١ علامة) أمّا ليلى فمُقرضة للمؤسسة وليست شريكة فيها، لذلك تتقاضى فائدة على مالها المقترض، لا حصّة من الأرباح، فلا يزيد ما تتقاضاه بارتفاع الربح.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16506, 2753, 2, '(١ علامة) أ- تقترض مباشرة من السوق المالي بإصدار سندات دين، أو تزيد رأس مالها بإصدار أسهم جديدة. (١ علامة) ب- سامر، لأنّ السهم يجعله شريكاً في المؤسسة يتقاضى حصّة من أرباحها تقرّرها الجمعية العمومية، وتزيد أو تنقص بحسب الربح السنوي. (١ علامة) أمّا ليلى فمُقرضة للمؤسسة وليست شريكة فيها، لذلك تتقاضى فائدة على مالها المقترض، لا حصّة من الأرباح، فلا يزيد ما تتقاضاه بارتفاع الربح.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16507, 2754, 1, '(١ علامة) الوظيفة التجاريّة مهمّة لأنّ ربح المنشأة واستمراريّتها مرتبطان بقدرتها على بيع إنتاجها بالكمّيّة الكافية، ويتولّاها القسم التجاريّ. (١ علامة) تتمحور الاستراتيجيّة التسويقيّة حول: تحديد السلعة (شكلها ونوعيّتها وتغليفها)، وتحديد السعر، وإطلاق السلعة (التعريف بها وبمزاياها من خلال الدعاية)، والتوزيع.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16508, 2754, 2, '(١ علامة) الوظيفة التجاريّة مهمّة لأنّ ربح المنشأة واستمراريّتها مرتبطان بقدرتها على بيع إنتاجها بالكمّيّة الكافية، ويتولّاها القسم التجاريّ. (١ علامة) تتمحور الاستراتيجيّة التسويقيّة حول: تحديد السلعة (شكلها ونوعيّتها وتغليفها)، وتحديد السعر، وإطلاق السلعة (التعريف بها وبمزاياها من خلال الدعاية)، والتوزيع.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16509, 2755, 1, '(١ علامة) أ- استعمال مدّخراته الخاصّة تمويل ذاتي مباشر، والقرض من المصرف تمويل غير مباشر بالاقتراض من الآخرين، وكلاهما من المصادر الداخلية. (١ علامة) ب- يظهر القرض في جانب المطلوبات (موارد المنشأة ومصادر أموالها)، وهو من الموارد الخارجيّة أي أموال الآخرين. (١ علامة) ج- تظهر الآلات في جانب الموجودات ضمن الأصول الثابتة، وهي رأس المال الثابت (وهي أيضاً رأس مال عينيّ).', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16510, 2755, 2, '(١ علامة) أ- استعمال مدّخراته الخاصّة تمويل ذاتي مباشر، والقرض من المصرف تمويل غير مباشر بالاقتراض من الآخرين، وكلاهما من المصادر الداخلية. (١ علامة) ب- يظهر القرض في جانب المطلوبات (موارد المنشأة ومصادر أموالها)، وهو من الموارد الخارجيّة أي أموال الآخرين. (١ علامة) ج- تظهر الآلات في جانب الموجودات ضمن الأصول الثابتة، وهي رأس المال الثابت (وهي أيضاً رأس مال عينيّ).', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16511, 2756, 1, '(١ علامة) الموجودات (وتُسمّى أيضاً توظيفات): الآلات، والأموال في المصرف، ومخزون الموادّ الأوّليّة. أمّا المطلوبات (أي الموارد): القروض، وأموال أصحاب المنشأة، ومستحقّات من يزوّدون المنشأة بالموادّ؛ فالأموال الخاصّة من المطلوبات لا من الموجودات. (١ علامة) تُبوَّب الموجودات حسب أنواعها، وتُبوَّب الموارد (المطلوبات) حسب مصادرها.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16512, 2756, 2, '(١ علامة) الموجودات (وتُسمّى أيضاً توظيفات): الآلات، والأموال في المصرف، ومخزون الموادّ الأوّليّة. أمّا المطلوبات (أي الموارد): القروض، وأموال أصحاب المنشأة، ومستحقّات من يزوّدون المنشأة بالموادّ؛ فالأموال الخاصّة من المطلوبات لا من الموجودات. (١ علامة) تُبوَّب الموجودات حسب أنواعها، وتُبوَّب الموارد (المطلوبات) حسب مصادرها.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16513, 2757, 1, '(١ علامة) أ- لأنّ شراء الأرض والبناء والآلات في المشاريع الكبيرة يحتاج رأسمالاً نقديّاً كبيراً يعجز عنه فرد أو مجموعة صغيرة، فيُقسم الرأسمال إلى أسهم متساوية القيمة تُباع للآخرين. (١ علامة) ب- السهم جزء من الرأسمال، أي جزء من ملكيّة المنشأة. ولا يُسأل المساهمون عن ديون الشركة إلّا في حدود قيمة أسهمهم، بخلاف شركاء التضامن.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16514, 2757, 2, '(١ علامة) أ- لأنّ شراء الأرض والبناء والآلات في المشاريع الكبيرة يحتاج رأسمالاً نقديّاً كبيراً يعجز عنه فرد أو مجموعة صغيرة، فيُقسم الرأسمال إلى أسهم متساوية القيمة تُباع للآخرين. (١ علامة) ب- السهم جزء من الرأسمال، أي جزء من ملكيّة المنشأة. ولا يُسأل المساهمون عن ديون الشركة إلّا في حدود قيمة أسهمهم، بخلاف شركاء التضامن.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16515, 2758, 1, '(١ علامة) أ- التكاليف الثابتة بالوحدة: الشهر الأوّل 6000000 ÷ 300 = 20000 ليرة، والشهر الثاني 6000000 ÷ 600 = 10000 ليرة. (١ علامة) ب- الشهر الأوّل: الإيرادات 300 × 40000 = 12000000 ليرة، والتكاليف 6000000 + (300 × 20000) = 12000000 ليرة، فالربح = 12000000 − 12000000 = 0 (لا ربح ولا خسارة). الشهر الثاني: الإيرادات 600 × 40000 = 24000000 ليرة، والتكاليف 6000000 + (600 × 20000) = 18000000 ليرة، فالربح = 24000000 − 18000000 = 6000000 ليرة. (١ علامة) ج- مردود سلّمي متزايد، لأنّ زيادة حجم الإنتاج أدّت إلى انخفاض التكاليف الثابتة للوحدة المنتجة (من 20000 إلى 10000 ليرة)، فيتوفّر للمنشأة هامش واسع لتكييف أسعارها مع أسعار السوق، فتكتسب القدرة التنافسية. (١ علامة) د- في الشهر الأوّل تتساوى الإيرادات مع التكاليف، فلا خسارة ولا ربح لأصحابها؛ وإذا استمرّ هذا الوضع طويلاً يفقد أصحابها الحافز على توظيف أموالهم فيها، فيكون مصيرها الإقفال، لأنّ استمراريّة المنشأة الخاصّة ترتبط ارتباطاً وثيقاً بالربح.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16516, 2758, 2, '(١ علامة) أ- التكاليف الثابتة بالوحدة: الشهر الأوّل 6000000 ÷ 300 = 20000 ليرة، والشهر الثاني 6000000 ÷ 600 = 10000 ليرة. (١ علامة) ب- الشهر الأوّل: الإيرادات 300 × 40000 = 12000000 ليرة، والتكاليف 6000000 + (300 × 20000) = 12000000 ليرة، فالربح = 12000000 − 12000000 = 0 (لا ربح ولا خسارة). الشهر الثاني: الإيرادات 600 × 40000 = 24000000 ليرة، والتكاليف 6000000 + (600 × 20000) = 18000000 ليرة، فالربح = 24000000 − 18000000 = 6000000 ليرة. (١ علامة) ج- مردود سلّمي متزايد، لأنّ زيادة حجم الإنتاج أدّت إلى انخفاض التكاليف الثابتة للوحدة المنتجة (من 20000 إلى 10000 ليرة)، فيتوفّر للمنشأة هامش واسع لتكييف أسعارها مع أسعار السوق، فتكتسب القدرة التنافسية. (١ علامة) د- في الشهر الأوّل تتساوى الإيرادات مع التكاليف، فلا خسارة ولا ربح لأصحابها؛ وإذا استمرّ هذا الوضع طويلاً يفقد أصحابها الحافز على توظيف أموالهم فيها، فيكون مصيرها الإقفال، لأنّ استمراريّة المنشأة الخاصّة ترتبط ارتباطاً وثيقاً بالربح.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16517, 2759, 1, '(١ علامة) أ- الدخل الفعلي هو الدخل منسوباً إلى مؤشّر الأسعار، أي القدرة الشرائية للدخل الاسمي. فإذا ارتفعت الأسعار ولم يتغيّر الدخل الاسمي (1,200,000 ل.ل.)، تراجع الدخل الفعلي للعامل. (١ علامة) ب- يُزاد الدخل الاسمي بالنسبة نفسها التي زادت بها الأسعار: 1,200,000 × 10% = 120,000 ل.ل.، فيصبح الدخل الاسمي الجديد 1,200,000 + 120,000 = 1,320,000 ل.ل. (١ علامة) ج- يُسمّى هذا التعديل السُّلَّم المتحرّك للأجور، وهدفه الحفاظ على القدرة الشرائية للدخل.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16518, 2759, 2, '(١ علامة) أ- الدخل الفعلي هو الدخل منسوباً إلى مؤشّر الأسعار، أي القدرة الشرائية للدخل الاسمي. فإذا ارتفعت الأسعار ولم يتغيّر الدخل الاسمي (1,200,000 ل.ل.)، تراجع الدخل الفعلي للعامل. (١ علامة) ب- يُزاد الدخل الاسمي بالنسبة نفسها التي زادت بها الأسعار: 1,200,000 × 10% = 120,000 ل.ل.، فيصبح الدخل الاسمي الجديد 1,200,000 + 120,000 = 1,320,000 ل.ل. (١ علامة) ج- يُسمّى هذا التعديل السُّلَّم المتحرّك للأجور، وهدفه الحفاظ على القدرة الشرائية للدخل.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16519, 2760, 1, '(١ علامة) أ- السبب هو الجنس، وهو من الأسباب الشخصيّة لأنّه مرتبط بشخص صاحب الدخل. (١ علامة) ب- المظهر الأوّل: تُعرض على المرأة الأعمال الأقلّ دخلاً؛ المظهر الثاني: في الوظائف النظاميّة الدائمة يكون راتبها إجمالاً أقلّ من راتب الرجل مع أنّ المهامّ متماثلة في الكفاءات. (١ علامة) ج- سبب واحد مشروح، مثلاً: الجنسيّة: العمّال الأجانب يكتفون بشروط عمل متدنّية لأنّهم يأتون من مجتمع يتدنّى فيه مستوى المعيشة، فينافسون العمّال الوطنيّين؛ أو الإنتاجيّة: من محدّدات الأجر، يرتفع بارتفاعها وينخفض بانخفاضها؛ أو العمر: الأقدميّة تلعب دوراً لا يُستهان به في تحديد الأجور (يُقبل أيضاً: المهارات والكفاءات، الشهادات، نوع العمل مع الشرح).', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16520, 2760, 2, '(١ علامة) أ- السبب هو الجنس، وهو من الأسباب الشخصيّة لأنّه مرتبط بشخص صاحب الدخل. (١ علامة) ب- المظهر الأوّل: تُعرض على المرأة الأعمال الأقلّ دخلاً؛ المظهر الثاني: في الوظائف النظاميّة الدائمة يكون راتبها إجمالاً أقلّ من راتب الرجل مع أنّ المهامّ متماثلة في الكفاءات. (١ علامة) ج- سبب واحد مشروح، مثلاً: الجنسيّة: العمّال الأجانب يكتفون بشروط عمل متدنّية لأنّهم يأتون من مجتمع يتدنّى فيه مستوى المعيشة، فينافسون العمّال الوطنيّين؛ أو الإنتاجيّة: من محدّدات الأجر، يرتفع بارتفاعها وينخفض بانخفاضها؛ أو العمر: الأقدميّة تلعب دوراً لا يُستهان به في تحديد الأجور (يُقبل أيضاً: المهارات والكفاءات، الشهادات، نوع العمل مع الشرح).', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16521, 2761, 1, '(١ علامة) أ- عندما يرتفع معدّل البطالة تشتدّ المزاحمة بين العمّال في سوق العمل، فتنخفض الأجور وفق قاعدة العرض والطلب وترتفع أرباح المستثمرين، فيتعمّق التفاوت. (١ علامة) أمّا النظام الضرائبيّ غير العادل اجتماعياً فيرفع الضرائب على الاستهلاك (الضرائب غير المباشرة) فيرهق أصحاب المداخيل المحدودة ويقلّص قدرتهم الشرائيّة، ويخفّض في المقابل الضرائب على الدخل والأرباح. (١ علامة) ب- السياسة الضريبية: اعتماد الضريبة التصاعدية التي يرتفع معدّلها مع ارتفاع المداخيل والأرباح، فتدفع هذه الأسرة ضريبة بمعدّل منخفض وتخضع المداخيل الكبيرة لمعدّلات مرتفعة، وتؤمّن الضريبة للدولة موارد مالية تموّل بها التقديمات الاجتماعية. (١ علامة) سياسة الحماية الاجتماعية: تستفيد الأسرة من تقديمات مثل تعويضات البطالة، والتعويض الشهري عن كلّ ولد (التعويضات العائلية)، أو المساهمة في الإيجار (تعويضات السكن)، أو الحضانة المجانية؛ وتشكّل هذه التقديمات أجراً اجتماعياً (أجراً غير مباشر) يحافظ على القدرة الشرائية لأصحاب الدخل المحدود ويحول دون اتساع التفاوت.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16522, 2761, 2, '(١ علامة) أ- عندما يرتفع معدّل البطالة تشتدّ المزاحمة بين العمّال في سوق العمل، فتنخفض الأجور وفق قاعدة العرض والطلب وترتفع أرباح المستثمرين، فيتعمّق التفاوت. (١ علامة) أمّا النظام الضرائبيّ غير العادل اجتماعياً فيرفع الضرائب على الاستهلاك (الضرائب غير المباشرة) فيرهق أصحاب المداخيل المحدودة ويقلّص قدرتهم الشرائيّة، ويخفّض في المقابل الضرائب على الدخل والأرباح. (١ علامة) ب- السياسة الضريبية: اعتماد الضريبة التصاعدية التي يرتفع معدّلها مع ارتفاع المداخيل والأرباح، فتدفع هذه الأسرة ضريبة بمعدّل منخفض وتخضع المداخيل الكبيرة لمعدّلات مرتفعة، وتؤمّن الضريبة للدولة موارد مالية تموّل بها التقديمات الاجتماعية. (١ علامة) سياسة الحماية الاجتماعية: تستفيد الأسرة من تقديمات مثل تعويضات البطالة، والتعويض الشهري عن كلّ ولد (التعويضات العائلية)، أو المساهمة في الإيجار (تعويضات السكن)، أو الحضانة المجانية؛ وتشكّل هذه التقديمات أجراً اجتماعياً (أجراً غير مباشر) يحافظ على القدرة الشرائية لأصحاب الدخل المحدود ويحول دون اتساع التفاوت.', 1, '2026-09-30 22:54:10', '2026-09-30 22:54:10'),
(16523, 2762, 1, 'أ- (١ علامة) الاستهلاك الذاتي: تستهلك الأسرة من إنتاجها من دون نفقات مباشرة؛ مثلاً يزرع بعض سكّان الأرياف جزءاً من حاجاتهم من الخضار والفاكهة والحبوب ثمّ يستهلكونها بدلاً من شرائها من السوق.\nب- (١ علامة) قد تنفق الأسرة من دون أن تستهلك، أي لغير أغراض الاستهلاك: فتودع المال في المصارف، أو تشتري أسهماً وسندات، أو توظّفه في مشاريع مولّدة للدخل (يكفي مثلان).\nج- (١ علامة) وجود قاعدة عريضة من الخدمات العامّة المجانية أو شبه المجانية يحرّر استهلاك الأسرة من أعباء معيشية رئيسية، ويوجّهه نحو أبواب إنفاق أخرى (كالأبواب ذات الطابع الثقافي والكمالي والترفيهي).', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16524, 2762, 2, 'أ- (١ علامة) الاستهلاك الذاتي: تستهلك الأسرة من إنتاجها من دون نفقات مباشرة؛ مثلاً يزرع بعض سكّان الأرياف جزءاً من حاجاتهم من الخضار والفاكهة والحبوب ثمّ يستهلكونها بدلاً من شرائها من السوق.\nب- (١ علامة) قد تنفق الأسرة من دون أن تستهلك، أي لغير أغراض الاستهلاك: فتودع المال في المصارف، أو تشتري أسهماً وسندات، أو توظّفه في مشاريع مولّدة للدخل (يكفي مثلان).\nج- (١ علامة) وجود قاعدة عريضة من الخدمات العامّة المجانية أو شبه المجانية يحرّر استهلاك الأسرة من أعباء معيشية رئيسية، ويوجّهه نحو أبواب إنفاق أخرى (كالأبواب ذات الطابع الثقافي والكمالي والترفيهي).', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16525, 2763, 1, '(١ علامة) الخطأ الأوّل: العيّنة غير ممثّلة؛ فالتحقيق الميداني يشمل عيّنة من الأسر الممثّلة لمجموع المقيمين في المنطقة التي يجري فيها التحقيق، لا بعض أسر حيّ واحد.\n(١ علامة) الخطأ الثاني: المدّة قصيرة؛ فالأعمال الميدانية تمتدّ في العادة على مدار عام كامل للإحاطة بأنواع النفقات الاستهلاكية كافّة، بما فيها النفقات الموسمية، فشهر تمّوز وحده لا يُظهر مثلاً نفقات التعليم في بداية العام الدراسي ولا الملابس الشتوية.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16526, 2763, 2, '(١ علامة) الخطأ الأوّل: العيّنة غير ممثّلة؛ فالتحقيق الميداني يشمل عيّنة من الأسر الممثّلة لمجموع المقيمين في المنطقة التي يجري فيها التحقيق، لا بعض أسر حيّ واحد.\n(١ علامة) الخطأ الثاني: المدّة قصيرة؛ فالأعمال الميدانية تمتدّ في العادة على مدار عام كامل للإحاطة بأنواع النفقات الاستهلاكية كافّة، بما فيها النفقات الموسمية، فشهر تمّوز وحده لا يُظهر مثلاً نفقات التعليم في بداية العام الدراسي ولا الملابس الشتوية.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16527, 2764, 1, '(١ علامة) متفاوت بين الأسر بحسب دخلها: الأسرة الفقيرة نسبياً تخصّص للغذاء حصّة كبيرة من مصروفها، وتتراجع هذه الحصّة (وكذلك حصّة السكن) كلّما ارتفع الدخل، بينما ترتفع حصّة باب الملابس والترفيه وباب النفقات الأخرى مع ارتفاع الدخل.\n(١ علامة) متغيّر عبر الزمن بحسب الظروف الاقتصادية والاجتماعية: فقد تغيّر توزّع النفقات الاستهلاكية للأسرة في لبنان إلى حدّ كبير خلال العقود الثلاثة الماضية، بسبب الحرب اللبنانية وما نجم عنها من تحوّلات، وبسبب التغيّرات العميقة في حركة السكان والدخل وأنماط المعيشة والإنفاق والتركيبة الاقتصادية والاجتماعية.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16528, 2764, 2, '(١ علامة) متفاوت بين الأسر بحسب دخلها: الأسرة الفقيرة نسبياً تخصّص للغذاء حصّة كبيرة من مصروفها، وتتراجع هذه الحصّة (وكذلك حصّة السكن) كلّما ارتفع الدخل، بينما ترتفع حصّة باب الملابس والترفيه وباب النفقات الأخرى مع ارتفاع الدخل.\n(١ علامة) متغيّر عبر الزمن بحسب الظروف الاقتصادية والاجتماعية: فقد تغيّر توزّع النفقات الاستهلاكية للأسرة في لبنان إلى حدّ كبير خلال العقود الثلاثة الماضية، بسبب الحرب اللبنانية وما نجم عنها من تحوّلات، وبسبب التغيّرات العميقة في حركة السكان والدخل وأنماط المعيشة والإنفاق والتركيبة الاقتصادية والاجتماعية.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16529, 2765, 1, 'أ- (١ علامة) المقياس الكسريّ هو نسبة التصغير التي اعتُمدت في الخريطة؛ يتضمّن بسطه وحدة القياس على الخريطة، ويتضمّن مخرجه ما يوازي هذه الوحدة على الأرض.\nب- (١ علامة) أغفل الطالب تحويل النتيجة إلى أمتار أو كيلومترات: 4 × 50000 = 200000 سم = 2000 م = 2 كلم.\nج- (١ علامة) لأنّ مقياس الخريطة الكدستراليّة كبير جداً فتشتمل على تفاصيل كثيرة، أمّا الخريطة الجداريّة فتفتقد إلى الدقّة بسبب صغر مقياسها؛ فكلّما كبر المقياس زادت التفاصيل.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16530, 2765, 2, 'أ- (١ علامة) المقياس الكسريّ هو نسبة التصغير التي اعتُمدت في الخريطة؛ يتضمّن بسطه وحدة القياس على الخريطة، ويتضمّن مخرجه ما يوازي هذه الوحدة على الأرض.\nب- (١ علامة) أغفل الطالب تحويل النتيجة إلى أمتار أو كيلومترات: 4 × 50000 = 200000 سم = 2000 م = 2 كلم.\nج- (١ علامة) لأنّ مقياس الخريطة الكدستراليّة كبير جداً فتشتمل على تفاصيل كثيرة، أمّا الخريطة الجداريّة فتفتقد إلى الدقّة بسبب صغر مقياسها؛ فكلّما كبر المقياس زادت التفاصيل.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16531, 2766, 1, 'أ- (١ علامة) الادّخار = الدخل − الاستهلاك: قبل ارتفاع الدخل 1500 − 1200 = 300 وحدة نقدية؛ وبعده 2000 − 1500 = 500 وحدة نقدية.\nب- (١ علامة) الميل الوسطي للاستهلاك = الاستهلاك ÷ الدخل = 1200 ÷ 1500 = 0,8.\nج- (١ علامة) زيادة الدخل = 500، وزيادة الاستهلاك = 300، وزيادة الادّخار = 200؛ الميل الحدّي للاستهلاك = 300 ÷ 500 = 0,6، والميل الحدّي للادّخار = 200 ÷ 500 = 0,4.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16532, 2766, 2, 'أ- (١ علامة) الادّخار = الدخل − الاستهلاك: قبل ارتفاع الدخل 1500 − 1200 = 300 وحدة نقدية؛ وبعده 2000 − 1500 = 500 وحدة نقدية.\nب- (١ علامة) الميل الوسطي للاستهلاك = الاستهلاك ÷ الدخل = 1200 ÷ 1500 = 0,8.\nج- (١ علامة) زيادة الدخل = 500، وزيادة الاستهلاك = 300، وزيادة الادّخار = 200؛ الميل الحدّي للاستهلاك = 300 ÷ 500 = 0,6، والميل الحدّي للادّخار = 200 ÷ 500 = 0,4.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16533, 2767, 1, 'أ- (١ علامة) تنتمي إلى الخرائط الكمّيّة، لأنّها تتضمّن رموزاً وتركّز على إبراز الأعداد والكثافات وتغيّراتها المجاليّة (وهي أحد أنواعها الأربعة: التوزيعات، التدفّقات، خطوط التساوي، التوزيعات النسبيّة).\nب- (١ علامة) العمر المتوقّع عند الولادة هو ما يتوقّعه المولود الجديد من عمر، وفق المستوى الاجتماعيّ والصحّيّ والمعيشيّ في بلده.\nج- (١ علامة) خرائط التوزيعات النسبيّة تقوم على معطيات إحصائيّة مصنّفة في فئات متجانسة، أمّا الخرائط النوعيّة فلا تتضمّن أيّ معطيات حول الكثافة أو العدد، وهدفها الانتشار والحدود فقط.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16534, 2767, 2, 'أ- (١ علامة) تنتمي إلى الخرائط الكمّيّة، لأنّها تتضمّن رموزاً وتركّز على إبراز الأعداد والكثافات وتغيّراتها المجاليّة (وهي أحد أنواعها الأربعة: التوزيعات، التدفّقات، خطوط التساوي، التوزيعات النسبيّة).\nب- (١ علامة) العمر المتوقّع عند الولادة هو ما يتوقّعه المولود الجديد من عمر، وفق المستوى الاجتماعيّ والصحّيّ والمعيشيّ في بلده.\nج- (١ علامة) خرائط التوزيعات النسبيّة تقوم على معطيات إحصائيّة مصنّفة في فئات متجانسة، أمّا الخرائط النوعيّة فلا تتضمّن أيّ معطيات حول الكثافة أو العدد، وهدفها الانتشار والحدود فقط.', 1, '2026-09-30 22:54:11', '2026-09-30 22:54:11'),
(16535, 2768, 1, 'أ- (١ علامة) إيراتوستينوس، العالم الإغريقيّ من مدرسة الإسكندريّة، وضع أولى الخرائط الجغرافيّة؛ وأدخل العرب، وأشهرهم الإدريسي والمسعودي، إلى الخرائط تفاصيل هامّة (ويُقبل أيضاً: بطليموس وصف خريطة العالم المعروف آنذاك، أو الفراعنة وشعوب بلاد ما بين النهرين وضعوا أولى مبادئ المساحة والهندسة المسطّحة).\nب- (١ علامة) ساعدت الرحلات البحريّة وحركة الاستعمار وتقارير القناصل والتقدّم التقنيّ على وضع أولى الخرائط العالميّة.\nج- (١ علامة) كان وضع الخرائط الطوبوغرافيّة يعتمد على الطائرة ومختبرات الكارتوغرافيا، ويجري حالياً الاعتماد على الأقمار الاصطناعيّة التي وفّرت المال والجهد والوقت.\nد- (١ علامة) يسّر عملَهم دفقُ المعلومات الإحصائيّة والصور الجوّيّة والفضائيّة، وهم يدرسون المجالين الريفيّ والمدينيّ والمناطق المهدّدة بالتدهور البيئيّ.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16536, 2768, 2, 'أ- (١ علامة) إيراتوستينوس، العالم الإغريقيّ من مدرسة الإسكندريّة، وضع أولى الخرائط الجغرافيّة؛ وأدخل العرب، وأشهرهم الإدريسي والمسعودي، إلى الخرائط تفاصيل هامّة (ويُقبل أيضاً: بطليموس وصف خريطة العالم المعروف آنذاك، أو الفراعنة وشعوب بلاد ما بين النهرين وضعوا أولى مبادئ المساحة والهندسة المسطّحة).\nب- (١ علامة) ساعدت الرحلات البحريّة وحركة الاستعمار وتقارير القناصل والتقدّم التقنيّ على وضع أولى الخرائط العالميّة.\nج- (١ علامة) كان وضع الخرائط الطوبوغرافيّة يعتمد على الطائرة ومختبرات الكارتوغرافيا، ويجري حالياً الاعتماد على الأقمار الاصطناعيّة التي وفّرت المال والجهد والوقت.\nد- (١ علامة) يسّر عملَهم دفقُ المعلومات الإحصائيّة والصور الجوّيّة والفضائيّة، وهم يدرسون المجالين الريفيّ والمدينيّ والمناطق المهدّدة بالتدهور البيئيّ.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16537, 2769, 1, '(١ علامة) العاملان: الاقتصاد والموارد (مدن صناعيّة في مناطق الفحم الحجريّ والحديد، ومدن مكيّفة بعد اكتشاف النفط)، وشبكات المواصلات (مدن عند محطّات سكك الحديد وتقاطع طرق المواصلات). (١ علامة) لأنّ شبكات المواصلات تسهّل نقل المواد الأوّليّة والسلع والأفراد بأقلّ كلفة، فتجذب المؤسّسات واليد العاملة. (١ علامة) العوامل الدائمة كالمناخ والتضاريس، أمّا العوامل الظرفيّة كثوران البراكين والهزّات والحروب والتأزّم الاقتصاديّ فتجبر الناس على ترك مناطقهم مؤقّتاً.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16538, 2769, 2, '(١ علامة) العاملان: الاقتصاد والموارد (مدن صناعيّة في مناطق الفحم الحجريّ والحديد، ومدن مكيّفة بعد اكتشاف النفط)، وشبكات المواصلات (مدن عند محطّات سكك الحديد وتقاطع طرق المواصلات). (١ علامة) لأنّ شبكات المواصلات تسهّل نقل المواد الأوّليّة والسلع والأفراد بأقلّ كلفة، فتجذب المؤسّسات واليد العاملة. (١ علامة) العوامل الدائمة كالمناخ والتضاريس، أمّا العوامل الظرفيّة كثوران البراكين والهزّات والحروب والتأزّم الاقتصاديّ فتجبر الناس على ترك مناطقهم مؤقّتاً.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16539, 2770, 1, '(١ علامة) أسباب التراجع (يكفي ذكر اثنين): التقدّم التقنيّ فرض دراسة أطول فتضاعفت مصاريف الإعالة؛ دخول المرأة ميادين العمل فتأخّر زواجها واكتفت بولد أو اثنين؛ تيسّر وسائل منع الحمل. (١ علامة) حين تحدّ الأسر من ولاداتها تتقلّص قاعدة الهرم بعد مرور سنوات، فتسود في الدول الصناعيّة الأهرامات المتّجهة نحو الشيخوخة: قاعدتها ضيّقة ووسطها منتفخ، والبالغون فيها هم الأكثرية العظمى. (١ علامة) يتّجه الاهتمام إلى نظام التقاعد ومؤسّسات الصحّة والعجزة، ويُخشى من تراجع الابتكار بسبب تراجع نسبة الشباب.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16540, 2770, 2, '(١ علامة) أسباب التراجع (يكفي ذكر اثنين): التقدّم التقنيّ فرض دراسة أطول فتضاعفت مصاريف الإعالة؛ دخول المرأة ميادين العمل فتأخّر زواجها واكتفت بولد أو اثنين؛ تيسّر وسائل منع الحمل. (١ علامة) حين تحدّ الأسر من ولاداتها تتقلّص قاعدة الهرم بعد مرور سنوات، فتسود في الدول الصناعيّة الأهرامات المتّجهة نحو الشيخوخة: قاعدتها ضيّقة ووسطها منتفخ، والبالغون فيها هم الأكثرية العظمى. (١ علامة) يتّجه الاهتمام إلى نظام التقاعد ومؤسّسات الصحّة والعجزة، ويُخشى من تراجع الابتكار بسبب تراجع نسبة الشباب.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16541, 2771, 1, '(½ علامة) أ- النزوح: انتقال من الريف للسكن في المدينة داخل البلد الواحد. (½ علامة) ب- الحركة الدورية: انتقال مؤقّت للعمل ثمّ العودة بعد انتهاء المهمّة. (½ علامة) ج- هجرة الأدمغة: هجرة الباحثين وأساتذة الجامعات وأصحاب الاختصاصات العالية. (½ علامة) د- الهجرة المؤقّتة: كهجرات العمل إلى دول الخليج.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16542, 2771, 2, '(½ علامة) أ- النزوح: انتقال من الريف للسكن في المدينة داخل البلد الواحد. (½ علامة) ب- الحركة الدورية: انتقال مؤقّت للعمل ثمّ العودة بعد انتهاء المهمّة. (½ علامة) ج- هجرة الأدمغة: هجرة الباحثين وأساتذة الجامعات وأصحاب الاختصاصات العالية. (½ علامة) د- الهجرة المؤقّتة: كهجرات العمل إلى دول الخليج.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16543, 2772, 1, '(١ علامة) أسباب التقارب: فتوّة هرم الأعمار، ونشر الخدمات الطبّيّة والوقاية، والسيطرة الجزئيّة على المجاعات والأوبئة (يكفي ذكر اثنين). (١ علامة) بقي التفاوت واضحاً في وفيات الأطفال والعمر المتوقّع عند الولادة: فالدول الغنيّة، خاصّة النفطيّة، تسجّل أعماراً مرتفعة، بينما يتدنّى العمر المتوقّع في أفريقيا السوداء بسبب الشروط الغذائيّة والصحّيّة السيّئة.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16544, 2772, 2, '(١ علامة) أسباب التقارب: فتوّة هرم الأعمار، ونشر الخدمات الطبّيّة والوقاية، والسيطرة الجزئيّة على المجاعات والأوبئة (يكفي ذكر اثنين). (١ علامة) بقي التفاوت واضحاً في وفيات الأطفال والعمر المتوقّع عند الولادة: فالدول الغنيّة، خاصّة النفطيّة، تسجّل أعماراً مرتفعة، بينما يتدنّى العمر المتوقّع في أفريقيا السوداء بسبب الشروط الغذائيّة والصحّيّة السيّئة.', 1, '2026-09-30 22:54:12', '2026-09-30 22:54:12'),
(16545, 2773, 1, 'أ- (١ علامة) تنتمي المشكلتان (تفكّك الروابط الاجتماعية وتفكّك العائلة) إلى الواقع الاجتماعي في مدن الدول النامية. ب- (١ علامة) في الريف حفظ التعاون الاقتصادي وإشراف الأب ترابط العائلة، أمّا في المدينة فأضعفه الاستقلال الاقتصادي لأفرادها. ج- (١ علامة) مشكلتان من: التسوّل وتشرّد الأحداث وتشكيل عصابات تخرق القانون؛ أزمة المواصلات لغياب التخطيط؛ الفروقات الاجتماعية إذ تتجاور الأحياء الغنية والفقيرة.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16546, 2773, 2, 'أ- (١ علامة) تنتمي المشكلتان (تفكّك الروابط الاجتماعية وتفكّك العائلة) إلى الواقع الاجتماعي في مدن الدول النامية. ب- (١ علامة) في الريف حفظ التعاون الاقتصادي وإشراف الأب ترابط العائلة، أمّا في المدينة فأضعفه الاستقلال الاقتصادي لأفرادها. ج- (١ علامة) مشكلتان من: التسوّل وتشرّد الأحداث وتشكيل عصابات تخرق القانون؛ أزمة المواصلات لغياب التخطيط؛ الفروقات الاجتماعية إذ تتجاور الأحياء الغنية والفقيرة.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16547, 2774, 1, '(١ علامة) التحدّي الأوّل هو التوسّع الأفقي، أي زيادة مساحة الأراضي الزراعية. (١ علامة) التحدّي الثاني هو التوسّع الرأسي، أي زيادة الإنتاجية باستعمال مكثّف للأسمدة والريّ والأدوية الزراعية. (١ علامة) في المدينة أدّى النزوح الواسع من الريف، مع ارتفاع نسبة المواليد، إلى تزايد سكاني نتج عنه نقص كبير في الأبنية، فاضطرّ كثير من السكان إلى العيش في ظروف مأساوية، في أحياء عشوائية النموّ ومساكن مزرية.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16548, 2774, 2, '(١ علامة) التحدّي الأوّل هو التوسّع الأفقي، أي زيادة مساحة الأراضي الزراعية. (١ علامة) التحدّي الثاني هو التوسّع الرأسي، أي زيادة الإنتاجية باستعمال مكثّف للأسمدة والريّ والأدوية الزراعية. (١ علامة) في المدينة أدّى النزوح الواسع من الريف، مع ارتفاع نسبة المواليد، إلى تزايد سكاني نتج عنه نقص كبير في الأبنية، فاضطرّ كثير من السكان إلى العيش في ظروف مأساوية، في أحياء عشوائية النموّ ومساكن مزرية.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16549, 2775, 1, '(١ علامة) سبب المدّ والجزر: جاذبية كلّ من القمر والشمس على الأرض. (١ علامة) جاذبية القمر على الأرض تساوي أكثر من ضعفي جاذبية الشمس عليها بسبب قربه منها. (١ علامة) المدّ الأعلى يحدث عندما تجتمع جاذبيتا القمر والشمس على الأرض، لأنّهما يقعان على مستقيم واحد معها، كما في المحاق والبدر. (١ علامة) المدّ الأدنى يحدث في موقعي التربيع الأول والتربيع الأخير، حيث تتعارض جاذبيتا القمر والشمس في تأثيرهما على الأرض.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16550, 2775, 2, '(١ علامة) سبب المدّ والجزر: جاذبية كلّ من القمر والشمس على الأرض. (١ علامة) جاذبية القمر على الأرض تساوي أكثر من ضعفي جاذبية الشمس عليها بسبب قربه منها. (١ علامة) المدّ الأعلى يحدث عندما تجتمع جاذبيتا القمر والشمس على الأرض، لأنّهما يقعان على مستقيم واحد معها، كما في المحاق والبدر. (١ علامة) المدّ الأدنى يحدث في موقعي التربيع الأول والتربيع الأخير، حيث تتعارض جاذبيتا القمر والشمس في تأثيرهما على الأرض.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16551, 2776, 1, '(١ علامة) الاتّجاه: الدورتان من الغرب إلى الشرق. (١ علامة) المدّة: تكمل الأرض دورتها حول نفسها كلّ أربعٍ وعشرين ساعة، وتجتاز مدارها حول الشمس في نحو 365 يوماً وبضع ساعات. (١ علامة) الظاهرة: ينتج عن الدورة المحوريّة تعاقب الليل والنهار (أو أيّ نتيجة أخرى من نتائجها: الحركة الظاهريّة للشمس، اختلاف التوقيت…)، وينتج عن الدورة الإهليليجيّة مع ميل محور الأرض تعاقب الفصول الأربعة (أو توزّع الأقاليم الحراريّة، أو اختلاف طول النهار والليل).', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16552, 2776, 2, '(١ علامة) الاتّجاه: الدورتان من الغرب إلى الشرق. (١ علامة) المدّة: تكمل الأرض دورتها حول نفسها كلّ أربعٍ وعشرين ساعة، وتجتاز مدارها حول الشمس في نحو 365 يوماً وبضع ساعات. (١ علامة) الظاهرة: ينتج عن الدورة المحوريّة تعاقب الليل والنهار (أو أيّ نتيجة أخرى من نتائجها: الحركة الظاهريّة للشمس، اختلاف التوقيت…)، وينتج عن الدورة الإهليليجيّة مع ميل محور الأرض تعاقب الفصول الأربعة (أو توزّع الأقاليم الحراريّة، أو اختلاف طول النهار والليل).', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16553, 2777, 1, '(١ علامة) يضع المعيار الاقتصادي الزراعة وتربية الماشية ضمن مفهوم القرية، بينما يعمل معظم سكّان المدينة في الصناعة والتجارة والخدمات. (١ علامة) لكنّ ضواحي مدن كثيرة في العالم النامي لها أنماط معيشة وإنتاج أقرب إلى الريف، فضلاً عن العادات والتقاليد السائدة، فلا يكفي هذا المعيار وحده.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16554, 2777, 2, '(١ علامة) يضع المعيار الاقتصادي الزراعة وتربية الماشية ضمن مفهوم القرية، بينما يعمل معظم سكّان المدينة في الصناعة والتجارة والخدمات. (١ علامة) لكنّ ضواحي مدن كثيرة في العالم النامي لها أنماط معيشة وإنتاج أقرب إلى الريف، فضلاً عن العادات والتقاليد السائدة، فلا يكفي هذا المعيار وحده.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16555, 2778, 1, '(١ علامة) لأنّ سهولة المواصلات حرّرت المدينة والريف من ارتباطهما القديم والوثيق. (١ علامة) فلم تعد المدينة الركيزة الأساسية التي يعتمد عليها الريف، بل صارت حلقة في الحياة الاقتصادية والاجتماعية.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16556, 2778, 2, '(١ علامة) لأنّ سهولة المواصلات حرّرت المدينة والريف من ارتباطهما القديم والوثيق. (١ علامة) فلم تعد المدينة الركيزة الأساسية التي يعتمد عليها الريف، بل صارت حلقة في الحياة الاقتصادية والاجتماعية.', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16557, 2779, 1, '(١ علامة) الكون هو الفضاء الشاسع الذي تشغل ملايين المجرّات والسُّدُم جزءاً منه، وتفصل بينها مساحات هائلة. (١ علامة) المجموعة الشمسيّة (الشمس والكواكب السيّارة التي تدور حولها وتوابعها والمذنّبات) جزء صغير من مجرّة درب التبّانة، وهي على شكل قرص. (١ علامة) أقرب المجرّات إلى مجرّتنا مجرّة أندروميد (المرأة المسلسلة).', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16558, 2779, 2, '(١ علامة) الكون هو الفضاء الشاسع الذي تشغل ملايين المجرّات والسُّدُم جزءاً منه، وتفصل بينها مساحات هائلة. (١ علامة) المجموعة الشمسيّة (الشمس والكواكب السيّارة التي تدور حولها وتوابعها والمذنّبات) جزء صغير من مجرّة درب التبّانة، وهي على شكل قرص. (١ علامة) أقرب المجرّات إلى مجرّتنا مجرّة أندروميد (المرأة المسلسلة).', 1, '2026-09-30 22:54:13', '2026-09-30 22:54:13'),
(16559, 2780, 1, 'أ- (١ علامة) يصنعها الإنسان للرذاذات والمذيبات والتبريد (يكفي ذكر استعمالين). ب- (١ علامة) لأنّها تبقى نحو مئة سنة في الجوّ، وكلّ ذرّة كلور منها تفكّك مئة ألف ذرّة أوزون، فتحوّله إلى أوكسجين عاديّ لا يمتصّ الأشعة ما فوق البنفسجيّة. ج- (١ علامة) لأنّ طبقة الأوزون تمتصّ الأشعة ما فوق البنفسجيّة التي ترسلها الشمس فلا يصل إلى سطح الأرض إلّا جزء قليل منها، ولو وصلت كاملة لانعدمت الحياة، لأنّ كمّيّاتها الكبيرة تقتل الخلايا الحيّة الحيوانيّة والنباتيّة.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16560, 2780, 2, 'أ- (١ علامة) يصنعها الإنسان للرذاذات والمذيبات والتبريد (يكفي ذكر استعمالين). ب- (١ علامة) لأنّها تبقى نحو مئة سنة في الجوّ، وكلّ ذرّة كلور منها تفكّك مئة ألف ذرّة أوزون، فتحوّله إلى أوكسجين عاديّ لا يمتصّ الأشعة ما فوق البنفسجيّة. ج- (١ علامة) لأنّ طبقة الأوزون تمتصّ الأشعة ما فوق البنفسجيّة التي ترسلها الشمس فلا يصل إلى سطح الأرض إلّا جزء قليل منها، ولو وصلت كاملة لانعدمت الحياة، لأنّ كمّيّاتها الكبيرة تقتل الخلايا الحيّة الحيوانيّة والنباتيّة.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16561, 2781, 1, '(١ علامة) البياض هو ما تعكسه الأجسام من الأشعة، وتختلف نسبته باختلاف لون الأجسام ونعومتها، لذلك تكون مرتفعة جدّاً في الجليديات ومنخفضة في الغابات. (١ علامة) أمّا باقي الأشعة فيختزنه سطح الأرض ويدفأ به، ثمّ يبثّه ليلاً مع غياب الشمس.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16562, 2781, 2, '(١ علامة) البياض هو ما تعكسه الأجسام من الأشعة، وتختلف نسبته باختلاف لون الأجسام ونعومتها، لذلك تكون مرتفعة جدّاً في الجليديات ومنخفضة في الغابات. (١ علامة) أمّا باقي الأشعة فيختزنه سطح الأرض ويدفأ به، ثمّ يبثّه ليلاً مع غياب الشمس.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16563, 2782, 1, '(١ علامة) يؤدّي صعود الهواء في المنخفض الجوّيّ إلى حدوث فراغات يعوّضها الهواء المتراكم في المرتفع الجوّيّ، فتنشأ عن فروقات الضغط حركة أفقيّة للهواء من المرتفع نحو المنخفض تسمّى الرياح. (١ علامة) لا يتّجه الهواء مستقيماً بل ينحرف نحو يسار مساره لأنّ المنطقة في نصف الكرة الجنوبيّ، وذلك بسبب قوّة كوريوليس.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16564, 2782, 2, '(١ علامة) يؤدّي صعود الهواء في المنخفض الجوّيّ إلى حدوث فراغات يعوّضها الهواء المتراكم في المرتفع الجوّيّ، فتنشأ عن فروقات الضغط حركة أفقيّة للهواء من المرتفع نحو المنخفض تسمّى الرياح. (١ علامة) لا يتّجه الهواء مستقيماً بل ينحرف نحو يسار مساره لأنّ المنطقة في نصف الكرة الجنوبيّ، وذلك بسبب قوّة كوريوليس.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16565, 2783, 1, 'أ- (١ علامة) الرياح الغربيّة حارّة نسبيّاً ورطبة، أمّا الرياح القطبيّة فشديدة البرودة لأنّ الهواء يبرد باحتكاكه بصفحات الجليد في المناطق القطبيّة. ب- (١ علامة) تصطدم الرياح القطبيّة بالرياح الغربيّة فيرتفع الهواء وتنشأ المنخفضات فوق المناطق المعتدلة. ج- (١ علامة) هذا تبرّد بالتصادم: تندسّ الرياح الباردة تحت الحارّة الرطبة وتدفعها إلى الأعالي، فتبرد وتتكاثف وتهطل أمطاراً غزيرة عند الجبهة القطبيّة (السطح الفاصل بين الكتلتين)، وهذا ما يحدث في لبنان خلال فصل الشتاء.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16566, 2783, 2, 'أ- (١ علامة) الرياح الغربيّة حارّة نسبيّاً ورطبة، أمّا الرياح القطبيّة فشديدة البرودة لأنّ الهواء يبرد باحتكاكه بصفحات الجليد في المناطق القطبيّة. ب- (١ علامة) تصطدم الرياح القطبيّة بالرياح الغربيّة فيرتفع الهواء وتنشأ المنخفضات فوق المناطق المعتدلة. ج- (١ علامة) هذا تبرّد بالتصادم: تندسّ الرياح الباردة تحت الحارّة الرطبة وتدفعها إلى الأعالي، فتبرد وتتكاثف وتهطل أمطاراً غزيرة عند الجبهة القطبيّة (السطح الفاصل بين الكتلتين)، وهذا ما يحدث في لبنان خلال فصل الشتاء.', 1, '2026-09-30 22:54:14', '2026-09-30 22:54:14'),
(16567, 2784, 1, 'أ- (١ علامة) يسود في المناطق الواقعة خلف السلاسل الجبليّة التي تمنع وصول المؤثّرات البحريّة إليها، كما في كندا والولايات المتّحدة الأميركيّة، وفي داخل القارات البعيد عن البحار، كما في داخل أوروبا وآسيا. ب- (١ علامة) لأنّ تأثير المحيطات لا يصل إليه، تتّسع فيه الفروقات الحراريّة اليوميّة والسنويّة. ج- (١ علامة) الإقليم المعتدل المحيطي يسود في الواجهات الغربيّة من القارات التي تتلقّى تأثيرات التيّارات البحريّة، وتتوزّع أمطاره على جميع أشهر السنة؛ أمّا الإقليم المعتدل القاري فبعيد عن المؤثّرات البحريّة، وتسقط أمطاره خلال فصلَي الربيع والصيف.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16568, 2784, 2, 'أ- (١ علامة) يسود في المناطق الواقعة خلف السلاسل الجبليّة التي تمنع وصول المؤثّرات البحريّة إليها، كما في كندا والولايات المتّحدة الأميركيّة، وفي داخل القارات البعيد عن البحار، كما في داخل أوروبا وآسيا. ب- (١ علامة) لأنّ تأثير المحيطات لا يصل إليه، تتّسع فيه الفروقات الحراريّة اليوميّة والسنويّة. ج- (١ علامة) الإقليم المعتدل المحيطي يسود في الواجهات الغربيّة من القارات التي تتلقّى تأثيرات التيّارات البحريّة، وتتوزّع أمطاره على جميع أشهر السنة؛ أمّا الإقليم المعتدل القاري فبعيد عن المؤثّرات البحريّة، وتسقط أمطاره خلال فصلَي الربيع والصيف.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16569, 2785, 1, 'أ- (١ علامة) الإيجابيّتان: زاد المحاصيل كثيراً، وحقّق بعض الأمن الغذائي في العالم؛ والسلبية: تملّح بعض الترب في الأراضي الجافة (كلفة بيئية عالية). ب- (١ علامة) دراسة طرق الري لتتناسب مع طبيعة التربة والمناخ السائد. ج- (١ علامة) كارثة بحر آرال: حُوّلت مياه نهرَي سيرداريا وأموداريا لريّ مزارع القطن، فجفّ جزء من البحر وزادت ملوحته حتّى صار كالبحر الميت. (أو: نضوب الآبار الجوفية في السعودية لأنّ استهلاك مخزونها لا يعوَّض لندرة سقوط الأمطار.)', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16570, 2785, 2, 'أ- (١ علامة) الإيجابيّتان: زاد المحاصيل كثيراً، وحقّق بعض الأمن الغذائي في العالم؛ والسلبية: تملّح بعض الترب في الأراضي الجافة (كلفة بيئية عالية). ب- (١ علامة) دراسة طرق الري لتتناسب مع طبيعة التربة والمناخ السائد. ج- (١ علامة) كارثة بحر آرال: حُوّلت مياه نهرَي سيرداريا وأموداريا لريّ مزارع القطن، فجفّ جزء من البحر وزادت ملوحته حتّى صار كالبحر الميت. (أو: نضوب الآبار الجوفية في السعودية لأنّ استهلاك مخزونها لا يعوَّض لندرة سقوط الأمطار.)', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16571, 2786, 1, '(١ علامة) الإقليم الصحراويّ: تسيطر فوقه المرتفعات الجوّيّة الديناميكيّة طوال أشهر السنة، وهي تيّار هوائيّ هابط، حارّ وجافّ، فتتجاوز كمّيّة التبخّر كمّيّة المتساقطات في جميع أشهر السنة. (١ علامة) الإقليم الاستوائيّ: أشعّة الشمس تبقى شبه عموديّة طوال السنة والهواء مشبع دائماً ببخار الماء، فبعد الظهر يتشبّع الهواء أكثر فتتشكّل الغيوم وتهطل الأمطار الغزيرة. (١ علامة) الأثر في النبات: يغطّي الإقليمَ الاستوائيّ غاباتٌ كثيفة دائمة النموّ ومتعدّدة الأنواع، تتدرّج فيها ثلاثة مستويات (الأشجار العالية، الشجيرات، الأعشاب والنبات المتسلّق)؛ أمّا في الإقليم الصحراويّ فالنبات متكيّف مع الجفاف: تشكيلات شوكيّة ذات جذور رأسيّة عميقة، ونباتات قادرة على اختزان المياه كالصبّار، ونباتات أوراقها مكسوّة بغطاء دهنيّ يمنع التبخّر كالجوجوبا والنخيل والأكاسيا.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16572, 2786, 2, '(١ علامة) الإقليم الصحراويّ: تسيطر فوقه المرتفعات الجوّيّة الديناميكيّة طوال أشهر السنة، وهي تيّار هوائيّ هابط، حارّ وجافّ، فتتجاوز كمّيّة التبخّر كمّيّة المتساقطات في جميع أشهر السنة. (١ علامة) الإقليم الاستوائيّ: أشعّة الشمس تبقى شبه عموديّة طوال السنة والهواء مشبع دائماً ببخار الماء، فبعد الظهر يتشبّع الهواء أكثر فتتشكّل الغيوم وتهطل الأمطار الغزيرة. (١ علامة) الأثر في النبات: يغطّي الإقليمَ الاستوائيّ غاباتٌ كثيفة دائمة النموّ ومتعدّدة الأنواع، تتدرّج فيها ثلاثة مستويات (الأشجار العالية، الشجيرات، الأعشاب والنبات المتسلّق)؛ أمّا في الإقليم الصحراويّ فالنبات متكيّف مع الجفاف: تشكيلات شوكيّة ذات جذور رأسيّة عميقة، ونباتات قادرة على اختزان المياه كالصبّار، ونباتات أوراقها مكسوّة بغطاء دهنيّ يمنع التبخّر كالجوجوبا والنخيل والأكاسيا.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16573, 2787, 1, '(١ علامة) كلّما قلّت الأمطار وطال فصل الجفاف تغيّرت كثافة الغطاء النباتيّ: على تخوم الإقليم الاستوائيّ تنتشر السافانا، وهي أعشاب عالية تتخلّلها أشجار متباعدة. (١ علامة) وعلى أطراف الإقليم المداريّ عند تخوم الصحراء يسود الإستبس، وهو نباتات شوكيّة وعشبيّة.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16574, 2788, 1, '(١ علامة) تتغذّى الأسماك من العلقيّات النباتيّة، وهذه تحتاج إلى حرارة مناسبة وضوء كافٍ للتمثيل الكلوروفيليّ وتجديد دائم للأوكسيجين وأملاح. (١ علامة) الأرصفة القارّيّة منطقة محاذية للشواطئ قليلة العمق إجمالاً، فيصلها الضوء. (١ علامة) في مناطق التقاء التيارات ترفع التيارات الرأسيّة الأملاح من الأعماق إلى السطح وتجدّد الأوكسيجين.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16575, 2787, 2, '(١ علامة) كلّما قلّت الأمطار وطال فصل الجفاف تغيّرت كثافة الغطاء النباتيّ: على تخوم الإقليم الاستوائيّ تنتشر السافانا، وهي أعشاب عالية تتخلّلها أشجار متباعدة. (١ علامة) وعلى أطراف الإقليم المداريّ عند تخوم الصحراء يسود الإستبس، وهو نباتات شوكيّة وعشبيّة.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16576, 2788, 2, '(١ علامة) تتغذّى الأسماك من العلقيّات النباتيّة، وهذه تحتاج إلى حرارة مناسبة وضوء كافٍ للتمثيل الكلوروفيليّ وتجديد دائم للأوكسيجين وأملاح. (١ علامة) الأرصفة القارّيّة منطقة محاذية للشواطئ قليلة العمق إجمالاً، فيصلها الضوء. (١ علامة) في مناطق التقاء التيارات ترفع التيارات الرأسيّة الأملاح من الأعماق إلى السطح وتجدّد الأوكسيجين.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16577, 2789, 1, 'أ- (١ علامة) المياه: الآبار الجوفية في السعودية مهدّدة بالنضوب لأنّ استهلاك مخزونها لا يعوَّض لندرة سقوط الأمطار (أو كارثة بحر آرال). (١ علامة) البحر: فاقت كمّيات الصيد في بعض الأماكن ما يتجدّد سنوياً، ولجأت بعض المنشآت إلى تصغير قياس الشباك فصار التجدّد صعباً (أو التلوّث بالأسمدة والنفايات الصناعية ومياه الصرف الصحّي والنفط الذي أهلك كمّيات كبيرة من الكائنات البحرية). ب- (١ علامة) المياه: اعتماد سياسة الأمن المائي وشروط استثمار المياه، مثل مسح الخزانات الجوفية أو تحسين قنوات المياه للحدّ من التبخّر والتسرّب أو إعادة استعمال المياه المعالَجة في الري. (١ علامة) البحر: تنظيم المنظّمات الإقليمية والدولية لعمليّات الصيد والحدّ من التلوّث، وعقد مؤتمرات دولية للحدّ من الإفراط في الصيد (أو تربية الأسماك في مزارع المائيات).', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16578, 2789, 2, 'أ- (١ علامة) المياه: الآبار الجوفية في السعودية مهدّدة بالنضوب لأنّ استهلاك مخزونها لا يعوَّض لندرة سقوط الأمطار (أو كارثة بحر آرال). (١ علامة) البحر: فاقت كمّيات الصيد في بعض الأماكن ما يتجدّد سنوياً، ولجأت بعض المنشآت إلى تصغير قياس الشباك فصار التجدّد صعباً (أو التلوّث بالأسمدة والنفايات الصناعية ومياه الصرف الصحّي والنفط الذي أهلك كمّيات كبيرة من الكائنات البحرية). ب- (١ علامة) المياه: اعتماد سياسة الأمن المائي وشروط استثمار المياه، مثل مسح الخزانات الجوفية أو تحسين قنوات المياه للحدّ من التبخّر والتسرّب أو إعادة استعمال المياه المعالَجة في الري. (١ علامة) البحر: تنظيم المنظّمات الإقليمية والدولية لعمليّات الصيد والحدّ من التلوّث، وعقد مؤتمرات دولية للحدّ من الإفراط في الصيد (أو تربية الأسماك في مزارع المائيات).', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16579, 2790, 1, '(١ علامة) في الشتاء يقع الإقليم تحت تأثير الجبهة القطبيّة التي تنشأ من التقاء الرياح الغربيّة الحارّة والرطبة بالرياح القطبيّة الباردة، فتسقط الأمطار بغزارة على شكل موجات تستمرّ بضعة أيّام وتتدنّى كمّيّتها من الشمال نحو الجنوب، والحرارة معتدلة على الشواطئ ومتدنّية على المرتفعات. (١ علامة) في الصيف يقع الإقليم تحت تأثير المرتفعات الجوّيّة المداريّة، فيسود الجفاف وترتفع الحرارة، وتتزايد نحو الجنوب حيث تخوم الصحراء.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16580, 2790, 2, '(١ علامة) في الشتاء يقع الإقليم تحت تأثير الجبهة القطبيّة التي تنشأ من التقاء الرياح الغربيّة الحارّة والرطبة بالرياح القطبيّة الباردة، فتسقط الأمطار بغزارة على شكل موجات تستمرّ بضعة أيّام وتتدنّى كمّيّتها من الشمال نحو الجنوب، والحرارة معتدلة على الشواطئ ومتدنّية على المرتفعات. (١ علامة) في الصيف يقع الإقليم تحت تأثير المرتفعات الجوّيّة المداريّة، فيسود الجفاف وترتفع الحرارة، وتتزايد نحو الجنوب حيث تخوم الصحراء.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16581, 2791, 1, 'أ- (١ علامة) السيال طبقة غرانيتية من مادّتي السيليسيوم والألومينيوم تتركّب منها قشرة الأرض الخارجية، أمّا السيما فطبقة بازلتية أثقل وأكثر كثافة ترتكز عليها هذه القشرة.\nب- (١ علامة) كلّما ازداد ارتفاع الكتلة السيالية ازداد تعمّقها في السيما، لذلك تتعمّق الجبال الالتوائية الشاهقة في السيما بجذور عميقة تحفظ توازنها.\nج- (١ علامة) تتعمّق القشرة أكثر في السيما؛ لأنّ ذوبان الجليد في المناطق السكندنافية جعلها أخفّ وزناً فأخذت تطفو تدريجياً وأصبحت أقلّ عمقاً، فإذا ازداد الحمل حدث العكس.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16582, 2791, 2, 'أ- (١ علامة) السيال طبقة غرانيتية من مادّتي السيليسيوم والألومينيوم تتركّب منها قشرة الأرض الخارجية، أمّا السيما فطبقة بازلتية أثقل وأكثر كثافة ترتكز عليها هذه القشرة.\nب- (١ علامة) كلّما ازداد ارتفاع الكتلة السيالية ازداد تعمّقها في السيما، لذلك تتعمّق الجبال الالتوائية الشاهقة في السيما بجذور عميقة تحفظ توازنها.\nج- (١ علامة) تتعمّق القشرة أكثر في السيما؛ لأنّ ذوبان الجليد في المناطق السكندنافية جعلها أخفّ وزناً فأخذت تطفو تدريجياً وأصبحت أقلّ عمقاً، فإذا ازداد الحمل حدث العكس.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16583, 2792, 1, 'أ- (١ علامة) في حركة التقارب تزحف صفيحتان باتّجاه متقابل فتنزلق الأكثف والأثقل تحت الأخرى، فتتكوّن وهاد بحرية عميقة جدّاً وترتفع الرواسب على شكل سلاسل التوائية، ويرافق ذلك حدوث زلازل مدمّرة.\nب- (١ علامة) تنتشر نقاط ضعف جيولوجية عند خطوط التباعد أو عند خطوط التقارب والالتحام بين الصفائح، فتتيح للحمم الملتهبة (الماغما التي جمعتها تيّارات الحمل في أعلى الوشاح) أن تخترق القشرة فتحدث ظاهرة البركان.\nج- (١ علامة) النطاق البحري يمرّ في أواسط المحيطات الكبرى من الشمال إلى الجنوب، ويتّفق مع امتداد الأخاديد المحيطية في الظهور التصدّعية المحيطية التي تنتج عن حركة التباعد.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16584, 2792, 2, 'أ- (١ علامة) في حركة التقارب تزحف صفيحتان باتّجاه متقابل فتنزلق الأكثف والأثقل تحت الأخرى، فتتكوّن وهاد بحرية عميقة جدّاً وترتفع الرواسب على شكل سلاسل التوائية، ويرافق ذلك حدوث زلازل مدمّرة.\nب- (١ علامة) تنتشر نقاط ضعف جيولوجية عند خطوط التباعد أو عند خطوط التقارب والالتحام بين الصفائح، فتتيح للحمم الملتهبة (الماغما التي جمعتها تيّارات الحمل في أعلى الوشاح) أن تخترق القشرة فتحدث ظاهرة البركان.\nج- (١ علامة) النطاق البحري يمرّ في أواسط المحيطات الكبرى من الشمال إلى الجنوب، ويتّفق مع امتداد الأخاديد المحيطية في الظهور التصدّعية المحيطية التي تنتج عن حركة التباعد.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16585, 2793, 1, '(١ علامة) في المنطقة الثانية ذات الصخور الرسوبية؛ لأنّ الصخور الرسوبية مسامية، فتتكوّن فيها خزّانات مياه جوفية عند ظهور طبقة عازلة.\n(١ علامة) أمّا الغرانيت فصخر ناري تكاد تنعدم مساميته، فلا يمتصّ المياه ولا يخزّن مياهاً جوفية.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16586, 2793, 2, '(١ علامة) في المنطقة الثانية ذات الصخور الرسوبية؛ لأنّ الصخور الرسوبية مسامية، فتتكوّن فيها خزّانات مياه جوفية عند ظهور طبقة عازلة.\n(١ علامة) أمّا الغرانيت فصخر ناري تكاد تنعدم مساميته، فلا يمتصّ المياه ولا يخزّن مياهاً جوفية.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16587, 2794, 1, '(١ علامة) إذا أصاب الزلزال قاع المحيط تنشأ أمواج مدمّرة تُسمّى التسونامي، تطغى بعنف على السواحل المقابلة.\n(١ علامة) توقع خسائر فادحة في المنشآت العمرانية وتُغرق آلاف الضحايا، والسبب حدوثها الفجائي.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16588, 2794, 2, '(١ علامة) إذا أصاب الزلزال قاع المحيط تنشأ أمواج مدمّرة تُسمّى التسونامي، تطغى بعنف على السواحل المقابلة.\n(١ علامة) توقع خسائر فادحة في المنشآت العمرانية وتُغرق آلاف الضحايا، والسبب حدوثها الفجائي.', 1, '2026-09-30 22:54:15', '2026-09-30 22:54:15'),
(16589, 2795, 1, 'أ- (١ علامة) يتكثّف الغطاء النباتي فيؤمّن الدبال، وتتوافر الرطوبة والحوامض التي تهاجم الصخور وتفكّكها (يُكتفى بعاملين). ب- (١ علامة) في الأفق ج تتحلّل الصخور وتتفكّك بفعل المياه المحمّلة بحوامض الدبال والكربون. ج- (١ علامة) تفكّك الحيوانات المجهرية الدبال (أوراق الأشجار وبقايا جثث الحيوانات وروثها) إلى عناصر غذائية بسيطة تمتصّها الجذور.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16590, 2795, 2, 'أ- (١ علامة) يتكثّف الغطاء النباتي فيؤمّن الدبال، وتتوافر الرطوبة والحوامض التي تهاجم الصخور وتفكّكها (يُكتفى بعاملين). ب- (١ علامة) في الأفق ج تتحلّل الصخور وتتفكّك بفعل المياه المحمّلة بحوامض الدبال والكربون. ج- (١ علامة) تفكّك الحيوانات المجهرية الدبال (أوراق الأشجار وبقايا جثث الحيوانات وروثها) إلى عناصر غذائية بسيطة تمتصّها الجذور.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16591, 2796, 1, 'أ- (١ علامة) الفكرة الرئيسة: الحضارة خاصّة بالإنسان وحده، لأنّه وحده يعلّم خبراته ويورّثها، أمّا الحيوان فيكتسب بعض المهارات والعادات لكنّه عاجز عن تعليمها لغيره أو توريثها لجيل آخر، لذلك لا نستطيع الحديث عن حضارة للحيوان. ب- (١ علامة) لأنّ القرود أذكى أنواع الحيوان، ومع ذلك ما زالت تعيش اليوم كما عاشت دائماً، فإذا لم تبلغ الحضارة فغيرها من الحيوان أولى بألّا يبلغها. ج- (١ علامة) مكوّنان من مثل: تغيير واعٍ وهادف للحيّز الطبيعي؛ تطوّر في المأكل والمشرب والمسكن والملبس؛ عادات وأعراف وقواعد وقوانين اجتماعيّة؛ تقدّم مادّي وتقني وعلمي وترقٍّ ثقافي وروحي (نصف علامة لكلّ مكوّن).', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16592, 2796, 2, 'أ- (١ علامة) الفكرة الرئيسة: الحضارة خاصّة بالإنسان وحده، لأنّه وحده يعلّم خبراته ويورّثها، أمّا الحيوان فيكتسب بعض المهارات والعادات لكنّه عاجز عن تعليمها لغيره أو توريثها لجيل آخر، لذلك لا نستطيع الحديث عن حضارة للحيوان. ب- (١ علامة) لأنّ القرود أذكى أنواع الحيوان، ومع ذلك ما زالت تعيش اليوم كما عاشت دائماً، فإذا لم تبلغ الحضارة فغيرها من الحيوان أولى بألّا يبلغها. ج- (١ علامة) مكوّنان من مثل: تغيير واعٍ وهادف للحيّز الطبيعي؛ تطوّر في المأكل والمشرب والمسكن والملبس؛ عادات وأعراف وقواعد وقوانين اجتماعيّة؛ تقدّم مادّي وتقني وعلمي وترقٍّ ثقافي وروحي (نصف علامة لكلّ مكوّن).', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16593, 2797, 1, '(١ علامة) شكل الفطر بالتجوية التفاضليّة: تنشط التجوية الميكانيكيّة في الطبقات الليّنة من الصخر فتتفتّت بسرعة وتسقط أجزاؤها أرضاً، وتقاوم الطبقات الصلبة فتبقى في أعلى الصخر، فيتّخذ الصخر شكل نبات الفطر. (١ علامة) القور الصحراوية: تعمل الرياح بما تحمله من رمال على تآكل الطبقة السفلى الليّنة، مبقيةً الطبقة العليا الصلبة، فتتّخذ مظهر مظلّة أو شكل نبات الفطر. (١ علامة) وجه الشبه: في الحالتين يتفتّت أو يتآكل الصخر الليّن، ويقاوم الصخر الصلب فيبقى في الأعلى. (١ علامة) وجه الاختلاف: التجوية عوامل ساكنة تفتّت الصخر في مكانه ولا تنقله، أمّا الرياح فهي عامل حتّ ونقل وإرساب، تستعمل ذرّات الرمال أداةً للحتّ.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16594, 2797, 2, '(١ علامة) شكل الفطر بالتجوية التفاضليّة: تنشط التجوية الميكانيكيّة في الطبقات الليّنة من الصخر فتتفتّت بسرعة وتسقط أجزاؤها أرضاً، وتقاوم الطبقات الصلبة فتبقى في أعلى الصخر، فيتّخذ الصخر شكل نبات الفطر. (١ علامة) القور الصحراوية: تعمل الرياح بما تحمله من رمال على تآكل الطبقة السفلى الليّنة، مبقيةً الطبقة العليا الصلبة، فتتّخذ مظهر مظلّة أو شكل نبات الفطر. (١ علامة) وجه الشبه: في الحالتين يتفتّت أو يتآكل الصخر الليّن، ويقاوم الصخر الصلب فيبقى في الأعلى. (١ علامة) وجه الاختلاف: التجوية عوامل ساكنة تفتّت الصخر في مكانه ولا تنقله، أمّا الرياح فهي عامل حتّ ونقل وإرساب، تستعمل ذرّات الرمال أداةً للحتّ.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16595, 2798, 1, '(١ علامة) الموقف: لم تكن تلك الحياة بسيطة، بل غنيّة ومتنوّعة ومعقّدة أحياناً؛ فحاجة الإنسان إلى الإنسان ثابتة، لكنّ طرق تلبيتها تختلف بحسب الظروف والإمكانات والتحدّيات، ولكلّ عصر حلوله. (١ علامة) السمة الأولى: تنظيم الأسرة وأنماط الزواج المتعدّدة (الزواج بمعناه البدائي الواسع، ثمّ التبادل، ثمّ الزواج داخل العشيرة وخارجها)، والأسرة الأموميّة التي قد تكون فيها المرأة كاهنة وقاضية ورئيسة للقبيلة وقائدة في الحرب. (١ علامة) السمة الثانية: الدين، باعتقاداته التي تجيب عن أسئلة الإنسان المقلقة في صيغة أساطير، وطقوسه وشعائره ومؤسّساته، ووظائفه الكثيرة، ودفن الموتى؛ أو السحر بوصفه أولى محاولات فهم قوانين الطبيعة. (١ علامة) السمة الثالثة: الفنّ المتقن في رسوم الكهوف ومنحوتاتها، كرسوم كهف لاسكو التي تُظهر حيوانات برّيّة مرسومة بدقّة ومهارة، ملوّنة أحياناً وغنيّة بالدلالات الرمزيّة.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(16596, 2798, 2, '(١ علامة) الموقف: لم تكن تلك الحياة بسيطة، بل غنيّة ومتنوّعة ومعقّدة أحياناً؛ فحاجة الإنسان إلى الإنسان ثابتة، لكنّ طرق تلبيتها تختلف بحسب الظروف والإمكانات والتحدّيات، ولكلّ عصر حلوله. (١ علامة) السمة الأولى: تنظيم الأسرة وأنماط الزواج المتعدّدة (الزواج بمعناه البدائي الواسع، ثمّ التبادل، ثمّ الزواج داخل العشيرة وخارجها)، والأسرة الأموميّة التي قد تكون فيها المرأة كاهنة وقاضية ورئيسة للقبيلة وقائدة في الحرب. (١ علامة) السمة الثانية: الدين، باعتقاداته التي تجيب عن أسئلة الإنسان المقلقة في صيغة أساطير، وطقوسه وشعائره ومؤسّساته، ووظائفه الكثيرة، ودفن الموتى؛ أو السحر بوصفه أولى محاولات فهم قوانين الطبيعة. (١ علامة) السمة الثالثة: الفنّ المتقن في رسوم الكهوف ومنحوتاتها، كرسوم كهف لاسكو التي تُظهر حيوانات برّيّة مرسومة بدقّة ومهارة، ملوّنة أحياناً وغنيّة بالدلالات الرمزيّة.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16597, 2799, 1, '(١ علامة) الكهف الجيري: تجوّف طبيعي ضخم ساعد في تكوّنه ذوبان الجير بفعل ثاني أوكسيد الكربون المذاب في المياه المتسرّبة عبر الطبقات الجيريّة. (١ علامة) الكهف البحريّ: تكتشف الأمواج مناطق الضعف الجيولوجيّ، أي تعاقب طبقات صلبة مع أخرى ليّنة، فتُحدث حركتها المستمرّة فجوات جانبية تتّسع مع مرور الزمن لتكوّن كهوفاً بحرية. (١ علامة) الكهف الجيري من الأشكال الكارستيّة الجوفيّة الناتجة عن التجوية الكيميائيّة (إذابة الجير)، أمّا الكهف البحريّ فمن الأشكال الناتجة عن الهدم، وهو إحدى عمليات الحتّ البحريّ التي تقوم بها الأمواج.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16598, 2799, 2, '(١ علامة) الكهف الجيري: تجوّف طبيعي ضخم ساعد في تكوّنه ذوبان الجير بفعل ثاني أوكسيد الكربون المذاب في المياه المتسرّبة عبر الطبقات الجيريّة. (١ علامة) الكهف البحريّ: تكتشف الأمواج مناطق الضعف الجيولوجيّ، أي تعاقب طبقات صلبة مع أخرى ليّنة، فتُحدث حركتها المستمرّة فجوات جانبية تتّسع مع مرور الزمن لتكوّن كهوفاً بحرية. (١ علامة) الكهف الجيري من الأشكال الكارستيّة الجوفيّة الناتجة عن التجوية الكيميائيّة (إذابة الجير)، أمّا الكهف البحريّ فمن الأشكال الناتجة عن الهدم، وهو إحدى عمليات الحتّ البحريّ التي تقوم بها الأمواج.', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16599, 2800, 1, 'أ- (١ علامة) العوامل الطبيعيّة والبيئيّة أوّل ما يسمح بقيام حضارة: فتبدّل المناخ واستقراره أوجبا تحوّل الإنسان من الصيد والرعي إلى الزراعة، وهي البداية الفعليّة للحضارة؛ وقد استقرّ الإنسان على ضفاف الأنهار، وأحواض الأنهر الخصبة كانت المكان الملائم للجماعات البشريّة الأولى. ب- (١ علامة) مع اقتراب نهاية العصر الجليدي الرابع ذاب الحزام الجليدي، وتحوّلت براري جنوب المتوسّط وشمال أفريقيا إلى صحارى، فصار الحصول على الطعام أصعب (التحدّي)، فسعى الإنسان إلى إنتاج طعامه وحفظه (التصدّي للتحدّي)، فنمت حضارته. (١ علامة) نتيجتان من مثل: تدجين الكلب والغنم والماعز وزراعة الشعير والقمح؛ الاستقرار وبناء الأكواخ ثمّ البيوت الحجريّة ونشوء القرى الأولى؛ حفظ الطعام في جلود مخيطة أو حفر داخل الأرض؛ تحوّل الأسرة من أموميّة إلى أبويّة (نصف علامة لكلّ نتيجة).', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16600, 2800, 2, 'أ- (١ علامة) العوامل الطبيعيّة والبيئيّة أوّل ما يسمح بقيام حضارة: فتبدّل المناخ واستقراره أوجبا تحوّل الإنسان من الصيد والرعي إلى الزراعة، وهي البداية الفعليّة للحضارة؛ وقد استقرّ الإنسان على ضفاف الأنهار، وأحواض الأنهر الخصبة كانت المكان الملائم للجماعات البشريّة الأولى. ب- (١ علامة) مع اقتراب نهاية العصر الجليدي الرابع ذاب الحزام الجليدي، وتحوّلت براري جنوب المتوسّط وشمال أفريقيا إلى صحارى، فصار الحصول على الطعام أصعب (التحدّي)، فسعى الإنسان إلى إنتاج طعامه وحفظه (التصدّي للتحدّي)، فنمت حضارته. (١ علامة) نتيجتان من مثل: تدجين الكلب والغنم والماعز وزراعة الشعير والقمح؛ الاستقرار وبناء الأكواخ ثمّ البيوت الحجريّة ونشوء القرى الأولى؛ حفظ الطعام في جلود مخيطة أو حفر داخل الأرض؛ تحوّل الأسرة من أموميّة إلى أبويّة (نصف علامة لكلّ نتيجة).', 1, '2026-09-30 22:54:16', '2026-09-30 22:54:16'),
(16601, 2801, 1, '(١ علامة) أ- كانت شعوب بلاد ما بين النهرين تنقش الرموز على ألواح من الطين المتوافر بكثافة وهي طريّة، ثمّ تجفّفها بالنار أو بأشعّة الشمس. ولم يصل البابليّون إلى الحروف الهجائيّة، بل قامت لغتهم على مقاطع يُرمز إليها بعلامات، وقد تدلّ العلامة على أكثر من معنى (إشارة الشمس تعني الشمس والنهار والبياض). (١ علامة) ب- كانت المسماريّة صعبة: الحرفة خاصّة بالكهنة أو بعائلات تتوارثها، والتدريب قاسٍ في المعابد وملحقات القصور؛ فأدّت هذه الصعوبة إلى اختفائها تدريجاً لتحلّ محلّها أنظمة أيسر، وخصوصاً الأبجديّة الفينيقيّة، بدءاً من نهاية الألف الثاني قبل الميلاد. (١ علامة) ج- بعد أن خطا الكنعانيّون خطوة نحو الكتابة المقطعيّة بعدد محدود من المقاطع، أحصى الفينيقيّون الرموز الصوتيّة وبسّطوها وخصّوا كلّ رمز بحرف، فأحلّوا الرموز اللفظيّة مكان الرموز التصويريّة، ووُلدت الأبجديّة باثنين وعشرين حرفاً فقط.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16602, 2801, 2, '(١ علامة) أ- كانت شعوب بلاد ما بين النهرين تنقش الرموز على ألواح من الطين المتوافر بكثافة وهي طريّة، ثمّ تجفّفها بالنار أو بأشعّة الشمس. ولم يصل البابليّون إلى الحروف الهجائيّة، بل قامت لغتهم على مقاطع يُرمز إليها بعلامات، وقد تدلّ العلامة على أكثر من معنى (إشارة الشمس تعني الشمس والنهار والبياض). (١ علامة) ب- كانت المسماريّة صعبة: الحرفة خاصّة بالكهنة أو بعائلات تتوارثها، والتدريب قاسٍ في المعابد وملحقات القصور؛ فأدّت هذه الصعوبة إلى اختفائها تدريجاً لتحلّ محلّها أنظمة أيسر، وخصوصاً الأبجديّة الفينيقيّة، بدءاً من نهاية الألف الثاني قبل الميلاد. (١ علامة) ج- بعد أن خطا الكنعانيّون خطوة نحو الكتابة المقطعيّة بعدد محدود من المقاطع، أحصى الفينيقيّون الرموز الصوتيّة وبسّطوها وخصّوا كلّ رمز بحرف، فأحلّوا الرموز اللفظيّة مكان الرموز التصويريّة، ووُلدت الأبجديّة باثنين وعشرين حرفاً فقط.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16603, 2802, 1, '(١ علامة) أ- ماني من أسرة إيرانيّة، كان أبوه من العائلة الأشكانيّة الحاكمة وقد هاجر من همدان إلى بابل؛ وهناك زعم ماني أنّ الوحي ظهر له في هيئة ملاك، وقد أعدمه الملك بهرام بعد مناظرة عقائديّة. (١ علامة) ب- أخذت المانويّة عن الزردشتيّة ثنائيّة النور والظلمة: إله النور فيها يسمّى العظيم الأوّل وله خمسة عناصر منها العلم والعقل والفطنة، وللظلمات خمسة عناصر منها الضباب والدخان. والإنسان عند ماني نفس ترجع إلى العالم العلويّ، وجسد يتبع العالم السفليّ. (١ علامة) ج- اثنان ممّا يلي: وضع الخواتيم السبعة؛ فرض العشر في الأموال؛ صيام سبعة أيّام كلّ شهر؛ ترك الكذب والقتل والسرقة.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16604, 2802, 2, '(١ علامة) أ- ماني من أسرة إيرانيّة، كان أبوه من العائلة الأشكانيّة الحاكمة وقد هاجر من همدان إلى بابل؛ وهناك زعم ماني أنّ الوحي ظهر له في هيئة ملاك، وقد أعدمه الملك بهرام بعد مناظرة عقائديّة. (١ علامة) ب- أخذت المانويّة عن الزردشتيّة ثنائيّة النور والظلمة: إله النور فيها يسمّى العظيم الأوّل وله خمسة عناصر منها العلم والعقل والفطنة، وللظلمات خمسة عناصر منها الضباب والدخان. والإنسان عند ماني نفس ترجع إلى العالم العلويّ، وجسد يتبع العالم السفليّ. (١ علامة) ج- اثنان ممّا يلي: وضع الخواتيم السبعة؛ فرض العشر في الأموال؛ صيام سبعة أيّام كلّ شهر؛ ترك الكذب والقتل والسرقة.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16605, 2803, 1, '(١ علامة) المصريّون: التحنيط يلخّص معرفتهم بالتشريح والعقاقير، وقد عرفوا أهمية القلب واكتشفوا النبض، وتُعدّ برديتا إدوين سميث وإيبرس من أقدم المدوّنات الطبّيّة؛ لكنّ تداخل الطبّ مع السحر منع قيام طبّ مستقلّ. (١ علامة) أبقراط: فصل الطبّ عن الدين والفلسفة، ورأى أنّ للأمراض عللاً طبيعيّة حتّى الصرع الذي سمّاه الناس المرض المقدّس، واعتمد على نظام التغذية والرياضة أكثر من الأدوية، ووضع أخلاقيّة مهنيّة وقَسَماً لا يزال حتّى عصرنا، فاستحقّ أن يُدعى أبا الطبّ.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16606, 2803, 2, '(١ علامة) المصريّون: التحنيط يلخّص معرفتهم بالتشريح والعقاقير، وقد عرفوا أهمية القلب واكتشفوا النبض، وتُعدّ برديتا إدوين سميث وإيبرس من أقدم المدوّنات الطبّيّة؛ لكنّ تداخل الطبّ مع السحر منع قيام طبّ مستقلّ. (١ علامة) أبقراط: فصل الطبّ عن الدين والفلسفة، ورأى أنّ للأمراض عللاً طبيعيّة حتّى الصرع الذي سمّاه الناس المرض المقدّس، واعتمد على نظام التغذية والرياضة أكثر من الأدوية، ووضع أخلاقيّة مهنيّة وقَسَماً لا يزال حتّى عصرنا، فاستحقّ أن يُدعى أبا الطبّ.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16607, 2804, 1, '(١ علامة) المصادر: نهل الشرع الرومانيّ في البدء من الأخلاق والدين، ثمّ من الفكر الفلسفيّ، وبخاصّة المدرسة الرواقيّة التي غذّت فكرة الأخوّة الإنسانيّة، فصلح لإمبراطوريّة متنوّعة الثقافات والأديان. (١ علامة) مبدآن ممّا يلي: الشريعة تتوخّى الخير العامّ والجميع متساوون أمامها؛ لا تكون لصالح طبقة على حساب أخرى؛ لكلّ مواطن أن يطعن في الحكم الصادر ضدّه؛ لا يُلجأ إلى التشريع إلّا في حالات محدّدة بدقّة. وهكذا صار الشرع أساس الحرّيّة المنظّمة.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16608, 2804, 2, '(١ علامة) المصادر: نهل الشرع الرومانيّ في البدء من الأخلاق والدين، ثمّ من الفكر الفلسفيّ، وبخاصّة المدرسة الرواقيّة التي غذّت فكرة الأخوّة الإنسانيّة، فصلح لإمبراطوريّة متنوّعة الثقافات والأديان. (١ علامة) مبدآن ممّا يلي: الشريعة تتوخّى الخير العامّ والجميع متساوون أمامها؛ لا تكون لصالح طبقة على حساب أخرى؛ لكلّ مواطن أن يطعن في الحكم الصادر ضدّه؛ لا يُلجأ إلى التشريع إلّا في حالات محدّدة بدقّة. وهكذا صار الشرع أساس الحرّيّة المنظّمة.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16609, 2805, 1, '(١ علامة) في حركة الترجمة إلى العربيّة كانت كتب أرسطو أشهر المنقول في الفلسفة، ومنها كتب المنطق المعروفة بالأرغانون، وقد ترجم حنين بن إسحق نحو نصف مؤلّفات أرسطو، وتميّزت مرحلته بالدقّة وتأسيس المصطلح العلميّ. (١ علامة) قبل القرن الثاني عشر لم يعرف الأوروبيّون إلّا القليل من الفلسفة اليونانيّة، ومنه ترجمات بويتيوس لبعض كتب أرسطو المنطقيّة. (١ علامة) ثمّ نُقلت في طليطلة كتب أرسطو في المنطق والإلهيّات والطبيعيّات، ولم يتمّ النقل من اليونانيّة بل من الترجمات العربيّة، فعرفت أوروبا أرسطو أوّلاً من ترجماته العربيّة. (١ علامة) ونُقلت معها الشروح والاختصارات العربيّة، فقد نقل مايكل سكوت على الأرجح شروح ابن رشد على أرسطو، فلُقّب ابن رشد بالشارح، وعدّه توما الأكوينيّ أفضل شارح لمنطق أرسطو.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16610, 2805, 2, '(١ علامة) في حركة الترجمة إلى العربيّة كانت كتب أرسطو أشهر المنقول في الفلسفة، ومنها كتب المنطق المعروفة بالأرغانون، وقد ترجم حنين بن إسحق نحو نصف مؤلّفات أرسطو، وتميّزت مرحلته بالدقّة وتأسيس المصطلح العلميّ. (١ علامة) قبل القرن الثاني عشر لم يعرف الأوروبيّون إلّا القليل من الفلسفة اليونانيّة، ومنه ترجمات بويتيوس لبعض كتب أرسطو المنطقيّة. (١ علامة) ثمّ نُقلت في طليطلة كتب أرسطو في المنطق والإلهيّات والطبيعيّات، ولم يتمّ النقل من اليونانيّة بل من الترجمات العربيّة، فعرفت أوروبا أرسطو أوّلاً من ترجماته العربيّة. (١ علامة) ونُقلت معها الشروح والاختصارات العربيّة، فقد نقل مايكل سكوت على الأرجح شروح ابن رشد على أرسطو، فلُقّب ابن رشد بالشارح، وعدّه توما الأكوينيّ أفضل شارح لمنطق أرسطو.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16611, 2806, 1, 'أ- (١ علامة) انحصرت الديانة الرومانيّة التقليديّة في طقوس خارجيّة صارمة لا تتجاوب مع حاجات الناس الداخليّة (٠٫٥ علامة)، فأهملها أكثر الشعب (٠٫٥ علامة).\nب- (١ علامة) الرواقيّة (٠٫٥ علامة): قاعدتها العيش بانسجام مع الطبيعة، والكون عندها كلّ متماسك يحييه عقل واحد هو اللوغس، وقد أنمت روح الأخوّة بين جميع الناس، لكنّ رؤيتها حتميّة. الأبيقوريّة (٠٫٥ علامة): ظهرت لأنّ الحتميّة لم ترضِ أنصار الحرّيّة الفرديّة، فركّزت على الحرّيّة حتّى أنكرت دور الآلهة في حياة الناس، والسعادة عندها بإشباع الحاجات بلا خوف وبتنظيم اللذّات والقناعة.\nج- (١ علامة) الديانات الشرقيّة (٠٫٥ علامة): تخاطب العاطفة والخيال وتقدّم حلولاً خلاصيّة، وطقوسها تُعدّ موتاً رمزيّاً تعقبه ولادة روحيّة جديدة، لكنّها بقيت تحصر الألوهة داخل الكون. الغنوصيّة (٠٫٥ علامة): رأت العالم المخلوق شرّيراً والجسد سجناً للروح، والخلاص عندها أن يعي الإنسان أنّه شرارة إلهيّة منفيّة في عالم مظلم تحنّ إلى مصدرها.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16612, 2806, 2, 'أ- (١ علامة) انحصرت الديانة الرومانيّة التقليديّة في طقوس خارجيّة صارمة لا تتجاوب مع حاجات الناس الداخليّة (٠٫٥ علامة)، فأهملها أكثر الشعب (٠٫٥ علامة).\nب- (١ علامة) الرواقيّة (٠٫٥ علامة): قاعدتها العيش بانسجام مع الطبيعة، والكون عندها كلّ متماسك يحييه عقل واحد هو اللوغس، وقد أنمت روح الأخوّة بين جميع الناس، لكنّ رؤيتها حتميّة. الأبيقوريّة (٠٫٥ علامة): ظهرت لأنّ الحتميّة لم ترضِ أنصار الحرّيّة الفرديّة، فركّزت على الحرّيّة حتّى أنكرت دور الآلهة في حياة الناس، والسعادة عندها بإشباع الحاجات بلا خوف وبتنظيم اللذّات والقناعة.\nج- (١ علامة) الديانات الشرقيّة (٠٫٥ علامة): تخاطب العاطفة والخيال وتقدّم حلولاً خلاصيّة، وطقوسها تُعدّ موتاً رمزيّاً تعقبه ولادة روحيّة جديدة، لكنّها بقيت تحصر الألوهة داخل الكون. الغنوصيّة (٠٫٥ علامة): رأت العالم المخلوق شرّيراً والجسد سجناً للروح، والخلاص عندها أن يعي الإنسان أنّه شرارة إلهيّة منفيّة في عالم مظلم تحنّ إلى مصدرها.', 1, '2026-09-30 22:54:17', '2026-09-30 22:54:17'),
(16613, 2807, 1, '(١ علامة) البداوة أصل وأقدم من الحضارة، لأنّ الإنسان يبدأ بالضروري قبل الكمالي؛ فالعمران البدويّ يقتصر على الضروري من القوت والسكن والدفء، ثمّ تنشأ الحضارة باتّساع أحوال البدو أو بالتفاعل بين الغالب والمغلوب، فتكون غاية العمران. (١ علامة) الترف يفسد أخلاق أهل الحضر ويذهب بشجاعتهم، وحين يبلغ غايته تذهب المكاسب في النفقات فيعمّ الغشّ والكذب؛ وفي الدولة تزيد النفقات مع الترف فتفرض المكوس ثمّ تصادر أموال الرعايا، فيختلّ المال الذي هو قوام الجند وأحد أساسَي الملك، فتضمحلّ الدولة كالفتيلة في السراج إذا فني زيتها. (١ علامة) العمران مثل الدولة له عمر محدّد، والدولة للعمران بمثابة الصورة للمادّة، فاختلال أحدهما يؤثّر في الآخر.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16614, 2807, 2, '(١ علامة) البداوة أصل وأقدم من الحضارة، لأنّ الإنسان يبدأ بالضروري قبل الكمالي؛ فالعمران البدويّ يقتصر على الضروري من القوت والسكن والدفء، ثمّ تنشأ الحضارة باتّساع أحوال البدو أو بالتفاعل بين الغالب والمغلوب، فتكون غاية العمران. (١ علامة) الترف يفسد أخلاق أهل الحضر ويذهب بشجاعتهم، وحين يبلغ غايته تذهب المكاسب في النفقات فيعمّ الغشّ والكذب؛ وفي الدولة تزيد النفقات مع الترف فتفرض المكوس ثمّ تصادر أموال الرعايا، فيختلّ المال الذي هو قوام الجند وأحد أساسَي الملك، فتضمحلّ الدولة كالفتيلة في السراج إذا فني زيتها. (١ علامة) العمران مثل الدولة له عمر محدّد، والدولة للعمران بمثابة الصورة للمادّة، فاختلال أحدهما يؤثّر في الآخر.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16615, 2808, 1, 'أ- (١ علامة) كلام الصديق يعبّر عن السلام في المنطق العاديّ، حيث يقوم السلام على العدالة، فيؤدّي كلّ فرد واجباته وينال حقوقه (٠٫٥ علامة). أمّا في المنطق المسيحيّ فالسلام يتخطّى المعاملة بالمثل: المصالحة تتطلّب الصفح، سبعين مرّة سبع مرّات، والمحبّة تمتدّ حتّى إلى الأعداء (٠٫٥ علامة).\nب- (١ علامة) كتب متّى إنجيله ليؤكّد أنّ يسوع هو موسى الجديد، واضع شريعة المحبّة لجميع البشر حتّى الأعداء (٠٫٥ علامة). وعلى المؤمن ألّا يقسو في احتقار ذاته، وألّا يهرب إلى عزلة، بل يطبّق شريعة المحبّة، فيحبّ الله والقريب؛ فيكون الصفح عن الزميل تطبيقاً لهذه الشريعة (٠٫٥ علامة).\nج- (١ علامة) مستويات المحبّة: أوّلها الحبّ الزوجيّ، ثمّ حبّ القريب بالتسامح ومعاملة الآخر كالذات والامتناع عن إدانته (٠٫٥ علامة)، وأعلاها محبّة الأعداء؛ فشريعة المحبّة في النهاية هي شريعة الكمال (٠٫٥ علامة).', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16616, 2808, 2, 'أ- (١ علامة) كلام الصديق يعبّر عن السلام في المنطق العاديّ، حيث يقوم السلام على العدالة، فيؤدّي كلّ فرد واجباته وينال حقوقه (٠٫٥ علامة). أمّا في المنطق المسيحيّ فالسلام يتخطّى المعاملة بالمثل: المصالحة تتطلّب الصفح، سبعين مرّة سبع مرّات، والمحبّة تمتدّ حتّى إلى الأعداء (٠٫٥ علامة).\nب- (١ علامة) كتب متّى إنجيله ليؤكّد أنّ يسوع هو موسى الجديد، واضع شريعة المحبّة لجميع البشر حتّى الأعداء (٠٫٥ علامة). وعلى المؤمن ألّا يقسو في احتقار ذاته، وألّا يهرب إلى عزلة، بل يطبّق شريعة المحبّة، فيحبّ الله والقريب؛ فيكون الصفح عن الزميل تطبيقاً لهذه الشريعة (٠٫٥ علامة).\nج- (١ علامة) مستويات المحبّة: أوّلها الحبّ الزوجيّ، ثمّ حبّ القريب بالتسامح ومعاملة الآخر كالذات والامتناع عن إدانته (٠٫٥ علامة)، وأعلاها محبّة الأعداء؛ فشريعة المحبّة في النهاية هي شريعة الكمال (٠٫٥ علامة).', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16617, 2809, 1, '(١ علامة) في أصول الفقه: صرّح الغزالي في «المستصفى» بالأصول الخمسة التي حفظتها الشريعة، فقال: «مقصود الشرع من الخلق خمسة»، وهي: الدين، والنفس، والعقل، والنسل، والمال. (٠٫٥ علامة) وقال: «كلّ ما يفوّت هذه الأصول الخمسة فهو مفسدة، ودفعها مصلحة». (١ علامة) في التصوّف: قسم الغزالي علوم طريق الآخرة إلى علم المعاملة وعلم المكاشفة، فلم يتعرّض للمكاشفة لأنّها رزق إلهيّ شخصيّ، ورسّخ علم المعاملة وجعله فرض عين على كلّ مسلم وطريقاً إلى المكاشفة، وبذلك وفّق بين الفقه والتصوّف. (٠٫٥ علامة) ورفض أن يسلّم المريد إرادته للشيخ، فألّف «إحياء علوم الدين» ليسير السالك بإرادته الواعية.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16618, 2809, 2, '(١ علامة) في أصول الفقه: صرّح الغزالي في «المستصفى» بالأصول الخمسة التي حفظتها الشريعة، فقال: «مقصود الشرع من الخلق خمسة»، وهي: الدين، والنفس، والعقل، والنسل، والمال. (٠٫٥ علامة) وقال: «كلّ ما يفوّت هذه الأصول الخمسة فهو مفسدة، ودفعها مصلحة». (١ علامة) في التصوّف: قسم الغزالي علوم طريق الآخرة إلى علم المعاملة وعلم المكاشفة، فلم يتعرّض للمكاشفة لأنّها رزق إلهيّ شخصيّ، ورسّخ علم المعاملة وجعله فرض عين على كلّ مسلم وطريقاً إلى المكاشفة، وبذلك وفّق بين الفقه والتصوّف. (٠٫٥ علامة) ورفض أن يسلّم المريد إرادته للشيخ، فألّف «إحياء علوم الدين» ليسير السالك بإرادته الواعية.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16619, 2810, 1, 'أ- (١ علامة) يجمع الدير بين الروحانيّة: أماكن للحياة الجمعيّة ومجالس لفلسفة المتوحّدين (٠٫٥ علامة)، والعلم: مدارس لقنية العلوم، وخدمة الناس: تكايا لمأوى الغرباء (٠٫٥ علامة).\nب- (١ علامة) ليس النسك هرباً من العالم، إنّما هو احتجاج على النظام الأخلاقيّ السائد في العالم (٠٫٥ علامة). وهو رفض لضياع النفس وذوبان الشخصيّة في الملذّات، ووعي لوحدة الشخصيّة ولأهمّيّة سيطرة الإرادة على الغرائز (٠٫٥ علامة).', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16620, 2810, 2, 'أ- (١ علامة) يجمع الدير بين الروحانيّة: أماكن للحياة الجمعيّة ومجالس لفلسفة المتوحّدين (٠٫٥ علامة)، والعلم: مدارس لقنية العلوم، وخدمة الناس: تكايا لمأوى الغرباء (٠٫٥ علامة).\nب- (١ علامة) ليس النسك هرباً من العالم، إنّما هو احتجاج على النظام الأخلاقيّ السائد في العالم (٠٫٥ علامة). وهو رفض لضياع النفس وذوبان الشخصيّة في الملذّات، ووعي لوحدة الشخصيّة ولأهمّيّة سيطرة الإرادة على الغرائز (٠٫٥ علامة).', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16621, 2811, 1, 'أ- (١ علامة) الفعل الأوّل من الأفعال التي لا تتحقّق بمعزل عن الآخرين، لأنّ الفوز يحتاج إلى الفريق كلّه (٠٫٥ علامة). والفعل الثاني في متناولنا لكنّه شرّير، فنحن نرغب فيه ونعرف أنّه غير مفوَّض إلينا (٠٫٥ علامة).\nب- (١ علامة) المشيئة هي التي تميل إلى الخير (٠٫٥ علامة)، أمّا الإرادة فهي التي تختار خيراً معيّناً وتنفّذه (٠٫٥ علامة).', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16622, 2811, 2, 'أ- (١ علامة) الفعل الأوّل من الأفعال التي لا تتحقّق بمعزل عن الآخرين، لأنّ الفوز يحتاج إلى الفريق كلّه (٠٫٥ علامة). والفعل الثاني في متناولنا لكنّه شرّير، فنحن نرغب فيه ونعرف أنّه غير مفوَّض إلينا (٠٫٥ علامة).\nب- (١ علامة) المشيئة هي التي تميل إلى الخير (٠٫٥ علامة)، أمّا الإرادة فهي التي تختار خيراً معيّناً وتنفّذه (٠٫٥ علامة).', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16623, 2812, 1, '(١ علامة) نظر هيجل إلى الحضارات كحلقات متعاقبة، متناقضة ومتداخلة في آن. (١ علامة) جعل الحرّية غاية أخيرة لحركة العقل، فالعقل يقود العالم ومع كلّ مرحلة يصير الروح أكثر حرّية ووعياً بذاته. (١ علامة) استعمل الجدل ليفسّر كيف تموت حضارة في شكلها بينما تدخل عناصرها في تشكيل حضارة صاعدة، وهكذا أدخل فكرة الصيرورة إلى دراسة الحضارات فصار التاريخ مفهوماً بالعقل.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16624, 2812, 2, '(١ علامة) نظر هيجل إلى الحضارات كحلقات متعاقبة، متناقضة ومتداخلة في آن. (١ علامة) جعل الحرّية غاية أخيرة لحركة العقل، فالعقل يقود العالم ومع كلّ مرحلة يصير الروح أكثر حرّية ووعياً بذاته. (١ علامة) استعمل الجدل ليفسّر كيف تموت حضارة في شكلها بينما تدخل عناصرها في تشكيل حضارة صاعدة، وهكذا أدخل فكرة الصيرورة إلى دراسة الحضارات فصار التاريخ مفهوماً بالعقل.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16625, 2813, 1, '(١ علامة) أ- نظريّة الجنس ونظريّة البيئة: فلا الجنس ولا البيئة، إذا أُخذ كلّ منهما بمفرده، هو العامل الذي أيقظ البشر من الركود؛ فبدء الحضارات نتيجة تفاعل بين العوامل، والعامل الحاسم ليس وحدة بل علاقة. (١ علامة) ب- الإرادة والتصميم، وبها تنتقل الجماعة من الركود إلى القوّة الدافعة، وهذا معنى التحدّي والاستجابة. (١ علامة) ج- لا؛ فللشدّة حدود إذا تجاوزتها لم تعد تبعث استجابة ناجحة، لذلك فأنسب تحدٍّ هو الوسط الذهبيّ بين التفريط والإفراط في الشدّة.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16626, 2813, 2, '(١ علامة) أ- نظريّة الجنس ونظريّة البيئة: فلا الجنس ولا البيئة، إذا أُخذ كلّ منهما بمفرده، هو العامل الذي أيقظ البشر من الركود؛ فبدء الحضارات نتيجة تفاعل بين العوامل، والعامل الحاسم ليس وحدة بل علاقة. (١ علامة) ب- الإرادة والتصميم، وبها تنتقل الجماعة من الركود إلى القوّة الدافعة، وهذا معنى التحدّي والاستجابة. (١ علامة) ج- لا؛ فللشدّة حدود إذا تجاوزتها لم تعد تبعث استجابة ناجحة، لذلك فأنسب تحدٍّ هو الوسط الذهبيّ بين التفريط والإفراط في الشدّة.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16627, 2814, 1, '(١ علامة) أ- لأنّ هيغل، الفيلسوف الألماني، فيلسوف قبل أن يكون مؤرّخاً، أمّا توينبي، المؤرّخ البريطاني، فمؤرّخ قبل أن يكون فيلسوفاً. (١ علامة) ب- عند هيغل: العقل يقود العالم، وهو القوّة الدافعة لحركة الحضارات وغايتها الأخيرة، وتتعاقب الحضارات وفق المنهج الجدليّ (قضيّة، نقيض، تركيب) في حركة صاعدة نحو الحرّية: من فرد واحد في العالم الشرقيّ، إلى فئة في العالم الإغريقيّ الرومانيّ، إلى كلّ إنسان في العالم الجرمانيّ. (١ علامة) عند توينبي: الحضارة تنشأ استجابةً ناجحة لتحدٍّ، بتفاعل عوامل عدّة مع الإرادة والتصميم، لا بالجنس أو البيئة وحدهما، وتنهار حين تفقد طاقتها الإبداعيّة ويتوقّف الإبداع. (١ علامة) ج- فلسفة الحضارة محاولة في المنهج أكثر ممّا هي إضافات في الوقائع، ولا تدّعي المعرفة الأكيدة بالأسباب المسؤولة عن صعود حضارة ثمّ انحلالها؛ لذلك يمكن أن تتباين مواقف الفلاسفة كما تباين موقفا هيغل وتوينبي، ووظيفة الفلسفة أن تكتشف الأسئلة وتصوغها بوضوح وتخضع الإجابات تكراراً للتحليل والنقد.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16628, 2814, 2, '(١ علامة) أ- لأنّ هيغل، الفيلسوف الألماني، فيلسوف قبل أن يكون مؤرّخاً، أمّا توينبي، المؤرّخ البريطاني، فمؤرّخ قبل أن يكون فيلسوفاً. (١ علامة) ب- عند هيغل: العقل يقود العالم، وهو القوّة الدافعة لحركة الحضارات وغايتها الأخيرة، وتتعاقب الحضارات وفق المنهج الجدليّ (قضيّة، نقيض، تركيب) في حركة صاعدة نحو الحرّية: من فرد واحد في العالم الشرقيّ، إلى فئة في العالم الإغريقيّ الرومانيّ، إلى كلّ إنسان في العالم الجرمانيّ. (١ علامة) عند توينبي: الحضارة تنشأ استجابةً ناجحة لتحدٍّ، بتفاعل عوامل عدّة مع الإرادة والتصميم، لا بالجنس أو البيئة وحدهما، وتنهار حين تفقد طاقتها الإبداعيّة ويتوقّف الإبداع. (١ علامة) ج- فلسفة الحضارة محاولة في المنهج أكثر ممّا هي إضافات في الوقائع، ولا تدّعي المعرفة الأكيدة بالأسباب المسؤولة عن صعود حضارة ثمّ انحلالها؛ لذلك يمكن أن تتباين مواقف الفلاسفة كما تباين موقفا هيغل وتوينبي، ووظيفة الفلسفة أن تكتشف الأسئلة وتصوغها بوضوح وتخضع الإجابات تكراراً للتحليل والنقد.', 1, '2026-09-30 22:54:18', '2026-09-30 22:54:18'),
(16629, 2815, 1, '(١ علامة) أ- تُشتقّ كلمة الحضارة في العربيّة من «حضر» الذي يقابل «بدو»، وابن خلدون استعمل هذا المعنى فربط الحضارة بحياة الحضر، أي بالمدينة، فهي عنده تفنّن في الترف وإحكام للصنائع المستعملة فيه. (١ علامة) ب- الحضارة في معناها الحديث هي مجموع الإنتاج المادّي والروحي والعلمي والتقني، ومعه الفنون والحرف والتقاليد وأنظمة الحكم وأساليب العيش، لمجتمع ما ولفترة طويلة نسبيّاً؛ أي كلّ ما أضافه الإنسان إلى الطبيعة ماديّاً وروحيّاً. (١ علامة) ج- لأنّ المعنى الحديث أوسع من معنى ابن خلدون ولا يقصر الحضارة على المدينة: فكلّ ما أضافه الإنسان إلى الطبيعة، منذ تعلّم إشعال النار، حضارة؛ لذلك فلكلّ جماعة بشريّة حضارة، لا لأهل المدن وحدهم.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16630, 2815, 2, '(١ علامة) أ- تُشتقّ كلمة الحضارة في العربيّة من «حضر» الذي يقابل «بدو»، وابن خلدون استعمل هذا المعنى فربط الحضارة بحياة الحضر، أي بالمدينة، فهي عنده تفنّن في الترف وإحكام للصنائع المستعملة فيه. (١ علامة) ب- الحضارة في معناها الحديث هي مجموع الإنتاج المادّي والروحي والعلمي والتقني، ومعه الفنون والحرف والتقاليد وأنظمة الحكم وأساليب العيش، لمجتمع ما ولفترة طويلة نسبيّاً؛ أي كلّ ما أضافه الإنسان إلى الطبيعة ماديّاً وروحيّاً. (١ علامة) ج- لأنّ المعنى الحديث أوسع من معنى ابن خلدون ولا يقصر الحضارة على المدينة: فكلّ ما أضافه الإنسان إلى الطبيعة، منذ تعلّم إشعال النار، حضارة؛ لذلك فلكلّ جماعة بشريّة حضارة، لا لأهل المدن وحدهم.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16631, 2816, 1, '(١ علامة) العوامل الطبيعيّة والاقتصاديّة مهمّة لكنّها لا تكفي وحدها لبناء حضارة؛ فالموارد الطبيعيّة موجودة دائماً، ولم يستغلّها ويطوّرها إلّا الإنسان بفضل ما امتلكه من عوامل فكريّة وعلميّة. (١ علامة) وهذا الشرط الإنساني يقوى عند بعض الجماعات ويضعف عند أخرى، فقوي عند الجماعة الأولى وضعف عند الثانية؛ ولذلك كانت إرادة الإنسان وعقله العامل الأساسيّ، وأحياناً الحاسم، في نشوء الحضارات.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16632, 2816, 2, '(١ علامة) العوامل الطبيعيّة والاقتصاديّة مهمّة لكنّها لا تكفي وحدها لبناء حضارة؛ فالموارد الطبيعيّة موجودة دائماً، ولم يستغلّها ويطوّرها إلّا الإنسان بفضل ما امتلكه من عوامل فكريّة وعلميّة. (١ علامة) وهذا الشرط الإنساني يقوى عند بعض الجماعات ويضعف عند أخرى، فقوي عند الجماعة الأولى وضعف عند الثانية؛ ولذلك كانت إرادة الإنسان وعقله العامل الأساسيّ، وأحياناً الحاسم، في نشوء الحضارات.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16633, 2817, 1, '(١ علامة) الرازي: كان يصف المرض وصفاً دقيقاً في كلّ مرحلة من مراحله، ويشدّد على الأعراض المتشابهة لمرضين مختلفين. ففي المرضين يظهر طفح على الجلد له علاقة بارتفاع حرارة الجسم، لكنّ طفح الجدري يترك آثاراً تبقى مدى الحياة، أمّا طفح الحصبة فيزول بعد الشفاء (ومن أخطار الجدري أنّه يسبّب العمى). (١ علامة) ابن سينا: سبقه إلى دراسة هذين المرضين ثابت بن قرّة والرازي، لكنّه تميّز من الرازي بأسلوبه الواضح وعرضه الموجز. (١ علامة) العلامة في القول: يميّز ابن سينا بين المرضين بعلامة واحدة واضحة، هي أنّ الحصبة تخرج في الأكثر دفعة واحدة، أمّا الجدري فيخرج شيئاً بعد شيء.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16634, 2817, 2, '(١ علامة) الرازي: كان يصف المرض وصفاً دقيقاً في كلّ مرحلة من مراحله، ويشدّد على الأعراض المتشابهة لمرضين مختلفين. ففي المرضين يظهر طفح على الجلد له علاقة بارتفاع حرارة الجسم، لكنّ طفح الجدري يترك آثاراً تبقى مدى الحياة، أمّا طفح الحصبة فيزول بعد الشفاء (ومن أخطار الجدري أنّه يسبّب العمى). (١ علامة) ابن سينا: سبقه إلى دراسة هذين المرضين ثابت بن قرّة والرازي، لكنّه تميّز من الرازي بأسلوبه الواضح وعرضه الموجز. (١ علامة) العلامة في القول: يميّز ابن سينا بين المرضين بعلامة واحدة واضحة، هي أنّ الحصبة تخرج في الأكثر دفعة واحدة، أمّا الجدري فيخرج شيئاً بعد شيء.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16635, 2818, 1, '(١ علامة) الدين بمعناه العامّ سمة حاضرة ومشتركة لدى سائر جماعات ما قبل التاريخ، فلم تخلُ جماعة واحدة من العامل الدينيّ؛ وهو مجموعة اعتقادات تُعدّ حقائق ثابتة تجيب عن الأسئلة المقلقة لدى الإنسان، وتأتي غالباً في صيغة أساطير. (١ علامة) ومن مظاهره التي توضحها المكتشفات: دفن الموتى والمحافظة على جثّة الميت لاعتقاده بإمكانيّة العودة إلى الحياة، وتقديس قوى متعدّدة مثل الصخر والجبل والمطر والريح والنهر والقمر والشمس.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16636, 2818, 2, '(١ علامة) الدين بمعناه العامّ سمة حاضرة ومشتركة لدى سائر جماعات ما قبل التاريخ، فلم تخلُ جماعة واحدة من العامل الدينيّ؛ وهو مجموعة اعتقادات تُعدّ حقائق ثابتة تجيب عن الأسئلة المقلقة لدى الإنسان، وتأتي غالباً في صيغة أساطير. (١ علامة) ومن مظاهره التي توضحها المكتشفات: دفن الموتى والمحافظة على جثّة الميت لاعتقاده بإمكانيّة العودة إلى الحياة، وتقديس قوى متعدّدة مثل الصخر والجبل والمطر والريح والنهر والقمر والشمس.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16637, 2819, 1, '(١ علامة) أ- يعالج النصّ السبب الثالث لضرورة الاجتماع، وهو الوازع: فإذا حصل الاجتماع ظهر ما في طباع البشر الحيوانية من عدوان وظلم، فلا بدّ من وازع يدفع بعض الناس عن بعض. ولا يكفي السلاح لأنّه في متناول الجميع. (١ علامة) ب- الوازع في الحضارة هو صاحب الملك، الذي له الغلبة والسلطان واليد القاهرة، حتّى لا يصل أحد إلى غيره بعدوان (أمّا في البداوة فهو شيخ القبيلة من البيت الأقوى). (١ علامة) ج- لا يشترط ذلك؛ فالوازع قد يقوم بسطوة الملك وقهر أهل الشوكة ولو لم يكن شرع، كما عند أمم المجوس. ودليله من الواقع أنّ الدول التي انتشرت فيها الأديان المنزلة أقلّية بالنسبة إلى غيرها، وهذا يدلّ على نظرته الواقعيّة.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16638, 2819, 2, '(١ علامة) أ- يعالج النصّ السبب الثالث لضرورة الاجتماع، وهو الوازع: فإذا حصل الاجتماع ظهر ما في طباع البشر الحيوانية من عدوان وظلم، فلا بدّ من وازع يدفع بعض الناس عن بعض. ولا يكفي السلاح لأنّه في متناول الجميع. (١ علامة) ب- الوازع في الحضارة هو صاحب الملك، الذي له الغلبة والسلطان واليد القاهرة، حتّى لا يصل أحد إلى غيره بعدوان (أمّا في البداوة فهو شيخ القبيلة من البيت الأقوى). (١ علامة) ج- لا يشترط ذلك؛ فالوازع قد يقوم بسطوة الملك وقهر أهل الشوكة ولو لم يكن شرع، كما عند أمم المجوس. ودليله من الواقع أنّ الدول التي انتشرت فيها الأديان المنزلة أقلّية بالنسبة إلى غيرها، وهذا يدلّ على نظرته الواقعيّة.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16639, 2820, 1, '(١ علامة) العامل الطبيعيّ: تراجع الحزام الجليدي واستقرار المناخ أوجبا تحوّل الإنسان من الصيد والرعي إلى الزراعة؛ وبالزراعة تنتهي العصور الحجريّة الممتدّة من أوّل ظهور الإنسان إلى حين تحوّله إلى الزراعة. (١ علامة) الأثر في الغذاء: كانت الثورة الزراعيّة، وهي أوّل ثورة تكنولوجيّة في التاريخ، أوّل التحوّلات الحضاريّة وأكبرها، إذ نقلت الإنسان من جامع للغذاء بالتنقّل والالتقاط والصيد إلى منتج له، فاستأنس الحيوان ودجّن القمح والشعير وبنى الأكواخ ثمّ القرى. (١ علامة) الأثر في الأسرة: بعد التحوّل إلى الزراعة والاستقرار صارت الأسرة أبويّة بعد أن كانت أموميّة، وصارت المرأة هي التي تنتقل حاملة أملاكها وحصّتها من الإرث.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16640, 2820, 2, '(١ علامة) العامل الطبيعيّ: تراجع الحزام الجليدي واستقرار المناخ أوجبا تحوّل الإنسان من الصيد والرعي إلى الزراعة؛ وبالزراعة تنتهي العصور الحجريّة الممتدّة من أوّل ظهور الإنسان إلى حين تحوّله إلى الزراعة. (١ علامة) الأثر في الغذاء: كانت الثورة الزراعيّة، وهي أوّل ثورة تكنولوجيّة في التاريخ، أوّل التحوّلات الحضاريّة وأكبرها، إذ نقلت الإنسان من جامع للغذاء بالتنقّل والالتقاط والصيد إلى منتج له، فاستأنس الحيوان ودجّن القمح والشعير وبنى الأكواخ ثمّ القرى. (١ علامة) الأثر في الأسرة: بعد التحوّل إلى الزراعة والاستقرار صارت الأسرة أبويّة بعد أن كانت أموميّة، وصارت المرأة هي التي تنتقل حاملة أملاكها وحصّتها من الإرث.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16641, 2821, 1, '(١ علامة) إذا تعاطى الحاكم التجارة احتكرها، لأنّ التجّار لا يقدرون على منافسة نفوذه السياسيّ؛ والاحتكار عموماً يقتل التجارة ويضعف الدولة، لأنّه يضعف جبايتها. (١ علامة) وتكون التجارة مربحة إذا كانت في السلع النادرة أو الثمينة أو الكثيرة الطلب.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16642, 2821, 2, '(١ علامة) إذا تعاطى الحاكم التجارة احتكرها، لأنّ التجّار لا يقدرون على منافسة نفوذه السياسيّ؛ والاحتكار عموماً يقتل التجارة ويضعف الدولة، لأنّه يضعف جبايتها. (١ علامة) وتكون التجارة مربحة إذا كانت في السلع النادرة أو الثمينة أو الكثيرة الطلب.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16643, 2822, 1, '(١ علامة) التعليل: عظم الدولة واتّساع نطاقها وعمرها على نسبة القائمين بها؛ فإذا كثرت ممالكها كثرت أطرافها، والنقص يبدأ من الأطراف، فتكثر أزمان النقص ويطول أمدها، ولذلك عمرت دولة العبّاسيّين قريباً من أربعمائة سنة. (١ علامة) زوال التناقض: نظريّة الأجيال الثلاثة تنطبق على الدول العاديّة، أمّا إطالة العمر فتنطبق على الدول المتّسعة النطاق.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16644, 2822, 2, '(١ علامة) التعليل: عظم الدولة واتّساع نطاقها وعمرها على نسبة القائمين بها؛ فإذا كثرت ممالكها كثرت أطرافها، والنقص يبدأ من الأطراف، فتكثر أزمان النقص ويطول أمدها، ولذلك عمرت دولة العبّاسيّين قريباً من أربعمائة سنة. (١ علامة) زوال التناقض: نظريّة الأجيال الثلاثة تنطبق على الدول العاديّة، أمّا إطالة العمر فتنطبق على الدول المتّسعة النطاق.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16645, 2823, 1, '(١ علامة) المقصود بالاختبار في قول كبلر نتيجة الرصد، أي أرصاد تيخو براهي الدقيقة؛ فالرصد صار هو الحَكَم. (١ علامة) بدأ كبلر بفرض مدار دائريّ للمرّيخ، فظهر فرق بثماني دقائق بين حساباته ورصدين لتيخو. وبينما سمح بطليموس لنفسه بتساهل قدره أربع دقائق، وثق كبلر بأرصاد تيخو ورفض هذا الفرق، فوضع تسع عشرة فرضيّة وأعاد حساباته أكثر من سبعين مرّة حتّى وصل إلى الشكل البيضاويّ. (١ علامة) يقوم المنهج الاختباري عند برنار على الإحساس الذي يبادر ويعطي الفكرة الأساسيّة أي الحدس، ثمّ العقل الذي يوضّحها ويوسّعها، ثمّ الاختبار الذي يهدي العقل ويحكم على استنتاجاته. (١ علامة) الفكرة المشتركة: لا يكفي الحساب أو التفكير العقليّ وحده، بل يجب أن يخضع لحكم الاختبار (الرصد عند كبلر، والاختبار عند برنار)، فهو الذي يقرّر صحّة النتائج.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16646, 2823, 2, '(١ علامة) المقصود بالاختبار في قول كبلر نتيجة الرصد، أي أرصاد تيخو براهي الدقيقة؛ فالرصد صار هو الحَكَم. (١ علامة) بدأ كبلر بفرض مدار دائريّ للمرّيخ، فظهر فرق بثماني دقائق بين حساباته ورصدين لتيخو. وبينما سمح بطليموس لنفسه بتساهل قدره أربع دقائق، وثق كبلر بأرصاد تيخو ورفض هذا الفرق، فوضع تسع عشرة فرضيّة وأعاد حساباته أكثر من سبعين مرّة حتّى وصل إلى الشكل البيضاويّ. (١ علامة) يقوم المنهج الاختباري عند برنار على الإحساس الذي يبادر ويعطي الفكرة الأساسيّة أي الحدس، ثمّ العقل الذي يوضّحها ويوسّعها، ثمّ الاختبار الذي يهدي العقل ويحكم على استنتاجاته. (١ علامة) الفكرة المشتركة: لا يكفي الحساب أو التفكير العقليّ وحده، بل يجب أن يخضع لحكم الاختبار (الرصد عند كبلر، والاختبار عند برنار)، فهو الذي يقرّر صحّة النتائج.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16647, 2824, 1, '(١ علامة) كبلر: اعتمد نيوتن على قوانين كبلر الفلكيّة الثلاثة ووضع لها ثلاثة قوانين نظريّة تشرحها، فصارت قوانين فيزيائيّة عامّة تنطبق على حركات الأفلاك في أيّ مكان وأيّ زمان؛ وحوّل القوّة الشبيهة بالمغناطيس التي قال بها كبلر إلى قوّة الجاذبيّة الكونيّة. (١ علامة) غاليليو، وعليه كان اعتماد نيوتن الأكبر: اكتشف أنّ مدّة سقوط الأجسام متساوية مهما اختلف ثقلها، وأنّ المسافة التي يقطعها الجسم الساقط تتناسب مع مربّع مدّة السقوط، وقد جعل نيوتن هذا القانون في صلب نظريّة الجاذبيّة. (١ علامة) هويغنز الهولندي: بحث في رقّاص الساعة والقوّة الطاردة والقصور الذاتي، وكان ثالث العمالقة الذين اعتمد عليهم نيوتن وبنى نظريّته على أعمالهم.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16648, 2824, 2, '(١ علامة) كبلر: اعتمد نيوتن على قوانين كبلر الفلكيّة الثلاثة ووضع لها ثلاثة قوانين نظريّة تشرحها، فصارت قوانين فيزيائيّة عامّة تنطبق على حركات الأفلاك في أيّ مكان وأيّ زمان؛ وحوّل القوّة الشبيهة بالمغناطيس التي قال بها كبلر إلى قوّة الجاذبيّة الكونيّة. (١ علامة) غاليليو، وعليه كان اعتماد نيوتن الأكبر: اكتشف أنّ مدّة سقوط الأجسام متساوية مهما اختلف ثقلها، وأنّ المسافة التي يقطعها الجسم الساقط تتناسب مع مربّع مدّة السقوط، وقد جعل نيوتن هذا القانون في صلب نظريّة الجاذبيّة. (١ علامة) هويغنز الهولندي: بحث في رقّاص الساعة والقوّة الطاردة والقصور الذاتي، وكان ثالث العمالقة الذين اعتمد عليهم نيوتن وبنى نظريّته على أعمالهم.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16649, 2825, 1, '(١ علامة) بالنسبة إلى نظام مربوط بالقطار يسقط الحجر في خطّ عموديّ مستقيم، وبالنسبة إلى نظام مربوط بالأرض يرسم خطّاً منحنياً على شكل قطع مكافئ (يراه الفلّاح يسقط بخطّ مائل). (١ علامة) ليس للحجر مسار قائم بذاته، بل هناك فقط مسار بالنسبة إلى جسم مرجع محدّد؛ لأنّ الحركة، أي السرعة والاتّجاه، نسبيّة، ولا يوجد مكان في الكون يمكن اعتباره مرجعاً لحركة مطلقة، فلا معنى لعبارة «الحركة الحقيقيّة». (١ علامة) في فيزياء غاليليو ونيوتن يُظنّ أنّ للحركة حقيقة مطلقة، أمّا عند أينشتاين فهي نسبيّة إلى مرجع.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16650, 2825, 2, '(١ علامة) بالنسبة إلى نظام مربوط بالقطار يسقط الحجر في خطّ عموديّ مستقيم، وبالنسبة إلى نظام مربوط بالأرض يرسم خطّاً منحنياً على شكل قطع مكافئ (يراه الفلّاح يسقط بخطّ مائل). (١ علامة) ليس للحجر مسار قائم بذاته، بل هناك فقط مسار بالنسبة إلى جسم مرجع محدّد؛ لأنّ الحركة، أي السرعة والاتّجاه، نسبيّة، ولا يوجد مكان في الكون يمكن اعتباره مرجعاً لحركة مطلقة، فلا معنى لعبارة «الحركة الحقيقيّة». (١ علامة) في فيزياء غاليليو ونيوتن يُظنّ أنّ للحركة حقيقة مطلقة، أمّا عند أينشتاين فهي نسبيّة إلى مرجع.', 1, '2026-09-30 22:54:19', '2026-09-30 22:54:19'),
(16651, 2826, 1, '(١ علامة) أ- يتحدّد دور كلّ وسيلة إعلاميّة بأمرين: درجة توسّعها داخل المجتمع، وهامش الخيار الذاتي في التعامل معها. (١ علامة) ب- لأنّ المتلقّي يحدّد العرض مسبقاً، ويذهب إلى المكان، ويدفع ثمن البطاقة، فكلّما زاد الخيار الذاتي صار التلقّي إرادياً أكثر. (١ علامة) ج- لأنّ من يريد الالتزام بحزب يختاره أوّلاً ويتوجّه نحوه، ثمّ يتولّى الحزب بدوره قبول انتسابه أو رفضه؛ لذلك تشكّل الأحزاب أطراً أكثر نخبويّة وتمايزاً، أمّا وسائل الإعلام فوسيط جماهيري بمتناول أوسع الفئات.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16652, 2826, 2, '(١ علامة) أ- يتحدّد دور كلّ وسيلة إعلاميّة بأمرين: درجة توسّعها داخل المجتمع، وهامش الخيار الذاتي في التعامل معها. (١ علامة) ب- لأنّ المتلقّي يحدّد العرض مسبقاً، ويذهب إلى المكان، ويدفع ثمن البطاقة، فكلّما زاد الخيار الذاتي صار التلقّي إرادياً أكثر. (١ علامة) ج- لأنّ من يريد الالتزام بحزب يختاره أوّلاً ويتوجّه نحوه، ثمّ يتولّى الحزب بدوره قبول انتسابه أو رفضه؛ لذلك تشكّل الأحزاب أطراً أكثر نخبويّة وتمايزاً، أمّا وسائل الإعلام فوسيط جماهيري بمتناول أوسع الفئات.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16653, 2828, 1, '(١ علامة) أ- الخاصّيّة هي اللغة الخاصّة بالمراهقين: يبتكر المراهق لغة اتصال خاصّة به، لها مفرداتها ورموزها. (١ علامة) ب- تصبح هذه اللغة أداة اتصال فيما بين المراهقين، ولا يفهمها الآخرون، وخصوصاً الكبار. (١ علامة) ج- انقطاع التواصل: يعزل المراهق نفسه عن محيطه ويقطع الحوار، فيتوقّف عن استيعاب ما يُعرض عليه.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16654, 2828, 2, '(١ علامة) أ- الخاصّيّة هي اللغة الخاصّة بالمراهقين: يبتكر المراهق لغة اتصال خاصّة به، لها مفرداتها ورموزها. (١ علامة) ب- تصبح هذه اللغة أداة اتصال فيما بين المراهقين، ولا يفهمها الآخرون، وخصوصاً الكبار. (١ علامة) ج- انقطاع التواصل: يعزل المراهق نفسه عن محيطه ويقطع الحوار، فيتوقّف عن استيعاب ما يُعرض عليه.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16655, 2827, 1, '(١ علامة) التنشئة الاجتماعيّة هي تلقّي قواعد الحياة الفرديّة ومعاييرها، أي عمليّة تعليم وإقناع تدريجي بأهمّيّة الأنماط الثقافيّة وجدواها، فيعمل بها الإنسان بقناعة تامّة، لا طمعاً في مكافأة ولا خوفاً من عقاب. (١ علامة) الرقابة الاجتماعيّة آليّات يراقب بها المجتمع امتثال الأفراد والجماعات لأنماطه الثقافيّة، وتقوم على مبدأ الثواب والعقاب: يكافئ المجتمع السلوك القويم المطابق للقواعد ويدين الانحراف عنها، بهدف المحافظة على تماسك النسيج الاجتماعي وحيويّته. (١ علامة) لا تستطيع المجتمعات أن تتقدّم وتتجدّد بالتكرار الدائم للتنشئة الاجتماعيّة وبالرقابة الصارمة؛ فالتجدّد سيرورة طويلة تبدأ بنشوء فئات تنتقد القيم والأفكار السائدة، ثمّ تتغلغل القيم الجديدة، ثمّ تثبت تدريجياً قيماً سائدة ومقبولة.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16656, 2827, 2, '(١ علامة) التنشئة الاجتماعيّة هي تلقّي قواعد الحياة الفرديّة ومعاييرها، أي عمليّة تعليم وإقناع تدريجي بأهمّيّة الأنماط الثقافيّة وجدواها، فيعمل بها الإنسان بقناعة تامّة، لا طمعاً في مكافأة ولا خوفاً من عقاب. (١ علامة) الرقابة الاجتماعيّة آليّات يراقب بها المجتمع امتثال الأفراد والجماعات لأنماطه الثقافيّة، وتقوم على مبدأ الثواب والعقاب: يكافئ المجتمع السلوك القويم المطابق للقواعد ويدين الانحراف عنها، بهدف المحافظة على تماسك النسيج الاجتماعي وحيويّته. (١ علامة) لا تستطيع المجتمعات أن تتقدّم وتتجدّد بالتكرار الدائم للتنشئة الاجتماعيّة وبالرقابة الصارمة؛ فالتجدّد سيرورة طويلة تبدأ بنشوء فئات تنتقد القيم والأفكار السائدة، ثمّ تتغلغل القيم الجديدة، ثمّ تثبت تدريجياً قيماً سائدة ومقبولة.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16657, 2829, 1, '(١ علامة) أ- في المشاغل الصغيرة والمؤسّسات الحرفيّة تحدّد المهارة والخبرة والتجربة المركز العملي. (١ علامة) ب- يولّد الشعور بالتهميش ردّة فعل، فيكتشف رامي أهمّيّة التواصل مع زملائه وينشأ لديه الشعور التضامني؛ ويشارك في إدارة الصراع عبر النقابة، وهي هيئة منتخبة للعاملين يتقوّى بها الفرد في مهنته.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16658, 2829, 2, '(١ علامة) أ- في المشاغل الصغيرة والمؤسّسات الحرفيّة تحدّد المهارة والخبرة والتجربة المركز العملي. (١ علامة) ب- يولّد الشعور بالتهميش ردّة فعل، فيكتشف رامي أهمّيّة التواصل مع زملائه وينشأ لديه الشعور التضامني؛ ويشارك في إدارة الصراع عبر النقابة، وهي هيئة منتخبة للعاملين يتقوّى بها الفرد في مهنته.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16659, 2830, 1, '(١ علامة) النمط الجانح: لم ينجح في تطوير معاييره الأخلاقيّة ولا في بناء الضمير الحيّ، فتتّسم علاقته بالآخرين بالبرودة وعدم الاكتراث، وتدفع تصرّفاته مشاعر العدوانيّة وإلحاق الأذى بالآخر. (١ علامة) الشخصيّة المضادّة للمجتمع: فرد غير متكيّف اجتماعياً يقوده سلوكه إلى الصدام مع المجتمع، عاجز عن إظهار الولاء للآخرين أو للجماعات أو للقيم الاجتماعية، ويمتاز بالأنانية المفرطة والاندفاعية، وبالعجز عن الشعور بالذنب، وبالقسوة. (١ علامة) وجه الشبه (يُقبل أحدها): غياب الضمير الحيّ عند الجانح يقابله العجز عن الشعور بالذنب عند الشخصيّة المضادّة للمجتمع؛ أو العدوانيّة وإلحاق الأذى بالآخر يقابلهما القسوة؛ أو البرودة وعدم الاكتراث بالآخرين يقابلهما العجز عن إظهار الولاء للآخرين.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16660, 2830, 2, '(١ علامة) النمط الجانح: لم ينجح في تطوير معاييره الأخلاقيّة ولا في بناء الضمير الحيّ، فتتّسم علاقته بالآخرين بالبرودة وعدم الاكتراث، وتدفع تصرّفاته مشاعر العدوانيّة وإلحاق الأذى بالآخر. (١ علامة) الشخصيّة المضادّة للمجتمع: فرد غير متكيّف اجتماعياً يقوده سلوكه إلى الصدام مع المجتمع، عاجز عن إظهار الولاء للآخرين أو للجماعات أو للقيم الاجتماعية، ويمتاز بالأنانية المفرطة والاندفاعية، وبالعجز عن الشعور بالذنب، وبالقسوة. (١ علامة) وجه الشبه (يُقبل أحدها): غياب الضمير الحيّ عند الجانح يقابله العجز عن الشعور بالذنب عند الشخصيّة المضادّة للمجتمع؛ أو العدوانيّة وإلحاق الأذى بالآخر يقابلهما القسوة؛ أو البرودة وعدم الاكتراث بالآخرين يقابلهما العجز عن إظهار الولاء للآخرين.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16661, 2831, 1, '(١ علامة) روح المبادرة: يعلم التلميذ أنّ المبادرات الحسنة تُكافأ. (١ علامة) الإخلاص والخدمة: يدرك التلميذ أنّ عليه القيام بأعمال دون مقابل، وفق نظام القيم الذي يتلقّنه، وهنا يبدأ بترجمة ما اكتسبه في المنزل إلى حياته الاجتماعيّة.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16662, 2831, 2, '(١ علامة) روح المبادرة: يعلم التلميذ أنّ المبادرات الحسنة تُكافأ. (١ علامة) الإخلاص والخدمة: يدرك التلميذ أنّ عليه القيام بأعمال دون مقابل، وفق نظام القيم الذي يتلقّنه، وهنا يبدأ بترجمة ما اكتسبه في المنزل إلى حياته الاجتماعيّة.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16663, 2832, 1, '(١ علامة) أ- فقدان أحد الأبوين، ونبذ الطفل نبذاً قاسياً (أو: فقدان الحبّ والتعاطف، أو عدم اتّباع طرائق سليمة في التأديب وفي تعليم الأولاد تحمّل المسؤولية)؛ ويكفي ذكر عاملين. (١ علامة) ب- مثلاً: الاكتشاف المبكر، لأنّ الفرد لا يصبح منحرفاً بين عشيّة وضحاها، والكذب والتأخّر في العودة إلى المنزل إشارات أولى يمكن معالجتها مبكراً؛ أو: توفير جوّ عاطفي صحّي وعلاقات ودّية، لأنّ النبذ وفقدان الحبّ من أسباب السلوك المضادّ للمجتمع. تُقبل أيّ وسيلة من الدرس مع تعليل صحيح.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16664, 2832, 2, '(١ علامة) أ- فقدان أحد الأبوين، ونبذ الطفل نبذاً قاسياً (أو: فقدان الحبّ والتعاطف، أو عدم اتّباع طرائق سليمة في التأديب وفي تعليم الأولاد تحمّل المسؤولية)؛ ويكفي ذكر عاملين. (١ علامة) ب- مثلاً: الاكتشاف المبكر، لأنّ الفرد لا يصبح منحرفاً بين عشيّة وضحاها، والكذب والتأخّر في العودة إلى المنزل إشارات أولى يمكن معالجتها مبكراً؛ أو: توفير جوّ عاطفي صحّي وعلاقات ودّية، لأنّ النبذ وفقدان الحبّ من أسباب السلوك المضادّ للمجتمع. تُقبل أيّ وسيلة من الدرس مع تعليل صحيح.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16665, 2833, 1, '(١ علامة) المدرسة البيولوجيّة: تنتهي المراهقة حين تكتمل الخصائص البيولوجيّة المطلوبة للإنجاب، فتتوقّف عندها التحوّلات الأساسيّة وردود الفعل النفسيّة عليها. (١ علامة) المدرسة المجتمعيّة: تربط نهاية المراهقة بسنّ البلوغ القانوني، وأغلب المجتمعات تحدّدها بالثامنة عشرة، وهي سنّ المسؤوليّة الجزائيّة وحقّ الاقتراع.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16666, 2833, 2, '(١ علامة) المدرسة البيولوجيّة: تنتهي المراهقة حين تكتمل الخصائص البيولوجيّة المطلوبة للإنجاب، فتتوقّف عندها التحوّلات الأساسيّة وردود الفعل النفسيّة عليها. (١ علامة) المدرسة المجتمعيّة: تربط نهاية المراهقة بسنّ البلوغ القانوني، وأغلب المجتمعات تحدّدها بالثامنة عشرة، وهي سنّ المسؤوليّة الجزائيّة وحقّ الاقتراع.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16667, 2834, 1, '(١ علامة) يلجأ الطفل إلى العدوانيّة ليواجه صعوبات الحياة ويلفت الاهتمام، ثمّ يصطدم بقواعد المجتمع كلّما كبر. (١ علامة) إذا نجحت التنشئة يتكيّف مع قواعد المجتمع ويثق بالغير ويواجه النزاعات بالحوار واللاعنف؛ وإذا فشلت تتأصّل فيه النزعات العدوانيّة ويصبح العنف وسيلته الوحيدة، فيخلّ بنظام المجتمع ويتعدّى على القانون. (١ علامة) العنف الكلاميّ كالكلام البذيء والشتائم؛ والعنف المادّيّ كالضرب والإيذاء الجسديّ والقتل والتهديد والتعذيب؛ والعنف الذاتيّ كالانتحار وإدمان المخدّرات.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16668, 2834, 2, '(١ علامة) يلجأ الطفل إلى العدوانيّة ليواجه صعوبات الحياة ويلفت الاهتمام، ثمّ يصطدم بقواعد المجتمع كلّما كبر. (١ علامة) إذا نجحت التنشئة يتكيّف مع قواعد المجتمع ويثق بالغير ويواجه النزاعات بالحوار واللاعنف؛ وإذا فشلت تتأصّل فيه النزعات العدوانيّة ويصبح العنف وسيلته الوحيدة، فيخلّ بنظام المجتمع ويتعدّى على القانون. (١ علامة) العنف الكلاميّ كالكلام البذيء والشتائم؛ والعنف المادّيّ كالضرب والإيذاء الجسديّ والقتل والتهديد والتعذيب؛ والعنف الذاتيّ كالانتحار وإدمان المخدّرات.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16669, 2835, 1, '(١ علامة) مستوى العائلة: الطلاق وغياب أحد الوالدين والإهمال. (١ علامة) مستوى المجتمع: مشاكل الأحياء المهمّشة وغياب أماكن التسلية والرياضة. (١ علامة) من عناصر السياسة الوقائيّة العامّة (عنصران): المسكن اللائق، فرص العمل، التعليم، الخدمات الصحّيّة والاجتماعيّة، مجال الترفيه، التربية المدنيّة. (١ علامة) العائلة هي العامل الأوّل والأساسيّ في الرقابة الاجتماعيّة لأنّها المكان الأفضل ليتعلّم الناشئ كيف يحترم الأنظمة ويتقيّد بها.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16670, 2835, 2, '(١ علامة) مستوى العائلة: الطلاق وغياب أحد الوالدين والإهمال. (١ علامة) مستوى المجتمع: مشاكل الأحياء المهمّشة وغياب أماكن التسلية والرياضة. (١ علامة) من عناصر السياسة الوقائيّة العامّة (عنصران): المسكن اللائق، فرص العمل، التعليم، الخدمات الصحّيّة والاجتماعيّة، مجال الترفيه، التربية المدنيّة. (١ علامة) العائلة هي العامل الأوّل والأساسيّ في الرقابة الاجتماعيّة لأنّها المكان الأفضل ليتعلّم الناشئ كيف يحترم الأنظمة ويتقيّد بها.', 1, '2026-09-30 22:54:20', '2026-09-30 22:54:20'),
(16671, 2836, 1, '(١ علامة) في أوروبا: فكّكت الثورة الصناعيّة العائلة الريفيّة التقليديّة، ودفعت أفواج الشباب إلى المدن طلباً للعمل. (١ علامة) في مجتمعاتنا: أدّت الصدمة مع الحداثة الأوروبيّة، والعلاقات غير المتكافئة مع العالم الصناعيّ، أي الحركة الاستعماريّة، إلى طرح موضوع تنظيم الشباب لمواجهة التحدّيات الجديدة. (١ علامة) في بعض الأنظمة: أرادت الدولة (الإرادة العليا للدولة) أن تجمع الشباب في تنظيم واحد إجباريّ يكون قوّة مساندة لأجهزة النظام ومجالاً لنشر عقيدته بين الأجيال الطالعة.', 1, '2026-09-30 22:54:21', '2026-09-30 22:54:21'),
(16672, 2836, 2, '(١ علامة) في أوروبا: فكّكت الثورة الصناعيّة العائلة الريفيّة التقليديّة، ودفعت أفواج الشباب إلى المدن طلباً للعمل. (١ علامة) في مجتمعاتنا: أدّت الصدمة مع الحداثة الأوروبيّة، والعلاقات غير المتكافئة مع العالم الصناعيّ، أي الحركة الاستعماريّة، إلى طرح موضوع تنظيم الشباب لمواجهة التحدّيات الجديدة. (١ علامة) في بعض الأنظمة: أرادت الدولة (الإرادة العليا للدولة) أن تجمع الشباب في تنظيم واحد إجباريّ يكون قوّة مساندة لأجهزة النظام ومجالاً لنشر عقيدته بين الأجيال الطالعة.', 1, '2026-09-30 22:54:21', '2026-09-30 22:54:21'),
(16673, 2837, 1, '(١ علامة) أ- يشير النصّ إلى تحشيد المدن، أي تدفّق موجات من السكان على المدن وضواحيها لم يكن مخطّطاً لها أن تستوعبها. (١ علامة) ب- التمهيد لاضطرابات أمنية، والتمهيد لظواهر انحراف كالإدمان والتفكّك. (١ علامة) ج- تجذب الحركات المتطرّفة الطبقات الشعبيّة التي تعاني الانهزام أو التهميش أكثر من غيرها، ويزيد التهميش من ظهورها؛ والمحتشدون في الضواحي يعيشون التهميش والنقمة على امتيازات الأحياء الأخرى، فتجد فيهم هذه الحركات بيئة ملائمة وتقدّم نفسها كمنقذة.', 1, '2026-09-30 22:54:21', '2026-09-30 22:54:21'),
(16674, 2837, 2, '(١ علامة) أ- يشير النصّ إلى تحشيد المدن، أي تدفّق موجات من السكان على المدن وضواحيها لم يكن مخطّطاً لها أن تستوعبها. (١ علامة) ب- التمهيد لاضطرابات أمنية، والتمهيد لظواهر انحراف كالإدمان والتفكّك. (١ علامة) ج- تجذب الحركات المتطرّفة الطبقات الشعبيّة التي تعاني الانهزام أو التهميش أكثر من غيرها، ويزيد التهميش من ظهورها؛ والمحتشدون في الضواحي يعيشون التهميش والنقمة على امتيازات الأحياء الأخرى، فتجد فيهم هذه الحركات بيئة ملائمة وتقدّم نفسها كمنقذة.', 1, '2026-09-30 22:54:21', '2026-09-30 22:54:21'),
(16675, 2838, 1, 'أ- (١ علامة) هو تفسير غير علمي (خرافي) يقوم على نظرة انفعالية خيالية تردّ أسباب الظواهر إلى اعتقادات خرافية، كتفسير خسوف القمر بتنّين أو حوت يحاول ابتلاعه، والأمراض بغضب الآلهة أو دخول روح الشرّ. ب- (١ علامة) تخلّى الإنسان عن هذه التفسيرات البدائية وبحث عن الأسباب الحقيقية للظواهر بأساليب علمية (التفسير العلمي). ج- (١ علامة) أصبحت هذه الاعتقادات الخرافية نفسها مادّة للدراسة.', 1, '2026-09-30 22:54:21', '2026-09-30 22:54:21'),
(16676, 2838, 2, 'أ- (١ علامة) هو تفسير غير علمي (خرافي) يقوم على نظرة انفعالية خيالية تردّ أسباب الظواهر إلى اعتقادات خرافية، كتفسير خسوف القمر بتنّين أو حوت يحاول ابتلاعه، والأمراض بغضب الآلهة أو دخول روح الشرّ. ب- (١ علامة) تخلّى الإنسان عن هذه التفسيرات البدائية وبحث عن الأسباب الحقيقية للظواهر بأساليب علمية (التفسير العلمي). ج- (١ علامة) أصبحت هذه الاعتقادات الخرافية نفسها مادّة للدراسة.', 1, '2026-09-30 22:54:21', '2026-09-30 22:54:21'),
(16677, 2839, 1, 'أ- (١ علامة) ترتبط بمجال التربية. (١ علامة) تبيّن الدراسات الاجتماعية مدى مطابقة المناهج التربوية للحاجات الاجتماعية والاقتصادية للسكّان، فتوجّه تطوير المناهج وإصلاحها، وتشكّل أساساً للتخطيط التربوي الهادف إلى تأمين المستلزمات التعليمية بشكل مدروس ومتناسب مع الحاجات. ب- (١ علامة) طريقة أولى مع تعريفها، و(١ علامة) طريقة ثانية مع تعريفها، من بين: الملاحظة العيانية: المشاهدة بالعين ثمّ وصف الوقائع والسلوكيات في الحياة اليومية وعند اتّخاذ القرارات؛ التوثيق: جمع المعلومات من مصادرها كالكتب والمجلّات والنشرات ومن دراسات مشابهة؛ الإحصاء: استعمال المعلومات الرقمية التي تكشف مدى تكرار الظاهرة (شامل يتناول كلّ الحالات، أو بالعيّنة يختار نسبة منها بشكل عشوائي).', 1, '2026-09-30 22:54:22', '2026-09-30 22:54:22'),
(16678, 2839, 2, 'أ- (١ علامة) ترتبط بمجال التربية. (١ علامة) تبيّن الدراسات الاجتماعية مدى مطابقة المناهج التربوية للحاجات الاجتماعية والاقتصادية للسكّان، فتوجّه تطوير المناهج وإصلاحها، وتشكّل أساساً للتخطيط التربوي الهادف إلى تأمين المستلزمات التعليمية بشكل مدروس ومتناسب مع الحاجات. ب- (١ علامة) طريقة أولى مع تعريفها، و(١ علامة) طريقة ثانية مع تعريفها، من بين: الملاحظة العيانية: المشاهدة بالعين ثمّ وصف الوقائع والسلوكيات في الحياة اليومية وعند اتّخاذ القرارات؛ التوثيق: جمع المعلومات من مصادرها كالكتب والمجلّات والنشرات ومن دراسات مشابهة؛ الإحصاء: استعمال المعلومات الرقمية التي تكشف مدى تكرار الظاهرة (شامل يتناول كلّ الحالات، أو بالعيّنة يختار نسبة منها بشكل عشوائي).', 1, '2026-09-30 22:54:22', '2026-09-30 22:54:22'),
(16679, 2840, 1, '(١ علامة) نظرية الدولة الراعية (سيطرت منذ الحرب العالمية الثانية): تتدخّل الدولة ببرامج مباشرة للتشغيل والإنفاق، وببرامج للحماية الصحية والتعليمية، لتحمي القدرة الشرائية للمواطنين. (١ علامة) نظرية اقتصاد السوق (حلّت محلّها منذ منتصف السبعينات): يصير دور الدولة حماية قوانين السوق الحرّة، وتتراجع الحماية الاجتماعية، أوّلاً في الدول الغنية ثمّ في البلدان النامية الفقيرة. (١ علامة) نظرية الدولة الراعية أقرب، لأنّ درس الفقر يطلب من الدولة أن ترسم سياسة اقتصادية أكثر توازناً في توزيع الدخل، وسياسة اجتماعية أكثر توازناً في توافر الخدمات التربوية والصحية والإسكانية، وهذا تدخّل مباشر من الدولة لا اكتفاء بحماية قوانين السوق.', 1, '2026-09-30 22:54:22', '2026-09-30 22:54:22');
