(18093, 3547, 1, '(علامة ونصف) نصف علامة لكلّ مرحلة: سنة ١٩٢٠: حلّ غورو مجلس إدارة المتصرّفيّة وعيّن لجنة إداريّة من ١٧ عضواً – سنة ١٩٢٢: حلّ غورو اللجنة وأجرى اقتراعاً على درجتين أُنشئ على أثره مجلس تمثيلي من ٣٠ عضواً – سنة ١٩٢٥: حلّ سراي هذا المجلس، وانتخب اللبنانيّون مجلساً من ٣٠ عضواً تحوّل إلى مجلس تأسيسي وضع الدستور وعُرف بمجلس النوّاب.', 1, '2026-10-01 01:33:03', '2026-10-01 01:33:03'),
(18094, 3547, 2, '(علامة ونصف) نصف علامة لكلّ مرحلة: سنة ١٩٢٠: حلّ غورو مجلس إدارة المتصرّفيّة وعيّن لجنة إداريّة من ١٧ عضواً – سنة ١٩٢٢: حلّ غورو اللجنة وأجرى اقتراعاً على درجتين أُنشئ على أثره مجلس تمثيلي من ٣٠ عضواً – سنة ١٩٢٥: حلّ سراي هذا المجلس، وانتخب اللبنانيّون مجلساً من ٣٠ عضواً تحوّل إلى مجلس تأسيسي وضع الدستور وعُرف بمجلس النوّاب.', 1, '2026-10-01 01:33:03', '2026-10-01 01:33:03'),
(18095, 3548, 1, '(علامتان) نصف علامة لكلّ إجراء: تعليق الدستور – إقالة الحكومة وتعيين مجلس مديرين برئاسة عبدالله بيهم مع الإبقاء على إميل إدّه رئيساً للجمهوريّة – إعلان الأحكام العرفيّة – حلّ الأحزاب وملاحقة زعمائها ولا سيّما الحزب الشيوعي والحزب السوري القومي – مراقبة الصحافة ومنع بعضها من الصدور – منع الاجتماعات السياسيّة – إشراف الفرنسيّين على دوائر الدولة – صدور المراسيم بتوقيع رئيس الدولة ومصادقة المفوّض السامي.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18096, 3548, 2, '(علامتان) نصف علامة لكلّ إجراء: تعليق الدستور – إقالة الحكومة وتعيين مجلس مديرين برئاسة عبدالله بيهم مع الإبقاء على إميل إدّه رئيساً للجمهوريّة – إعلان الأحكام العرفيّة – حلّ الأحزاب وملاحقة زعمائها ولا سيّما الحزب الشيوعي والحزب السوري القومي – مراقبة الصحافة ومنع بعضها من الصدور – منع الاجتماعات السياسيّة – إشراف الفرنسيّين على دوائر الدولة – صدور المراسيم بتوقيع رئيس الدولة ومصادقة المفوّض السامي.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18097, 3549, 1, '(علامة واحدة) نصف علامة لكلّ تدبير: مكافحة الاحتكار – مراقبة الأسعار – الإشراف على بعض الصناعات المحلّيّة – تأمين بعض المواد الغذائيّة ووضع نظام الإعاشة.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18098, 3549, 2, '(علامة واحدة) نصف علامة لكلّ تدبير: مكافحة الاحتكار – مراقبة الأسعار – الإشراف على بعض الصناعات المحلّيّة – تأمين بعض المواد الغذائيّة ووضع نظام الإعاشة.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18099, 3550, 1, '(علامتان) علامة واحدة لكلّ خطوة مشروحة: عدم زيارة المفوّض السامي عند تأليفها واعتبار المندوب الفرنسي سفيراً كغيره من السفراء – إيجاب استعمال العربيّة في كلّ المعاملات وفي أوامر الحرس والدرك – تحديد البيان الوزاري دون إطلاع الفرنسيّين عليه قبل عرضه على المجلس النيابي – المطالبة في ٢٠ تشرين الأوّل باستلام المصالح ورفض عقد أيّ معاهدة قبل الاستقلال الناجز.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18100, 3550, 2, '(علامتان) علامة واحدة لكلّ خطوة مشروحة: عدم زيارة المفوّض السامي عند تأليفها واعتبار المندوب الفرنسي سفيراً كغيره من السفراء – إيجاب استعمال العربيّة في كلّ المعاملات وفي أوامر الحرس والدرك – تحديد البيان الوزاري دون إطلاع الفرنسيّين عليه قبل عرضه على المجلس النيابي – المطالبة في ٢٠ تشرين الأوّل باستلام المصالح ورفض عقد أيّ معاهدة قبل الاستقلال الناجز.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18101, 3551, 1, '1) First pass, the shape: read quickly once and find the one sentence that carries each paragraph. 2) Second pass, the joints: find and mark the places where the text turns. 3) Third pass, question by question, already knowing where each answer lives in the text.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(18102, 3551, 2, '1) First pass, the shape: read quickly once and find the one sentence that carries each paragraph. 2) Second pass, the joints: find and mark the places where the text turns. 3) Third pass, question by question, already knowing where each answer lives in the text.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
(18103, 3552, 1, 'The exam passage (about 45 lines, on a theme from your curriculum) is one you have never seen, on purpose, so you cannot study it in advance. The only thing left to study is the method, and a weak reader with a method beats a strong reader without one.', 1, '2026-10-01 01:33:10', '2026-10-01 01:33:10'),
