(18991, 3996, 1, 'المجموعة الأولى (شروط اقتصاديّة واجتماعيّة): العمل براتب محدّد ودوام محدّد – الدخول إلى نقابات تدافع عن مصالح العمّال. (٠٫٥٠)\nالمجموعة الثانية (شروط سياسيّة): حرّيّة الترشّح والانتخاب – حرّيّة الإعلام والتعبير والنشر. (٠٫٥٠)\nالتبرير: الأولى تؤمّن للعامل استقرار موقعه ومن يدافع عن مصالحه (٠٫٢٥)، والثانية من شروط الديمقراطيّة: كلّما زادت الديمقراطيّة زادت المشاركة وتحقّق الاندماج. (٠٫٢٥)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(18992, 3996, 2, 'المجموعة الأولى (شروط اقتصاديّة واجتماعيّة): العمل براتب محدّد ودوام محدّد – الدخول إلى نقابات تدافع عن مصالح العمّال. (٠٫٥٠)\nالمجموعة الثانية (شروط سياسيّة): حرّيّة الترشّح والانتخاب – حرّيّة الإعلام والتعبير والنشر. (٠٫٥٠)\nالتبرير: الأولى تؤمّن للعامل استقرار موقعه ومن يدافع عن مصالحه (٠٫٢٥)، والثانية من شروط الديمقراطيّة: كلّما زادت الديمقراطيّة زادت المشاركة وتحقّق الاندماج. (٠٫٢٥)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(18993, 3997, 1, 'أ- مع الأهالي: الاستمارة (٠٫٢٥)، لأنّها توجَّه بأسئلة مرقّمة مغلقة إلى أفراد العيّنة فتجمع آراء عدد كبير منهم (٠٫٢٥). مع رئيس البلديّة: المقابلة (٠٫٢٥)، لأنّها لفرد واحد وأسئلتها مفتوحة تتيح له الإجابة بحرّيّة. (٠٫٢٥)\nب- مثال: كيف تقيّم الخدمات الصحّيّة المتوافرة في منطقتك؟ □ كافية □ كافية إلى حدّ ما □ غير كافية. (صياغة بأداة مسموح بها ٠٫٥٠، الخيارات ٠٫٥٠)\nج- العيّنة العشوائيّة. (٠٫٥٠)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(18994, 3997, 2, 'أ- مع الأهالي: الاستمارة (٠٫٢٥)، لأنّها توجَّه بأسئلة مرقّمة مغلقة إلى أفراد العيّنة فتجمع آراء عدد كبير منهم (٠٫٢٥). مع رئيس البلديّة: المقابلة (٠٫٢٥)، لأنّها لفرد واحد وأسئلتها مفتوحة تتيح له الإجابة بحرّيّة. (٠٫٢٥)\nب- مثال: كيف تقيّم الخدمات الصحّيّة المتوافرة في منطقتك؟ □ كافية □ كافية إلى حدّ ما □ غير كافية. (صياغة بأداة مسموح بها ٠٫٥٠، الخيارات ٠٫٥٠)\nج- العيّنة العشوائيّة. (٠٫٥٠)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(18995, 3998, 1, 'المقدّمة (٣ علامات): المنهجيّة ١٫٥٠ (حسن التمهيد، طرح الإشكاليّة بصيغة سؤال، الإعلان عن التصميم). أهمّيّة الموضوع: القيم ميزان تزن به الجماعة سلوك أفرادها، وهي متنقّلة ومتغيّرة (٠٫٥٠)؛ الإطار: المجتمع اللبنانيّ حاليّاً (٠٫٢٥)؛ الإشكاليّة: كيف يمكن للمجتمع اللبنانيّ أن يواجه اختبار القيم من دون أن يفقد قيمه المحلّيّة؟ (٠٫٥٠)؛ التصميم (٠٫٢٥).\nجسم الموضوع (٧ علامات): المنهجيّة ٢ (معالجة النقاط الأربع بالترتيب، الربط بالمستند وبالمعلومات المكتسبة، تسلسل الأفكار وسلامة اللغة). النقطة ١ (١): القيم في نظر عالم الاجتماع مكتسبة من البيئة التي يعيش فيها الفرد، تحدّد سلوكه ومجالات تفكيره (٠٫٢٥)؛ اختبار القيم هو الصراع بين القيم المحلّيّة والقيم الوافدة، وهو يولّد تبايناً في المواقف (٠٫٢٥)؛ العلاقة: لأنّ القيم متنقّلة ومتغيّرة تدخل قيم من الخارج فتصطدم بالقيم المحلّيّة (٠٫٥٠).\nالنقطة ٢ (١٫٥٠): من الداخل: العائلة (الطاعة والامتثال واحترام الرأي)، المدرسة (المعرفة وروح الانتماء واحترام القواعد)، أو الحيّ أو الدين (٠٫٧٥)؛ من الخارج: وسائل الاتّصال (قيم مغايرة)، المقاهي والمسارح ودور السينما (قيم فنّيّة وترفيهيّة)، الشركات (قيمة الربح)، المدارس والجامعات الأجنبيّة (٠٫٧٥).\nالنقطة ٣ (١): المسنّون يرفضون القيم الوافدة ويتمسّكون بالتراث، والشباب يتلقّون الجديد (٠٫٥٠)؛ التلقّي عند أهل المدينة أسرع منه عند أهل الريف (٠٫٥٠).\nالنقطة ٤ (١٫٥٠): ثلاثة اقتراحات، ٠٫٥٠ لكلّ منها، مثل: تفعيل دور العائلة في الحوار مع الأبناء – تعزيز دور المدرسة في ترسيخ روح الانتماء واحترام القواعد – تفعيل دور الحيّ والدين في نقل قيم الكرم والضيافة والمغفرة والمحبّة والتسامح.\nالخاتمة (علامتان): المنهجيّة ٠٫٥٠. تلخيص والإجابة عن الإشكاليّة: لا يُواجَه اختبار القيم بالانغلاق بل بتفعيل مؤسّسات الداخل والانفتاح الواعي (١)؛ فتح آفاق: كيف يمكن الحدّ من أثر وسائل الاتّصال في تغيّر القيم لدى الشباب؟ (٠٫٥٠)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(18996, 3998, 2, 'المقدّمة (٣ علامات): المنهجيّة ١٫٥٠ (حسن التمهيد، طرح الإشكاليّة بصيغة سؤال، الإعلان عن التصميم). أهمّيّة الموضوع: القيم ميزان تزن به الجماعة سلوك أفرادها، وهي متنقّلة ومتغيّرة (٠٫٥٠)؛ الإطار: المجتمع اللبنانيّ حاليّاً (٠٫٢٥)؛ الإشكاليّة: كيف يمكن للمجتمع اللبنانيّ أن يواجه اختبار القيم من دون أن يفقد قيمه المحلّيّة؟ (٠٫٥٠)؛ التصميم (٠٫٢٥).\nجسم الموضوع (٧ علامات): المنهجيّة ٢ (معالجة النقاط الأربع بالترتيب، الربط بالمستند وبالمعلومات المكتسبة، تسلسل الأفكار وسلامة اللغة). النقطة ١ (١): القيم في نظر عالم الاجتماع مكتسبة من البيئة التي يعيش فيها الفرد، تحدّد سلوكه ومجالات تفكيره (٠٫٢٥)؛ اختبار القيم هو الصراع بين القيم المحلّيّة والقيم الوافدة، وهو يولّد تبايناً في المواقف (٠٫٢٥)؛ العلاقة: لأنّ القيم متنقّلة ومتغيّرة تدخل قيم من الخارج فتصطدم بالقيم المحلّيّة (٠٫٥٠).\nالنقطة ٢ (١٫٥٠): من الداخل: العائلة (الطاعة والامتثال واحترام الرأي)، المدرسة (المعرفة وروح الانتماء واحترام القواعد)، أو الحيّ أو الدين (٠٫٧٥)؛ من الخارج: وسائل الاتّصال (قيم مغايرة)، المقاهي والمسارح ودور السينما (قيم فنّيّة وترفيهيّة)، الشركات (قيمة الربح)، المدارس والجامعات الأجنبيّة (٠٫٧٥).\nالنقطة ٣ (١): المسنّون يرفضون القيم الوافدة ويتمسّكون بالتراث، والشباب يتلقّون الجديد (٠٫٥٠)؛ التلقّي عند أهل المدينة أسرع منه عند أهل الريف (٠٫٥٠).\nالنقطة ٤ (١٫٥٠): ثلاثة اقتراحات، ٠٫٥٠ لكلّ منها، مثل: تفعيل دور العائلة في الحوار مع الأبناء – تعزيز دور المدرسة في ترسيخ روح الانتماء واحترام القواعد – تفعيل دور الحيّ والدين في نقل قيم الكرم والضيافة والمغفرة والمحبّة والتسامح.\nالخاتمة (علامتان): المنهجيّة ٠٫٥٠. تلخيص والإجابة عن الإشكاليّة: لا يُواجَه اختبار القيم بالانغلاق بل بتفعيل مؤسّسات الداخل والانفتاح الواعي (١)؛ فتح آفاق: كيف يمكن الحدّ من أثر وسائل الاتّصال في تغيّر القيم لدى الشباب؟ (٠٫٥٠)', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
(18997, 3999, 1, 'أ- القياس السوسيومتريّ. (٠٫٥٠)\nب- التفاعل الثقافيّ (التثاقف أو المثاقفة). (٠٫٥٠)\nج- شبكة الأمان الاجتماعيّ. (٠٫٥٠)\nكلّ مصطلح ٠٫٥٠ — المجموع ١٫٥٠.', 1, '2026-10-01 02:33:09', '2026-10-01 02:33:09'),
