(19003, 4002, 1, 'المجموعة الأولى: الضبط والتوازن – رصد الموارد العامّة. (٠٫٥٠)\nالمجموعة الثانية: التخفيف من الحاجة والعوز – ترسيخ الوحدة الوطنيّة. (٠٫٥٠)\nالتبرير: الأولى وظائف تقوم بها دولة العناية (٠٫٢٥)، والثانية أهداف يسعى إليها الضمان الاجتماعيّ. (٠٫٢٥)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
(19004, 4002, 2, 'المجموعة الأولى: الضبط والتوازن – رصد الموارد العامّة. (٠٫٥٠)\nالمجموعة الثانية: التخفيف من الحاجة والعوز – ترسيخ الوحدة الوطنيّة. (٠٫٥٠)\nالتبرير: الأولى وظائف تقوم بها دولة العناية (٠٫٢٥)، والثانية أهداف يسعى إليها الضمان الاجتماعيّ. (٠٫٢٥)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
(19005, 4003, 1, 'أ- الاستمارة (٠٫٢٥)، لأنّها توجَّه إلى أفراد العيّنة بأسئلة مرقّمة مغلقة فتعطي اتّساعاً: عدداً كبيراً من الأجوبة القابلة للعدّ والمقارنة. (٠٫٥٠)\nب- مثال: ما المدّة التي تقضيها يوميّاً في متابعة محتوى من بلدان أخرى؟ □ أقلّ من ساعة □ من ساعة إلى ثلاث ساعات □ أكثر من ثلاث ساعات. (صياغة ٠٫٢٥، الخيارات ٠٫٥٠) — نوع التحليل: الكمّيّ. (٠٫٥٠)\nج- المرحلة الميدانيّة. (٠٫٥٠)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
(19006, 4003, 2, 'أ- الاستمارة (٠٫٢٥)، لأنّها توجَّه إلى أفراد العيّنة بأسئلة مرقّمة مغلقة فتعطي اتّساعاً: عدداً كبيراً من الأجوبة القابلة للعدّ والمقارنة. (٠٫٥٠)\nب- مثال: ما المدّة التي تقضيها يوميّاً في متابعة محتوى من بلدان أخرى؟ □ أقلّ من ساعة □ من ساعة إلى ثلاث ساعات □ أكثر من ثلاث ساعات. (صياغة ٠٫٢٥، الخيارات ٠٫٥٠) — نوع التحليل: الكمّيّ. (٠٫٥٠)\nج- المرحلة الميدانيّة. (٠٫٥٠)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
(19007, 4004, 1, 'المقدّمة (٣ علامات): المنهجيّة ١٫٥٠ (حسن التمهيد، طرح الإشكاليّة بصيغة سؤال، الإعلان عن التصميم). أهمّيّة الموضوع: التغيّر يبدّل طرق العيش، واتّجاهه يحدّد موقع المجتمع بين التقدّم والتخلّف (٠٫٥٠)؛ الإطار: لبنان حاليّاً (٠٫٢٥)؛ الإشكاليّة: كيف يمكن لقوى التغيّر أن تنقل لبنان من التأرجح إلى التقدّم؟ (٠٫٥٠)؛ التصميم (٠٫٢٥).\nجسم الموضوع (٧ علامات): المنهجيّة ٢ (معالجة النقاط الأربع بالترتيب، الربط بالمستند وبالمعلومات المكتسبة، تسلسل الأفكار وسلامة اللغة). النقطة ١ (١): التغيّر الاجتماعيّ تحوّل من وضع قديم إلى وضع جديد يطرأ على جماعة أو جزء منها ويؤدّي إلى تبدّل في طرق العيش (٠٫٢٥)؛ التقدّم السيطرة على الطبيعة بالعلوم والتكنولوجيا وتأمين الرفاه والرخاء لأوسع الفئات (٠٫٢٥)؛ العلاقة: التقدّم ثمرة تغيّر يقبله المجتمع، أمّا رفض فكرة التقدّم والتطوّر فيبقيه في التخلّف (٠٫٥٠).\nالنقطة ٢ (١٫٥٠): ثلاثة معايير، ٠٫٥٠ لكلّ منها مع دلالتها على لبنان: مستوى المديونيّة (غرق في الديون وفوائدها أعاق التنمية) – مستوى الدخل – مستوى التعليم – الأمل في الحياة – مدى توزّع المداخيل (الضرائب التصاعديّة والتقديمات الاجتماعيّة) – مستوى الديمقراطيّة والمشاركة (حرّيّة التعبير، حرّيّة الترشّح والانتخاب، الحقّ في العدالة والحماية).\nالنقطة ٣ (١): إيجابيّ: قوى منظّمة (أحزاب، نقابات كنقابة المهندسين، جمعيّات الدفاع عن حقوق المرأة والطفل) وقوى غير منظّمة كبيرة التأثير (الفنّانون والأدباء والشعراء) (٠٫٥٠)؛ سلبيّ: مقاومة السلطات التي لا تريد التخلّي عن السلطة ولا مشاركتها، دفاعاً عن مصالحها (٠٫٥٠).\nالنقطة ٤ (١٫٥٠): ثلاثة اقتراحات، ٠٫٥٠ لكلّ منها، مبنيّة على أسباب التخلّف: الاستثمار في التنمية البشريّة (سكن وتعليم وصحّة) – الحدّ من الهدر والتبذير في الإنفاق العامّ ومن المديونيّة – تنمية القدرات التنظيميّة والمهارات – دعم قوى التغيّر المنظّمة.\nالخاتمة (علامتان): المنهجيّة ٠٫٥٠. تلخيص والإجابة عن الإشكاليّة: لا يخرج لبنان من التأرجح إلّا بتنمية بشريّة تقودها قوى التغيّر وتحدّ من مقاومة المستفيدين (١)؛ فتح آفاق: كيف يمكن تخفيف المديونيّة من دون المسّ بالتقديمات الاجتماعيّة؟ (٠٫٥٠)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
(19008, 4004, 2, 'المقدّمة (٣ علامات): المنهجيّة ١٫٥٠ (حسن التمهيد، طرح الإشكاليّة بصيغة سؤال، الإعلان عن التصميم). أهمّيّة الموضوع: التغيّر يبدّل طرق العيش، واتّجاهه يحدّد موقع المجتمع بين التقدّم والتخلّف (٠٫٥٠)؛ الإطار: لبنان حاليّاً (٠٫٢٥)؛ الإشكاليّة: كيف يمكن لقوى التغيّر أن تنقل لبنان من التأرجح إلى التقدّم؟ (٠٫٥٠)؛ التصميم (٠٫٢٥).\nجسم الموضوع (٧ علامات): المنهجيّة ٢ (معالجة النقاط الأربع بالترتيب، الربط بالمستند وبالمعلومات المكتسبة، تسلسل الأفكار وسلامة اللغة). النقطة ١ (١): التغيّر الاجتماعيّ تحوّل من وضع قديم إلى وضع جديد يطرأ على جماعة أو جزء منها ويؤدّي إلى تبدّل في طرق العيش (٠٫٢٥)؛ التقدّم السيطرة على الطبيعة بالعلوم والتكنولوجيا وتأمين الرفاه والرخاء لأوسع الفئات (٠٫٢٥)؛ العلاقة: التقدّم ثمرة تغيّر يقبله المجتمع، أمّا رفض فكرة التقدّم والتطوّر فيبقيه في التخلّف (٠٫٥٠).\nالنقطة ٢ (١٫٥٠): ثلاثة معايير، ٠٫٥٠ لكلّ منها مع دلالتها على لبنان: مستوى المديونيّة (غرق في الديون وفوائدها أعاق التنمية) – مستوى الدخل – مستوى التعليم – الأمل في الحياة – مدى توزّع المداخيل (الضرائب التصاعديّة والتقديمات الاجتماعيّة) – مستوى الديمقراطيّة والمشاركة (حرّيّة التعبير، حرّيّة الترشّح والانتخاب، الحقّ في العدالة والحماية).\nالنقطة ٣ (١): إيجابيّ: قوى منظّمة (أحزاب، نقابات كنقابة المهندسين، جمعيّات الدفاع عن حقوق المرأة والطفل) وقوى غير منظّمة كبيرة التأثير (الفنّانون والأدباء والشعراء) (٠٫٥٠)؛ سلبيّ: مقاومة السلطات التي لا تريد التخلّي عن السلطة ولا مشاركتها، دفاعاً عن مصالحها (٠٫٥٠).\nالنقطة ٤ (١٫٥٠): ثلاثة اقتراحات، ٠٫٥٠ لكلّ منها، مبنيّة على أسباب التخلّف: الاستثمار في التنمية البشريّة (سكن وتعليم وصحّة) – الحدّ من الهدر والتبذير في الإنفاق العامّ ومن المديونيّة – تنمية القدرات التنظيميّة والمهارات – دعم قوى التغيّر المنظّمة.\nالخاتمة (علامتان): المنهجيّة ٠٫٥٠. تلخيص والإجابة عن الإشكاليّة: لا يخرج لبنان من التأرجح إلّا بتنمية بشريّة تقودها قوى التغيّر وتحدّ من مقاومة المستفيدين (١)؛ فتح آفاق: كيف يمكن تخفيف المديونيّة من دون المسّ بالتقديمات الاجتماعيّة؟ (٠٫٥٠)', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
(19009, 4005, 1, 'أ- الحراك العاموديّ الصاعد. (٠٫٥٠)\nب- التمييز الجنسيّ. (٠٫٥٠)\nج- السمة الثقافيّة. (٠٫٥٠)\nكلّ مصطلح ٠٫٥٠ — المجموع ١٫٥٠.', 1, '2026-10-01 02:33:10', '2026-10-01 02:33:10'),
