(19577, 4289, 1, 'الصدر: فعولُ مفاعيلن فعولن مفاعلن. العجز: فعولن مفاعيلن فعولن مفاعلن. العروض «مفاعلن»، وهي عروض الطويل الوحيدة، والضرب «مفاعلن» أيضًا؛ لأنّ مفاعيلن قد تأتي في الضرب والحشو مفاعلن.', 1, '2026-10-01 13:12:22', '2026-10-01 13:12:22'),
(19578, 4289, 2, 'الصدر: فعولُ مفاعيلن فعولن مفاعلن. العجز: فعولن مفاعيلن فعولن مفاعلن. العروض «مفاعلن»، وهي عروض الطويل الوحيدة، والضرب «مفاعلن» أيضًا؛ لأنّ مفاعيلن قد تأتي في الضرب والحشو مفاعلن.', 1, '2026-10-01 13:12:22', '2026-10-01 13:12:22'),
(19579, 4290, 1, 'جاءت العروض «مفاعيلن» بسبب التصريع، وهو سجعٌ يلحق العروض والضرب فيجعل العروض موافقة للضرب؛ فلمّا جاء الضرب «مفاعيلن» جاءت العروض مثله. وتقطيع البيت: فعولُ مفاعيلن فعولُ مفاعيلن، فعولن مفاعيلن فعولُ مفاعيلن.', 1, '2026-10-01 13:12:23', '2026-10-01 13:12:23'),
(19580, 4290, 2, 'جاءت العروض «مفاعيلن» بسبب التصريع، وهو سجعٌ يلحق العروض والضرب فيجعل العروض موافقة للضرب؛ فلمّا جاء الضرب «مفاعيلن» جاءت العروض مثله. وتقطيع البيت: فعولُ مفاعيلن فعولُ مفاعيلن، فعولن مفاعيلن فعولُ مفاعيلن.', 1, '2026-10-01 13:12:23', '2026-10-01 13:12:23'),
(19581, 4291, 1, 'الرمل التامّ: فاعلاتن فاعلاتن فاعلاتن في كلّ شطر (ستّ تفعيلات). مجزوء الرمل: فاعلاتن فاعلاتن في كلّ شطر؛ أي يكتفي البيت بتفعيلتين في كلّ شطر.', 1, '2026-10-01 13:12:24', '2026-10-01 13:12:24'),
(19582, 4291, 2, 'الرمل التامّ: فاعلاتن فاعلاتن فاعلاتن في كلّ شطر (ستّ تفعيلات). مجزوء الرمل: فاعلاتن فاعلاتن في كلّ شطر؛ أي يكتفي البيت بتفعيلتين في كلّ شطر.', 1, '2026-10-01 13:12:24', '2026-10-01 13:12:24'),
(19583, 4292, 1, 'الصدر: يَنْبُتُلْوَرْ / دُ مِنَشْشَوْ / كِ وَما = فاعلاتن فعلاتن فعِلن. العجز: يَنْبُتُنْنَرْ / جِسُ إِلْلا / مِنْ بَصَلْ = فاعلاتن فعلاتن فاعلن. العروض فعِلن، والضرب فاعلن، وفي الحشو تحوّلت فاعلاتن إلى فعلاتن.', 1, '2026-10-01 13:12:25', '2026-10-01 13:12:25'),
(19584, 4292, 2, 'الصدر: يَنْبُتُلْوَرْ / دُ مِنَشْشَوْ / كِ وَما = فاعلاتن فعلاتن فعِلن. العجز: يَنْبُتُنْنَرْ / جِسُ إِلْلا / مِنْ بَصَلْ = فاعلاتن فعلاتن فاعلن. العروض فعِلن، والضرب فاعلن، وفي الحشو تحوّلت فاعلاتن إلى فعلاتن.', 1, '2026-10-01 13:12:25', '2026-10-01 13:12:25'),
(19585, 4293, 1, 'الرمل التامّ: فاعلاتن في العروض تتحوّل إلى فاعلن وفعِلن؛ وفي الضرب إلى فعلاتن وفاعلن وفاعلانْ؛ وفي الحشو تأتي فعلاتن. مجزوء الرمل: العروض فاعلاتن لا تتغيّر، والضرب فاعلاتن أو فاعلن أو فاعلاتانْ.', 1, '2026-10-01 13:12:25', '2026-10-01 13:12:25'),
(19586, 4293, 2, 'الرمل التامّ: فاعلاتن في العروض تتحوّل إلى فاعلن وفعِلن؛ وفي الضرب إلى فعلاتن وفاعلن وفاعلانْ؛ وفي الحشو تأتي فعلاتن. مجزوء الرمل: العروض فاعلاتن لا تتغيّر، والضرب فاعلاتن أو فاعلن أو فاعلاتانْ.', 1, '2026-10-01 13:12:25', '2026-10-01 13:12:25'),
(19587, 4294, 1, 'الكامل التامّ: متفاعلن متفاعلن متفاعلن في كلّ شطر (ستّ تفعيلات). مجزوء الكامل: متفاعلن متفاعلن في كلّ شطر؛ فعدد التفاعيل اثنتان في الصدر ومثلهما في العجز.', 1, '2026-10-01 13:12:26', '2026-10-01 13:12:26'),
(19588, 4294, 2, 'الكامل التامّ: متفاعلن متفاعلن متفاعلن في كلّ شطر (ستّ تفعيلات). مجزوء الكامل: متفاعلن متفاعلن في كلّ شطر؛ فعدد التفاعيل اثنتان في الصدر ومثلهما في العجز.', 1, '2026-10-01 13:12:26', '2026-10-01 13:12:26'),
(19589, 4295, 1, 'الصدر: لَوْلَلْلَذي / غَرَسَشْشِتا / ءُ بِكَفْفِهي = مستفعلن متفاعلن متفاعلن. العجز: قاسَلْمَصي / فُ هَشائِمَنْ / لا تُثْمِرو = مستفعلن متفاعلن مستفعلن. العروض متفاعلن، والضرب مستفعلن؛ والجواز: تحوّل متفاعلن إلى مستفعلن في الحشو والضرب.', 1, '2026-10-01 13:12:26', '2026-10-01 13:12:26'),
(19590, 4295, 2, 'الصدر: لَوْلَلْلَذي / غَرَسَشْشِتا / ءُ بِكَفْفِهي = مستفعلن متفاعلن متفاعلن. العجز: قاسَلْمَصي / فُ هَشائِمَنْ / لا تُثْمِرو = مستفعلن متفاعلن مستفعلن. العروض متفاعلن، والضرب مستفعلن؛ والجواز: تحوّل متفاعلن إلى مستفعلن في الحشو والضرب.', 1, '2026-10-01 13:12:26', '2026-10-01 13:12:26'),
(19591, 4296, 1, 'الكامل التامّ: العروض متفاعلن (وقد تأتي مستفعلن)، والضرب متفاعلن أو متفاعلْ أو فعْلن. مجزوء الكامل: العروض متفاعلن وجوازها مستفعلن، والضرب متفاعلاتن أو متفاعلانْ أو متفاعلن أو متفاعلْ.', 1, '2026-10-01 13:12:26', '2026-10-01 13:12:26'),
(19592, 4296, 2, 'الكامل التامّ: العروض متفاعلن (وقد تأتي مستفعلن)، والضرب متفاعلن أو متفاعلْ أو فعْلن. مجزوء الكامل: العروض متفاعلن وجوازها مستفعلن، والضرب متفاعلاتن أو متفاعلانْ أو متفاعلن أو متفاعلْ.', 1, '2026-10-01 13:12:26', '2026-10-01 13:12:26'),
(19593, 4297, 1, 'البسيط التامّ: العروض فعِلن، والضرب فعِلن أو فعْلن. البسيط المجزوء: العروض مستفعلن، والضرب مستفعلانْ أو مستفعلن أو مفعولن.', 1, '2026-10-01 13:12:28', '2026-10-01 13:12:28'),
(19594, 4297, 2, 'البسيط التامّ: العروض فعِلن، والضرب فعِلن أو فعْلن. البسيط المجزوء: العروض مستفعلن، والضرب مستفعلانْ أو مستفعلن أو مفعولن.', 1, '2026-10-01 13:12:28', '2026-10-01 13:12:28'),
(19595, 4298, 1, 'الصدر: وَذاتِ دَلْ / لِنْ كَأَنْ / نَلْبَدْرَ صو / رَتُها = مفاعلن فاعلن مستفعلن فعِلن. العجز: باتَتْ تُغَنْ / ني عَمي / دَلْقَلْبِ سَكْ / رانا = مستفعلن فاعلن مستفعلن فعْلن. البحر البسيط التامّ، العروض فعِلن، والضرب فعْلن.', 1, '2026-10-01 13:12:28', '2026-10-01 13:12:28'),
(19596, 4298, 2, 'الصدر: وَذاتِ دَلْ / لِنْ كَأَنْ / نَلْبَدْرَ صو / رَتُها = مفاعلن فاعلن مستفعلن فعِلن. العجز: باتَتْ تُغَنْ / ني عَمي / دَلْقَلْبِ سَكْ / رانا = مستفعلن فاعلن مستفعلن فعْلن. البحر البسيط التامّ، العروض فعِلن، والضرب فعْلن.', 1, '2026-10-01 13:12:28', '2026-10-01 13:12:28'),
(19597, 4299, 1, 'التقطيع: مفاعلن فاعلن فعولن / مفاعلن فاعلن فعولن. وزنه مخلّع البسيط، وهو وزن من المجزوء تفاعيله مستفعلن فاعلن فعولن (مرّتين)؛ وقد جاءت مستفعلن في المطلع مفاعلن.', 1, '2026-10-01 13:12:28', '2026-10-01 13:12:28'),
(19598, 4299, 2, 'التقطيع: مفاعلن فاعلن فعولن / مفاعلن فاعلن فعولن. وزنه مخلّع البسيط، وهو وزن من المجزوء تفاعيله مستفعلن فاعلن فعولن (مرّتين)؛ وقد جاءت مستفعلن في المطلع مفاعلن.', 1, '2026-10-01 13:12:28', '2026-10-01 13:12:28'),
(19599, 4300, 1, 'الخفيف التامّ: فاعلاتن مستفعلن فاعلاتن في كلّ شطر. مجزوء الخفيف: فاعلاتن مستفعلن في كلّ شطر؛ أي نقصت تفاعيل الوزن تفعيلة من كلّ شطر.', 1, '2026-10-01 13:12:29', '2026-10-01 13:12:29'),
(19600, 4300, 2, 'الخفيف التامّ: فاعلاتن مستفعلن فاعلاتن في كلّ شطر. مجزوء الخفيف: فاعلاتن مستفعلن في كلّ شطر؛ أي نقصت تفاعيل الوزن تفعيلة من كلّ شطر.', 1, '2026-10-01 13:12:29', '2026-10-01 13:12:29'),
(19601, 4301, 1, 'الصدر: قالَ ريمُنْ / مُرَعْعَثُنْ = فاعلاتن مفاعلن. العجز: ساحِرُطْطَرْ / فِ وَنْنَظَرْ = فاعلاتن مفاعلن. الوزن مجزوء الخفيف، ومستفعلن تحوّلت إلى مفاعلن في العروض والضرب.', 1, '2026-10-01 13:12:29', '2026-10-01 13:12:29'),
(19602, 4301, 2, 'الصدر: قالَ ريمُنْ / مُرَعْعَثُنْ = فاعلاتن مفاعلن. العجز: ساحِرُطْطَرْ / فِ وَنْنَظَرْ = فاعلاتن مفاعلن. الوزن مجزوء الخفيف، ومستفعلن تحوّلت إلى مفاعلن في العروض والضرب.', 1, '2026-10-01 13:12:29', '2026-10-01 13:12:29'),
(19603, 4302, 1, 'فاعلاتن في العروض والضرب والحشو قد تتحوّل إلى فعِلاتن، وفي العروض والضرب إلى فاعلن = فعِلن، وفي الضرب وحده إلى فالاتن = مفعولن. مستفعلن في الحشو تتحوّل إلى متَفْعِلن = مفاعلن. مجزوء الخفيف: العروض مستفعلن، والضرب مستفعلن أو مفعولن.', 1, '2026-10-01 13:12:29', '2026-10-01 13:12:29'),
(19604, 4302, 2, 'فاعلاتن في العروض والضرب والحشو قد تتحوّل إلى فعِلاتن، وفي العروض والضرب إلى فاعلن = فعِلن، وفي الضرب وحده إلى فالاتن = مفعولن. مستفعلن في الحشو تتحوّل إلى متَفْعِلن = مفاعلن. مجزوء الخفيف: العروض مستفعلن، والضرب مستفعلن أو مفعولن.', 1, '2026-10-01 13:12:29', '2026-10-01 13:12:29'),
(19605, 4303, 1, 'الوافر التامّ: مفاعلتن مفاعلتن فعولن في كلّ شطر، والعروض والضرب لا يأتيان إلّا على فعولن. مجزوء الوافر: مفاعلتن مفاعلتن في كلّ شطر، والضرب مفاعلتن أو مفاعيلن؛ فعروض المجزوء وضربه يختلفان عن التامّ.', 1, '2026-10-01 13:12:31', '2026-10-01 13:12:31'),
(19606, 4303, 2, 'الوافر التامّ: مفاعلتن مفاعلتن فعولن في كلّ شطر، والعروض والضرب لا يأتيان إلّا على فعولن. مجزوء الوافر: مفاعلتن مفاعلتن في كلّ شطر، والضرب مفاعلتن أو مفاعيلن؛ فعروض المجزوء وضربه يختلفان عن التامّ.', 1, '2026-10-01 13:12:31', '2026-10-01 13:12:31'),
(19607, 4304, 1, 'الصدر: وَزائِرَتي / كَأَنْنَ بِها / حَياءَنْ = مفاعلتن مفاعلتن فعولن. العجز: فَلَيْسَ تَزو / رُ إِلْلا فِظْ / ظَلامي = مفاعلتن مفاعيلن فعولن. العروض فعولن، والضرب فعولن، وفي حشو العجز تحوّلت مفاعلتن إلى مفاعيلن.', 1, '2026-10-01 13:12:31', '2026-10-01 13:12:31'),
(19608, 4304, 2, 'الصدر: وَزائِرَتي / كَأَنْنَ بِها / حَياءَنْ = مفاعلتن مفاعلتن فعولن. العجز: فَلَيْسَ تَزو / رُ إِلْلا فِظْ / ظَلامي = مفاعلتن مفاعيلن فعولن. العروض فعولن، والضرب فعولن، وفي حشو العجز تحوّلت مفاعلتن إلى مفاعيلن.', 1, '2026-10-01 13:12:31', '2026-10-01 13:12:31'),
(19609, 4305, 1, 'الصدر: مفاعيلن مفاعلتن فعولن. العجز: مفاعيلن مفاعلتن فعولن. العروض فعولن والضرب فعولن، وتحوّلت مفاعلتن في أوّل كلّ شطر (الحشو) إلى مفاعيلن.', 1, '2026-10-01 13:12:32', '2026-10-01 13:12:32'),
(19610, 4305, 2, 'الصدر: مفاعيلن مفاعلتن فعولن. العجز: مفاعيلن مفاعلتن فعولن. العروض فعولن والضرب فعولن، وتحوّلت مفاعلتن في أوّل كلّ شطر (الحشو) إلى مفاعيلن.', 1, '2026-10-01 13:12:32', '2026-10-01 13:12:32'),
(19611, 4306, 1, 'المتقارب التامّ: فعولن فعولن فعولن فعولن في كلّ شطر. مجزوء المتقارب: فعولن فعولن فَعَلْ في كلّ شطر؛ أي تسقط تفعيلة من كلّ شطر فيصير ثلاث تفاعيل بدل أربع.', 1, '2026-10-01 13:12:33', '2026-10-01 13:12:33'),
(19612, 4306, 2, 'المتقارب التامّ: فعولن فعولن فعولن فعولن في كلّ شطر. مجزوء المتقارب: فعولن فعولن فَعَلْ في كلّ شطر؛ أي تسقط تفعيلة من كلّ شطر فيصير ثلاث تفاعيل بدل أربع.', 1, '2026-10-01 13:12:33', '2026-10-01 13:12:33'),
(19613, 4307, 1, 'الصدر: أَغُضْضُلْ / جُفونَ / إِذا ما / بَدَتْ = فعولن فعولُ فعولن فَعَلْ. العجز: وَأَكْني / إِذا قي / لَ لي سَمْ / مِها = فعولن فعولن فعولن فَعَلْ. العروض فَعَلْ، والضرب فَعَلْ، وفي الحشو تحوّلت فعولن إلى فعولُ.', 1, '2026-10-01 13:12:33', '2026-10-01 13:12:33'),
(19614, 4307, 2, 'الصدر: أَغُضْضُلْ / جُفونَ / إِذا ما / بَدَتْ = فعولن فعولُ فعولن فَعَلْ. العجز: وَأَكْني / إِذا قي / لَ لي سَمْ / مِها = فعولن فعولن فعولن فَعَلْ. العروض فَعَلْ، والضرب فَعَلْ، وفي الحشو تحوّلت فعولن إلى فعولُ.', 1, '2026-10-01 13:12:33', '2026-10-01 13:12:33'),
(19615, 4308, 1, 'في الحشو: فعولن (//ه/ه) تتحوّل إلى فعولُ (//ه/). في العروض والضرب: تتحوّل إلى فعولُ (//ه/)، وفعولْ (//هه)، وفَعَلْ (//ه).', 1, '2026-10-01 13:12:33', '2026-10-01 13:12:33'),
(19616, 4308, 2, 'في الحشو: فعولن (//ه/ه) تتحوّل إلى فعولُ (//ه/). في العروض والضرب: تتحوّل إلى فعولُ (//ه/)، وفعولْ (//هه)، وفَعَلْ (//ه).', 1, '2026-10-01 13:12:33', '2026-10-01 13:12:33'),
(19617, 4309, 1, 'تفعيلة واحدة: الرمل (فاعلاتن ×٣)، الكامل (متفاعلن ×٣)، المتقارب (فعولن ×٤)، والوافر (مفاعلتن مفاعلتن فعولن؛ عروضه وضربه على فعولن). ممتزجة: الطويل (فعولن مفاعيلن ×٢)، البسيط (مستفعلن فاعلن ×٢)، الخفيف (فاعلاتن مستفعلن فاعلاتن).', 1, '2026-10-01 13:12:34', '2026-10-01 13:12:34'),
(19618, 4309, 2, 'تفعيلة واحدة: الرمل (فاعلاتن ×٣)، الكامل (متفاعلن ×٣)، المتقارب (فعولن ×٤)، والوافر (مفاعلتن مفاعلتن فعولن؛ عروضه وضربه على فعولن). ممتزجة: الطويل (فعولن مفاعيلن ×٢)، البسيط (مستفعلن فاعلن ×٢)، الخفيف (فاعلاتن مستفعلن فاعلاتن).', 1, '2026-10-01 13:12:34', '2026-10-01 13:12:34'),
(19619, 4310, 1, 'الصدر: مستفعلن فعِلن مستفعلن فعْلن؛ العجز: مفاعلن فاعلن مستفعلن فعْلن. البحر البسيط. العروض فعِلن والضرب فعْلن؛ وفي الحشو تحوّلت فاعلن إلى فعِلن، وفي مطلع العجز تحوّلت مستفعلن إلى مفاعلن.', 1, '2026-10-01 13:12:34', '2026-10-01 13:12:34'),
(19620, 4310, 2, 'الصدر: مستفعلن فعِلن مستفعلن فعْلن؛ العجز: مفاعلن فاعلن مستفعلن فعْلن. البحر البسيط. العروض فعِلن والضرب فعْلن؛ وفي الحشو تحوّلت فاعلن إلى فعِلن، وفي مطلع العجز تحوّلت مستفعلن إلى مفاعلن.', 1, '2026-10-01 13:12:34', '2026-10-01 13:12:34'),
(19621, 4311, 1, 'لَكِلْلا / هُ مِنْ أَ / مَلِنْ مو / جَعي = فعولن فعولُ فعولن فَعَلْ؛ نَما وَ / تَرَعْ رَ / عَ في أَضْ / لُعي = فعولُ فعولُ فعولن فَعَلْ. البحر المتقارب؛ العروض فَعَلْ، والضرب فَعَلْ.', 1, '2026-10-01 13:12:35', '2026-10-01 13:12:35'),
(19622, 4311, 2, 'لَكِلْلا / هُ مِنْ أَ / مَلِنْ مو / جَعي = فعولن فعولُ فعولن فَعَلْ؛ نَما وَ / تَرَعْ رَ / عَ في أَضْ / لُعي = فعولُ فعولُ فعولن فَعَلْ. البحر المتقارب؛ العروض فَعَلْ، والضرب فَعَلْ.', 1, '2026-10-01 13:12:35', '2026-10-01 13:12:35'),
(19623, 4312, 1, 'لارتباط الشعر بالحياة وبالأذواق الخاصّة؛ فتطوّره مرتبط ارتباطاً عضويّاً بتأدية الجديد من التجارب. فتراءت لبعض الشعراء ضرورة تخطّي الحواجز وكسر القيود، فتصدّوا للقوالب الفنّيّة في الوزن والقافية؛ وكان التجديد بنظرهم صدى للجديد الذي طرأ على الحياة وتحرّراً من قيود يأباها الشعر.', 1, '2026-10-01 13:12:36', '2026-10-01 13:12:36'),
(19624, 4312, 2, 'لارتباط الشعر بالحياة وبالأذواق الخاصّة؛ فتطوّره مرتبط ارتباطاً عضويّاً بتأدية الجديد من التجارب. فتراءت لبعض الشعراء ضرورة تخطّي الحواجز وكسر القيود، فتصدّوا للقوالب الفنّيّة في الوزن والقافية؛ وكان التجديد بنظرهم صدى للجديد الذي طرأ على الحياة وتحرّراً من قيود يأباها الشعر.', 1, '2026-10-01 13:12:36', '2026-10-01 13:12:36'),
(19625, 4313, 1, 'تجاوز الشعراء البيت التقليديّ واعتمدوا السطر الموزون الذي يتضمّن عدداً غير ثابت من التفاعيل؛ وقد يكتفون بجزء من تفعيلة («مَطَرْ» = فَعَلْ = نصف مفاعلن عند السيّاب)، أو يوزّعون التفعيلة بين سطرين («بي ولي من» = فاعلاتن في «الجسر»). والسطر لا يستقلّ بمعناه بل يتّصل بأسطر أخرى مضموناً وتعبيراً.', 1, '2026-10-01 13:12:36', '2026-10-01 13:12:36'),
(19626, 4313, 2, 'تجاوز الشعراء البيت التقليديّ واعتمدوا السطر الموزون الذي يتضمّن عدداً غير ثابت من التفاعيل؛ وقد يكتفون بجزء من تفعيلة («مَطَرْ» = فَعَلْ = نصف مفاعلن عند السيّاب)، أو يوزّعون التفعيلة بين سطرين («بي ولي من» = فاعلاتن في «الجسر»). والسطر لا يستقلّ بمعناه بل يتّصل بأسطر أخرى مضموناً وتعبيراً.', 1, '2026-10-01 13:12:36', '2026-10-01 13:12:36'),
(19627, 4314, 1, 'في الشعر العموديّ القافية موحّدة ونهاية ثابتة للبيت، تتكرّر بانتظام في أماكن محدّدة وعلى مسافات متساوية. عند شعراء التفعيلة صارت دفقة موسيقيّة تتفاوت مسافاتها، وقد ينتهي السطر بنصف تفعيلة يكملها السطر التالي؛ وتلتزم الرويّ المختار (زاد/معاد، عيد/جديد)، وقد ترتبط بسابقاتها ارتباط تآلف وإيقاع (أترابي/كفاني).', 1, '2026-10-01 13:12:36', '2026-10-01 13:12:36'),
(19628, 4314, 2, 'في الشعر العموديّ القافية موحّدة ونهاية ثابتة للبيت، تتكرّر بانتظام في أماكن محدّدة وعلى مسافات متساوية. عند شعراء التفعيلة صارت دفقة موسيقيّة تتفاوت مسافاتها، وقد ينتهي السطر بنصف تفعيلة يكملها السطر التالي؛ وتلتزم الرويّ المختار (زاد/معاد، عيد/جديد)، وقد ترتبط بسابقاتها ارتباط تآلف وإيقاع (أترابي/كفاني).', 1, '2026-10-01 13:12:36', '2026-10-01 13:12:36'),
(19629, 4315, 1, 'موسيقى الشعر الكلاسيكيّ يؤمّنها الوزن بدرجة أولى، وهي ظاهرة سهلة الإدراك، ونغمها يبقى واحداً على امتداد القصيدة. وموسيقى الشعر الحرّ رهن بموهبة الشاعر، أخفت صوتاً، تتطلّب دربة ورهافة حسّ لاكتشافها؛ ولكلّ سطر نغمه ولكلّ مقطع لونه الخاصّ.', 1, '2026-10-01 13:12:37', '2026-10-01 13:12:37'),
(19630, 4315, 2, 'موسيقى الشعر الكلاسيكيّ يؤمّنها الوزن بدرجة أولى، وهي ظاهرة سهلة الإدراك، ونغمها يبقى واحداً على امتداد القصيدة. وموسيقى الشعر الحرّ رهن بموهبة الشاعر، أخفت صوتاً، تتطلّب دربة ورهافة حسّ لاكتشافها؛ ولكلّ سطر نغمه ولكلّ مقطع لونه الخاصّ.', 1, '2026-10-01 13:12:37', '2026-10-01 13:12:37'),
(19631, 4316, 1, 'الوقفات المحدّدة عند نهاية الأبيات تريح القارئ وتبرز اللفظة الموقوف عليها معنى وموسيقى؛ وتكرار نغم القافية في أماكن معروفة وعلى مسافات متعادلة يقوّي التوازن بين الأبيات، وتنويع الوقفات يوفّر متعة متجدّدة. وفي الشعر الحرّ حافظ الشعراء على مبدأ القافية، ولأنّها خاتمة أسطر غير متساوية الطول فهي تكسر حدّة التوازن وتكسب الشعر رونقاً وتجديداً.', 1, '2026-10-01 13:12:37', '2026-10-01 13:12:37'),
(19632, 4316, 2, 'الوقفات المحدّدة عند نهاية الأبيات تريح القارئ وتبرز اللفظة الموقوف عليها معنى وموسيقى؛ وتكرار نغم القافية في أماكن معروفة وعلى مسافات متعادلة يقوّي التوازن بين الأبيات، وتنويع الوقفات يوفّر متعة متجدّدة. وفي الشعر الحرّ حافظ الشعراء على مبدأ القافية، ولأنّها خاتمة أسطر غير متساوية الطول فهي تكسر حدّة التوازن وتكسب الشعر رونقاً وتجديداً.', 1, '2026-10-01 13:12:37', '2026-10-01 13:12:37'),
(19633, 4317, 1, 'تكرار الأحرف: الراء في «أفياء جيكور» أو الدال في مطلع «الجسر»؛ تكرار الكلمات: «الشرق» في «الجسر» أو «جيكور» عند السيّاب؛ تكرار بعض الأسطر في قصيدة حاوي؛ التوازن بين جمل متشابهة حيناً ومعكوسة السياق حيناً آخر؛ توزيع الفواصل والوقفات وأحرف العطف وعلامات التعجّب والاستفهام.', 1, '2026-10-01 13:12:38', '2026-10-01 13:12:38'),
(19634, 4317, 2, 'تكرار الأحرف: الراء في «أفياء جيكور» أو الدال في مطلع «الجسر»؛ تكرار الكلمات: «الشرق» في «الجسر» أو «جيكور» عند السيّاب؛ تكرار بعض الأسطر في قصيدة حاوي؛ التوازن بين جمل متشابهة حيناً ومعكوسة السياق حيناً آخر؛ توزيع الفواصل والوقفات وأحرف العطف وعلامات التعجّب والاستفهام.', 1, '2026-10-01 13:12:38', '2026-10-01 13:12:38'),
(19635, 4318, 1, 'الحقيقة: استعمال الكلام في ما وُضِع له في الأصل. المجاز: استعمال الكلام في وجهٍ غير الوجه الذي وُضِع له في الأصل. والفيصل: هل الكلمة في موضعها المألوف الذي نعرفه من المعجم، أم حملت دلالة ليست لها في الأصل؟', 1, '2026-10-01 13:12:39', '2026-10-01 13:12:39'),
(19636, 4318, 2, 'الحقيقة: استعمال الكلام في ما وُضِع له في الأصل. المجاز: استعمال الكلام في وجهٍ غير الوجه الذي وُضِع له في الأصل. والفيصل: هل الكلمة في موضعها المألوف الذي نعرفه من المعجم، أم حملت دلالة ليست لها في الأصل؟', 1, '2026-10-01 13:12:39', '2026-10-01 13:12:39'),
(19637, 4319, 1, 'الإسناد الحقيقيّ: إسناد المعنى إلى صاحبه الحقيقيّ، مثل «مَرِضَ الرَّجُلُ» أو «غَرَّدَ الطّائِرُ». الإسناد المجازيّ: إسناد الفعل إلى غير صاحبه الحقيقيّ على سبيل التصوير، مثل «وَتُزهِرُ الآمالُ» (الإزهار للشجر). ويسمّيه البلاغيّون المجاز العقليّ.', 1, '2026-10-01 13:12:39', '2026-10-01 13:12:39'),
(19638, 4319, 2, 'الإسناد الحقيقيّ: إسناد المعنى إلى صاحبه الحقيقيّ، مثل «مَرِضَ الرَّجُلُ» أو «غَرَّدَ الطّائِرُ». الإسناد المجازيّ: إسناد الفعل إلى غير صاحبه الحقيقيّ على سبيل التصوير، مثل «وَتُزهِرُ الآمالُ» (الإزهار للشجر). ويسمّيه البلاغيّون المجاز العقليّ.', 1, '2026-10-01 13:12:39', '2026-10-01 13:12:39'),
(19639, 4320, 1, 'المجاز في كلمة «جدول»: الجدول في الأصل ماء يجري، وقد استُعمل للأحزان، فهو مجاز لفظيّ. وهو قائم على المشابهة (الحزن يجري في النفس كما يجري الماء)، فيكون استعارة. أمّا الإسناد فحقيقيّ لا مجاز فيه.', 1, '2026-10-01 13:12:39', '2026-10-01 13:12:39'),
(19640, 4320, 2, 'المجاز في كلمة «جدول»: الجدول في الأصل ماء يجري، وقد استُعمل للأحزان، فهو مجاز لفظيّ. وهو قائم على المشابهة (الحزن يجري في النفس كما يجري الماء)، فيكون استعارة. أمّا الإسناد فحقيقيّ لا مجاز فيه.', 1, '2026-10-01 13:12:39', '2026-10-01 13:12:39'),
(19641, 4321, 1, 'التشبيه: عقد الصلة، أو الربط، بين شيئين تماثلا في صفة مشتركة بينهما بوساطة أداة هي الكاف أو نحوها، ملفوظة أو مقدّرة. أركانه: المشبّه، والمشبّه به (وهما طرفاه)، وأداة التشبيه، ووجه الشبه.', 1, '2026-10-01 13:12:40', '2026-10-01 13:12:40'),
(19642, 4321, 2, 'التشبيه: عقد الصلة، أو الربط، بين شيئين تماثلا في صفة مشتركة بينهما بوساطة أداة هي الكاف أو نحوها، ملفوظة أو مقدّرة. أركانه: المشبّه، والمشبّه به (وهما طرفاه)، وأداة التشبيه، ووجه الشبه.', 1, '2026-10-01 13:12:40', '2026-10-01 13:12:40'),
(19643, 4322, 1, 'المشبّه: السيوف؛ الأداة: الكاف؛ المشبّه به: بارق الثغر المتبسّم؛ وجه الشبه: اللمعان (لمعت). ذُكرت الأداة فهو مرسل، وذُكر وجه الشبه فهو مفصّل؛ فهو تشبيه مرسل مفصّل.', 1, '2026-10-01 13:12:40', '2026-10-01 13:12:40'),
(19644, 4322, 2, 'المشبّه: السيوف؛ الأداة: الكاف؛ المشبّه به: بارق الثغر المتبسّم؛ وجه الشبه: اللمعان (لمعت). ذُكرت الأداة فهو مرسل، وذُكر وجه الشبه فهو مفصّل؛ فهو تشبيه مرسل مفصّل.', 1, '2026-10-01 13:12:40', '2026-10-01 13:12:40'),
(19645, 4323, 1, 'من أغراضه: بيان حال المشبّه أو تفصيلها أو تثبيتها، تثبيت صفة المشبّه وإيضاحها، تزيين المشبّه ومدحه أو تقبيحه وهجاؤه. أقسامه: المرسل (ذُكرت الأداة)، المفصّل (ذُكر وجه الشبه)، المؤكّد (حُذفت الأداة)، المجمل (حُذف وجه الشبه)، البليغ (حُذفت الأداة ووجه الشبه معًا).', 1, '2026-10-01 13:12:40', '2026-10-01 13:12:40'),
(19646, 4323, 2, 'من أغراضه: بيان حال المشبّه أو تفصيلها أو تثبيتها، تثبيت صفة المشبّه وإيضاحها، تزيين المشبّه ومدحه أو تقبيحه وهجاؤه. أقسامه: المرسل (ذُكرت الأداة)، المفصّل (ذُكر وجه الشبه)، المؤكّد (حُذفت الأداة)، المجمل (حُذف وجه الشبه)، البليغ (حُذفت الأداة ووجه الشبه معًا).', 1, '2026-10-01 13:12:40', '2026-10-01 13:12:40'),
(19647, 4324, 1, 'المكنيّة: تشبيه حُذف منه المشبّه به ورُمز إليه بشيء من لوازمه. التصريحيّة: ما صُرّح فيها بلفظ المشبّه به. أركانها: المستعار منه (المشبّه به في الأصل)، والمستعار له (المشبّه في الأصل)، واللفظ الجامع بين طرفي الاستعارة.', 1, '2026-10-01 13:12:42', '2026-10-01 13:12:42'),
(19648, 4324, 2, 'المكنيّة: تشبيه حُذف منه المشبّه به ورُمز إليه بشيء من لوازمه. التصريحيّة: ما صُرّح فيها بلفظ المشبّه به. أركانها: المستعار منه (المشبّه به في الأصل)، والمستعار له (المشبّه في الأصل)، واللفظ الجامع بين طرفي الاستعارة.', 1, '2026-10-01 13:12:42', '2026-10-01 13:12:42'),
(19649, 4325, 1, 'استعارة مكنيّة: شبّه التاريخ بإنسان ينام، فذكر المشبّه (التاريخ) وحذف المشبّه به (الإنسان)، ورمز إليه بشيء من لوازمه هو «نام».', 1, '2026-10-01 13:12:42', '2026-10-01 13:12:42'),
(19650, 4325, 2, 'استعارة مكنيّة: شبّه التاريخ بإنسان ينام، فذكر المشبّه (التاريخ) وحذف المشبّه به (الإنسان)، ورمز إليه بشيء من لوازمه هو «نام».', 1, '2026-10-01 13:12:42', '2026-10-01 13:12:42'),
(19651, 4326, 1, 'شبّه الصلاة بالطائر؛ فالمشبّه (الصلاة) مذكور، والمشبّه به (الطائر) محذوف، ورُمز إليه بشيء من لوازمه هو «مجنّحة» و«ترفرف»، فالصلاة لا ترفرف. فهي استعارة مكنيّة.', 1, '2026-10-01 13:12:42', '2026-10-01 13:12:42'),
(19652, 4326, 2, 'شبّه الصلاة بالطائر؛ فالمشبّه (الصلاة) مذكور، والمشبّه به (الطائر) محذوف، ورُمز إليه بشيء من لوازمه هو «مجنّحة» و«ترفرف»، فالصلاة لا ترفرف. فهي استعارة مكنيّة.', 1, '2026-10-01 13:12:42', '2026-10-01 13:12:42'),
(19653, 4327, 1, 'الكناية تعبير أُطلق وأُريد به غير معناه الحقيقيّ الذي وُضع له، مع جواز إرادة هذا المعنى (نقول شيئًا ونريد لازمه). أنواعها باعتبار المكنيّ عنه: الكناية عن صفة، والكناية عن نسبة، والكناية عن موصوف.', 1, '2026-10-01 13:12:43', '2026-10-01 13:12:43'),
(19654, 4327, 2, 'الكناية تعبير أُطلق وأُريد به غير معناه الحقيقيّ الذي وُضع له، مع جواز إرادة هذا المعنى (نقول شيئًا ونريد لازمه). أنواعها باعتبار المكنيّ عنه: الكناية عن صفة، والكناية عن نسبة، والكناية عن موصوف.', 1, '2026-10-01 13:12:43', '2026-10-01 13:12:43'),
(19655, 4328, 1, 'أراد أن ينسب صفة الكرم إلى ممدوحه، فبدل أن ينسبها إليه مباشرة نسبها إلى ما له بها اتّصال، أي إلى المكان الذي يسير فيه: الجود يسير حيث سار الممدوح. فهي كناية عن نسبة، وعلامتها التصريح بالصفة: «الجود».', 1, '2026-10-01 13:12:43', '2026-10-01 13:12:43'),
(19656, 4328, 2, 'أراد أن ينسب صفة الكرم إلى ممدوحه، فبدل أن ينسبها إليه مباشرة نسبها إلى ما له بها اتّصال، أي إلى المكان الذي يسير فيه: الجود يسير حيث سار الممدوح. فهي كناية عن نسبة، وعلامتها التصريح بالصفة: «الجود».', 1, '2026-10-01 13:12:43', '2026-10-01 13:12:43'),
(19657, 4329, 1, 'عن صفة: المكنيّ عنه صفة، والشرط أن يكون الموصوف مذكورًا باللفظ أو مفهومًا من السياق. عن نسبة: المكنيّ عنه نسبة إلى ما له اتّصال بالموصوف، وأظهر علامتها التصريح بالصفة. عن موصوف: المكنيّ عنه موصوف، يُذكر بصفة تلازمه وتشير إليه.', 1, '2026-10-01 13:12:43', '2026-10-01 13:12:43'),
(19658, 4329, 2, 'عن صفة: المكنيّ عنه صفة، والشرط أن يكون الموصوف مذكورًا باللفظ أو مفهومًا من السياق. عن نسبة: المكنيّ عنه نسبة إلى ما له اتّصال بالموصوف، وأظهر علامتها التصريح بالصفة. عن موصوف: المكنيّ عنه موصوف، يُذكر بصفة تلازمه وتشير إليه.', 1, '2026-10-01 13:12:43', '2026-10-01 13:12:43');
INSERT INTO `written_model_answers_translations` (`id`, `written_model_answer_id`, `language_id`, `model_answer`, `is_active`, `created_at`, `updated_at`) VALUES
(19659, 4330, 1, 'الجناس أن يتشابه اللفظان في النطق ويختلفا في المعنى. التامّ: تتجانس فيه أحرف الكلمتين نوعًا وشكلًا وعددًا وترتيبًا. غير التامّ (الناقص): تختلف فيه الكلمتان في واحد من هذه الأركان الأربعة.', 1, '2026-10-01 13:12:45', '2026-10-01 13:12:45'),
(19660, 4330, 2, 'الجناس أن يتشابه اللفظان في النطق ويختلفا في المعنى. التامّ: تتجانس فيه أحرف الكلمتين نوعًا وشكلًا وعددًا وترتيبًا. غير التامّ (الناقص): تختلف فيه الكلمتان في واحد من هذه الأركان الأربعة.', 1, '2026-10-01 13:12:45', '2026-10-01 13:12:45'),
(19661, 4331, 1, 'الجناس بين «إنسانًا» و«إنسانا»: الأولى الإنسان من البشر، والثانية إنسان العين أي بؤبؤها. اتّفقتا في نوع الأحرف وشكلها وعددها وترتيبها واختلفتا في المعنى، فالجناس تامّ.', 1, '2026-10-01 13:12:45', '2026-10-01 13:12:45'),
(19662, 4331, 2, 'الجناس بين «إنسانًا» و«إنسانا»: الأولى الإنسان من البشر، والثانية إنسان العين أي بؤبؤها. اتّفقتا في نوع الأحرف وشكلها وعددها وترتيبها واختلفتا في المعنى، فالجناس تامّ.', 1, '2026-10-01 13:12:45', '2026-10-01 13:12:45'),
(19663, 4332, 1, 'علم البديع: تزيين يضفيه الأديب على النصّ من حيث المعنى أو من حيث المبنى، وهو قسمان: لفظيّ ومعنويّ. كثر السجع والجناس في النصوص النثريّة الجاهليّة والإسلاميّة، ثمّ توسّع في النثر العبّاسيّ حتّى لامس الشعر، ثمّ غلب التكلّف والتصنّع في العصور التالية، إلى أن انحسر في مرحلة النهضة والحداثة.', 1, '2026-10-01 13:12:45', '2026-10-01 13:12:45'),
(19664, 4332, 2, 'علم البديع: تزيين يضفيه الأديب على النصّ من حيث المعنى أو من حيث المبنى، وهو قسمان: لفظيّ ومعنويّ. كثر السجع والجناس في النصوص النثريّة الجاهليّة والإسلاميّة، ثمّ توسّع في النثر العبّاسيّ حتّى لامس الشعر، ثمّ غلب التكلّف والتصنّع في العصور التالية، إلى أن انحسر في مرحلة النهضة والحداثة.', 1, '2026-10-01 13:12:45', '2026-10-01 13:12:45'),
(19665, 4333, 1, 'السجع توافق فاصلتين أو أكثر من فواصل الكلام في الحرف الأخير أو الحرفين الأخيرين، في النثر. وتعلو مرتبته إذا تساوت الفواصل في طولها أو قصرها إضافة إلى التشابه في أواخرها، فتغدو إيقاعاته أكثر اتّساقًا ورشاقة.', 1, '2026-10-01 13:12:46', '2026-10-01 13:12:46'),
(19666, 4333, 2, 'السجع توافق فاصلتين أو أكثر من فواصل الكلام في الحرف الأخير أو الحرفين الأخيرين، في النثر. وتعلو مرتبته إذا تساوت الفواصل في طولها أو قصرها إضافة إلى التشابه في أواخرها، فتغدو إيقاعاته أكثر اتّساقًا ورشاقة.', 1, '2026-10-01 13:12:46', '2026-10-01 13:12:46'),
(19667, 4334, 1, 'الفواصل: وفى، كفى، عفا، متوافقة في الحرف الأخير (الألف) ومتقاربة في الطول؛ فأكسبت الجملة إيقاعًا متّسقًا يسهل حفظه، ويقوّي وقع الحكمة في النفس.', 1, '2026-10-01 13:12:46', '2026-10-01 13:12:46'),
(19668, 4334, 2, 'الفواصل: وفى، كفى، عفا، متوافقة في الحرف الأخير (الألف) ومتقاربة في الطول؛ فأكسبت الجملة إيقاعًا متّسقًا يسهل حفظه، ويقوّي وقع الحكمة في النفس.', 1, '2026-10-01 13:12:46', '2026-10-01 13:12:46'),
(19669, 4335, 1, 'البلاء / الإعطاء: تتوافقان في آخرهما (الألف والهمزة). الإنصاف / الإلحاف: تتوافقان في آخرهما (الألف والفاء). وقد تعدّد السجع وتقاربت الفواصل في طولها، فعلت مرتبته.', 1, '2026-10-01 13:12:46', '2026-10-01 13:12:46'),
(19670, 4335, 2, 'البلاء / الإعطاء: تتوافقان في آخرهما (الألف والهمزة). الإنصاف / الإلحاف: تتوافقان في آخرهما (الألف والفاء). وقد تعدّد السجع وتقاربت الفواصل في طولها، فعلت مرتبته.', 1, '2026-10-01 13:12:46', '2026-10-01 13:12:46'),
(19671, 4336, 1, 'الاقتباس تضمين الشعر أو النثر قولًا من شاعر آخر أو ناثر آخر. يُنقل الكلام المقتبس إمّا بحرفيّته وإمّا بتغيير قليل. وقد يصرّح الناقل بمصدر الاقتباس وقد لا يصرّح.', 1, '2026-10-01 13:12:47', '2026-10-01 13:12:47'),
(19672, 4336, 2, 'الاقتباس تضمين الشعر أو النثر قولًا من شاعر آخر أو ناثر آخر. يُنقل الكلام المقتبس إمّا بحرفيّته وإمّا بتغيير قليل. وقد يصرّح الناقل بمصدر الاقتباس وقد لا يصرّح.', 1, '2026-10-01 13:12:47', '2026-10-01 13:12:47'),
(19673, 4337, 1, 'اقتبس قيس من المثل عبارة «ما أقام عسيب»، ومعناها: أبدًا، ما دام جبل عسيب قائمًا؛ فهو باقٍ على العهد أبدًا. أخذ العبارة بلفظها وغيّر ما قبلها ليوافق بيته، ولم يصرّح بمصدرها.', 1, '2026-10-01 13:12:47', '2026-10-01 13:12:47'),
(19674, 4337, 2, 'اقتبس قيس من المثل عبارة «ما أقام عسيب»، ومعناها: أبدًا، ما دام جبل عسيب قائمًا؛ فهو باقٍ على العهد أبدًا. أخذ العبارة بلفظها وغيّر ما قبلها ليوافق بيته، ولم يصرّح بمصدرها.', 1, '2026-10-01 13:12:47', '2026-10-01 13:12:47'),
(19675, 4338, 1, 'كان الخطباء يقتبسون من القرآن الكريم، أو الحديث الشريف، أو من حكم البلغاء الجاهليّين والإسلاميّين؛ لإضفاء هالة من القداسة والشرعيّة على النصّ، ولتقويته وتزيينه مضمونًا وأسلوبًا.', 1, '2026-10-01 13:12:48', '2026-10-01 13:12:48'),
(19676, 4338, 2, 'كان الخطباء يقتبسون من القرآن الكريم، أو الحديث الشريف، أو من حكم البلغاء الجاهليّين والإسلاميّين؛ لإضفاء هالة من القداسة والشرعيّة على النصّ، ولتقويته وتزيينه مضمونًا وأسلوبًا.', 1, '2026-10-01 13:12:48', '2026-10-01 13:12:48'),
(19677, 4339, 1, 'الطباق هو الجمع بين كلمتين متضادّتين في المعنى. وهو نوعان: طباق الإيجاب، وهو ما يختلف فيه الضدّان إيجابًا وسلبًا، نحو: الشقاء، النعيم؛ وطباق السلب، وهو ما يختلف فيه الضدّان إثباتًا ونفيًا، نحو: أرضى، ولا أرضى.', 1, '2026-10-01 13:12:49', '2026-10-01 13:12:49'),
(19678, 4339, 2, 'الطباق هو الجمع بين كلمتين متضادّتين في المعنى. وهو نوعان: طباق الإيجاب، وهو ما يختلف فيه الضدّان إيجابًا وسلبًا، نحو: الشقاء، النعيم؛ وطباق السلب، وهو ما يختلف فيه الضدّان إثباتًا ونفيًا، نحو: أرضى، ولا أرضى.', 1, '2026-10-01 13:12:49', '2026-10-01 13:12:49'),
(19679, 4340, 1, 'عند أبي فراس طباق إيجاب: كلمتان مختلفتان متضادّتان (الوفاء والغدر). أمّا عند أبي نواس فطباق سلب: فعلان من مادّة واحدة، أحدهما مثبت (أبكي) والآخر منفيّ (لا أبكي).', 1, '2026-10-01 13:12:49', '2026-10-01 13:12:49'),
(19680, 4340, 2, 'عند أبي فراس طباق إيجاب: كلمتان مختلفتان متضادّتان (الوفاء والغدر). أمّا عند أبي نواس فطباق سلب: فعلان من مادّة واحدة، أحدهما مثبت (أبكي) والآخر منفيّ (لا أبكي).', 1, '2026-10-01 13:12:49', '2026-10-01 13:12:49'),
(19681, 4341, 1, 'نضع مكان الفعل المنفيّ ضدّه المثبت: «يصبر الإنسان الأبيّ على الفقر، ويجزع من الذلّ والمهانة» (أو: ويضيق بالذلّ). فيصير الطباق بين «يصبر» و«يجزع»، وهما كلمتان مختلفتان متضادّتان، فهو طباق إيجاب.', 1, '2026-10-01 13:12:49', '2026-10-01 13:12:49'),
(19682, 4341, 2, 'نضع مكان الفعل المنفيّ ضدّه المثبت: «يصبر الإنسان الأبيّ على الفقر، ويجزع من الذلّ والمهانة» (أو: ويضيق بالذلّ). فيصير الطباق بين «يصبر» و«يجزع»، وهما كلمتان مختلفتان متضادّتان، فهو طباق إيجاب.', 1, '2026-10-01 13:12:49', '2026-10-01 13:12:49'),
(19683, 4342, 1, 'التورية أن يذكر الكاتب كلمة مفردة لها معنيان: أحدهما قريب ظاهر غير مقصود، ودلالة اللفظ عليه واضحة ظاهرة في سياق الكلام؛ والثاني بعيد غير ظاهر، وهو المعنى المقصود، ودلالة اللفظ عليه خفيّة غير ظاهرة.', 1, '2026-10-01 13:12:50', '2026-10-01 13:12:50'),
(19684, 4342, 2, 'التورية أن يذكر الكاتب كلمة مفردة لها معنيان: أحدهما قريب ظاهر غير مقصود، ودلالة اللفظ عليه واضحة ظاهرة في سياق الكلام؛ والثاني بعيد غير ظاهر، وهو المعنى المقصود، ودلالة اللفظ عليه خفيّة غير ظاهرة.', 1, '2026-10-01 13:12:50', '2026-10-01 13:12:50'),
(19685, 4343, 1, '1) لا بدّ في الجناس من تكرار الكلمة مرّتين، تُذكر بمعنى ثمّ تُعاد بمعنى آخر، أمّا في التورية فلا تتكرّر. 2) يبقى المعنيان في الجناس التامّ سواء من حيث القرب والبعد، أمّا في التورية فأحدهما قريب واضح والآخر بعيد خفيّ. 3) في الجناس التامّ يكون المعنيان مرادين، أمّا في التورية فأحدهما هو المراد والمقصود.', 1, '2026-10-01 13:12:50', '2026-10-01 13:12:50'),
(19686, 4343, 2, '1) لا بدّ في الجناس من تكرار الكلمة مرّتين، تُذكر بمعنى ثمّ تُعاد بمعنى آخر، أمّا في التورية فلا تتكرّر. 2) يبقى المعنيان في الجناس التامّ سواء من حيث القرب والبعد، أمّا في التورية فأحدهما قريب واضح والآخر بعيد خفيّ. 3) في الجناس التامّ يكون المعنيان مرادين، أمّا في التورية فأحدهما هو المراد والمقصود.', 1, '2026-10-01 13:12:50', '2026-10-01 13:12:50'),
(19687, 4344, 1, 'التورية في «روحي». المعنى القريب الظاهر من السياق بعد قولها «رُحْ»: فعل أمر من راح، أي اذهبي أنتِ، وهو غير مقصود. والمعنى البعيد المقصود: أنتِ روحي، أي نفسي.', 1, '2026-10-01 13:12:50', '2026-10-01 13:12:50'),
(19688, 4344, 2, 'التورية في «روحي». المعنى القريب الظاهر من السياق بعد قولها «رُحْ»: فعل أمر من راح، أي اذهبي أنتِ، وهو غير مقصود. والمعنى البعيد المقصود: أنتِ روحي، أي نفسي.', 1, '2026-10-01 13:12:50', '2026-10-01 13:12:50'),
(19689, 4345, 1, 'الابتدائيّ: المخاطب متقبّل للحكم بلا تردّد أو خالي الذهن، فيُلقى إليه الخبر خاليًا من أدوات التوكيد. الطلبيّ: المخاطب متردّد في الحكم، فيُلقى إليه الخبر مقرونًا بأداة توكيد أو أكثر. الإنكاريّ: المخاطب منكر أو جاحد للحكم، فيزداد التوكيد ويقوى على حسب الإنكار.', 1, '2026-10-01 13:12:52', '2026-10-01 13:12:52'),
(19690, 4345, 2, 'الابتدائيّ: المخاطب متقبّل للحكم بلا تردّد أو خالي الذهن، فيُلقى إليه الخبر خاليًا من أدوات التوكيد. الطلبيّ: المخاطب متردّد في الحكم، فيُلقى إليه الخبر مقرونًا بأداة توكيد أو أكثر. الإنكاريّ: المخاطب منكر أو جاحد للحكم، فيزداد التوكيد ويقوى على حسب الإنكار.', 1, '2026-10-01 13:12:52', '2026-10-01 13:12:52'),
(19691, 4346, 1, 'من أدوات التوكيد: إنّ، أنّ، قد، القسم، لام الابتداء، نونا التوكيد، أمّا الشرطيّة. مثال: «فَإِنّي بِلَيْلى قَدْ لَقيتُ الدَّواهِيا» (إنّ وقد)، أو «وَتاللهِ إِنّي مِنْ مُقامي بَيْنَكُمْ» (القسم وإنّ).', 1, '2026-10-01 13:12:52', '2026-10-01 13:12:52'),
(19692, 4346, 2, 'من أدوات التوكيد: إنّ، أنّ، قد، القسم، لام الابتداء، نونا التوكيد، أمّا الشرطيّة. مثال: «فَإِنّي بِلَيْلى قَدْ لَقيتُ الدَّواهِيا» (إنّ وقد)، أو «وَتاللهِ إِنّي مِنْ مُقامي بَيْنَكُمْ» (القسم وإنّ).', 1, '2026-10-01 13:12:52', '2026-10-01 13:12:52'),
(19693, 4347, 1, 'الخبر إنكاريّ، لأنّ الشاعر قوّاه بأكثر من أداة توكيد: إنّ، ولام الابتداء في «لأرفض»، فازداد التوكيد كما يكون مع المخاطب المنكر للحكم.', 1, '2026-10-01 13:12:52', '2026-10-01 13:12:52'),
(19694, 4347, 2, 'الخبر إنكاريّ، لأنّ الشاعر قوّاه بأكثر من أداة توكيد: إنّ، ولام الابتداء في «لأرفض»، فازداد التوكيد كما يكون مع المخاطب المنكر للحكم.', 1, '2026-10-01 13:12:52', '2026-10-01 13:12:52'),
(19695, 4348, 1, 'الجملة الإنشائيّة هي التي لا تحتمل في معناها تصديقًا ولا تكذيبًا. وهي نوعان: طلبيّة، يستدعي مضمونها مطلوبًا غير حاصل وقت الطلب، وتتحقّق بالأمر أو النهي أو الاستفهام أو التمنّي أو النداء؛ وغير طلبيّة، لا يستدعي مضمونها مطلوبًا، وتتحقّق بصيغ منها التعجّب والمدح أو الذمّ وأفعال الرجاء والقسم.', 1, '2026-10-01 13:12:53', '2026-10-01 13:12:53'),
(19696, 4348, 2, 'الجملة الإنشائيّة هي التي لا تحتمل في معناها تصديقًا ولا تكذيبًا. وهي نوعان: طلبيّة، يستدعي مضمونها مطلوبًا غير حاصل وقت الطلب، وتتحقّق بالأمر أو النهي أو الاستفهام أو التمنّي أو النداء؛ وغير طلبيّة، لا يستدعي مضمونها مطلوبًا، وتتحقّق بصيغ منها التعجّب والمدح أو الذمّ وأفعال الرجاء والقسم.', 1, '2026-10-01 13:12:53', '2026-10-01 13:12:53'),
(19697, 4349, 1, '«يا قلبُ»: إنشاء طلبيّ، أسلوبه النداء. «خبّرني»: إنشاء طلبيّ، أسلوبه الأمر. «كيف تصنع»: إنشاء طلبيّ، أسلوبه الاستفهام.', 1, '2026-10-01 13:12:53', '2026-10-01 13:12:53'),
(19698, 4349, 2, '«يا قلبُ»: إنشاء طلبيّ، أسلوبه النداء. «خبّرني»: إنشاء طلبيّ، أسلوبه الأمر. «كيف تصنع»: إنشاء طلبيّ، أسلوبه الاستفهام.', 1, '2026-10-01 13:12:53', '2026-10-01 13:12:53'),
(19699, 4350, 1, 'كلاهما إنشاء لأنّه لا يحتمل صدقًا ولا كذبًا. قول الإمام عليّ إنشاء طلبيّ بأسلوب الأمر، لأنّه يطلب من واليه أن يتّصف بما لم يكن حاصلًا وقت الطلب. أمّا قول جرير فإنشاء غير طلبيّ بصيغة المدح (حبّذا)، لأنّه لا يستدعي مطلوبًا.', 1, '2026-10-01 13:12:53', '2026-10-01 13:12:53'),
(19700, 4350, 2, 'كلاهما إنشاء لأنّه لا يحتمل صدقًا ولا كذبًا. قول الإمام عليّ إنشاء طلبيّ بأسلوب الأمر، لأنّه يطلب من واليه أن يتّصف بما لم يكن حاصلًا وقت الطلب. أمّا قول جرير فإنشاء غير طلبيّ بصيغة المدح (حبّذا)، لأنّه لا يستدعي مطلوبًا.', 1, '2026-10-01 13:12:53', '2026-10-01 13:12:53'),
(19701, 4351, 1, 'الإيجاز جمع المعاني الكثيرة في اللفظ القليل، مع الوضوح والإفصاح. وهو نوعان: إيجاز قصر، يكون فيه حجم الألفاظ أقلّ من حجم المعاني، من غير حذف في اللفظ؛ وإيجاز حذف، يكون بحذف كلمة أو جملة أو أكثر، من غير أن يختلّ المعنى أو يصيب الكلام غموض والتباس.', 1, '2026-10-01 13:12:55', '2026-10-01 13:12:55'),
(19702, 4351, 2, 'الإيجاز جمع المعاني الكثيرة في اللفظ القليل، مع الوضوح والإفصاح. وهو نوعان: إيجاز قصر، يكون فيه حجم الألفاظ أقلّ من حجم المعاني، من غير حذف في اللفظ؛ وإيجاز حذف، يكون بحذف كلمة أو جملة أو أكثر، من غير أن يختلّ المعنى أو يصيب الكلام غموض والتباس.', 1, '2026-10-01 13:12:55', '2026-10-01 13:12:55'),
(19703, 4352, 1, 'المساواة هي التوازن بين الألفاظ والمعاني، فتكون الألفاظ بقدر المعاني والمعاني بقدر الألفاظ، فلا يزيد طرف منهما على الآخر. أمّا الإطناب فزيادة اللفظ على المعنى لفائدة ولدواعٍ، من غير تطويل أو حشو. من دواعيه: تثبيت المعنى، أو توضيحه، أو توكيده، أو دفع الإبهام والغموض، أو قوّة التأثير وتحريك النفس بالمشاعر والأحاسيس.', 1, '2026-10-01 13:12:55', '2026-10-01 13:12:55'),
(19704, 4352, 2, 'المساواة هي التوازن بين الألفاظ والمعاني، فتكون الألفاظ بقدر المعاني والمعاني بقدر الألفاظ، فلا يزيد طرف منهما على الآخر. أمّا الإطناب فزيادة اللفظ على المعنى لفائدة ولدواعٍ، من غير تطويل أو حشو. من دواعيه: تثبيت المعنى، أو توضيحه، أو توكيده، أو دفع الإبهام والغموض، أو قوّة التأثير وتحريك النفس بالمشاعر والأحاسيس.', 1, '2026-10-01 13:12:55', '2026-10-01 13:12:55'),
(19705, 4353, 1, 'إيجاز حذف: حُذفت جملة «أعود إلى البيت» واكتُفي بلفظة واحدة «غدًا» دلّت على المحذوف، من غير أن يختلّ المعنى أو يصيب الكلام غموض أو التباس.', 1, '2026-10-01 13:12:55', '2026-10-01 13:12:55'),
(19706, 4353, 2, 'إيجاز حذف: حُذفت جملة «أعود إلى البيت» واكتُفي بلفظة واحدة «غدًا» دلّت على المحذوف، من غير أن يختلّ المعنى أو يصيب الكلام غموض أو التباس.', 1, '2026-10-01 13:12:55', '2026-10-01 13:12:55'),
(19707, 4354, 1, '١- العنصر العقليّ: الفكرة التي يبني منها الكاتب موضوعه. ٢- العنصر العاطفيّ: الشعور الذي يثيره الموضوع في نفسه ويودّ أن يثيره فينا. ٣- عنصر الخيال: القدرة على التأمّل القويّ العميق. ٤- العنصر الفنّيّ (التأليف والأسلوب): تشكيل المادّة وتهذيبها وفق مبادئ النظام والتناسق والجمال والتأثير.', 1, '2026-10-01 13:12:56', '2026-10-01 13:12:56'),
(19708, 4354, 2, '١- العنصر العقليّ: الفكرة التي يبني منها الكاتب موضوعه. ٢- العنصر العاطفيّ: الشعور الذي يثيره الموضوع في نفسه ويودّ أن يثيره فينا. ٣- عنصر الخيال: القدرة على التأمّل القويّ العميق. ٤- العنصر الفنّيّ (التأليف والأسلوب): تشكيل المادّة وتهذيبها وفق مبادئ النظام والتناسق والجمال والتأثير.', 1, '2026-10-01 13:12:56', '2026-10-01 13:12:56'),
(19709, 4355, 1, 'المادّة هي الحياة والفكر والخيال والعاطفة، والتكوين هو بناء العمل الأدبيّ من هذه المادّة. والمحتوى هو الأفكار والعواطف، والصورة هي العناصر الشكليّة التي تعبّر عنه. وهما متداخلان: فالحوادث في الرواية محتوى، وطريقة تنسيقها صورة.', 1, '2026-10-01 13:12:56', '2026-10-01 13:12:56'),
(19710, 4355, 2, 'المادّة هي الحياة والفكر والخيال والعاطفة، والتكوين هو بناء العمل الأدبيّ من هذه المادّة. والمحتوى هو الأفكار والعواطف، والصورة هي العناصر الشكليّة التي تعبّر عنه. وهما متداخلان: فالحوادث في الرواية محتوى، وطريقة تنسيقها صورة.', 1, '2026-10-01 13:12:56', '2026-10-01 13:12:56'),
(19711, 4356, 1, 'لا يطلعنا الأدب على عالم الرؤية الخارجيّ فحسب، بل على العالم الداخليّ للفكر والشعور كذلك، فنبدأ في فهم كيف يعيش الناس ومن أجل ماذا يموتون. فالعمل الأدبيّ يستكشف معنا الحياة ويخلق بيننا وبينها علاقات جديدة من الفهم والمعرفة، وهي الغاية التي تسعى لها الإنسانيّة في نشاطها الدائب.', 1, '2026-10-01 13:12:57', '2026-10-01 13:12:57'),
(19712, 4356, 2, 'لا يطلعنا الأدب على عالم الرؤية الخارجيّ فحسب، بل على العالم الداخليّ للفكر والشعور كذلك، فنبدأ في فهم كيف يعيش الناس ومن أجل ماذا يموتون. فالعمل الأدبيّ يستكشف معنا الحياة ويخلق بيننا وبينها علاقات جديدة من الفهم والمعرفة، وهي الغاية التي تسعى لها الإنسانيّة في نشاطها الدائب.', 1, '2026-10-01 13:12:57', '2026-10-01 13:12:57'),
(19713, 4357, 1, 'الشاعر يشعر بعواطفه الشخصيّة أو بعواطف غيره، فيراها منعكسة على مرآة نفسه، فيبرزها إلى الخارج بطريقة تجعلنا شاعرين معه ببعض تلك العواطف. وقد تتّسع دائرة الشعر فيعبّر عن عواطف جمهور من النفوس، بل عن عواطف أمّة بأسرها.', 1, '2026-10-01 13:12:58', '2026-10-01 13:12:58'),
(19714, 4357, 2, 'الشاعر يشعر بعواطفه الشخصيّة أو بعواطف غيره، فيراها منعكسة على مرآة نفسه، فيبرزها إلى الخارج بطريقة تجعلنا شاعرين معه ببعض تلك العواطف. وقد تتّسع دائرة الشعر فيعبّر عن عواطف جمهور من النفوس، بل عن عواطف أمّة بأسرها.', 1, '2026-10-01 13:12:58', '2026-10-01 13:12:58'),
(19715, 4358, 1, 'الشعر حالة إلهاميّة، كلٌّ متوحّد من المعاني والصور والتراكيب والموسيقى، ينقل اهتزاز الشاعر إلى السامع، وروعته لا تُشرح ولا يضبطها العروض. أمّا النظم فصناعة تُقاس بالتفاعيل والتراكيب البديعيّة، يمكن توليدها بالتمرين، ويُعجب فيها بدقّة الصنعة.', 1, '2026-10-01 13:12:58', '2026-10-01 13:12:58'),
(19716, 4358, 2, 'الشعر حالة إلهاميّة، كلٌّ متوحّد من المعاني والصور والتراكيب والموسيقى، ينقل اهتزاز الشاعر إلى السامع، وروعته لا تُشرح ولا يضبطها العروض. أمّا النظم فصناعة تُقاس بالتفاعيل والتراكيب البديعيّة، يمكن توليدها بالتمرين، ويُعجب فيها بدقّة الصنعة.', 1, '2026-10-01 13:12:58', '2026-10-01 13:12:58'),
(19717, 4359, 1, 'تظهر الكتابة التواصليّة في عرض أفكار في تحديد الشعر والاستشهاد بالعلماء (الأصمعي والخليل والجرجاني وابن الأثير) وبابن خلدون. وتظهر الكتابة الأدبيّة في الصور: الشعر «زفرات حرّى يصعّدها صدر هائج»، والعواطف «منعكسة على مرآة النفس»، والكلمات «مجرى موصل» ينقل تيّار الاهتزاز.', 1, '2026-10-01 13:12:58', '2026-10-01 13:12:58'),
(19718, 4359, 2, 'تظهر الكتابة التواصليّة في عرض أفكار في تحديد الشعر والاستشهاد بالعلماء (الأصمعي والخليل والجرجاني وابن الأثير) وبابن خلدون. وتظهر الكتابة الأدبيّة في الصور: الشعر «زفرات حرّى يصعّدها صدر هائج»، والعواطف «منعكسة على مرآة النفس»، والكلمات «مجرى موصل» ينقل تيّار الاهتزاز.', 1, '2026-10-01 13:12:58', '2026-10-01 13:12:58'),
(19719, 4360, 1, 'شرق قديم وشرق جديد، وواقع وحلم، ويأس وأمل، وأجيال هرمة يتحكّم بها الجمود وأجيال فتيّة واعدة مؤهّلة للتغيير. (تُقبل أيّ ثلاث)', 1, '2026-10-01 13:12:59', '2026-10-01 13:12:59'),
(19720, 4360, 2, 'شرق قديم وشرق جديد، وواقع وحلم، ويأس وأمل، وأجيال هرمة يتحكّم بها الجمود وأجيال فتيّة واعدة مؤهّلة للتغيير. (تُقبل أيّ ثلاث)', 1, '2026-10-01 13:12:59', '2026-10-01 13:12:59'),
(19721, 4361, 1, 'يردّ عليها بأنّ في صناديقه كنوزًا لا تبيد، أي لا تفنى: فرحه في كلّ ما أطعم من جوهر عمره، وفرح الأيدي التي أعطت إيمانًا وذكرى. والومضات الوجدانيّة الباسمة: حبّ الأطفال، وفرح الأيدي التي تعطي، وعيد الحصاد.', 1, '2026-10-01 13:12:59', '2026-10-01 13:12:59'),
(19722, 4361, 2, 'يردّ عليها بأنّ في صناديقه كنوزًا لا تبيد، أي لا تفنى: فرحه في كلّ ما أطعم من جوهر عمره، وفرح الأيدي التي أعطت إيمانًا وذكرى. والومضات الوجدانيّة الباسمة: حبّ الأطفال، وفرح الأيدي التي تعطي، وعيد الحصاد.', 1, '2026-10-01 13:12:59', '2026-10-01 13:12:59'),
(19723, 4362, 1, 'عدل الشاعر عن نظام البيت التقليديّ ذي الشطرين المتكافئين، واعتمد تفعيلات بحر الرمل مع تفنّن في توزيعها. وحافظ على مبدأ القافية دون التزام وحدتها، فوزّعها بين قافية عاديّة وقافية داخليّة. ويضاف إلى ذلك إيقاع داخليّ يتمثّل في تكرار يراوح بين الحرف الواحد والمقطع الكامل.', 1, '2026-10-01 13:12:59', '2026-10-01 13:12:59'),
(19724, 4362, 2, 'عدل الشاعر عن نظام البيت التقليديّ ذي الشطرين المتكافئين، واعتمد تفعيلات بحر الرمل مع تفنّن في توزيعها. وحافظ على مبدأ القافية دون التزام وحدتها، فوزّعها بين قافية عاديّة وقافية داخليّة. ويضاف إلى ذلك إيقاع داخليّ يتمثّل في تكرار يراوح بين الحرف الواحد والمقطع الكامل.', 1, '2026-10-01 13:12:59', '2026-10-01 13:12:59'),
(19725, 4363, 1, 'وردة الحديقة حيّة عبقة كريمة، لكنّها كثيرة متشابهة متكرّرة فانية، لها ألف أخت مثلها. أمّا وردة الدهّان فلا عبق لها، لكنّها فريدة في ملك الله لا تشبهها وردة، لأنّ الفنّ يطبع الشيء بذات صاحبه فيجعله واحدًا لا يتكرّر.', 1, '2026-10-01 13:13:00', '2026-10-01 13:13:00'),
(19726, 4363, 2, 'وردة الحديقة حيّة عبقة كريمة، لكنّها كثيرة متشابهة متكرّرة فانية، لها ألف أخت مثلها. أمّا وردة الدهّان فلا عبق لها، لكنّها فريدة في ملك الله لا تشبهها وردة، لأنّ الفنّ يطبع الشيء بذات صاحبه فيجعله واحدًا لا يتكرّر.', 1, '2026-10-01 13:13:00', '2026-10-01 13:13:00'),
(19727, 4364, 1, 'يظهر العنصر العاطفيّ في الإعجاب بوردة الحائط والملل من تشابه ورد الحديقة، ويظهر عنصر الخيال في تشخيص الورد (حاتم الطيب، ألف فم مدوّر، خجل خلع شيمته)، ويظهر العنصر الفنّيّ في الأسلوب المتقن.', 1, '2026-10-01 13:13:01', '2026-10-01 13:13:01'),
(19728, 4364, 2, 'يظهر العنصر العاطفيّ في الإعجاب بوردة الحائط والملل من تشابه ورد الحديقة، ويظهر عنصر الخيال في تشخيص الورد (حاتم الطيب، ألف فم مدوّر، خجل خلع شيمته)، ويظهر العنصر الفنّيّ في الأسلوب المتقن.', 1, '2026-10-01 13:13:01', '2026-10-01 13:13:01'),
(19729, 4365, 1, 'الموهبة أساس لا غنى عنه لكلّ فنّان؛ فالأديب أديب بالطبع، قد تغنيه الثقافة وتصقله التجربة وتزيده الصنعة إتقانًا، لكنّ ذلك لا يجعل الإنسان العاديّ أديبًا، كما أنّ معرفة العروض لا تحوّل الناظم شاعرًا. والتقاء المقوّمات الإنسانيّة والجماليّة كثيرًا ما يمنح الأدب خلوده، شريطة أن يكون صاحبه مبدعًا.', 1, '2026-10-01 13:13:01', '2026-10-01 13:13:01'),
(19730, 4365, 2, 'الموهبة أساس لا غنى عنه لكلّ فنّان؛ فالأديب أديب بالطبع، قد تغنيه الثقافة وتصقله التجربة وتزيده الصنعة إتقانًا، لكنّ ذلك لا يجعل الإنسان العاديّ أديبًا، كما أنّ معرفة العروض لا تحوّل الناظم شاعرًا. والتقاء المقوّمات الإنسانيّة والجماليّة كثيرًا ما يمنح الأدب خلوده، شريطة أن يكون صاحبه مبدعًا.', 1, '2026-10-01 13:13:01', '2026-10-01 13:13:01'),
(19731, 4366, 1, 'العدم تهديد الفناء: قسوة الصحراء، والعدوّ المنافس على الماء والمراعي، والدهر والبوار والمجهول، والعدم الميتافيزيقيّ المطلق. وقد صعّد العربيّ موقفه المادّيّ إلى فكرة العِرض والشرف، فأصبح الدفاع عن المال انتصارًا للكرامة، وكان الصراع البرهان الإيجابيّ الوحيد ضدّ تهديد العدم.', 1, '2026-10-01 13:13:02', '2026-10-01 13:13:02'),
(19732, 4366, 2, 'العدم تهديد الفناء: قسوة الصحراء، والعدوّ المنافس على الماء والمراعي، والدهر والبوار والمجهول، والعدم الميتافيزيقيّ المطلق. وقد صعّد العربيّ موقفه المادّيّ إلى فكرة العِرض والشرف، فأصبح الدفاع عن المال انتصارًا للكرامة، وكان الصراع البرهان الإيجابيّ الوحيد ضدّ تهديد العدم.', 1, '2026-10-01 13:13:02', '2026-10-01 13:13:02'),
(19733, 4367, 1, 'القوّة والشهامة، وإقراء الضيف، ونجدة الملهوف، وإطعام الجائع، وحماية الضعيف. وكان على الشاعر أن يكون الفصيح بالسلوك النموذجيّ: من الفرسان المجلّين، والمكرمين الأخيار، والمدافعين عن عرض القبيلة.', 1, '2026-10-01 13:13:02', '2026-10-01 13:13:02'),
(19734, 4367, 2, 'القوّة والشهامة، وإقراء الضيف، ونجدة الملهوف، وإطعام الجائع، وحماية الضعيف. وكان على الشاعر أن يكون الفصيح بالسلوك النموذجيّ: من الفرسان المجلّين، والمكرمين الأخيار، والمدافعين عن عرض القبيلة.', 1, '2026-10-01 13:13:02', '2026-10-01 13:13:02'),
(19735, 4368, 1, 'مصاعب مادّيّة رهن بطبيعة الصحراء، ومصاعب نفسيّة وليدة حياة تفتقر إلى غائيّة ما ورائيّة. وتدرّج النصّ تدرّجًا منطقيًّا في خطّين متكاملين: إعلان النظريّات وتعليلها.', 1, '2026-10-01 13:13:02', '2026-10-01 13:13:02'),
(19736, 4368, 2, 'مصاعب مادّيّة رهن بطبيعة الصحراء، ومصاعب نفسيّة وليدة حياة تفتقر إلى غائيّة ما ورائيّة. وتدرّج النصّ تدرّجًا منطقيًّا في خطّين متكاملين: إعلان النظريّات وتعليلها.', 1, '2026-10-01 13:13:02', '2026-10-01 13:13:02'),
(19737, 4369, 1, 'الحبيبة تشجّع الفارس وتحمله على الصبر والثبات، وتوحي إليه أجمل الغزل الحماسيّ فيجتمع فيه الحبّ والفخر، ويتغنّى الفارس بذكرها في حديثه عن معاركه شأن عنترة. والفارس يعفّ عنها وعن نساء القبيلة ولا سيّما جاراته.', 1, '2026-10-01 13:13:03', '2026-10-01 13:13:03'),
(19738, 4369, 2, 'الحبيبة تشجّع الفارس وتحمله على الصبر والثبات، وتوحي إليه أجمل الغزل الحماسيّ فيجتمع فيه الحبّ والفخر، ويتغنّى الفارس بذكرها في حديثه عن معاركه شأن عنترة. والفارس يعفّ عنها وعن نساء القبيلة ولا سيّما جاراته.', 1, '2026-10-01 13:13:03', '2026-10-01 13:13:03'),
(19739, 4370, 1, 'الموقعة الصغيرة تبدو ملحمة كبيرة، والعدد القليل يتحوّل جيشًا عرمرمًا، ونفر من القتلى يُعدّ بالمئات والألوف. وهذا الغلوّ لم يأتِ مستقبحًا لأنّه وليد العاطفة المتحمّسة التي تجعله قريبًا إلى النفس، والفطرة الساذجة التي تمسحه بجمالها الجذّاب.', 1, '2026-10-01 13:13:03', '2026-10-01 13:13:03'),
(19740, 4370, 2, 'الموقعة الصغيرة تبدو ملحمة كبيرة، والعدد القليل يتحوّل جيشًا عرمرمًا، ونفر من القتلى يُعدّ بالمئات والألوف. وهذا الغلوّ لم يأتِ مستقبحًا لأنّه وليد العاطفة المتحمّسة التي تجعله قريبًا إلى النفس، والفطرة الساذجة التي تمسحه بجمالها الجذّاب.', 1, '2026-10-01 13:13:03', '2026-10-01 13:13:03'),
(19741, 4371, 1, 'البراعة في ركوب الخيل، والشجاعة والصبر وحسن البلاء، والنجدة، وبُعد الغارة، والعفّة. وكان إذا أعطى رأيًا قرنه بشاهد يثبته (النجدة ببيت طرفة، والعفّة ببيت عنترة)، وهي طريقة مفيدة في الكتابة التواصليّة لأنّها تجعل الفكرة مقنعة مستندة إلى النصّ.', 1, '2026-10-01 13:13:03', '2026-10-01 13:13:03'),
(19742, 4371, 2, 'البراعة في ركوب الخيل، والشجاعة والصبر وحسن البلاء، والنجدة، وبُعد الغارة، والعفّة. وكان إذا أعطى رأيًا قرنه بشاهد يثبته (النجدة ببيت طرفة، والعفّة ببيت عنترة)، وهي طريقة مفيدة في الكتابة التواصليّة لأنّها تجعل الفكرة مقنعة مستندة إلى النصّ.', 1, '2026-10-01 13:13:03', '2026-10-01 13:13:03'),
(19743, 4372, 1, 'يبتغي من جهة مجابهة الحسّاد المستهينين ببأسه ولونه، ويتوخّى من جهة ثانية تعظيم نفسه في عين محبوبته عبلة وإبلاغها نجوى فؤاده المتيّم.', 1, '2026-10-01 13:13:04', '2026-10-01 13:13:04'),
(19744, 4372, 2, 'يبتغي من جهة مجابهة الحسّاد المستهينين ببأسه ولونه، ويتوخّى من جهة ثانية تعظيم نفسه في عين محبوبته عبلة وإبلاغها نجوى فؤاده المتيّم.', 1, '2026-10-01 13:13:04', '2026-10-01 13:13:04'),
(19745, 4373, 1, 'فروسيّة حربيّة ملحميّة تخيّم عليها أجواء المعارك وأصوات الأسلحة ومشاهد الفتك، مثل «فوددت تقبيل السيوف» أو «جادت له كفّي»؛ وفروسيّة خلقيّة ترفعه من مرتبة العبيد إلى مصافّ السادة الشرفاء، مثل «أثني عليّ بما علمت» أو «وكما علمت شمائلي وتكرّمي».', 1, '2026-10-01 13:13:05', '2026-10-01 13:13:05'),
(19746, 4373, 2, 'فروسيّة حربيّة ملحميّة تخيّم عليها أجواء المعارك وأصوات الأسلحة ومشاهد الفتك، مثل «فوددت تقبيل السيوف» أو «جادت له كفّي»؛ وفروسيّة خلقيّة ترفعه من مرتبة العبيد إلى مصافّ السادة الشرفاء، مثل «أثني عليّ بما علمت» أو «وكما علمت شمائلي وتكرّمي».', 1, '2026-10-01 13:13:05', '2026-10-01 13:13:05'),
(19747, 4374, 1, 'الصورة استعارة في «الرماح نواهل»، إذ جعل الرماح كأنّها تشرب من دمه. وذِكره عبلة في قلب المعركة يدلّ على أنّها أمله ومبعث بطولته، وأنّ صورتها خلفيّة ثابتة لمشاهده كلّها.', 1, '2026-10-01 13:13:05', '2026-10-01 13:13:05'),
(19748, 4374, 2, 'الصورة استعارة في «الرماح نواهل»، إذ جعل الرماح كأنّها تشرب من دمه. وذِكره عبلة في قلب المعركة يدلّ على أنّها أمله ومبعث بطولته، وأنّ صورتها خلفيّة ثابتة لمشاهده كلّها.', 1, '2026-10-01 13:13:05', '2026-10-01 13:13:05'),
(19749, 4375, 1, 'من حججه: أنّ كلّ امرئ جارٍ على ما تعوّد والكرم خليقته؛ وأنّ المال جنّة تقي العرض قبل أن يتبدّد؛ وأنّه لا جواد مات هزلًا ولا بخيل خُلّد («أريني جوادًا مات هزلًا… أو بخيلًا مخلّدا»).', 1, '2026-10-01 13:13:06', '2026-10-01 13:13:06'),
(19750, 4375, 2, 'من حججه: أنّ كلّ امرئ جارٍ على ما تعوّد والكرم خليقته؛ وأنّ المال جنّة تقي العرض قبل أن يتبدّد؛ وأنّه لا جواد مات هزلًا ولا بخيل خُلّد («أريني جوادًا مات هزلًا… أو بخيلًا مخلّدا»).', 1, '2026-10-01 13:13:06', '2026-10-01 13:13:06'),
(19751, 4376, 1, 'يقابل بين «جوادًا» و«بخيلًا»، وبين «مات هزلًا» و«مخلّدا». وغرضها التحدّي والإقناع: يطلب من العاذلة دليلًا لا تملكه، ليثبت أنّ الكرم لا يميت صاحبه فقرًا والبخل لا يخلّد صاحبه.', 1, '2026-10-01 13:13:06', '2026-10-01 13:13:06'),
(19752, 4376, 2, 'يقابل بين «جوادًا» و«بخيلًا»، وبين «مات هزلًا» و«مخلّدا». وغرضها التحدّي والإقناع: يطلب من العاذلة دليلًا لا تملكه، ليثبت أنّ الكرم لا يميت صاحبه فقرًا والبخل لا يخلّد صاحبه.', 1, '2026-10-01 13:13:06', '2026-10-01 13:13:06'),
(19753, 4377, 1, 'الإيجابيّ: الفروسيّة أو المروءة، مثل إغاثة الملهوف وحماية الجار والضيافة والوفاء وحفظ العرض والعفّة. المرفوض اليوم: الغزو الذي دفع إليه القحط والعوز، والثأر الذي يُنفَّذ كأنّه قانون توازن القوّة والرعب، والتغنّي بالخمرة والميسر. والأدب شاهد على هذا الواقع بإيجابيّاته وسلبيّاته.', 1, '2026-10-01 13:13:06', '2026-10-01 13:13:06'),
(19754, 4377, 2, 'الإيجابيّ: الفروسيّة أو المروءة، مثل إغاثة الملهوف وحماية الجار والضيافة والوفاء وحفظ العرض والعفّة. المرفوض اليوم: الغزو الذي دفع إليه القحط والعوز، والثأر الذي يُنفَّذ كأنّه قانون توازن القوّة والرعب، والتغنّي بالخمرة والميسر. والأدب شاهد على هذا الواقع بإيجابيّاته وسلبيّاته.', 1, '2026-10-01 13:13:06', '2026-10-01 13:13:06'),
(19755, 4378, 1, 'على الصعيد الروحيّ: نزل القرآن الكريم، وساد التوحيد دنيا العرب، وانكفأت العقائد الوثنيّة. على الصعيد الاجتماعيّ: تكرّست مُثُل أخلاقيّة ووُضعت قوانين تنظيميّة نقلت الناس من دائرة القبيلة الضيّقة إلى رحاب الدولة.', 1, '2026-10-01 13:13:07', '2026-10-01 13:13:07'),
(19756, 4378, 2, 'على الصعيد الروحيّ: نزل القرآن الكريم، وساد التوحيد دنيا العرب، وانكفأت العقائد الوثنيّة. على الصعيد الاجتماعيّ: تكرّست مُثُل أخلاقيّة ووُضعت قوانين تنظيميّة نقلت الناس من دائرة القبيلة الضيّقة إلى رحاب الدولة.', 1, '2026-10-01 13:13:07', '2026-10-01 13:13:07'),
(19757, 4379, 1, 'يقصد أنّ الإسلام انتشر بتعاليمه السمحة لا بالإكراه، إذ احترم حقوق الإنسان في الدين نفسه («لا إكراه في الدين»)، وكفل الحرّيّة لكلّ من عاش في ظلاله، مسلمين وغير مسلمين، وكأنّه أراد وحدة النوع الإنسانيّ.', 1, '2026-10-01 13:13:08', '2026-10-01 13:13:08'),
(19758, 4379, 2, 'يقصد أنّ الإسلام انتشر بتعاليمه السمحة لا بالإكراه، إذ احترم حقوق الإنسان في الدين نفسه («لا إكراه في الدين»)، وكفل الحرّيّة لكلّ من عاش في ظلاله، مسلمين وغير مسلمين، وكأنّه أراد وحدة النوع الإنسانيّ.', 1, '2026-10-01 13:13:08', '2026-10-01 13:13:08'),
(19759, 4380, 1, 'من خصائصه: الاقتباس من القرآن الكريم أساسًا للكتابة؛ والعرض التراكميّ لا الجدليّ مع كثرة أدوات العطف؛ والتجرّد من الأحكام العاطفيّة والمبالغات والتعميمات؛ والتقسيم والتفصيل؛ وأسلوب سرديّ بسيط واضح سهل التعبير يتنكّر للصنعة اللفظيّة، بمعجم إسلاميّ الطابع.', 1, '2026-10-01 13:13:08', '2026-10-01 13:13:08'),
(19760, 4380, 2, 'من خصائصه: الاقتباس من القرآن الكريم أساسًا للكتابة؛ والعرض التراكميّ لا الجدليّ مع كثرة أدوات العطف؛ والتجرّد من الأحكام العاطفيّة والمبالغات والتعميمات؛ والتقسيم والتفصيل؛ وأسلوب سرديّ بسيط واضح سهل التعبير يتنكّر للصنعة اللفظيّة، بمعجم إسلاميّ الطابع.', 1, '2026-10-01 13:13:08', '2026-10-01 13:13:08'),
(19761, 4381, 1, '«خُلَّصًا»: خالصين، أي شعراء إسلاميّين لا أثر فيهم لجاهليّة. «انبتّ من جذوره»: انقطع عنها، أي تغيّر الأدب تغيّرًا حاسمًا بين يوم وليلة وقطع كلّ صلة بماضيه.', 1, '2026-10-01 13:13:09', '2026-10-01 13:13:09'),
(19762, 4381, 2, '«خُلَّصًا»: خالصين، أي شعراء إسلاميّين لا أثر فيهم لجاهليّة. «انبتّ من جذوره»: انقطع عنها، أي تغيّر الأدب تغيّرًا حاسمًا بين يوم وليلة وقطع كلّ صلة بماضيه.', 1, '2026-10-01 13:13:09', '2026-10-01 13:13:09'),
(19763, 4382, 1, 'افترضت صحّة الرأي ثمّ استنتجت ما يلزم عنه: «لو صحّ هذا، لكان معناه» أنّ الأدب وقف بمعزل عن الحادث الأكبر الذي هزّ أرجاء الجزيرة العربيّة، وهذا يعزل الأدب عن الحياة، فالرأي مرفوض.', 1, '2026-10-01 13:13:09', '2026-10-01 13:13:09'),
(19764, 4382, 2, 'افترضت صحّة الرأي ثمّ استنتجت ما يلزم عنه: «لو صحّ هذا، لكان معناه» أنّ الأدب وقف بمعزل عن الحادث الأكبر الذي هزّ أرجاء الجزيرة العربيّة، وهذا يعزل الأدب عن الحياة، فالرأي مرفوض.', 1, '2026-10-01 13:13:09', '2026-10-01 13:13:09'),
(19765, 4383, 1, 'جعلت الخضرمة تمتدّ من أخريات الجاهليّة إلى قُبيل النصف الثاني من القرن الأوّل للهجرة، فأدب هذه الفترة يحمل ملامح الجاهليّة والإسلام معًا، فيه تأثّر بالحياة الجديدة مع رواسب من الماضي. فلا هو إسلاميّ خالص ولا جاهليّ خالص، فيسقط التناقض بين الرأيين ويثبت أنّ الأدب لم يكن بمعزل عن الحياة.', 1, '2026-10-01 13:13:09', '2026-10-01 13:13:09'),
(19766, 4383, 2, 'جعلت الخضرمة تمتدّ من أخريات الجاهليّة إلى قُبيل النصف الثاني من القرن الأوّل للهجرة، فأدب هذه الفترة يحمل ملامح الجاهليّة والإسلام معًا، فيه تأثّر بالحياة الجديدة مع رواسب من الماضي. فلا هو إسلاميّ خالص ولا جاهليّ خالص، فيسقط التناقض بين الرأيين ويثبت أنّ الأدب لم يكن بمعزل عن الحياة.', 1, '2026-10-01 13:13:09', '2026-10-01 13:13:09'),
(19767, 4384, 1, 'الفهم («فافهم إذا أُدلي إليك»)، والمساواة بين الناس في الوجه والعدل والمجلس، والبيّنة على من ادّعى واليمين على من أنكر، والرجوع إلى الحقّ، والقياس بالأشباه والأمثال، وجعل أمدٍ لمن ادّعى حقًّا غائبًا، وتجنّب الغلق والضجر والتأذّي بالخصوم (يكفي أربع).', 1, '2026-10-01 13:13:10', '2026-10-01 13:13:10'),
(19768, 4384, 2, 'الفهم («فافهم إذا أُدلي إليك»)، والمساواة بين الناس في الوجه والعدل والمجلس، والبيّنة على من ادّعى واليمين على من أنكر، والرجوع إلى الحقّ، والقياس بالأشباه والأمثال، وجعل أمدٍ لمن ادّعى حقًّا غائبًا، وتجنّب الغلق والضجر والتأذّي بالخصوم (يكفي أربع).', 1, '2026-10-01 13:13:10', '2026-10-01 13:13:10'),
(19769, 4385, 1, 'كان القضاء في الجاهليّة قائمًا على المزاجيّة والاعتبارات القبليّة، أي على الفرديّة والاستنساب في الأحكام؛ أمّا في الرسالة فصار قوانين موحّدة صارمة تأخذها الدولة على عاتقها وتُعنى بتنفيذها بغير تحيّزٍ أو تمييز، ومرجعها الواحد الشريعة الإسلاميّة.', 1, '2026-10-01 13:13:10', '2026-10-01 13:13:10'),
(19770, 4385, 2, 'كان القضاء في الجاهليّة قائمًا على المزاجيّة والاعتبارات القبليّة، أي على الفرديّة والاستنساب في الأحكام؛ أمّا في الرسالة فصار قوانين موحّدة صارمة تأخذها الدولة على عاتقها وتُعنى بتنفيذها بغير تحيّزٍ أو تمييز، ومرجعها الواحد الشريعة الإسلاميّة.', 1, '2026-10-01 13:13:10', '2026-10-01 13:13:10'),
(19771, 4386, 1, 'أدخل لغة العقل والتعليل في كثير من الجمل، فاتّخذ التوجيه طابع النصح والإرشاد، كقوله: «فافهم إذا أُدلي إليك، فإنّه لا ينفع تكلّمٌ بحقٍّ لا نفاذ له»؛ فالأمر يتبعه تعليل يقنع العقل.', 1, '2026-10-01 13:13:10', '2026-10-01 13:13:10'),
(19772, 4386, 2, 'أدخل لغة العقل والتعليل في كثير من الجمل، فاتّخذ التوجيه طابع النصح والإرشاد، كقوله: «فافهم إذا أُدلي إليك، فإنّه لا ينفع تكلّمٌ بحقٍّ لا نفاذ له»؛ فالأمر يتبعه تعليل يقنع العقل.', 1, '2026-10-01 13:13:10', '2026-10-01 13:13:10'),
(19773, 4387, 1, 'اختلفت هنالك الكلمة، وظهرت معالم الجور، وكثر الإدغال (الفساد) في الدين، وتُركت محاجّ السنن، وذلّت الأبرار وعزّت الأشرار (يكفي اثنتان).', 1, '2026-10-01 13:13:11', '2026-10-01 13:13:11'),
(19774, 4387, 2, 'اختلفت هنالك الكلمة، وظهرت معالم الجور، وكثر الإدغال (الفساد) في الدين، وتُركت محاجّ السنن، وذلّت الأبرار وعزّت الأشرار (يكفي اثنتان).', 1, '2026-10-01 13:13:11', '2026-10-01 13:13:11'),
(19775, 4388, 1, 'يربط الإمام بين الجانبين الشرعيّ والدنيويّ ترابط تلازم وحتميّة، فالحقوق فريضة من الله، وتبادلها نظام يرضي الخالق ويفيد الناس: «عزٌّ لدينهم» و«نظامٌ لألفتهم». البعد الأوّل دينيّ محض صادر عن مؤمن يرى الأمور من منظور إسلاميّ، والثاني شخصيّ يتّصل بحاكم لقي مواجهة وعصيانًا فأكّد الحقّ الإلهيّ للوالي تعزيزًا لموقعه، ومع معاوية بشكل خاصّ.', 1, '2026-10-01 13:13:11', '2026-10-01 13:13:11'),
(19776, 4388, 2, 'يربط الإمام بين الجانبين الشرعيّ والدنيويّ ترابط تلازم وحتميّة، فالحقوق فريضة من الله، وتبادلها نظام يرضي الخالق ويفيد الناس: «عزٌّ لدينهم» و«نظامٌ لألفتهم». البعد الأوّل دينيّ محض صادر عن مؤمن يرى الأمور من منظور إسلاميّ، والثاني شخصيّ يتّصل بحاكم لقي مواجهة وعصيانًا فأكّد الحقّ الإلهيّ للوالي تعزيزًا لموقعه، ومع معاوية بشكل خاصّ.', 1, '2026-10-01 13:13:11', '2026-10-01 13:13:11'),
(19777, 4389, 1, 'قلّب الإمام المعاني على وجهيها الإيجابيّ والسلبيّ: أداء الحقوق يقابله الإخلال بها، فتقابلت النتائج (عزّ الحقّ / اختلفت الكلمة). ومن المقابلة في الأسلوب: «فهنالك تذلّ الأبرار، وتعزّ الأشرار»، فـ«تذلّ» تقابل «تعزّ» و«الأبرار» تقابل «الأشرار»، مع تقطيع موسيقيّ واضح في توازن الجمل.', 1, '2026-10-01 13:13:11', '2026-10-01 13:13:11'),
(19778, 4389, 2, 'قلّب الإمام المعاني على وجهيها الإيجابيّ والسلبيّ: أداء الحقوق يقابله الإخلال بها، فتقابلت النتائج (عزّ الحقّ / اختلفت الكلمة). ومن المقابلة في الأسلوب: «فهنالك تذلّ الأبرار، وتعزّ الأشرار»، فـ«تذلّ» تقابل «تعزّ» و«الأبرار» تقابل «الأشرار»، مع تقطيع موسيقيّ واضح في توازن الجمل.', 1, '2026-10-01 13:13:11', '2026-10-01 13:13:11'),
(19779, 4390, 1, 'الجبّارون؛ الذين كان لهم ذكر القتال والغلبة في مواطن الحروب؛ الملوك الذين أثاروا الأرض وعمروها؛ الوضاء الحسنة وجوههم المعجبون بشبابهم؛ الذين بنوا المدائن وحصّنوها بالحوائط (يكفي أربع).', 1, '2026-10-01 13:13:12', '2026-10-01 13:13:12'),
(19780, 4390, 2, 'الجبّارون؛ الذين كان لهم ذكر القتال والغلبة في مواطن الحروب؛ الملوك الذين أثاروا الأرض وعمروها؛ الوضاء الحسنة وجوههم المعجبون بشبابهم؛ الذين بنوا المدائن وحصّنوها بالحوائط (يكفي أربع).', 1, '2026-10-01 13:13:12', '2026-10-01 13:13:12'),
(19781, 4391, 1, 'تقوم العبارة على ثنائيّة: الاعتبار بالموتى طريق النجاة، والاغترار طريق الهلاك ومصيرٍ كمصيرهم. وهي تتّصل بالعدالة الإلهيّة في معاملة البشر: فالموتى مضوا والأعمال أعمالهم، ووردوا على ما قدّموا فحلّوا عليه، فالفرد يتحمّل مسؤوليّة أعماله.', 1, '2026-10-01 13:13:12', '2026-10-01 13:13:12'),
(19782, 4391, 2, 'تقوم العبارة على ثنائيّة: الاعتبار بالموتى طريق النجاة، والاغترار طريق الهلاك ومصيرٍ كمصيرهم. وهي تتّصل بالعدالة الإلهيّة في معاملة البشر: فالموتى مضوا والأعمال أعمالهم، ووردوا على ما قدّموا فحلّوا عليه، فالفرد يتحمّل مسؤوليّة أعماله.', 1, '2026-10-01 13:13:12', '2026-10-01 13:13:12'),
(19783, 4392, 1, 'في النثر كان التزام مبادئ الإسلام واضحًا أكيدًا: خطبٌ دينيّة أملتها الأجواء الناشئة ورسائل إداريّة حتّمها تنظيم الدولة (رسالة عمر، خطبة عليّ). أمّا الشعراء فلم يتخلّصوا من الجاهليّة كلّيًّا: فريق غير مبالٍ (الحطيئة، أبو محجن الثقفيّ)، ومعارضون (ابن الزبعرى، ضرار بن الخطّاب)، وحتّى الناصرون (حسّان، كعب بن مالك، كعب بن زهير) ترجموا الآيات شعرًا بأسلوب قديم وأبيات قليلة.', 1, '2026-10-01 13:13:12', '2026-10-01 13:13:12'),
(19784, 4392, 2, 'في النثر كان التزام مبادئ الإسلام واضحًا أكيدًا: خطبٌ دينيّة أملتها الأجواء الناشئة ورسائل إداريّة حتّمها تنظيم الدولة (رسالة عمر، خطبة عليّ). أمّا الشعراء فلم يتخلّصوا من الجاهليّة كلّيًّا: فريق غير مبالٍ (الحطيئة، أبو محجن الثقفيّ)، ومعارضون (ابن الزبعرى، ضرار بن الخطّاب)، وحتّى الناصرون (حسّان، كعب بن مالك، كعب بن زهير) ترجموا الآيات شعرًا بأسلوب قديم وأبيات قليلة.', 1, '2026-10-01 13:13:12', '2026-10-01 13:13:12'),
(19785, 4393, 1, 'من الصور البدويّة: المغاني والصير الدارسة، والفرس الأغرّ. ومن الصور الحضريّة: الفتيات المتنعّمات، ورضاب المسك في الأثواب.', 1, '2026-10-01 13:13:14', '2026-10-01 13:13:14'),
(19786, 4393, 2, 'من الصور البدويّة: المغاني والصير الدارسة، والفرس الأغرّ. ومن الصور الحضريّة: الفتيات المتنعّمات، ورضاب المسك في الأثواب.', 1, '2026-10-01 13:13:14', '2026-10-01 13:13:14'),
(19787, 4394, 1, 'الحادثة محورها عمر: هو معشوق الصبايا ومنية خلواتهنّ، فيتغزّل بنفسه على ألسنة الفتيات بدل أن يتغزّل بالمرأة؛ ويرتفع الحوار درجةً درجة: سؤال الكبرى «أتعرفن الفتى؟»، فتعريف الوسطى «نعم، هذا عمر»، فتشبيه الصغرى «قد عرفناه، وهل يخفى القمر!».', 1, '2026-10-01 13:13:14', '2026-10-01 13:13:14'),
(19788, 4394, 2, 'الحادثة محورها عمر: هو معشوق الصبايا ومنية خلواتهنّ، فيتغزّل بنفسه على ألسنة الفتيات بدل أن يتغزّل بالمرأة؛ ويرتفع الحوار درجةً درجة: سؤال الكبرى «أتعرفن الفتى؟»، فتعريف الوسطى «نعم، هذا عمر»، فتشبيه الصغرى «قد عرفناه، وهل يخفى القمر!».', 1, '2026-10-01 13:13:14', '2026-10-01 13:13:14'),
(19789, 4395, 1, 'أسلوب عفويّ هو كلام الناس البعيد من التكلّف والتزيين، ذهب السرد القصصيّ فيه بالمحسّنات؛ مفردات سهلة متآلفة الأحرف إلّا ما ندر كـ«اسبطرّ»؛ جمل قصيرة سريعة معظمها خبريّ والقليل الإنشائيّ استوجبه مقام القصّة والحوار؛ ووزن الرمل السريع النابض بالحياة الذي يرمز إلى الغبطة والفرح.', 1, '2026-10-01 13:13:14', '2026-10-01 13:13:14'),
(19790, 4395, 2, 'أسلوب عفويّ هو كلام الناس البعيد من التكلّف والتزيين، ذهب السرد القصصيّ فيه بالمحسّنات؛ مفردات سهلة متآلفة الأحرف إلّا ما ندر كـ«اسبطرّ»؛ جمل قصيرة سريعة معظمها خبريّ والقليل الإنشائيّ استوجبه مقام القصّة والحوار؛ ووزن الرمل السريع النابض بالحياة الذي يرمز إلى الغبطة والفرح.', 1, '2026-10-01 13:13:14', '2026-10-01 13:13:14'),
